def run_pooled_figures(config: PipelineConfig) -> dict[str, str]:
    pooled_nb_path = config.notebooks_root / "PooledFigure_CKII_Stats_V2.ipynb"
    if not pooled_nb_path.exists():
        raise FileNotFoundError(f"Pooled notebook not found: {pooled_nb_path}")

    # Validate PSD file contract before running pooled PSD sections.
    if config.pooled.run_psd_sections and config.pooled.cs_plc_only:
        for animal_id in config.animals:
            _validate_psd_contract(animal_id, config)

    pooled_out_dir = config.figures_root / "CKII_pooled"
    pooled_out_dir.mkdir(parents=True, exist_ok=True)

    start_ns = datetime.now(timezone.utc).timestamp() * 1_000_000_000

    nb = nbformat.read(str(pooled_nb_path), as_version=4)
    nb = _patch_pooled_notebook(nb, config)

    save_path = None
    if config.cache.save_executed_notebooks:
        save_path = config.notebooks_root / "_executed_cache" / "PooledFigure_CKII_Stats_V2_executed.ipynb"

    _execute_notebook(nb, cwd=config.notebooks_root, save_path=save_path)

    generated: dict[str, str] = {}
    for svg_path in sorted(pooled_out_dir.glob("*.svg")):
        if svg_path.stat().st_mtime_ns >= int(start_ns):
            generated[svg_path.name] = str(svg_path)

    return generated


def summarize_statuses(statuses: list[AnimalCacheStatus]) -> dict[str, int]:
    out = {
        "recomputed": 0,
        "reused": 0,
        "needs_recompute": 0,
    }
    for st in statuses:
        out[st.action] = out.get(st.action, 0) + 1
    return out


def summarize_snr_removed_frames(
    config: PipelineConfig,
    *,
    by_place_cells_only: bool = False,
    show_plot: bool = True,
    bins: int = 10,
) -> dict[str, Any]:
    """
    Summarize percentage of frames removed by the analysis bad-frame mask.

    The total bad-frame mask includes low/non-finite time-varying SNR,
    invalid behavior samples, and recovered source-trace bad epochs that were
    later interpolated in ``traces_SNR_interpolated``. Cells removed by the
    min-good-minutes rule are included.
    """
    import pandas as pd

    rows: list[dict[str, Any]] = []
    missing_animals: list[str] = []
    for animal_id in config.animals:
        animal_dir = config.data_root / animal_id
        try:
            _resolve_merged_data_path(animal_dir, config)
        except FileNotFoundError:
            missing_animals.append(animal_id)
            continue

        merged = _load_merged_data(animal_dir, config)
        bad_masks, mask_stats = _compute_bad_masks(
            merged,
            snr_threshold=float(config.analysis.snr_threshold),
            min_good_minutes=float(config.analysis.min_good_minutes),
            return_stats=True,
        )

        spatial_is_pc: dict[int, bool] = {}
        spatial_path = animal_dir / "spatial_analysis_full.pkl"
        if spatial_path.exists():
            with spatial_path.open("rb") as f:
                cells = pickle.load(f)
            if isinstance(cells, list):
                for rec in cells:
                    if isinstance(rec, dict) and "cell_idx" in rec:
                        spatial_is_pc[int(rec["cell_idx"])] = bool(rec.get("is_place_cell", False))

        for cell_idx in range(len(mask_stats)):
            st = mask_stats[cell_idx]
            is_pc_val = spatial_is_pc.get(int(cell_idx), np.nan)
            if by_place_cells_only and not bool(is_pc_val is True):
                continue
            rows.append(
                {
                    "animal_id": animal_id,
                    "cell_idx": int(cell_idx),
                    "cell_num": int(cell_idx) + 1,
                    "is_place_cell": is_pc_val,
                    "eligible_cell": bool(st.get("eligible_cell", False)),
                    "removed_by_min_good_minutes": bool(st.get("removed_by_min_good_minutes", False)),
                    "good_minutes_before_min_minutes": float(st.get("good_minutes_before_min_minutes", np.nan)),
                    "pct_removed_frames_snr_only": float(st.get("pct_removed_frames_snr_only", np.nan)),
                    "pct_removed_frames_snr_threshold_only": float(st.get("pct_removed_frames_snr_threshold_only", np.nan)),
                    "pct_removed_frames_manual_snr_cutoff": float(st.get("pct_removed_frames_manual_snr_cutoff", np.nan)),
                    "pct_removed_frames_source_trace_bad": float(st.get("pct_removed_frames_source_trace_bad", np.nan)),
                    "pct_removed_frames_pos_nan": (
                        100.0
                        * float(st.get("n_removed_frames_pos_nan", 0))
                        / float(st.get("n_frames_total", bad_masks.shape[1] if bad_masks.ndim == 2 else 0))
                        if float(st.get("n_frames_total", bad_masks.shape[1] if bad_masks.ndim == 2 else 0)) > 0
                        else np.nan
                    ),
                    "pct_removed_frames_total": float(st.get("pct_removed_frames_total", np.nan)),
                    "n_removed_frames_snr_only": int(st.get("n_removed_frames_snr_only", 0)),
                    "n_removed_frames_snr_threshold_only": int(st.get("n_removed_frames_snr_threshold_only", 0)),
                    "n_removed_frames_manual_snr_cutoff": int(st.get("n_removed_frames_manual_snr_cutoff", 0)),
                    "n_removed_frames_source_trace_bad": int(st.get("n_removed_frames_source_trace_bad", 0)),
                    "n_removed_frames_pos_nan": int(st.get("n_removed_frames_pos_nan", 0)),
                    "n_removed_frames_total": int(st.get("n_removed_frames_total", 0)),
                    "n_frames_total": int(st.get("n_frames_total", bad_masks.shape[1] if bad_masks.ndim == 2 else 0)),
                }
            )

    df = pd.DataFrame(rows)
    if len(df) == 0:
        print("No rows found for SNR frame-removal summary.")
        if missing_animals:
            print(f"Missing merged data for: {', '.join(missing_animals)}")
        return {
            "per_cell": df,
            "per_animal": pd.DataFrame(),
            "overall": pd.DataFrame(),
            "missing_animals": missing_animals,
            "figure": None,
        }

    df["is_place_cell"] = pd.Series(df["is_place_cell"], dtype="object")
    valid_pct = df["pct_removed_frames_total"].to_numpy(dtype=float)
    valid_pct = valid_pct[np.isfinite(valid_pct)]
    removed_mask = np.asarray(df["removed_by_min_good_minutes"], dtype=bool)
    n_removed_min_good = int(np.sum(removed_mask))
    n_kept = int(len(df) - n_removed_min_good)

    def _finite_stats(values: Any, suffix: str) -> dict[str, float]:
        vals = np.asarray(values, dtype=float)
        vals = vals[np.isfinite(vals)]
        return {
            f"mean_{suffix}": float(np.nanmean(vals)) if vals.size else np.nan,
            f"median_{suffix}": float(np.nanmedian(vals)) if vals.size else np.nan,
            f"std_{suffix}": float(np.nanstd(vals)) if vals.size else np.nan,
            f"min_{suffix}": float(np.nanmin(vals)) if vals.size else np.nan,
            f"max_{suffix}": float(np.nanmax(vals)) if vals.size else np.nan,
        }

    def _sum_pct(group: Any, count_col: str) -> float:
        denom = float(np.sum(group["n_frames_total"].to_numpy(dtype=float)))
        if denom <= 0:
            return np.nan
        return float(100.0 * np.sum(group[count_col].to_numpy(dtype=float)) / denom)

    overall = {
        "scope": "place_cells_only" if by_place_cells_only else "all_cells_including_removed",
        "n_cells": int(len(df)),
        "n_kept_cells": n_kept,
        "n_removed_min_good_minutes": n_removed_min_good,
        "n_frames_total_cellwise": int(np.sum(df["n_frames_total"].to_numpy(dtype=float))),
        "n_removed_frames_total": int(np.sum(df["n_removed_frames_total"].to_numpy(dtype=float))),
        "n_removed_frames_snr_only": int(np.sum(df["n_removed_frames_snr_only"].to_numpy(dtype=float))),
        "n_removed_frames_snr_threshold_only": int(np.sum(df["n_removed_frames_snr_threshold_only"].to_numpy(dtype=float))),
        "n_removed_frames_manual_snr_cutoff": int(np.sum(df["n_removed_frames_manual_snr_cutoff"].to_numpy(dtype=float))),
        "n_removed_frames_source_trace_bad": int(np.sum(df["n_removed_frames_source_trace_bad"].to_numpy(dtype=float))),
        "n_removed_frames_pos_nan": int(np.sum(df["n_removed_frames_pos_nan"].to_numpy(dtype=float))),
        "pct_removed_total_cellwise": _sum_pct(df, "n_removed_frames_total"),
        "pct_removed_snr_only_cellwise": _sum_pct(df, "n_removed_frames_snr_only"),
        "pct_removed_snr_threshold_only_cellwise": _sum_pct(df, "n_removed_frames_snr_threshold_only"),
        "pct_removed_manual_snr_cutoff_cellwise": _sum_pct(df, "n_removed_frames_manual_snr_cutoff"),
        "pct_removed_source_trace_bad_cellwise": _sum_pct(df, "n_removed_frames_source_trace_bad"),
        "pct_removed_pos_nan_cellwise": _sum_pct(df, "n_removed_frames_pos_nan"),
        **_finite_stats(df["pct_removed_frames_total"], "pct_removed_total"),
        **_finite_stats(df["pct_removed_frames_snr_only"], "pct_removed_snr_only"),
        **_finite_stats(df["pct_removed_frames_snr_threshold_only"], "pct_removed_snr_threshold_only"),
        **_finite_stats(df["pct_removed_frames_manual_snr_cutoff"], "pct_removed_manual_snr_cutoff"),
        **_finite_stats(df["pct_removed_frames_source_trace_bad"], "pct_removed_source_trace_bad"),
        **_finite_stats(df["pct_removed_frames_pos_nan"], "pct_removed_pos_nan"),
    }
    overall_df = pd.DataFrame([overall])

    def _agg_per_animal(group: Any) -> Any:
        payload = {
            "n_cells": int(len(group)),
            "n_kept_cells": int(np.sum(~group["removed_by_min_good_minutes"].to_numpy(dtype=bool))),
            "n_removed_min_good_minutes": int(np.sum(group["removed_by_min_good_minutes"].to_numpy(dtype=bool))),
            "n_frames_total_cellwise": int(np.sum(group["n_frames_total"].to_numpy(dtype=float))),
            "n_removed_frames_total": int(np.sum(group["n_removed_frames_total"].to_numpy(dtype=float))),
            "n_removed_frames_snr_only": int(np.sum(group["n_removed_frames_snr_only"].to_numpy(dtype=float))),
            "n_removed_frames_snr_threshold_only": int(np.sum(group["n_removed_frames_snr_threshold_only"].to_numpy(dtype=float))),
            "n_removed_frames_manual_snr_cutoff": int(np.sum(group["n_removed_frames_manual_snr_cutoff"].to_numpy(dtype=float))),
            "n_removed_frames_source_trace_bad": int(np.sum(group["n_removed_frames_source_trace_bad"].to_numpy(dtype=float))),
            "n_removed_frames_pos_nan": int(np.sum(group["n_removed_frames_pos_nan"].to_numpy(dtype=float))),
            "pct_removed_total_cellwise": _sum_pct(group, "n_removed_frames_total"),
            "pct_removed_snr_only_cellwise": _sum_pct(group, "n_removed_frames_snr_only"),
            "pct_removed_snr_threshold_only_cellwise": _sum_pct(group, "n_removed_frames_snr_threshold_only"),
            "pct_removed_manual_snr_cutoff_cellwise": _sum_pct(group, "n_removed_frames_manual_snr_cutoff"),
            "pct_removed_source_trace_bad_cellwise": _sum_pct(group, "n_removed_frames_source_trace_bad"),
            "pct_removed_pos_nan_cellwise": _sum_pct(group, "n_removed_frames_pos_nan"),
        }
        payload.update(_finite_stats(group["pct_removed_frames_total"], "pct_removed_total"))
        payload.update(_finite_stats(group["pct_removed_frames_snr_only"], "pct_removed_snr_only"))
        payload.update(_finite_stats(group["pct_removed_frames_snr_threshold_only"], "pct_removed_snr_threshold_only"))
        payload.update(_finite_stats(group["pct_removed_frames_manual_snr_cutoff"], "pct_removed_manual_snr_cutoff"))
        payload.update(_finite_stats(group["pct_removed_frames_source_trace_bad"], "pct_removed_source_trace_bad"))
        payload.update(_finite_stats(group["pct_removed_frames_pos_nan"], "pct_removed_pos_nan"))
        return pd.Series(payload)

    per_animal_rows: list[dict[str, Any]] = []
    for animal_id, group in df.groupby("animal_id", sort=True):
        payload = dict(_agg_per_animal(group))
        payload["animal_id"] = animal_id
        per_animal_rows.append(payload)
    per_animal = pd.DataFrame(per_animal_rows)
    if not per_animal.empty:
        per_animal = per_animal[["animal_id"] + [col for col in per_animal.columns if col != "animal_id"]]

    print(
        "SNR removed-frame summary "
        f"({'place cells only' if by_place_cells_only else 'all cells'}): "
        f"n_cells={overall['n_cells']}, "
        f"removed(<{config.analysis.min_good_minutes} min good)={overall['n_removed_min_good_minutes']}, "
        f"mean_total={overall['mean_pct_removed_total']:.2f}%, "
        f"median_total={overall['median_pct_removed_total']:.2f}%, "
        f"source_bad={overall['pct_removed_source_trace_bad_cellwise']:.2f}%, "
        f"snr_only={overall['pct_removed_snr_only_cellwise']:.2f}%"
    )
    if missing_animals:
        print(f"Missing merged data for: {', '.join(missing_animals)}")

    fig = None
    if show_plot and valid_pct.size > 0:
        fig, ax = plt.subplots(figsize=(1.4, 1.2))
        kept_pct = df.loc[~df["removed_by_min_good_minutes"], "pct_removed_frames_total"].to_numpy(dtype=float)
        kept_pct = kept_pct[np.isfinite(kept_pct)]
        removed_pct = df.loc[df["removed_by_min_good_minutes"], "pct_removed_frames_total"].to_numpy(dtype=float)
        removed_pct = removed_pct[np.isfinite(removed_pct)]

        plot_series = []
        plot_labels = []
        plot_colors = []
        if kept_pct.size > 0:
            plot_series.append(kept_pct)
            plot_labels.append("Kept cells")
            plot_colors.append("#6C9A8B")
        if removed_pct.size > 0:
            plot_series.append(removed_pct)
            plot_labels.append(f"Removed (<{config.analysis.min_good_minutes} min good)")
            plot_colors.append("#9E9E9E")
        counts, bin_edges, _patches = ax.hist(
            plot_series,
            bins=int(bins),
            stacked=True,
            color=plot_colors,
            edgecolor="white",
            linewidth=0.4,
            label=plot_labels,
        )
        total_counts, _ = np.histogram(np.concatenate(plot_series), bins=bin_edges)
        if total_counts.size > 0 and np.nanmax(total_counts) > 0:
            y_offset = max(0.2, float(np.nanmax(total_counts)) * 0.03)
            for left, right, count in zip(bin_edges[:-1], bin_edges[1:], total_counts):
                if int(count) <= 0:
                    continue
                ax.text(
                    (float(left) + float(right)) / 2.0,
                    float(count) + y_offset,
                    str(int(count)),
                    ha="center",
                    va="bottom",
                    fontsize=5,
                    fontname="Arial",
                )
            ax.set_ylim(top=float(np.nanmax(total_counts)) + y_offset * 5.0)
        #ax.axvline(float(np.nanmedian(valid_pct)), color="#A11D33", linestyle="--", linewidth=0.8)
        ax.set_xlabel("% frames removed (total)")
        ax.set_ylabel("Cell count")
        ax.set_title("Bad Frame Removal Distribution")
        # if len(plot_labels) > 1:
        #     ax.legend(frameon=False, fontsize=5)
        ax.spines["top"].set_visible(False)
        ax.spines["right"].set_visible(False)
        fig.tight_layout()

    return {
        "per_cell": df,
        "per_animal": per_animal,
        "overall": overall_df,
        "missing_animals": missing_animals,
        "figure": fig,
    }


def summarize_snr_effective_max_time(
    config: PipelineConfig,
    *,
    snr_removed_summary: dict[str, Any] | None = None,
    by_place_cells_only: bool = False,
    show_plot: bool = True,
    bin_width_minutes: float = 1.0,
    figure_save_folder: str | Path | None = None,
    save_name: str | None = None,
    show_legend: bool = False,
    figsize: tuple[float, float] = (1.4, 1.2),
) -> dict[str, Any]:
    """
    Summarize effective analyzable minutes after all frame-level bad masks.

    ``effective_max_minutes_all_bad_frames`` is the number of good frames after
    manual GUI exclusions, low/non-finite SNR, source-trace bad samples, and
    behavior NaNs, divided by frame rate. It is measured before the
    ``min_good_minutes`` rule converts an under-threshold cell to all-bad.
    Cells removed by that rule are plotted as gray bars.
    """
    import pandas as pd

    if snr_removed_summary is None:
        snr_removed_summary = summarize_snr_removed_frames(
            config=config,
            by_place_cells_only=by_place_cells_only,
            show_plot=False,
        )

    df = snr_removed_summary.get("per_cell", pd.DataFrame()).copy()
    missing_animals = list(snr_removed_summary.get("missing_animals", []))
    if df.empty:
        print("No rows found for SNR effective max-time summary.")
        return {
            "per_cell": df,
            "overall": pd.DataFrame(),
            "per_animal": pd.DataFrame(),
            "missing_animals": missing_animals,
            "figure": None,
            "figure_path": None,
        }

    df["effective_max_minutes_all_bad_frames"] = pd.to_numeric(
        df.get("good_minutes_before_min_minutes", np.nan),
        errors="coerce",
    )
    if "removed_by_min_good_minutes" in df:
        df["excluded_by_min_good_minutes"] = df["removed_by_min_good_minutes"].astype(bool)
    else:
        df["excluded_by_min_good_minutes"] = False
    finite_mask = np.isfinite(df["effective_max_minutes_all_bad_frames"].to_numpy(dtype=float))
    valid_df = df.loc[finite_mask].copy()

    n_kept = int(np.sum(~valid_df["excluded_by_min_good_minutes"].to_numpy(dtype=bool)))
    n_excluded = int(np.sum(valid_df["excluded_by_min_good_minutes"].to_numpy(dtype=bool)))
    overall_df = pd.DataFrame(
        [
            {
                "scope": "place_cells_only" if by_place_cells_only else "all_cells_including_excluded",
                "n_cells": int(len(valid_df)),
                "n_kept_cells": n_kept,
                "n_excluded_min_good_minutes": n_excluded,
                "mean_effective_max_minutes": (
                    float(np.nanmean(valid_df["effective_max_minutes_all_bad_frames"]))
                    if len(valid_df)
                    else np.nan
                ),
                "median_effective_max_minutes": (
                    float(np.nanmedian(valid_df["effective_max_minutes_all_bad_frames"]))
                    if len(valid_df)
                    else np.nan
                ),
                "min_effective_max_minutes": (
                    float(np.nanmin(valid_df["effective_max_minutes_all_bad_frames"]))
                    if len(valid_df)
                    else np.nan
                ),
                "max_effective_max_minutes": (
                    float(np.nanmax(valid_df["effective_max_minutes_all_bad_frames"]))
                    if len(valid_df)
                    else np.nan
                ),
            }
        ]
    )

    if len(valid_df):
        per_animal = (
            valid_df.groupby("animal_id", sort=True)
            .agg(
                n_cells=("effective_max_minutes_all_bad_frames", "size"),
                n_kept_cells=(
                    "excluded_by_min_good_minutes",
                    lambda s: int(np.sum(~s.to_numpy(dtype=bool))),
                ),
                n_excluded_min_good_minutes=(
                    "excluded_by_min_good_minutes",
                    lambda s: int(np.sum(s.to_numpy(dtype=bool))),
                ),
                mean_effective_max_minutes=("effective_max_minutes_all_bad_frames", "mean"),
                median_effective_max_minutes=("effective_max_minutes_all_bad_frames", "median"),
                min_effective_max_minutes=("effective_max_minutes_all_bad_frames", "min"),
                max_effective_max_minutes=("effective_max_minutes_all_bad_frames", "max"),
            )
            .reset_index()
        )
    else:
        per_animal = pd.DataFrame()

    print(
        "SNR effective max-time summary "
        f"({'place cells only' if by_place_cells_only else 'all cells'}): "
        f"n_cells={int(overall_df.loc[0, 'n_cells'])}, "
        f"excluded(<{config.analysis.min_good_minutes} min good)={n_excluded}, "
        f"mean={float(overall_df.loc[0, 'mean_effective_max_minutes']):.2f} min, "
        f"median={float(overall_df.loc[0, 'median_effective_max_minutes']):.2f} min"
    )
    if missing_animals:
        print(f"Missing merged data for: {', '.join(missing_animals)}")

    fig = None
    if show_plot and len(valid_df) > 0:
        kept_minutes = valid_df.loc[
            ~valid_df["excluded_by_min_good_minutes"],
            "effective_max_minutes_all_bad_frames",
        ].to_numpy(dtype=float)
        excluded_minutes = valid_df.loc[
            valid_df["excluded_by_min_good_minutes"],
            "effective_max_minutes_all_bad_frames",
        ].to_numpy(dtype=float)

        plot_series: list[np.ndarray] = []
        plot_labels: list[str] = []
        plot_colors: list[str] = []
        if kept_minutes.size > 0:
            plot_series.append(kept_minutes)
            plot_labels.append("Kept cells")
            plot_colors.append("#6C9A8B")
        if excluded_minutes.size > 0:
            plot_series.append(excluded_minutes)
            plot_labels.append(f"Excluded (<{config.analysis.min_good_minutes:g} min good)")
            plot_colors.append("#9E9E9E")

        max_effective_min = float(
            np.nanmax(valid_df["effective_max_minutes_all_bad_frames"].to_numpy(dtype=float))
        )
        bin_width = float(bin_width_minutes)
        if not np.isfinite(bin_width) or bin_width <= 0:
            raise ValueError(f"bin_width_minutes must be positive, got {bin_width_minutes!r}")
        bin_stop = max(bin_width, np.ceil(max_effective_min / bin_width) * bin_width + bin_width)
        minute_bins = np.arange(0.0, bin_stop + 0.5 * bin_width, bin_width)

        fig, ax = plt.subplots(figsize=figsize)
        _counts, bin_edges, _patches = ax.hist(
            plot_series,
            bins=minute_bins,
            stacked=True,
            color=plot_colors,
            edgecolor="white",
            linewidth=0.4,
            label=plot_labels,
        )
        total_counts, _ = np.histogram(np.concatenate(plot_series), bins=bin_edges)
        if total_counts.size > 0 and np.nanmax(total_counts) > 0:
            y_offset = max(0.2, float(np.nanmax(total_counts)) * 0.03)
            for left, right, count in zip(bin_edges[:-1], bin_edges[1:], total_counts):
                if int(count) <= 0:
                    continue
                ax.text(
                    (float(left) + float(right)) / 2.0,
                    float(count) + y_offset,
                    str(int(count)),
                    ha="center",
                    va="bottom",
                    fontsize=5,
                    fontname="Arial",
                )
            ax.set_ylim(top=float(np.nanmax(total_counts)) + y_offset * 5.0)

        ax.axvline(float(config.analysis.min_good_minutes), color="#A11D33", linestyle="--", linewidth=0.7)
        ax.set_xlabel("Effective max time (min)")
        ax.set_ylabel("Cell count")
        ax.set_title("Effective Time After Bad Frames")
        if show_legend and len(plot_labels) > 1:
            ax.legend(frameon=False, fontsize=5, handlelength=1.0)
        ax.spines["top"].set_visible(False)
        ax.spines["right"].set_visible(False)
        fig.tight_layout()

    figure_path = None
    if fig is not None and figure_save_folder is not None:
        folder = Path(figure_save_folder)
        if save_name is None:
            save_name = (
                "SNR_EffectiveMaxTimeDistribution_place_cells_only.svg"
                if by_place_cells_only
                else "SNR_EffectiveMaxTimeDistribution_all_cells.svg"
            )
        figure_path = folder / save_name
        figure_path.parent.mkdir(parents=True, exist_ok=True)
        fig.savefig(figure_path, dpi=300)
        print(f"SNR effective max-time figure saved: {figure_path}")
    elif fig is None:
        print("SNR effective max-time figure was not generated.")

    return {
        "per_cell": df,
        "overall": overall_df,
        "per_animal": per_animal,
        "missing_animals": missing_animals,
        "figure": fig,
        "figure_path": str(figure_path) if figure_path is not None else None,
    }


def plot_missing_frame_seconds_by_animal(
    config: PipelineConfig,
    *,
    variable_key: str = "x_neural",
    variable_label: str | None = None,
    variable_aliases: tuple[str, ...] | list[str] | None = None,
    figure_save_folder: str | Path | None = None,
    save_name: str | None = None,
    csv_name: str | None = None,
    show_plot: bool = True,
    figsize: tuple[float, float] = (6.6, 2.9),
    n_cols: int = 4,
) -> dict[str, Any]:
    """Plot per-animal finite vs non-finite seconds for a frame-wise variable."""
    import pandas as pd

    requested_key = str(variable_key)
    aliases = [requested_key]
    if variable_aliases is not None:
        aliases.extend([str(k) for k in variable_aliases])
    seen: set[str] = set()
    aliases = [k for k in aliases if not (k in seen or seen.add(k))]
    label = variable_label if variable_label is not None else requested_key

    rows: list[dict[str, Any]] = []
    for animal_id in config.animals:
        animal_dir = Path(config.data_root) / str(animal_id)
        row = {
            "animal_id": str(animal_id),
            "requested_variable": requested_key,
            "resolved_variable": "",
            "n_frames": np.nan,
            "frame_rate": np.nan,
            "duration_s": np.nan,
            "missing_frames": np.nan,
            "missing_seconds": np.nan,
            "missing_percent": np.nan,
            "finite_seconds": np.nan,
            "load_error": "",
        }
        try:
            merged = _load_merged_data(animal_dir, config)
        except Exception as exc:
            row["load_error"] = str(exc)
            rows.append(row)
            continue

        resolved_key = next((key for key in aliases if key in merged), None)
        if resolved_key is None:
            row["load_error"] = f"Missing variable; tried {aliases}"
            rows.append(row)
            continue

        values = np.asarray(merged.get(resolved_key, []), dtype=float).reshape(-1)
        try:
            frame_rate = float(merged.get("frame_rate", np.nan))
        except Exception:
            frame_rate = np.nan
        n_frames = int(values.size)
        missing_mask = ~np.isfinite(values)
        n_missing = int(np.sum(missing_mask))
        duration_s = float(n_frames / frame_rate) if np.isfinite(frame_rate) and frame_rate > 0 else np.nan
        missing_s = float(n_missing / frame_rate) if np.isfinite(frame_rate) and frame_rate > 0 else np.nan
        finite_s = float((n_frames - n_missing) / frame_rate) if np.isfinite(frame_rate) and frame_rate > 0 else np.nan
        missing_pct = float(100.0 * n_missing / n_frames) if n_frames > 0 else np.nan

        row.update(
            {
                "resolved_variable": str(resolved_key),
                "n_frames": n_frames,
                "frame_rate": frame_rate,
                "duration_s": duration_s,
                "missing_frames": n_missing,
                "missing_seconds": missing_s,
                "missing_percent": missing_pct,
                "finite_seconds": finite_s,
            }
        )
        rows.append(row)

    summary_df = pd.DataFrame(rows)

    fig = None
    if show_plot and len(summary_df) > 0:
        n_cols = max(1, int(n_cols))
        n_rows = int(np.ceil(len(summary_df) / n_cols))
        fig, axes = plt.subplots(n_rows, n_cols, figsize=figsize)
        axes = np.asarray(axes).reshape(-1)
        colors = ["#D9D9D9", "#D55E00"]

        def _fmt_seconds(value: Any) -> str:
            try:
                value_f = float(value)
            except Exception:
                return "NaN"
            if not np.isfinite(value_f):
                return "NaN"
            return f"{value_f:.1f} s"

        for ax_idx, ax in enumerate(axes):
            if ax_idx >= len(summary_df):
                ax.axis("off")
                continue
            row = summary_df.iloc[ax_idx]
            finite_s = float(row.get("finite_seconds", np.nan))
            missing_s = float(row.get("missing_seconds", np.nan))
            if not np.isfinite(finite_s):
                finite_s = 0.0
            if not np.isfinite(missing_s):
                missing_s = 0.0
            vals = np.asarray([finite_s, missing_s], dtype=float)
            if np.nansum(vals) <= 0:
                vals = np.asarray([1.0, 0.0], dtype=float)
            ax.pie(
                vals,
                colors=colors,
                startangle=90,
                counterclock=False,
                wedgeprops={"linewidth": 0.35, "edgecolor": "white"},
            )
            animal_short = str(row.get("animal_id", "")).replace("CKII_", "")
            try:
                missing_pct = float(row.get("missing_percent", np.nan))
            except Exception:
                missing_pct = np.nan
            title_pct = f"{missing_pct:.2f}%" if np.isfinite(missing_pct) else "NaN%"
            ax.set_title(
                f"{animal_short}\nNaN {_fmt_seconds(row.get('missing_seconds', np.nan))} ({title_pct})",
                fontsize=5,
                fontname="Arial",
                pad=1.5,
            )
            ax.set_aspect("equal")

        fig.legend(
            [f"Finite {label}", f"NaN {label}"],
            loc="lower center",
            bbox_to_anchor=(0.5, -0.01),
            ncol=2,
            frameon=False,
            fontsize=5,
        )
        fig.tight_layout(rect=[0, 0.05, 1, 1])

    figure_path = None
    csv_path = None
    if figure_save_folder is not None:
        folder = Path(figure_save_folder)
        folder.mkdir(parents=True, exist_ok=True)
        if save_name is None:
            safe_key = re.sub(r"[^A-Za-z0-9_]+", "_", requested_key).strip("_") or "variable"
            save_name = f"{safe_key}_NaN_RemovedSeconds_ByAnimal_Pies.svg"
        if csv_name is None:
            safe_key = re.sub(r"[^A-Za-z0-9_]+", "_", requested_key).strip("_") or "variable"
            csv_name = f"{safe_key}_NaN_RemovedSeconds_ByAnimal.csv"
        csv_path = folder / csv_name
        summary_df.to_csv(csv_path, index=False)
        if fig is not None:
            figure_path = folder / save_name
            fig.savefig(figure_path, dpi=300)
            print(f"{label} missing-frame pie figure saved: {figure_path}")
        print(f"{label} missing-frame summary CSV saved: {csv_path}")

    return {
        "summary_df": summary_df,
        "figure": fig,
        "figure_path": str(figure_path) if figure_path is not None else None,
        "csv_path": str(csv_path) if csv_path is not None else None,
        "variable_key": requested_key,
        "variable_aliases": aliases,
    }


def summarize_first_last_minute_snr_change(
    config: PipelineConfig,
    *,
    spatial_data: Any | None = None,
    window_seconds: float = 60.0,
    figure_save_folder: str | Path | None = None,
    save_name: str = "SNR_FirstLast1min_SignedChange.svg",
    show_plot: bool = True,
    figsize: tuple[float, float] = (3.4, 1.35),
) -> dict[str, Any]:
    """Summarize signed saved-SNR change from the first to last recording minute.

    The refined pipeline first uses the saved ``SNR_interpolated`` trace because
    that is the trace thresholded by ``_compute_bad_masks``. The signed percent
    change is ``100 * (last - first) / first``; negative values indicate a drop.
    """
    import pandas as pd

    def _finite_stats(values: Any, prefix: str) -> dict[str, float]:
        vals = np.asarray(values, dtype=float)
        vals = vals[np.isfinite(vals)]
        return {
            f"{prefix}_mean": float(np.nanmean(vals)) if vals.size else np.nan,
            f"{prefix}_median": float(np.nanmedian(vals)) if vals.size else np.nan,
            f"{prefix}_std": float(np.nanstd(vals, ddof=1)) if vals.size > 1 else np.nan,
            f"{prefix}_sem": (
                float(np.nanstd(vals, ddof=1) / np.sqrt(vals.size)) if vals.size > 1 else np.nan
            ),
            f"{prefix}_min": float(np.nanmin(vals)) if vals.size else np.nan,
            f"{prefix}_max": float(np.nanmax(vals)) if vals.size else np.nan,
        }

    def _sig_label(p_value: float) -> str:
        if not np.isfinite(p_value):
            return "n/a"
        if p_value < 0.001:
            return "***"
        if p_value < 0.01:
            return "**"
        if p_value < 0.05:
            return "*"
        return "n.s."

    def _holm_adjust(p_values: list[float]) -> list[float]:
        p_arr = np.asarray(p_values, dtype=float)
        out = np.full(p_arr.shape, np.nan, dtype=float)
        finite_idx = np.flatnonzero(np.isfinite(p_arr))
        m = int(finite_idx.size)
        if m == 0:
            return out.tolist()
        order = finite_idx[np.argsort(p_arr[finite_idx])]
        running = 0.0
        for rank, idx in enumerate(order):
            adjusted = float((m - rank) * p_arr[idx])
            running = max(running, adjusted)
            out[idx] = min(1.0, running)
        return out.tolist()

    def _add_bracket(ax: Any, pos1: float, pos2: float, y: float, h: float, sig_text: str, color: str = "black") -> None:
        ax.plot([pos1, pos1], [y, y + h], color=color, linewidth=0.8)
        ax.plot([pos2, pos2], [y, y + h], color=color, linewidth=0.8)
        ax.plot([pos1, pos2], [y + h, y + h], color=color, linewidth=0.8)
        ax.text(
            (pos1 + pos2) / 2.0,
            y + h + 0.02,
            sig_text,
            ha="center",
            va="bottom",
            fontsize=5,
            fontname="Arial",
            color=color,
        )

    def _add_comparison_brackets(
        ax: Any,
        comparisons_df: Any,
        specs: list[dict[str, Any]],
        *,
        p_column: str = "p_value",
    ) -> None:
        if comparisons_df is None or len(comparisons_df) == 0:
            return

        y_min, y_max = ax.get_ylim()
        y_range = float(y_max - y_min)
        if not np.isfinite(y_range) or y_range <= 0:
            y_range = 1.0
        h = y_range * 0.03
        text_h = y_range * 0.08
        gap = y_range * 0.05
        y = y_max + y_range * 0.05
        y_top = y_max

        for spec in specs:
            hit = comparisons_df.loc[comparisons_df["comparison"] == spec["comparison"]]
            if hit.empty:
                continue
            p_val = float(hit.iloc[0].get(p_column, np.nan))
            if not np.isfinite(p_val):
                continue
            _add_bracket(
                ax,
                float(spec["pos1"]),
                float(spec["pos2"]),
                y,
                h,
                _sig_label(p_val),
                color=str(spec.get("color", "black")),
            )
            y_top = max(y_top, y + h + text_h)
            y += h + text_h + gap

        if y_top > y_max:
            ax.set_ylim(y_min, y_top + y_range * 0.05)

    def _category_maps(spatial_data_obj: Any | None) -> dict[tuple[str, int], dict[str, Any]]:
        if spatial_data_obj is None:
            from utils.spatial_heatmaps import classify_spatial_cells

            spatial_data_obj = classify_spatial_cells(
                data_folder=str(config.data_root),
                folders=config.animals,
                cb_num_threshold=config.pooled.cb_num_threshold,
                cs_peak_rate_threshold=config.pooled.cs_peak_rate_threshold,
                cs_plc_definition_mode=config.pooled.cs_plc_definition_mode,
                snr_threshold=config.analysis.snr_threshold,
                min_good_minutes=config.analysis.min_good_minutes,
            )

        mapping: dict[tuple[str, int], dict[str, Any]] = {}

        def _add(cells: Any, place_nonplace: str, cs_group: str, is_place_cell: bool, is_cs_plc: bool) -> None:
            for cell in cells or []:
                if not isinstance(cell, dict):
                    continue
                session = cell.get("session", cell.get("animal_id", None))
                if session is None or "cell_idx" not in cell:
                    continue
                mapping[(str(session), int(cell["cell_idx"]))] = {
                    "is_place_cell": bool(is_place_cell),
                    "is_cs_plc": bool(is_cs_plc),
                    "place_nonplace_group": str(place_nonplace),
                    "cs_group": str(cs_group),
                }

        _add(getattr(spatial_data_obj, "plcs_csplus", []), "Place cell", "CS+ place cell", True, True)
        _add(getattr(spatial_data_obj, "plcs_csminus", []), "Place cell", "CS- place cell", True, False)
        _add(getattr(spatial_data_obj, "non_plcs", []), "Non-place cell", "Non-place cell", False, False)
        return mapping

    def _extract_per_cell_vector(source: Any, cell_idx: int, n_frames: int) -> np.ndarray:
        try:
            if source is None:
                return np.array([], dtype=float)
            if isinstance(source, (list, tuple)):
                if int(cell_idx) >= len(source) or source[int(cell_idx)] is None:
                    return np.array([], dtype=float)
                arr = np.asarray(source[int(cell_idx)], dtype=float).reshape(-1)
            else:
                data = np.asarray(source, dtype=float)
                if data.ndim == 1 and int(cell_idx) == 0:
                    arr = data.reshape(-1)
                elif data.ndim == 2 and data.shape[0] > int(cell_idx) and data.shape[1] == int(n_frames):
                    arr = data[int(cell_idx), :].reshape(-1)
                elif data.ndim == 2 and data.shape[1] > int(cell_idx) and data.shape[0] == int(n_frames):
                    arr = data[:, int(cell_idx)].reshape(-1)
                else:
                    return np.array([], dtype=float)
        except Exception:
            return np.array([], dtype=float)
        if arr.size != int(n_frames):
            return np.array([], dtype=float)
        return arr.astype(float, copy=False)

    def _plot_box_with_points(
        ax: Any,
        df: Any,
        group_col: str,
        groups: list[str],
        colors: list[str],
        *,
        value_col: str = "pct_snr_change_last_vs_first",
        title: str,
        ylabel: str | None = None,
        zero_line: bool = True,
    ) -> None:
        rng = np.random.default_rng(42)
        plot_vals: list[np.ndarray] = []
        positions: list[float] = []
        labels: list[str] = []
        used_colors: list[str] = []
        for pos, (group, color) in enumerate(zip(groups, colors), start=1):
            vals = df.loc[df[group_col] == group, value_col].to_numpy(dtype=float)
            vals = vals[np.isfinite(vals)]
            if vals.size == 0:
                continue
            plot_vals.append(vals)
            positions.append(float(pos))
            labels.append(str(group))
            used_colors.append(str(color))
        if not plot_vals:
            ax.text(0.5, 0.5, "No valid cells", ha="center", va="center", transform=ax.transAxes, fontsize=6)
            ax.set_xticks([])
        else:
            bp = ax.boxplot(
                plot_vals,
                positions=positions,
                widths=0.42,
                patch_artist=True,
                showfliers=False,
                medianprops={"color": "black", "linewidth": 0.7},
                boxprops={"linewidth": 0.6},
                whiskerprops={"linewidth": 0.6},
                capprops={"linewidth": 0.6},
            )
            for patch, color in zip(bp["boxes"], used_colors):
                patch.set_facecolor(color)
                patch.set_alpha(0.45)
            for pos, vals, color in zip(positions, plot_vals, used_colors):
                jitter = rng.normal(0.0, 0.035, size=vals.size)
                ax.scatter(np.full(vals.size, pos) + jitter, vals, s=7, color=color, alpha=0.75, linewidths=0)
            ax.set_xticks(positions)
            ax.set_xticklabels(labels, rotation=25, ha="right")
        if zero_line:
            ax.axhline(0.0, color="#666666", linewidth=0.6, linestyle="--", zorder=0)
        ax.set_title(title)
        if ylabel:
            ax.set_ylabel(ylabel)
        ax.spines["top"].set_visible(False)
        ax.spines["right"].set_visible(False)
        ax.tick_params(labelsize=5, direction="in", length=1.75)

    window_seconds = float(window_seconds)
    if window_seconds <= 0:
        raise ValueError("window_seconds must be > 0.")

    if spatial_data is None:
        from utils.spatial_heatmaps import classify_spatial_cells

        spatial_data = classify_spatial_cells(
            data_folder=str(config.data_root),
            folders=config.animals,
            cb_num_threshold=config.pooled.cb_num_threshold,
            cs_peak_rate_threshold=config.pooled.cs_peak_rate_threshold,
            cs_plc_definition_mode=config.pooled.cs_plc_definition_mode,
            snr_threshold=config.analysis.snr_threshold,
            min_good_minutes=config.analysis.min_good_minutes,
        )
    category_by_key = _category_maps(spatial_data)

    rows: list[dict[str, Any]] = []
    skipped_rows: list[dict[str, Any]] = []
    for animal_id in config.animals:
        animal_dir = config.data_root / animal_id
        try:
            _resolve_merged_data_path(animal_dir, config)
        except FileNotFoundError:
            skipped_rows.append(
                {
                    "animal_id": str(animal_id),
                    "cell_idx": np.nan,
                    "cell_num": np.nan,
                    "reason": "missing merged data",
                }
            )
            continue

        merged = _load_merged_data(animal_dir, config)
        x_neural = np.asarray(merged.get("x_neural", []), dtype=float)
        frame_rate = float(merged.get("frame_rate", np.nan))
        if not np.isfinite(frame_rate) or frame_rate <= 0:
            frame_rate = 1.0
        n_frames = int(x_neural.size)
        window_frames = int(round(window_seconds * frame_rate))
        window_frames = max(1, window_frames)
        if n_frames < 2 * window_frames:
            skipped_rows.append(
                {
                    "animal_id": str(animal_id),
                    "cell_idx": np.nan,
                    "cell_num": np.nan,
                    "reason": f"recording shorter than {2 * window_seconds:g} seconds",
                }
            )
            continue

        snr_source = merged.get("SNR_interpolated", [])
        traces_snr_fallback = merged.get("traces_SNR_interpolated", merged.get("traces", []))
        all_spikes = merged.get("all_spikes", merged.get("spikes", []))
        complex_bursts_dicts = merged.get("complex_bursts_dicts", [])
        n_cells = len(merged.get("spikes", traces_snr_fallback))
        try:
            final_bad_masks = np.asarray(
                _compute_bad_masks(
                    merged,
                    float(config.analysis.snr_threshold),
                    float(config.analysis.min_good_minutes),
                ),
                dtype=bool,
            )
            if final_bad_masks.ndim != 2 or final_bad_masks.shape != (n_cells, n_frames):
                final_bad_masks = np.empty((0, 0), dtype=bool)
        except Exception:
            final_bad_masks = np.empty((0, 0), dtype=bool)

        for cell_idx in range(n_cells):
            base_row = {
                "animal_id": str(animal_id),
                "cell_idx": int(cell_idx),
                "cell_num": int(cell_idx) + 1,
            }
            category = category_by_key.get((str(animal_id), int(cell_idx)))
            if category is None:
                skipped_rows.append(
                    {
                        **base_row,
                        "reason": "not in spatial classification output; excluded by SNR/eligibility filtering",
                    }
                )
                continue
            snr_vals = _extract_per_cell_vector(snr_source, cell_idx, n_frames)
            snr_value_source = "saved_SNR_interpolated"
            if snr_vals.size != n_frames:
                trace = _extract_per_cell_vector(traces_snr_fallback, cell_idx, n_frames)
                if trace.size != n_frames:
                    skipped_rows.append({**base_row, "reason": "missing saved or fallback SNR trace"})
                    continue
                spks = np.asarray(all_spikes[cell_idx], dtype=int) if cell_idx < len(all_spikes) else np.array([], dtype=int)
                cb = complex_bursts_dicts[cell_idx] if cell_idx < len(complex_bursts_dicts) else None
                try:
                    snr_res = compute_time_varying_snr_from_trace(
                        trace=trace,
                        spks=spks,
                        complex_burst_dict=cb,
                        sampling_rate_hz=frame_rate,
                        isi_threshold_ms=20,
                        spike_baseline_points=3,
                        spike_remove_points=3,
                        baseline_window_seconds=10,
                        plot_single_cell=False,
                    )
                    snr_vals = np.asarray(snr_res.get("snr_time_varying", []), dtype=float).reshape(-1)
                    snr_value_source = "recomputed_from_fallback_trace"
                except Exception as exc:
                    skipped_rows.append({**base_row, "reason": f"fallback time-varying SNR failed: {exc}"})
                    continue
                if snr_vals.size != n_frames:
                    skipped_rows.append(
                        {
                            **base_row,
                            "reason": f"fallback time-varying SNR length mismatch: expected {n_frames}, got {snr_vals.size}",
                        }
                    )
                    continue

            has_final_bad_mask = bool(final_bad_masks.shape == (n_cells, n_frames))
            if has_final_bad_mask:
                good_frame_mask = (~final_bad_masks[cell_idx]) & np.isfinite(snr_vals)
            else:
                good_frame_mask = np.isfinite(snr_vals)
            good_frame_snr = snr_vals[good_frame_mask]
            n_good_snr_frames = int(good_frame_snr.size)
            good_snr_minutes = float(n_good_snr_frames) / float(frame_rate) / 60.0
            overall_good_frame_mean_snr = (
                float(np.nanmean(good_frame_snr)) if n_good_snr_frames > 0 else np.nan
            )
            min_good_frame_snr = float(np.nanmin(good_frame_snr)) if n_good_snr_frames > 0 else np.nan
            n_good_snr_frames_below_threshold = int(
                np.sum(good_frame_snr < (float(config.analysis.snr_threshold) - 1e-9))
            )

            first_vals = snr_vals[:window_frames]
            last_vals = snr_vals[-window_frames:]
            first_mean = float(np.nanmean(first_vals)) if np.any(np.isfinite(first_vals)) else np.nan
            last_mean = float(np.nanmean(last_vals)) if np.any(np.isfinite(last_vals)) else np.nan
            if not np.isfinite(first_mean) or np.isclose(first_mean, 0.0) or not np.isfinite(last_mean):
                pct_change = np.nan
                valid_change = False
            else:
                pct_change = float(100.0 * (last_mean - first_mean) / first_mean)
                valid_change = True

            rows.append(
                {
                    **base_row,
                    "recording_duration_min": float(n_frames / frame_rate / 60.0),
                    "window_seconds": window_seconds,
                    "first_1min_mean_snr": first_mean,
                    "last_1min_mean_snr": last_mean,
                    "pct_snr_change_last_vs_first": pct_change,
                    "overall_good_frame_mean_snr": overall_good_frame_mean_snr,
                    "min_good_frame_snr": min_good_frame_snr,
                    "n_good_snr_frames": n_good_snr_frames,
                    "n_good_snr_frames_below_threshold": n_good_snr_frames_below_threshold,
                    "good_snr_minutes": good_snr_minutes,
                    "used_final_bad_mask_for_good_snr": has_final_bad_mask,
                    "snr_value_source": snr_value_source,
                    "valid_change": bool(valid_change),
                    "is_place_cell": category.get("is_place_cell", np.nan),
                    "is_cs_plc": category.get("is_cs_plc", np.nan),
                    "place_nonplace_group": category.get("place_nonplace_group", "Unclassified"),
                    "cs_group": category.get("cs_group", "Unclassified"),
                }
            )

    per_cell = pd.DataFrame(rows)
    skipped_cells = pd.DataFrame(skipped_rows)
    if per_cell.empty:
        return {
            "per_cell": per_cell,
            "overall": pd.DataFrame(),
            "group_summary": pd.DataFrame(),
            "comparisons": pd.DataFrame(),
            "good_frame_snr_comparisons": pd.DataFrame(),
            "skipped_cells": skipped_cells,
            "figure_path": None,
            "figure": None,
            "spatial_data": spatial_data,
        }

    valid_df = per_cell.loc[np.asarray(per_cell["valid_change"], dtype=bool)].copy()
    good_snr_df = per_cell.loc[np.isfinite(per_cell["overall_good_frame_mean_snr"].to_numpy(dtype=float))].copy()
    overall = {
        "n_cells_total": int(len(per_cell)),
        "n_cells_valid_change": int(len(valid_df)),
        "n_cells_valid_good_frame_snr": int(len(good_snr_df)),
        "n_cells_skipped": int(len(skipped_cells)),
        **_finite_stats(valid_df["first_1min_mean_snr"], "first_1min_mean_snr"),
        **_finite_stats(valid_df["last_1min_mean_snr"], "last_1min_mean_snr"),
        **_finite_stats(valid_df["pct_snr_change_last_vs_first"], "pct_snr_change_last_vs_first"),
        **_finite_stats(good_snr_df["overall_good_frame_mean_snr"], "overall_good_frame_mean_snr"),
        **_finite_stats(good_snr_df["good_snr_minutes"], "good_snr_minutes"),
    }
    overall_df = pd.DataFrame([overall])

    summary_rows: list[dict[str, Any]] = []
    group_specs = [
        ("all_cells", "All cells", None, None),
        ("place_nonplace", "Place cell", "place_nonplace_group", "Place cell"),
        ("place_nonplace", "Non-place cell", "place_nonplace_group", "Non-place cell"),
        ("cs_place_nonplace", "CS+ place cell", "cs_group", "CS+ place cell"),
        ("cs_place_nonplace", "CS- place cell", "cs_group", "CS- place cell"),
        ("cs_place_nonplace", "Non-place cell", "cs_group", "Non-place cell"),
    ]
    for grouping, group, group_col, group_value in group_specs:
        if group_col is None:
            group_df = valid_df
            group_snr_df = good_snr_df
        else:
            group_df = valid_df.loc[valid_df[group_col] == group_value]
            group_snr_df = good_snr_df.loc[good_snr_df[group_col] == group_value]
        summary_rows.append(
            {
                "grouping": grouping,
                "group": group,
                "n_cells": int(len(group_df)),
                "n_animals": int(group_df["animal_id"].nunique()) if len(group_df) else 0,
                "n_cells_valid_good_frame_snr": int(len(group_snr_df)),
                "n_animals_valid_good_frame_snr": (
                    int(group_snr_df["animal_id"].nunique()) if len(group_snr_df) else 0
                ),
                **_finite_stats(group_df["first_1min_mean_snr"], "first_1min_mean_snr"),
                **_finite_stats(group_df["last_1min_mean_snr"], "last_1min_mean_snr"),
                **_finite_stats(group_df["pct_snr_change_last_vs_first"], "pct_snr_change_last_vs_first"),
                **_finite_stats(group_snr_df["overall_good_frame_mean_snr"], "overall_good_frame_mean_snr"),
                **_finite_stats(group_snr_df["good_snr_minutes"], "good_snr_minutes"),
            }
        )
    group_summary = pd.DataFrame(summary_rows)

    comparison_specs = [
        ("place_vs_nonplace", "place_nonplace_group", "Place cell", "Non-place cell"),
        ("csplus_vs_csminus", "cs_group", "CS+ place cell", "CS- place cell"),
        ("csplus_vs_nonplace", "cs_group", "CS+ place cell", "Non-place cell"),
        ("csminus_vs_nonplace", "cs_group", "CS- place cell", "Non-place cell"),
    ]

    def _build_comparisons(df: Any, value_col: str) -> Any:
        comparison_rows: list[dict[str, Any]] = []
        for comparison, group_col, group_a, group_b in comparison_specs:
            a = df.loc[df[group_col] == group_a, value_col].to_numpy(dtype=float)
            b = df.loc[df[group_col] == group_b, value_col].to_numpy(dtype=float)
            a = a[np.isfinite(a)]
            b = b[np.isfinite(b)]
            if a.size > 0 and b.size > 0:
                try:
                    res = scipy_stats.mannwhitneyu(a, b, alternative="two-sided")
                    statistic = float(res.statistic)
                    p_value = float(res.pvalue)
                    test = "mann-whitney u"
                except Exception:
                    statistic = np.nan
                    p_value = np.nan
                    test = "mann-whitney u"
            else:
                statistic = np.nan
                p_value = np.nan
                test = "not enough cells"
            comparison_rows.append(
                {
                    "comparison": comparison,
                    "metric": value_col,
                    "group_a": group_a,
                    "group_b": group_b,
                    "n_a": int(a.size),
                    "n_b": int(b.size),
                    "median_a": float(np.nanmedian(a)) if a.size else np.nan,
                    "median_b": float(np.nanmedian(b)) if b.size else np.nan,
                    "median_delta_a_minus_b": (
                        float(np.nanmedian(a) - np.nanmedian(b)) if a.size and b.size else np.nan
                    ),
                    "test": test,
                    "statistic": statistic,
                    "p_value": p_value,
                }
            )
        out = pd.DataFrame(comparison_rows)
        if not out.empty:
            out["holm_p_value"] = _holm_adjust(out["p_value"].to_list())
            out["significance"] = out["p_value"].map(_sig_label)
            out["holm_significance"] = out["holm_p_value"].map(_sig_label)
        return out

    comparisons = _build_comparisons(valid_df, "pct_snr_change_last_vs_first")
    good_frame_snr_comparisons = _build_comparisons(good_snr_df, "overall_good_frame_mean_snr")

    fig = None
    figure_path = None
    if (show_plot or figure_save_folder is not None) and (len(valid_df) > 0 or len(good_snr_df) > 0):
        csplus_color = "#EE9B00"
        csminus_color = "#026C80"
        nonplc_color = "#888888"
        all_place_color = "#333333"

        base_width, base_height = tuple(float(v) for v in figsize)
        fig, axes = plt.subplots(2, 3, figsize=(base_width, base_height * 2.05))
        axes = np.asarray(axes)
        vals_all = valid_df["pct_snr_change_last_vs_first"].to_numpy(dtype=float)
        vals_all = vals_all[np.isfinite(vals_all)]
        drop_vals_all = -vals_all
        if drop_vals_all.size > 0:
            axes[0, 0].hist(drop_vals_all, bins=12, color=nonplc_color, edgecolor="white", linewidth=0.4)
            axes[0, 0].axvline(0.0, color="#666666", linewidth=0.6, linestyle="--")
        else:
            axes[0, 0].text(0.5, 0.5, "No valid cells", ha="center", va="center", transform=axes[0, 0].transAxes)
        axes[0, 0].set_title("All cells")
        axes[0, 0].set_xlabel("% SNR drop")
        axes[0, 0].set_ylabel("Cell count")
        axes[0, 0].spines["top"].set_visible(False)
        axes[0, 0].spines["right"].set_visible(False)
        axes[0, 0].tick_params(labelsize=5, direction="in", length=1.75)

        _plot_box_with_points(
            axes[0, 1],
            valid_df,
            "place_nonplace_group",
            ["Place cell", "Non-place cell"],
            [all_place_color, nonplc_color],
            title="Place vs non-place",
            ylabel="% SNR change",
        )
        _add_comparison_brackets(
            axes[0, 1],
            comparisons,
            [
                {
                    "comparison": "place_vs_nonplace",
                    "pos1": 1,
                    "pos2": 2,
                    "color": all_place_color,
                },
            ],
        )
        _plot_box_with_points(
            axes[0, 2],
            valid_df,
            "cs_group",
            ["CS+ place cell", "CS- place cell", "Non-place cell"],
            [csplus_color, csminus_color, nonplc_color],
            title="CS groups",
        )
        _add_comparison_brackets(
            axes[0, 2],
            comparisons,
            [
                {
                    "comparison": "csplus_vs_csminus",
                    "pos1": 1,
                    "pos2": 2,
                    "color": "black",
                },
                {
                    "comparison": "csplus_vs_nonplace",
                    "pos1": 1,
                    "pos2": 3,
                    "color": csplus_color,
                },
                {
                    "comparison": "csminus_vs_nonplace",
                    "pos1": 2,
                    "pos2": 3,
                    "color": csminus_color,
                },
            ],
        )
        mean_snr_vals = good_snr_df["overall_good_frame_mean_snr"].to_numpy(dtype=float)
        mean_snr_vals = mean_snr_vals[np.isfinite(mean_snr_vals)]
        if mean_snr_vals.size > 0:
            axes[1, 0].hist(mean_snr_vals, bins=12, color=nonplc_color, edgecolor="white", linewidth=0.4)
        else:
            axes[1, 0].text(0.5, 0.5, "No valid cells", ha="center", va="center", transform=axes[1, 0].transAxes)
        axes[1, 0].set_title("All cells")
        axes[1, 0].set_xlabel("Good-frame mean SNR")
        axes[1, 0].set_ylabel("Cell count")
        axes[1, 0].spines["top"].set_visible(False)
        axes[1, 0].spines["right"].set_visible(False)
        axes[1, 0].tick_params(labelsize=5, direction="in", length=1.75)

        _plot_box_with_points(
            axes[1, 1],
            good_snr_df,
            "place_nonplace_group",
            ["Place cell", "Non-place cell"],
            [all_place_color, nonplc_color],
            value_col="overall_good_frame_mean_snr",
            title="Place vs non-place",
            ylabel="Good-frame mean SNR",
            zero_line=False,
        )
        _add_comparison_brackets(
            axes[1, 1],
            good_frame_snr_comparisons,
            [
                {
                    "comparison": "place_vs_nonplace",
                    "pos1": 1,
                    "pos2": 2,
                    "color": all_place_color,
                },
            ],
        )
        _plot_box_with_points(
            axes[1, 2],
            good_snr_df,
            "cs_group",
            ["CS+ place cell", "CS- place cell", "Non-place cell"],
            [csplus_color, csminus_color, nonplc_color],
            value_col="overall_good_frame_mean_snr",
            title="CS groups",
            zero_line=False,
        )
        _add_comparison_brackets(
            axes[1, 2],
            good_frame_snr_comparisons,
            [
                {
                    "comparison": "csplus_vs_csminus",
                    "pos1": 1,
                    "pos2": 2,
                    "color": "black",
                },
                {
                    "comparison": "csplus_vs_nonplace",
                    "pos1": 1,
                    "pos2": 3,
                    "color": csplus_color,
                },
                {
                    "comparison": "csminus_vs_nonplace",
                    "pos1": 2,
                    "pos2": 3,
                    "color": csminus_color,
                },
            ],
        )
        fig.tight_layout(w_pad=0.7)

        if figure_save_folder is not None:
            figure_dir = Path(figure_save_folder)
            figure_dir.mkdir(parents=True, exist_ok=True)
            figure_path = str(figure_dir / str(save_name))
            fig.savefig(figure_path, dpi=300)
    if show_plot and fig is not None:
        plt.show()
    elif fig is not None:
        plt.close(fig)

    print(
        "First-vs-last saved/interpolated SNR change: "
        f"valid cells={overall['n_cells_valid_change']}/{overall['n_cells_total']}, "
        f"median change={overall['pct_snr_change_last_vs_first_median']:.2f}% "
        "(negative means SNR dropped)."
    )
    if figure_path:
        print(f"Saved: {figure_path}")

    return {
        "per_cell": per_cell,
        "overall": overall_df,
        "group_summary": group_summary,
        "comparisons": comparisons,
        "good_frame_snr_comparisons": good_frame_snr_comparisons,
        "skipped_cells": skipped_cells,
        "figure_path": figure_path,
        "figure": fig if show_plot else None,
        "spatial_data": spatial_data,
    }


def plot_animal_movement_summary_boxplots(
    config: PipelineConfig,
    figure_save_folder: str | Path,
    *,
    first_n_minutes: float = 10.0,
    figsize: tuple[float, float] = (3.6, 1.45),
    save_name: str = "AnimalMovementSummary.svg",
    show_plot: bool = True,
) -> dict[str, Any]:
    import pandas as pd

    first_n_minutes_use = float(first_n_minutes)
    if not np.isclose(first_n_minutes_use, 10.0, atol=1e-8):
        raise ValueError(
            "animal_movement_summary.pkl currently stores first-10-minute distance only; "
            "use first_n_minutes=10.0."
        )

    rows: list[dict[str, Any]] = []
    for animal_id in config.animals:
        summary = load_animal_movement_summary(animal_id, config)
        rows.append(
            {
                "animal_id": str(summary.get("animal_id", animal_id)),
                "moving_percent": float(summary.get("moving_percent", np.nan)),
                "mean_speed_cm_s": float(summary.get("mean_speed_cm_s", np.nan)),
                "distance_first_10_min_m": float(summary.get("distance_first_10_min_m", np.nan)),
            }
        )

    summary_df = pd.DataFrame(rows)
    if summary_df.empty:
        raise ValueError("No cached animal movement summaries were found.")

    if len(tuple(figsize)) != 2:
        raise ValueError("figsize must be a 2-tuple: (width, height).")
    fig, axes = plt.subplots(1, 3, figsize=tuple(float(v) for v in figsize))
    axes = np.atleast_1d(axes)
    rng = np.random.default_rng(42)
    metric_specs = [
        ("moving_percent", "Moving time (%)", "#4D4D4D"),
        ("mean_speed_cm_s", "Mean speed moving (cm/s)", "#4D4D4D"),
        ("distance_first_10_min_m", "Distance first 10 min (m)", "#4D4D4D"),
    ]

    for ax, (metric_key, y_label, color) in zip(axes, metric_specs):
        vals = summary_df[metric_key].to_numpy(dtype=float)
        vals = vals[np.isfinite(vals)]
        bp = ax.boxplot(
            [vals],
            positions=[1.0],
            widths=0.42,
            patch_artist=True,
            showfliers=False,
            medianprops={"color": "black", "linewidth": 0.7},
            boxprops={"linewidth": 0.5},
            whiskerprops={"linewidth": 0.5},
            capprops={"linewidth": 0.5},
        )
        for box in bp["boxes"]:
            box.set_facecolor(color)
            box.set_alpha(0.25)

        if vals.size > 0:
            x_jitter = 1.0 + rng.uniform(-0.08, 0.08, size=vals.size)
            ax.scatter(x_jitter, vals, s=10, color=color, alpha=0.9, linewidths=0, zorder=2)

        ax.set_xlim(0.65, 1.35)
        ax.set_xticks([])
        ax.set_ylabel(y_label)
        ax.tick_params(labelsize=5, direction="in", length=1.75)
        ax.spines["top"].set_visible(False)
        ax.spines["right"].set_visible(False)

    fig.tight_layout(w_pad=0.9)
    figure_dir = Path(figure_save_folder)
    figure_dir.mkdir(parents=True, exist_ok=True)
    figure_path = figure_dir / str(save_name)
    fig.savefig(figure_path, dpi=300)
    if show_plot:
        plt.show()
    else:
        plt.close(fig)

    return {
        "figure_path": str(figure_path),
        "summary_df": summary_df,
        "figure": fig if show_plot else None,
    }


def plot_animal_movement_first_last_window_comparison(
    config: PipelineConfig,
    figure_save_folder: str | Path,
    *,
    window_minutes: float = 10.0,
    include_short_recordings_in_first_window: bool = False,
    figsize: tuple[float, float] = (2.4, 1.2),
    save_name: str = "AnimalMovementFirstLast10minComparison.svg",
    annotate_stats: bool = True,
    show_plot: bool = True,
) -> dict[str, Any]:
    import pandas as pd

    def _format_significance_label(p_value: float) -> str:
        if not np.isfinite(p_value):
            return "n/a"
        if p_value < 0.001:
            return "***"
        if p_value < 0.01:
            return "**"
        if p_value < 0.05:
            return "*"
        return "n.s."

    window_minutes = float(window_minutes)
    if window_minutes <= 0:
        raise ValueError("window_minutes must be > 0.")

    rows: list[dict[str, Any]] = []
    skipped_animals: list[dict[str, Any]] = []
    unpaired_animals: list[dict[str, Any]] = []
    for animal_id in config.animals:
        merged = _load_merged_data(config.data_root / animal_id, config)
        movement_inputs = _prepare_animal_movement_summary_inputs(animal_id, merged, config)
        frame_rate = float(movement_inputs["frame_rate"])
        n_frames = int(movement_inputs["n_frames"])
        recording_duration_min = float(n_frames / frame_rate / 60.0)
        window_frames = int(np.floor(window_minutes * 60.0 * frame_rate))
        window_frames = max(1, window_frames)

        if n_frames <= window_frames:
            skip_row = {
                "animal_id": str(animal_id),
                "recording_duration_min": recording_duration_min,
                "reason": f"recording <= {window_minutes:g} min",
            }
            if not include_short_recordings_in_first_window or n_frames <= 0:
                skipped_animals.append(skip_row)
                continue
            unpaired_animals.append(skip_row)

        has_last_window = n_frames > window_frames
        first_end_frame = min(n_frames, window_frames)
        window_defs = [
            ("first", f"First {window_minutes:g} min", 0, first_end_frame),
        ]
        if has_last_window:
            window_defs.append(
                ("last", f"Last {window_minutes:g} min", n_frames - window_frames, n_frames)
            )
        for window_key, window_label, start_frame, end_frame in window_defs:
            metrics = _compute_animal_movement_window_metrics(movement_inputs, start_frame, end_frame)
            rows.append(
                {
                    "animal_id": str(animal_id),
                    "window": window_key,
                    "window_label": window_label,
                    "recording_duration_min": recording_duration_min,
                    "window_minutes": window_minutes,
                    "start_min": float(metrics["start_frame"] / frame_rate / 60.0),
                    "end_min": float(metrics["end_frame"] / frame_rate / 60.0),
                    "actual_window_minutes": float(
                        (metrics["end_frame"] - metrics["start_frame"]) / frame_rate / 60.0
                    ),
                    "has_last_window": bool(has_last_window),
                    "is_paired_window": bool(has_last_window),
                    "n_valid_frames": int(metrics["n_valid_frames"]),
                    "n_moving_frames": int(metrics["n_moving_frames"]),
                    "moving_percent": float(metrics["moving_percent"]),
                    "mean_speed_cm_s": float(metrics["mean_speed_cm_s"]),
                    "distance_m": float(metrics["distance_m"]),
                }
            )

    comparison_df = pd.DataFrame(rows)
    if comparison_df.empty:
        raise ValueError(f"No animals have recordings longer than {window_minutes:g} minutes.")

    metric_specs = [
        ("moving_percent", "Moving time (%)"),
        ("mean_speed_cm_s", "Mean moving speed (cm/s)"),
        ("distance_m", "Distance (m)"),
    ]

    paired_df = comparison_df.pivot(index="animal_id", columns="window", values=[m[0] for m in metric_specs])
    paired_df.columns = [f"{metric}_{window}" for metric, window in paired_df.columns]
    paired_df = paired_df.reset_index()
    for metric_key, _ in metric_specs:
        for window_key in ("first", "last"):
            column = f"{metric_key}_{window_key}"
            if column not in paired_df.columns:
                paired_df[column] = np.nan

    stats_rows: list[dict[str, Any]] = []
    for metric_key, y_label in metric_specs:
        first_vals = paired_df[f"{metric_key}_first"].to_numpy(dtype=float)
        last_vals = paired_df[f"{metric_key}_last"].to_numpy(dtype=float)
        valid = np.isfinite(first_vals) & np.isfinite(last_vals)
        n_valid = int(np.sum(valid))
        delta = last_vals[valid] - first_vals[valid]
        if n_valid >= 2 and not np.allclose(delta, 0.0, equal_nan=False):
            try:
                test_res = scipy_stats.wilcoxon(last_vals[valid], first_vals[valid])
                p_value = float(test_res.pvalue)
                test_stat = float(test_res.statistic)
                test_name = "wilcoxon"
            except ValueError:
                p_value = np.nan
                test_stat = np.nan
                test_name = "wilcoxon"
        elif n_valid >= 2:
            p_value = 1.0
            test_stat = 0.0
            test_name = "wilcoxon"
        else:
            p_value = np.nan
            test_stat = np.nan
            test_name = "not enough paired animals"

        stats_rows.append(
            {
                "metric": metric_key,
                "label": y_label,
                "n_animals": n_valid,
                "first_mean": float(np.nanmean(first_vals[valid])) if n_valid else np.nan,
                "last_mean": float(np.nanmean(last_vals[valid])) if n_valid else np.nan,
                "mean_delta_last_minus_first": float(np.nanmean(delta)) if n_valid else np.nan,
                "median_delta_last_minus_first": float(np.nanmedian(delta)) if n_valid else np.nan,
                "test": test_name,
                "statistic": test_stat,
                "p_value": p_value,
            }
        )
    stats_df = pd.DataFrame(stats_rows)

    if len(tuple(figsize)) != 2:
        raise ValueError("figsize must be a 2-tuple: (width, height).")
    fig, axes = plt.subplots(1, 3, figsize=tuple(float(v) for v in figsize))
    axes = np.atleast_1d(axes)
    rng = np.random.default_rng(42)
    colors = {"first": "#4D4D4D", "last": "#A8574F"}

    for ax, (metric_key, y_label) in zip(axes, metric_specs):
        first_vals = paired_df[f"{metric_key}_first"].to_numpy(dtype=float)
        last_vals = paired_df[f"{metric_key}_last"].to_numpy(dtype=float)
        valid = np.isfinite(first_vals) & np.isfinite(last_vals)
        first_finite = np.isfinite(first_vals)
        last_finite = np.isfinite(last_vals)
        plot_vals = [first_vals[first_finite], last_vals[last_finite]]
        bp = ax.boxplot(
            plot_vals,
            positions=[1.0, 2.0],
            widths=0.42,
            patch_artist=True,
            showfliers=False,
            medianprops={"color": "black", "linewidth": 0.7},
            boxprops={"linewidth": 0.5},
            whiskerprops={"linewidth": 0.5},
            capprops={"linewidth": 0.5},
        )
        for box, color in zip(bp["boxes"], [colors["first"], colors["last"]]):
            box.set_facecolor(color)
            box.set_alpha(0.25)

        if np.any(valid):
            jitter_first = rng.uniform(-0.04, 0.04, size=int(np.sum(valid)))
            jitter_last = rng.uniform(-0.04, 0.04, size=int(np.sum(valid)))
            for idx, (first_val, last_val) in enumerate(zip(first_vals[valid], last_vals[valid])):
                ax.plot(
                    [1.0 + jitter_first[idx], 2.0 + jitter_last[idx]],
                    [first_val, last_val],
                    color="#B0B0B0",
                    linewidth=0.45,
                    zorder=1,
                )
            ax.scatter(
                1.0 + jitter_first,
                first_vals[valid],
                s=9,
                color=colors["first"],
                alpha=0.9,
                linewidths=0,
                zorder=2,
            )
            ax.scatter(
                2.0 + jitter_last,
                last_vals[valid],
                s=9,
                color=colors["last"],
                alpha=0.9,
                linewidths=0,
                zorder=2,
            )

        unpaired_first = first_finite & ~np.isfinite(last_vals)
        if np.any(unpaired_first):
            jitter_unpaired_first = rng.uniform(-0.04, 0.04, size=int(np.sum(unpaired_first)))
            ax.scatter(
                1.0 + jitter_unpaired_first,
                first_vals[unpaired_first],
                s=9,
                color=colors["first"],
                alpha=0.9,
                linewidths=0,
                zorder=2,
            )

        unpaired_last = last_finite & ~np.isfinite(first_vals)
        if np.any(unpaired_last):
            jitter_unpaired_last = rng.uniform(-0.04, 0.04, size=int(np.sum(unpaired_last)))
            ax.scatter(
                2.0 + jitter_unpaired_last,
                last_vals[unpaired_last],
                s=9,
                color=colors["last"],
                alpha=0.9,
                linewidths=0,
                zorder=2,
            )

        if annotate_stats and np.any(valid):
            stats_match = stats_df.loc[stats_df["metric"] == metric_key]
            p_value = float(stats_match["p_value"].iloc[0]) if not stats_match.empty else np.nan
            finite_plot_vals = np.concatenate(plot_vals)
            finite_plot_vals = finite_plot_vals[np.isfinite(finite_plot_vals)]
            if finite_plot_vals.size > 0:
                y_min = float(np.nanmin(finite_plot_vals))
                y_max = float(np.nanmax(finite_plot_vals))
                y_span = y_max - y_min
                if (not np.isfinite(y_span)) or y_span <= 0:
                    y_span = max(abs(y_max), 1.0)
                y_line = y_max + 0.10 * y_span
                y_tick = y_max + 0.06 * y_span
                y_text = y_max + 0.15 * y_span
                ax.plot(
                    [1.0, 1.0, 2.0, 2.0],
                    [y_tick, y_line, y_line, y_tick],
                    color="black",
                    linewidth=0.45,
                    clip_on=False,
                )
                ax.text(
                    1.5,
                    y_text,
                    _format_significance_label(p_value),
                    ha="center",
                    va="bottom",
                    fontsize=5,
                )
                cur_low, cur_high = ax.get_ylim()
                ax.set_ylim(cur_low, max(cur_high, y_max + 0.28 * y_span))

        ax.set_xlim(0.55, 2.45)
        ax.set_xticks([1.0, 2.0])
        ax.set_xticklabels([f"First\n{window_minutes:g} mins", f"Last\n{window_minutes:g} mins"], fontsize=5)
        ax.set_ylabel(y_label)
        ax.tick_params(labelsize=5, direction="in", length=1.75)
        ax.spines["top"].set_visible(False)
        ax.spines["right"].set_visible(False)

    fig.tight_layout(w_pad=0.8)
    figure_dir = Path(figure_save_folder)
    figure_dir.mkdir(parents=True, exist_ok=True)
    figure_path = figure_dir / str(save_name)
    fig.savefig(figure_path, dpi=300)
    if show_plot:
        plt.show()
    else:
        plt.close(fig)

    return {
        "figure_path": str(figure_path),
        "comparison_df": comparison_df,
        "paired_df": paired_df,
        "stats_df": stats_df,
        "skipped_animals": skipped_animals,
        "unpaired_animals": unpaired_animals,
        "figure": fig if show_plot else None,
    }


def _compute_plateau_event_count_summary_df(
    config: PipelineConfig,
    df_all,
    *,
    plateau_include_long_cb_as_plateau: bool = False,
    plateau_cb_min_duration_ms: float = 200.0,
    plateau_speed_threshold: float | None = None,
):
    import pandas as pd

    if "session" not in df_all.columns or "cell_idx" not in df_all.columns:
        raise KeyError("df_all must contain 'session' and 'cell_idx' columns.")

    speed_threshold_use = (
        float(config.analysis.speed_threshold)
        if plateau_speed_threshold is None
        else float(plateau_speed_threshold)
    )
    if not np.isfinite(speed_threshold_use) or speed_threshold_use < 0:
        raise ValueError("plateau_speed_threshold must be a finite number >= 0.")

    session_cache: dict[str, dict[str, Any]] = {}
    rows: list[dict[str, Any]] = []

    for row in df_all[["session", "cell_idx"]].itertuples(index=False):
        animal_id = str(row.session)
        cell_idx = int(row.cell_idx)

        cache = session_cache.get(animal_id)
        if cache is None:
            merged = _load_merged_data(config.data_root / animal_id, config)
            x_neural = np.asarray(merged["x_neural"], dtype=float).reshape(-1)
            y_neural = np.asarray(
                merged.get("y_neural", np.full_like(x_neural, np.nan)),
                dtype=float,
            ).reshape(-1)
            speed = np.asarray(
                merged.get("speed", np.full_like(x_neural, np.nan)),
                dtype=float,
            ).reshape(-1)
            frame_rate = float(merged.get("frame_rate", np.nan))
            if (not np.isfinite(frame_rate)) or frame_rate <= 0:
                raise ValueError(f"{animal_id}: merged_data frame_rate must be a finite number > 0.")

            n_frames = int(min(x_neural.size, y_neural.size, speed.size))
            x_neural = x_neural[:n_frames]
            y_neural = y_neural[:n_frames]
            speed = speed[:n_frames]
            speed_clean = np.asarray(speed, dtype=float).copy()
            speed_clean[speed_clean > 60.0] = np.nan
            valid_frames_global = np.isfinite(x_neural) & np.isfinite(y_neural) & np.isfinite(speed_clean)
            bad_masks = np.asarray(
                _compute_bad_masks(
                    merged,
                    config.analysis.snr_threshold,
                    config.analysis.min_good_minutes,
                ),
                dtype=bool,
            )

            cache = {
                "merged": merged,
                "frame_rate": frame_rate,
                "n_frames": n_frames,
                "speed_clean": speed_clean,
                "valid_frames_global": valid_frames_global,
                "bad_masks": bad_masks,
                "moving_masks": {},
                "plateau_counts": {},
            }
            session_cache[animal_id] = cache

        plateau_counts = cache["plateau_counts"]
        if cell_idx not in plateau_counts:
            n_frames = int(cache["n_frames"])
            bad_masks = np.asarray(cache["bad_masks"], dtype=bool)
            if bad_masks.ndim == 2 and cell_idx < bad_masks.shape[0] and bad_masks.shape[1] == n_frames:
                bad_mask = bad_masks[cell_idx]
            else:
                bad_mask = np.zeros(n_frames, dtype=bool)
            valid_frames_cell = np.asarray(cache["valid_frames_global"], dtype=bool) & (~bad_mask)

            moving_masks = cache["moving_masks"]
            moving_mask_cell = moving_masks.get(cell_idx)
            if moving_mask_cell is None:
                speed_for_epochs = np.asarray(cache["speed_clean"], dtype=float).copy()
                speed_for_epochs[~valid_frames_cell] = np.nan
                _, _, moving_idx_cell = core._compute_moving_epochs(
                    speed_for_epochs,
                    float(cache["frame_rate"]),
                    kernel_size=int(config.analysis.kernel_size),
                    filter_type="boxcar",
                    speed_threshold=speed_threshold_use,
                    min_duration_s=float(config.analysis.min_duration_s),
                    merge_gap_s=float(config.analysis.merge_gap_s),
                )
                moving_mask_cell = np.zeros(n_frames, dtype=bool)
                if len(moving_idx_cell) > 0:
                    moving_mask_cell[np.asarray(moving_idx_cell, dtype=int)] = True
                moving_mask_cell &= valid_frames_cell
                moving_masks[cell_idx] = moving_mask_cell

            plateau_starts, _ = _build_plateau_intervals_for_cell(
                cell_idx=cell_idx,
                plateaus_dicts=cache["merged"].get("plateaus_dicts"),
                complex_bursts_dicts=cache["merged"].get("complex_bursts_dicts"),
                include_long_cb_as_plateau=bool(plateau_include_long_cb_as_plateau),
                cb_plateau_min_duration_ms=float(plateau_cb_min_duration_ms),
                frame_rate=float(cache["frame_rate"]),
                n_frames=n_frames,
            )
            plateau_starts = np.asarray(plateau_starts, dtype=int)
            plateau_starts = plateau_starts[(plateau_starts >= 0) & (plateau_starts < n_frames)]
            plateau_starts = plateau_starts[valid_frames_cell[plateau_starts]]

            n_loco = int(np.sum(moving_mask_cell[plateau_starts])) if plateau_starts.size > 0 else 0
            n_quiet = int(plateau_starts.size - n_loco)
            plateau_counts[cell_idx] = (n_loco, n_quiet)

        n_loco, n_quiet = plateau_counts[cell_idx]
        rows.append(
            {
                "session": animal_id,
                "cell_idx": cell_idx,
                "plateau_event_count_loco": int(n_loco),
                "plateau_event_count_quiet": int(n_quiet),
            }
        )

    return pd.DataFrame(rows)


def _compute_complex_burst_event_summary_df(
    config: PipelineConfig,
    df_all,
    *,
    speed_threshold: float | None = None,
):
    import pandas as pd

    if "session" not in df_all.columns or "cell_idx" not in df_all.columns:
        raise KeyError("df_all must contain 'session' and 'cell_idx' columns.")

    speed_threshold_use = (
        float(config.analysis.speed_threshold)
        if speed_threshold is None
        else float(speed_threshold)
    )
    if not np.isfinite(speed_threshold_use) or speed_threshold_use < 0:
        raise ValueError("speed_threshold must be a finite number >= 0.")

    session_cache: dict[str, dict[str, Any]] = {}
    rows: list[dict[str, Any]] = []

    for row in df_all[["session", "cell_idx"]].itertuples(index=False):
        animal_id = str(row.session)
        cell_idx = int(row.cell_idx)

        cache = session_cache.get(animal_id)
        if cache is None:
            merged = _load_merged_data(config.data_root / animal_id, config)
            x_neural = np.asarray(merged["x_neural"], dtype=float).reshape(-1)
            y_neural = np.asarray(
                merged.get("y_neural", np.full_like(x_neural, np.nan)),
                dtype=float,
            ).reshape(-1)
            speed = np.asarray(
                merged.get("speed", np.full_like(x_neural, np.nan)),
                dtype=float,
            ).reshape(-1)
            frame_rate = float(merged.get("frame_rate", np.nan))
            if (not np.isfinite(frame_rate)) or frame_rate <= 0:
                raise ValueError(f"{animal_id}: merged_data frame_rate must be a finite number > 0.")

            n_frames = int(min(x_neural.size, y_neural.size, speed.size))
            x_neural = x_neural[:n_frames]
            y_neural = y_neural[:n_frames]
            speed = speed[:n_frames]
            speed_clean = np.asarray(speed, dtype=float).copy()
            speed_clean[speed_clean > 60.0] = np.nan
            valid_frames_global = np.isfinite(x_neural) & np.isfinite(y_neural) & np.isfinite(speed_clean)
            bad_masks = np.asarray(
                _compute_bad_masks(
                    merged,
                    config.analysis.snr_threshold,
                    config.analysis.min_good_minutes,
                ),
                dtype=bool,
            )

            cache = {
                "merged": merged,
                "frame_rate": frame_rate,
                "n_frames": n_frames,
                "speed_clean": speed_clean,
                "valid_frames_global": valid_frames_global,
                "bad_masks": bad_masks,
                "moving_masks": {},
                "burst_summary": {},
            }
            session_cache[animal_id] = cache

        burst_summary = cache["burst_summary"]
        if cell_idx not in burst_summary:
            n_frames = int(cache["n_frames"])
            bad_masks = np.asarray(cache["bad_masks"], dtype=bool)
            if bad_masks.ndim == 2 and cell_idx < bad_masks.shape[0] and bad_masks.shape[1] == n_frames:
                bad_mask = bad_masks[cell_idx]
            else:
                bad_mask = np.zeros(n_frames, dtype=bool)
            valid_frames_cell = np.asarray(cache["valid_frames_global"], dtype=bool) & (~bad_mask)

            moving_masks = cache["moving_masks"]
            moving_mask_cell = moving_masks.get(cell_idx)
            if moving_mask_cell is None:
                speed_for_epochs = np.asarray(cache["speed_clean"], dtype=float).copy()
                speed_for_epochs[~valid_frames_cell] = np.nan
                _, _, moving_idx_cell = core._compute_moving_epochs(
                    speed_for_epochs,
                    float(cache["frame_rate"]),
                    kernel_size=int(config.analysis.kernel_size),
                    filter_type="boxcar",
                    speed_threshold=speed_threshold_use,
                    min_duration_s=float(config.analysis.min_duration_s),
                    merge_gap_s=float(config.analysis.merge_gap_s),
                )
                moving_mask_cell = np.zeros(n_frames, dtype=bool)
                if len(moving_idx_cell) > 0:
                    moving_mask_cell[np.asarray(moving_idx_cell, dtype=int)] = True
                moving_mask_cell &= valid_frames_cell
                moving_masks[cell_idx] = moving_mask_cell

            quiet_mask_cell = valid_frames_cell & (~moving_mask_cell)
            loco_time_s = float(np.sum(moving_mask_cell) / float(cache["frame_rate"]))
            quiet_time_s = float(np.sum(quiet_mask_cell) / float(cache["frame_rate"]))

            cb_entry = None
            complex_bursts_dicts = cache["merged"].get("complex_bursts_dicts", [])
            if isinstance(complex_bursts_dicts, (list, tuple)) and cell_idx < len(complex_bursts_dicts):
                cb_entry = complex_bursts_dicts[cell_idx]
            elif isinstance(complex_bursts_dicts, dict):
                cb_entry = complex_bursts_dicts

            cb_starts = np.array([], dtype=int)
            if isinstance(cb_entry, dict):
                cb_starts = np.asarray(cb_entry.get("starts", []), dtype=int).reshape(-1)
            cb_starts = cb_starts[(cb_starts >= 0) & (cb_starts < n_frames)]
            cb_starts = cb_starts[valid_frames_cell[cb_starts]]

            n_loco = int(np.sum(moving_mask_cell[cb_starts])) if cb_starts.size > 0 else 0
            n_quiet = int(cb_starts.size - n_loco)
            burst_summary[cell_idx] = {
                "complex_burst_event_count_loco": n_loco,
                "complex_burst_event_count_quiet": n_quiet,
                "complex_burst_event_rate_loco": (float(n_loco) / loco_time_s) if loco_time_s > 0 else np.nan,
                "complex_burst_event_rate_quiet": (float(n_quiet) / quiet_time_s) if quiet_time_s > 0 else np.nan,
            }

        row_payload = dict(burst_summary[cell_idx])
        row_payload["session"] = animal_id
        row_payload["cell_idx"] = cell_idx
        rows.append(row_payload)

    return pd.DataFrame(rows)


def plot_state_dependent_firing_rates_with_plateau_count(
    config: PipelineConfig,
    pooled_stats: Any,
    figure_save_folder: str | Path,
    *,
    plateau_include_long_cb_as_plateau: bool = False,
    plateau_cb_min_duration_ms: float = 200.0,
    plateau_speed_threshold: float | None = None,
    rate_ylim_max: float = 6.0,
    plateau_zoom_ylim_max: float = 10.0,
    figsize: tuple[float, float] = (4.8, 1.0),
    save_name: str = "StateDep_FiringRates_AllCells_WithPlateauCount.svg",
    show_plot: bool = True,
) -> dict[str, Any]:
    import pandas as pd
    from utils.pooled_figures_core import (
        _global_ylim as pooled_global_ylim,
        _paired_test as pooled_paired_test,
        _sig_label as pooled_sig_label,
        _style_violin_medians as pooled_style_violin_medians,
    )

    df_all = getattr(pooled_stats, "df_all", pooled_stats)
    if not isinstance(df_all, pd.DataFrame):
        raise TypeError("pooled_stats must be a PooledStatsData object or a pandas DataFrame.")

    plateau_df = _compute_plateau_event_count_summary_df(
        config,
        df_all,
        plateau_include_long_cb_as_plateau=plateau_include_long_cb_as_plateau,
        plateau_cb_min_duration_ms=plateau_cb_min_duration_ms,
        plateau_speed_threshold=plateau_speed_threshold,
    )
    complex_burst_df = _compute_complex_burst_event_summary_df(
        config,
        df_all,
        speed_threshold=plateau_speed_threshold,
    )
    summary_df = df_all.copy().merge(
        plateau_df,
        on=["session", "cell_idx"],
        how="left",
        validate="one_to_one",
    ).merge(
        complex_burst_df,
        on=["session", "cell_idx"],
        how="left",
        validate="one_to_one",
    )
    summary_df["plateau_event_count_loco"] = pd.to_numeric(
        summary_df["plateau_event_count_loco"],
        errors="coerce",
    ).fillna(0.0)
    summary_df["plateau_event_count_quiet"] = pd.to_numeric(
        summary_df["plateau_event_count_quiet"],
        errors="coerce",
    ).fillna(0.0)

    if len(tuple(figsize)) != 2:
        raise ValueError("figsize must be a 2-tuple: (width, height).")
    rate_ylim_max = float(rate_ylim_max)
    plateau_zoom_ylim_max = float(plateau_zoom_ylim_max)
    if (not np.isfinite(rate_ylim_max)) or rate_ylim_max <= 0:
        raise ValueError("rate_ylim_max must be a finite number > 0.")
    if (not np.isfinite(plateau_zoom_ylim_max)) or plateau_zoom_ylim_max <= 0:
        raise ValueError("plateau_zoom_ylim_max must be a finite number > 0.")

    fig, axes = plt.subplots(1, 6, figsize=tuple(float(v) for v in figsize), sharex=True)
    axes = np.atleast_1d(axes)
    axes[1].sharey(axes[0])
    axes[2].sharey(axes[0])
    run_color = "#f9e800ff"
    rest_color = "#563c25"
    rate_specs = [
        ("all", axes[0]),
        ("ss", axes[1]),
        ("cs", axes[2]),
    ]
    rate_ylim = (0.0, rate_ylim_max)

    stats_results: list[dict[str, Any]] = []
    subplot_counts: dict[str, int] = {}

    def _plot_split_half_violin_pair(
        ax,
        vals_loco: np.ndarray,
        vals_quiet: np.ndarray,
        *,
        sig_label: str = "",
        ylim: tuple[float, float] | None = None,
    ) -> None:
        vals_loco = np.asarray(vals_loco, dtype=float)
        vals_quiet = np.asarray(vals_quiet, dtype=float)
        plot_specs = [
            (1.0, vals_loco, run_color, "left"),
            (2.0, vals_quiet, rest_color, "right"),
        ]
        rng = np.random.default_rng(0)

        for pos, vals, color, side in plot_specs:
            finite_vals = vals[np.isfinite(vals)]
            if finite_vals.size >= 2:
                parts = ax.violinplot(
                    [finite_vals],
                    positions=[pos],
                    showmedians=True,
                    showextrema=False,
                )
                body = parts["bodies"][0]
                verts = body.get_paths()[0].vertices
                if side == "left":
                    verts[:, 0] = np.clip(verts[:, 0], -np.inf, pos)
                else:
                    verts[:, 0] = np.clip(verts[:, 0], pos, np.inf)
                body.set_facecolor(color)
                body.set_edgecolor("none")
                body.set_alpha(0.3)
                body.set_zorder(1)
                if "cmedians" in parts:
                    clipped_segments = []
                    for seg in parts["cmedians"].get_segments():
                        seg = np.asarray(seg, dtype=float).copy()
                        if side == "left":
                            seg[:, 0] = np.clip(seg[:, 0], -np.inf, pos)
                        else:
                            seg[:, 0] = np.clip(seg[:, 0], pos, np.inf)
                        clipped_segments.append(seg)
                    parts["cmedians"].set_segments(clipped_segments)
                pooled_style_violin_medians(parts)

            if finite_vals.size > 0:
                scatter_offsets = 0.05 + rng.random(finite_vals.size) * 0.12
                if side == "left":
                    scatter_x = pos + scatter_offsets
                else:
                    scatter_x = pos - scatter_offsets
                ax.scatter(
                    scatter_x,
                    finite_vals,
                    s=5,
                    color="black",
                    alpha=0.6,
                    linewidths=0,
                    zorder=3,
                )

        n_pairs = min(len(vals_loco), len(vals_quiet))
        for i in range(n_pairs):
            if np.isfinite(vals_loco[i]) and np.isfinite(vals_quiet[i]):
                ax.plot(
                    [1.12, 1.88],
                    [vals_loco[i], vals_quiet[i]],
                    color="black",
                    alpha=0.3,
                    linewidth=0.6,
                    zorder=2,
                )

        if ylim is not None:
            ax.set_ylim(*ylim)
            if sig_label:
                ax.text(
                    1.5,
                    ylim[1] - 0.05 * (ylim[1] - ylim[0]),
                    sig_label,
                    ha="center",
                    va="bottom",
                    fontsize=6,
                )
        elif sig_label:
            ax.text(
                1.5,
                0.99,
                sig_label,
                ha="center",
                va="top",
                fontsize=6,
                transform=ax.get_xaxis_transform(),
            )

        ax.set_xticks([1, 2])
        ax.set_xticklabels(["Loco.", "Quiet"], fontsize=5)
        ax.set_xlim(0.5, 2.5)
        ax.spines["top"].set_visible(False)
        ax.spines["right"].set_visible(False)

    for spike_type, ax in rate_specs:
        data_loco_all = summary_df[f"{spike_type}_rate_loco"].to_numpy(dtype=float)
        data_quiet_all = summary_df[f"{spike_type}_rate_quiet"].to_numpy(dtype=float)
        pair_mask = np.isfinite(data_loco_all) & np.isfinite(data_quiet_all)
        if spike_type == "cs":
            pair_mask &= ((data_loco_all != 0) | (data_quiet_all != 0))
        data_loco = data_loco_all[pair_mask]
        data_quiet = data_quiet_all[pair_mask]
        subplot_counts[f"{spike_type}_rate"] = int(len(data_loco))

        p_val, test_stat, test_name, n_valid, shapiro_p = pooled_paired_test(data_loco, data_quiet)
        sig = pooled_sig_label(p_val)
        _plot_split_half_violin_pair(ax, data_loco, data_quiet, sig_label=sig, ylim=rate_ylim)
        stats_results.append(
            {
                "metric": f"{spike_type}_rate",
                "n_cells": int(n_valid),
                "test": test_name,
                "p_value": float(p_val) if np.isfinite(p_val) else np.nan,
                "loco_mean": float(np.nanmean(data_loco)) if data_loco.size > 0 else np.nan,
                "loco_std": float(np.nanstd(data_loco)) if data_loco.size > 0 else np.nan,
                "quiet_mean": float(np.nanmean(data_quiet)) if data_quiet.size > 0 else np.nan,
                "quiet_std": float(np.nanstd(data_quiet)) if data_quiet.size > 0 else np.nan,
                "test_stat": float(test_stat) if np.isfinite(test_stat) else np.nan,
                "shapiro_p": float(shapiro_p) if np.isfinite(shapiro_p) else np.nan,
            }
        )

        ax.set_ylabel("Rate (Hz)" if ax == axes[0] else "", fontsize=6)
        if ax != axes[0]:
            ax.tick_params(left=False, labelleft=False)

    cb_rate_ax = axes[3]
    cb_rate_loco = summary_df["complex_burst_event_rate_loco"].to_numpy(dtype=float)
    cb_rate_quiet = summary_df["complex_burst_event_rate_quiet"].to_numpy(dtype=float)
    cb_count_loco = summary_df["complex_burst_event_count_loco"].to_numpy(dtype=float)
    cb_count_quiet = summary_df["complex_burst_event_count_quiet"].to_numpy(dtype=float)
    cb_pair_mask = np.isfinite(cb_rate_loco) & np.isfinite(cb_rate_quiet)
    cb_pair_mask &= (
        (np.isfinite(cb_count_loco) & (cb_count_loco > 0))
        | (np.isfinite(cb_count_quiet) & (cb_count_quiet > 0))
    )
    cb_rate_loco = cb_rate_loco[cb_pair_mask]
    cb_rate_quiet = cb_rate_quiet[cb_pair_mask]
    subplot_counts["complex_burst_rate"] = int(len(cb_rate_loco))

    p_val, test_stat, test_name, n_valid, shapiro_p = pooled_paired_test(cb_rate_loco, cb_rate_quiet)
    sig = pooled_sig_label(p_val)
    cb_rate_ylim = pooled_global_ylim([cb_rate_loco, cb_rate_quiet])
    _plot_split_half_violin_pair(cb_rate_ax, cb_rate_loco, cb_rate_quiet, sig_label=sig, ylim=cb_rate_ylim)

    cb_rate_ax.set_ylabel("CB event rate (Hz)", fontsize=6)

    stats_results.append(
        {
            "metric": "complex_burst_event_rate",
            "n_cells": int(n_valid),
            "test": test_name,
            "p_value": float(p_val) if np.isfinite(p_val) else np.nan,
            "loco_mean": float(np.nanmean(cb_rate_loco)) if cb_rate_loco.size > 0 else np.nan,
            "loco_std": float(np.nanstd(cb_rate_loco)) if cb_rate_loco.size > 0 else np.nan,
            "quiet_mean": float(np.nanmean(cb_rate_quiet)) if cb_rate_quiet.size > 0 else np.nan,
            "quiet_std": float(np.nanstd(cb_rate_quiet)) if cb_rate_quiet.size > 0 else np.nan,
            "test_stat": float(test_stat) if np.isfinite(test_stat) else np.nan,
            "shapiro_p": float(shapiro_p) if np.isfinite(shapiro_p) else np.nan,
        }
    )

    plateau_ax = axes[4]
    plateau_zoom_ax = axes[5]
    plateau_loco_all = summary_df["plateau_event_count_loco"].to_numpy(dtype=float)
    plateau_quiet_all = summary_df["plateau_event_count_quiet"].to_numpy(dtype=float)
    plateau_pair_mask = (
        np.isfinite(plateau_loco_all)
        & np.isfinite(plateau_quiet_all)
        & ((plateau_loco_all > 0) | (plateau_quiet_all > 0))
    )
    plateau_loco = plateau_loco_all[plateau_pair_mask]
    plateau_quiet = plateau_quiet_all[plateau_pair_mask]
    subplot_counts["plateau"] = int(len(plateau_loco))
    subplot_counts["plateau_zoom"] = int(len(plateau_loco))
    p_val, test_stat, test_name, n_valid, shapiro_p = pooled_paired_test(plateau_loco, plateau_quiet)
    sig = pooled_sig_label(p_val)
    plateau_ylim = pooled_global_ylim([plateau_loco, plateau_quiet])

    def _plot_plateau_panel(
        ax,
        *,
        ylim_override: tuple[float, float] | None = None,
        hide_yticks: bool = False,
        custom_yticks: list[float] | tuple[float, ...] | None = None,
    ):
        ylim_use = ylim_override if ylim_override is not None else plateau_ylim
        _plot_split_half_violin_pair(ax, plateau_loco, plateau_quiet, sig_label=sig, ylim=ylim_use)
        ax.set_ylabel("Plateau event #" if not hide_yticks else "", fontsize=6)
        if hide_yticks:
            ax.set_yticks([])
        elif custom_yticks is not None:
            ax.set_yticks(list(custom_yticks))

    _plot_plateau_panel(plateau_ax)
    _plot_plateau_panel(
        plateau_zoom_ax,
        ylim_override=(0.0, plateau_zoom_ylim_max),
        hide_yticks=False,
        custom_yticks=(0.0, 5.0),
    )

    stats_results.append(
        {
            "metric": "plateau_event_count",
            "n_cells": int(n_valid),
            "test": test_name,
            "p_value": float(p_val) if np.isfinite(p_val) else np.nan,
            "loco_mean": float(np.nanmean(plateau_loco)) if plateau_loco.size > 0 else np.nan,
            "loco_std": float(np.nanstd(plateau_loco)) if plateau_loco.size > 0 else np.nan,
            "quiet_mean": float(np.nanmean(plateau_quiet)) if plateau_quiet.size > 0 else np.nan,
            "quiet_std": float(np.nanstd(plateau_quiet)) if plateau_quiet.size > 0 else np.nan,
            "test_stat": float(test_stat) if np.isfinite(test_stat) else np.nan,
            "shapiro_p": float(shapiro_p) if np.isfinite(shapiro_p) else np.nan,
        }
    )

    fig.tight_layout()
    figure_dir = Path(figure_save_folder)
    figure_dir.mkdir(parents=True, exist_ok=True)
    figure_path = figure_dir / str(save_name)
    fig.savefig(figure_path, dpi=300)
    if show_plot:
        plt.show()
    else:
        plt.close(fig)

    return {
        "figure_path": str(figure_path),
        "summary_df": summary_df,
        "subplot_counts": subplot_counts,
        "plateau_pair_mask": plateau_pair_mask,
        "n_plateau_cells_plotted": int(np.sum(plateau_pair_mask)),
        "stats_results": pd.DataFrame(stats_results),
        "figure": fig if show_plot else None,
        "rate_ylim_max": rate_ylim_max,
        "plateau_zoom_ylim_max": plateau_zoom_ylim_max,
    }


# -----------------------------------------------------------------------------
# Deduplicated utility functions used across pooled figure statistics
# -----------------------------------------------------------------------------

def paired_test_auto(vals_in: np.ndarray, vals_out: np.ndarray) -> tuple[float, float, str, int, float]:
    vals_in = np.asarray(vals_in, dtype=float)
    vals_out = np.asarray(vals_out, dtype=float)
    n_pairs = min(len(vals_in), len(vals_out))
    if n_pairs == 0:
        return np.nan, np.nan, "n/a", 0, np.nan
    paired_in = vals_in[:n_pairs]
    paired_out = vals_out[:n_pairs]
    valid = np.isfinite(paired_in) & np.isfinite(paired_out)
    n_valid = int(np.sum(valid))
    if n_valid < 3:
        return np.nan, np.nan, "n/a", n_valid, np.nan

    diffs = paired_in[valid] - paired_out[valid]
    try:
        shapiro_p = scipy_stats.shapiro(diffs).pvalue
    except ValueError:
        shapiro_p = np.nan

    if np.isfinite(shapiro_p) and shapiro_p >= 0.05:
        res = scipy_stats.ttest_rel(paired_in[valid], paired_out[valid], nan_policy="omit")
        return float(res.pvalue), float(res.statistic), "paired t-test", n_valid, float(shapiro_p)

    try:
        res = scipy_stats.wilcoxon(paired_in[valid], paired_out[valid])
        return float(res.pvalue), float(res.statistic), "wilcoxon", n_valid, float(shapiro_p)
    except ValueError:
        return np.nan, np.nan, "wilcoxon", n_valid, float(shapiro_p)


def unpaired_test_auto(vals_a: np.ndarray, vals_b: np.ndarray) -> tuple[float, float, str, int, int]:
    a = np.asarray(vals_a, dtype=float)
    b = np.asarray(vals_b, dtype=float)
    a = a[np.isfinite(a)]
    b = b[np.isfinite(b)]
    na, nb = len(a), len(b)
    if min(na, nb) < 3:
        return np.nan, np.nan, "n/a", na, nb

    try:
        pa = scipy_stats.shapiro(a).pvalue
        pb = scipy_stats.shapiro(b).pvalue
    except ValueError:
        pa, pb = np.nan, np.nan

    if np.isfinite(pa) and np.isfinite(pb) and pa >= 0.05 and pb >= 0.05:
        res = scipy_stats.ttest_ind(a, b, equal_var=False, nan_policy="omit")
        return float(res.pvalue), float(res.statistic), "welch t-test", na, nb

    res = scipy_stats.mannwhitneyu(a, b, alternative="two-sided")
    return float(res.pvalue), float(res.statistic), "mann-whitney", na, nb


def one_sample_test_auto(vals: np.ndarray, mu: float = 0.0) -> tuple[float, float, str, int]:
    x = np.asarray(vals, dtype=float)
    x = x[np.isfinite(x)]
    n = len(x)
    if n < 3:
        return np.nan, np.nan, "n/a", n

    try:
        pnorm = scipy_stats.shapiro(x).pvalue
    except ValueError:
        pnorm = np.nan

    if np.isfinite(pnorm) and pnorm >= 0.05:
        res = scipy_stats.ttest_1samp(x, popmean=mu, nan_policy="omit")
        return float(res.pvalue), float(res.statistic), "one-sample t-test", n

    res = scipy_stats.wilcoxon(x - mu)
    return float(res.pvalue), float(res.statistic), "wilcoxon", n


def sig_label(p_val: float) -> str:
    if not np.isfinite(p_val):
        return ""
    if p_val < 0.001:
        return "***"
    if p_val < 0.01:
        return "**"
    if p_val < 0.05:
        return "*"
    return "n.s."


def sig_stars(p_val: float) -> str:
    if not np.isfinite(p_val):
        return ""
    if p_val < 0.001:
        return "***"
    if p_val < 0.01:
        return "**"
    if p_val < 0.05:
        return "*"
    return ""


def global_ylim(arrays: list[np.ndarray], pad_frac: float = 0.1) -> tuple[float, float] | None:
    vals = []
    for arr in arrays:
        arr = np.asarray(arr, dtype=float)
        finite = arr[np.isfinite(arr)]
        if finite.size:
            vals.append(finite)
    if not vals:
        return None
    merged = np.concatenate(vals)
    lo = float(np.nanmin(merged))
    hi = float(np.nanmax(merged))
    if not np.isfinite(lo) or not np.isfinite(hi):
        return None
    if hi == lo:
        span = abs(hi) if hi != 0 else 1.0
        return lo - pad_frac * span, hi + pad_frac * span
    span = hi - lo
    return lo - pad_frac * span, hi + pad_frac * span


def confidence_interval(x: np.ndarray, alpha: float = 0.05) -> tuple[float, float]:
    vals = np.asarray(x, dtype=float)
    vals = vals[np.isfinite(vals)]
    n = len(vals)
    if n < 2:
        return np.nan, np.nan
    mean = float(np.mean(vals))
    sem = float(np.std(vals, ddof=1) / math.sqrt(n))
    tcrit = float(scipy_stats.t.ppf(1 - alpha / 2, n - 1))
    return mean - tcrit * sem, mean + tcrit * sem


# -----------------------------------------------------------------------------
# Notebook helper functions moved from Figures.ipynb
# -----------------------------------------------------------------------------

def _paired_test(vals_a: np.ndarray, vals_b: np.ndarray) -> tuple[float, float, str, int, float]:
    return paired_test_auto(vals_a, vals_b)


def _sig_label(p_val: float) -> str:
    return sig_label(p_val)


def _global_ylim_from_vals(vals_in_raw: np.ndarray, vals_out_raw: np.ndarray, pad_frac: float = 0.1) -> tuple[float, float] | None:
    return global_ylim([vals_in_raw, vals_out_raw], pad_frac=pad_frac)


def _global_ylim(vals_in_raw: np.ndarray, vals_out_raw: np.ndarray, pad_frac: float = 0.1) -> tuple[float, float] | None:
    return global_ylim([vals_in_raw, vals_out_raw], pad_frac=pad_frac)


def _get_spike_positions_on_traj(spike_times, moving_idx, x_traj, y_traj, n_frames):
    """Get x, y positions of spikes during locomotion."""
    if spike_times is None or len(spike_times) == 0:
        return np.array([]), np.array([])
    spike_times = np.asarray(spike_times, dtype=int)
    spike_times = spike_times[(spike_times >= 0) & (spike_times < n_frames)]
    binary_full = np.zeros(n_frames, dtype=bool)
    binary_full[spike_times] = True
    binary_sub = binary_full[moving_idx]
    spikes_in_sub_idx = np.where(binary_sub)[0]
    if len(spikes_in_sub_idx) == 0:
        return np.array([]), np.array([])
    return x_traj[spikes_in_sub_idx], y_traj[spikes_in_sub_idx]


# Function moved from Figures.ipynb (cell 33)
def compute_pf_centered_trial_data(
    cell_idx, 
    PC_output_all, 
    traces, 
    vms,
    x_neural, 
    y_neural, 
    speed, 
    spikes,
    all_spikes, 
    refined_SS, 
    all_CS_spikes, 
    frame_rate,
    pf_center_window_sec,
    theta_freqs,
    slow_freqs,
    speed_threshold,
    min_duration_ms,
    place_field_threshold,
    min_distance_cm,
    clear_traversal,
    session_start_frames,
    session_indices,
    bad_masks,
    center_by_pf_position=False,
    firing_rate_bin_ms=100,
    firing_rate_smooth_ms=50,
    min_traversals=10,
    subtract_pre_traversal_baseline=True,
    mask_non_traversal_pf=False,
    max_pf_distance_cm=None,
    pf_component_selection='peak_rate',
    complex_bursts_dicts=None,
    plateaus_dicts=None,
    plateau_min_duration_ms=100,
    analysis_override=None,
):
    """
    Compute all PF-centered trial-by-trial data for a single cell.
    
    This function handles:
    - Centering by max firing rate OR by PF peak position
    - Separating traversals by direction (All, CW, CCW)
    - Computing firing rates for All spikes, SS, CS
    - Computing theta amplitude and slow Vm
    - Returning both trial stacks and means
    
    Parameters
    ----------
    center_by_pf_position : bool
        If True, center each traversal by the timepoint closest to PF peak position.
        If False, center by the timepoint of maximum firing rate.
        Traversals without spikes are excluded from averaging in both cases.
    mask_non_traversal_pf : bool
        If True, set data to NaN for timepoints when the animal is inside the place field
        but outside the traversal epoch (e.g., resting in PF before/after traversal).
        This ensures only approach, traversal, and departure periods contribute to averages.
    max_pf_distance_cm : float or None
        Maximum allowed distance (cm) from PF peak at closest approach for a trial to be included.
        If None, no distance limit is applied. Only used when center_by_pf_position=True.
    
    Returns
    -------
    dict or None
        Returns None if cell is not a place cell or has insufficient traversals.
        Otherwise returns a dict with structure:
        {
            'cell_idx': int,
            'pf_peak_xy': tuple or None,
            'center_by_pf_position': bool,
            'time_rel': ndarray (T,),
            'all': {  # All traversals
                'n_trials': int,
                'n_total_trials': int,
                'traversal_types': list,
                'theta_stack': ndarray (N, T),
                'slow_stack': ndarray (N, T),
                'rate_stack': ndarray (N, T),
                'ss_rate_stack': ndarray (N, T),
                'cs_rate_stack': ndarray (N, T),
                'ss_pct_stack': ndarray (N, T),
                'cs_pct_stack': ndarray (N, T),
                'theta_mean': ndarray (T,),
                'slow_mean': ndarray (T,),
                'rate_mean': ndarray (T,),
                'ss_rate_mean': ndarray (T,),
                'cs_rate_mean': ndarray (T,),
                'ss_pct_mean': ndarray (T,),
                'cs_pct_mean': ndarray (T,),
            },
            'cw': { ... same structure ... },
            'ccw': { ... same structure ... },
        }
    """
    if analysis_override is not None:
        analysis = analysis_override
    else:
        if PC_output_all is None:
            raise ValueError("PC_output_all must be provided when analysis_override is None.")
        analysis = PC_output_all[cell_idx]
    if not analysis.get('is_place_cell', False):
        return None
    
    # Preprocess trace
    trace = traces[cell_idx]
    trace = interpolate_nan_segment(trace)
    theta_vm = bandpass_filter(trace, theta_freqs[0], theta_freqs[1], frame_rate, order=5)
    slow_vm = lowpass_filter(trace, slow_freqs, frame_rate, order=5)
    theta_amp = np.abs(signal.hilbert(theta_vm))
    
    # Find place field traversals
    traversal_epochs, place_field_mask, rate_map, pf_bins, traversal_types = find_place_field_traversals(
        x_neural, y_neural, spikes, speed, frame_rate, cell_idx,
        analysis=analysis,
        speed_threshold=speed_threshold,
        min_duration_ms=min_duration_ms,
        place_field_threshold=place_field_threshold,
        min_distance_cm=min_distance_cm,
        max_pf_distance_cm=max_pf_distance_cm,
        clear_traversal=clear_traversal,
        return_traversal_types=True,
        pf_component_selection=pf_component_selection,
        bad_timepoints=bad_masks[cell_idx] if bad_masks is not None else None,
    )
    
    if len(traversal_epochs) < min_traversals:
        return None
    
    # Compute PF peak position
    pf_peak_xy = None
    if place_field_mask is not None and np.any(place_field_mask):
        masked_rate = np.where(place_field_mask, rate_map, np.nan)
        if np.any(np.isfinite(masked_rate)):
            x_centers = (pf_bins[0][:-1] + pf_bins[0][1:]) / 2
            y_centers = (pf_bins[1][:-1] + pf_bins[1][1:]) / 2
            peak_idx = np.nanargmax(masked_rate)
            peak_row, peak_col = np.unravel_index(peak_idx, masked_rate.shape)
            pf_peak_xy = (x_centers[peak_row], y_centers[peak_col])
    
    # Compute in_place_field for each frame (needed for mask_non_traversal_pf)
    in_place_field = None
    if mask_non_traversal_pf and place_field_mask is not None:
        x_bins, y_bins = pf_bins
        x_bin_idx = np.clip(np.digitize(x_neural, x_bins) - 1, 0, place_field_mask.shape[0] - 1)
        y_bin_idx = np.clip(np.digitize(y_neural, y_bins) - 1, 0, place_field_mask.shape[1] - 1)
        in_place_field = place_field_mask[x_bin_idx, y_bin_idx]
    
    # Filter epochs by session
    padding_frames = int(pf_center_window_sec * frame_rate)
    epochs_with_types = list(zip(traversal_epochs, traversal_types))
    
    if session_indices is not None and session_start_frames is not None:
        session_start_frames_arr = np.asarray(session_start_frames, dtype=int)
        session_start_frames_arr = session_start_frames_arr[np.argsort(session_start_frames_arr)]
        epochs_filtered = []
        for (epoch_start, epoch_end), ttype in epochs_with_types:
            session_idx = np.searchsorted(session_start_frames_arr, epoch_start, side="right") - 1
            if session_idx in session_indices:
                epochs_filtered.append(((epoch_start, epoch_end), ttype))
        epochs_with_types = epochs_filtered
    
    # Filter by bad timepoints
    bad_mask = None
    if bad_masks is not None and cell_idx < len(bad_masks):
        bad_mask = np.asarray(bad_masks[cell_idx])
        if bad_mask.dtype != bool:
            if bad_mask.ndim == 1 and bad_mask.size == len(trace):
                bad_mask = bad_mask.astype(bool)
            else:
                bad_indices = np.asarray(bad_mask, dtype=int)
                bad_indices = bad_indices[(bad_indices >= 0) & (bad_indices < len(trace))]
                bad_mask = np.zeros(len(trace), dtype=bool)
                bad_mask[bad_indices] = True
        if bad_mask.shape[0] != len(trace):
            bad_mask = None
    
    valid_epochs = []
    valid_types = []
    for (epoch_start, epoch_end), ttype in epochs_with_types:
        start_idx = epoch_start - padding_frames
        end_idx = epoch_end + padding_frames
        if start_idx < 0 or end_idx >= len(trace):
            continue
        if bad_mask is not None and np.any(bad_mask[start_idx:end_idx]):
            continue
        valid_epochs.append((epoch_start, epoch_end))
        valid_types.append(ttype)
    
    if len(valid_epochs) < min_traversals:
        return None
    
    # Get spike indices
    all_spike_indices = np.asarray(all_spikes[cell_idx], dtype=int)
    ss_indices = np.asarray(refined_SS[cell_idx], dtype=int)
    cs_indices = np.asarray(all_CS_spikes[cell_idx], dtype=int)
    
    # Extract plateau potential bursts
    plateau_starts = np.array([], dtype=int)
    plateau_ends = np.array([], dtype=int)
    if plateaus_dicts is not None and cell_idx < len(plateaus_dicts):
        plat = plateaus_dicts[cell_idx]
        if plat is not None:
            plateau_starts = np.asarray(plat.get('starts', []), dtype=int)
            plateau_ends = np.asarray(plat.get('ends', []), dtype=int)
    elif complex_bursts_dicts is not None and cell_idx < len(complex_bursts_dicts):
        bursts = complex_bursts_dicts[cell_idx]
        cb_starts = np.asarray(bursts.get('starts', []), dtype=int)
        cb_ends = np.asarray(bursts.get('ends', []), dtype=int)
        cb_durs = np.asarray(bursts.get('durations_ms', []), dtype=float)
        plateau_mask = cb_durs >= plateau_min_duration_ms
        plateau_starts = cb_starts[plateau_mask]
        plateau_ends = cb_ends[plateau_mask]
    
    # Compute instantaneous firing rates
    def _compute_ifr(spike_indices):
        if spike_indices is None or len(spike_indices) == 0:
            return None
        spike_indices = spike_indices[(spike_indices >= 0) & (spike_indices < len(trace))]
        if spike_indices.size == 0:
            return None
        spike_train = np.zeros(len(trace), dtype=float)
        spike_train[spike_indices] = 1.0
        bin_frames = max(1, int(round(firing_rate_bin_ms / 1000 * frame_rate)))
        bin_kernel = np.ones(bin_frames, dtype=float) / bin_frames
        ifr = np.convolve(spike_train, bin_kernel, mode="same") * frame_rate
        smooth_frames = max(1, int(round(firing_rate_smooth_ms / 1000 * frame_rate)))
        if smooth_frames > 1:
            smooth_kernel = np.ones(smooth_frames, dtype=float) / smooth_frames
            ifr = np.convolve(ifr, smooth_kernel, mode="same")
        return ifr
    
    ifr_all = _compute_ifr(all_spike_indices)
    ifr_ss = _compute_ifr(ss_indices)
    ifr_cs = _compute_ifr(cs_indices)
    
    # Setup window parameters
    window_frames = int(round(pf_center_window_sec * frame_rate))
    avg_len = window_frames * 2 + 1
    time_rel = np.arange(-window_frames, window_frames + 1) / frame_rate
    
    baseline_start_offset = int(round(2.0 * frame_rate))
    baseline_end_offset = int(round(1.0 * frame_rate))
    session_start_frames_arr = None
    if session_start_frames is not None:
        session_start_frames_arr = np.asarray(session_start_frames, dtype=int)
        session_start_frames_arr = session_start_frames_arr[np.argsort(session_start_frames_arr)]
    
    def _compute_center_indices(epochs, types, direction_filter=None):
        """
        Compute center indices for each trial based on centering method.
        Returns: (center_indices, trials_with_spikes, filtered_epochs, filtered_types)
        """
        # Filter by direction
        if direction_filter is not None:
            filtered = [(ep, tt) for ep, tt in zip(epochs, types) if tt == direction_filter]
            if not filtered:
                return [], [], [], []
            epochs, types = zip(*filtered)
            epochs, types = list(epochs), list(types)
        
        center_indices = []
        trials_with_spikes = []
        
        for epoch_start, epoch_end in epochs:
            # Check if there are spikes in this epoch
            spikes_in_epoch = (all_spike_indices >= epoch_start) & (all_spike_indices < epoch_end)
            has_spikes = np.any(spikes_in_epoch)
            trials_with_spikes.append(has_spikes)
            
            if center_by_pf_position and pf_peak_xy is not None:
                # Center by closest position to PF peak (works even without spikes)
                pf_x, pf_y = pf_peak_xy
                x_epoch = x_neural[epoch_start:epoch_end]
                y_epoch = y_neural[epoch_start:epoch_end]
                dist_sq = (x_epoch - pf_x)**2 + (y_epoch - pf_y)**2
                if len(dist_sq) > 0 and np.any(np.isfinite(dist_sq)):
                    min_dist_sq = np.nanmin(dist_sq)
                    min_dist_cm = np.sqrt(min_dist_sq)
                    # Check if closest point is within allowed distance
                    if max_pf_distance_cm is not None and min_dist_cm > max_pf_distance_cm:
                        center_idx = None
                    else:
                        min_rel_idx = np.nanargmin(dist_sq)
                        center_idx = epoch_start + min_rel_idx
                else:
                    center_idx = None
            else:
                # Center by max firing rate (requires spikes)
                if not has_spikes:
                    center_indices.append(None)
                    continue
                if ifr_all is not None:
                    ifr_segment = ifr_all[epoch_start:epoch_end]
                    if len(ifr_segment) > 0 and np.any(np.isfinite(ifr_segment)):
                        max_rel_idx = np.nanargmax(ifr_segment)
                        center_idx = epoch_start + max_rel_idx
                    else:
                        center_idx = None
                else:
                    center_idx = None
            
            center_indices.append(center_idx)
        
        return center_indices, trials_with_spikes, epochs, types
    
    def _count_spikes_in_epochs(spike_indices, starts, ends):
        """Count spikes in each epoch."""
        if spike_indices is None or len(spike_indices) == 0:
            return np.zeros(len(starts), dtype=int)
        spike_sorted = np.sort(spike_indices)
        left = np.searchsorted(spike_sorted, starts, side="left")
        right = np.searchsorted(spike_sorted, ends, side="left")
        return (right - left).astype(int)
    
    def _build_stacks(epochs, types, center_indices, trials_with_spikes):
        """Build trial stacks, compute means, and trial firing rate data."""
        n_total = len(epochs)
        n_reliable = sum(trials_with_spikes)  # Trials with ≥1 spike in place field
        n_in_stack = sum(1 for i, center_idx in enumerate(center_indices)
                         if center_idx is not None and (center_by_pf_position or trials_with_spikes[i]))
        
        # Compute trial_data for ALL epochs (not just those with spikes)
        epoch_start_frames = np.asarray([s for s, _ in epochs], dtype=int)
        epoch_end_frames = np.asarray([e for _, e in epochs], dtype=int)
        duration_frames = epoch_end_frames - epoch_start_frames
        duration_sec = duration_frames.astype(float) / float(frame_rate)
        epoch_start_sec = epoch_start_frames.astype(float) / float(frame_rate)
        epoch_end_sec = epoch_end_frames.astype(float) / float(frame_rate)
        
        # Count spikes in each epoch
        n_all = _count_spikes_in_epochs(all_spike_indices, epoch_start_frames, epoch_end_frames)
        n_ss = _count_spikes_in_epochs(ss_indices, epoch_start_frames, epoch_end_frames)
        n_cs = _count_spikes_in_epochs(cs_indices, epoch_start_frames, epoch_end_frames)
        
        with np.errstate(divide="ignore", invalid="ignore"):
            fr_all = np.where(duration_sec > 0, n_all / duration_sec, np.nan)
            fr_ss = np.where(duration_sec > 0, n_ss / duration_sec, np.nan)
            fr_cs = np.where(duration_sec > 0, n_cs / duration_sec, np.nan)
        
        trial_data = {
            'epoch_start_sec': epoch_start_sec,
            'epoch_end_sec': epoch_end_sec,
            'duration_sec': duration_sec,
            'n_spikes_all': n_all,
            'n_spikes_ss': n_ss,
            'n_spikes_cs': n_cs,
            'fr_all_hz': fr_all,
            'fr_ss_hz': fr_ss,
            'fr_cs_hz': fr_cs,
            'traversal_types': np.asarray(types, dtype=object),
        }
        
        if n_in_stack == 0:
            empty = np.array([]).reshape(0, avg_len)
            return {
                'n_trials': 0,
                'n_total_trials': n_total,
                'n_reliable_trials': n_reliable,
                'reliability': n_reliable / n_total if n_total > 0 else np.nan,
                'traversal_types': types,
                'trial_data': trial_data,
                'theta_stack': empty, 'slow_stack': empty,
                'rate_stack': empty, 'ss_rate_stack': empty, 'cs_rate_stack': empty,
                'ss_pct_stack': empty, 'cs_pct_stack': empty,
                'plateau_stack': empty,
                'pf_entry_rel': np.array([]),
                'pf_exit_rel': np.array([]),
                'n_plateaus_per_trial': np.array([], dtype=int),
                'theta_mean': np.full(avg_len, np.nan),
                'slow_mean': np.full(avg_len, np.nan),
                'rate_mean': np.full(avg_len, np.nan),
                'ss_rate_mean': np.full(avg_len, np.nan),
                'cs_rate_mean': np.full(avg_len, np.nan),
                'ss_pct_mean': np.full(avg_len, np.nan),
                'cs_pct_mean': np.full(avg_len, np.nan),
            }
        
        theta_stack, slow_stack = [], []
        rate_stack, ss_rate_stack, cs_rate_stack = [], [], []
        ss_pct_stack, cs_pct_stack = [], []
        plateau_stack = []
        pf_entry_rel_list, pf_exit_rel_list = [], []  # Time relative to center when animal enters/exits PF
        
        for i, ((epoch_start, _), center_idx) in enumerate(zip(epochs, center_indices)):
            # Skip if no valid center; for position-based centering, include trials without spikes
            if center_idx is None:
                continue
            if not center_by_pf_position and not trials_with_spikes[i]:
                continue
            
            # Baseline
            base_start = max(epoch_start - baseline_start_offset, 0)
            base_end = max(epoch_start - baseline_end_offset, 0)
            baseline_theta = np.nanmean(theta_amp[base_start:base_end]) if base_end > base_start else np.nan
            baseline_slow = np.nanmean(slow_vm[base_start:base_end]) if base_end > base_start else np.nan
            
            # Window around center
            start_idx = max(center_idx - window_frames, 0)
            end_idx = min(center_idx + window_frames + 1, len(trace))
            if end_idx <= start_idx:
                continue
            
            left_pad = (center_idx - window_frames) - start_idx
            right_pad = (center_idx + window_frames + 1) - end_idx
            write_start = max(0, left_pad)
            write_end = avg_len - max(0, right_pad)
            
            # Initialize trial arrays
            theta_trial = np.full(avg_len, np.nan)
            slow_trial = np.full(avg_len, np.nan)
            rate_trial = np.full(avg_len, np.nan)
            ss_rate_trial = np.full(avg_len, np.nan)
            cs_rate_trial = np.full(avg_len, np.nan)
            ss_pct_trial = np.full(avg_len, np.nan)
            cs_pct_trial = np.full(avg_len, np.nan)
            
            # Theta and slow (baseline subtracted)
            theta_seg = theta_amp[start_idx:end_idx].copy()
            slow_seg = slow_vm[start_idx:end_idx].copy()
            if bool(subtract_pre_traversal_baseline) and np.isfinite(baseline_theta):
                theta_seg = theta_seg - baseline_theta
            if bool(subtract_pre_traversal_baseline) and np.isfinite(baseline_slow):
                slow_seg = slow_seg - baseline_slow
            theta_trial[write_start:write_end] = theta_seg
            slow_trial[write_start:write_end] = slow_seg
            
            # Firing rates
            if ifr_all is not None:
                rate_trial[write_start:write_end] = ifr_all[start_idx:end_idx]
            if ifr_ss is not None:
                ss_rate_trial[write_start:write_end] = ifr_ss[start_idx:end_idx]
            if ifr_cs is not None:
                cs_rate_trial[write_start:write_end] = ifr_cs[start_idx:end_idx]
            
            # SS/CS percentages
            if ifr_ss is not None and ifr_cs is not None:
                ss_seg = ifr_ss[start_idx:end_idx]
                cs_seg = ifr_cs[start_idx:end_idx]
                denom = ss_seg + cs_seg
                valid_denom = np.isfinite(denom) & (denom > 0)
                ss_pct_trial[write_start:write_end] = np.where(valid_denom, 100.0 * ss_seg / denom, np.nan)
                cs_pct_trial[write_start:write_end] = np.where(valid_denom, 100.0 * cs_seg / denom, np.nan)
            
            # Mask non-traversal PF time if requested
            if mask_non_traversal_pf and in_place_field is not None:
                epoch_end_frame = epochs[i][1]
                for j in range(write_start, write_end):
                    frame_idx = start_idx + (j - write_start)
                    # Check if frame is in PF but outside traversal epoch
                    if in_place_field[frame_idx] and not (epoch_start <= frame_idx < epoch_end_frame):
                        theta_trial[j] = np.nan
                        slow_trial[j] = np.nan
                        rate_trial[j] = np.nan
                        ss_rate_trial[j] = np.nan
                        cs_rate_trial[j] = np.nan
                        ss_pct_trial[j] = np.nan
                        cs_pct_trial[j] = np.nan
            
            # Compute PF entry/exit times relative to center
            pf_entry_rel = (epoch_start - center_idx) / frame_rate  # Negative (before center)
            pf_exit_rel = (epochs[i][1] - center_idx) / frame_rate  # Positive (after center)
            pf_entry_rel_list.append(pf_entry_rel)
            pf_exit_rel_list.append(pf_exit_rel)
            
            # Plateau potential trace (baseline-subtracted trace during plateaus >= threshold, zeros elsewhere)
            plateau_trial = np.zeros(avg_len)
            for ps, pe in zip(plateau_starts, plateau_ends):
                # Check if this plateau overlaps with the trial window [start_idx, end_idx)
                overlap_start = max(ps, start_idx)
                overlap_end = min(pe + 1, end_idx)
                if overlap_start < overlap_end:
                    trial_s = write_start + (overlap_start - start_idx)
                    trial_e = write_start + (overlap_end - start_idx)
                    seg = vms[cell_idx][overlap_start:overlap_end].copy()
                    if bool(subtract_pre_traversal_baseline) and np.isfinite(baseline_slow):
                        seg = seg - baseline_slow
                    plateau_trial[trial_s:trial_e] = seg
            # Apply mask_non_traversal_pf to plateau as well
            if mask_non_traversal_pf and in_place_field is not None:
                epoch_end_frame = epochs[i][1]
                for j in range(write_start, write_end):
                    frame_idx = start_idx + (j - write_start)
                    if in_place_field[frame_idx] and not (epoch_start <= frame_idx < epoch_end_frame):
                        plateau_trial[j] = 0.0
            plateau_stack.append(plateau_trial)
            
            theta_stack.append(theta_trial)
            slow_stack.append(slow_trial)
            rate_stack.append(rate_trial)
            ss_rate_stack.append(ss_rate_trial)
            cs_rate_stack.append(cs_rate_trial)
            ss_pct_stack.append(ss_pct_trial)
            cs_pct_stack.append(cs_pct_trial)
        
        # Convert to arrays and compute means
        theta_arr = np.array(theta_stack)
        slow_arr = np.array(slow_stack)
        rate_arr = np.array(rate_stack)
        ss_rate_arr = np.array(ss_rate_stack)
        cs_rate_arr = np.array(cs_rate_stack)
        ss_pct_arr = np.array(ss_pct_stack)
        cs_pct_arr = np.array(cs_pct_stack)
        plateau_arr = np.array(plateau_stack)
        
        return {
            'n_trials': len(theta_stack),
            'n_total_trials': n_total,
            'n_reliable_trials': n_reliable,
            'reliability': n_reliable / n_total if n_total > 0 else np.nan,
            'traversal_types': types,
            'trial_data': trial_data,
            'theta_stack': theta_arr, 'slow_stack': slow_arr,
            'rate_stack': rate_arr, 'ss_rate_stack': ss_rate_arr, 'cs_rate_stack': cs_rate_arr,
            'ss_pct_stack': ss_pct_arr, 'cs_pct_stack': cs_pct_arr,
            'plateau_stack': plateau_arr,
            'pf_entry_rel': np.array(pf_entry_rel_list),  # Time (sec) when animal entered PF, relative to center
            'pf_exit_rel': np.array(pf_exit_rel_list),    # Time (sec) when animal exited PF, relative to center
            'n_plateaus_per_trial': np.array([int(np.any(row != 0)) for row in plateau_arr]) if plateau_arr.size > 0 else np.array([], dtype=int),
            'theta_mean': np.nanmean(theta_arr, axis=0) if theta_arr.size > 0 else np.full(avg_len, np.nan),
            'slow_mean': np.nanmean(slow_arr, axis=0) if slow_arr.size > 0 else np.full(avg_len, np.nan),
            'rate_mean': np.nanmean(rate_arr, axis=0) if rate_arr.size > 0 else np.full(avg_len, np.nan),
            'ss_rate_mean': np.nanmean(ss_rate_arr, axis=0) if ss_rate_arr.size > 0 else np.full(avg_len, np.nan),
            'cs_rate_mean': np.nanmean(cs_rate_arr, axis=0) if cs_rate_arr.size > 0 else np.full(avg_len, np.nan),
            'ss_pct_mean': np.nanmean(ss_pct_arr, axis=0) if ss_pct_arr.size > 0 else np.full(avg_len, np.nan),
            'cs_pct_mean': np.nanmean(cs_pct_arr, axis=0) if cs_pct_arr.size > 0 else np.full(avg_len, np.nan),
        }
    
    # Compute for All, CW, CCW
    center_all, spikes_all, epochs_all, types_all = _compute_center_indices(valid_epochs, valid_types, None)
    center_cw, spikes_cw, epochs_cw, types_cw = _compute_center_indices(valid_epochs, valid_types, 'cw')
    center_ccw, spikes_ccw, epochs_ccw, types_ccw = _compute_center_indices(valid_epochs, valid_types, 'ccw')
    
    result_all = _build_stacks(epochs_all, types_all, center_all, spikes_all)
    result_cw = _build_stacks(epochs_cw, types_cw, center_cw, spikes_cw)
    result_ccw = _build_stacks(epochs_ccw, types_ccw, center_ccw, spikes_ccw)
    
    return {
        'cell_idx': cell_idx,
        'pf_peak_xy': pf_peak_xy,
        'center_by_pf_position': center_by_pf_position,
        'time_rel': time_rel,
        'all': result_all,
        'cw': result_cw,
        'ccw': result_ccw,
    }


def _compute_ifr_from_spike_indices(
    n_frames: int,
    spike_indices: np.ndarray | list[int] | tuple[int, ...] | None,
    frame_rate: float,
    firing_rate_bin_ms: float,
    firing_rate_smooth_ms: float,
) -> np.ndarray | None:
    if spike_indices is None:
        return None
    spike_indices = np.asarray(spike_indices, dtype=int)
    spike_indices = spike_indices[(spike_indices >= 0) & (spike_indices < int(n_frames))]
    if spike_indices.size == 0:
        return None
    spike_train = np.zeros(int(n_frames), dtype=float)
    spike_train[spike_indices] = 1.0
    bin_frames = max(1, int(round(float(firing_rate_bin_ms) / 1000.0 * float(frame_rate))))
    bin_kernel = np.ones(bin_frames, dtype=float) / float(bin_frames)
    ifr = np.convolve(spike_train, bin_kernel, mode="same") * float(frame_rate)
    smooth_frames = max(1, int(round(float(firing_rate_smooth_ms) / 1000.0 * float(frame_rate))))
    if smooth_frames > 1:
        smooth_kernel = np.ones(smooth_frames, dtype=float) / float(smooth_frames)
        ifr = np.convolve(ifr, smooth_kernel, mode="same")
    return ifr


def _resample_trace_to_distance_grid(
    signed_distance: np.ndarray,
    values: np.ndarray,
    distance_rel: np.ndarray,
    *,
    allow_partial: bool = False,
) -> np.ndarray | None:
    x = np.asarray(signed_distance, dtype=float)
    y = np.asarray(values, dtype=float)
    grid = np.asarray(distance_rel, dtype=float)
    valid = np.isfinite(x) & np.isfinite(y)
    if int(np.sum(valid)) < 2:
        return None
    x = x[valid]
    y = y[valid]
    order = np.argsort(x, kind="mergesort")
    x = x[order]
    y = y[order]
    keep = np.ones(x.shape[0], dtype=bool)
    if x.shape[0] > 1:
        keep[1:] = np.diff(x) > 1e-9
    x = x[keep]
    y = y[keep]
    if x.shape[0] < 2:
        return None
    if (not allow_partial) and (grid[0] < x[0] or grid[-1] > x[-1]):
        return None
    out = np.full(grid.shape, np.nan, dtype=float)
    inside = (grid >= x[0]) & (grid <= x[-1])
    if not np.any(inside):
        return None
    out[inside] = np.interp(grid[inside], x, y).astype(float)
    return out


def _build_symmetric_distance_axis(
    distance_window_cm: float,
    distance_bin_cm: float,
) -> tuple[float, float, np.ndarray]:
    """
    Build a symmetric distance axis that always contains 0.

    If requested half-window is not divisible by bin size, expand to the next
    multiple of the bin size (e.g., 15 cm with 2 cm bins -> 16 cm).
    """
    window_req = float(distance_window_cm)
    bin_cm = float(distance_bin_cm)
    if window_req <= 0 or bin_cm <= 0:
        raise ValueError("distance_window_cm and distance_bin_cm must be > 0.")
    n_half_bins = max(1, int(np.ceil(window_req / bin_cm - 1e-12)))
    window_eff = float(n_half_bins) * bin_cm
    distance_rel = np.arange(-n_half_bins, n_half_bins + 1, dtype=float) * bin_cm
    # Avoid tiny floating-point residue at center.
    distance_rel[np.abs(distance_rel) < 1e-12] = 0.0
    return window_req, window_eff, distance_rel


def _normalize_distance_mode(raw: str | None) -> str:
    mode = str(raw if raw is not None else "").strip().lower()
    if mode in {"cumulative_path", "cumulative", "path", "path_length", "travel", "traveled_distance"}:
        return "cumulative_path"
    if mode in {"euclidean_to_peak", "euclidean", "peak", "straight_to_peak"}:
        return "euclidean_to_peak"
    raise ValueError(
        f"Unsupported distance_mode '{raw}'. "
        "Use 'cumulative_path' or 'euclidean_to_peak'."
    )


def _normalize_drz_trial_clip_mode(raw: str | None) -> str:
    mode = str(raw if raw is not None else "").strip().lower()
    if mode in {"pf_entry_exit", "entry_exit", "pf", "place_field", "place_field_entry_exit"}:
        return "pf_entry_exit"
    if mode in {"distance_window", "distance", "window", "full_span"}:
        return "distance_window"
    raise ValueError(
        f"Unsupported trial_clip_mode '{raw}'. "
        "Use 'pf_entry_exit' or 'distance_window'."
    )


def _compute_signed_distance_from_center(
    x_seg: np.ndarray,
    y_seg: np.ndarray,
    *,
    center_local: int,
    pf_peak_xy: tuple[float, float],
    distance_mode: str,
) -> np.ndarray | None:
    x_seg = np.asarray(x_seg, dtype=float)
    y_seg = np.asarray(y_seg, dtype=float)
    if x_seg.size == 0 or y_seg.size == 0 or x_seg.size != y_seg.size:
        return None
    if center_local < 0 or center_local >= int(x_seg.size):
        return None
    if not (np.all(np.isfinite(x_seg)) and np.all(np.isfinite(y_seg))):
        return None

    mode = _normalize_distance_mode(distance_mode)
    if mode == "cumulative_path":
        if x_seg.size == 1:
            return np.array([0.0], dtype=float)
        step_cm = np.sqrt(np.diff(x_seg) ** 2 + np.diff(y_seg) ** 2)
        cumulative_cm = np.concatenate([np.array([0.0], dtype=float), np.cumsum(step_cm, dtype=float)])
        signed_distance = cumulative_cm - float(cumulative_cm[int(center_local)])
        signed_distance[np.abs(signed_distance) < 1e-12] = 0.0
        return signed_distance

    pf_x, pf_y = pf_peak_xy
    signed_distance = np.sqrt((x_seg - float(pf_x)) ** 2 + (y_seg - float(pf_y)) ** 2)
    signed_distance = np.asarray(signed_distance, dtype=float)
    signed_distance[:int(center_local)] *= -1.0
    signed_distance[int(center_local)] = 0.0
    signed_distance[np.abs(signed_distance) < 1e-12] = 0.0
    return signed_distance


def _build_plateau_intervals_for_cell(
    *,
    cell_idx: int,
    plateaus_dicts: list[dict[str, Any] | None] | dict[str, Any] | None,
    complex_bursts_dicts: list[dict[str, Any] | None] | dict[str, Any] | None,
    include_long_cb_as_plateau: bool = True,
    cb_plateau_min_duration_ms: float = 100.0,
    frame_rate: float | None = None,
    n_frames: int | None = None,
) -> tuple[np.ndarray, np.ndarray]:
    """Return merged plateau intervals (inclusive starts/ends) for one cell."""

    def _extract_entry(source: Any, idx: int) -> dict[str, Any] | None:
        if source is None:
            return None
        if isinstance(source, dict):
            return source
        if isinstance(source, (list, tuple)) and 0 <= int(idx) < len(source):
            entry = source[int(idx)]
            return entry if isinstance(entry, dict) else None
        return None

    def _sanitize_intervals(starts: np.ndarray, ends: np.ndarray, n_clip: int | None) -> tuple[np.ndarray, np.ndarray]:
        starts = np.asarray(starts, dtype=int).ravel()
        ends = np.asarray(ends, dtype=int).ravel()
        n = int(min(starts.size, ends.size))
        if n <= 0:
            return np.array([], dtype=int), np.array([], dtype=int)
        starts = starts[:n]
        ends = ends[:n]
        swap = ends < starts
        if np.any(swap):
            s2 = starts.copy()
            starts[swap] = ends[swap]
            ends[swap] = s2[swap]
        if n_clip is not None and int(n_clip) > 0:
            n_clip = int(n_clip)
            starts = np.clip(starts, 0, n_clip - 1)
            ends = np.clip(ends, 0, n_clip - 1)
        valid = np.isfinite(starts) & np.isfinite(ends) & (ends >= starts)
        starts = starts[valid]
        ends = ends[valid]
        if starts.size == 0:
            return np.array([], dtype=int), np.array([], dtype=int)
        order = np.argsort(starts, kind="mergesort")
        return starts[order], ends[order]

    def _merge_intervals(starts: np.ndarray, ends: np.ndarray) -> tuple[np.ndarray, np.ndarray]:
        if starts.size == 0:
            return np.array([], dtype=int), np.array([], dtype=int)
        merged_starts: list[int] = [int(starts[0])]
        merged_ends: list[int] = [int(ends[0])]
        for s, e in zip(starts[1:], ends[1:]):
            s_i = int(s)
            e_i = int(e)
            if s_i <= merged_ends[-1] + 1:
                if e_i > merged_ends[-1]:
                    merged_ends[-1] = e_i
            else:
                merged_starts.append(s_i)
                merged_ends.append(e_i)
        return np.asarray(merged_starts, dtype=int), np.asarray(merged_ends, dtype=int)

    plat_entry = _extract_entry(plateaus_dicts, int(cell_idx))
    p_starts = np.array([], dtype=int)
    p_ends = np.array([], dtype=int)
    if plat_entry is not None:
        p_starts = np.asarray(plat_entry.get("starts", []), dtype=int)
        p_ends = np.asarray(plat_entry.get("ends", []), dtype=int)

    cb_starts = np.array([], dtype=int)
    cb_ends = np.array([], dtype=int)
    if bool(include_long_cb_as_plateau):
        thr_ms = float(cb_plateau_min_duration_ms)
        if (not np.isfinite(thr_ms)) or thr_ms <= 0:
            raise ValueError("cb_plateau_min_duration_ms must be a finite number > 0.")
        cb_entry = _extract_entry(complex_bursts_dicts, int(cell_idx))
        if cb_entry is not None:
            cb_starts_all = np.asarray(cb_entry.get("starts", []), dtype=int).ravel()
            cb_ends_all = np.asarray(cb_entry.get("ends", []), dtype=int).ravel()
            n_cb = int(min(cb_starts_all.size, cb_ends_all.size))
            if n_cb > 0:
                cb_starts_all = cb_starts_all[:n_cb]
                cb_ends_all = cb_ends_all[:n_cb]
                cb_durs = np.asarray(cb_entry.get("durations_ms", []), dtype=float).ravel()
                if cb_durs.size == n_cb:
                    durs_ms = cb_durs
                elif frame_rate is not None and np.isfinite(float(frame_rate)) and float(frame_rate) > 0:
                    durs_ms = (cb_ends_all - cb_starts_all + 1).astype(float) / float(frame_rate) * 1000.0
                else:
                    durs_ms = np.full(n_cb, np.nan, dtype=float)
                keep = np.isfinite(durs_ms) & (durs_ms >= thr_ms)
                cb_starts = cb_starts_all[keep]
                cb_ends = cb_ends_all[keep]

    starts_all = np.concatenate([p_starts, cb_starts]) if (p_starts.size or cb_starts.size) else np.array([], dtype=int)
    ends_all = np.concatenate([p_ends, cb_ends]) if (p_ends.size or cb_ends.size) else np.array([], dtype=int)
    starts_all, ends_all = _sanitize_intervals(starts_all, ends_all, n_frames)
    return _merge_intervals(starts_all, ends_all)


def compute_pf_distance_centered_trial_data(
    cell_idx,
    PC_output_all,
    traces,
    vms,
    x_neural,
    y_neural,
    speed,
    spikes,
    all_spikes,
    refined_SS,
    all_CS_spikes,
    frame_rate,
    distance_window_cm,
    distance_bin_cm,
    theta_freqs,
    slow_freqs,
    speed_threshold,
    min_duration_ms,
    place_field_threshold,
    min_distance_cm,
    clear_traversal,
    session_start_frames,
    session_indices,
    bad_masks,
    center_by_pf_position=True,
    require_movement=True,
    firing_rate_bin_ms=100,
    firing_rate_smooth_ms=50,
    min_traversals=10,
    require_full_span=True,
    subtract_pre_traversal_baseline=True,
    moving_kernel_size=21,
    moving_min_duration_s=None,
    max_pf_distance_cm=None,
    pf_component_selection='peak_rate',
    merge_gap_s=0.0,
    complex_bursts_dicts=None,
    plateaus_dicts=None,
    plateau_min_duration_ms=100,
    analysis_override=None,
    distance_mode="cumulative_path",
):
    """
    Compute PF-centered trial data on a signed distance axis.

    Traversals are detected first, then the displayed epoch is rebuilt around the frame
    closest to the PF peak. If `require_movement=True`, only moving frames are used for
    traversal detection and support epochs; otherwise all valid (non-bad) frames are used.
    The start/end of the displayed epoch are defined by the first support frames on either
    side that reach `distance_window_cm` on the selected distance axis.
    """
    if analysis_override is not None:
        analysis = analysis_override
    else:
        if PC_output_all is None:
            raise ValueError("PC_output_all must be provided when analysis_override is None.")
        analysis = PC_output_all[cell_idx]
    if not analysis.get('is_place_cell', False):
        return None
    distance_mode = _normalize_distance_mode(distance_mode)

    distance_window_cm_req, distance_window_cm_eff, distance_rel = _build_symmetric_distance_axis(
        distance_window_cm,
        distance_bin_cm,
    )
    distance_window_cm = float(distance_window_cm_eff)
    distance_bin_cm = float(distance_bin_cm)
    avg_len = int(distance_rel.size)

    trace = np.asarray(traces[cell_idx], dtype=float)
    trace = interpolate_nan_segment(trace)
    theta_vm = bandpass_filter(trace, theta_freqs[0], theta_freqs[1], frame_rate, order=5)
    slow_vm = lowpass_filter(trace, slow_freqs, frame_rate, order=5)
    theta_amp = np.abs(signal.hilbert(theta_vm))

    traversal_speed_threshold = float(speed_threshold) if bool(require_movement) else -np.inf
    traversal_epochs, place_field_mask, rate_map, pf_bins, traversal_types = find_place_field_traversals(
        x_neural,
        y_neural,
        spikes,
        speed,
        frame_rate,
        cell_idx,
        analysis=analysis,
        speed_threshold=traversal_speed_threshold,
        min_duration_ms=min_duration_ms,
        place_field_threshold=place_field_threshold,
        min_distance_cm=min_distance_cm,
        max_pf_distance_cm=max_pf_distance_cm,
        clear_traversal=clear_traversal,
        return_traversal_types=True,
        pf_component_selection=pf_component_selection,
        merge_gap_s=merge_gap_s,
        bad_timepoints=bad_masks[cell_idx] if bad_masks is not None else None,
    )
    if len(traversal_epochs) < int(min_traversals):
        return None

    pf_peak_xy = _compute_pf_peak_xy_from_mask(place_field_mask, rate_map, pf_bins)
    if pf_peak_xy is None:
        return None
    session_start_frames_arr = None
    if session_start_frames is not None:
        session_start_frames_arr = np.asarray(session_start_frames, dtype=int)
        session_start_frames_arr = session_start_frames_arr[np.argsort(session_start_frames_arr)]

    epochs_with_types = list(zip(traversal_epochs, traversal_types))
    if session_indices is not None and session_start_frames_arr is not None:
        epochs_filtered = []
        for (epoch_start, epoch_end), ttype in epochs_with_types:
            session_idx = np.searchsorted(session_start_frames_arr, epoch_start, side="right") - 1
            if session_idx in session_indices:
                epochs_filtered.append(((epoch_start, epoch_end), ttype))
        epochs_with_types = epochs_filtered

    bad_mask = None
    if bad_masks is not None and cell_idx < len(bad_masks):
        bad_mask = np.asarray(bad_masks[cell_idx])
        if bad_mask.dtype != bool:
            if bad_mask.ndim == 1 and bad_mask.size == len(trace):
                bad_mask = bad_mask.astype(bool)
            else:
                bad_indices = np.asarray(bad_mask, dtype=int)
                bad_indices = bad_indices[(bad_indices >= 0) & (bad_indices < len(trace))]
                bad_mask = np.zeros(len(trace), dtype=bool)
                bad_mask[bad_indices] = True
        if bad_mask.shape[0] != len(trace):
            bad_mask = None

    valid_epochs = []
    valid_types = []
    for (epoch_start, epoch_end), ttype in epochs_with_types:
        if epoch_end <= epoch_start:
            continue
        if bad_mask is not None and np.any(bad_mask[int(epoch_start):int(epoch_end)]):
            continue
        valid_epochs.append((int(epoch_start), int(epoch_end)))
        valid_types.append(ttype)
    if len(valid_epochs) < int(min_traversals):
        return None

    all_spike_indices = np.asarray(all_spikes[cell_idx], dtype=int)
    ss_indices = np.asarray(refined_SS[cell_idx], dtype=int)
    cs_indices = np.asarray(all_CS_spikes[cell_idx], dtype=int)

    plateau_starts = np.array([], dtype=int)
    plateau_ends = np.array([], dtype=int)
    if plateaus_dicts is not None and cell_idx < len(plateaus_dicts):
        plat = plateaus_dicts[cell_idx]
        if plat is not None:
            plateau_starts = np.asarray(plat.get('starts', []), dtype=int)
            plateau_ends = np.asarray(plat.get('ends', []), dtype=int)
    elif complex_bursts_dicts is not None and cell_idx < len(complex_bursts_dicts):
        bursts = complex_bursts_dicts[cell_idx]
        cb_starts = np.asarray(bursts.get('starts', []), dtype=int)
        cb_ends = np.asarray(bursts.get('ends', []), dtype=int)
        cb_durs = np.asarray(bursts.get('durations_ms', []), dtype=float)
        plateau_mask = cb_durs >= plateau_min_duration_ms
        plateau_starts = cb_starts[plateau_mask]
        plateau_ends = cb_ends[plateau_mask]

    ifr_all = _compute_ifr_from_spike_indices(
        len(trace), all_spike_indices, frame_rate, firing_rate_bin_ms, firing_rate_smooth_ms
    )
    ifr_ss = _compute_ifr_from_spike_indices(
        len(trace), ss_indices, frame_rate, firing_rate_bin_ms, firing_rate_smooth_ms
    )
    ifr_cs = _compute_ifr_from_spike_indices(
        len(trace), cs_indices, frame_rate, firing_rate_bin_ms, firing_rate_smooth_ms
    )

    baseline_start_offset = int(round(2.0 * frame_rate))
    baseline_end_offset = int(round(1.0 * frame_rate))
    valid_frame_mask = np.isfinite(np.asarray(x_neural, dtype=float))
    valid_frame_mask &= np.isfinite(np.asarray(y_neural, dtype=float))
    valid_frame_mask &= np.isfinite(np.asarray(speed, dtype=float))
    if bad_mask is not None:
        valid_frame_mask &= ~bad_mask
    if bool(require_movement):
        if moving_min_duration_s is None:
            moving_min_duration_s = max(float(min_duration_ms) / 1000.0, 0.1)
        moving_kernel_size = max(3, int(moving_kernel_size))
        if moving_kernel_size % 2 == 0:
            moving_kernel_size += 1
        _, _, moving_idx_raw = core._compute_moving_epochs(
            speed=np.asarray(speed, dtype=float),
            frame_rate=float(frame_rate),
            kernel_size=int(moving_kernel_size),
            filter_type="median",
            speed_threshold=float(speed_threshold),
            min_duration_s=float(moving_min_duration_s),
            merge_gap_s=float(merge_gap_s),
        )
        moving_mask = np.zeros(len(trace), dtype=bool)
        moving_idx_raw = np.asarray(moving_idx_raw, dtype=int)
        moving_idx_raw = moving_idx_raw[(moving_idx_raw >= 0) & (moving_idx_raw < len(trace))]
        moving_mask[moving_idx_raw] = True
        moving_mask &= valid_frame_mask
    else:
        moving_mask = valid_frame_mask.copy()

    def _mask_to_epochs(mask: np.ndarray, *, min_frames: int = 1) -> list[tuple[int, int]]:
        starts: list[int] = []
        ends: list[int] = []
        in_epoch = False
        for idx, flag in enumerate(mask):
            if flag and not in_epoch:
                starts.append(int(idx))
                in_epoch = True
            elif (not flag) and in_epoch:
                ends.append(int(idx) - 1)
                in_epoch = False
        if in_epoch:
            ends.append(int(len(mask)) - 1)
        return [(s, e) for s, e in zip(starts, ends) if (e - s + 1) >= min_frames]

    moving_min_frames = 1
    if bool(require_movement):
        moving_min_frames = max(1, int(round(float(moving_min_duration_s) * float(frame_rate))))
    moving_epochs = _mask_to_epochs(moving_mask, min_frames=int(moving_min_frames))
    def _find_support_epoch_for_center(
        center_idx: int,
        epoch_start: int,
        epoch_end_exclusive: int,
    ) -> tuple[int, int] | None:
        if not bool(require_movement):
            # In non-movement mode, keep support local to this traversal epoch.
            run_start = int(epoch_start)
            run_end = int(epoch_end_exclusive) - 1
            if run_end < run_start:
                return None
            return run_start, run_end
        for start_i, end_i in moving_epochs:
            if start_i <= int(center_idx) <= end_i:
                return int(start_i), int(end_i)
        return None

    def _compute_center_indices(epochs, types, direction_filter=None):
        if direction_filter is not None:
            filtered = [(ep, tt) for ep, tt in zip(epochs, types) if tt == direction_filter]
            if not filtered:
                return [], [], [], []
            epochs, types = zip(*filtered)
            epochs, types = list(epochs), list(types)

        center_indices = []
        trials_with_spikes = []
        for epoch_start, epoch_end in epochs:
            spikes_in_epoch = (all_spike_indices >= epoch_start) & (all_spike_indices < epoch_end)
            has_spikes = np.any(spikes_in_epoch)
            trials_with_spikes.append(has_spikes)
            if center_by_pf_position and pf_peak_xy is not None:
                pf_x, pf_y = pf_peak_xy
                x_epoch = np.asarray(x_neural[epoch_start:epoch_end], dtype=float)
                y_epoch = np.asarray(y_neural[epoch_start:epoch_end], dtype=float)
                moving_epoch = moving_mask[int(epoch_start):int(epoch_end)]
                if x_epoch.size == 0 or y_epoch.size == 0:
                    center_indices.append(None)
                    continue
                valid_epoch = np.isfinite(x_epoch) & np.isfinite(y_epoch) & np.asarray(moving_epoch, dtype=bool)
                if not np.any(valid_epoch):
                    center_indices.append(None)
                    continue
                dist_sq = np.full(x_epoch.shape, np.nan, dtype=float)
                dist_sq[valid_epoch] = (x_epoch[valid_epoch] - pf_x) ** 2 + (y_epoch[valid_epoch] - pf_y) ** 2
                if np.any(np.isfinite(dist_sq)):
                    min_dist_sq = np.nanmin(dist_sq)
                    min_dist_cm = np.sqrt(min_dist_sq)
                    if max_pf_distance_cm is not None and min_dist_cm > max_pf_distance_cm:
                        center_idx = None
                    else:
                        center_idx = epoch_start + int(np.nanargmin(dist_sq))
                else:
                    center_idx = None
            else:
                if not has_spikes or ifr_all is None:
                    center_idx = None
                else:
                    ifr_segment = ifr_all[epoch_start:epoch_end]
                    if len(ifr_segment) > 0 and np.any(np.isfinite(ifr_segment)):
                        center_idx = epoch_start + int(np.nanargmax(ifr_segment))
                    else:
                        center_idx = None
            center_indices.append(center_idx)
        return center_indices, trials_with_spikes, epochs, types

    def _build_distance_stacks(epochs, types, center_indices, trials_with_spikes):
        n_total = len(epochs)
        n_reliable = sum(trials_with_spikes)

        theta_stack, slow_stack = [], []
        rate_stack, ss_rate_stack, cs_rate_stack = [], [], []
        ss_pct_stack, cs_pct_stack = [], []
        plateau_stack = []
        pf_entry_rel_list, pf_exit_rel_list = [], []
        kept_starts, kept_ends, kept_types = [], [], []
        kept_session_idx: list[int] = []
        # Deduplicate by displayed epoch window within this PF result.
        # PF1/PF2 are already computed in separate calls, so this does not mix PF ranks.
        seen_display_epochs: set[tuple[int, int]] = set()

        for i, ((epoch_start, epoch_end), center_idx) in enumerate(zip(epochs, center_indices)):
            if center_idx is None:
                continue
            if not center_by_pf_position and not trials_with_spikes[i]:
                continue
            if center_idx < epoch_start or center_idx >= epoch_end or not valid_frame_mask[int(center_idx)]:
                continue
            support_epoch = _find_support_epoch_for_center(
                int(center_idx),
                int(epoch_start),
                int(epoch_end),
            )
            if support_epoch is None:
                continue
            run_start, run_end = support_epoch
            frame_idx = np.arange(run_start, run_end + 1, dtype=int)
            x_seg = np.asarray(x_neural[run_start:run_end + 1], dtype=float)
            y_seg = np.asarray(y_neural[run_start:run_end + 1], dtype=float)
            if x_seg.size < 2 or y_seg.size < 2:
                continue
            if not (np.all(np.isfinite(x_seg)) and np.all(np.isfinite(y_seg))):
                continue
            center_local = int(center_idx - run_start)
            if center_local < 0 or center_local >= x_seg.size:
                continue
            signed_distance_full = _compute_signed_distance_from_center(
                x_seg,
                y_seg,
                center_local=int(center_local),
                pf_peak_xy=pf_peak_xy,
                distance_mode=distance_mode,
            )
            if signed_distance_full is None or not np.all(np.isfinite(signed_distance_full)):
                continue
            left_candidates = np.where(signed_distance_full[:center_local + 1] <= -distance_window_cm)[0]
            right_candidates = np.where(signed_distance_full[center_local:] >= distance_window_cm)[0]
            if bool(require_full_span):
                if left_candidates.size == 0 or right_candidates.size == 0:
                    continue
                start_local = int(left_candidates[-1])
                end_local = int(center_local + right_candidates[0])
                if end_local <= start_local:
                    continue
            else:
                start_local = 0
                end_local = int(dist_to_peak.size - 1)

            display_start = int(run_start + start_local)
            display_end_exclusive = int(run_start + end_local + 1)
            if display_end_exclusive <= display_start:
                continue
            display_epoch_key = (int(display_start), int(display_end_exclusive))
            if display_epoch_key in seen_display_epochs:
                continue
            signed_distance = np.asarray(
                signed_distance_full[start_local:end_local + 1],
                dtype=float,
            )
            if signed_distance.size < 2:
                continue

            base_start = max(epoch_start - baseline_start_offset, 0)
            base_end = max(epoch_start - baseline_end_offset, 0)
            baseline_theta = np.nanmean(theta_amp[base_start:base_end]) if base_end > base_start else np.nan
            baseline_slow = np.nanmean(slow_vm[base_start:base_end]) if base_end > base_start else np.nan

            theta_seg = theta_amp[display_start:display_end_exclusive].copy()
            slow_seg = slow_vm[display_start:display_end_exclusive].copy()
            if bool(subtract_pre_traversal_baseline) and np.isfinite(baseline_theta):
                theta_seg = theta_seg - baseline_theta
            if bool(subtract_pre_traversal_baseline) and np.isfinite(baseline_slow):
                slow_seg = slow_seg - baseline_slow

            seg_len = int(display_end_exclusive - display_start)
            rate_seg = ifr_all[display_start:display_end_exclusive].copy() if ifr_all is not None else np.full(seg_len, np.nan)
            ss_rate_seg = ifr_ss[display_start:display_end_exclusive].copy() if ifr_ss is not None else np.full(seg_len, np.nan)
            cs_rate_seg = ifr_cs[display_start:display_end_exclusive].copy() if ifr_cs is not None else np.full(seg_len, np.nan)
            denom = ss_rate_seg + cs_rate_seg
            with np.errstate(divide="ignore", invalid="ignore"):
                ss_pct_seg = np.where(np.isfinite(denom) & (denom > 0), 100.0 * ss_rate_seg / denom, np.nan)
                cs_pct_seg = np.where(np.isfinite(denom) & (denom > 0), 100.0 * cs_rate_seg / denom, np.nan)

            plateau_seg = np.zeros(seg_len, dtype=float)
            for ps, pe in zip(plateau_starts, plateau_ends):
                overlap_start = max(int(ps), display_start)
                overlap_end = min(int(pe) + 1, display_end_exclusive)
                if overlap_start < overlap_end:
                    local_s = overlap_start - display_start
                    local_e = overlap_end - display_start
                    seg = np.asarray(vms[cell_idx][overlap_start:overlap_end], dtype=float).copy()
                    if bool(subtract_pre_traversal_baseline) and np.isfinite(baseline_slow):
                        seg = seg - baseline_slow
                    plateau_seg[local_s:local_e] = seg

            allow_partial = not bool(require_full_span)
            theta_trial = _resample_trace_to_distance_grid(signed_distance, theta_seg, distance_rel, allow_partial=allow_partial)
            slow_trial = _resample_trace_to_distance_grid(signed_distance, slow_seg, distance_rel, allow_partial=allow_partial)
            rate_trial = _resample_trace_to_distance_grid(signed_distance, rate_seg, distance_rel, allow_partial=allow_partial)
            ss_rate_trial = _resample_trace_to_distance_grid(signed_distance, ss_rate_seg, distance_rel, allow_partial=allow_partial)
            cs_rate_trial = _resample_trace_to_distance_grid(signed_distance, cs_rate_seg, distance_rel, allow_partial=allow_partial)
            ss_pct_trial = _resample_trace_to_distance_grid(signed_distance, ss_pct_seg, distance_rel, allow_partial=allow_partial)
            cs_pct_trial = _resample_trace_to_distance_grid(signed_distance, cs_pct_seg, distance_rel, allow_partial=allow_partial)
            plateau_trial = _resample_trace_to_distance_grid(signed_distance, plateau_seg, distance_rel, allow_partial=allow_partial)
            if any(v is None for v in (
                theta_trial,
                slow_trial,
                rate_trial,
                ss_rate_trial,
                cs_rate_trial,
            )):
                continue
            if ss_pct_trial is None:
                ss_pct_trial = np.full(avg_len, np.nan, dtype=float)
            if cs_pct_trial is None:
                cs_pct_trial = np.full(avg_len, np.nan, dtype=float)
            if plateau_trial is None:
                plateau_trial = np.zeros(avg_len, dtype=float)

            theta_stack.append(theta_trial)
            slow_stack.append(slow_trial)
            rate_stack.append(rate_trial)
            ss_rate_stack.append(ss_rate_trial)
            cs_rate_stack.append(cs_rate_trial)
            ss_pct_stack.append(ss_pct_trial)
            cs_pct_stack.append(cs_pct_trial)
            plateau_stack.append(plateau_trial)
            pf_entry_rel_list.append(float(signed_distance[0]))
            pf_exit_rel_list.append(float(signed_distance[-1]))
            kept_starts.append(display_start)
            kept_ends.append(display_end_exclusive)
            kept_types.append(types[i])
            seen_display_epochs.add(display_epoch_key)
            if session_start_frames_arr is not None:
                kept_session_idx.append(int(np.searchsorted(session_start_frames_arr, display_start, side="right") - 1))
            else:
                kept_session_idx.append(0)

        empty = np.array([]).reshape(0, avg_len)
        if len(theta_stack) == 0:
            return {
                'n_trials': 0,
                'n_total_trials': n_total,
                'n_reliable_trials': n_reliable,
                'reliability': n_reliable / n_total if n_total > 0 else np.nan,
                'traversal_types': types,
                'trial_data': {
                    'epoch_start_frames': np.array([], dtype=int),
                    'epoch_end_frames': np.array([], dtype=int),
                    'epoch_start_sec': np.array([], dtype=float),
                    'epoch_end_sec': np.array([], dtype=float),
                    'duration_sec': np.array([], dtype=float),
                    'n_spikes_all': np.array([], dtype=int),
                    'n_spikes_ss': np.array([], dtype=int),
                    'n_spikes_cs': np.array([], dtype=int),
                    'fr_all_hz': np.array([], dtype=float),
                    'fr_ss_hz': np.array([], dtype=float),
                    'fr_cs_hz': np.array([], dtype=float),
                    'traversal_types': np.array([], dtype=object),
                    'session_idx': np.array([], dtype=int),
                },
                'theta_stack': empty,
                'slow_stack': empty,
                'rate_stack': empty,
                'ss_rate_stack': empty,
                'cs_rate_stack': empty,
                'ss_pct_stack': empty,
                'cs_pct_stack': empty,
                'plateau_stack': empty,
                'pf_entry_rel': np.array([], dtype=float),
                'pf_exit_rel': np.array([], dtype=float),
                'n_plateaus_per_trial': np.array([], dtype=int),
                'theta_mean': np.full(avg_len, np.nan),
                'slow_mean': np.full(avg_len, np.nan),
                'rate_mean': np.full(avg_len, np.nan),
                'ss_rate_mean': np.full(avg_len, np.nan),
                'cs_rate_mean': np.full(avg_len, np.nan),
                'ss_pct_mean': np.full(avg_len, np.nan),
                'cs_pct_mean': np.full(avg_len, np.nan),
            }

        theta_arr = np.vstack(theta_stack)
        slow_arr = np.vstack(slow_stack)
        rate_arr = np.vstack(rate_stack)
        ss_rate_arr = np.vstack(ss_rate_stack)
        cs_rate_arr = np.vstack(cs_rate_stack)
        ss_pct_arr = np.vstack(ss_pct_stack)
        cs_pct_arr = np.vstack(cs_pct_stack)
        plateau_arr = np.vstack(plateau_stack)
        epoch_start_frames = np.asarray(kept_starts, dtype=int)
        epoch_end_frames = np.asarray(kept_ends, dtype=int)
        duration_frames = epoch_end_frames - epoch_start_frames
        duration_sec = duration_frames.astype(float) / float(frame_rate)
        epoch_start_sec = epoch_start_frames.astype(float) / float(frame_rate)
        epoch_end_sec = epoch_end_frames.astype(float) / float(frame_rate)
        spike_sorted_all = np.sort(all_spike_indices)
        spike_sorted_ss = np.sort(ss_indices)
        spike_sorted_cs = np.sort(cs_indices)
        left_all = np.searchsorted(spike_sorted_all, epoch_start_frames, side="left")
        right_all = np.searchsorted(spike_sorted_all, epoch_end_frames, side="left")
        left_ss = np.searchsorted(spike_sorted_ss, epoch_start_frames, side="left")
        right_ss = np.searchsorted(spike_sorted_ss, epoch_end_frames, side="left")
        left_cs = np.searchsorted(spike_sorted_cs, epoch_start_frames, side="left")
        right_cs = np.searchsorted(spike_sorted_cs, epoch_end_frames, side="left")
        n_all = (right_all - left_all).astype(int)
        n_ss = (right_ss - left_ss).astype(int)
        n_cs = (right_cs - left_cs).astype(int)
        with np.errstate(divide="ignore", invalid="ignore"):
            fr_all = np.where(duration_sec > 0, n_all / duration_sec, np.nan)
            fr_ss = np.where(duration_sec > 0, n_ss / duration_sec, np.nan)
            fr_cs = np.where(duration_sec > 0, n_cs / duration_sec, np.nan)
        return {
            'n_trials': len(theta_stack),
            'n_total_trials': n_total,
            'n_reliable_trials': n_reliable,
            'reliability': n_reliable / n_total if n_total > 0 else np.nan,
            'traversal_types': kept_types,
            'trial_data': {
                'epoch_start_frames': epoch_start_frames,
                'epoch_end_frames': epoch_end_frames,
                'epoch_start_sec': epoch_start_sec,
                'epoch_end_sec': epoch_end_sec,
                'duration_sec': duration_sec,
                'n_spikes_all': n_all,
                'n_spikes_ss': n_ss,
                'n_spikes_cs': n_cs,
                'fr_all_hz': fr_all,
                'fr_ss_hz': fr_ss,
                'fr_cs_hz': fr_cs,
                'traversal_types': np.asarray(kept_types, dtype=object),
                'session_idx': np.asarray(kept_session_idx, dtype=int),
            },
            'theta_stack': theta_arr,
            'slow_stack': slow_arr,
            'rate_stack': rate_arr,
            'ss_rate_stack': ss_rate_arr,
            'cs_rate_stack': cs_rate_arr,
            'ss_pct_stack': ss_pct_arr,
            'cs_pct_stack': cs_pct_arr,
            'plateau_stack': plateau_arr,
            'pf_entry_rel': np.asarray(pf_entry_rel_list, dtype=float),
            'pf_exit_rel': np.asarray(pf_exit_rel_list, dtype=float),
            'n_plateaus_per_trial': np.array([int(np.any(row != 0)) for row in plateau_arr], dtype=int),
            'theta_mean': np.nanmean(theta_arr, axis=0),
            'slow_mean': np.nanmean(slow_arr, axis=0),
            'rate_mean': np.nanmean(rate_arr, axis=0),
            'ss_rate_mean': np.nanmean(ss_rate_arr, axis=0),
            'cs_rate_mean': np.nanmean(cs_rate_arr, axis=0),
            'ss_pct_mean': np.nanmean(ss_pct_arr, axis=0) if np.any(np.isfinite(ss_pct_arr)) else np.full(avg_len, np.nan),
            'cs_pct_mean': np.nanmean(cs_pct_arr, axis=0) if np.any(np.isfinite(cs_pct_arr)) else np.full(avg_len, np.nan),
        }

    center_all, spikes_all, epochs_all, types_all = _compute_center_indices(valid_epochs, valid_types, None)
    center_cw, spikes_cw, epochs_cw, types_cw = _compute_center_indices(valid_epochs, valid_types, 'cw')
    center_ccw, spikes_ccw, epochs_ccw, types_ccw = _compute_center_indices(valid_epochs, valid_types, 'ccw')
    result_all = _build_distance_stacks(epochs_all, types_all, center_all, spikes_all)
    result_cw = _build_distance_stacks(epochs_cw, types_cw, center_cw, spikes_cw)
    result_ccw = _build_distance_stacks(epochs_ccw, types_ccw, center_ccw, spikes_ccw)

    if int(result_all.get("n_trials", 0)) < int(min_traversals):
        return None
    return {
        'cell_idx': cell_idx,
        'pf_peak_xy': pf_peak_xy,
        'place_field_mask': np.asarray(place_field_mask, dtype=bool) if place_field_mask is not None else None,
        'rate_map': np.asarray(rate_map, dtype=float) if rate_map is not None else None,
        'pf_bins': pf_bins,
        'center_by_pf_position': center_by_pf_position,
        'require_movement': bool(require_movement),
        'distance_rel': distance_rel,
        'distance_window_cm': distance_window_cm,
        'distance_window_cm_requested': float(distance_window_cm_req),
        'distance_window_cm_effective': float(distance_window_cm_eff),
        'distance_bin_cm': distance_bin_cm,
        'distance_mode': str(distance_mode),
        'all': result_all,
        'cw': result_cw,
        'ccw': result_ccw,
    }


def _load_spatial_analysis_by_idx(animal_dir: Path) -> dict[int, dict[str, Any]]:
    spatial_path = animal_dir / "spatial_analysis_full.pkl"
    if not spatial_path.exists():
        raise FileNotFoundError(f"Missing spatial_analysis_full.pkl for {animal_dir.name}")
    with spatial_path.open("rb") as f:
        spatial_cells = pickle.load(f)
    out: dict[int, dict[str, Any]] = {}
    if isinstance(spatial_cells, list):
        for item in spatial_cells:
            if isinstance(item, dict) and "cell_idx" in item:
                out[int(item["cell_idx"])] = item
    return out


def _compute_pf_peak_xy_from_mask(
    place_field_mask: np.ndarray,
    rate_map: np.ndarray | None,
    pf_bins: list[np.ndarray],
) -> tuple[float, float] | None:
    if place_field_mask is None or not np.any(place_field_mask):
        return None
    if rate_map is None:
        return None
    masked_rate = np.where(place_field_mask, rate_map, np.nan)
    if not np.any(np.isfinite(masked_rate)):
        return None
    x_centers = (pf_bins[0][:-1] + pf_bins[0][1:]) / 2
    y_centers = (pf_bins[1][:-1] + pf_bins[1][1:]) / 2
    peak_idx = np.nanargmax(masked_rate)
    peak_row, peak_col = np.unravel_index(peak_idx, masked_rate.shape)
    return float(x_centers[peak_row]), float(y_centers[peak_col])


def _empty_distance_defined_direction_result(
    distance_rel: np.ndarray,
    *,
    n_total_trials: int = 0,
) -> dict[str, Any]:
    n_bins = int(len(distance_rel))
    empty = np.full((0, n_bins), np.nan, dtype=float)
    return {
        "n_trials": 0,
        "n_total_trials": int(n_total_trials),
        "n_reliable_trials": 0,
        "reliability": np.nan,
        "traversal_types": [],
        "trial_data": {
            "epoch_start_frames": np.array([], dtype=int),
            "epoch_end_frames": np.array([], dtype=int),
            "center_frames": np.array([], dtype=int),
            "center_vicinity_cm": np.array([], dtype=float),
            "epoch_start_sec": np.array([], dtype=float),
            "epoch_end_sec": np.array([], dtype=float),
            "duration_sec": np.array([], dtype=float),
            "nonrest_duration_sec": np.array([], dtype=float),
            "n_spikes_all": np.array([], dtype=int),
            "n_spikes_ss": np.array([], dtype=int),
            "n_spikes_cs": np.array([], dtype=int),
            "fr_all_hz": np.array([], dtype=float),
            "fr_ss_hz": np.array([], dtype=float),
            "fr_cs_hz": np.array([], dtype=float),
            "traversal_types": np.array([], dtype=object),
            "session_idx": np.array([], dtype=int),
        },
        "theta_stack": empty.copy(),
        "slow_stack": empty.copy(),
        "rate_stack": empty.copy(),
        "ss_rate_stack": empty.copy(),
        "cs_rate_stack": empty.copy(),
        "ss_pct_stack": empty.copy(),
        "cs_pct_stack": empty.copy(),
        "plateau_stack": np.zeros((0, n_bins), dtype=float),
        "pf_entry_rel": np.array([], dtype=float),
        "pf_exit_rel": np.array([], dtype=float),
        "n_plateaus_per_trial": np.array([], dtype=int),
        "plateau_trace_events_by_trial": [],
        "theta_mean": np.full(n_bins, np.nan, dtype=float),
        "slow_mean": np.full(n_bins, np.nan, dtype=float),
        "rate_mean": np.full(n_bins, np.nan, dtype=float),
        "ss_rate_mean": np.full(n_bins, np.nan, dtype=float),
        "cs_rate_mean": np.full(n_bins, np.nan, dtype=float),
        "ss_pct_mean": np.full(n_bins, np.nan, dtype=float),
        "cs_pct_mean": np.full(n_bins, np.nan, dtype=float),
    }


def _aggregate_distance_defined_trials(
    trials: list[dict[str, Any]],
    distance_rel: np.ndarray,
    frame_rate: float,
) -> dict[str, Any]:
    if len(trials) == 0:
        return _empty_distance_defined_direction_result(distance_rel, n_total_trials=0)

    n_trials = int(len(trials))
    n_reliable = int(sum(int(t.get("n_spikes_all", 0)) > 0 for t in trials))
    theta_arr = np.vstack([np.asarray(t["theta_trial"], dtype=float) for t in trials])
    slow_arr = np.vstack([np.asarray(t["slow_trial"], dtype=float) for t in trials])
    rate_arr = np.vstack([np.asarray(t["rate_trial"], dtype=float) for t in trials])
    ss_rate_arr = np.vstack([np.asarray(t["ss_rate_trial"], dtype=float) for t in trials])
    cs_rate_arr = np.vstack([np.asarray(t["cs_rate_trial"], dtype=float) for t in trials])
    ss_pct_arr = np.vstack([np.asarray(t["ss_pct_trial"], dtype=float) for t in trials])
    cs_pct_arr = np.vstack([np.asarray(t["cs_pct_trial"], dtype=float) for t in trials])
    plateau_arr = np.vstack([np.asarray(t["plateau_trial"], dtype=float) for t in trials])
    plateau_trace_events_by_trial = [
        list(t.get("plateau_trace_events", []))
        if isinstance(t.get("plateau_trace_events", []), (list, tuple))
        else []
        for t in trials
    ]
    starts = np.asarray([int(t["epoch_start"]) for t in trials], dtype=int)
    ends = np.asarray([int(t["epoch_end"]) for t in trials], dtype=int)
    centers = np.asarray([int(t["center_idx"]) for t in trials], dtype=int)
    vicinity = np.asarray([float(t["center_vicinity_cm"]) for t in trials], dtype=float)
    session_idx = np.asarray([int(t["session_idx"]) for t in trials], dtype=int)
    n_spikes_all = np.asarray([int(t["n_spikes_all"]) for t in trials], dtype=int)
    n_spikes_ss = np.asarray([int(t["n_spikes_ss"]) for t in trials], dtype=int)
    n_spikes_cs = np.asarray([int(t["n_spikes_cs"]) for t in trials], dtype=int)
    nonrest_duration_sec = np.asarray([float(t["nonrest_duration_sec"]) for t in trials], dtype=float)
    traversal_types = np.asarray([str(t.get("traversal_type", "unknown")) for t in trials], dtype=object)
    duration_sec = (ends - starts).astype(float) / float(frame_rate)
    with np.errstate(divide="ignore", invalid="ignore"):
        fr_all_hz = np.where(nonrest_duration_sec > 0, n_spikes_all / nonrest_duration_sec, np.nan)
        fr_ss_hz = np.where(nonrest_duration_sec > 0, n_spikes_ss / nonrest_duration_sec, np.nan)
        fr_cs_hz = np.where(nonrest_duration_sec > 0, n_spikes_cs / nonrest_duration_sec, np.nan)

    def _nanmean_columns(arr: np.ndarray) -> np.ndarray:
        arr = np.asarray(arr, dtype=float)
        out = np.full(len(time_rel), np.nan, dtype=float)
        if arr.ndim != 2 or arr.shape[1] != len(time_rel):
            return out
        valid = np.isfinite(arr)
        counts = np.sum(valid, axis=0)
        if np.any(counts > 0):
            sums = np.nansum(arr, axis=0)
            out[counts > 0] = sums[counts > 0] / counts[counts > 0]
        return out

    return {
        "n_trials": n_trials,
        "n_total_trials": n_trials,
        "n_reliable_trials": n_reliable,
        "reliability": float(n_reliable) / float(n_trials) if n_trials > 0 else np.nan,
        "traversal_types": traversal_types.tolist(),
        "trial_data": {
            "epoch_start_frames": starts,
            "epoch_end_frames": ends,
            "center_frames": centers,
            "center_vicinity_cm": vicinity,
            "epoch_start_sec": starts.astype(float) / float(frame_rate),
            "epoch_end_sec": ends.astype(float) / float(frame_rate),
            "duration_sec": duration_sec,
            "nonrest_duration_sec": nonrest_duration_sec,
            "n_spikes_all": n_spikes_all,
            "n_spikes_ss": n_spikes_ss,
            "n_spikes_cs": n_spikes_cs,
            "fr_all_hz": fr_all_hz,
            "fr_ss_hz": fr_ss_hz,
            "fr_cs_hz": fr_cs_hz,
            "traversal_types": traversal_types,
            "session_idx": session_idx,
        },
        "theta_stack": theta_arr,
        "slow_stack": slow_arr,
        "rate_stack": rate_arr,
        "ss_rate_stack": ss_rate_arr,
        "cs_rate_stack": cs_rate_arr,
        "ss_pct_stack": ss_pct_arr,
        "cs_pct_stack": cs_pct_arr,
        "plateau_stack": plateau_arr,
        "pf_entry_rel": np.asarray([float(t["pf_entry_rel"]) for t in trials], dtype=float),
        "pf_exit_rel": np.asarray([float(t["pf_exit_rel"]) for t in trials], dtype=float),
        "n_plateaus_per_trial": np.asarray([int(t["n_plateaus"]) for t in trials], dtype=int),
        "plateau_trace_events_by_trial": plateau_trace_events_by_trial,
        "theta_mean": np.nanmean(theta_arr, axis=0),
        "slow_mean": np.nanmean(slow_arr, axis=0),
        "rate_mean": np.nanmean(rate_arr, axis=0),
        "ss_rate_mean": np.nanmean(ss_rate_arr, axis=0),
        "cs_rate_mean": np.nanmean(cs_rate_arr, axis=0),
        "ss_pct_mean": np.nanmean(ss_pct_arr, axis=0) if np.any(np.isfinite(ss_pct_arr)) else np.full(len(distance_rel), np.nan),
        "cs_pct_mean": np.nanmean(cs_pct_arr, axis=0) if np.any(np.isfinite(cs_pct_arr)) else np.full(len(distance_rel), np.nan),
    }


def _find_distance_defined_trials_iterative(
    dist_to_peak: np.ndarray,
    valid_mask: np.ndarray,
    moving_mask: np.ndarray,
    *,
    trial_span_cm: float,
    detection_span_cm: float,
    vicinity_min_cm: int,
    vicinity_max_cm: int,
) -> list[dict[str, int | float]]:
    n = int(len(dist_to_peak))
    if n == 0:
        return []
    dist_arr = np.asarray(dist_to_peak, dtype=float).reshape(-1)
    valid_arr = np.asarray(valid_mask, dtype=bool).reshape(-1)
    moving_arr = np.asarray(moving_mask, dtype=bool).reshape(-1)
    if dist_arr.size != n or valid_arr.size != n or moving_arr.size != n:
        raise ValueError("dist_to_peak, valid_mask, and moving_mask must have matching lengths.")

    trials: list[dict[str, int | float]] = []
    taken = np.zeros(n, dtype=bool)
    valid_dist_mask = valid_arr & np.isfinite(dist_arr)
    moving_valid_mask = valid_dist_mask & moving_arr
    if not np.any(moving_valid_mask):
        return []
    moving_valid_indices = np.flatnonzero(moving_valid_mask)

    def _build_reach_arrays(span_cm: float) -> tuple[np.ndarray, np.ndarray]:
        reach_mask = valid_dist_mask & (dist_arr >= float(span_cm))
        left_reach = np.full(n, -1, dtype=int)
        right_reach = np.full(n, -1, dtype=int)

        last_idx = -1
        for i in range(n):
            if reach_mask[i]:
                last_idx = int(i)
            left_reach[i] = int(last_idx)

        next_idx = -1
        for i in range(n - 1, -1, -1):
            if reach_mask[i]:
                next_idx = int(i)
            right_reach[i] = int(next_idx)
        return left_reach, right_reach

    left_detect_reach, right_detect_reach = _build_reach_arrays(float(detection_span_cm))
    left_trial_reach, right_trial_reach = _build_reach_arrays(float(trial_span_cm))

    def _find_left(center_idx: int, left_reach: np.ndarray) -> int | None:
        center_idx = int(center_idx)
        if center_idx <= 0:
            return None
        out = int(left_reach[center_idx - 1])
        return None if out < 0 else out

    def _find_right(center_idx: int, right_reach: np.ndarray) -> int | None:
        center_idx = int(center_idx)
        if center_idx >= (n - 1):
            return None
        out = int(right_reach[center_idx + 1])
        return None if out < 0 else out

    for vicinity_cm in range(int(vicinity_min_cm), int(vicinity_max_cm) + 1):
        candidate_indices = np.flatnonzero(moving_valid_mask & (dist_arr <= float(vicinity_cm)))
        if candidate_indices.size == 0:
            continue
        pointer = 0
        pos = 0
        n_candidates = int(candidate_indices.size)
        while pos < n_candidates:
            center_idx = int(candidate_indices[pos])
            if center_idx < pointer or bool(taken[center_idx]):
                pos += 1
                continue
            candidate_center_idx = int(center_idx)
            detect_start_idx = _find_left(center_idx, left_detect_reach)
            detect_end_idx = _find_right(center_idx, right_detect_reach)
            if (
                detect_start_idx is None
                or detect_end_idx is None
                or detect_end_idx <= detect_start_idx
            ):
                pointer = max(int(pointer), int(candidate_center_idx) + 1, int(center_idx) + 1)
                pos += 1
                continue
            start_idx = _find_left(center_idx, left_trial_reach)
            end_idx = _find_right(center_idx, right_trial_reach)
            if start_idx is None or end_idx is None or end_idx <= start_idx:
                pointer = max(int(pointer), int(candidate_center_idx) + 1, int(center_idx) + 1)
                pos += 1
                continue

            # Refine to the closest-to-peak moving frame inside the trial span.
            left_pos = int(np.searchsorted(moving_valid_indices, int(start_idx), side="left"))
            right_pos = int(np.searchsorted(moving_valid_indices, int(end_idx), side="right"))
            trial_candidates = moving_valid_indices[left_pos:right_pos]
            if trial_candidates.size > 0 and np.any(taken[trial_candidates]):
                trial_candidates = trial_candidates[~taken[trial_candidates]]
            if trial_candidates.size == 0:
                pointer = max(int(pointer), int(candidate_center_idx) + 1, int(center_idx) + 1)
                pos += 1
                continue
            trial_dists = np.asarray(dist_arr[trial_candidates], dtype=float)
            center_idx = int(trial_candidates[int(np.nanargmin(trial_dists))])
            detect_start_idx = _find_left(center_idx, left_detect_reach)
            detect_end_idx = _find_right(center_idx, right_detect_reach)
            if (
                detect_start_idx is None
                or detect_end_idx is None
                or detect_end_idx <= detect_start_idx
            ):
                pointer = max(int(pointer), int(candidate_center_idx) + 1, int(center_idx) + 1)
                pos += 1
                continue
            start_idx = _find_left(center_idx, left_trial_reach)
            end_idx = _find_right(center_idx, right_trial_reach)
            if start_idx is None or end_idx is None or end_idx <= start_idx:
                pointer = max(int(pointer), int(candidate_center_idx) + 1, int(center_idx) + 1)
                pos += 1
                continue
            end_exclusive = int(end_idx + 1)
            if np.any(taken[start_idx:end_exclusive]):
                pointer = max(int(pointer), int(candidate_center_idx) + 1, int(center_idx) + 1)
                pos += 1
                continue
            trials.append(
                {
                    "epoch_start": int(start_idx),
                    "epoch_end": int(end_exclusive),
                    "center_idx": int(center_idx),
                    "center_vicinity_cm": float(vicinity_cm),
                    "detect_start": int(detect_start_idx),
                    "detect_end": int(detect_end_idx + 1),
                }
            )
            taken[start_idx:end_exclusive] = True
            pointer = int(end_exclusive)
            pos = int(np.searchsorted(candidate_indices, int(pointer), side="left"))
    if len(trials) > 1:
        trials = sorted(
            trials,
            key=lambda t: (int(t["epoch_start"]), int(t["epoch_end"]), int(t["center_idx"])),
        )
    return trials


def compute_pf_distance_centered_trial_data_iterative(
    *,
    cell_idx: int,
    traces: np.ndarray,
    vms: np.ndarray,
    x_neural: np.ndarray,
    y_neural: np.ndarray,
    speed: np.ndarray,
    all_spikes: list[np.ndarray] | np.ndarray,
    refined_SS: list[np.ndarray] | np.ndarray,
    all_CS_spikes: list[np.ndarray] | np.ndarray,
    frame_rate: float,
    distance_window_cm: float = 15.0,
    detection_window_cm: float = 10.0,
    distance_bin_cm: float = 1.0,
    center_vicinity_min_cm: int = 1,
    center_vicinity_max_cm: int = 5,
    moving_speed_threshold: float = 3.0,
    resting_speed_threshold: float = 0.5,
    moving_kernel_size: int = 51,
    moving_min_duration_s: float = 0.25,
    merge_gap_s: float = 0.0,
    theta_freqs: tuple[float, float] = (4.0, 8.0),
    slow_freqs: float = 2.0,
    subtract_pre_traversal_baseline: bool = True,
    min_traversals: int = 10,
    exclude_trials_with_bad_frames: bool = True,
    session_start_frames: list[int] | np.ndarray | None = None,
    session_indices: tuple[int, ...] | None = None,
    bad_masks: np.ndarray | None = None,
    bad_frame_mask: np.ndarray | None = None,
    plateaus_dicts: list[dict[str, Any] | None] | None = None,
    complex_bursts_dicts: list[dict[str, Any] | None] | None = None,
    include_long_cb_as_plateau: bool = True,
    cb_plateau_min_duration_ms: float = 100.0,
    plateau_min_duration_ms: float = 100.0,
    plateau_trace_window_ms: float = 100.0,
    include_resting_plateaus: bool = True,
    analysis_override: dict[str, Any] | None = None,
    distance_mode: str = "cumulative_path",
) -> dict[str, Any] | None:
    if analysis_override is None or not bool(analysis_override.get("is_place_cell", False)):
        return None
    distance_mode = _normalize_distance_mode(distance_mode)
    plateau_trace_window_ms = float(plateau_trace_window_ms)
    if (not np.isfinite(plateau_trace_window_ms)) or plateau_trace_window_ms < 0:
        raise ValueError("plateau_trace_window_ms must be a finite number >= 0.")

    distance_window_cm_req, distance_window_cm_eff, distance_rel = _build_symmetric_distance_axis(
        distance_window_cm,
        distance_bin_cm,
    )
    detection_window_cm_req = float(detection_window_cm)
    if (not np.isfinite(detection_window_cm_req)) or detection_window_cm_req <= 0:
        raise ValueError("detection_window_cm must be a finite number > 0.")
    detection_window_cm_eff = min(float(detection_window_cm_req), float(distance_window_cm_eff))
    distance_window_cm = float(distance_window_cm_eff)
    distance_bin_cm = float(distance_bin_cm)
    n_bins = int(distance_rel.size)
    bin_edges = np.concatenate(
        [
            distance_rel - 0.5 * distance_bin_cm,
            np.array([distance_rel[-1] + 0.5 * distance_bin_cm], dtype=float),
        ]
    )

    trace = np.asarray(traces[cell_idx], dtype=float)
    trace = interpolate_nan_segment(trace)
    theta_vm = bandpass_filter(trace, theta_freqs[0], theta_freqs[1], frame_rate, order=5)
    slow_vm = lowpass_filter(trace, slow_freqs, frame_rate, order=5)
    theta_amp = np.abs(signal.hilbert(theta_vm))

    bad_mask = None
    if bad_frame_mask is not None:
        bad_mask = np.asarray(bad_frame_mask)
        if bad_mask.dtype != bool:
            if bad_mask.ndim == 1 and bad_mask.size == len(trace):
                bad_mask = bad_mask.astype(bool)
            else:
                bad_indices = np.asarray(bad_mask, dtype=int)
                bad_indices = bad_indices[(bad_indices >= 0) & (bad_indices < len(trace))]
                bad_bool = np.zeros(len(trace), dtype=bool)
                bad_bool[bad_indices] = True
                bad_mask = bad_bool
        if bad_mask.shape[0] != len(trace):
            bad_mask = None
    elif bad_masks is not None and cell_idx < len(bad_masks):
        bad_mask = np.asarray(bad_masks[cell_idx])
        if bad_mask.dtype != bool:
            if bad_mask.ndim == 1 and bad_mask.size == len(trace):
                bad_mask = bad_mask.astype(bool)
            else:
                bad_indices = np.asarray(bad_mask, dtype=int)
                bad_indices = bad_indices[(bad_indices >= 0) & (bad_indices < len(trace))]
                bad_mask = np.zeros(len(trace), dtype=bool)
                bad_mask[bad_indices] = True
        if bad_mask.shape[0] != len(trace):
            bad_mask = None

    valid_frame_mask = np.isfinite(np.asarray(x_neural, dtype=float))
    valid_frame_mask &= np.isfinite(np.asarray(y_neural, dtype=float))
    valid_frame_mask &= np.isfinite(np.asarray(speed, dtype=float))
    if bad_mask is not None:
        valid_frame_mask &= ~bad_mask

    moving_kernel_size = max(3, int(moving_kernel_size))
    if moving_kernel_size % 2 == 0:
        moving_kernel_size += 1
    _, _, moving_idx_raw = core._compute_moving_epochs(
        speed=np.asarray(speed, dtype=float),
        frame_rate=float(frame_rate),
        kernel_size=int(moving_kernel_size),
        filter_type="median",
        speed_threshold=float(moving_speed_threshold),
        min_duration_s=float(max(0.0, moving_min_duration_s)),
        merge_gap_s=float(max(0.0, merge_gap_s)),
    )
    moving_mask = np.zeros(len(trace), dtype=bool)
    moving_idx_raw = np.asarray(moving_idx_raw, dtype=int)
    moving_idx_raw = moving_idx_raw[(moving_idx_raw >= 0) & (moving_idx_raw < len(trace))]
    moving_mask[moving_idx_raw] = True
    moving_mask &= valid_frame_mask

    place_field_mask = np.asarray(analysis_override.get("place_field_mask", []), dtype=bool)
    rate_map = np.asarray(analysis_override.get("rate_map", np.full_like(place_field_mask, np.nan)), dtype=float)
    params = dict(analysis_override.get("params", {}))
    width_real = float(params.get("width_real", 35.5))
    height_real = float(params.get("height_real", 20.0))
    bin_size = float(params.get("bin_size", 1.5))
    pf_bins = [
        np.arange(0, width_real + bin_size, bin_size),
        np.arange(0, height_real + bin_size, bin_size),
    ]
    pf_peak_xy = _compute_pf_peak_xy_from_mask(place_field_mask, rate_map, pf_bins)
    if pf_peak_xy is None:
        return None
    pf_x, pf_y = pf_peak_xy
    # Trial discovery stays anchored on nearest approach to the PF peak.
    # `distance_mode` only changes the signed distance axis used to crop and bin
    # the final per-trial signal stacks.
    dist_to_peak = np.full(len(trace), np.nan, dtype=float)
    valid_xy = np.isfinite(np.asarray(x_neural, dtype=float)) & np.isfinite(np.asarray(y_neural, dtype=float))
    dist_to_peak[valid_xy] = np.sqrt(
        (np.asarray(x_neural, dtype=float)[valid_xy] - float(pf_x)) ** 2
        + (np.asarray(y_neural, dtype=float)[valid_xy] - float(pf_y)) ** 2
    )

    trials = _find_distance_defined_trials_iterative(
        dist_to_peak=dist_to_peak,
        valid_mask=valid_frame_mask,
        moving_mask=moving_mask,
        trial_span_cm=float(distance_window_cm_eff),
        detection_span_cm=float(detection_window_cm_eff),
        vicinity_min_cm=int(center_vicinity_min_cm),
        vicinity_max_cm=int(center_vicinity_max_cm),
    )
    if len(trials) == 0:
        return None

    session_start_arr = None
    if session_start_frames is not None:
        session_start_arr = np.asarray(session_start_frames, dtype=int)
        session_start_arr = session_start_arr[np.argsort(session_start_arr)]

    all_spike_indices = np.unique(np.asarray(all_spikes[cell_idx], dtype=int))
    all_spike_indices = all_spike_indices[(all_spike_indices >= 0) & (all_spike_indices < len(trace))]
    ss_indices = np.unique(np.asarray(refined_SS[cell_idx], dtype=int))
    ss_indices = ss_indices[(ss_indices >= 0) & (ss_indices < len(trace))]
    cs_indices = np.unique(np.asarray(all_CS_spikes[cell_idx], dtype=int))
    cs_indices = cs_indices[(cs_indices >= 0) & (cs_indices < len(trace))]

    plateau_starts, plateau_ends = _build_plateau_intervals_for_cell(
        cell_idx=int(cell_idx),
        plateaus_dicts=plateaus_dicts,
        complex_bursts_dicts=complex_bursts_dicts,
        include_long_cb_as_plateau=bool(include_long_cb_as_plateau),
        cb_plateau_min_duration_ms=float(cb_plateau_min_duration_ms),
        frame_rate=float(frame_rate),
        n_frames=int(len(trace)),
    )

    def _extract_plateau_trace_events_for_trial(
        trial_start: int,
        trial_end: int,
    ) -> list[dict[str, np.ndarray]]:
        events: list[dict[str, np.ndarray]] = []
        if plateau_starts.size == 0 or plateau_ends.size == 0:
            return events
        window_frames = max(0, int(round(float(plateau_trace_window_ms) / 1000.0 * float(frame_rate))))
        n_plateau = int(min(plateau_starts.size, plateau_ends.size))
        for p_start_raw, p_end_raw in zip(plateau_starts[:n_plateau], plateau_ends[:n_plateau]):
            p_start = int(p_start_raw)
            p_end = int(p_end_raw)
            if p_end < p_start:
                p_end = p_start
            if p_end < int(trial_start) or p_start >= int(trial_end):
                continue
            snippet_start = max(0, p_start - window_frames)
            snippet_end = min(int(len(trace)), p_end + window_frames + 1)
            if snippet_end <= snippet_start:
                continue
            seg = np.asarray(trace[snippet_start:snippet_end], dtype=float)
            if seg.size == 0 or not np.any(np.isfinite(seg)):
                continue
            frame_idx = np.arange(snippet_start, snippet_end, dtype=float)
            x_ms = (frame_idx - float(p_start)) / float(frame_rate) * 1000.0
            plateau_end_ms = (float(p_end) + 1.0 - float(p_start)) / float(frame_rate) * 1000.0
            events.append(
                {
                    "x_ms": np.asarray(x_ms, dtype=np.float32),
                    "trace_spkh": np.asarray(seg, dtype=np.float32),
                    "plateau_start_ms": 0.0,
                    "plateau_end_ms": float(plateau_end_ms),
                    "plateau_trace_window_ms": float(plateau_trace_window_ms),
                    "plateau_start_frame": int(p_start),
                    "plateau_end_frame": int(p_end),
                    "trial_start_frame": int(trial_start),
                    "trial_end_frame": int(trial_end),
                }
            )
        return events

    baseline_start_offset = int(round(2.0 * frame_rate))
    baseline_end_offset = int(round(1.0 * frame_rate))
    vms_cell = np.asarray(vms[cell_idx], dtype=float)
    trial_payloads: list[dict[str, Any]] = []
    for tr in trials:
        start = int(tr["epoch_start"])
        end = int(tr["epoch_end"])
        center_idx = int(tr["center_idx"])
        if end <= start or center_idx < start or center_idx >= end:
            continue
        if bool(exclude_trials_with_bad_frames) and bad_mask is not None and np.any(bad_mask[start:end]):
            continue
        if session_start_arr is not None:
            session_idx = int(np.searchsorted(session_start_arr, start, side="right") - 1)
            if session_indices is not None and session_idx not in session_indices:
                continue
        else:
            session_idx = 0
        x_seg_full = np.asarray(x_neural[start:end], dtype=float)
        y_seg_full = np.asarray(y_neural[start:end], dtype=float)
        center_local_full = int(center_idx - start)
        signed_distance_full = _compute_signed_distance_from_center(
            x_seg_full,
            y_seg_full,
            center_local=int(center_local_full),
            pf_peak_xy=pf_peak_xy,
            distance_mode=distance_mode,
        )
        if signed_distance_full is None or signed_distance_full.size == 0 or not np.all(np.isfinite(signed_distance_full)):
            continue
        left_candidates = np.where(signed_distance_full[:center_local_full + 1] <= -distance_window_cm)[0]
        right_candidates = np.where(signed_distance_full[center_local_full:] >= distance_window_cm)[0]
        if left_candidates.size == 0 or right_candidates.size == 0:
            continue
        start_local = int(left_candidates[-1])
        end_local = int(center_local_full + right_candidates[0])
        if end_local <= start_local:
            continue
        start = int(start + start_local)
        end = int(start + (end_local - start_local + 1))
        center_local = int(center_local_full - start_local)
        signed_distance = np.asarray(
            signed_distance_full[start_local:end_local + 1],
            dtype=float,
        )

        speed_seg = np.asarray(speed[start:end], dtype=float)
        rest_mask = np.isfinite(speed_seg) & (speed_seg < float(resting_speed_threshold))
        valid_local = valid_frame_mask[start:end] & np.isfinite(signed_distance)
        x_seg = np.asarray(x_neural[start:end], dtype=float)
        y_seg = np.asarray(y_neural[start:end], dtype=float)
        in_pf_local = core._positions_in_place_field(
            x_seg,
            y_seg,
            pf_bins,
            np.asarray(place_field_mask, dtype=bool),
        )
        # Keep only trials that actually entered this PF at least once.
        if not np.any(in_pf_local & valid_local):
            continue
        bin_idx = np.digitize(signed_distance, bin_edges) - 1
        bin_valid = (bin_idx >= 0) & (bin_idx < n_bins)
        include_local = valid_local & bin_valid & (~rest_mask)
        if not np.any(include_local):
            continue
        occupancy_counts = np.bincount(bin_idx[include_local], minlength=n_bins).astype(float)
        occupancy_sec = occupancy_counts / float(frame_rate)
        # Guard against inflated rates from very small occupancy.
        min_frames_per_bin = 2.0
        low_occupancy_bins = occupancy_counts < min_frames_per_bin

        base_start = max(start - baseline_start_offset, 0)
        base_end = max(start - baseline_end_offset, 0)
        baseline_theta = np.nanmean(theta_amp[base_start:base_end]) if base_end > base_start else np.nan
        baseline_slow = np.nanmean(slow_vm[base_start:base_end]) if base_end > base_start else np.nan
        theta_seg = theta_amp[start:end].copy()
        slow_seg = slow_vm[start:end].copy()
        if bool(subtract_pre_traversal_baseline) and np.isfinite(baseline_theta):
            theta_seg = theta_seg - baseline_theta
        if bool(subtract_pre_traversal_baseline) and np.isfinite(baseline_slow):
            slow_seg = slow_seg - baseline_slow

        def _mean_per_bin(values: np.ndarray) -> np.ndarray:
            out = np.full(n_bins, np.nan, dtype=float)
            mask = include_local & np.isfinite(values)
            if np.any(mask):
                counts = np.bincount(bin_idx[mask], minlength=n_bins).astype(float)
                sums = np.bincount(bin_idx[mask], weights=np.asarray(values[mask], dtype=float), minlength=n_bins)
                valid_counts = counts > 0
                out[valid_counts] = sums[valid_counts] / counts[valid_counts]
            out[low_occupancy_bins] = np.nan
            return out

        theta_trial = _mean_per_bin(theta_seg)
        slow_trial = _mean_per_bin(slow_seg)
        frame_to_bin = np.full(end - start, -1, dtype=int)
        frame_to_bin[include_local] = bin_idx[include_local]

        def _rate_per_bin(spike_indices: np.ndarray) -> tuple[np.ndarray, int]:
            counts = np.zeros(n_bins, dtype=float)
            if spike_indices.size == 0:
                with np.errstate(divide="ignore", invalid="ignore"):
                    rates_empty = np.where(occupancy_sec > 0, counts / occupancy_sec, np.nan)
                return rates_empty, 0
            left = int(np.searchsorted(spike_indices, start, side="left"))
            right = int(np.searchsorted(spike_indices, end, side="left"))
            spike_local = spike_indices[left:right] - start
            spike_local = spike_local[(spike_local >= 0) & (spike_local < (end - start))]
            spike_bins = frame_to_bin[spike_local]
            spike_bins = spike_bins[spike_bins >= 0]
            if spike_bins.size > 0:
                counts = np.bincount(spike_bins, minlength=n_bins).astype(float)
            with np.errstate(divide="ignore", invalid="ignore"):
                rates = np.where(occupancy_sec > 0, counts / occupancy_sec, np.nan)
            rates[low_occupancy_bins] = np.nan
            return rates, int(spike_bins.size)

        rate_trial, n_spk_all = _rate_per_bin(all_spike_indices)
        ss_rate_trial, n_spk_ss = _rate_per_bin(ss_indices)
        cs_rate_trial, n_spk_cs = _rate_per_bin(cs_indices)
        denom = ss_rate_trial + cs_rate_trial
        with np.errstate(divide="ignore", invalid="ignore"):
            ss_pct_trial = np.where(np.isfinite(denom) & (denom > 0), 100.0 * ss_rate_trial / denom, np.nan)
            cs_pct_trial = np.where(np.isfinite(denom) & (denom > 0), 100.0 * cs_rate_trial / denom, np.nan)

        plateau_trial = np.zeros(n_bins, dtype=float)
        plateau_presence = np.zeros(end - start, dtype=bool)
        for ps, pe in zip(plateau_starts, plateau_ends):
            overlap_start = max(int(ps), start)
            overlap_end = min(int(pe) + 1, end)
            if overlap_start < overlap_end:
                plateau_presence[(overlap_start - start):(overlap_end - start)] = True
        plateau_include_local = valid_local & bin_valid if bool(include_resting_plateaus) else include_local
        plateau_mask = plateau_include_local & plateau_presence
        if np.any(plateau_mask):
            plateau_values = vms_cell[start:end].copy()
            if bool(subtract_pre_traversal_baseline) and np.isfinite(baseline_slow):
                plateau_values = plateau_values - baseline_slow
            counts = np.bincount(bin_idx[plateau_mask], minlength=n_bins).astype(float)
            sums = np.bincount(bin_idx[plateau_mask], weights=np.asarray(plateau_values[plateau_mask], dtype=float), minlength=n_bins)
            valid_counts = counts > 0
            plateau_trial[valid_counts] = sums[valid_counts] / counts[valid_counts]
        plateau_trace_events = _extract_plateau_trace_events_for_trial(start, end)

        nonrest_duration_sec = float(np.sum(occupancy_sec))
        traversal_type = core._classify_traversal_direction_pf_entry_exit(
            np.asarray(x_neural[start:end], dtype=float),
            np.asarray(y_neural[start:end], dtype=float),
            pf_peak_xy,
            entry_exit_window_frames=5,
            min_center_radius_cm=1.0,
            min_angle_deg=12.0,
        )
        trial_payloads.append(
            {
                "epoch_start": start,
                "epoch_end": end,
                "center_idx": center_idx,
                "center_vicinity_cm": float(tr.get("center_vicinity_cm", np.nan)),
                "session_idx": session_idx,
                "traversal_type": traversal_type,
                "pf_entry_rel": float(np.nanmin(signed_distance)),
                "pf_exit_rel": float(np.nanmax(signed_distance)),
                "n_plateaus": int(np.any(plateau_presence)),
                "n_spikes_all": int(n_spk_all),
                "n_spikes_ss": int(n_spk_ss),
                "n_spikes_cs": int(n_spk_cs),
                "nonrest_duration_sec": nonrest_duration_sec,
                "theta_trial": theta_trial,
                "slow_trial": slow_trial,
                "rate_trial": rate_trial,
                "ss_rate_trial": ss_rate_trial,
                "cs_rate_trial": cs_rate_trial,
                "ss_pct_trial": ss_pct_trial,
                "cs_pct_trial": cs_pct_trial,
                "plateau_trial": plateau_trial,
                "plateau_trace_events": plateau_trace_events,
            }
        )

    if len(trial_payloads) > 1:
        trial_payloads = sorted(
            trial_payloads,
            key=lambda t: (int(t["epoch_start"]), int(t["epoch_end"]), int(t["center_idx"])),
        )
    if len(trial_payloads) < int(min_traversals):
        return None
    all_result = _aggregate_distance_defined_trials(trial_payloads, distance_rel, frame_rate=float(frame_rate))
    cw_trials = [t for t in trial_payloads if str(t.get("traversal_type", "")) == "cw"]
    ccw_trials = [t for t in trial_payloads if str(t.get("traversal_type", "")) == "ccw"]
    cw_result = _aggregate_distance_defined_trials(cw_trials, distance_rel, frame_rate=float(frame_rate))
    ccw_result = _aggregate_distance_defined_trials(ccw_trials, distance_rel, frame_rate=float(frame_rate))
    return {
        "cell_idx": int(cell_idx),
        "pf_peak_xy": pf_peak_xy,
        "place_field_mask": np.asarray(place_field_mask, dtype=bool),
        "rate_map": np.asarray(rate_map, dtype=float),
        "pf_bins": pf_bins,
        "center_by_pf_position": True,
        "require_movement": True,
        "distance_rel": distance_rel,
        "distance_window_cm": float(distance_window_cm),
        "distance_window_cm_requested": float(distance_window_cm_req),
        "distance_window_cm_effective": float(distance_window_cm_eff),
        "detection_window_cm": float(detection_window_cm_eff),
        "detection_window_cm_requested": float(detection_window_cm_req),
        "detection_window_cm_effective": float(detection_window_cm_eff),
        "distance_bin_cm": float(distance_bin_cm),
        "distance_mode": str(distance_mode),
        "include_long_cb_as_plateau": bool(include_long_cb_as_plateau),
        "include_resting_plateaus": bool(include_resting_plateaus),
        "cb_plateau_min_duration_ms": float(cb_plateau_min_duration_ms),
        "center_vicinity_min_cm": int(center_vicinity_min_cm),
        "center_vicinity_max_cm": int(center_vicinity_max_cm),
        "moving_speed_threshold": float(moving_speed_threshold),
        "resting_speed_threshold": float(resting_speed_threshold),
        "all": all_result,
        "cw": cw_result,
        "ccw": ccw_result,
    }


def _build_trial_plot_runtime_payload(
    animal_id: str,
    config: PipelineConfig,
) -> dict[str, Any]:
    animal_dir = config.data_root / animal_id
    merged = _load_merged_data(animal_dir, config)
    merged = _clean_behavior_speed_outliers_for_cache(merged, config, animal_id=animal_id)
    spatial_by_idx = _load_spatial_analysis_by_idx(animal_dir)

    # Match Figures.ipynb behavior: trial plots use SNR-interpolated traces.
    traces_raw = merged.get("traces_SNR_interpolated", merged.get("traces"))
    if traces_raw is None:
        raise KeyError(f"Missing traces for {animal_id}")
    traces = np.asarray(traces_raw, dtype=object)
    vms = np.asarray(merged.get("Vm_SNR_interpolated", traces), dtype=object)

    bad_masks = _compute_bad_masks(
        merged,
        config.analysis.snr_threshold,
        config.analysis.min_good_minutes,
    )
    n_cells = int(len(bad_masks))
    n_kept = int(np.sum(~np.all(bad_masks, axis=1))) if n_cells > 0 else 0
    print(
        f"{animal_id}: SNR filter kept {n_kept}/{n_cells} cells "
        f"(threshold={config.analysis.snr_threshold}, min_good_minutes={config.analysis.min_good_minutes})."
    )
    return {
        "merged": merged,
        "spatial_by_idx": spatial_by_idx,
        "traces": traces,
        "vms": vms,
        "bad_masks": bad_masks,
    }


def generate_bin_by_bin_directionality_plots(
    config: PipelineConfig,
    spatial_data: Any,
    *,
    figure_save_folder: str | Path | None = None,
    categories: tuple[str, ...] = ("CSplus", "CSminus", "non-PLC"),
    first_n_minutes: float | None = None,
    direction_mode: str = "head",
    clear_output: bool = True,
    width_real: float = 35.5,
    height_real: float = 20.0,
    bin_size: float = 4.0,
    kernel_size: int | None = None,
    filter_type: str = "boxcar",
    speed_threshold: float | None = None,
    min_duration_s: float | None = None,
    merge_gap_s: float | None = None,
    min_spikes_per_bin: int = 10,
    min_visited_angle_bins: int = 2,
    min_visited_angle_separation_deg: float = 45.0,
    min_occ_frames_per_angle: int = 100,
    hd_count_smooth_sigma: float = 0.0,
    min_pref_vector_strength: float = 0.0,
    preferred_angle_mode: str = "peak_cluster_mean",
    pref_angle_std_threshold: float = 0.0,
    hd_bin_size_deg: float = 30.0,
    travel_smooth_window: int = 5,
    travel_min_step: float = 0.0,
    show_trajectory: bool = True,
    use_normalized_rate: bool = False,
    max_arrow_length: float | str | None = "pf_peak",
    max_arrow_std_factor: float | None = None,
    polar_smooth_sigma: float = 1.0,
    pf_bg_alpha: float = 0.05,
    tuning_curve_color: str = "red",
    mini_pref_arrow_length_mode: str = "vector_strength",
    mini_pref_arrow_length_min: float = 0.15,
    mini_pref_arrow_length_max: float = 0.95,
    occupancy_style: str = "fan",
    tuning_style: str = "fan",
    right_panel_width_mode: str | float = "auto",
    figsize_base: tuple[float, float] = (6.5, 5.0),
    save_prefix: str | None = None,
    save_ext: str = "svg",
    close_figures: bool = True,
    return_data: bool = False,
    hd_info_null_mode: str = "timeshift",
    hd_time_shift_min_s: float = 10.0,
    hd_time_shift_sessionwise: bool = True,
) -> dict[str, Any]:
    """
    Run bin-by-bin directionality figures (vector maps + polar panels) by category.

    This mirrors the workflow used in Figures.ipynb and batches one figure per cell
    via `plot_hd_vector_fields_all_cells_moving_with_bin_polar`, organizing outputs as:
      <figure_save_folder>/bin_by_bin_directionality_<mode>/<category>/...
    with animal-id-prefixed filenames to avoid collisions across sessions.

    Parameters
    ----------
    first_n_minutes : float or None, optional
        If provided, only the first N minutes of each animal's concatenated
        recording are included in the analysis. Frames after this cutoff are
        excluded via bad-frame masking.
    """
    mode = str(direction_mode).strip().lower()
    if mode not in {"head", "travel"}:
        raise ValueError("direction_mode must be 'head' or 'travel'.")

    if kernel_size is None:
        kernel_size = int(config.analysis.kernel_size)
    if speed_threshold is None:
        speed_threshold = float(config.analysis.speed_threshold)
    if min_duration_s is None:
        min_duration_s = float(config.analysis.min_duration_s)
    if merge_gap_s is None:
        merge_gap_s = float(config.analysis.merge_gap_s)
    if first_n_minutes is not None:
        first_n_minutes = float(first_n_minutes)
        if (not np.isfinite(first_n_minutes)) or first_n_minutes <= 0:
            raise ValueError("first_n_minutes must be a positive finite value when provided.")

    if figure_save_folder is None:
        figure_root = config.figures_root / "CKII_pooled"
    else:
        figure_root = Path(figure_save_folder)
    root_dir = figure_root / f"bin_by_bin_directionality_{mode}"
    root_dir.mkdir(parents=True, exist_ok=True)

    if clear_output and root_dir.exists():
        shutil.rmtree(root_dir)
        root_dir.mkdir(parents=True, exist_ok=True)

    runtime_cache: dict[str, dict[str, Any]] = {}
    category_payload: dict[str, Any] = {}

    def _bump_reason(reason_map: dict[str, int], reason: str) -> None:
        reason_map[reason] = int(reason_map.get(reason, 0)) + 1

    for category in categories:
        cat = _normalize_pf_category_name(category)
        cat_cells = _get_spatial_category_cells(spatial_data, cat)
        cat_dir = root_dir / cat
        cat_dir.mkdir(parents=True, exist_ok=True)

        cat_summary: dict[str, Any] = {
            "output_dir": str(cat_dir),
            "attempted": 0,
            "saved": 0,
            "skipped": 0,
            "skip_reasons": {},
            "animals": {},
        }
        per_animal_candidates: dict[str, set[int]] = {}

        for cell_meta in cat_cells:
            cat_summary["attempted"] = int(cat_summary["attempted"]) + 1
            animal_id = str(cell_meta.get("session", "")).strip()
            try:
                cell_idx = int(cell_meta.get("cell_idx", -1))
            except Exception:
                cell_idx = -1
            if not animal_id or cell_idx < 0:
                cat_summary["skipped"] = int(cat_summary["skipped"]) + 1
                _bump_reason(cat_summary["skip_reasons"], "invalid_cell_meta")
                continue
            if animal_id not in per_animal_candidates:
                per_animal_candidates[animal_id] = set()
            per_animal_candidates[animal_id].add(cell_idx)

        for animal_id in sorted(per_animal_candidates.keys()):
            animal_summary: dict[str, Any] = {
                "output_dir": str(cat_dir),
                "attempted": int(len(per_animal_candidates[animal_id])),
                "saved": 0,
                "skipped": 0,
                "skip_reasons": {},
                "cell_order": [],
                "saved_cell_ids": [],
                "save_prefix": "",
            }

            try:
                if animal_id not in runtime_cache:
                    runtime_cache[animal_id] = _build_trial_plot_runtime_payload(animal_id, config)
                runtime = runtime_cache[animal_id]
                merged = runtime["merged"]
                spatial_by_idx = runtime["spatial_by_idx"]
            except Exception as exc:
                reason = f"runtime_load_error:{type(exc).__name__}"
                n_cells = int(len(per_animal_candidates[animal_id]))
                animal_summary["skipped"] = n_cells
                _bump_reason(animal_summary["skip_reasons"], reason)
                cat_summary["skipped"] = int(cat_summary["skipped"]) + n_cells
                _bump_reason(cat_summary["skip_reasons"], reason)
                cat_summary["animals"][animal_id] = animal_summary
                continue

            eligible_cells: list[int] = []
            for cell_idx in sorted(per_animal_candidates[animal_id]):
                analysis = spatial_by_idx.get(int(cell_idx))
                if not isinstance(analysis, dict):
                    animal_summary["skipped"] = int(animal_summary["skipped"]) + 1
                    cat_summary["skipped"] = int(cat_summary["skipped"]) + 1
                    _bump_reason(animal_summary["skip_reasons"], "missing_spatial_analysis")
                    _bump_reason(cat_summary["skip_reasons"], "missing_spatial_analysis")
                    continue
                if cat == "nonPLC":
                    if bool(analysis.get("is_place_cell", False)):
                        animal_summary["skipped"] = int(animal_summary["skipped"]) + 1
                        cat_summary["skipped"] = int(cat_summary["skipped"]) + 1
                        _bump_reason(animal_summary["skip_reasons"], "nonplc_is_place_cell")
                        _bump_reason(cat_summary["skip_reasons"], "nonplc_is_place_cell")
                        continue
                    if not bool(analysis.get("is_place_cell_ss", False)):
                        animal_summary["skipped"] = int(animal_summary["skipped"]) + 1
                        cat_summary["skipped"] = int(cat_summary["skipped"]) + 1
                        _bump_reason(animal_summary["skip_reasons"], "nonplc_not_ss_place_cell")
                        _bump_reason(cat_summary["skip_reasons"], "nonplc_not_ss_place_cell")
                        continue
                eligible_cells.append(int(cell_idx))

            if len(eligible_cells) == 0:
                cat_summary["animals"][animal_id] = animal_summary
                continue

            n_cells_total = int(len(merged.get("spikes", [])))
            pc_output_all: list[Any] = [None] * n_cells_total
            for idx, analysis in spatial_by_idx.items():
                try:
                    i = int(idx)
                except Exception:
                    continue
                if 0 <= i < n_cells_total:
                    pc_output_all[i] = analysis

            bad_masks_for_plot = runtime.get("bad_masks", None)
            if first_n_minutes is not None:
                frame_rate = float(merged["frame_rate"])
                n_frames = int(len(np.asarray(merged["x_neural"], dtype=float)))
                cutoff_frame = int(np.floor(first_n_minutes * 60.0 * frame_rate))
                cutoff_frame = max(1, min(n_frames, cutoff_frame))
                animal_summary["analysis_frame_cutoff"] = int(cutoff_frame)
                animal_summary["analysis_duration_minutes"] = float(first_n_minutes)
                if cutoff_frame < n_frames:
                    tail_bad_mask = np.zeros(n_frames, dtype=bool)
                    tail_bad_mask[cutoff_frame:] = True
                    if bad_masks_for_plot is None:
                        bad_masks_for_plot = np.tile(tail_bad_mask[None, :], (n_cells_total, 1))
                    else:
                        bad_masks_arr = np.asarray(bad_masks_for_plot, dtype=bool)
                        if bad_masks_arr.ndim == 1:
                            if bad_masks_arr.size != n_frames:
                                raise ValueError(
                                    "runtime bad-mask length does not match x_neural length."
                                )
                            bad_masks_for_plot = bad_masks_arr | tail_bad_mask
                        elif bad_masks_arr.ndim == 2:
                            if bad_masks_arr.shape[1] != n_frames:
                                raise ValueError(
                                    "runtime bad-mask frame dimension does not match x_neural length."
                                )
                            bad_masks_for_plot = bad_masks_arr | tail_bad_mask[None, :]
                        else:
                            raise ValueError("runtime bad_masks must be 1D or 2D when provided.")

            base_prefix = (
                str(save_prefix).strip()
                if isinstance(save_prefix, str) and str(save_prefix).strip()
                else f"bin_by_bin_{mode}"
            )
            local_prefix = f"{base_prefix}_{animal_id}"
            animal_summary["save_prefix"] = str(local_prefix)
            try:
                outputs = core.plot_hd_vector_fields_all_cells_moving_with_bin_polar(
                    np.asarray(merged["x_neural"], dtype=float),
                    np.asarray(merged["y_neural"], dtype=float),
                    np.asarray(merged["hd_angles_neural"], dtype=float),
                    merged.get("all_spikes", merged.get("spikes", [])),
                    np.asarray(merged["speed"], dtype=float),
                    float(merged["frame_rate"]),
                    refined_SS=merged.get("refined_SS", None),
                    all_CS_spikes=merged.get("all_CS_spikes", None),
                    pc_output_all=pc_output_all,
                    cell_order=eligible_cells,
                    width_real=float(width_real),
                    height_real=float(height_real),
                    bin_size=float(bin_size),
                    kernel_size=int(kernel_size),
                    filter_type=str(filter_type),
                    speed_threshold=float(speed_threshold),
                    min_duration_s=float(min_duration_s),
                    merge_gap_s=float(merge_gap_s),
                    bad_timepoints_all=bad_masks_for_plot,
                    min_spikes_per_bin=int(min_spikes_per_bin),
                    min_visited_angle_bins=int(min_visited_angle_bins),
                    min_visited_angle_separation_deg=float(min_visited_angle_separation_deg),
                    min_occ_frames_per_angle=int(min_occ_frames_per_angle),
                    hd_count_smooth_sigma=float(hd_count_smooth_sigma),
                    min_pref_vector_strength=float(min_pref_vector_strength),
                    preferred_angle_mode=str(preferred_angle_mode),
                    pref_angle_std_threshold=float(pref_angle_std_threshold),
                    hd_bin_size_deg=float(hd_bin_size_deg),
                    direction_mode=mode,
                    travel_smooth_window=int(travel_smooth_window),
                    travel_min_step=float(travel_min_step),
                    show_trajectory=bool(show_trajectory),
                    use_normalized_rate=bool(use_normalized_rate),
                    max_arrow_length=max_arrow_length,
                    max_arrow_std_factor=max_arrow_std_factor,
                    polar_smooth_sigma=float(polar_smooth_sigma),
                    pf_bg_alpha=float(pf_bg_alpha),
                    tuning_curve_color=str(tuning_curve_color),
                    mini_pref_arrow_length_mode=str(mini_pref_arrow_length_mode),
                    mini_pref_arrow_length_min=float(mini_pref_arrow_length_min),
                    mini_pref_arrow_length_max=float(mini_pref_arrow_length_max),
                    occupancy_style=str(occupancy_style),
                    tuning_style=str(tuning_style),
                    hd_info_null_mode=str(hd_info_null_mode),
                    hd_time_shift_min_s=float(hd_time_shift_min_s),
                    hd_time_shift_sessionwise=bool(hd_time_shift_sessionwise),
                    right_panel_width_mode=right_panel_width_mode,
                    figsize_base=tuple(figsize_base),
                    save_dir=str(cat_dir),
                    save_prefix=local_prefix,
                    save_ext=str(save_ext),
                    close_figures=bool(close_figures),
                    return_data=bool(return_data),
                    session_start_frames=merged.get("session_start_frames", [0]),
                )
            except Exception as exc:
                reason = f"render_error:{type(exc).__name__}"
                n_cells = int(len(eligible_cells))
                animal_summary["skipped"] = int(animal_summary["skipped"]) + n_cells
                cat_summary["skipped"] = int(cat_summary["skipped"]) + n_cells
                _bump_reason(animal_summary["skip_reasons"], reason)
                _bump_reason(cat_summary["skip_reasons"], reason)
                cat_summary["animals"][animal_id] = animal_summary
                continue

            saved_n = int(len(outputs))
            animal_summary["saved"] = saved_n
            animal_summary["cell_order"] = [int(i) for i in eligible_cells]
            animal_summary["saved_cell_ids"] = [int(o.get("cell_id", -1)) for o in outputs]
            cat_summary["saved"] = int(cat_summary["saved"]) + saved_n
            if saved_n < len(eligible_cells):
                miss_n = int(len(eligible_cells) - saved_n)
                animal_summary["skipped"] = int(animal_summary["skipped"]) + miss_n
                cat_summary["skipped"] = int(cat_summary["skipped"]) + miss_n
                _bump_reason(animal_summary["skip_reasons"], "partial_save")
                _bump_reason(cat_summary["skip_reasons"], "partial_save")

            cat_summary["animals"][animal_id] = animal_summary

        category_payload[cat] = cat_summary

    return {
        "direction_mode": mode,
        "first_n_minutes": (
            None if first_n_minutes is None else float(first_n_minutes)
        ),
        "hd_info_null_mode": str(hd_info_null_mode),
        "hd_time_shift_min_s": float(hd_time_shift_min_s),
        "hd_time_shift_sessionwise": bool(hd_time_shift_sessionwise),
        "root_output_dir": str(root_dir),
        "categories": category_payload,
    }


def generate_trial_by_trial_plc_plots(
    config: PipelineConfig,
    spatial_data: Any,
    figure_save_folder: str | Path | None = None,
    *,
    clear_output: bool = True,
    save_summary_csv: bool = True,
    show_plots: bool = False,
    show_rest_patches: bool = True,
    show_pf_prepost_patches: bool = False,
    pf_prepost_patch_alpha: float = 0.05,
    pf_reliability_dilation_bins: int | None = None,
    pf_reliability_dilation_shape: str | None = None,
    traversal_merge_gap_s: float | None = None,
    trace_slow_gap: float = 1.0,
    theta_slow_pad_factor: float = 0.05,
    sharey: bool = False,
) -> dict[str, Any]:
    """
    Generate trial-by-trial traversal plots for CS+ and CS- PLCs.

    The source PFs are reliability-filtered `place_field_components` from
    `spatial_analysis_full.pkl`. Each PF component of each PLC gets its own figure.
    Dilation and stacked-trace spacing can be overridden per call.
    Trajectory contours are PF-rank coded (PF1=magenta, PF2=cyan). For cells with
    at least two PFs, both PF1 and PF2 contours are shown on each trajectory panel.
    Optionally shade pre/post periods where trajectory passes through PF1/PF2 on
    trace panels (PF1 magenta, PF2 cyan), with configurable alpha.
    Set `sharey=True` to enforce shared trial-axis y-limits and shared slow/theta
    vertical offsets across all trials within each figure.
    """
    import pandas as pd
    from scipy.ndimage import binary_dilation

    if figure_save_folder is None:
        figure_root = config.figures_root / "CKII_pooled"
    else:
        figure_root = Path(figure_save_folder)
    figure_root.mkdir(parents=True, exist_ok=True)

    csplus_dir = figure_root / "PF_traversal_trials_CSplus_PLCs"
    csminus_dir = figure_root / "PF_traversal_trials_CSminus_PLCs"
    summary_csv = figure_root / "PF_traversal_trials_summary.csv"

    if clear_output:
        for out_dir in (csplus_dir, csminus_dir):
            if out_dir.exists():
                shutil.rmtree(out_dir)
            out_dir.mkdir(parents=True, exist_ok=True)
    else:
        csplus_dir.mkdir(parents=True, exist_ok=True)
        csminus_dir.mkdir(parents=True, exist_ok=True)

    trial_speed_threshold = float(config.analysis.speed_threshold)
    trial_resting_speed_threshold = 0.0
    trial_theta_freqs = tuple(config.analysis.theta_freqs)
    trial_slow_freqs = float(config.analysis.slow_freqs)
    trial_min_duration_ms = float(config.traversal.min_duration_ms)
    trial_min_distance_cm = float(config.traversal.min_distance_cm)
    trial_clear_traversal = bool(config.traversal.clear_traversal)
    trial_session_indices = tuple(config.traversal.session_indices)
    trial_pf_center_window_sec = float(config.traversal.pf_center_window_sec)
    trial_min_traversals = int(config.traversal.min_traversals)
    trial_firing_rate_bin_ms = float(config.traversal.firing_rate_bin_ms)
    trial_firing_rate_smooth_ms = float(config.traversal.firing_rate_smooth_ms)
    trial_max_pf_distance_cm = config.traversal.max_pf_distance_cm
    trial_pf_component_selection = str(config.traversal.pf_component_selection)
    trial_center_by_pf_position = bool(config.traversal.center_by_pf_position)
    if traversal_merge_gap_s is None:
        trial_traversal_merge_gap_s = float(getattr(config.traversal, "traversal_merge_gap_s", 1.0))
    else:
        trial_traversal_merge_gap_s = float(traversal_merge_gap_s)
    if trial_traversal_merge_gap_s < 0:
        raise ValueError("traversal_merge_gap_s must be >= 0.")

    if pf_reliability_dilation_bins is None:
        dilation_bins = int(config.place_cell.pf_reliability_dilation_bins)
    else:
        dilation_bins = int(pf_reliability_dilation_bins)
    if pf_reliability_dilation_shape is None:
        dilation_shape = str(config.place_cell.pf_reliability_dilation_shape).strip().lower()
    else:
        dilation_shape = str(pf_reliability_dilation_shape).strip().lower()
    if dilation_bins < 0:
        raise ValueError("pf_reliability_dilation_bins must be >= 0.")
    trace_slow_gap = float(trace_slow_gap)
    theta_slow_pad_factor = float(theta_slow_pad_factor)
    if trace_slow_gap < 0:
        raise ValueError("trace_slow_gap must be >= 0.")
    if theta_slow_pad_factor < 0:
        raise ValueError("theta_slow_pad_factor must be >= 0.")
    pf_prepost_patch_alpha = float(pf_prepost_patch_alpha)
    if pf_prepost_patch_alpha < 0 or pf_prepost_patch_alpha > 1:
        raise ValueError("pf_prepost_patch_alpha must be in [0, 1].")
    show_pf_prepost_patches = bool(show_pf_prepost_patches)
    show_rest_patches_effective = bool(show_rest_patches) and (not show_pf_prepost_patches)
    dilation_structure = (
        core._build_pf_dilation_structure(dilation_bins, dilation_shape)
        if dilation_bins > 0
        else None
    )

    category_specs = [
        ("CSplus", getattr(spatial_data, "plcs_csplus", []), csplus_dir),
        ("CSminus", getattr(spatial_data, "plcs_csminus", []), csminus_dir),
    ]

    runtime_cache: dict[str, dict[str, Any]] = {}
    summary_rows: list[dict[str, Any]] = []
    category_counters: dict[str, dict[str, int]] = {}

    for category_name, category_cells, out_dir in category_specs:
        category_counters[category_name] = {
            "attempted_cells": 0,
            "attempted_components": 0,
            "saved": 0,
            "skipped_or_error": 0,
        }

        for cell_meta in category_cells:
            animal_id = str(cell_meta.get("session", ""))
            cell_idx = int(cell_meta.get("cell_idx", -1))
            category_counters[category_name]["attempted_cells"] += 1

            if not animal_id or cell_idx < 0:
                summary_rows.append(
                    {
                        "category": category_name,
                        "animal_id": animal_id,
                        "cell_idx": cell_idx,
                        "cell_num": np.nan,
                        "pf_rank": np.nan,
                        "status": "skip_invalid_cell_meta",
                        "n_traversals": np.nan,
                        "message": "missing session or invalid cell_idx",
                    }
                )
                category_counters[category_name]["skipped_or_error"] += 1
                continue

            try:
                if animal_id not in runtime_cache:
                    runtime_cache[animal_id] = _build_trial_plot_runtime_payload(animal_id, config)
                runtime = runtime_cache[animal_id]

                merged = runtime["merged"]
                spatial_by_idx = runtime["spatial_by_idx"]
                analysis = spatial_by_idx.get(cell_idx)
                if analysis is None:
                    summary_rows.append(
                        {
                            "category": category_name,
                            "animal_id": animal_id,
                            "cell_idx": cell_idx,
                            "cell_num": cell_idx + 1,
                            "pf_rank": np.nan,
                            "status": "skip_missing_analysis",
                            "n_traversals": np.nan,
                            "message": "cell analysis missing in spatial_analysis_full.pkl",
                        }
                    )
                    category_counters[category_name]["skipped_or_error"] += 1
                    continue

                if not bool(analysis.get("is_place_cell", False)):
                    summary_rows.append(
                        {
                            "category": category_name,
                            "animal_id": animal_id,
                            "cell_idx": cell_idx,
                            "cell_num": cell_idx + 1,
                            "pf_rank": np.nan,
                            "status": "skip_not_place_cell",
                            "n_traversals": np.nan,
                            "message": "analysis is not place cell",
                        }
                    )
                    category_counters[category_name]["skipped_or_error"] += 1
                    continue

                components = _sanitize_ranked_pf_components(
                    list(analysis.get("place_field_components", []) or []),
                    np.asarray(analysis.get("place_field_mask", []), dtype=bool),
                    rate_map=np.asarray(analysis.get("rate_map", []), dtype=float),
                    fallback_peak_rate=float(analysis.get("peak_rate", np.nan)),
                    max_components=None,
                )
                if not components:
                    summary_rows.append(
                        {
                            "category": category_name,
                            "animal_id": animal_id,
                            "cell_idx": cell_idx,
                            "cell_num": cell_idx + 1,
                            "pf_rank": np.nan,
                            "status": "skip_no_place_field_mask",
                            "n_traversals": np.nan,
                            "message": "no PF components and empty PF mask",
                        }
                    )
                    category_counters[category_name]["skipped_or_error"] += 1
                    continue

                # Prepare per-component masks used in reliability-aware traversal analysis,
                # and contour overlays for trajectory plots (PF1=magenta, PF2=cyan).
                rank_to_eval_mask: dict[int, np.ndarray] = {}
                trajectory_contours: list[dict[str, Any]] = []
                for rank_i, comp_i in enumerate(components, start=1):
                    comp_mask_i = np.asarray(comp_i.get("mask", []), dtype=bool)
                    if comp_mask_i.size == 0 or not np.any(comp_mask_i):
                        continue
                    comp_eval_i = comp_mask_i
                    if dilation_structure is not None:
                        comp_eval_i = binary_dilation(comp_mask_i, structure=dilation_structure)
                    rank_to_eval_mask[int(rank_i)] = np.asarray(comp_eval_i, dtype=bool)
                    if rank_i <= 2:
                        trajectory_contours.append(
                            {
                                "mask": np.asarray(comp_eval_i, dtype=bool),
                                "color": "magenta" if rank_i == 1 else "cyan",
                                "linewidth": 0.8,
                                "linestyle": "solid",
                                "alpha": 1.0,
                            }
                        )

                traces = runtime["traces"]
                vms = runtime["vms"]
                frame_rate = float(merged["frame_rate"])
                x_neural = np.asarray(merged["x_neural"], dtype=float)
                y_neural = np.asarray(merged["y_neural"], dtype=float)
                speed = np.asarray(merged["speed"], dtype=float)
                spikes = merged["spikes"]
                all_spikes = merged.get("all_spikes", merged["spikes"])
                refined_ss = merged.get("refined_SS", [np.array([], dtype=int) for _ in spikes])
                all_cs_spikes = merged.get("all_CS_spikes", [np.array([], dtype=int) for _ in spikes])
                complex_bursts_dicts = merged.get("complex_bursts_dicts", [])
                plateaus_dicts = merged.get("plateaus_dicts", None)
                session_start_frames = merged.get("session_start_frames", [0])
                bad_timepoints = (
                    runtime["bad_masks"][cell_idx]
                    if isinstance(runtime["bad_masks"], np.ndarray) and cell_idx < len(runtime["bad_masks"])
                    else None
                )
                bad_mask = None
                if bad_timepoints is not None:
                    bad_mask = np.asarray(bad_timepoints, dtype=bool)
                    if bad_mask.shape[0] != x_neural.shape[0]:
                        raise ValueError(
                            f"bad_timepoints length mismatch for {animal_id} cell {cell_idx}."
                        )

                # Strict trial exclusion mask:
                # 1) SNR-derived bad frames, and
                # 2) raw-trace NaN frames (original, non-interpolated trace).
                raw_bad_mask = None
                traces_raw_source = merged.get("traces", None)
                if traces_raw_source is not None and cell_idx < len(traces_raw_source):
                    raw_trace = np.asarray(traces_raw_source[cell_idx], dtype=float)
                    if raw_trace.ndim == 1 and raw_trace.shape[0] == x_neural.shape[0]:
                        raw_bad_mask = ~np.isfinite(raw_trace)

                traversal_bad_mask = None
                if bad_mask is not None and raw_bad_mask is not None:
                    traversal_bad_mask = bad_mask | raw_bad_mask
                elif bad_mask is not None:
                    traversal_bad_mask = bad_mask
                elif raw_bad_mask is not None:
                    traversal_bad_mask = raw_bad_mask

                # Exclude low-SNR segments from behavioral arrays used in traversal finding/plotting.
                x_neural_plot = x_neural.copy()
                y_neural_plot = y_neural.copy()
                speed_plot = speed.copy()
                if traversal_bad_mask is not None:
                    x_neural_plot[traversal_bad_mask] = np.nan
                    y_neural_plot[traversal_bad_mask] = np.nan
                    speed_plot[traversal_bad_mask] = np.nan

                def _filter_spike_indices(spike_source: Any) -> np.ndarray:
                    if isinstance(spike_source, (list, tuple, np.ndarray)):
                        src = spike_source[cell_idx] if isinstance(spike_source, (list, tuple)) else spike_source
                    else:
                        src = np.array([], dtype=int)
                    idx = np.asarray(src, dtype=int)
                    idx = idx[(idx >= 0) & (idx < x_neural.shape[0])]
                    if traversal_bad_mask is not None and idx.size > 0:
                        idx = idx[~traversal_bad_mask[idx]]
                    return idx

                all_spikes_cell = _filter_spike_indices(all_spikes)
                refined_ss_cell = _filter_spike_indices(refined_ss)
                all_cs_spikes_cell = _filter_spike_indices(all_cs_spikes)

                trace = np.asarray(traces[cell_idx], dtype=float)
                trace = core.interpolate_nan_segment(trace)
                theta_vm = core.bandpass_filter(
                    trace,
                    trial_theta_freqs[0],
                    trial_theta_freqs[1],
                    frame_rate,
                    order=5,
                )
                slow_vm = core.lowpass_filter(trace, trial_slow_freqs, frame_rate, order=5)

                base_params = dict(analysis.get("params", {}))
                base_params.setdefault("width_real", 35.5)
                base_params.setdefault("height_real", 20.0)
                base_params.setdefault("bin_size", float(config.place_cell.bin_size))

                for pf_rank, comp in enumerate(components, start=1):
                    category_counters[category_name]["attempted_components"] += 1
                    comp_mask = np.asarray(comp.get("mask", []), dtype=bool)
                    if comp_mask.size == 0 or not np.any(comp_mask):
                        summary_rows.append(
                            {
                                "category": category_name,
                                "animal_id": animal_id,
                                "cell_idx": cell_idx,
                                "cell_num": cell_idx + 1,
                                "pf_rank": pf_rank,
                                "status": "skip_empty_component",
                                "n_traversals": np.nan,
                                "message": "component mask empty",
                            }
                        )
                        category_counters[category_name]["skipped_or_error"] += 1
                        continue

                    pf_mask_eval = rank_to_eval_mask.get(int(pf_rank))
                    if pf_mask_eval is None or pf_mask_eval.size == 0 or not np.any(pf_mask_eval):
                        summary_rows.append(
                            {
                                "category": category_name,
                                "animal_id": animal_id,
                                "cell_idx": cell_idx,
                                "cell_num": cell_idx + 1,
                                "pf_rank": pf_rank,
                                "status": "skip_invalid_eval_mask",
                                "n_traversals": np.nan,
                                "message": "missing/empty reliability-eval PF mask",
                            }
                        )
                        category_counters[category_name]["skipped_or_error"] += 1
                        continue

                    analysis_override = {
                        "is_place_cell": True,
                        "place_field_mask": pf_mask_eval,
                        "rate_map": analysis.get("rate_map", None),
                        "peak_rate": float(comp.get("peak_rate", np.nan)),
                        "params": base_params,
                    }

                    traversal_epochs, place_field_mask, rate_map, pf_bins, traversal_types = core.find_place_field_traversals(
                        x_neural_plot,
                        y_neural_plot,
                        spikes,
                        speed_plot,
                        frame_rate,
                        cell_idx,
                        analysis=analysis_override,
                        speed_threshold=trial_speed_threshold,
                        min_duration_ms=trial_min_duration_ms,
                        place_field_threshold=float(config.place_cell.place_field_threshold),
                        min_distance_cm=trial_min_distance_cm,
                        max_pf_distance_cm=trial_max_pf_distance_cm,
                        clear_traversal=trial_clear_traversal,
                        return_traversal_types=True,
                        pf_component_selection=trial_pf_component_selection,
                        merge_gap_s=trial_traversal_merge_gap_s,
                        bad_timepoints=traversal_bad_mask,
                    )

                    # Enforce strict rule: remove trials with any bad frame inside the
                    # traversal epoch itself (green shaded interval).
                    dropped_bad_in_epoch = 0
                    if traversal_bad_mask is not None and len(traversal_epochs) > 0:
                        epochs_filtered = []
                        types_filtered = []
                        if traversal_types is None or len(traversal_types) != len(traversal_epochs):
                            traversal_types = ["cw"] * len(traversal_epochs)
                        for (epoch_start, epoch_end), ttype in zip(traversal_epochs, traversal_types):
                            s = max(0, int(epoch_start))
                            e = min(int(epoch_end), int(traversal_bad_mask.shape[0]))
                            if e <= s:
                                dropped_bad_in_epoch += 1
                                continue
                            if np.any(traversal_bad_mask[s:e]):
                                dropped_bad_in_epoch += 1
                                continue
                            epochs_filtered.append((s, e))
                            types_filtered.append(ttype)
                        traversal_epochs = epochs_filtered
                        traversal_types = types_filtered

                    if len(traversal_epochs) < trial_min_traversals:
                        summary_rows.append(
                            {
                                "category": category_name,
                                "animal_id": animal_id,
                                "cell_idx": cell_idx,
                                "cell_num": cell_idx + 1,
                                "pf_rank": pf_rank,
                                "status": "skip_insufficient_traversals",
                                "n_traversals": len(traversal_epochs),
                                "message": (
                                    f"< min_traversals ({trial_min_traversals}); "
                                    f"dropped_bad_in_epoch={dropped_bad_in_epoch}"
                                ),
                            }
                        )
                        category_counters[category_name]["skipped_or_error"] += 1
                        continue

                    pf_peak_xy = _compute_pf_peak_xy_from_mask(place_field_mask, rate_map, pf_bins)
                    plot_result = core.plot_place_field_traversal_trials_with_cb_example_centered_by_max_rate(
                        trace,
                        theta_vm,
                        slow_vm,
                        speed_plot,
                        x_neural_plot,
                        y_neural_plot,
                        traversal_epochs,
                        place_field_mask,
                        pf_bins,
                        frame_rate,
                        complex_bursts_dicts=complex_bursts_dicts,
                        cell_idx=cell_idx,
                        traversal_types=traversal_types,
                        padding_sec=trial_pf_center_window_sec,
                        zscore_traces=False,
                        theta_freqs=trial_theta_freqs,
                        slow_freqs=trial_slow_freqs,
                        session_start_frames=session_start_frames,
                        session_indices=trial_session_indices,
                        color_by_session=True,
                        # Keep patch/run state logic consistent with traversal detection.
                        resting_speed_threshold=trial_speed_threshold,
                        show_rest_patches=show_rest_patches_effective,
                        show_pf_prepost_patches=show_pf_prepost_patches,
                        pf_prepost_patch_alpha=pf_prepost_patch_alpha,
                        pf_prepost_patch_defs=trajectory_contours,
                        refined_SS=refined_ss_cell,
                        all_CS_spikes=all_cs_spikes_cell,
                        all_spikes=all_spikes_cell,
                        firing_rate_bin_ms=trial_firing_rate_bin_ms,
                        firing_rate_smooth_ms=trial_firing_rate_smooth_ms,
                        show_firing_rate=False,
                        simple_spike_color="#026C80",
                        complex_spike_color="#EE9B00",
                        pf_peak_xy=pf_peak_xy,
                        pf_center_window_sec=trial_pf_center_window_sec,
                        plot_pf_centered_average=True,
                        return_pf_centered=True,
                        return_spike_rate_means=True,
                        show=show_plots,
                        bad_timepoints=traversal_bad_mask,
                        return_trial_firing_rates=True,
                        center_by_pf_position=trial_center_by_pf_position,
                        max_pf_distance_cm=trial_max_pf_distance_cm,
                        plateaus_dicts=plateaus_dicts,
                        slow_trace_gap=trace_slow_gap,
                        theta_slow_pad_factor=theta_slow_pad_factor,
                        sharey=bool(sharey),
                        place_field_contours=trajectory_contours,
                        pf_occupancy_mask=np.asarray(place_field_contour_mask, dtype=bool),
                        center_position_label=f"Closest to PF{pf_rank}",
                        pf_peak_label=f"PF{pf_rank} peak",
                        pf_peak_color=("magenta" if int(pf_rank) == 1 else "cyan"),
                    )

                    fig = plot_result[0] if isinstance(plot_result, tuple) and len(plot_result) > 0 else plot_result
                    if fig is None:
                        summary_rows.append(
                            {
                                "category": category_name,
                                "animal_id": animal_id,
                                "cell_idx": cell_idx,
                                "cell_num": cell_idx + 1,
                                "pf_rank": pf_rank,
                                "status": "skip_no_figure",
                                "n_traversals": len(traversal_epochs),
                                "message": "plot function returned no figure",
                            }
                        )
                        category_counters[category_name]["skipped_or_error"] += 1
                        continue

                    out_name = f"{animal_id}_Cell{cell_idx + 1}_PF{pf_rank}_traversal.svg"
                    out_path = out_dir / out_name
                    fig.savefig(out_path, dpi=300)
                    if not show_plots:
                        plt.close(fig)

                    summary_rows.append(
                        {
                            "category": category_name,
                            "animal_id": animal_id,
                            "cell_idx": cell_idx,
                            "cell_num": cell_idx + 1,
                            "pf_rank": pf_rank,
                            "status": "saved",
                            "n_traversals": len(traversal_epochs),
                            "message": str(out_path),
                        }
                    )
                    category_counters[category_name]["saved"] += 1

            except Exception as exc:
                summary_rows.append(
                    {
                        "category": category_name,
                        "animal_id": animal_id,
                        "cell_idx": cell_idx,
                        "cell_num": cell_idx + 1 if cell_idx >= 0 else np.nan,
                        "pf_rank": np.nan,
                        "status": "error",
                        "n_traversals": np.nan,
                        "message": str(exc),
                    }
                )
                category_counters[category_name]["skipped_or_error"] += 1

    summary_columns = [
        "category",
        "animal_id",
        "cell_idx",
        "cell_num",
        "pf_rank",
        "status",
        "n_traversals",
        "n_detected_traversals",
        "n_classified_traversals",
        "n_preferred_traversals",
        "n_nonpreferred_traversals",
        "n_unclassified_traversals",
        "preferred_fraction_threshold",
        "preferred_half_width_deg",
        "min_covered_green_bins",
        "traversal_bin_selection_mode",
        "preferred_angle_source",
        "fit_angle_fallback_to_empirical",
        "classification_frame_selection_mode",
        "classification_drz_segment_mode",
        "classification_phase_signed_drz_filter",
        "classification_speed_threshold_used",
        "first_n_minutes",
        "min_valid_traversal_duration_s",
        "message",
    ]
    summary_df = pd.DataFrame(summary_rows, columns=summary_columns)
    if save_summary_csv:
        summary_df.to_csv(summary_csv, index=False)

    return {
        "csplus_dir": str(csplus_dir),
        "csminus_dir": str(csminus_dir),
        "summary_csv": str(summary_csv) if save_summary_csv else None,
        "summary_df": summary_df,
        "counters": category_counters,
        "dilation_bins": dilation_bins,
        "dilation_shape": dilation_shape,
        "trace_slow_gap": trace_slow_gap,
        "theta_slow_pad_factor": theta_slow_pad_factor,
        "show_pf_prepost_patches": show_pf_prepost_patches,
        "pf_prepost_patch_alpha": pf_prepost_patch_alpha,
        "show_rest_patches": show_rest_patches_effective,
        "traversal_merge_gap_s": trial_traversal_merge_gap_s,
    }


def _remove_trial_plot_trajectory_start_end_indicators(axes: Any) -> None:
    import matplotlib.text as mtext

    axes_arr = np.asarray(axes, dtype=object)
    if axes_arr.ndim != 2 or axes_arr.shape[1] < 2:
        return
    n_rows = int(axes_arr.shape[0])
    for row in range(max(0, n_rows - 1)):
        ax_traj = axes_arr[row, 1]
        if ax_traj is None:
            continue
        for txt in list(getattr(ax_traj, "texts", [])):
            if isinstance(txt, mtext.Annotation) and getattr(txt, "arrow_patch", None) is not None:
                txt.remove()


def generate_distance_defined_trial_by_trial_plc_plots(
    config: PipelineConfig,
    spatial_data: Any,
    distance_params: PFDistanceCenteredParams | None = None,
    figure_save_folder: str | Path | None = None,
    *,
    distance_window_cm: float | None = None,
    clear_output: bool = True,
    save_summary_csv: bool = True,
    show_plots: bool = False,
    show_rest_patches: bool = True,
    resting_speed_threshold: float = 0.0,
    pf_reliability_dilation_bins: int | None = None,
    pf_reliability_dilation_shape: str | None = None,
    trace_slow_gap: float = 1.0,
    theta_slow_pad_factor: float = 0.05,
    sharey: bool = True,
    max_plot_trial_duration_s: float = 20.0,
) -> dict[str, Any]:
    """
    Generate trial-by-trial traversal plots using distance-defined traversal epochs.

    Epoch start/end are defined by the distance-centered logic in
    `compute_pf_distance_centered_trial_data`: the traversal segment begins at the
    first valid point before the PF-peak approach that reaches `distance_window_cm`,
    and ends at the first valid point after the PF peak that reaches the same
    distance. The plotted traces remain on a time axis.
    """
    import pandas as pd
    from scipy.ndimage import binary_dilation

    if distance_params is None:
        distance_params = PFDistanceCenteredParams()
    if distance_window_cm is not None:
        distance_params = PFDistanceCenteredParams(
            distance_window_cm=float(distance_window_cm),
            distance_bin_cm=float(distance_params.distance_bin_cm),
            center_by_pf_position=bool(distance_params.center_by_pf_position),
            require_movement=bool(distance_params.require_movement),
            min_traversals=int(distance_params.min_traversals),
            min_traversals_per_type=int(distance_params.min_traversals_per_type),
            require_full_span=bool(distance_params.require_full_span),
            subtract_pre_traversal_baseline=bool(distance_params.subtract_pre_traversal_baseline),
            exclude_trials_with_bad_frames=bool(distance_params.exclude_trials_with_bad_frames),
            pf_component_selection=str(distance_params.pf_component_selection),
            max_pf_distance_cm=distance_params.max_pf_distance_cm,
            smooth_window=float(distance_params.smooth_window),
        )

    if figure_save_folder is None:
        figure_root = config.figures_root / "CKII_pooled"
    else:
        figure_root = Path(figure_save_folder)
    figure_root.mkdir(parents=True, exist_ok=True)

    csplus_dir = figure_root / "PF_distance_defined_trials_CSplus_PLCs"
    csminus_dir = figure_root / "PF_distance_defined_trials_CSminus_PLCs"
    summary_csv = figure_root / "PF_distance_defined_trials_summary.csv"

    if clear_output:
        for out_dir in (csplus_dir, csminus_dir):
            if out_dir.exists():
                shutil.rmtree(out_dir)
            out_dir.mkdir(parents=True, exist_ok=True)
    else:
        csplus_dir.mkdir(parents=True, exist_ok=True)
        csminus_dir.mkdir(parents=True, exist_ok=True)

    if pf_reliability_dilation_bins is None:
        dilation_bins = int(config.place_cell.pf_reliability_dilation_bins)
    else:
        dilation_bins = int(pf_reliability_dilation_bins)
    if pf_reliability_dilation_shape is None:
        dilation_shape = str(config.place_cell.pf_reliability_dilation_shape).strip().lower()
    else:
        dilation_shape = str(pf_reliability_dilation_shape).strip().lower()
    if dilation_bins < 0:
        raise ValueError("pf_reliability_dilation_bins must be >= 0.")
    trace_slow_gap = float(trace_slow_gap)
    theta_slow_pad_factor = float(theta_slow_pad_factor)
    if trace_slow_gap < 0:
        raise ValueError("trace_slow_gap must be >= 0.")
    if theta_slow_pad_factor < 0:
        raise ValueError("theta_slow_pad_factor must be >= 0.")
    trial_resting_speed_threshold = float(resting_speed_threshold)
    trial_max_plot_duration_s = float(max_plot_trial_duration_s)
    if not np.isfinite(trial_max_plot_duration_s) or trial_max_plot_duration_s <= 0:
        raise ValueError("max_plot_trial_duration_s must be > 0.")

    trial_speed_threshold = float(config.analysis.speed_threshold)
    trial_theta_freqs = tuple(config.analysis.theta_freqs)
    trial_slow_freqs = float(config.analysis.slow_freqs)
    trial_session_indices = tuple(config.traversal.session_indices)
    trial_firing_rate_bin_ms = float(config.traversal.firing_rate_bin_ms)
    trial_firing_rate_smooth_ms = float(config.traversal.firing_rate_smooth_ms)
    trial_pf_center_window_sec = float(config.traversal.pf_center_window_sec)
    dilation_structure = (
        core._build_pf_dilation_structure(dilation_bins, dilation_shape)
        if dilation_bins > 0
        else None
    )

    category_specs = [
        ("CSplus", getattr(spatial_data, "plcs_csplus", []), csplus_dir),
        ("CSminus", getattr(spatial_data, "plcs_csminus", []), csminus_dir),
    ]

    runtime_cache: dict[str, dict[str, Any]] = {}
    summary_rows: list[dict[str, Any]] = []
    category_counters: dict[str, dict[str, int]] = {}

    for category_name, category_cells, out_dir in category_specs:
        category_counters[category_name] = {
            "attempted_cells": 0,
            "attempted_components": 0,
            "saved": 0,
            "skipped_or_error": 0,
        }

        for cell_meta in category_cells:
            animal_id = str(cell_meta.get("session", ""))
            cell_idx = int(cell_meta.get("cell_idx", -1))
            category_counters[category_name]["attempted_cells"] += 1

            if not animal_id or cell_idx < 0:
                category_counters[category_name]["skipped_or_error"] += 1
                continue

            try:
                if animal_id not in runtime_cache:
                    runtime_cache[animal_id] = _build_trial_plot_runtime_payload(animal_id, config)
                runtime = runtime_cache[animal_id]
                merged = runtime["merged"]
                spatial_by_idx = runtime["spatial_by_idx"]
                analysis = spatial_by_idx.get(cell_idx)
                if analysis is None or not bool(analysis.get("is_place_cell", False)):
                    category_counters[category_name]["skipped_or_error"] += 1
                    continue

                components = _sanitize_ranked_pf_components(
                    list(analysis.get("place_field_components", []) or []),
                    np.asarray(analysis.get("place_field_mask", []), dtype=bool),
                    rate_map=np.asarray(analysis.get("rate_map", []), dtype=float),
                    fallback_peak_rate=float(analysis.get("peak_rate", np.nan)),
                    max_components=None,
                )
                if not components:
                    category_counters[category_name]["skipped_or_error"] += 1
                    continue

                rank_to_eval_mask: dict[int, np.ndarray] = {}
                trajectory_contours: list[dict[str, Any]] = []
                for rank_i, comp_i in enumerate(components, start=1):
                    comp_mask_i = np.asarray(comp_i.get("mask", []), dtype=bool)
                    if comp_mask_i.size == 0 or not np.any(comp_mask_i):
                        continue
                    comp_eval_i = comp_mask_i
                    if dilation_structure is not None:
                        comp_eval_i = binary_dilation(comp_mask_i, structure=dilation_structure)
                    rank_to_eval_mask[int(rank_i)] = np.asarray(comp_eval_i, dtype=bool)
                    if rank_i <= 2:
                        trajectory_contours.append(
                            {
                                "mask": np.asarray(comp_eval_i, dtype=bool),
                                "color": "magenta" if rank_i == 1 else "cyan",
                                "linewidth": 0.8,
                                "linestyle": "solid",
                                "alpha": 1.0,
                            }
                        )

                traces = runtime["traces"]
                x_neural = np.asarray(merged["x_neural"], dtype=float)
                y_neural = np.asarray(merged["y_neural"], dtype=float)
                speed = np.asarray(merged["speed"], dtype=float)
                spikes = merged["spikes"]
                all_spikes = merged.get("all_spikes", merged["spikes"])
                refined_ss = merged.get("refined_SS", [np.array([], dtype=int) for _ in spikes])
                all_cs_spikes = merged.get("all_CS_spikes", [np.array([], dtype=int) for _ in spikes])
                complex_bursts_dicts = merged.get("complex_bursts_dicts", [])
                plateaus_dicts = merged.get("plateaus_dicts", None)
                session_start_frames = merged.get("session_start_frames", [0])
                frame_rate = float(merged["frame_rate"])

                bad_timepoints = (
                    runtime["bad_masks"][cell_idx]
                    if isinstance(runtime["bad_masks"], np.ndarray) and cell_idx < len(runtime["bad_masks"])
                    else None
                )
                bad_mask = None
                if bad_timepoints is not None:
                    bad_mask = np.asarray(bad_timepoints, dtype=bool)
                    if bad_mask.shape[0] != x_neural.shape[0]:
                        raise ValueError(f"bad_timepoints length mismatch for {animal_id} cell {cell_idx}.")

                raw_bad_mask = None
                traces_raw_source = merged.get("traces", None)
                if traces_raw_source is not None and cell_idx < len(traces_raw_source):
                    raw_trace = np.asarray(traces_raw_source[cell_idx], dtype=float)
                    if raw_trace.ndim == 1 and raw_trace.shape[0] == x_neural.shape[0]:
                        raw_bad_mask = ~np.isfinite(raw_trace)

                traversal_bad_mask = None
                if bad_mask is not None and raw_bad_mask is not None:
                    traversal_bad_mask = bad_mask | raw_bad_mask
                elif bad_mask is not None:
                    traversal_bad_mask = bad_mask
                elif raw_bad_mask is not None:
                    traversal_bad_mask = raw_bad_mask

                x_neural_plot = x_neural.copy()
                y_neural_plot = y_neural.copy()
                speed_plot = speed.copy()
                if traversal_bad_mask is not None:
                    x_neural_plot[traversal_bad_mask] = np.nan
                    y_neural_plot[traversal_bad_mask] = np.nan
                    speed_plot[traversal_bad_mask] = np.nan

                def _filter_spike_indices(spike_source: Any) -> np.ndarray:
                    if isinstance(spike_source, (list, tuple, np.ndarray)):
                        src = spike_source[cell_idx] if isinstance(spike_source, (list, tuple)) else spike_source
                    else:
                        src = np.array([], dtype=int)
                    idx = np.asarray(src, dtype=int)
                    idx = idx[(idx >= 0) & (idx < x_neural.shape[0])]
                    if traversal_bad_mask is not None and idx.size > 0:
                        idx = idx[~traversal_bad_mask[idx]]
                    return idx

                all_spikes_cell = _filter_spike_indices(all_spikes)
                refined_ss_cell = _filter_spike_indices(refined_ss)
                all_cs_spikes_cell = _filter_spike_indices(all_cs_spikes)

                trace = np.asarray(traces[cell_idx], dtype=float)
                trace = core.interpolate_nan_segment(trace)
                theta_vm = core.bandpass_filter(trace, trial_theta_freqs[0], trial_theta_freqs[1], frame_rate, order=5)
                slow_vm = core.lowpass_filter(trace, trial_slow_freqs, frame_rate, order=5)

                for pf_rank, _comp in enumerate(components, start=1):
                    category_counters[category_name]["attempted_components"] += 1

                    result = compute_distance_centered_component_result(
                        animal_id=animal_id,
                        cell_idx=cell_idx,
                        pf_rank=int(pf_rank),
                        runtime=runtime,
                        config=config,
                        distance_params=distance_params,
                        dilation_bins=dilation_bins,
                        dilation_shape=dilation_shape,
                    )
                    if result is None:
                        category_counters[category_name]["skipped_or_error"] += 1
                        continue

                    trial_data = result.get("all", {}).get("trial_data", {})
                    epoch_start_frames = np.asarray(trial_data.get("epoch_start_frames", []), dtype=int)
                    epoch_end_frames = np.asarray(trial_data.get("epoch_end_frames", []), dtype=int)
                    traversal_types = list(np.asarray(trial_data.get("traversal_types", []), dtype=object))
                    n_trials_raw = int(epoch_start_frames.size)
                    # Safety dedupe at plotting stage: keep unique displayed epoch windows
                    # in input order so stale cached payloads cannot render duplicate rows.
                    keep_idx: list[int] = []
                    seen_epochs: set[tuple[int, int]] = set()
                    for _i, (_s, _e) in enumerate(zip(epoch_start_frames.tolist(), epoch_end_frames.tolist())):
                        epoch_key = (int(_s), int(_e))
                        if int(_e) <= int(_s):
                            continue
                        if epoch_key in seen_epochs:
                            continue
                        seen_epochs.add(epoch_key)
                        keep_idx.append(int(_i))
                    if len(keep_idx) != int(epoch_start_frames.size):
                        epoch_start_frames = epoch_start_frames[np.asarray(keep_idx, dtype=int)]
                        epoch_end_frames = epoch_end_frames[np.asarray(keep_idx, dtype=int)]
                        if len(traversal_types) == n_trials_raw:
                            traversal_types = [traversal_types[i] for i in keep_idx]
                        else:
                            traversal_types = ["unknown"] * int(epoch_start_frames.size)

                    n_trials = int(epoch_start_frames.size)
                    if n_trials < int(distance_params.min_traversals):
                        category_counters[category_name]["skipped_or_error"] += 1
                        continue
                    traversal_epochs = list(zip(epoch_start_frames.tolist(), epoch_end_frames.tolist()))
                    place_field_mask = result.get("place_field_mask", rank_to_eval_mask.get(int(pf_rank)))
                    pf_bins = result.get("pf_bins", None)
                    pf_peak_xy = result.get("pf_peak_xy", None)
                    if place_field_mask is None or pf_bins is None:
                        category_counters[category_name]["skipped_or_error"] += 1
                        continue

                    plot_result = core.plot_place_field_traversal_trials_with_cb_example_centered_by_max_rate(
                        trace,
                        theta_vm,
                        slow_vm,
                        speed_plot,
                        x_neural_plot,
                        y_neural_plot,
                        traversal_epochs,
                        place_field_mask,
                        pf_bins,
                        frame_rate,
                        complex_bursts_dicts=complex_bursts_dicts,
                        cell_idx=cell_idx,
                        traversal_types=traversal_types,
                        padding_sec=0.0,
                        zscore_traces=False,
                        theta_freqs=trial_theta_freqs,
                        slow_freqs=trial_slow_freqs,
                        session_start_frames=session_start_frames,
                        session_indices=trial_session_indices,
                        color_by_session=True,
                        resting_speed_threshold=trial_resting_speed_threshold,
                        show_rest_patches=bool(show_rest_patches),
                        show_pf_prepost_patches=True,
                        pf_prepost_patch_alpha=0.1,
                        pf_prepost_patch_scope="full_window",
                        pf_prepost_running_only=False,
                        pf_prepost_patch_defs=[
                            {
                                "mask": np.asarray(place_field_contour_mask, dtype=bool),
                                "color": ("magenta" if int(pf_rank) == 1 else "cyan"),
                            }
                        ],
                        rest_patch_scope="full_window",
                        rest_patch_require_in_pf=False,
                        min_rest_patch_duration_s=1.0,
                        rest_patch_color="#B3B3B3",
                        rest_patch_alpha=0.25,
                        shade_traversal_epoch=False,
                        gradient_traversal_trajectory=True,
                        trajectory_rasterized=True,
                        trajectory_direction_label_top=True,
                        trajectory_direction_label_fontsize=5,
                        max_plot_trial_duration_s=trial_max_plot_duration_s,
                        drop_epochs_with_bad_timepoints=bool(distance_params.exclude_trials_with_bad_frames),
                        refined_SS=refined_ss_cell,
                        all_CS_spikes=all_cs_spikes_cell,
                        all_spikes=all_spikes_cell,
                        firing_rate_bin_ms=trial_firing_rate_bin_ms,
                        firing_rate_smooth_ms=trial_firing_rate_smooth_ms,
                        show_firing_rate=False,
                        simple_spike_color="#026C80",
                        complex_spike_color="#EE9B00",
                        pf_peak_xy=pf_peak_xy,
                        pf_center_window_sec=trial_pf_center_window_sec,
                        plot_pf_centered_average=True,
                        return_pf_centered=True,
                        return_spike_rate_means=True,
                        show=show_plots,
                        bad_timepoints=traversal_bad_mask,
                        return_trial_firing_rates=True,
                        center_by_pf_position=True,
                        max_pf_distance_cm=distance_params.max_pf_distance_cm,
                        plateaus_dicts=plateaus_dicts,
                        slow_trace_gap=trace_slow_gap,
                        theta_slow_pad_factor=theta_slow_pad_factor,
                        trace_ymax_from_simple_spikes=(str(category_name) == "CSminus"),
                        sharey=bool(sharey),
                        place_field_contours=trajectory_contours,
                        center_position_label=f"Closest to PF{pf_rank}",
                        pf_peak_label=f"PF{pf_rank} peak",
                        pf_peak_color=("magenta" if int(pf_rank) == 1 else "cyan"),
                    )
                    fig = plot_result[0] if isinstance(plot_result, tuple) and len(plot_result) > 0 else plot_result
                    axes = plot_result[1] if isinstance(plot_result, tuple) and len(plot_result) > 1 else None
                    if fig is None:
                        category_counters[category_name]["skipped_or_error"] += 1
                        continue

                    _remove_trial_plot_trajectory_start_end_indicators(axes)

                    out_name = f"{animal_id}_Cell{cell_idx + 1}_PF{pf_rank}_distance_defined_traversal.svg"
                    out_path = out_dir / out_name
                    fig.savefig(out_path, dpi=300)
                    if not show_plots:
                        plt.close(fig)

                    summary_rows.append(
                        {
                            "category": category_name,
                            "animal_id": animal_id,
                            "cell_idx": cell_idx,
                            "cell_num": cell_idx + 1,
                            "pf_rank": pf_rank,
                            "status": "saved",
                            "n_traversals": n_trials,
                            "message": str(out_path),
                        }
                    )
                    category_counters[category_name]["saved"] += 1
            except Exception as exc:
                summary_rows.append(
                    {
                        "category": category_name,
                        "animal_id": animal_id,
                        "cell_idx": cell_idx,
                        "cell_num": cell_idx + 1 if cell_idx >= 0 else np.nan,
                        "pf_rank": np.nan,
                        "status": "error",
                        "n_traversals": np.nan,
                        "message": str(exc),
                    }
                )
                category_counters[category_name]["skipped_or_error"] += 1

    summary_columns = [
        "category",
        "animal_id",
        "cell_idx",
        "cell_num",
        "pf_rank",
        "status",
        "n_detected_traversals",
        "n_classified_traversals",
        "n_preferred_traversals",
        "n_nonpreferred_traversals",
        "n_unclassified_traversals",
        "preferred_fraction_threshold",
        "preferred_half_width_deg",
        "min_covered_green_bins",
        "traversal_bin_selection_mode",
        "preferred_angle_source",
        "fit_angle_fallback_to_empirical",
        "classification_frame_selection_mode",
        "classification_drz_segment_mode",
        "classification_phase_signed_drz_filter",
        "classification_speed_threshold_used",
        "first_n_minutes",
        "min_valid_traversal_duration_s",
        "message",
    ]
    summary_df = pd.DataFrame(summary_rows, columns=summary_columns)
    if save_summary_csv:
        summary_df.to_csv(summary_csv, index=False)

    return {
        "csplus_dir": str(csplus_dir),
        "csminus_dir": str(csminus_dir),
        "summary_csv": str(summary_csv) if save_summary_csv else None,
        "summary_df": summary_df,
        "counters": category_counters,
        "distance_window_cm": float(distance_params.distance_window_cm),
        "distance_bin_cm": float(distance_params.distance_bin_cm),
        "require_movement": bool(distance_params.require_movement),
        "dilation_bins": dilation_bins,
        "dilation_shape": dilation_shape,
        "trace_slow_gap": trace_slow_gap,
        "theta_slow_pad_factor": theta_slow_pad_factor,
        "resting_speed_threshold": trial_resting_speed_threshold,
        "max_plot_trial_duration_s": trial_max_plot_duration_s,
    }


def _smooth_boxcar(trace: np.ndarray, win: int = 5) -> np.ndarray:
    arr = np.asarray(trace, dtype=float)
    if int(win) <= 1:
        return arr
    if arr.ndim != 1 or arr.size == 0:
        return arr
    win_eff = max(1, min(int(win), int(arr.size)))
    kernel = np.ones(win_eff, dtype=float)
    valid = np.isfinite(arr).astype(float)
    arr_filled = np.where(np.isfinite(arr), arr, 0.0)
    smoothed = np.convolve(arr_filled, kernel, mode="same")
    counts = np.convolve(valid, kernel, mode="same")
    with np.errstate(invalid="ignore", divide="ignore"):
        smoothed = np.where(counts > 0, smoothed / counts, np.nan)
    return smoothed


def _normalize_pf_category_name(category: str) -> str:
    raw = str(category).strip().lower()
    if raw in {"csplus", "cs+", "plus", "plcs_csplus"}:
        return "CSplus"
    if raw in {"csminus", "cs-", "minus", "plcs_csminus"}:
        return "CSminus"
    if raw in {"nonplc", "non-plc", "non_plc", "nonplcs", "non-plcs", "non_plcs"}:
        return "nonPLC"
    if raw in {"all-nonplc", "all_nonplc", "allnonplc", "all-non-plc", "all_non_plc"}:
        return "all-nonPLC"
    raise ValueError(
        f"Unknown category '{category}'. Use 'CSplus', 'CSminus', 'non-PLC', or 'all-nonPLC'."
    )


def _axis_smooth_window_to_bins(bin_width: float, smooth_window: float | int | None) -> int | None:
    if smooth_window is None:
        return None
    val = float(smooth_window)
    if not np.isfinite(val) or val <= 0:
        return 0
    bin_w = float(bin_width)
    if (not np.isfinite(bin_w)) or bin_w <= 0:
        return max(1, int(round(val)))
    return max(1, int(round(val / bin_w)))


def _distance_smooth_cm_to_bins(distance_bin_cm: float, smooth_window_cm: float | int | None) -> int | None:
    return _axis_smooth_window_to_bins(distance_bin_cm, smooth_window_cm)


def _peak_rate_from_trace(trace: np.ndarray | None) -> float:
    if trace is None:
        return np.nan
    arr = np.asarray(trace, dtype=float)
    if arr.ndim != 1 or arr.size == 0:
        return np.nan
    finite = arr[np.isfinite(arr)]
    if finite.size == 0:
        return np.nan
    return float(np.nanmax(finite))


def _infer_preferred_direction_from_rate_traces(
    cw_rate_trace: np.ndarray | None,
    ccw_rate_trace: np.ndarray | None,
) -> str | None:
    """Infer preferred direction by larger peak all-spike firing rate."""
    cw_peak = _peak_rate_from_trace(cw_rate_trace)
    ccw_peak = _peak_rate_from_trace(ccw_rate_trace)
    if not (np.isfinite(cw_peak) and np.isfinite(ccw_peak)):
        return None
    if cw_peak > ccw_peak:
        return "cw"
    if ccw_peak > cw_peak:
        return "ccw"
    return None


def _shift_trace_with_nan(trace: np.ndarray, shift_bins: int) -> np.ndarray:
    arr = np.asarray(trace, dtype=float)
    if arr.ndim != 1 or arr.size == 0 or int(shift_bins) == 0:
        return arr.copy()
    n = int(arr.size)
    shift = int(shift_bins)
    out = np.full(n, np.nan, dtype=float)
    if abs(shift) >= n:
        return out
    if shift > 0:
        out[shift:] = arr[:-shift]
    else:
        out[:shift] = arr[-shift:]
    return out


def _get_spatial_category_cells(spatial_data: Any, category: str) -> list[dict[str, Any]]:
    cat = _normalize_pf_category_name(category)
    if cat == "CSplus":
        return list(getattr(spatial_data, "plcs_csplus", []))
    if cat == "CSminus":
        return list(getattr(spatial_data, "plcs_csminus", []))
    if cat == "nonPLC":
        return list(getattr(spatial_data, "non_plcs", []))
    if cat == "all-nonPLC":
        return list(getattr(spatial_data, "non_plcs", []))
    return []


def _passes_egocentric_category_gate(
    *,
    category: str,
    analysis: dict[str, Any],
) -> tuple[bool, str]:
    cat = _normalize_pf_category_name(category)
    if cat in {"CSplus", "CSminus"}:
        return True, ""
    if cat == "nonPLC":
        if bool(analysis.get("is_place_cell", False)):
            return False, "nonplc_is_place_cell"
        if not bool(analysis.get("is_place_cell_ss", False)):
            return False, "nonplc_not_ss_place_cell"
        return True, ""
    if cat == "all-nonPLC":
        if bool(analysis.get("is_place_cell", False)):
            return False, "all_nonplc_is_place_cell"
        return True, ""
    return False, f"unsupported_category:{cat}"


def _ordered_dataset_categories(
    dataset: dict[str, Any],
    *,
    fallback: tuple[str, ...] = ("CSplus", "CSminus"),
) -> list[str]:
    ordered: list[str] = []

    def _push(val: Any) -> None:
        try:
            cat = _normalize_pf_category_name(str(val))
        except Exception:
            return
        if cat not in ordered:
            ordered.append(cat)

    meta = dataset.get("metadata", {}) if isinstance(dataset, dict) else {}
    for cat in list(meta.get("categories", ()) or ()):
        _push(cat)
    for key, value in (dataset.items() if isinstance(dataset, dict) else []):
        if key == "metadata":
            continue
        if not isinstance(value, dict):
            continue
        _push(key)
    if len(ordered) == 0:
        for cat in fallback:
            _push(cat)
    return ordered


def _category_output_dir_name(
    *,
    prefix: str,
    category: str,
    suffix: str,
) -> str:
    cat = _normalize_pf_category_name(category)
    if cat == "CSplus":
        return f"{prefix}_CSplus{suffix}"
    if cat == "CSminus":
        return f"{prefix}_CSminus{suffix}"
    return f"{prefix}_{cat}{suffix}"


def _build_component_analysis_override(
    analysis: dict[str, Any],
    component_mask: np.ndarray,
    component_peak_rate: float,
    component_rate_map: np.ndarray | None = None,
    default_bin_size: float = 1.5,
) -> dict[str, Any]:
    base_params = dict(analysis.get("params", {}))
    base_params.setdefault("width_real", 35.5)
    base_params.setdefault("height_real", 20.0)
    base_params.setdefault("bin_size", float(default_bin_size))
    out = dict(analysis)
    out["is_place_cell"] = True
    out["place_field_mask"] = np.asarray(component_mask, dtype=bool)
    out["peak_rate"] = float(component_peak_rate)
    if component_rate_map is not None:
        out["rate_map"] = np.asarray(component_rate_map, dtype=float)
    out["params"] = base_params
    return out


def _compute_component_pf_centered_result(
    animal_id: str,
    cell_idx: int,
    pf_rank: int,
    runtime: dict[str, Any],
    config: PipelineConfig,
    dilation_bins: int,
    dilation_shape: str,
) -> dict[str, Any] | None:
    from scipy.ndimage import binary_dilation

    spatial_by_idx = runtime["spatial_by_idx"]
    analysis = spatial_by_idx.get(cell_idx)
    if analysis is None or not bool(analysis.get("is_place_cell", False)):
        return None

    components = _sanitize_ranked_pf_components(
        list(analysis.get("place_field_components", []) or []),
        np.asarray(analysis.get("place_field_mask", []), dtype=bool),
        rate_map=np.asarray(analysis.get("rate_map", []), dtype=float),
        fallback_peak_rate=float(analysis.get("peak_rate", np.nan)),
        max_components=None,
    )
    if not components:
        return None

    rank_idx = int(pf_rank) - 1
    if rank_idx < 0 or rank_idx >= len(components):
        return None

    comp = components[rank_idx]
    comp_mask = np.asarray(comp.get("mask", []), dtype=bool)
    if comp_mask.size == 0 or not np.any(comp_mask):
        return None

    eval_mask = comp_mask
    if int(dilation_bins) > 0:
        structure = core._build_pf_dilation_structure(int(dilation_bins), str(dilation_shape).strip().lower())
        eval_mask = binary_dilation(comp_mask, structure=structure)

    analysis_override = _build_component_analysis_override(
        analysis=analysis,
        component_mask=eval_mask,
        component_peak_rate=float(comp.get("peak_rate", np.nan)),
        default_bin_size=float(config.place_cell.bin_size),
    )
    merged = runtime["merged"]
    result = compute_pf_centered_trial_data(
        cell_idx=cell_idx,
        PC_output_all=None,
        traces=runtime["traces"],
        vms=runtime["vms"],
        x_neural=np.asarray(merged["x_neural"], dtype=float),
        y_neural=np.asarray(merged["y_neural"], dtype=float),
        speed=np.asarray(merged["speed"], dtype=float),
        spikes=merged["spikes"],
        all_spikes=merged.get("all_spikes", merged["spikes"]),
        refined_SS=merged.get("refined_SS", [np.array([], dtype=int) for _ in merged["spikes"]]),
        all_CS_spikes=merged.get("all_CS_spikes", [np.array([], dtype=int) for _ in merged["spikes"]]),
        frame_rate=float(merged["frame_rate"]),
        pf_center_window_sec=float(config.traversal.pf_center_window_sec),
        theta_freqs=tuple(config.analysis.theta_freqs),
        slow_freqs=float(config.analysis.slow_freqs),
        speed_threshold=float(config.analysis.speed_threshold),
        min_duration_ms=float(config.traversal.min_duration_ms),
        place_field_threshold=float(config.place_cell.place_field_threshold),
        min_distance_cm=float(config.traversal.min_distance_cm),
        clear_traversal=bool(config.traversal.clear_traversal),
        session_start_frames=merged.get("session_start_frames", [0]),
        session_indices=tuple(config.traversal.session_indices),
        bad_masks=runtime["bad_masks"],
        center_by_pf_position=bool(config.traversal.center_by_pf_position),
        firing_rate_bin_ms=float(config.traversal.firing_rate_bin_ms),
        firing_rate_smooth_ms=float(config.traversal.firing_rate_smooth_ms),
        min_traversals=int(config.traversal.min_traversals),
        subtract_pre_traversal_baseline=bool(config.traversal.subtract_pre_traversal_baseline),
        mask_non_traversal_pf=bool(config.traversal.mask_non_traversal_pf),
        max_pf_distance_cm=config.traversal.max_pf_distance_cm,
        pf_component_selection=str(config.traversal.pf_component_selection),
        complex_bursts_dicts=merged.get("complex_bursts_dicts", []),
        plateaus_dicts=merged.get("plateaus_dicts", None),
        plateau_min_duration_ms=float(config.traversal.plateau_min_duration_ms),
        analysis_override=analysis_override,
    )
    if result is None:
        return None
    result["pf_rank"] = int(pf_rank)
    result["animal_id"] = animal_id
    result["reliability_eval_dilation_bins"] = int(dilation_bins)
    result["reliability_eval_dilation_shape"] = str(dilation_shape)
    result["pf_component_size_bins"] = int(np.sum(comp_mask))
    result["pf_component_eval_size_bins"] = int(np.sum(eval_mask))
    return result


