def compute_distance_defined_component_result_iterative(
    animal_id: str,
    cell_idx: int,
    pf_rank: int,
    runtime: dict[str, Any],
    config: PipelineConfig,
    distance_params: PFDistanceCenteredParams,
    dilation_bins: int,
    dilation_shape: str,
    *,
    distance_window_cm: float,
    detection_window_cm: float,
    distance_bin_cm: float,
    center_vicinity_min_cm: int,
    center_vicinity_max_cm: int,
    moving_speed_threshold: float,
    resting_speed_threshold: float,
    exclude_trials_with_bad_frames: bool,
    pf_source_mode: str,
    include_long_cb_as_plateau: bool,
    include_resting_plateaus: bool,
    cb_plateau_min_duration_ms: float,
    distance_mode: str,
    plateau_trace_window_ms: float = 100.0,
    align_all_pf_components_to_session_compare: bool = True,
    session_compare_cache_version: str = "v2",
    min_traversals: int | None = None,
    bad_frame_mask: np.ndarray | None = None,
) -> dict[str, Any] | None:
    from scipy.ndimage import binary_dilation

    spatial_by_idx = runtime["spatial_by_idx"]
    analysis = spatial_by_idx.get(cell_idx)
    if analysis is None:
        return None
    source = str(pf_source_mode).strip().lower()
    if source not in {"all", "ss"}:
        raise ValueError(f"Unknown pf_source_mode='{pf_source_mode}'. Use 'all' or 'ss'.")
    if source == "ss":
        if not bool(analysis.get("is_place_cell_ss", False)):
            return None
    else:
        if not bool(analysis.get("is_place_cell", False)):
            return None

    pf_source_info = _resolve_distance_defined_pf_component_source(
        animal_id=animal_id,
        cell_idx=int(cell_idx),
        analysis=analysis,
        config=config,
        pf_source_mode=source,
        align_all_pf_components_to_session_compare=bool(align_all_pf_components_to_session_compare),
        session_compare_cache_version=str(session_compare_cache_version),
    )
    components_raw = list(pf_source_info.get("components_raw", []) or [])
    fallback_mask = np.asarray(pf_source_info.get("fallback_mask", []), dtype=bool)
    fallback_peak_rate = pf_source_info.get("fallback_peak_rate", np.nan)
    source_rate_map = np.asarray(pf_source_info.get("source_rate_map", []), dtype=float)

    components = _sanitize_ranked_pf_components(
        components_raw,
        fallback_mask,
        rate_map=(source_rate_map if source_rate_map.size > 0 else None),
        fallback_peak_rate=float(fallback_peak_rate),
        max_components=None,
    )
    if not components:
        return None

    rank_idx = int(pf_rank) - 1
    if rank_idx < 0 or rank_idx >= len(components):
        return None

    comp = components[rank_idx]
    comp_mask = np.asarray(comp.get("mask", []), dtype=bool)
    if comp_mask.size == 0 or not np.any(comp_mask):
        return None

    eval_mask = comp_mask
    if int(dilation_bins) > 0:
        structure = core._build_pf_dilation_structure(int(dilation_bins), str(dilation_shape).strip().lower())
        eval_mask = binary_dilation(comp_mask, structure=structure)

    analysis_override = _build_component_analysis_override(
        analysis=analysis,
        component_mask=eval_mask,
        component_peak_rate=float(comp.get("peak_rate", np.nan)),
        component_rate_map=source_rate_map if source_rate_map.size > 0 else None,
        default_bin_size=float(config.place_cell.bin_size),
    )
    merged = runtime["merged"]
    result = compute_pf_distance_centered_trial_data_iterative(
        cell_idx=int(cell_idx),
        traces=runtime["traces"],
        vms=runtime["vms"],
        x_neural=np.asarray(merged["x_neural"], dtype=float),
        y_neural=np.asarray(merged["y_neural"], dtype=float),
        speed=np.asarray(merged["speed"], dtype=float),
        all_spikes=merged.get("all_spikes", merged["spikes"]),
        refined_SS=merged.get("refined_SS", [np.array([], dtype=int) for _ in merged["spikes"]]),
        all_CS_spikes=merged.get("all_CS_spikes", [np.array([], dtype=int) for _ in merged["spikes"]]),
        frame_rate=float(merged["frame_rate"]),
        distance_window_cm=float(distance_window_cm),
        detection_window_cm=float(detection_window_cm),
        distance_bin_cm=float(distance_bin_cm),
        center_vicinity_min_cm=int(center_vicinity_min_cm),
        center_vicinity_max_cm=int(center_vicinity_max_cm),
        moving_speed_threshold=float(moving_speed_threshold),
        resting_speed_threshold=float(resting_speed_threshold),
        moving_kernel_size=int(config.analysis.kernel_size),
        moving_min_duration_s=float(config.analysis.min_duration_s),
        merge_gap_s=float(getattr(config.traversal, "traversal_merge_gap_s", 0.0)),
        theta_freqs=tuple(config.analysis.theta_freqs),
        slow_freqs=float(config.analysis.slow_freqs),
        subtract_pre_traversal_baseline=bool(distance_params.subtract_pre_traversal_baseline),
        min_traversals=int(distance_params.min_traversals) if min_traversals is None else int(min_traversals),
        exclude_trials_with_bad_frames=bool(exclude_trials_with_bad_frames),
        session_start_frames=merged.get("session_start_frames", [0]),
        session_indices=tuple(config.traversal.session_indices),
        bad_masks=runtime["bad_masks"],
        bad_frame_mask=bad_frame_mask,
        plateaus_dicts=merged.get("plateaus_dicts", None),
        complex_bursts_dicts=merged.get("complex_bursts_dicts", []),
        include_long_cb_as_plateau=bool(include_long_cb_as_plateau),
        include_resting_plateaus=bool(include_resting_plateaus),
        cb_plateau_min_duration_ms=float(cb_plateau_min_duration_ms),
        plateau_min_duration_ms=float(config.traversal.plateau_min_duration_ms),
        plateau_trace_window_ms=float(plateau_trace_window_ms),
        analysis_override=analysis_override,
        distance_mode=str(distance_mode),
    )
    if result is None:
        return None
    result["pf_rank"] = int(pf_rank)
    result["animal_id"] = animal_id
    result["reliability_eval_dilation_bins"] = int(dilation_bins)
    result["reliability_eval_dilation_shape"] = str(dilation_shape)
    result["pf_component_size_bins"] = int(np.sum(comp_mask))
    result["pf_component_eval_size_bins"] = int(np.sum(eval_mask))
    result["pf_source"] = ("ss" if source == "ss" else "all")
    result["pf_component_source_name"] = str(pf_source_info.get("source_name", "unknown"))
    return result


def _empty_time_defined_direction_result(
    time_rel: np.ndarray,
    *,
    n_total_trials: int = 0,
) -> dict[str, Any]:
    n_time = int(len(time_rel))
    empty = np.full((0, n_time), np.nan, dtype=float)
    return {
        "n_trials": 0,
        "n_total_trials": int(n_total_trials),
        "n_reliable_trials": 0,
        "reliability": np.nan,
        "traversal_types": [],
        "trial_data": {
            "epoch_start_frames": np.array([], dtype=int),
            "epoch_end_frames": np.array([], dtype=int),
            "center_frames": np.array([], dtype=int),
            "center_vicinity_cm": np.array([], dtype=float),
            "epoch_start_sec": np.array([], dtype=float),
            "epoch_end_sec": np.array([], dtype=float),
            "duration_sec": np.array([], dtype=float),
            "nonrest_duration_sec": np.array([], dtype=float),
            "n_spikes_all": np.array([], dtype=int),
            "n_spikes_ss": np.array([], dtype=int),
            "n_spikes_cs": np.array([], dtype=int),
            "fr_all_hz": np.array([], dtype=float),
            "fr_ss_hz": np.array([], dtype=float),
            "fr_cs_hz": np.array([], dtype=float),
            "traversal_types": np.array([], dtype=object),
            "session_idx": np.array([], dtype=int),
        },
        "theta_stack": empty.copy(),
        "slow_stack": empty.copy(),
        "rate_stack": empty.copy(),
        "ss_rate_stack": empty.copy(),
        "cs_rate_stack": empty.copy(),
        "ss_pct_stack": empty.copy(),
        "cs_pct_stack": empty.copy(),
        "plateau_stack": np.zeros((0, n_time), dtype=float),
        "pf_entry_rel": np.array([], dtype=float),
        "pf_exit_rel": np.array([], dtype=float),
        "n_plateaus_per_trial": np.array([], dtype=int),
        "theta_mean": np.full(n_time, np.nan, dtype=float),
        "slow_mean": np.full(n_time, np.nan, dtype=float),
        "rate_mean": np.full(n_time, np.nan, dtype=float),
        "ss_rate_mean": np.full(n_time, np.nan, dtype=float),
        "cs_rate_mean": np.full(n_time, np.nan, dtype=float),
        "ss_pct_mean": np.full(n_time, np.nan, dtype=float),
        "cs_pct_mean": np.full(n_time, np.nan, dtype=float),
    }


def _nanmean_columns(arr: np.ndarray) -> np.ndarray:
    arr = np.asarray(arr, dtype=float)
    if arr.ndim != 2:
        return np.array([], dtype=float)
    out = np.full(int(arr.shape[1]), np.nan, dtype=float)
    valid = np.isfinite(arr)
    counts = np.sum(valid, axis=0)
    if np.any(counts > 0):
        sums = np.nansum(arr, axis=0)
        out[counts > 0] = sums[counts > 0] / counts[counts > 0]
    return out


def _aggregate_time_defined_trials(
    trials: list[dict[str, Any]],
    time_rel: np.ndarray,
    frame_rate: float,
) -> dict[str, Any]:
    if len(trials) == 0:
        return _empty_time_defined_direction_result(time_rel, n_total_trials=0)

    n_trials = int(len(trials))
    n_reliable = int(sum(int(t.get("n_spikes_all", 0)) > 0 for t in trials))
    theta_arr = np.vstack([np.asarray(t["theta_trial"], dtype=float) for t in trials])
    slow_arr = np.vstack([np.asarray(t["slow_trial"], dtype=float) for t in trials])
    rate_arr = np.vstack([np.asarray(t["rate_trial"], dtype=float) for t in trials])
    ss_rate_arr = np.vstack([np.asarray(t["ss_rate_trial"], dtype=float) for t in trials])
    cs_rate_arr = np.vstack([np.asarray(t["cs_rate_trial"], dtype=float) for t in trials])
    ss_pct_arr = np.vstack([np.asarray(t["ss_pct_trial"], dtype=float) for t in trials])
    cs_pct_arr = np.vstack([np.asarray(t["cs_pct_trial"], dtype=float) for t in trials])
    plateau_arr = np.vstack([np.asarray(t["plateau_trial"], dtype=float) for t in trials])
    starts = np.asarray([int(t["epoch_start"]) for t in trials], dtype=int)
    ends = np.asarray([int(t["epoch_end"]) for t in trials], dtype=int)
    centers = np.asarray([int(t["center_idx"]) for t in trials], dtype=int)
    vicinity = np.asarray([float(t.get("center_vicinity_cm", np.nan)) for t in trials], dtype=float)
    session_idx = np.asarray([int(t.get("session_idx", 0)) for t in trials], dtype=int)
    n_spikes_all = np.asarray([int(t.get("n_spikes_all", 0)) for t in trials], dtype=int)
    n_spikes_ss = np.asarray([int(t.get("n_spikes_ss", 0)) for t in trials], dtype=int)
    n_spikes_cs = np.asarray([int(t.get("n_spikes_cs", 0)) for t in trials], dtype=int)
    nonrest_duration_sec = np.asarray([float(t.get("nonrest_duration_sec", np.nan)) for t in trials], dtype=float)
    traversal_types = np.asarray([str(t.get("traversal_type", "unknown")) for t in trials], dtype=object)
    duration_sec = (ends - starts).astype(float) / float(frame_rate)
    with np.errstate(divide="ignore", invalid="ignore"):
        fr_all_hz = np.where(nonrest_duration_sec > 0, n_spikes_all / nonrest_duration_sec, np.nan)
        fr_ss_hz = np.where(nonrest_duration_sec > 0, n_spikes_ss / nonrest_duration_sec, np.nan)
        fr_cs_hz = np.where(nonrest_duration_sec > 0, n_spikes_cs / nonrest_duration_sec, np.nan)
    return {
        "n_trials": n_trials,
        "n_total_trials": n_trials,
        "n_reliable_trials": n_reliable,
        "reliability": float(n_reliable) / float(n_trials) if n_trials > 0 else np.nan,
        "traversal_types": traversal_types.tolist(),
        "trial_data": {
            "epoch_start_frames": starts,
            "epoch_end_frames": ends,
            "center_frames": centers,
            "center_vicinity_cm": vicinity,
            "epoch_start_sec": starts.astype(float) / float(frame_rate),
            "epoch_end_sec": ends.astype(float) / float(frame_rate),
            "duration_sec": duration_sec,
            "nonrest_duration_sec": nonrest_duration_sec,
            "n_spikes_all": n_spikes_all,
            "n_spikes_ss": n_spikes_ss,
            "n_spikes_cs": n_spikes_cs,
            "fr_all_hz": fr_all_hz,
            "fr_ss_hz": fr_ss_hz,
            "fr_cs_hz": fr_cs_hz,
            "traversal_types": traversal_types,
            "session_idx": session_idx,
        },
        "theta_stack": theta_arr,
        "slow_stack": slow_arr,
        "rate_stack": rate_arr,
        "ss_rate_stack": ss_rate_arr,
        "cs_rate_stack": cs_rate_arr,
        "ss_pct_stack": ss_pct_arr,
        "cs_pct_stack": cs_pct_arr,
        "plateau_stack": plateau_arr,
        "pf_entry_rel": np.asarray([float(t.get("pf_entry_rel", np.nan)) for t in trials], dtype=float),
        "pf_exit_rel": np.asarray([float(t.get("pf_exit_rel", np.nan)) for t in trials], dtype=float),
        "n_plateaus_per_trial": np.asarray([int(t.get("n_plateaus", 0)) for t in trials], dtype=int),
        "theta_mean": _nanmean_columns(theta_arr),
        "slow_mean": _nanmean_columns(slow_arr),
        "rate_mean": _nanmean_columns(rate_arr),
        "ss_rate_mean": _nanmean_columns(ss_rate_arr),
        "cs_rate_mean": _nanmean_columns(cs_rate_arr),
        "ss_pct_mean": _nanmean_columns(ss_pct_arr),
        "cs_pct_mean": _nanmean_columns(cs_pct_arr),
    }


def _build_time_defined_result_from_distance_result(
    distance_result: dict[str, Any],
    *,
    cell_idx: int,
    traces: np.ndarray,
    vms: np.ndarray,
    speed: np.ndarray,
    all_spikes: list[np.ndarray] | np.ndarray,
    refined_SS: list[np.ndarray] | np.ndarray,
    all_CS_spikes: list[np.ndarray] | np.ndarray,
    frame_rate: float,
    time_window_sec: float,
    theta_freqs: tuple[float, float],
    slow_freqs: float,
    firing_rate_bin_ms: float,
    firing_rate_smooth_ms: float,
    subtract_pre_traversal_baseline: bool,
    resting_speed_threshold: float,
    include_resting_plateaus: bool,
    plateaus_dicts: list[dict[str, Any] | None] | dict[str, Any] | None,
    complex_bursts_dicts: list[dict[str, Any] | None] | dict[str, Any] | None,
    include_long_cb_as_plateau: bool,
    cb_plateau_min_duration_ms: float,
    bad_frame_mask: np.ndarray | None,
    min_traversals: int,
) -> dict[str, Any] | None:
    if distance_result is None:
        return None
    time_window_sec = float(time_window_sec)
    if (not np.isfinite(time_window_sec)) or time_window_sec <= 0:
        raise ValueError("time_window_sec must be a finite number > 0.")
    frame_rate = float(frame_rate)
    window_frames = max(1, int(round(time_window_sec * frame_rate)))
    time_rel = np.arange(-window_frames, window_frames + 1, dtype=float) / frame_rate
    n_time = int(time_rel.size)

    trace = np.asarray(traces[cell_idx], dtype=float)
    trace = interpolate_nan_segment(trace)
    theta_vm = bandpass_filter(trace, theta_freqs[0], theta_freqs[1], frame_rate, order=5)
    slow_vm = lowpass_filter(trace, slow_freqs, frame_rate, order=5)
    theta_amp = np.abs(signal.hilbert(theta_vm))
    vms_cell = np.asarray(vms[cell_idx], dtype=float)
    n_frames = int(trace.size)

    bad_mask = None
    if bad_frame_mask is not None:
        bad_mask = np.asarray(bad_frame_mask, dtype=bool)
        if bad_mask.ndim != 1 or bad_mask.size != n_frames:
            bad_mask = None

    def _spike_indices(src: Any) -> np.ndarray:
        if isinstance(src, (list, tuple)):
            idx = np.asarray(src[cell_idx], dtype=int) if cell_idx < len(src) else np.array([], dtype=int)
        else:
            arr = np.asarray(src, dtype=object)
            idx = np.asarray(arr[cell_idx], dtype=int) if arr.ndim > 0 and cell_idx < arr.shape[0] else np.array([], dtype=int)
        idx = np.unique(idx[(idx >= 0) & (idx < n_frames)])
        if bad_mask is not None and idx.size > 0:
            idx = idx[~bad_mask[idx]]
        return idx

    all_spike_indices = _spike_indices(all_spikes)
    ss_indices = _spike_indices(refined_SS)
    cs_indices = _spike_indices(all_CS_spikes)
    ifr_all = _compute_ifr_from_spike_indices(n_frames, all_spike_indices, frame_rate, firing_rate_bin_ms, firing_rate_smooth_ms)
    ifr_ss = _compute_ifr_from_spike_indices(n_frames, ss_indices, frame_rate, firing_rate_bin_ms, firing_rate_smooth_ms)
    ifr_cs = _compute_ifr_from_spike_indices(n_frames, cs_indices, frame_rate, firing_rate_bin_ms, firing_rate_smooth_ms)
    plateau_starts, plateau_ends = _build_plateau_intervals_for_cell(
        cell_idx=int(cell_idx),
        plateaus_dicts=plateaus_dicts,
        complex_bursts_dicts=complex_bursts_dicts,
        include_long_cb_as_plateau=bool(include_long_cb_as_plateau),
        cb_plateau_min_duration_ms=float(cb_plateau_min_duration_ms),
        frame_rate=float(frame_rate),
        n_frames=int(n_frames),
    )

    all_dir = distance_result.get("all", {})
    trial_data = all_dir.get("trial_data", {}) if isinstance(all_dir, dict) else {}
    starts = np.asarray(trial_data.get("epoch_start_frames", []), dtype=int)
    ends = np.asarray(trial_data.get("epoch_end_frames", []), dtype=int)
    centers = np.asarray(trial_data.get("center_frames", []), dtype=int)
    traversal_types = np.asarray(trial_data.get("traversal_types", []), dtype=object)
    session_idx = np.asarray(trial_data.get("session_idx", []), dtype=int)
    vicinity = np.asarray(trial_data.get("center_vicinity_cm", []), dtype=float)
    nonrest_duration_sec = np.asarray(trial_data.get("nonrest_duration_sec", []), dtype=float)
    n_spikes_all = np.asarray(trial_data.get("n_spikes_all", []), dtype=int)
    n_spikes_ss = np.asarray(trial_data.get("n_spikes_ss", []), dtype=int)
    n_spikes_cs = np.asarray(trial_data.get("n_spikes_cs", []), dtype=int)
    n_trials_raw = min(starts.size, ends.size, centers.size)
    if n_trials_raw <= 0:
        return None

    n_plateaus_distance = np.asarray(all_dir.get("n_plateaus_per_trial", []), dtype=int)
    baseline_start_offset = int(round(2.0 * frame_rate))
    baseline_end_offset = int(round(1.0 * frame_rate))
    trial_payloads: list[dict[str, Any]] = []

    for i in range(n_trials_raw):
        epoch_start = int(starts[i])
        epoch_end = int(ends[i])
        center_idx = int(centers[i])
        if epoch_end <= epoch_start or center_idx < 0 or center_idx >= n_frames:
            continue

        base_start = max(epoch_start - baseline_start_offset, 0)
        base_end = max(epoch_start - baseline_end_offset, 0)
        baseline_theta = np.nanmean(theta_amp[base_start:base_end]) if base_end > base_start else np.nan
        baseline_slow = np.nanmean(slow_vm[base_start:base_end]) if base_end > base_start else np.nan

        src_start = center_idx - window_frames
        src_end = center_idx + window_frames + 1
        read_start = max(src_start, 0)
        read_end = min(src_end, n_frames)
        if read_end <= read_start:
            continue
        write_start = read_start - src_start
        write_end = write_start + (read_end - read_start)
        valid_seg = np.ones(read_end - read_start, dtype=bool)
        if bad_mask is not None:
            valid_seg &= ~bad_mask[read_start:read_end]
        speed_seg = np.asarray(speed[read_start:read_end], dtype=float)
        if not bool(include_resting_plateaus):
            valid_plateau_seg = valid_seg & np.isfinite(speed_seg) & (speed_seg >= float(resting_speed_threshold))
        else:
            valid_plateau_seg = valid_seg

        def _fill_trace(values: np.ndarray | None, *, baseline: float | None = None) -> np.ndarray:
            out = np.full(n_time, np.nan, dtype=float)
            if values is None:
                return out
            seg = np.asarray(values[read_start:read_end], dtype=float).copy()
            if baseline is not None and np.isfinite(float(baseline)):
                seg = seg - float(baseline)
            seg[~valid_seg] = np.nan
            out[write_start:write_end] = seg
            return out

        theta_trial = _fill_trace(theta_amp, baseline=(baseline_theta if bool(subtract_pre_traversal_baseline) else None))
        slow_trial = _fill_trace(slow_vm, baseline=(baseline_slow if bool(subtract_pre_traversal_baseline) else None))
        rate_trial = _fill_trace(ifr_all)
        ss_rate_trial = _fill_trace(ifr_ss)
        cs_rate_trial = _fill_trace(ifr_cs)
        denom = ss_rate_trial + cs_rate_trial
        with np.errstate(divide="ignore", invalid="ignore"):
            ss_pct_trial = np.where(np.isfinite(denom) & (denom > 0), 100.0 * ss_rate_trial / denom, np.nan)
            cs_pct_trial = np.where(np.isfinite(denom) & (denom > 0), 100.0 * cs_rate_trial / denom, np.nan)

        plateau_trial = np.zeros(n_time, dtype=float)
        has_plateau = bool(i < n_plateaus_distance.size and int(n_plateaus_distance[i]) > 0)
        if has_plateau:
            plateau_values = np.asarray(vms_cell[read_start:read_end], dtype=float).copy()
            if bool(subtract_pre_traversal_baseline) and np.isfinite(baseline_slow):
                plateau_values = plateau_values - float(baseline_slow)
            plateau_values[~valid_plateau_seg] = 0.0
            plateau_presence = np.zeros(read_end - read_start, dtype=bool)
            for ps, pe in zip(plateau_starts, plateau_ends):
                overlap_start = max(int(ps), read_start, epoch_start)
                overlap_end = min(int(pe) + 1, read_end, epoch_end)
                if overlap_start < overlap_end:
                    plateau_presence[(overlap_start - read_start):(overlap_end - read_start)] = True
            plateau_presence &= valid_plateau_seg
            if np.any(plateau_presence):
                plateau_seg_out = plateau_trial[write_start:write_end].copy()
                plateau_seg_out[plateau_presence] = plateau_values[plateau_presence]
                plateau_trial[write_start:write_end] = plateau_seg_out

        trial_payloads.append(
            {
                "epoch_start": epoch_start,
                "epoch_end": epoch_end,
                "center_idx": center_idx,
                "center_vicinity_cm": float(vicinity[i]) if i < vicinity.size else np.nan,
                "session_idx": int(session_idx[i]) if i < session_idx.size else 0,
                "traversal_type": str(traversal_types[i]) if i < traversal_types.size else "unknown",
                "pf_entry_rel": float((epoch_start - center_idx) / frame_rate),
                "pf_exit_rel": float((epoch_end - center_idx) / frame_rate),
                "n_plateaus": int(has_plateau),
                "n_spikes_all": int(n_spikes_all[i]) if i < n_spikes_all.size else 0,
                "n_spikes_ss": int(n_spikes_ss[i]) if i < n_spikes_ss.size else 0,
                "n_spikes_cs": int(n_spikes_cs[i]) if i < n_spikes_cs.size else 0,
                "nonrest_duration_sec": float(nonrest_duration_sec[i]) if i < nonrest_duration_sec.size else np.nan,
                "theta_trial": theta_trial,
                "slow_trial": slow_trial,
                "rate_trial": rate_trial,
                "ss_rate_trial": ss_rate_trial,
                "cs_rate_trial": cs_rate_trial,
                "ss_pct_trial": ss_pct_trial,
                "cs_pct_trial": cs_pct_trial,
                "plateau_trial": plateau_trial,
            }
        )

    if len(trial_payloads) < int(min_traversals):
        return None

    all_result = _aggregate_time_defined_trials(trial_payloads, time_rel, frame_rate=float(frame_rate))
    cw_result = _aggregate_time_defined_trials(
        [t for t in trial_payloads if str(t.get("traversal_type", "")) == "cw"],
        time_rel,
        frame_rate=float(frame_rate),
    )
    ccw_result = _aggregate_time_defined_trials(
        [t for t in trial_payloads if str(t.get("traversal_type", "")) == "ccw"],
        time_rel,
        frame_rate=float(frame_rate),
    )
    out = dict(distance_result)
    out.pop("distance_rel", None)
    out["time_rel"] = time_rel
    out["time_window_sec"] = float(time_window_sec)
    out["time_bin_sec"] = float(1.0 / frame_rate)
    out["center_by_pf_position"] = True
    out["all"] = all_result
    out["cw"] = cw_result
    out["ccw"] = ccw_result
    return out


def compute_time_defined_component_result_iterative(
    animal_id: str,
    cell_idx: int,
    pf_rank: int,
    runtime: dict[str, Any],
    config: PipelineConfig,
    distance_params: PFDistanceCenteredParams,
    dilation_bins: int,
    dilation_shape: str,
    *,
    time_window_sec: float,
    distance_window_cm: float,
    detection_window_cm: float,
    distance_bin_cm: float,
    center_vicinity_min_cm: int,
    center_vicinity_max_cm: int,
    moving_speed_threshold: float,
    resting_speed_threshold: float,
    exclude_trials_with_bad_frames: bool,
    pf_source_mode: str,
    include_long_cb_as_plateau: bool,
    include_resting_plateaus: bool,
    cb_plateau_min_duration_ms: float,
    distance_mode: str,
    align_all_pf_components_to_session_compare: bool = True,
    session_compare_cache_version: str = "v2",
    min_traversals: int | None = None,
    bad_frame_mask: np.ndarray | None = None,
) -> dict[str, Any] | None:
    distance_result = compute_distance_defined_component_result_iterative(
        animal_id=animal_id,
        cell_idx=cell_idx,
        pf_rank=pf_rank,
        runtime=runtime,
        config=config,
        distance_params=distance_params,
        dilation_bins=dilation_bins,
        dilation_shape=dilation_shape,
        distance_window_cm=distance_window_cm,
        detection_window_cm=detection_window_cm,
        distance_bin_cm=distance_bin_cm,
        center_vicinity_min_cm=center_vicinity_min_cm,
        center_vicinity_max_cm=center_vicinity_max_cm,
        moving_speed_threshold=moving_speed_threshold,
        resting_speed_threshold=resting_speed_threshold,
        exclude_trials_with_bad_frames=exclude_trials_with_bad_frames,
        pf_source_mode=pf_source_mode,
        include_long_cb_as_plateau=include_long_cb_as_plateau,
        include_resting_plateaus=include_resting_plateaus,
        cb_plateau_min_duration_ms=cb_plateau_min_duration_ms,
        distance_mode=distance_mode,
        plateau_trace_window_ms=float(getattr(distance_params, "plateau_trace_window_ms", 100.0)),
        align_all_pf_components_to_session_compare=align_all_pf_components_to_session_compare,
        session_compare_cache_version=session_compare_cache_version,
        min_traversals=min_traversals,
        bad_frame_mask=bad_frame_mask,
    )
    if distance_result is None:
        return None
    merged = runtime["merged"]
    result = _build_time_defined_result_from_distance_result(
        distance_result,
        cell_idx=int(cell_idx),
        traces=runtime["traces"],
        vms=runtime["vms"],
        speed=np.asarray(merged["speed"], dtype=float),
        all_spikes=merged.get("all_spikes", merged["spikes"]),
        refined_SS=merged.get("refined_SS", [np.array([], dtype=int) for _ in merged["spikes"]]),
        all_CS_spikes=merged.get("all_CS_spikes", [np.array([], dtype=int) for _ in merged["spikes"]]),
        frame_rate=float(merged["frame_rate"]),
        time_window_sec=float(time_window_sec),
        theta_freqs=tuple(config.analysis.theta_freqs),
        slow_freqs=float(config.analysis.slow_freqs),
        firing_rate_bin_ms=float(config.traversal.firing_rate_bin_ms),
        firing_rate_smooth_ms=float(config.traversal.firing_rate_smooth_ms),
        subtract_pre_traversal_baseline=bool(distance_params.subtract_pre_traversal_baseline),
        resting_speed_threshold=float(resting_speed_threshold),
        include_resting_plateaus=bool(include_resting_plateaus),
        plateaus_dicts=merged.get("plateaus_dicts", None),
        complex_bursts_dicts=merged.get("complex_bursts_dicts", None),
        include_long_cb_as_plateau=bool(include_long_cb_as_plateau),
        cb_plateau_min_duration_ms=float(cb_plateau_min_duration_ms),
        bad_frame_mask=bad_frame_mask,
        min_traversals=int(distance_params.min_traversals) if min_traversals is None else int(min_traversals),
    )
    return result


def generate_distance_defined_trials_and_dataset(
    config: PipelineConfig,
    spatial_data: Any,
    distance_params: PFDistanceCenteredParams | None = None,
    *,
    figure_save_folder: str | Path | None = None,
    distance_window_cm: float = 15.0,
    detection_window_cm: float | None = None,
    distance_bin_cm: float = 1.0,
    distance_mode: str | None = None,
    center_vicinity_min_cm: int = 1,
    center_vicinity_max_cm: int = 5,
    moving_speed_threshold: float | None = None,
    resting_speed_threshold: float = 0.5,
    pf_ranks: tuple[int, ...] = (1, 2),
    categories: tuple[str, ...] = ("CSplus", "CSminus"),
    clear_output: bool = True,
    save_summary_csv: bool = True,
    show_plots: bool = False,
    show_rest_patches: bool = True,
    pf_reliability_dilation_bins: int | None = None,
    pf_reliability_dilation_shape: str | None = None,
    trace_slow_gap: float = 1.0,
    theta_slow_pad_factor: float = 0.05,
    sharey: bool = True,
    max_plot_trial_duration_s: float = 25.0,
    include_long_cb_as_plateau: bool | None = None,
    include_resting_plateaus: bool = True,
    cb_plateau_min_duration_ms: float | None = None,
    plateau_trace_window_ms: float | None = None,
    align_all_pf_components_to_session_compare: bool = True,
    session_compare_cache_version: str = "v2",
    max_trials_per_component_plot: int | None = 120,
    print_component_progress: bool = True,
) -> dict[str, Any]:
    import pandas as pd
    import time
    from scipy.ndimage import binary_dilation

    if distance_params is None:
        distance_params = PFDistanceCenteredParams()
    if include_long_cb_as_plateau is None:
        include_long_cb_as_plateau = bool(getattr(distance_params, "include_long_cb_as_plateau", True))
    if cb_plateau_min_duration_ms is None:
        cb_plateau_min_duration_ms = float(getattr(distance_params, "cb_plateau_min_duration_ms", 100.0))
    if plateau_trace_window_ms is None:
        plateau_trace_window_ms = float(getattr(distance_params, "plateau_trace_window_ms", 100.0))
    if moving_speed_threshold is None:
        moving_speed_threshold = float(config.analysis.speed_threshold)
    if distance_mode is None:
        distance_mode = str(getattr(distance_params, "distance_mode", "cumulative_path"))
    distance_mode = _normalize_distance_mode(distance_mode)
    distance_window_cm_req, distance_window_cm_eff, _ = _build_symmetric_distance_axis(
        distance_window_cm,
        distance_bin_cm,
    )
    if detection_window_cm is None:
        detection_window_cm = float(getattr(distance_params, "detection_window_cm", 10.0))
    detection_window_cm_req = float(detection_window_cm)
    if (not np.isfinite(detection_window_cm_req)) or detection_window_cm_req <= 0:
        raise ValueError("detection_window_cm must be a finite number > 0.")
    detection_window_cm_eff = min(float(detection_window_cm_req), float(distance_window_cm_eff))
    if detection_window_cm_req > distance_window_cm_eff + 1e-12:
        print(
            "[distance-defined] Detection window exceeds final span; "
            f"clamped from ±{detection_window_cm_req:g} cm to ±{detection_window_cm_eff:g} cm."
        )
    distance_window_cm = float(distance_window_cm_eff)
    distance_bin_cm = float(distance_bin_cm)
    if distance_window_cm_eff > distance_window_cm_req + 1e-12:
        print(
            "[distance-defined] Expanded distance window "
            f"from ±{distance_window_cm_req:g} cm to ±{distance_window_cm_eff:g} cm "
            f"to match bin size ({distance_bin_cm:g} cm) and include 0 cm center bin."
        )
    if int(center_vicinity_min_cm) <= 0 or int(center_vicinity_max_cm) < int(center_vicinity_min_cm):
        raise ValueError("Invalid center vicinity range.")
    if (not np.isfinite(float(cb_plateau_min_duration_ms))) or float(cb_plateau_min_duration_ms) <= 0:
        raise ValueError("cb_plateau_min_duration_ms must be a finite number > 0.")
    plateau_trace_window_ms = float(plateau_trace_window_ms)
    if (not np.isfinite(plateau_trace_window_ms)) or plateau_trace_window_ms < 0:
        raise ValueError("plateau_trace_window_ms must be a finite number >= 0.")

    if figure_save_folder is None:
        figure_root = config.figures_root / "CKII_pooled"
    else:
        figure_root = Path(figure_save_folder)
    figure_root.mkdir(parents=True, exist_ok=True)

    output_dirs: dict[str, Path] = {}
    for cat in categories:
        cat_norm = _normalize_pf_category_name(cat)
        if cat_norm == "CSplus":
            out_dir = figure_root / "PF_distance_defined_trials_CSplus_PLCs"
        elif cat_norm == "CSminus":
            out_dir = figure_root / "PF_distance_defined_trials_CSminus_PLCs"
        elif cat_norm == "nonPLC":
            out_dir = figure_root / "PF_distance_defined_trials_nonPLC"
        else:
            out_dir = figure_root / f"PF_distance_defined_trials_{cat_norm}"
        output_dirs[cat_norm] = out_dir
    summary_csv = figure_root / "PF_distance_defined_trials_summary.csv"

    if clear_output:
        for out_dir in output_dirs.values():
            if out_dir.exists():
                shutil.rmtree(out_dir)
            out_dir.mkdir(parents=True, exist_ok=True)
    else:
        for out_dir in output_dirs.values():
            out_dir.mkdir(parents=True, exist_ok=True)

    if pf_reliability_dilation_bins is None:
        dilation_bins = int(config.place_cell.pf_reliability_dilation_bins)
    else:
        dilation_bins = int(pf_reliability_dilation_bins)
    if pf_reliability_dilation_shape is None:
        dilation_shape = str(config.place_cell.pf_reliability_dilation_shape).strip().lower()
    else:
        dilation_shape = str(pf_reliability_dilation_shape).strip().lower()
    if dilation_bins < 0:
        raise ValueError("pf_reliability_dilation_bins must be >= 0.")
    dilation_structure = (
        core._build_pf_dilation_structure(dilation_bins, dilation_shape)
        if dilation_bins > 0
        else None
    )

    trial_resting_speed_threshold = float(resting_speed_threshold)
    trial_max_plot_duration_s = float(max_plot_trial_duration_s)
    if not np.isfinite(trial_max_plot_duration_s) or trial_max_plot_duration_s <= 0:
        raise ValueError("max_plot_trial_duration_s must be > 0.")
    if max_trials_per_component_plot is None:
        max_trials_per_component_plot_eff = None
    else:
        max_trials_per_component_plot_eff = int(max_trials_per_component_plot)
        if max_trials_per_component_plot_eff <= 0:
            raise ValueError("max_trials_per_component_plot must be None or a positive integer.")
    trial_theta_freqs = tuple(config.analysis.theta_freqs)
    trial_slow_freqs = float(config.analysis.slow_freqs)
    trial_session_indices = tuple(config.traversal.session_indices)
    trial_firing_rate_bin_ms = float(config.traversal.firing_rate_bin_ms)
    trial_firing_rate_smooth_ms = float(config.traversal.firing_rate_smooth_ms)
    trial_pf_center_window_sec = float(config.traversal.pf_center_window_sec)

    dataset: dict[str, Any] = {
        "metadata": {
            "dilation_bins": int(dilation_bins),
            "dilation_shape": str(dilation_shape),
            "pf_ranks": tuple(int(r) for r in pf_ranks),
            "categories": tuple(_normalize_pf_category_name(c) for c in categories),
            "distance_window_cm": float(distance_window_cm),
            "distance_window_cm_requested": float(distance_window_cm_req),
            "distance_window_cm_effective": float(distance_window_cm_eff),
            "detection_window_cm": float(detection_window_cm_eff),
            "detection_window_cm_requested": float(detection_window_cm_req),
            "detection_window_cm_effective": float(detection_window_cm_eff),
            "distance_bin_cm": float(distance_bin_cm),
            "distance_mode": str(distance_mode),
            "include_long_cb_as_plateau": bool(include_long_cb_as_plateau),
            "include_resting_plateaus": bool(include_resting_plateaus),
            "cb_plateau_min_duration_ms": float(cb_plateau_min_duration_ms),
            "plateau_trace_window_ms": float(plateau_trace_window_ms),
            "center_vicinity_min_cm": int(center_vicinity_min_cm),
            "center_vicinity_max_cm": int(center_vicinity_max_cm),
            "moving_speed_threshold": float(moving_speed_threshold),
            "resting_speed_threshold": float(trial_resting_speed_threshold),
            "min_traversals": int(distance_params.min_traversals),
            "min_traversals_per_type": int(distance_params.min_traversals_per_type),
            "subtract_pre_traversal_baseline": bool(distance_params.subtract_pre_traversal_baseline),
            "exclude_trials_with_bad_frames": bool(distance_params.exclude_trials_with_bad_frames),
            "pf_component_selection": str(distance_params.pf_component_selection),
            "max_pf_distance_cm": distance_params.max_pf_distance_cm,
            "smooth_window_cm": float(distance_params.smooth_window),
            "traversal_merge_gap_s": float(getattr(config.traversal, "traversal_merge_gap_s", 0.0)),
            "session_indices": tuple(config.traversal.session_indices),
            "align_all_pf_components_to_session_compare": bool(align_all_pf_components_to_session_compare),
            "session_compare_cache_version": str(session_compare_cache_version),
            "max_trials_per_component_plot": max_trials_per_component_plot_eff,
            "print_component_progress": bool(print_component_progress),
        }
    }

    runtime_cache: dict[str, dict[str, Any]] = {}
    summary_rows: list[dict[str, Any]] = []
    category_counters: dict[str, dict[str, int]] = {}
    category_pf_sources: dict[str, str] = {
        _normalize_pf_category_name(cat): ("ss" if _normalize_pf_category_name(cat) == "nonPLC" else "all")
        for cat in categories
    }
    dataset["metadata"]["pf_source_by_category"] = dict(category_pf_sources)

    def _append_summary_row(
        *,
        category_name: str,
        animal_id: str,
        cell_idx: int,
        pf_rank: int | float,
        status: str,
        message: str,
        n_traversals: int | float = np.nan,
    ) -> None:
        summary_rows.append(
            {
                "category": category_name,
                "animal_id": str(animal_id),
                "cell_idx": int(cell_idx),
                "cell_num": int(cell_idx + 1) if int(cell_idx) >= 0 else np.nan,
                "pf_rank": pf_rank,
                "status": str(status),
                "n_traversals": n_traversals,
                "message": str(message),
            }
        )

    def _append_distance_dataset_entry(
        *,
        category_payload: dict[int, dict[str, Any]],
        rank_int: int,
        animal_id: str,
        cell_idx: int,
        result: dict[str, Any],
        pf_source_mode: str,
    ) -> None:
        category_payload[int(rank_int)]["entries"].append(
            {
                "session": str(animal_id),
                "cell_idx": int(cell_idx),
                "pf_rank": int(rank_int),
                "pf_source": str(result.get("pf_source", pf_source_mode)),
                "data": result,
            }
        )

    def _append_skip_rows_for_all_ranks(
        *,
        category_name: str,
        animal_id: str,
        cell_idx: int,
        status: str,
        message: str,
    ) -> None:
        for rank in pf_ranks:
            _append_summary_row(
                category_name=category_name,
                animal_id=animal_id,
                cell_idx=cell_idx,
                pf_rank=int(rank),
                status=status,
                message=message,
            )

    for category in categories:
        cat = _normalize_pf_category_name(category)
        out_dir = output_dirs[cat]
        category_cells = _get_spatial_category_cells(spatial_data, cat)
        category_counters[cat] = {
            "attempted_cells": 0,
            "attempted_components": 0,
            "saved": 0,
            "plots_skipped_many_trials": 0,
            "skipped_or_error": 0,
        }
        category_payload: dict[int, dict[str, Any]] = {}
        for pf_rank in pf_ranks:
            category_payload[int(pf_rank)] = {
                "distance_rel": None,
                "entries": [],
                "n_requested_cells": len(category_cells),
                "n_entries": 0,
                "n_skipped": 0,
            }

        for cell_meta in category_cells:
            animal_id = str(cell_meta.get("session", ""))
            cell_idx = int(cell_meta.get("cell_idx", -1))
            category_counters[cat]["attempted_cells"] += 1
            if not animal_id or cell_idx < 0:
                category_counters[cat]["skipped_or_error"] += 1
                for pf_rank in pf_ranks:
                    category_payload[int(pf_rank)]["n_skipped"] = int(category_payload[int(pf_rank)]["n_skipped"]) + 1
                _append_skip_rows_for_all_ranks(
                    category_name=cat,
                    animal_id=animal_id,
                    cell_idx=cell_idx,
                    status="skip_invalid_cell_meta",
                    message="Missing/invalid animal_id or cell_idx in spatial_data cell metadata.",
                )
                continue
            try:
                if animal_id not in runtime_cache:
                    runtime_cache[animal_id] = _build_trial_plot_runtime_payload(animal_id, config)
                runtime = runtime_cache[animal_id]
                merged = runtime["merged"]
                spatial_by_idx = runtime["spatial_by_idx"]
                analysis = spatial_by_idx.get(cell_idx)
                if analysis is None:
                    category_counters[cat]["skipped_or_error"] += 1
                    for pf_rank in pf_ranks:
                        category_payload[int(pf_rank)]["n_skipped"] = int(category_payload[int(pf_rank)]["n_skipped"]) + 1
                    _append_skip_rows_for_all_ranks(
                        category_name=cat,
                        animal_id=animal_id,
                        cell_idx=cell_idx,
                        status="skip_missing_runtime_spatial_analysis",
                        message="Cell missing in runtime spatial analysis.",
                    )
                    continue
                pf_source_mode = str(category_pf_sources.get(cat, "all")).strip().lower()
                if pf_source_mode == "ss":
                    if bool(analysis.get("is_place_cell", False)):
                        category_counters[cat]["skipped_or_error"] += 1
                        for pf_rank in pf_ranks:
                            category_payload[int(pf_rank)]["n_skipped"] = int(category_payload[int(pf_rank)]["n_skipped"]) + 1
                        _append_skip_rows_for_all_ranks(
                            category_name=cat,
                            animal_id=animal_id,
                            cell_idx=cell_idx,
                            status="skip_nonplc_is_place_cell",
                            message="nonPLC category requires is_place_cell=False, but this cell is an all-spike place cell.",
                        )
                        continue
                    if not bool(analysis.get("is_place_cell_ss", False)):
                        category_counters[cat]["skipped_or_error"] += 1
                        for pf_rank in pf_ranks:
                            category_payload[int(pf_rank)]["n_skipped"] = int(category_payload[int(pf_rank)]["n_skipped"]) + 1
                        _append_skip_rows_for_all_ranks(
                            category_name=cat,
                            animal_id=animal_id,
                            cell_idx=cell_idx,
                            status="skip_nonplc_not_ss_place_cell",
                            message="nonPLC category requires is_place_cell_ss=True (non all-spike PLC + SS PLC).",
                        )
                        continue
                else:
                    if not bool(analysis.get("is_place_cell", False)):
                        category_counters[cat]["skipped_or_error"] += 1
                        for pf_rank in pf_ranks:
                            category_payload[int(pf_rank)]["n_skipped"] = int(category_payload[int(pf_rank)]["n_skipped"]) + 1
                        _append_skip_rows_for_all_ranks(
                            category_name=cat,
                            animal_id=animal_id,
                            cell_idx=cell_idx,
                            status="skip_not_place_cell_runtime",
                            message="Cell missing in runtime spatial analysis or is_place_cell=False.",
                        )
                        continue

                pf_source_info = _resolve_distance_defined_pf_component_source(
                    animal_id=animal_id,
                    cell_idx=int(cell_idx),
                    analysis=analysis,
                    config=config,
                    pf_source_mode=pf_source_mode,
                    align_all_pf_components_to_session_compare=bool(align_all_pf_components_to_session_compare),
                    session_compare_cache_version=str(session_compare_cache_version),
                )
                components_raw = list(pf_source_info.get("components_raw", []) or [])
                fallback_mask = np.asarray(pf_source_info.get("fallback_mask", []), dtype=bool)
                fallback_peak = pf_source_info.get("fallback_peak_rate", np.nan)
                source_rate_map = np.asarray(pf_source_info.get("source_rate_map", []), dtype=float)
                missing_pf_message = str(pf_source_info.get("missing_pf_message", "No place-field components."))

                components = _sanitize_ranked_pf_components(
                    components_raw,
                    fallback_mask,
                    rate_map=(source_rate_map if source_rate_map.size > 0 else None),
                    fallback_peak_rate=float(fallback_peak),
                    max_components=None,
                )
                if not components:
                    category_counters[cat]["skipped_or_error"] += 1
                    for pf_rank in pf_ranks:
                        category_payload[int(pf_rank)]["n_skipped"] = int(category_payload[int(pf_rank)]["n_skipped"]) + 1
                    _append_skip_rows_for_all_ranks(
                        category_name=cat,
                        animal_id=animal_id,
                        cell_idx=cell_idx,
                        status="skip_no_place_field_components",
                        message=missing_pf_message,
                    )
                    continue

                rank_to_eval_mask: dict[int, np.ndarray] = {}
                trajectory_contours: list[dict[str, Any]] = []
                for rank_i, comp_i in enumerate(components, start=1):
                    comp_mask_i = np.asarray(comp_i.get("mask", []), dtype=bool)
                    if comp_mask_i.size == 0 or not np.any(comp_mask_i):
                        continue
                    comp_eval_i = comp_mask_i
                    if dilation_structure is not None:
                        comp_eval_i = binary_dilation(comp_mask_i, structure=dilation_structure)
                    rank_to_eval_mask[int(rank_i)] = np.asarray(comp_eval_i, dtype=bool)
                    if rank_i <= 2:
                        trajectory_contours.append(
                            {
                                "mask": np.asarray(comp_eval_i, dtype=bool),
                                "color": "magenta" if rank_i == 1 else "cyan",
                                "linewidth": 0.8,
                                "linestyle": "solid",
                                "alpha": 1.0,
                            }
                        )

                traces = runtime["traces"]
                x_neural = np.asarray(merged["x_neural"], dtype=float)
                y_neural = np.asarray(merged["y_neural"], dtype=float)
                speed = np.asarray(merged["speed"], dtype=float)
                spikes = merged["spikes"]
                all_spikes = merged.get("all_spikes", merged["spikes"])
                refined_ss = merged.get("refined_SS", [np.array([], dtype=int) for _ in spikes])
                all_cs_spikes = merged.get("all_CS_spikes", [np.array([], dtype=int) for _ in spikes])
                complex_bursts_dicts = merged.get("complex_bursts_dicts", [])
                plateaus_dicts = merged.get("plateaus_dicts", None)
                session_start_frames = merged.get("session_start_frames", [0])
                frame_rate = float(merged["frame_rate"])

                bad_timepoints = (
                    runtime["bad_masks"][cell_idx]
                    if isinstance(runtime["bad_masks"], np.ndarray) and cell_idx < len(runtime["bad_masks"])
                    else None
                )
                bad_mask = None
                if bad_timepoints is not None:
                    bad_mask = np.asarray(bad_timepoints, dtype=bool)
                    if bad_mask.shape[0] != x_neural.shape[0]:
                        raise ValueError(f"bad_timepoints length mismatch for {animal_id} cell {cell_idx}.")

                raw_bad_mask = None
                traces_raw_source = merged.get("traces", None)
                if traces_raw_source is not None and cell_idx < len(traces_raw_source):
                    raw_trace = np.asarray(traces_raw_source[cell_idx], dtype=float)
                    if raw_trace.ndim == 1 and raw_trace.shape[0] == x_neural.shape[0]:
                        raw_bad_mask = ~np.isfinite(raw_trace)

                traversal_bad_mask = None
                if bad_mask is not None and raw_bad_mask is not None:
                    traversal_bad_mask = bad_mask | raw_bad_mask
                elif bad_mask is not None:
                    traversal_bad_mask = bad_mask
                elif raw_bad_mask is not None:
                    traversal_bad_mask = raw_bad_mask

                x_neural_plot = x_neural.copy()
                y_neural_plot = y_neural.copy()
                speed_plot = speed.copy()
                if traversal_bad_mask is not None:
                    x_neural_plot[traversal_bad_mask] = np.nan
                    y_neural_plot[traversal_bad_mask] = np.nan
                    speed_plot[traversal_bad_mask] = np.nan

                def _filter_spike_indices(spike_source: Any) -> np.ndarray:
                    if isinstance(spike_source, (list, tuple, np.ndarray)):
                        src = spike_source[cell_idx] if isinstance(spike_source, (list, tuple)) else spike_source
                    else:
                        src = np.array([], dtype=int)
                    idx = np.asarray(src, dtype=int)
                    idx = idx[(idx >= 0) & (idx < x_neural.shape[0])]
                    if traversal_bad_mask is not None and idx.size > 0:
                        idx = idx[~traversal_bad_mask[idx]]
                    return idx

                all_spikes_cell = _filter_spike_indices(all_spikes)
                refined_ss_cell = _filter_spike_indices(refined_ss)
                all_cs_spikes_cell = _filter_spike_indices(all_cs_spikes)
                trace = np.asarray(traces[cell_idx], dtype=float)
                trace = core.interpolate_nan_segment(trace)
                theta_vm = core.bandpass_filter(trace, trial_theta_freqs[0], trial_theta_freqs[1], frame_rate, order=5)
                slow_vm = core.lowpass_filter(trace, trial_slow_freqs, frame_rate, order=5)

                for pf_rank in pf_ranks:
                    rank_int = int(pf_rank)
                    category_counters[cat]["attempted_components"] += 1
                    if rank_int > len(components):
                        category_payload[rank_int]["n_skipped"] = int(category_payload[rank_int]["n_skipped"]) + 1
                        category_counters[cat]["skipped_or_error"] += 1
                        _append_summary_row(
                            category_name=cat,
                            animal_id=animal_id,
                            cell_idx=cell_idx,
                            pf_rank=rank_int,
                            status="skip_missing_pf_rank_component",
                            message=f"PF{rank_int} component not present (n_components={len(components)}).",
                        )
                        continue
                    if rank_int not in rank_to_eval_mask:
                        category_payload[rank_int]["n_skipped"] = int(category_payload[rank_int]["n_skipped"]) + 1
                        category_counters[cat]["skipped_or_error"] += 1
                        _append_summary_row(
                            category_name=cat,
                            animal_id=animal_id,
                            cell_idx=cell_idx,
                            pf_rank=rank_int,
                            status="skip_empty_pf_component_mask",
                            message=f"PF{rank_int} component mask is empty after validity checks.",
                        )
                        continue

                    if print_component_progress:
                        print(
                            f"[distance-defined] {cat} {animal_id} Cell{cell_idx + 1} PF{rank_int}: "
                            "computing trials...",
                            flush=True,
                        )
                    component_start = time.perf_counter()
                    result = compute_distance_defined_component_result_iterative(
                        animal_id=animal_id,
                        cell_idx=cell_idx,
                        pf_rank=rank_int,
                        runtime=runtime,
                        config=config,
                        distance_params=distance_params,
                        dilation_bins=dilation_bins,
                        dilation_shape=dilation_shape,
                        distance_window_cm=float(distance_window_cm),
                        detection_window_cm=float(detection_window_cm_eff),
                        distance_bin_cm=float(distance_bin_cm),
                        center_vicinity_min_cm=int(center_vicinity_min_cm),
                        center_vicinity_max_cm=int(center_vicinity_max_cm),
                        moving_speed_threshold=float(moving_speed_threshold),
                        resting_speed_threshold=float(trial_resting_speed_threshold),
                        exclude_trials_with_bad_frames=bool(distance_params.exclude_trials_with_bad_frames),
                        pf_source_mode=str(pf_source_mode),
                        include_long_cb_as_plateau=bool(include_long_cb_as_plateau),
                        include_resting_plateaus=bool(include_resting_plateaus),
                        cb_plateau_min_duration_ms=float(cb_plateau_min_duration_ms),
                        plateau_trace_window_ms=float(plateau_trace_window_ms),
                        distance_mode=str(distance_mode),
                        align_all_pf_components_to_session_compare=bool(align_all_pf_components_to_session_compare),
                        session_compare_cache_version=str(session_compare_cache_version),
                        min_traversals=1,
                        bad_frame_mask=traversal_bad_mask,
                    )
                    compute_elapsed = time.perf_counter() - component_start
                    if result is None:
                        if print_component_progress:
                            print(
                                f"[distance-defined] {cat} {animal_id} Cell{cell_idx + 1} PF{rank_int}: "
                                f"no valid result ({compute_elapsed:.1f}s).",
                                flush=True,
                            )
                        category_payload[rank_int]["n_skipped"] = int(category_payload[rank_int]["n_skipped"]) + 1
                        category_counters[cat]["skipped_or_error"] += 1
                        _append_summary_row(
                            category_name=cat,
                            animal_id=animal_id,
                            cell_idx=cell_idx,
                            pf_rank=rank_int,
                            status="skip_no_distance_defined_result",
                            message=(
                                "Iterative distance-defined detection returned no result "
                                "(e.g., no valid trials or too few traversals after internal filtering)."
                            ),
                        )
                        continue

                    distance_rel = np.asarray(result.get("distance_rel", []), dtype=float)
                    if distance_rel.size == 0:
                        category_payload[rank_int]["n_skipped"] = int(category_payload[rank_int]["n_skipped"]) + 1
                        category_counters[cat]["skipped_or_error"] += 1
                        _append_summary_row(
                            category_name=cat,
                            animal_id=animal_id,
                            cell_idx=cell_idx,
                            pf_rank=rank_int,
                            status="skip_empty_distance_axis",
                            message="distance_rel is empty in computed component result.",
                        )
                        continue
                    distance_rel_ref = category_payload[rank_int]["distance_rel"]
                    if distance_rel_ref is None:
                        category_payload[rank_int]["distance_rel"] = distance_rel
                    else:
                        distance_rel_ref_arr = np.asarray(distance_rel_ref, dtype=float)
                        if distance_rel_ref_arr.size != distance_rel.size:
                            category_payload[rank_int]["n_skipped"] = int(category_payload[rank_int]["n_skipped"]) + 1
                            category_counters[cat]["skipped_or_error"] += 1
                            _append_summary_row(
                                category_name=cat,
                                animal_id=animal_id,
                                cell_idx=cell_idx,
                                pf_rank=rank_int,
                                status="skip_distance_axis_mismatch",
                                message=(
                                    "distance_rel length mismatch for this PF rank block "
                                    f"(existing={distance_rel_ref_arr.size}, current={distance_rel.size})."
                                ),
                            )
                            continue

                    trial_data = result.get("all", {}).get("trial_data", {})
                    epoch_start_frames = np.asarray(trial_data.get("epoch_start_frames", []), dtype=int)
                    epoch_end_frames = np.asarray(trial_data.get("epoch_end_frames", []), dtype=int)
                    traversal_types = list(np.asarray(trial_data.get("traversal_types", []), dtype=object))
                    n_trials = int(epoch_start_frames.size)
                    traversal_epochs = list(zip(epoch_start_frames.tolist(), epoch_end_frames.tolist()))
                    if print_component_progress:
                        print(
                            f"[distance-defined] {cat} {animal_id} Cell{cell_idx + 1} PF{rank_int}: "
                            f"computed {n_trials} trials in {compute_elapsed:.1f}s.",
                            flush=True,
                        )
                    place_field_mask = result.get("place_field_mask", rank_to_eval_mask.get(rank_int))
                    pf_bins = result.get("pf_bins", None)
                    pf_peak_xy = result.get("pf_peak_xy", None)
                    if place_field_mask is None or pf_bins is None:
                        category_payload[rank_int]["n_skipped"] = int(category_payload[rank_int]["n_skipped"]) + 1
                        category_counters[cat]["skipped_or_error"] += 1
                        _append_summary_row(
                            category_name=cat,
                            animal_id=animal_id,
                            cell_idx=cell_idx,
                            pf_rank=rank_int,
                            status="skip_missing_pf_geometry",
                            message="Missing place_field_mask and/or pf_bins for plotting.",
                            n_traversals=int(n_trials),
                        )
                        continue

                    if (
                        max_trials_per_component_plot_eff is not None
                        and n_trials > int(max_trials_per_component_plot_eff)
                    ):
                        _append_distance_dataset_entry(
                            category_payload=category_payload,
                            rank_int=rank_int,
                            animal_id=animal_id,
                            cell_idx=cell_idx,
                            result=result,
                            pf_source_mode=pf_source_mode,
                        )
                        category_counters[cat]["saved"] += 1
                        category_counters[cat]["plots_skipped_many_trials"] += 1
                        message = (
                            f"Dataset kept, SVG skipped because n_trials={n_trials} exceeds "
                            f"max_trials_per_component_plot={max_trials_per_component_plot_eff}."
                        )
                        _append_summary_row(
                            category_name=cat,
                            animal_id=animal_id,
                            cell_idx=cell_idx,
                            pf_rank=rank_int,
                            status="saved_dataset_plot_skipped_many_trials",
                            message=message,
                            n_traversals=int(n_trials),
                        )
                        if print_component_progress:
                            print(
                                f"[distance-defined] {cat} {animal_id} Cell{cell_idx + 1} PF{rank_int}: "
                                f"{message}",
                                flush=True,
                            )
                        continue

                    plateau_starts_plot, plateau_ends_plot = _build_plateau_intervals_for_cell(
                        cell_idx=int(cell_idx),
                        plateaus_dicts=plateaus_dicts,
                        complex_bursts_dicts=complex_bursts_dicts,
                        include_long_cb_as_plateau=bool(include_long_cb_as_plateau),
                        cb_plateau_min_duration_ms=float(cb_plateau_min_duration_ms),
                        frame_rate=float(frame_rate),
                        n_frames=int(x_neural.shape[0]),
                    )
                    plateaus_for_plot = {"starts": plateau_starts_plot, "ends": plateau_ends_plot}

                    if print_component_progress:
                        print(
                            f"[distance-defined] {cat} {animal_id} Cell{cell_idx + 1} PF{rank_int}: "
                            f"plotting {n_trials} trials...",
                            flush=True,
                        )
                    plot_start = time.perf_counter()
                    plot_result = core.plot_place_field_traversal_trials_with_cb_example_centered_by_max_rate(
                        trace,
                        theta_vm,
                        slow_vm,
                        speed_plot,
                        x_neural_plot,
                        y_neural_plot,
                        traversal_epochs,
                        place_field_mask,
                        pf_bins,
                        frame_rate,
                        complex_bursts_dicts=complex_bursts_dicts,
                        cell_idx=cell_idx,
                        traversal_types=traversal_types,
                        padding_sec=0.0,
                        zscore_traces=False,
                        theta_freqs=trial_theta_freqs,
                        slow_freqs=trial_slow_freqs,
                        session_start_frames=session_start_frames,
                        session_indices=trial_session_indices,
                        color_by_session=True,
                        resting_speed_threshold=trial_resting_speed_threshold,
                        show_rest_patches=bool(show_rest_patches),
                        show_pf_prepost_patches=True,
                        pf_prepost_patch_alpha=0.1,
                        pf_prepost_patch_scope="full_window",
                        pf_prepost_running_only=False,
                        pf_prepost_patch_defs=[
                            {
                                "mask": np.asarray(place_field_mask, dtype=bool),
                                "color": ("magenta" if rank_int == 1 else "cyan"),
                            }
                        ],
                        rest_patch_scope="full_window",
                        rest_patch_require_in_pf=False,
                        min_rest_patch_duration_s=1.0,
                        rest_patch_color="#B3B3B3",
                        rest_patch_alpha=0.25,
                        shade_traversal_epoch=False,
                        gradient_traversal_trajectory=True,
                        trajectory_rasterized=True,
                        trajectory_direction_label_top=True,
                        trajectory_direction_label_fontsize=5,
                        max_plot_trial_duration_s=trial_max_plot_duration_s,
                        drop_epochs_with_bad_timepoints=bool(distance_params.exclude_trials_with_bad_frames),
                        refined_SS=refined_ss_cell,
                        all_CS_spikes=all_cs_spikes_cell,
                        all_spikes=all_spikes_cell,
                        firing_rate_bin_ms=trial_firing_rate_bin_ms,
                        firing_rate_smooth_ms=trial_firing_rate_smooth_ms,
                        show_firing_rate=False,
                        simple_spike_color="#026C80",
                        complex_spike_color="#EE9B00",
                        pf_peak_xy=pf_peak_xy,
                        pf_center_window_sec=trial_pf_center_window_sec,
                        plot_pf_centered_average=True,
                        return_pf_centered=True,
                        return_spike_rate_means=True,
                        show=show_plots,
                        bad_timepoints=traversal_bad_mask,
                        return_trial_firing_rates=True,
                        center_by_pf_position=True,
                        max_pf_distance_cm=distance_params.max_pf_distance_cm,
                        plateaus_dicts=plateaus_for_plot,
                        slow_trace_gap=float(trace_slow_gap),
                        theta_slow_pad_factor=float(theta_slow_pad_factor),
                        trace_ymax_from_simple_spikes=(str(cat) == "CSminus"),
                        sharey=bool(sharey),
                        place_field_contours=trajectory_contours,
                        center_position_label=f"Closest to PF{pf_rank}",
                        pf_peak_label=f"PF{pf_rank} peak",
                        pf_peak_color=("magenta" if rank_int == 1 else "cyan"),
                    )
                    plot_elapsed = time.perf_counter() - plot_start
                    fig = plot_result[0] if isinstance(plot_result, tuple) and len(plot_result) > 0 else plot_result
                    axes = plot_result[1] if isinstance(plot_result, tuple) and len(plot_result) > 1 else None
                    valid_epochs_plot = (
                        list(plot_result[2])
                        if isinstance(plot_result, tuple) and len(plot_result) > 2 and plot_result[2] is not None
                        else list(traversal_epochs)
                    )
                    n_trials_plot = int(len(valid_epochs_plot))
                    if fig is None:
                        if print_component_progress:
                            print(
                                f"[distance-defined] {cat} {animal_id} Cell{cell_idx + 1} PF{rank_int}: "
                                f"plot returned fig=None ({plot_elapsed:.1f}s).",
                                flush=True,
                            )
                        category_payload[rank_int]["n_skipped"] = int(category_payload[rank_int]["n_skipped"]) + 1
                        category_counters[cat]["skipped_or_error"] += 1
                        _append_summary_row(
                            category_name=cat,
                            animal_id=animal_id,
                            cell_idx=cell_idx,
                            pf_rank=rank_int,
                            status="skip_plot_figure_none",
                            message="Traversal plot function returned fig=None.",
                            n_traversals=int(n_trials),
                        )
                        continue
                    if n_trials_plot != n_trials:
                        if not show_plots:
                            plt.close(fig)
                        if print_component_progress:
                            print(
                                f"[distance-defined] {cat} {animal_id} Cell{cell_idx + 1} PF{rank_int}: "
                                f"plot epoch mismatch ({n_trials_plot} plotted vs {n_trials} dataset).",
                                flush=True,
                            )
                        category_payload[rank_int]["n_skipped"] = int(category_payload[rank_int]["n_skipped"]) + 1
                        category_counters[cat]["skipped_or_error"] += 1
                        _append_summary_row(
                            category_name=cat,
                            animal_id=animal_id,
                            cell_idx=cell_idx,
                            pf_rank=rank_int,
                            status="skip_plot_epoch_mismatch",
                            message=(
                                f"Dataset trials ({n_trials}) != plotted valid epochs ({n_trials_plot}); "
                                "skipped to keep dataset/plot consistency."
                            ),
                            n_traversals=int(n_trials_plot),
                        )
                        continue

                    _remove_trial_plot_trajectory_start_end_indicators(axes)
                    out_name = f"{animal_id}_Cell{cell_idx + 1}_PF{rank_int}_distance_defined_traversal.svg"
                    out_path = out_dir / out_name
                    if print_component_progress:
                        print(
                            f"[distance-defined] {cat} {animal_id} Cell{cell_idx + 1} PF{rank_int}: "
                            f"saving {out_path}...",
                            flush=True,
                        )
                    save_start = time.perf_counter()
                    fig.savefig(out_path, dpi=300)
                    save_elapsed = time.perf_counter() - save_start
                    if not show_plots:
                        plt.close(fig)
                    _append_distance_dataset_entry(
                        category_payload=category_payload,
                        rank_int=rank_int,
                        animal_id=animal_id,
                        cell_idx=cell_idx,
                        result=result,
                        pf_source_mode=pf_source_mode,
                    )
                    _append_summary_row(
                        category_name=cat,
                        animal_id=animal_id,
                        cell_idx=cell_idx,
                        pf_rank=rank_int,
                        status="saved",
                        message=str(out_path),
                        n_traversals=int(n_trials_plot),
                    )
                    category_counters[cat]["saved"] += 1
                    if print_component_progress:
                        print(
                            f"[distance-defined] {cat} {animal_id} Cell{cell_idx + 1} PF{rank_int}: "
                            f"saved ({plot_elapsed:.1f}s plot, {save_elapsed:.1f}s save).",
                            flush=True,
                        )
            except Exception as exc:
                if print_component_progress:
                    print(
                        f"[distance-defined] {cat} {animal_id} Cell{cell_idx + 1}: error: {exc}",
                        flush=True,
                    )
                _append_summary_row(
                    category_name=cat,
                    animal_id=animal_id,
                    cell_idx=cell_idx,
                    pf_rank=np.nan,
                    status="error",
                    message=str(exc),
                )
                category_counters[cat]["skipped_or_error"] += 1
                for pf_rank in pf_ranks:
                    category_payload[int(pf_rank)]["n_skipped"] = int(category_payload[int(pf_rank)]["n_skipped"]) + 1

        for pf_rank in pf_ranks:
            block = category_payload[int(pf_rank)]
            block["n_entries"] = int(len(block["entries"]))
        dataset[cat] = category_payload

    summary_columns = [
        "category",
        "animal_id",
        "cell_idx",
        "cell_num",
        "pf_rank",
        "status",
        "n_detected_traversals",
        "n_classified_traversals",
        "n_preferred_traversals",
        "n_nonpreferred_traversals",
        "n_unclassified_traversals",
        "preferred_fraction_threshold",
        "preferred_half_width_deg",
        "min_covered_green_bins",
        "traversal_bin_selection_mode",
        "preferred_angle_source",
        "fit_angle_fallback_to_empirical",
        "classification_frame_selection_mode",
        "classification_drz_segment_mode",
        "classification_phase_signed_drz_filter",
        "classification_speed_threshold_used",
        "first_n_minutes",
        "min_valid_traversal_duration_s",
        "message",
    ]
    summary_df = pd.DataFrame(summary_rows, columns=summary_columns)
    if save_summary_csv:
        summary_df.to_csv(summary_csv, index=False)

    plot_summary = {
        "output_dirs": {k: str(v) for k, v in output_dirs.items()},
        "summary_csv": str(summary_csv) if save_summary_csv else None,
        "summary_df": summary_df,
        "counters": category_counters,
        "distance_window_cm": float(distance_window_cm),
        "distance_window_cm_requested": float(distance_window_cm_req),
        "distance_window_cm_effective": float(distance_window_cm_eff),
        "detection_window_cm": float(detection_window_cm_eff),
        "detection_window_cm_requested": float(detection_window_cm_req),
        "detection_window_cm_effective": float(detection_window_cm_eff),
        "distance_bin_cm": float(distance_bin_cm),
        "distance_mode": str(distance_mode),
        "include_long_cb_as_plateau": bool(include_long_cb_as_plateau),
        "include_resting_plateaus": bool(include_resting_plateaus),
        "cb_plateau_min_duration_ms": float(cb_plateau_min_duration_ms),
        "plateau_trace_window_ms": float(plateau_trace_window_ms),
        "center_vicinity_min_cm": int(center_vicinity_min_cm),
        "center_vicinity_max_cm": int(center_vicinity_max_cm),
        "moving_speed_threshold": float(moving_speed_threshold),
        "resting_speed_threshold": float(trial_resting_speed_threshold),
        "dilation_bins": int(dilation_bins),
        "dilation_shape": str(dilation_shape),
        "trace_slow_gap": float(trace_slow_gap),
        "theta_slow_pad_factor": float(theta_slow_pad_factor),
        "max_plot_trial_duration_s": float(trial_max_plot_duration_s),
        "max_trials_per_component_plot": max_trials_per_component_plot_eff,
        "print_component_progress": bool(print_component_progress),
    }
    return {"plot_summary": plot_summary, "dataset": dataset}


def generate_time_defined_trials_and_dataset(
    config: PipelineConfig,
    spatial_data: Any,
    distance_params: PFDistanceCenteredParams | None = None,
    *,
    figure_save_folder: str | Path | None = None,
    time_window_sec: float = 4.0,
    distance_window_cm: float = 15.0,
    detection_window_cm: float | None = None,
    distance_bin_cm: float = 1.5,
    distance_mode: str | None = None,
    center_vicinity_min_cm: int = 1,
    center_vicinity_max_cm: int = 5,
    moving_speed_threshold: float | None = None,
    resting_speed_threshold: float = 0.5,
    pf_ranks: tuple[int, ...] = (1, 2),
    categories: tuple[str, ...] = ("CSplus", "CSminus"),
    clear_output: bool = True,
    save_summary_csv: bool = True,
    show_plots: bool = False,
    show_rest_patches: bool = True,
    pf_reliability_dilation_bins: int | None = None,
    pf_reliability_dilation_shape: str | None = None,
    trace_slow_gap: float = 1.0,
    theta_slow_pad_factor: float = 0.05,
    sharey: bool = True,
    max_plot_trial_duration_s: float | None = None,
    include_long_cb_as_plateau: bool | None = None,
    include_resting_plateaus: bool = True,
    cb_plateau_min_duration_ms: float | None = None,
    align_all_pf_components_to_session_compare: bool = True,
    session_compare_cache_version: str = "v2",
) -> dict[str, Any]:
    import pandas as pd
    from scipy.ndimage import binary_dilation

    if distance_params is None:
        distance_params = PFDistanceCenteredParams()
    time_window_sec = float(time_window_sec)
    if (not np.isfinite(time_window_sec)) or time_window_sec <= 0:
        raise ValueError("time_window_sec must be a finite number > 0.")
    if include_long_cb_as_plateau is None:
        include_long_cb_as_plateau = bool(getattr(distance_params, "include_long_cb_as_plateau", True))
    if cb_plateau_min_duration_ms is None:
        cb_plateau_min_duration_ms = float(getattr(distance_params, "cb_plateau_min_duration_ms", 100.0))
    if moving_speed_threshold is None:
        moving_speed_threshold = float(config.analysis.speed_threshold)
    if distance_mode is None:
        distance_mode = str(getattr(distance_params, "distance_mode", "cumulative_path"))
    distance_mode = _normalize_distance_mode(distance_mode)
    distance_window_cm_req, distance_window_cm_eff, _ = _build_symmetric_distance_axis(
        distance_window_cm,
        distance_bin_cm,
    )
    if detection_window_cm is None:
        detection_window_cm = float(getattr(distance_params, "detection_window_cm", 10.0))
    detection_window_cm_req = float(detection_window_cm)
    if (not np.isfinite(detection_window_cm_req)) or detection_window_cm_req <= 0:
        raise ValueError("detection_window_cm must be a finite number > 0.")
    detection_window_cm_eff = min(float(detection_window_cm_req), float(distance_window_cm_eff))
    if int(center_vicinity_min_cm) <= 0 or int(center_vicinity_max_cm) < int(center_vicinity_min_cm):
        raise ValueError("Invalid center vicinity range.")
    if (not np.isfinite(float(cb_plateau_min_duration_ms))) or float(cb_plateau_min_duration_ms) <= 0:
        raise ValueError("cb_plateau_min_duration_ms must be a finite number > 0.")

    if figure_save_folder is None:
        figure_root = config.figures_root / "CKII_pooled"
    else:
        figure_root = Path(figure_save_folder)
    figure_root.mkdir(parents=True, exist_ok=True)

    output_dirs: dict[str, Path] = {}
    for cat in categories:
        cat_norm = _normalize_pf_category_name(cat)
        if cat_norm == "CSplus":
            out_dir = figure_root / "PF_time_defined_trials_CSplus_PLCs"
        elif cat_norm == "CSminus":
            out_dir = figure_root / "PF_time_defined_trials_CSminus_PLCs"
        elif cat_norm == "nonPLC":
            out_dir = figure_root / "PF_time_defined_trials_nonPLC"
        else:
            out_dir = figure_root / f"PF_time_defined_trials_{cat_norm}"
        output_dirs[cat_norm] = out_dir
    summary_csv = figure_root / "PF_time_defined_trials_summary.csv"

    if clear_output:
        for out_dir in output_dirs.values():
            if out_dir.exists():
                shutil.rmtree(out_dir)
            out_dir.mkdir(parents=True, exist_ok=True)
    else:
        for out_dir in output_dirs.values():
            out_dir.mkdir(parents=True, exist_ok=True)

    if pf_reliability_dilation_bins is None:
        dilation_bins = int(config.place_cell.pf_reliability_dilation_bins)
    else:
        dilation_bins = int(pf_reliability_dilation_bins)
    if pf_reliability_dilation_shape is None:
        dilation_shape = str(config.place_cell.pf_reliability_dilation_shape).strip().lower()
    else:
        dilation_shape = str(pf_reliability_dilation_shape).strip().lower()
    if dilation_bins < 0:
        raise ValueError("pf_reliability_dilation_bins must be >= 0.")
    dilation_structure = (
        core._build_pf_dilation_structure(dilation_bins, dilation_shape)
        if dilation_bins > 0
        else None
    )

    trial_resting_speed_threshold = float(resting_speed_threshold)
    if max_plot_trial_duration_s is None:
        trial_max_plot_duration_s = max(2.0 * float(time_window_sec), 1.0)
    else:
        trial_max_plot_duration_s = float(max_plot_trial_duration_s)
    if not np.isfinite(trial_max_plot_duration_s) or trial_max_plot_duration_s <= 0:
        raise ValueError("max_plot_trial_duration_s must be > 0.")
    trial_theta_freqs = tuple(config.analysis.theta_freqs)
    trial_slow_freqs = float(config.analysis.slow_freqs)
    trial_session_indices = tuple(config.traversal.session_indices)
    trial_firing_rate_bin_ms = float(config.traversal.firing_rate_bin_ms)
    trial_firing_rate_smooth_ms = float(config.traversal.firing_rate_smooth_ms)
    trial_pf_center_window_sec = float(config.traversal.pf_center_window_sec)

    dataset: dict[str, Any] = {
        "metadata": {
            "axis_kind": "time",
            "dilation_bins": int(dilation_bins),
            "dilation_shape": str(dilation_shape),
            "pf_ranks": tuple(int(r) for r in pf_ranks),
            "categories": tuple(_normalize_pf_category_name(c) for c in categories),
            "time_window_sec": float(time_window_sec),
            "distance_window_cm": float(distance_window_cm_eff),
            "distance_window_cm_requested": float(distance_window_cm_req),
            "distance_window_cm_effective": float(distance_window_cm_eff),
            "detection_window_cm": float(detection_window_cm_eff),
            "detection_window_cm_requested": float(detection_window_cm_req),
            "detection_window_cm_effective": float(detection_window_cm_eff),
            "distance_bin_cm": float(distance_bin_cm),
            "distance_mode": str(distance_mode),
            "include_long_cb_as_plateau": bool(include_long_cb_as_plateau),
            "include_resting_plateaus": bool(include_resting_plateaus),
            "cb_plateau_min_duration_ms": float(cb_plateau_min_duration_ms),
            "center_vicinity_min_cm": int(center_vicinity_min_cm),
            "center_vicinity_max_cm": int(center_vicinity_max_cm),
            "moving_speed_threshold": float(moving_speed_threshold),
            "resting_speed_threshold": float(trial_resting_speed_threshold),
            "min_traversals": int(distance_params.min_traversals),
            "min_traversals_per_type": int(distance_params.min_traversals_per_type),
            "subtract_pre_traversal_baseline": bool(distance_params.subtract_pre_traversal_baseline),
            "exclude_trials_with_bad_frames": bool(distance_params.exclude_trials_with_bad_frames),
            "pf_component_selection": str(distance_params.pf_component_selection),
            "max_pf_distance_cm": distance_params.max_pf_distance_cm,
            "smooth_window_sec": float(getattr(distance_params, "smooth_window", 0.0)),
            "traversal_merge_gap_s": float(getattr(config.traversal, "traversal_merge_gap_s", 0.0)),
            "session_indices": tuple(config.traversal.session_indices),
            "align_all_pf_components_to_session_compare": bool(align_all_pf_components_to_session_compare),
            "session_compare_cache_version": str(session_compare_cache_version),
        }
    }

    runtime_cache: dict[str, dict[str, Any]] = {}
    summary_rows: list[dict[str, Any]] = []
    category_counters: dict[str, dict[str, int]] = {}
    category_pf_sources: dict[str, str] = {
        _normalize_pf_category_name(cat): ("ss" if _normalize_pf_category_name(cat) == "nonPLC" else "all")
        for cat in categories
    }
    dataset["metadata"]["pf_source_by_category"] = dict(category_pf_sources)

    def _append_summary_row(
        *,
        category_name: str,
        animal_id: str,
        cell_idx: int,
        pf_rank: int | float,
        status: str,
        message: str,
        n_traversals: int | float = np.nan,
    ) -> None:
        summary_rows.append(
            {
                "category": category_name,
                "animal_id": str(animal_id),
                "cell_idx": int(cell_idx),
                "cell_num": int(cell_idx + 1) if int(cell_idx) >= 0 else np.nan,
                "pf_rank": pf_rank,
                "status": str(status),
                "n_traversals": n_traversals,
                "message": str(message),
            }
        )

    def _append_skip_rows_for_all_ranks(
        *,
        category_name: str,
        animal_id: str,
        cell_idx: int,
        status: str,
        message: str,
    ) -> None:
        for rank in pf_ranks:
            _append_summary_row(
                category_name=category_name,
                animal_id=animal_id,
                cell_idx=cell_idx,
                pf_rank=int(rank),
                status=status,
                message=message,
            )

    for category in categories:
        cat = _normalize_pf_category_name(category)
        out_dir = output_dirs[cat]
        category_cells = _get_spatial_category_cells(spatial_data, cat)
        category_counters[cat] = {
            "attempted_cells": 0,
            "attempted_components": 0,
            "saved": 0,
            "skipped_or_error": 0,
        }
        category_payload: dict[int, dict[str, Any]] = {}
        for pf_rank in pf_ranks:
            category_payload[int(pf_rank)] = {
                "time_rel": None,
                "entries": [],
                "n_requested_cells": len(category_cells),
                "n_entries": 0,
                "n_skipped": 0,
            }

        for cell_meta in category_cells:
            animal_id = str(cell_meta.get("session", ""))
            cell_idx = int(cell_meta.get("cell_idx", -1))
            category_counters[cat]["attempted_cells"] += 1
            if not animal_id or cell_idx < 0:
                category_counters[cat]["skipped_or_error"] += 1
                for pf_rank in pf_ranks:
                    category_payload[int(pf_rank)]["n_skipped"] = int(category_payload[int(pf_rank)]["n_skipped"]) + 1
                _append_skip_rows_for_all_ranks(
                    category_name=cat,
                    animal_id=animal_id,
                    cell_idx=cell_idx,
                    status="skip_invalid_cell_meta",
                    message="Missing/invalid animal_id or cell_idx in spatial_data cell metadata.",
                )
                continue
            try:
                if animal_id not in runtime_cache:
                    runtime_cache[animal_id] = _build_trial_plot_runtime_payload(animal_id, config)
                runtime = runtime_cache[animal_id]
                merged = runtime["merged"]
                spatial_by_idx = runtime["spatial_by_idx"]
                analysis = spatial_by_idx.get(cell_idx)
                if analysis is None:
                    category_counters[cat]["skipped_or_error"] += 1
                    for pf_rank in pf_ranks:
                        category_payload[int(pf_rank)]["n_skipped"] = int(category_payload[int(pf_rank)]["n_skipped"]) + 1
                    _append_skip_rows_for_all_ranks(
                        category_name=cat,
                        animal_id=animal_id,
                        cell_idx=cell_idx,
                        status="skip_missing_runtime_spatial_analysis",
                        message="Cell missing in runtime spatial analysis.",
                    )
                    continue

                pf_source_mode = str(category_pf_sources.get(cat, "all")).strip().lower()
                if pf_source_mode == "ss":
                    if bool(analysis.get("is_place_cell", False)):
                        category_counters[cat]["skipped_or_error"] += 1
                        for pf_rank in pf_ranks:
                            category_payload[int(pf_rank)]["n_skipped"] = int(category_payload[int(pf_rank)]["n_skipped"]) + 1
                        _append_skip_rows_for_all_ranks(
                            category_name=cat,
                            animal_id=animal_id,
                            cell_idx=cell_idx,
                            status="skip_nonplc_is_place_cell",
                            message="nonPLC category requires is_place_cell=False, but this cell is an all-spike place cell.",
                        )
                        continue
                    if not bool(analysis.get("is_place_cell_ss", False)):
                        category_counters[cat]["skipped_or_error"] += 1
                        for pf_rank in pf_ranks:
                            category_payload[int(pf_rank)]["n_skipped"] = int(category_payload[int(pf_rank)]["n_skipped"]) + 1
                        _append_skip_rows_for_all_ranks(
                            category_name=cat,
                            animal_id=animal_id,
                            cell_idx=cell_idx,
                            status="skip_nonplc_not_ss_place_cell",
                            message="nonPLC category requires is_place_cell_ss=True (non all-spike PLC + SS PLC).",
                        )
                        continue
                elif not bool(analysis.get("is_place_cell", False)):
                    category_counters[cat]["skipped_or_error"] += 1
                    for pf_rank in pf_ranks:
                        category_payload[int(pf_rank)]["n_skipped"] = int(category_payload[int(pf_rank)]["n_skipped"]) + 1
                    _append_skip_rows_for_all_ranks(
                        category_name=cat,
                        animal_id=animal_id,
                        cell_idx=cell_idx,
                        status="skip_not_place_cell_runtime",
                        message="Cell missing in runtime spatial analysis or is_place_cell=False.",
                    )
                    continue

                pf_source_info = _resolve_distance_defined_pf_component_source(
                    animal_id=animal_id,
                    cell_idx=int(cell_idx),
                    analysis=analysis,
                    config=config,
                    pf_source_mode=pf_source_mode,
                    align_all_pf_components_to_session_compare=bool(align_all_pf_components_to_session_compare),
                    session_compare_cache_version=str(session_compare_cache_version),
                )
                components_raw = list(pf_source_info.get("components_raw", []) or [])
                fallback_mask = np.asarray(pf_source_info.get("fallback_mask", []), dtype=bool)
                fallback_peak = pf_source_info.get("fallback_peak_rate", np.nan)
                source_rate_map = np.asarray(pf_source_info.get("source_rate_map", []), dtype=float)
                components = _sanitize_ranked_pf_components(
                    components_raw,
                    fallback_mask,
                    rate_map=(source_rate_map if source_rate_map.size > 0 else None),
                    fallback_peak_rate=float(fallback_peak),
                    max_components=None,
                )
                if not components:
                    category_counters[cat]["skipped_or_error"] += 1
                    for pf_rank in pf_ranks:
                        category_payload[int(pf_rank)]["n_skipped"] = int(category_payload[int(pf_rank)]["n_skipped"]) + 1
                    _append_skip_rows_for_all_ranks(
                        category_name=cat,
                        animal_id=animal_id,
                        cell_idx=cell_idx,
                        status="skip_no_place_field_components",
                        message=str(pf_source_info.get("missing_pf_message", "No place-field components.")),
                    )
                    continue

                trajectory_contours: list[dict[str, Any]] = []
                for rank_i, comp_i in enumerate(components, start=1):
                    comp_mask_i = np.asarray(comp_i.get("mask", []), dtype=bool)
                    if comp_mask_i.size == 0 or not np.any(comp_mask_i):
                        continue
                    comp_eval_i = comp_mask_i
                    if dilation_structure is not None:
                        comp_eval_i = binary_dilation(comp_mask_i, structure=dilation_structure)
                    if rank_i <= 2:
                        trajectory_contours.append(
                            {
                                "mask": np.asarray(comp_eval_i, dtype=bool),
                                "color": "magenta" if rank_i == 1 else "cyan",
                                "linewidth": 0.8,
                                "linestyle": "solid",
                                "alpha": 1.0,
                            }
                        )

                traces = runtime["traces"]
                x_neural = np.asarray(merged["x_neural"], dtype=float)
                y_neural = np.asarray(merged["y_neural"], dtype=float)
                speed = np.asarray(merged["speed"], dtype=float)
                spikes = merged["spikes"]
                all_spikes = merged.get("all_spikes", merged["spikes"])
                refined_ss = merged.get("refined_SS", [np.array([], dtype=int) for _ in spikes])
                all_cs_spikes = merged.get("all_CS_spikes", [np.array([], dtype=int) for _ in spikes])
                complex_bursts_dicts = merged.get("complex_bursts_dicts", [])
                plateaus_dicts = merged.get("plateaus_dicts", None)
                session_start_frames = merged.get("session_start_frames", [0])
                frame_rate = float(merged["frame_rate"])

                bad_timepoints = (
                    runtime["bad_masks"][cell_idx]
                    if isinstance(runtime["bad_masks"], np.ndarray) and cell_idx < len(runtime["bad_masks"])
                    else None
                )
                bad_mask = None
                if bad_timepoints is not None:
                    bad_mask = np.asarray(bad_timepoints, dtype=bool)
                    if bad_mask.shape[0] != x_neural.shape[0]:
                        raise ValueError(f"bad_timepoints length mismatch for {animal_id} cell {cell_idx}.")
                raw_bad_mask = None
                traces_raw_source = merged.get("traces", None)
                if traces_raw_source is not None and cell_idx < len(traces_raw_source):
                    raw_trace = np.asarray(traces_raw_source[cell_idx], dtype=float)
                    if raw_trace.ndim == 1 and raw_trace.shape[0] == x_neural.shape[0]:
                        raw_bad_mask = ~np.isfinite(raw_trace)
                traversal_bad_mask = None
                if bad_mask is not None and raw_bad_mask is not None:
                    traversal_bad_mask = bad_mask | raw_bad_mask
                elif bad_mask is not None:
                    traversal_bad_mask = bad_mask
                elif raw_bad_mask is not None:
                    traversal_bad_mask = raw_bad_mask

                x_neural_plot = x_neural.copy()
                y_neural_plot = y_neural.copy()
                speed_plot = speed.copy()
                if traversal_bad_mask is not None:
                    x_neural_plot[traversal_bad_mask] = np.nan
                    y_neural_plot[traversal_bad_mask] = np.nan
                    speed_plot[traversal_bad_mask] = np.nan

                def _filter_spike_indices(spike_source: Any) -> np.ndarray:
                    if isinstance(spike_source, (list, tuple, np.ndarray)):
                        src = spike_source[cell_idx] if isinstance(spike_source, (list, tuple)) else spike_source
                    else:
                        src = np.array([], dtype=int)
                    idx = np.asarray(src, dtype=int)
                    idx = idx[(idx >= 0) & (idx < x_neural.shape[0])]
                    if traversal_bad_mask is not None and idx.size > 0:
                        idx = idx[~traversal_bad_mask[idx]]
                    return idx

                all_spikes_cell = _filter_spike_indices(all_spikes)
                refined_ss_cell = _filter_spike_indices(refined_ss)
                all_cs_spikes_cell = _filter_spike_indices(all_cs_spikes)
                trace = np.asarray(traces[cell_idx], dtype=float)
                trace = core.interpolate_nan_segment(trace)
                theta_vm = core.bandpass_filter(trace, trial_theta_freqs[0], trial_theta_freqs[1], frame_rate, order=5)
                slow_vm = core.lowpass_filter(trace, trial_slow_freqs, frame_rate, order=5)

                for pf_rank in pf_ranks:
                    rank_int = int(pf_rank)
                    category_counters[cat]["attempted_components"] += 1
                    result = compute_time_defined_component_result_iterative(
                        animal_id=animal_id,
                        cell_idx=cell_idx,
                        pf_rank=rank_int,
                        runtime=runtime,
                        config=config,
                        distance_params=distance_params,
                        dilation_bins=dilation_bins,
                        dilation_shape=dilation_shape,
                        time_window_sec=float(time_window_sec),
                        distance_window_cm=float(distance_window_cm_eff),
                        detection_window_cm=float(detection_window_cm_eff),
                        distance_bin_cm=float(distance_bin_cm),
                        center_vicinity_min_cm=int(center_vicinity_min_cm),
                        center_vicinity_max_cm=int(center_vicinity_max_cm),
                        moving_speed_threshold=float(moving_speed_threshold),
                        resting_speed_threshold=float(trial_resting_speed_threshold),
                        exclude_trials_with_bad_frames=bool(distance_params.exclude_trials_with_bad_frames),
                        pf_source_mode=str(pf_source_mode),
                        include_long_cb_as_plateau=bool(include_long_cb_as_plateau),
                        include_resting_plateaus=bool(include_resting_plateaus),
                        cb_plateau_min_duration_ms=float(cb_plateau_min_duration_ms),
                        distance_mode=str(distance_mode),
                        align_all_pf_components_to_session_compare=bool(align_all_pf_components_to_session_compare),
                        session_compare_cache_version=str(session_compare_cache_version),
                        min_traversals=1,
                        bad_frame_mask=traversal_bad_mask,
                    )
                    if result is None:
                        category_payload[rank_int]["n_skipped"] = int(category_payload[rank_int]["n_skipped"]) + 1
                        category_counters[cat]["skipped_or_error"] += 1
                        _append_summary_row(
                            category_name=cat,
                            animal_id=animal_id,
                            cell_idx=cell_idx,
                            pf_rank=rank_int,
                            status="skip_no_time_defined_result",
                            message="Time-defined conversion returned no valid trials.",
                        )
                        continue

                    time_rel = np.asarray(result.get("time_rel", []), dtype=float)
                    if time_rel.size == 0:
                        category_payload[rank_int]["n_skipped"] = int(category_payload[rank_int]["n_skipped"]) + 1
                        category_counters[cat]["skipped_or_error"] += 1
                        _append_summary_row(
                            category_name=cat,
                            animal_id=animal_id,
                            cell_idx=cell_idx,
                            pf_rank=rank_int,
                            status="skip_empty_time_axis",
                            message="time_rel is empty in computed component result.",
                        )
                        continue
                    time_rel_ref = category_payload[rank_int]["time_rel"]
                    if time_rel_ref is None:
                        category_payload[rank_int]["time_rel"] = time_rel
                        dataset["metadata"]["time_bin_sec"] = float(np.nanmedian(np.diff(time_rel))) if time_rel.size > 1 else float(1.0 / frame_rate)
                    else:
                        time_rel_ref_arr = np.asarray(time_rel_ref, dtype=float)
                        if time_rel_ref_arr.size != time_rel.size:
                            category_payload[rank_int]["n_skipped"] = int(category_payload[rank_int]["n_skipped"]) + 1
                            category_counters[cat]["skipped_or_error"] += 1
                            _append_summary_row(
                                category_name=cat,
                                animal_id=animal_id,
                                cell_idx=cell_idx,
                                pf_rank=rank_int,
                                status="skip_time_axis_mismatch",
                                message=(
                                    "time_rel length mismatch for this PF rank block "
                                    f"(existing={time_rel_ref_arr.size}, current={time_rel.size})."
                                ),
                            )
                            continue

                    trial_data = result.get("all", {}).get("trial_data", {})
                    epoch_start_frames = np.asarray(trial_data.get("epoch_start_frames", []), dtype=int)
                    epoch_end_frames = np.asarray(trial_data.get("epoch_end_frames", []), dtype=int)
                    traversal_types = list(np.asarray(trial_data.get("traversal_types", []), dtype=object))
                    n_trials = int(epoch_start_frames.size)
                    traversal_epochs = list(zip(epoch_start_frames.tolist(), epoch_end_frames.tolist()))
                    place_field_mask = result.get("place_field_mask", None)
                    pf_bins = result.get("pf_bins", None)
                    pf_peak_xy = result.get("pf_peak_xy", None)
                    if place_field_mask is None or pf_bins is None:
                        category_payload[rank_int]["n_skipped"] = int(category_payload[rank_int]["n_skipped"]) + 1
                        category_counters[cat]["skipped_or_error"] += 1
                        _append_summary_row(
                            category_name=cat,
                            animal_id=animal_id,
                            cell_idx=cell_idx,
                            pf_rank=rank_int,
                            status="skip_missing_pf_geometry",
                            message="Missing place_field_mask and/or pf_bins for plotting.",
                            n_traversals=int(n_trials),
                        )
                        continue

                    plateau_starts_plot, plateau_ends_plot = _build_plateau_intervals_for_cell(
                        cell_idx=int(cell_idx),
                        plateaus_dicts=plateaus_dicts,
                        complex_bursts_dicts=complex_bursts_dicts,
                        include_long_cb_as_plateau=bool(include_long_cb_as_plateau),
                        cb_plateau_min_duration_ms=float(cb_plateau_min_duration_ms),
                        frame_rate=float(frame_rate),
                        n_frames=int(x_neural.shape[0]),
                    )
                    plateaus_for_plot = {"starts": plateau_starts_plot, "ends": plateau_ends_plot}

                    plot_result = core.plot_place_field_traversal_trials_with_cb_example_centered_by_max_rate(
                        trace,
                        theta_vm,
                        slow_vm,
                        speed_plot,
                        x_neural_plot,
                        y_neural_plot,
                        traversal_epochs,
                        place_field_mask,
                        pf_bins,
                        frame_rate,
                        complex_bursts_dicts=complex_bursts_dicts,
                        cell_idx=cell_idx,
                        traversal_types=traversal_types,
                        padding_sec=0.0,
                        zscore_traces=False,
                        theta_freqs=trial_theta_freqs,
                        slow_freqs=trial_slow_freqs,
                        session_start_frames=session_start_frames,
                        session_indices=trial_session_indices,
                        color_by_session=True,
                        resting_speed_threshold=trial_resting_speed_threshold,
                        show_rest_patches=bool(show_rest_patches),
                        show_pf_prepost_patches=True,
                        pf_prepost_patch_alpha=0.1,
                        pf_prepost_patch_scope="full_window",
                        pf_prepost_running_only=False,
                        pf_prepost_patch_defs=[
                            {
                                "mask": np.asarray(place_field_mask, dtype=bool),
                                "color": ("magenta" if rank_int == 1 else "cyan"),
                            }
                        ],
                        rest_patch_scope="full_window",
                        rest_patch_require_in_pf=False,
                        min_rest_patch_duration_s=1.0,
                        rest_patch_color="#B3B3B3",
                        rest_patch_alpha=0.25,
                        shade_traversal_epoch=False,
                        gradient_traversal_trajectory=True,
                        trajectory_rasterized=True,
                        trajectory_direction_label_top=True,
                        trajectory_direction_label_fontsize=5,
                        max_plot_trial_duration_s=trial_max_plot_duration_s,
                        drop_epochs_with_bad_timepoints=bool(distance_params.exclude_trials_with_bad_frames),
                        refined_SS=refined_ss_cell,
                        all_CS_spikes=all_cs_spikes_cell,
                        all_spikes=all_spikes_cell,
                        firing_rate_bin_ms=trial_firing_rate_bin_ms,
                        firing_rate_smooth_ms=trial_firing_rate_smooth_ms,
                        show_firing_rate=False,
                        simple_spike_color="#026C80",
                        complex_spike_color="#EE9B00",
                        pf_peak_xy=pf_peak_xy,
                        pf_center_window_sec=trial_pf_center_window_sec,
                        plot_pf_centered_average=True,
                        return_pf_centered=True,
                        return_spike_rate_means=True,
                        show=show_plots,
                        bad_timepoints=traversal_bad_mask,
                        return_trial_firing_rates=True,
                        center_by_pf_position=True,
                        max_pf_distance_cm=distance_params.max_pf_distance_cm,
                        plateaus_dicts=plateaus_for_plot,
                        slow_trace_gap=float(trace_slow_gap),
                        theta_slow_pad_factor=float(theta_slow_pad_factor),
                        trace_ymax_from_simple_spikes=(str(cat) == "CSminus"),
                        sharey=bool(sharey),
                        place_field_contours=trajectory_contours,
                        center_position_label=f"Closest to PF{pf_rank}",
                        pf_peak_label=f"PF{pf_rank} peak",
                        pf_peak_color=("magenta" if rank_int == 1 else "cyan"),
                    )
                    fig = plot_result[0] if isinstance(plot_result, tuple) and len(plot_result) > 0 else plot_result
                    axes = plot_result[1] if isinstance(plot_result, tuple) and len(plot_result) > 1 else None
                    valid_epochs_plot = (
                        list(plot_result[2])
                        if isinstance(plot_result, tuple) and len(plot_result) > 2 and plot_result[2] is not None
                        else list(traversal_epochs)
                    )
                    n_trials_plot = int(len(valid_epochs_plot))
                    if fig is None:
                        category_payload[rank_int]["n_skipped"] = int(category_payload[rank_int]["n_skipped"]) + 1
                        category_counters[cat]["skipped_or_error"] += 1
                        _append_summary_row(
                            category_name=cat,
                            animal_id=animal_id,
                            cell_idx=cell_idx,
                            pf_rank=rank_int,
                            status="skip_plot_figure_none",
                            message="Traversal plot function returned fig=None.",
                            n_traversals=int(n_trials),
                        )
                        continue
                    if n_trials_plot != n_trials:
                        if not show_plots:
                            plt.close(fig)
                        category_payload[rank_int]["n_skipped"] = int(category_payload[rank_int]["n_skipped"]) + 1
                        category_counters[cat]["skipped_or_error"] += 1
                        _append_summary_row(
                            category_name=cat,
                            animal_id=animal_id,
                            cell_idx=cell_idx,
                            pf_rank=rank_int,
                            status="skip_plot_epoch_mismatch",
                            message=(
                                f"Dataset trials ({n_trials}) != plotted valid epochs ({n_trials_plot}); "
                                "skipped to keep dataset/plot consistency."
                            ),
                            n_traversals=int(n_trials_plot),
                        )
                        continue

                    _remove_trial_plot_trajectory_start_end_indicators(axes)
                    out_name = f"{animal_id}_Cell{cell_idx + 1}_PF{rank_int}_time_defined_traversal.svg"
                    out_path = out_dir / out_name
                    fig.savefig(out_path, dpi=300)
                    if not show_plots:
                        plt.close(fig)
                    category_payload[rank_int]["entries"].append(
                        {
                            "session": animal_id,
                            "cell_idx": int(cell_idx),
                            "pf_rank": rank_int,
                            "pf_source": str(result.get("pf_source", pf_source_mode)),
                            "data": result,
                        }
                    )
                    _append_summary_row(
                        category_name=cat,
                        animal_id=animal_id,
                        cell_idx=cell_idx,
                        pf_rank=rank_int,
                        status="saved",
                        message=str(out_path),
                        n_traversals=int(n_trials_plot),
                    )
                    category_counters[cat]["saved"] += 1
            except Exception as exc:
                _append_summary_row(
                    category_name=cat,
                    animal_id=animal_id,
                    cell_idx=cell_idx,
                    pf_rank=np.nan,
                    status="error",
                    message=str(exc),
                )
                category_counters[cat]["skipped_or_error"] += 1
                for pf_rank in pf_ranks:
                    category_payload[int(pf_rank)]["n_skipped"] = int(category_payload[int(pf_rank)]["n_skipped"]) + 1

        for pf_rank in pf_ranks:
            block = category_payload[int(pf_rank)]
            block["n_entries"] = int(len(block["entries"]))
        dataset[cat] = category_payload

    summary_columns = [
        "category",
        "animal_id",
        "cell_idx",
        "cell_num",
        "pf_rank",
        "status",
        "n_traversals",
        "message",
    ]
    summary_df = pd.DataFrame(summary_rows, columns=summary_columns)
    if save_summary_csv:
        summary_df.to_csv(summary_csv, index=False)

    plot_summary = {
        "output_dirs": {k: str(v) for k, v in output_dirs.items()},
        "summary_csv": str(summary_csv) if save_summary_csv else None,
        "summary_df": summary_df,
        "counters": category_counters,
        "time_window_sec": float(time_window_sec),
        "time_bin_sec": dataset.get("metadata", {}).get("time_bin_sec", np.nan),
        "distance_window_cm": float(distance_window_cm_eff),
        "distance_window_cm_requested": float(distance_window_cm_req),
        "distance_window_cm_effective": float(distance_window_cm_eff),
        "detection_window_cm": float(detection_window_cm_eff),
        "detection_window_cm_requested": float(detection_window_cm_req),
        "detection_window_cm_effective": float(detection_window_cm_eff),
        "distance_bin_cm": float(distance_bin_cm),
        "distance_mode": str(distance_mode),
        "include_long_cb_as_plateau": bool(include_long_cb_as_plateau),
        "include_resting_plateaus": bool(include_resting_plateaus),
        "cb_plateau_min_duration_ms": float(cb_plateau_min_duration_ms),
        "center_vicinity_min_cm": int(center_vicinity_min_cm),
        "center_vicinity_max_cm": int(center_vicinity_max_cm),
        "moving_speed_threshold": float(moving_speed_threshold),
        "resting_speed_threshold": float(trial_resting_speed_threshold),
        "dilation_bins": int(dilation_bins),
        "dilation_shape": str(dilation_shape),
        "trace_slow_gap": float(trace_slow_gap),
        "theta_slow_pad_factor": float(theta_slow_pad_factor),
        "max_plot_trial_duration_s": float(trial_max_plot_duration_s),
    }
    return {"plot_summary": plot_summary, "dataset": dataset}


def build_pf_centered_component_dataset(
    config: PipelineConfig,
    spatial_data: Any,
    *,
    pf_ranks: tuple[int, ...] = (1, 2),
    pf_reliability_dilation_bins: int | None = None,
    pf_reliability_dilation_shape: str | None = None,
    categories: tuple[str, ...] = ("CSplus", "CSminus"),
) -> dict[str, Any]:
    """
    Build PF-centered trial data for CS+/CS- PLCs for selected PF ranks (default PF1/PF2).
    """
    dilation_bins = int(
        config.place_cell.pf_reliability_dilation_bins
        if pf_reliability_dilation_bins is None
        else pf_reliability_dilation_bins
    )
    dilation_shape = str(
        config.place_cell.pf_reliability_dilation_shape
        if pf_reliability_dilation_shape is None
        else pf_reliability_dilation_shape
    ).strip().lower()
    if dilation_bins < 0:
        raise ValueError("pf_reliability_dilation_bins must be >= 0.")
    if dilation_shape not in {"disk", "square", "manhattan"}:
        raise ValueError("pf_reliability_dilation_shape must be one of: disk, square, manhattan.")

    runtime_cache: dict[str, dict[str, Any]] = {}
    dataset: dict[str, Any] = {
        "metadata": {
            "dilation_bins": dilation_bins,
            "dilation_shape": dilation_shape,
            "pf_ranks": tuple(int(r) for r in pf_ranks),
            "categories": tuple(_normalize_pf_category_name(c) for c in categories),
            "subtract_pre_traversal_baseline": bool(config.traversal.subtract_pre_traversal_baseline),
        }
    }

    for category in categories:
        cat = _normalize_pf_category_name(category)
        cells = _get_spatial_category_cells(spatial_data, cat)
        category_payload: dict[int, dict[str, Any]] = {}
        for pf_rank in pf_ranks:
            entries: list[dict[str, Any]] = []
            time_rel_ref: np.ndarray | None = None
            skipped = 0
            for cell_meta in cells:
                animal_id = str(cell_meta.get("session", ""))
                cell_idx = int(cell_meta.get("cell_idx", -1))
                if not animal_id or cell_idx < 0:
                    skipped += 1
                    continue
                if animal_id not in runtime_cache:
                    runtime_cache[animal_id] = _build_trial_plot_runtime_payload(animal_id, config)
                runtime = runtime_cache[animal_id]
                result = _compute_component_pf_centered_result(
                    animal_id=animal_id,
                    cell_idx=cell_idx,
                    pf_rank=int(pf_rank),
                    runtime=runtime,
                    config=config,
                    dilation_bins=dilation_bins,
                    dilation_shape=dilation_shape,
                )
                if result is None:
                    skipped += 1
                    continue
                time_rel = np.asarray(result.get("time_rel", []), dtype=float)
                if time_rel.size == 0:
                    skipped += 1
                    continue
                if time_rel_ref is None:
                    time_rel_ref = time_rel
                elif len(time_rel_ref) != len(time_rel):
                    skipped += 1
                    continue
                entries.append(
                    {
                        "session": animal_id,
                        "cell_idx": cell_idx,
                        "pf_rank": int(pf_rank),
                        "data": result,
                    }
                )
            category_payload[int(pf_rank)] = {
                "time_rel": time_rel_ref,
                "entries": entries,
                "n_requested_cells": len(cells),
                "n_entries": len(entries),
                "n_skipped": skipped,
            }
        dataset[cat] = category_payload
    return dataset


def build_pf_distance_centered_component_dataset(
    config: PipelineConfig,
    spatial_data: Any,
    *,
    distance_params: PFDistanceCenteredParams | None = None,
    pf_ranks: tuple[int, ...] = (1, 2),
    pf_reliability_dilation_bins: int | None = None,
    pf_reliability_dilation_shape: str | None = None,
    categories: tuple[str, ...] = ("CSplus", "CSminus"),
) -> dict[str, Any]:
    """
    Build PF-centered trial data on a signed path-distance axis for selected PF ranks.
    """
    if distance_params is None:
        distance_params = PFDistanceCenteredParams()
    dilation_bins = int(
        config.place_cell.pf_reliability_dilation_bins
        if pf_reliability_dilation_bins is None
        else pf_reliability_dilation_bins
    )
    dilation_shape = str(
        config.place_cell.pf_reliability_dilation_shape
        if pf_reliability_dilation_shape is None
        else pf_reliability_dilation_shape
    ).strip().lower()
    if dilation_bins < 0:
        raise ValueError("pf_reliability_dilation_bins must be >= 0.")
    if dilation_shape not in {"disk", "square", "manhattan"}:
        raise ValueError("pf_reliability_dilation_shape must be one of: disk, square, manhattan.")

    runtime_cache: dict[str, dict[str, Any]] = {}
    dataset: dict[str, Any] = {
        "metadata": {
            "dilation_bins": dilation_bins,
            "dilation_shape": dilation_shape,
            "pf_ranks": tuple(int(r) for r in pf_ranks),
            "categories": tuple(_normalize_pf_category_name(c) for c in categories),
            "distance_window_cm": float(distance_params.distance_window_cm),
            "distance_bin_cm": float(distance_params.distance_bin_cm),
            "require_full_span": bool(distance_params.require_full_span),
            "center_by_pf_position": bool(distance_params.center_by_pf_position),
            "require_movement": bool(distance_params.require_movement),
            "min_traversals": int(distance_params.min_traversals),
            "min_traversals_per_type": int(distance_params.min_traversals_per_type),
            "subtract_pre_traversal_baseline": bool(distance_params.subtract_pre_traversal_baseline),
            "pf_component_selection": str(distance_params.pf_component_selection),
            "max_pf_distance_cm": distance_params.max_pf_distance_cm,
            "smooth_window_cm": float(distance_params.smooth_window),
            "traversal_merge_gap_s": float(getattr(config.traversal, "traversal_merge_gap_s", 0.0)),
            "session_indices": tuple(config.traversal.session_indices),
        }
    }

    for category in categories:
        cat = _normalize_pf_category_name(category)
        cells = _get_spatial_category_cells(spatial_data, cat)
        category_payload: dict[int, dict[str, Any]] = {}
        for pf_rank in pf_ranks:
            entries: list[dict[str, Any]] = []
            distance_rel_ref: np.ndarray | None = None
            skipped = 0
            for cell_meta in cells:
                animal_id = str(cell_meta.get("session", ""))
                cell_idx = int(cell_meta.get("cell_idx", -1))
                if not animal_id or cell_idx < 0:
                    skipped += 1
                    continue
                if animal_id not in runtime_cache:
                    runtime_cache[animal_id] = _build_trial_plot_runtime_payload(animal_id, config)
                runtime = runtime_cache[animal_id]
                result = compute_distance_centered_component_result(
                    animal_id=animal_id,
                    cell_idx=cell_idx,
                    pf_rank=int(pf_rank),
                    runtime=runtime,
                    config=config,
                    distance_params=distance_params,
                    dilation_bins=dilation_bins,
                    dilation_shape=dilation_shape,
                )
                if result is None:
                    skipped += 1
                    continue
                distance_rel = np.asarray(result.get("distance_rel", []), dtype=float)
                if distance_rel.size == 0:
                    skipped += 1
                    continue
                if distance_rel_ref is None:
                    distance_rel_ref = distance_rel
                elif len(distance_rel_ref) != len(distance_rel):
                    skipped += 1
                    continue
                entries.append(
                    {
                        "session": animal_id,
                        "cell_idx": cell_idx,
                        "pf_rank": int(pf_rank),
                        "data": result,
                    }
                )
            category_payload[int(pf_rank)] = {
                "distance_rel": distance_rel_ref,
                "entries": entries,
                "n_requested_cells": len(cells),
                "n_entries": len(entries),
                "n_skipped": skipped,
            }
        dataset[cat] = category_payload
    return dataset


def _compute_single_heatmap_max_trials(
    entry_data: dict[str, Any],
    time_rel: np.ndarray,
    *,
    direction_keys: tuple[str, str, str] = ("all", "cw", "ccw"),
) -> int:
    cell_data = entry_data["data"]
    directions = [cell_data.get(str(k), {}) for k in direction_keys]
    stack_keys = ["rate_stack", "ss_rate_stack", "cs_rate_stack", "theta_stack", "slow_stack"]
    col_trials: list[int] = []
    for dir_data in directions:
        max_trials = 1
        for key in stack_keys:
            stack = dir_data.get(key)
            if stack is None:
                continue
            stack = np.asarray(stack, dtype=float)
            if stack.ndim == 2 and stack.shape[1] == len(time_rel):
                max_trials = max(max_trials, int(stack.shape[0]))
        col_trials.append(max_trials)
    return max(col_trials) if col_trials else 1


def _estimate_single_heatmap_figure_height(
    entry_data: dict[str, Any],
    time_rel: np.ndarray,
    *,
    trial_height: float,
    avg_height: float,
    merge_ss_cs: bool,
    fixed_heatmap_height: float | None = None,
    direction_keys: tuple[str, str, str] = ("all", "cw", "ccw"),
) -> float:
    n_rows = 4 if bool(merge_ss_cs) else 5
    if fixed_heatmap_height is not None and np.isfinite(float(fixed_heatmap_height)) and float(fixed_heatmap_height) > 0:
        heatmap_h = float(fixed_heatmap_height)
    else:
        max_trials_all = _compute_single_heatmap_max_trials(
            entry_data,
            time_rel,
            direction_keys=direction_keys,
        )
        heatmap_h = max_trials_all * float(trial_height)
    row_spacing = 0.05
    title_space = 0.3
    xlabel_space = 0.3
    return n_rows * (heatmap_h + float(avg_height)) + (n_rows - 1) * row_spacing + title_space + xlabel_space


def _compute_pf_centered_panel_layout_inches(
    *,
    n_rows: int,
    heatmap_height: float,
    avg_height: float,
    subplot_width: float,
    show_row_ylabel: bool,
    show_column_titles: bool,
    show_colorbar: bool,
    heatmap_wspace: float,
) -> dict[str, float]:
    left_margin = 0.38 if bool(show_row_ylabel) else 0.12
    right_margin = 0.05
    top_margin = 0.22 if bool(show_column_titles) else 0.08
    bottom_margin = 0.24
    heat_avg_gap = 0.06
    row_gap = 0.10
    col_gap = max(0.05, float(heatmap_wspace) * float(subplot_width))
    cbar_gap = 0.08 if bool(show_colorbar) else 0.0
    cbar_width = 0.032 if bool(show_colorbar) else 0.0
    panel_width = (
        left_margin
        + 3.0 * float(subplot_width)
        + 2.0 * col_gap
        + cbar_gap
        + cbar_width
        + right_margin
    )
    panel_height = (
        top_margin
        + float(n_rows) * (float(heatmap_height) + heat_avg_gap + float(avg_height))
        + float(max(0, int(n_rows) - 1)) * row_gap
        + bottom_margin
    )
    return {
        "panel_width": float(panel_width),
        "panel_height": float(panel_height),
        "left_margin": float(left_margin),
        "right_margin": float(right_margin),
        "top_margin": float(top_margin),
        "bottom_margin": float(bottom_margin),
        "heat_avg_gap": float(heat_avg_gap),
        "row_gap": float(row_gap),
        "col_gap": float(col_gap),
        "cbar_gap": float(cbar_gap),
        "cbar_width": float(cbar_width),
    }


def _compute_pf_centered_2session_panel_layout_inches(
    *,
    avg_key_counts: list[int] | tuple[int, ...],
    heatmap_height: float,
    avg_height: float,
    subplot_width: float,
    show_row_ylabel: bool,
    show_colorbar: bool,
    show_panel_title: bool,
) -> dict[str, float]:
    left_margin = 0.38 if bool(show_row_ylabel) else 0.12
    right_margin = 0.05
    top_margin = 0.18 if bool(show_panel_title) else 0.08
    bottom_margin = 0.24
    inner_gap = 0.05
    row_gap = 0.10
    cbar_gap = 0.08 if bool(show_colorbar) else 0.0
    cbar_width = 0.032 if bool(show_colorbar) else 0.0
    panel_width = left_margin + float(subplot_width) + cbar_gap + cbar_width + right_margin
    row_total_height = 0.0
    for count in avg_key_counts:
        n_avg = max(0, int(count))
        row_total_height += float(heatmap_height) + float(n_avg) * (float(avg_height) + inner_gap)
    panel_height = top_margin + row_total_height + float(max(0, len(avg_key_counts) - 1)) * row_gap + bottom_margin
    return {
        "panel_width": float(panel_width),
        "panel_height": float(panel_height),
        "left_margin": float(left_margin),
        "right_margin": float(right_margin),
        "top_margin": float(top_margin),
        "bottom_margin": float(bottom_margin),
        "inner_gap": float(inner_gap),
        "row_gap": float(row_gap),
        "cbar_gap": float(cbar_gap),
        "cbar_width": float(cbar_width),
    }


def _interpolate_nan_stack_rows(stack: np.ndarray) -> np.ndarray:
    stack = np.asarray(stack, dtype=float)
    if stack.ndim != 2:
        raise ValueError("stack must be a 2D array")
    out = np.array(stack, dtype=float, copy=True)
    for i in range(out.shape[0]):
        out[i] = core.interpolate_nan_segment(np.asarray(out[i], dtype=float))
    return out


def _format_avg_axis_ticklabel(value: float, _: int | None = None) -> str:
    value_f = float(np.round(float(value), 1))
    if np.isclose(value_f, 0.0):
        value_f = 0.0
    if np.isclose(value_f, np.round(value_f)):
        return str(int(np.round(value_f)))
    return f"{value_f:.1f}"


def _rank_pf_component_candidates(
    candidates: list[dict[str, Any]],
    *,
    max_components: int | None = 2,
) -> list[dict[str, Any]]:
    if len(candidates) == 0:
        return []

    clean: list[dict[str, Any]] = []
    for item in candidates:
        comp = dict(item)
        comp["area_bins"] = int(comp.get("area_bins", int(np.sum(np.asarray(comp.get("mask", []), dtype=bool)))))
        clean.append(comp)

    finite_peak_items = [item for item in clean if np.isfinite(item.get("peak_rate", np.nan))]
    if len(finite_peak_items) > 0:
        primary = min(
            finite_peak_items,
            key=lambda item: (
                -float(item.get("peak_rate", np.nan)),
                -int(item.get("area_bins", 0)),
                int(item.get("source_rank", 0)),
            ),
        )
        primary_id = id(primary)
        remaining = [item for item in clean if id(item) != primary_id]
        remaining.sort(
            key=lambda item: (
                -int(item.get("area_bins", 0)),
                -float(item.get("peak_rate", -np.inf)) if np.isfinite(item.get("peak_rate", np.nan)) else np.inf,
                int(item.get("source_rank", 0)),
            ),
        )
        ordered = [primary] + remaining
    else:
        ordered = sorted(
            clean,
            key=lambda item: (
                -int(item.get("area_bins", 0)),
                int(item.get("source_rank", 0)),
            ),
        )

    if max_components is None:
        return ordered
    return ordered[:max(0, int(max_components))]


def _sanitize_ranked_pf_components(
    components: list[Any] | tuple[Any, ...] | None,
    fallback_mask: np.ndarray | None,
    *,
    rate_map: np.ndarray | None = None,
    fallback_peak_rate: float = np.nan,
    max_components: int | None = 2,
) -> list[dict[str, Any]]:
    clean: list[dict[str, Any]] = []
    fallback_shape = None
    if fallback_mask is not None:
        fallback_mask = np.asarray(fallback_mask, dtype=bool)
        if fallback_mask.ndim == 2:
            fallback_shape = fallback_mask.shape

    if isinstance(components, (list, tuple)):
        for rank_idx, comp in enumerate(components):
            arr = None
            peak_rate = np.nan
            if isinstance(comp, dict):
                arr_raw = comp.get("mask", None)
                if arr_raw is not None:
                    arr = np.asarray(arr_raw, dtype=bool)
                peak_rate = float(comp.get("peak_rate", np.nan))
            else:
                arr = np.asarray(comp, dtype=bool)
            if arr is None or arr.ndim != 2:
                continue
            if fallback_shape is not None and arr.shape != fallback_shape:
                continue
            if not np.any(arr):
                continue
            if (not np.isfinite(peak_rate)) and isinstance(rate_map, np.ndarray) and rate_map.shape == arr.shape:
                vals = np.asarray(rate_map, dtype=float)[arr]
                if vals.size > 0 and np.any(np.isfinite(vals)):
                    peak_rate = float(np.nanmax(vals))
            clean.append(
                {
                    "mask": np.asarray(arr, dtype=bool),
                    "peak_rate": peak_rate,
                    "source_rank": int(rank_idx),
                    "area_bins": int(np.sum(arr)),
                }
            )

    if len(clean) > 0:
        return _rank_pf_component_candidates(clean, max_components=max_components)

    if isinstance(fallback_mask, np.ndarray) and fallback_mask.ndim == 2 and np.any(fallback_mask):
        mask = np.asarray(fallback_mask, dtype=bool)
        if scipy_ndimage is not None:
            structure = np.ones((3, 3), dtype=int)
            labeled, n_comp = scipy_ndimage.label(mask, structure=structure)
            if int(n_comp) > 0:
                vals = np.asarray(rate_map, dtype=float) if isinstance(rate_map, np.ndarray) and rate_map.shape == mask.shape else None
                fallback_components: list[dict[str, Any]] = []
                for i in range(1, int(n_comp) + 1):
                    comp_mask = np.asarray(labeled == i, dtype=bool)
                    if not np.any(comp_mask):
                        continue
                    peak_rate = np.nan
                    if vals is not None:
                        vv = vals[comp_mask]
                        if vv.size > 0 and np.any(np.isfinite(vv)):
                            peak_rate = float(np.nanmax(vv))
                    fallback_components.append(
                        {
                            "mask": comp_mask,
                            "peak_rate": peak_rate,
                            "source_rank": int(i - 1),
                            "area_bins": int(np.sum(comp_mask)),
                        }
                    )
                return _rank_pf_component_candidates(fallback_components, max_components=max_components)
        return _rank_pf_component_candidates(
            [{
                "mask": mask,
                "peak_rate": float(fallback_peak_rate),
                "source_rank": 0,
                "area_bins": int(np.sum(mask)),
            }],
            max_components=max_components,
        )

    return []


_SESSION_COMPARE_COMBINED_PF_CACHE: dict[tuple[str, str, str], dict[int, dict[str, Any]] | None] = {}


def _load_session_compare_combined_pf_cells(
    config: PipelineConfig,
    animal_id: str,
    cache_version: str = "v2",
) -> dict[int, dict[str, Any]] | None:
    cache_key = (str(config.data_root), str(animal_id), str(cache_version))
    if cache_key in _SESSION_COMPARE_COMBINED_PF_CACHE:
        return _SESSION_COMPARE_COMBINED_PF_CACHE[cache_key]

    cache_path = Path(config.data_root) / str(animal_id) / f"spatial_session_cache_{cache_version}.pkl"
    if not cache_path.exists():
        _SESSION_COMPARE_COMBINED_PF_CACHE[cache_key] = None
        return None

    try:
        with cache_path.open("rb") as fh:
            cache_obj = pickle.load(fh)
    except Exception:
        _SESSION_COMPARE_COMBINED_PF_CACHE[cache_key] = None
        return None

    if not isinstance(cache_obj, dict):
        _SESSION_COMPARE_COMBINED_PF_CACHE[cache_key] = None
        return None
    cells_obj = cache_obj.get("cells", {})
    if not isinstance(cells_obj, dict):
        _SESSION_COMPARE_COMBINED_PF_CACHE[cache_key] = None
        return None

    combined_cells: dict[int, dict[str, Any]] = {}
    for raw_key, by_cond in cells_obj.items():
        if not isinstance(by_cond, dict):
            continue
        combined = by_cond.get("combined", None)
        if not isinstance(combined, dict):
            continue
        try:
            key_int = int(raw_key)
        except Exception:
            try:
                key_int = int(combined.get("cell_idx", -1))
            except Exception:
                key_int = -1
        if key_int < 0:
            continue
        combined_cells[key_int] = combined

    _SESSION_COMPARE_COMBINED_PF_CACHE[cache_key] = combined_cells
    return combined_cells


def _resolve_distance_defined_pf_component_source(
    *,
    animal_id: str,
    cell_idx: int,
    analysis: dict[str, Any],
    config: PipelineConfig,
    pf_source_mode: str,
    align_all_pf_components_to_session_compare: bool,
    session_compare_cache_version: str,
) -> dict[str, Any]:
    source = str(pf_source_mode).strip().lower()
    if source not in {"all", "ss"}:
        raise ValueError(f"Unknown pf_source_mode='{pf_source_mode}'. Use 'all' or 'ss'.")

    if source == "all" and bool(align_all_pf_components_to_session_compare):
        combined_cells = _load_session_compare_combined_pf_cells(
            config,
            animal_id,
            cache_version=str(session_compare_cache_version),
        )
        combined_cell = None if combined_cells is None else combined_cells.get(int(cell_idx), None)
        if isinstance(combined_cell, dict) and bool(combined_cell.get("is_place_cell", False)):
            combined_components = list(combined_cell.get("place_field_components", []) or [])
            combined_mask = np.asarray(combined_cell.get("place_field_mask", []), dtype=bool)
            if len(combined_components) > 0 or (combined_mask.size > 0 and np.any(combined_mask)):
                return {
                    "source_mode": "all",
                    "source_name": "session_compare_combined",
                    "components_raw": combined_components,
                    "fallback_mask": combined_mask,
                    "fallback_peak_rate": combined_cell.get("peak_rate", np.nan),
                    "source_rate_map": np.asarray(combined_cell.get("rate_map", []), dtype=float),
                    "missing_pf_message": (
                        "No non-empty place_field_components and no non-empty fallback "
                        "place_field_mask in session-compare combined cache entry."
                    ),
                }

    if source == "ss":
        return {
            "source_mode": "ss",
            "source_name": "runtime_ss",
            "components_raw": list(analysis.get("ss_place_field_components", []) or []),
            "fallback_mask": np.asarray(analysis.get("ss_place_field_mask", []), dtype=bool),
            "fallback_peak_rate": analysis.get("ss_peak_rate", np.nan),
            "source_rate_map": np.asarray(analysis.get("ss_rate_map", []), dtype=float),
            "missing_pf_message": (
                "No non-empty ss_place_field_components and no non-empty fallback "
                "ss_place_field_mask."
            ),
        }

    return {
        "source_mode": "all",
        "source_name": "runtime_all",
        "components_raw": list(analysis.get("place_field_components", []) or []),
        "fallback_mask": np.asarray(analysis.get("place_field_mask", []), dtype=bool),
        "fallback_peak_rate": analysis.get("peak_rate", np.nan),
        "source_rate_map": np.asarray(analysis.get("rate_map", []), dtype=float),
        "missing_pf_message": (
            "No non-empty place_field_components and no non-empty fallback "
            "place_field_mask."
        ),
    }


def _compute_single_cell_fr_vmaxs(
    entry_data: dict[str, Any],
    time_rel: np.ndarray,
    *,
    smooth_window: int = 0,
    interpolate_nan: bool = True,
    direction_keys: tuple[str, str, str] = ("all", "cw", "ccw"),
) -> tuple[float, float, float]:
    cell_data = entry_data["data"]
    directions = [cell_data.get(str(k), {}) for k in direction_keys]
    stack_keys = ["rate_stack", "ss_rate_stack", "cs_rate_stack"]
    row_vmax = [0.0, 0.0, 0.0]
    n_time = len(time_rel)
    for dir_data in directions:
        for row, key in enumerate(stack_keys):
            stack = dir_data.get(key)
            if stack is None:
                continue
            stack = np.asarray(stack, dtype=float)
            if stack.ndim != 2 or stack.shape[1] != n_time:
                continue
            if bool(interpolate_nan):
                stack = _interpolate_nan_stack_rows(stack)
            if smooth_window > 1:
                smoothed = np.zeros_like(stack)
                for i in range(stack.shape[0]):
                    smoothed[i] = _smooth_boxcar(stack[i], int(smooth_window))
                stack = smoothed
            if stack.size > 0:
                row_vmax[row] = max(row_vmax[row], float(np.nanmax(stack)))
    return float(row_vmax[0]), float(row_vmax[1]), float(row_vmax[2])


def _compute_cell_colorbar_vmax_from_all_direction(
    entry_data: dict[str, Any],
    time_rel: np.ndarray,
    *,
    smooth_window: int = 0,
    std_multiplier: float = 3.0,
) -> dict[str, float]:
    """Estimate colorbar vmax values from per-trial maxima in the all-direction stack."""
    if (not np.isfinite(float(std_multiplier))) or float(std_multiplier) < 0:
        raise ValueError("std_multiplier must be a finite number >= 0.")

    cell_data = entry_data.get("data", {})
    all_data = cell_data.get("all", {})
    n_time = int(len(time_rel))

    def _stack(key: str) -> np.ndarray | None:
        arr = all_data.get(key)
        if arr is None:
            return None
        arr = np.asarray(arr, dtype=float)
        if arr.ndim != 2 or arr.shape[1] != n_time:
            return None
        if int(smooth_window) > 1:
            smoothed = np.full_like(arr, np.nan)
            for i in range(arr.shape[0]):
                smoothed[i] = _smooth_boxcar(arr[i], int(smooth_window))
            arr = smoothed
        return arr

    def _vmax_from_trial_max(stack: np.ndarray | None) -> float | None:
        if stack is None or stack.size == 0:
            return None
        trial_max = []
        for i in range(stack.shape[0]):
            row = np.asarray(stack[i], dtype=float)
            finite = row[np.isfinite(row)]
            if finite.size == 0:
                continue
            trial_max.append(float(np.max(finite)))
        if len(trial_max) == 0:
            return None
        trial_max_arr = np.asarray(trial_max, dtype=float)
        vmax = float(np.nanmean(trial_max_arr) + float(std_multiplier) * np.nanstd(trial_max_arr))
        if (not np.isfinite(vmax)) or vmax <= 0:
            vmax = float(np.nanmax(trial_max_arr))
        if (not np.isfinite(vmax)) or vmax <= 0:
            return None
        return vmax

    out: dict[str, float] = {}
    key_map = {
        "rate": "rate_stack",
        "ss": "ss_rate_stack",
        "cs": "cs_rate_stack",
        "theta": "theta_stack",
    }
    for out_key, stack_key in key_map.items():
        v = _vmax_from_trial_max(_stack(stack_key))
        if v is not None:
            out[out_key] = float(v)
    return out


def _plot_single_cell_heatmap_on_figure(
    fig: Any,
    entry_data: dict[str, Any],
    time_rel: np.ndarray,
    *,
    smooth_window: int = 0,
    fr_vmax_scale: float = 0.5,
    theta_vlim: tuple[float, float] = (0, 0.4),
    slow_vlim: tuple[float, float] = (-0.2, 0.2),
    trial_height: float = 0.06,
    xlim: tuple[float, float] = (-4, 4),
    merge_ss_cs: bool = False,
    merge_plateau: bool = True,
    smooth_plateau: bool = False,
    plateau_vlim: float = 0.1,
    avg_height: float = 0.3,
    avg_smooth_window: int = 0,
    x_label: str = "Time (s)",
    center_line_x: float = 0.0,
    show_session_gap_line: bool = False,
    session_gap_line_color: str = "black",
    session_gap_line_width: float = 0.35,
    fr_vmax_override: tuple[float, float, float] | None = None,
    colorbar_vmax_override: dict[str, float] | None = None,
    avg_ylim_override: dict[int, tuple[float, float]] | None = None,
    fixed_heatmap_height: float | None = None,
    fixed_subplot_width: float | None = None,
    panel_bbox: tuple[float, float, float, float] | None = None,
    show_row_ylabel: bool = True,
    show_colorbar: bool = True,
    show_avg_yticks_left_only: bool = True,
    show_column_titles: bool = True,
    column_title_include_trials: bool = False,
    x_label_col_idx: int | None = None,
    show_heatmap_yticks: bool = True,
    show_heatmap_yticks_all_columns: bool = False,
    ss_cs_cbar_tick_labelsize: int = 3,
    heatmap_wspace: float = 0.15,
    apply_tight_layout: bool = True,
    direction_keys: tuple[str, str, str] | list[str] = ("all", "cw", "ccw"),
    direction_titles: tuple[str, str, str] | list[str] | None = None,
) -> dict[int, tuple[float, float]]:
    from matplotlib.cm import ScalarMappable
    from matplotlib.colors import LinearSegmentedColormap, Normalize
    from matplotlib.gridspec import GridSpec, GridSpecFromSubplotSpec

    dir_keys, dir_titles = _normalize_direction_triplet(
        direction_keys=direction_keys,
        direction_titles=direction_titles,
    )
    cell_data = entry_data["data"]

    def _get_stack(data: dict[str, Any], key: str) -> np.ndarray | None:
        stack = data.get(key)
        if stack is None:
            return None
        stack = np.asarray(stack, dtype=float)
        if stack.ndim != 2 or stack.shape[1] != len(time_rel):
            return None
        if smooth_window > 1:
            smoothed = np.zeros_like(stack)
            for i in range(stack.shape[0]):
                smoothed[i] = _smooth_boxcar(stack[i], int(smooth_window))
            return smoothed
        return stack

    def _smooth_avg(trace: np.ndarray) -> np.ndarray:
        if avg_smooth_window > 1:
            return _smooth_boxcar(trace, int(avg_smooth_window))
        return trace

    def _session_gap_y(data: dict[str, Any], actual_trials: int) -> float | None:
        if not bool(show_session_gap_line):
            return None
        trial_data = data.get("trial_data", {})
        if not isinstance(trial_data, dict):
            return None
        session_idx = np.asarray(trial_data.get("session_idx", []))
        if session_idx.ndim != 1 or session_idx.size != int(actual_trials) or session_idx.size < 2:
            return None
        changes = np.where(np.diff(session_idx.astype(int)) != 0)[0]
        if changes.size == 0:
            return None
        boundary_after = int(changes[0]) + 1
        return float(boundary_after) + 0.5

    stack_keys_all = ["rate_stack", "ss_rate_stack", "cs_rate_stack", "theta_stack", "slow_stack"]
    directions = [cell_data.get(k, {}) for k in dir_keys]

    all_stacks_5 = [[None] * 3 for _ in range(5)]
    row_vmax_5 = [0.0] * 5
    for col, dir_data in enumerate(directions):
        for row, key in enumerate(stack_keys_all):
            stack = _get_stack(dir_data, key)
            all_stacks_5[row][col] = stack
            if stack is not None and stack.size > 0 and row < 3:
                row_vmax_5[row] = max(row_vmax_5[row], float(np.nanmax(stack)))
    if fr_vmax_override is not None and len(fr_vmax_override) == 3:
        for row in range(3):
            v = float(fr_vmax_override[row])
            if np.isfinite(v) and v > 0:
                row_vmax_5[row] = v
    vmax_override: dict[str, float] = {}
    if isinstance(colorbar_vmax_override, dict):
        for key in ("rate", "ss", "cs", "theta"):
            val = colorbar_vmax_override.get(key)
            if val is None:
                continue
            val_f = float(val)
            if np.isfinite(val_f) and val_f > 0:
                vmax_override[key] = val_f
    if "rate" in vmax_override:
        row_vmax_5[0] = float(vmax_override["rate"])
    if "ss" in vmax_override:
        row_vmax_5[1] = float(vmax_override["ss"])
    if "cs" in vmax_override:
        row_vmax_5[2] = float(vmax_override["cs"])

    rate_vmax_disp = float(vmax_override.get("rate", row_vmax_5[0] * fr_vmax_scale if row_vmax_5[0] > 0 else 1.0))
    ss_vmax_disp = float(vmax_override.get("ss", row_vmax_5[1] * fr_vmax_scale if row_vmax_5[1] > 0 else 1.0))
    cs_vmax_disp = float(vmax_override.get("cs", row_vmax_5[2] * fr_vmax_scale if row_vmax_5[2] > 0 else 1.0))
    theta_vmax_disp = float(vmax_override.get("theta", theta_vlim[1]))
    if not np.isfinite(theta_vmax_disp):
        theta_vmax_disp = float(theta_vlim[1])
    if theta_vmax_disp <= float(theta_vlim[0]):
        theta_vmax_disp = float(theta_vlim[0]) + 1e-6

    plateau_stacks = [None] * 3
    if merge_plateau:
        for col, dir_data in enumerate(directions):
            p = dir_data.get("plateau_stack")
            if p is not None:
                p = np.asarray(p, dtype=float)
                if p.ndim == 2 and p.shape[1] == len(time_rel):
                    if bool(smooth_plateau) and smooth_window > 1:
                        smoothed_p = np.zeros_like(p)
                        for i in range(p.shape[0]):
                            smoothed_p[i] = _smooth_boxcar(p[i], int(smooth_window))
                        p = smoothed_p
                    plateau_stacks[col] = p

    if merge_ss_cs:
        n_rows = 4
        row_labels = ["FR", "SS+CS FR", "\u03b8 amp.", "Slow Vm"]
        ss_vmax = ss_vmax_disp
        cs_vmax = cs_vmax_disp
        row_vmin_disp = [0, 0, theta_vlim[0], slow_vlim[0]]
        row_vmax_disp = [
            rate_vmax_disp,
            None,
            theta_vmax_disp,
            slow_vlim[1],
        ]
        disp_to_orig = {0: 0, 1: None, 2: 3, 3: 4}
    else:
        n_rows = 5
        row_labels = ["FR", "SS FR", "CS FR", "\u03b8 amp.", "Slow Vm"]
        row_vmin_disp = [0, 0, 0, theta_vlim[0], slow_vlim[0]]
        row_vmax_disp = [rate_vmax_disp, ss_vmax_disp, cs_vmax_disp, theta_vmax_disp, slow_vlim[1]]
        disp_to_orig = {i: i for i in range(5)}
        ss_vmax = None
        cs_vmax = None

    col_trials = []
    for col in range(3):
        max_trials = 1
        for row in range(5):
            stack = all_stacks_5[row][col]
            if stack is not None:
                max_trials = max(max_trials, int(stack.shape[0]))
        col_trials.append(max_trials)

    if fixed_heatmap_height is not None and np.isfinite(float(fixed_heatmap_height)) and float(fixed_heatmap_height) > 0:
        heatmap_h = float(fixed_heatmap_height)
    else:
        heatmap_h = max(col_trials) * float(trial_height)
    hr = [heatmap_h, float(avg_height)]
    exact_layout = (
        panel_bbox is not None
        and fixed_subplot_width is not None
        and np.isfinite(float(fixed_subplot_width))
        and float(fixed_subplot_width) > 0
        and np.isfinite(float(heatmap_h))
        and float(heatmap_h) > 0
    )

    outer_gs = GridSpec(
        n_rows,
        4,
        figure=fig,
        width_ratios=[1, 1, 1, 0.05],
        wspace=float(heatmap_wspace),
        hspace=0.15,
    )
    axes = np.empty((n_rows, 3), dtype=object)
    avg_axes = np.empty((n_rows, 3), dtype=object)
    cbar_gs_top = [None] * n_rows
    fixed_cbar_positions: dict[int, tuple[float, float, float, float]] = {}

    for row in range(n_rows):
        for col in range(3):
            inner = GridSpecFromSubplotSpec(2, 1, subplot_spec=outer_gs[row, col], height_ratios=hr, hspace=0.05)
            axes[row, col] = fig.add_subplot(inner[0])
            if col == 0:
                avg_axes[row, col] = fig.add_subplot(inner[1])
            else:
                avg_axes[row, col] = fig.add_subplot(inner[1], sharey=avg_axes[row, 0])
        inner_cb = GridSpecFromSubplotSpec(2, 1, subplot_spec=outer_gs[row, 3], height_ratios=hr, hspace=0.05)
        cbar_gs_top[row] = inner_cb[0]
        fig.add_subplot(inner_cb[1]).axis("off")

    if exact_layout:
        fig_w, fig_h = fig.get_size_inches()
        panel_x, panel_y, panel_w, panel_h = [float(v) for v in panel_bbox]
        layout_in = _compute_pf_centered_panel_layout_inches(
            n_rows=n_rows,
            heatmap_height=float(heatmap_h),
            avg_height=float(avg_height),
            subplot_width=float(fixed_subplot_width),
            show_row_ylabel=bool(show_row_ylabel),
            show_column_titles=bool(show_column_titles),
            show_colorbar=bool(show_colorbar),
            heatmap_wspace=float(heatmap_wspace),
        )
        panel_x_in = panel_x * float(fig_w)
        panel_y_in = panel_y * float(fig_h)
        left_in = panel_x_in + float(layout_in["left_margin"])
        top_in = panel_y_in + panel_h * float(fig_h) - float(layout_in["top_margin"])
        subplot_width_in = float(fixed_subplot_width)
        heatmap_height_in = float(heatmap_h)
        avg_height_in = float(avg_height)
        heat_avg_gap_in = float(layout_in["heat_avg_gap"])
        row_gap_in = float(layout_in["row_gap"])
        col_gap_in = float(layout_in["col_gap"])
        cbar_x_in = left_in + 3.0 * subplot_width_in + 2.0 * col_gap_in + float(layout_in["cbar_gap"])
        cbar_w_in = float(layout_in["cbar_width"])

        for row in range(n_rows):
            row_top_in = top_in - row * (heatmap_height_in + heat_avg_gap_in + avg_height_in + row_gap_in)
            heat_y0_in = row_top_in - heatmap_height_in
            avg_y0_in = heat_y0_in - heat_avg_gap_in - avg_height_in
            for col in range(3):
                x0_in = left_in + col * (subplot_width_in + col_gap_in)
                axes[row, col].set_position([
                    x0_in / float(fig_w),
                    heat_y0_in / float(fig_h),
                    subplot_width_in / float(fig_w),
                    heatmap_height_in / float(fig_h),
                ])
                avg_axes[row, col].set_position([
                    x0_in / float(fig_w),
                    avg_y0_in / float(fig_h),
                    subplot_width_in / float(fig_w),
                    avg_height_in / float(fig_h),
                ])
            if bool(show_colorbar):
                fixed_cbar_positions[row] = (
                    cbar_x_in / float(fig_w),
                    heat_y0_in / float(fig_h),
                    cbar_w_in / float(fig_w),
                    heatmap_height_in / float(fig_h),
                )

    row_images = [None] * n_rows
    ss_rgb = np.array([2, 108, 128]) / 255.0
    cs_rgb = np.array([238, 155, 0]) / 255.0
    orig_row_colors = {0: "#555555", 1: "#026C80", 2: "#EE9B00", 3: "blue", 4: "red"}
    avg_ymins = {row: np.inf for row in range(n_rows)}
    avg_ymaxs = {row: -np.inf for row in range(n_rows)}
    xlim_mask = (time_rel >= xlim[0]) & (time_rel <= xlim[1])

    for col, (dir_data, dir_title) in enumerate(zip(directions, dir_titles)):
        n_trials = int(dir_data.get("n_trials", 0))
        n_total = int(dir_data.get("n_total_trials", 0))
        col_trials_for_title = int(n_trials) if int(n_trials) > 0 else int(col_trials[col])
        for disp_row in range(n_rows):
            ax = axes[disp_row, col]
            avg_ax = avg_axes[disp_row, col]
            orig_row = disp_to_orig[disp_row]
            actual_trials_local = int(col_trials[col])

            if orig_row is None:
                ss_stack = all_stacks_5[1][col]
                cs_stack = all_stacks_5[2][col]
                if (ss_stack is None or ss_stack.size == 0) and (cs_stack is None or cs_stack.size == 0):
                    ax.text(0.5, 0.5, "No data", transform=ax.transAxes, ha="center", va="center", fontsize=6)
                    ax.set_xlim(time_rel[0], time_rel[-1])
                    ax.set_ylim(col_trials[col] + 0.5, 0.5)
                else:
                    ref_stack = ss_stack if ss_stack is not None else cs_stack
                    actual_trials = ref_stack.shape[0]
                    actual_trials_local = int(actual_trials)
                    n_time = ref_stack.shape[1]
                    ss_nan = np.isnan(ss_stack) if ss_stack is not None else np.ones((actual_trials, n_time), dtype=bool)
                    cs_nan = np.isnan(cs_stack) if cs_stack is not None else np.ones((actual_trials, n_time), dtype=bool)
                    both_nan = ss_nan & cs_nan
                    ss_norm = (
                        np.clip(np.nan_to_num(ss_stack, nan=0.0) / ss_vmax, 0, 1)
                        if ss_stack is not None
                        else np.zeros((actual_trials, n_time))
                    )
                    cs_norm = (
                        np.clip(np.nan_to_num(cs_stack, nan=0.0) / cs_vmax, 0, 1)
                        if cs_stack is not None
                        else np.zeros((actual_trials, n_time))
                    )
                    rgba = np.ones((actual_trials, n_time, 4))
                    for ch in range(3):
                        rgba[..., ch] = 1.0 - ss_norm * (1.0 - ss_rgb[ch]) - cs_norm * (1.0 - cs_rgb[ch])
                    rgba[..., :3] = np.clip(rgba[..., :3], 0, 1)
                    rgba[both_nan] = [0.9, 0.9, 0.9, 1.0]
                    ax.imshow(
                        rgba,
                        aspect="auto",
                        origin="upper",
                        extent=[time_rel[0], time_rel[-1], actual_trials + 0.5, 0.5],
                        interpolation="nearest",
                        resample=False,
                    )
                    ax.axvline(center_line_x, color="k", linewidth=0.25, linestyle="--", alpha=0.5)
                    gap_y = _session_gap_y(dir_data, actual_trials)
                    if gap_y is not None:
                        ax.axhline(gap_y, color=session_gap_line_color, linewidth=session_gap_line_width, alpha=0.9)
                    ax.set_ylim(col_trials[col] + 0.5, 0.5)

                if ss_stack is not None and ss_stack.size > 0:
                    ss_mean = _smooth_avg(np.nanmean(ss_stack, axis=0))
                    ss_n = np.sum(~np.isnan(ss_stack), axis=0)
                    ss_sem = _smooth_avg(np.nanstd(ss_stack, axis=0) / np.sqrt(np.maximum(ss_n, 1)))
                    avg_ax.plot(time_rel, ss_mean, color="#026C80", linewidth=0.7)
                    avg_ax.fill_between(time_rel, ss_mean - ss_sem, ss_mean + ss_sem, color="#026C80", alpha=0.2)
                    vis = ss_mean[xlim_mask]
                    avg_ymins[disp_row] = min(avg_ymins[disp_row], float(np.nanmin(vis)))
                    avg_ymaxs[disp_row] = max(avg_ymaxs[disp_row], float(np.nanmax(vis)))
                if cs_stack is not None and cs_stack.size > 0:
                    cs_mean = _smooth_avg(np.nanmean(cs_stack, axis=0))
                    cs_n = np.sum(~np.isnan(cs_stack), axis=0)
                    cs_sem = _smooth_avg(np.nanstd(cs_stack, axis=0) / np.sqrt(np.maximum(cs_n, 1)))
                    avg_ax.plot(time_rel, cs_mean, color="#EE9B00", linewidth=0.7)
                    avg_ax.fill_between(time_rel, cs_mean - cs_sem, cs_mean + cs_sem, color="#EE9B00", alpha=0.2)
                    vis = cs_mean[xlim_mask]
                    avg_ymins[disp_row] = min(avg_ymins[disp_row], float(np.nanmin(vis)))
                    avg_ymaxs[disp_row] = max(avg_ymaxs[disp_row], float(np.nanmax(vis)))
                avg_ax.axvline(center_line_x, color="k", linewidth=0.25, linestyle="--", alpha=0.5)
            else:
                stack = all_stacks_5[orig_row][col]
                if stack is None or stack.size == 0:
                    ax.text(0.5, 0.5, "No data", transform=ax.transAxes, ha="center", va="center", fontsize=6)
                    ax.set_xlim(time_rel[0], time_rel[-1])
                    ax.set_ylim(col_trials[col] + 0.5, 0.5)
                else:
                    if orig_row == 4:
                        cmap_use = "RdBu_r"
                    elif orig_row == 3:
                        cmap_use = "Blues"
                    else:
                        cmap_use = ["Greys", "BuGn", "YlOrBr"][orig_row]
                    cmap_obj = plt.get_cmap(cmap_use).copy()
                    cmap_obj.set_bad(color=[0.9, 0.9, 0.9, 1.0])
                    vmin_val = row_vmin_disp[disp_row]
                    vmax_val = row_vmax_disp[disp_row]
                    actual_trials = stack.shape[0]
                    actual_trials_local = int(actual_trials)
                    im = ax.imshow(
                        stack,
                        aspect="auto",
                        origin="upper",
                        extent=[time_rel[0], time_rel[-1], actual_trials + 0.5, 0.5],
                        cmap=cmap_obj,
                        vmin=vmin_val,
                        vmax=vmax_val,
                        interpolation="nearest",
                        resample=False,
                    )
                    if merge_plateau and orig_row == 0:
                        p_stack = plateau_stacks[col]
                        if p_stack is not None and p_stack.size > 0 and np.any(p_stack != 0):
                            p_abs = np.abs(p_stack)
                            p_vmax = float(plateau_vlim) if float(plateau_vlim) > 0 else 0.1
                            p_norm = np.clip(p_abs / p_vmax, 0, 1)
                            rgba_p = np.zeros((*p_stack.shape, 4))
                            rgba_p[..., 0] = 1.0
                            rgba_p[..., 3] = np.where(p_stack != 0, p_norm * 0.8, 0.0)
                            ax.imshow(
                                rgba_p,
                                aspect="auto",
                                origin="upper",
                                extent=[time_rel[0], time_rel[-1], actual_trials + 0.5, 0.5],
                                interpolation="nearest",
                                resample=False,
                            )
                    ax.axvline(center_line_x, color="k", linewidth=0.25, linestyle="--", alpha=0.5)
                    gap_y = _session_gap_y(dir_data, actual_trials)
                    if gap_y is not None:
                        ax.axhline(gap_y, color=session_gap_line_color, linewidth=session_gap_line_width, alpha=0.9)
                    ax.set_ylim(col_trials[col] + 0.5, 0.5)
                    if row_images[disp_row] is None:
                        row_images[disp_row] = im

                if stack is not None and stack.size > 0:
                    mean_trace = _smooth_avg(np.nanmean(stack, axis=0))
                    n_valid = np.sum(~np.isnan(stack), axis=0)
                    sem_trace = _smooth_avg(np.nanstd(stack, axis=0) / np.sqrt(np.maximum(n_valid, 1)))
                    color = orig_row_colors.get(orig_row, "#555555")
                    avg_ax.plot(time_rel, mean_trace, color=color, linewidth=0.7)
                    avg_ax.fill_between(time_rel, mean_trace - sem_trace, mean_trace + sem_trace, color=color, alpha=0.2)
                    vis = mean_trace[xlim_mask]
                    avg_ymins[disp_row] = min(avg_ymins[disp_row], float(np.nanmin(vis)))
                    avg_ymaxs[disp_row] = max(avg_ymaxs[disp_row], float(np.nanmax(vis)))
                avg_ax.axvline(center_line_x, color="k", linewidth=0.25, linestyle="--", alpha=0.5)
                if orig_row == 4:
                    avg_ax.axhline(0, color="k", linewidth=0.25, linestyle="--", alpha=0.5)

            if disp_row == 0 and bool(show_column_titles):
                if bool(column_title_include_trials):
                    ax.set_title(f"{dir_title}\n(T={int(col_trials_for_title)})", fontsize=6)
                else:
                    ax.set_title(f"{dir_title}", fontsize=6)
            if bool(show_row_ylabel) and col == 0:
                ax.set_ylabel(row_labels[disp_row], fontsize=6)
            ax.tick_params(labelbottom=False)
            if disp_row == n_rows - 1:
                if (x_label_col_idx is None) or (int(col) == int(x_label_col_idx)):
                    avg_ax.set_xlabel(x_label, fontsize=6)
                else:
                    avg_ax.set_xlabel("")
            else:
                avg_ax.tick_params(labelbottom=False)
            if bool(show_heatmap_yticks):
                max_trial = int(max(1, int(actual_trials_local)))
                ax.set_yticks([1, max_trial] if max_trial > 1 else [1])
                if bool(show_heatmap_yticks_all_columns):
                    ax.tick_params(labelsize=5, labelleft=True)
                elif bool(show_row_ylabel) and col == 0:
                    ax.tick_params(labelsize=5, labelleft=True)
                else:
                    ax.tick_params(labelsize=5, labelleft=False)
            else:
                ax.set_yticks([])
                ax.tick_params(labelsize=5, labelleft=False)
            if bool(show_avg_yticks_left_only):
                show_avg_left = bool(show_row_ylabel) and (col == 0)
                avg_ax.tick_params(labelsize=5, labelleft=show_avg_left)
            else:
                avg_ax.tick_params(labelsize=4)
            avg_ax.yaxis.set_major_formatter(FuncFormatter(_format_avg_axis_ticklabel))
            avg_ax.spines["top"].set_visible(False)
            avg_ax.spines["right"].set_visible(False)

    for ax in axes.flat:
        ax.set_xlim(xlim)
    for ax in avg_axes.flat:
        ax.set_xlim(xlim)

    resolved_avg_ylim: dict[int, tuple[float, float]] = {}
    for row in range(n_rows):
        y0 = y1 = None
        if isinstance(avg_ylim_override, dict) and row in avg_ylim_override:
            y_pair = avg_ylim_override.get(row)
            if isinstance(y_pair, (tuple, list)) and len(y_pair) == 2:
                y0 = float(y_pair[0])
                y1 = float(y_pair[1])
        if y0 is None or y1 is None:
            if np.isfinite(avg_ymins[row]) and np.isfinite(avg_ymaxs[row]):
                span = avg_ymaxs[row] - avg_ymins[row]
                margin = span * 0.05 if span > 0 else 0.01
                y0 = float(avg_ymins[row] - margin)
                y1 = float(avg_ymaxs[row] + margin)
        if y0 is None or y1 is None or not np.isfinite(y0) or not np.isfinite(y1):
            continue
        for col in range(3):
            avg_axes[row, col].set_ylim(y0, y1)
        resolved_avg_ylim[row] = (y0, y1)

    for row in range(n_rows):
        if not bool(show_colorbar):
            fig.add_subplot(cbar_gs_top[row]).axis("off")
            continue
        if disp_to_orig[row] is None:
            gs_inner = GridSpecFromSubplotSpec(2, 1, subplot_spec=cbar_gs_top[row], hspace=0.4)
            ss_cmap = LinearSegmentedColormap.from_list("ss_teal", ["white", "#026C80"])
            cs_cmap = LinearSegmentedColormap.from_list("cs_orange", ["white", "#EE9B00"])

            ax_ss_cb = fig.add_subplot(gs_inner[0])
            sm_ss = ScalarMappable(cmap=ss_cmap, norm=Normalize(vmin=0, vmax=ss_vmax))
            sm_ss.set_array([])
            cb_ss = fig.colorbar(sm_ss, cax=ax_ss_cb)
            cb_ss.ax.tick_params(labelsize=int(ss_cs_cbar_tick_labelsize))
            cb_ss.set_label("SS", fontsize=4, rotation=0, labelpad=8)

            ax_cs_cb = fig.add_subplot(gs_inner[1])
            sm_cs = ScalarMappable(cmap=cs_cmap, norm=Normalize(vmin=0, vmax=cs_vmax))
            sm_cs.set_array([])
            cb_cs = fig.colorbar(sm_cs, cax=ax_cs_cb)
            cb_cs.ax.tick_params(labelsize=int(ss_cs_cbar_tick_labelsize))
            cb_cs.set_label("CS", fontsize=4, rotation=0, labelpad=8)
            if exact_layout and row in fixed_cbar_positions:
                x0, y0, w0, h0 = fixed_cbar_positions[row]
                cb_gap_in = 0.06
                cb_gap = cb_gap_in / float(fig_h)
                cb_half_h = max(0.0, (h0 - cb_gap) / 2.0)
                ax_ss_cb.set_position([x0, y0 + cb_half_h + cb_gap, w0, cb_half_h])
                ax_cs_cb.set_position([x0, y0, w0, cb_half_h])
        elif row_images[row] is not None:
            ax_cb = fig.add_subplot(cbar_gs_top[row])
            cbar = fig.colorbar(row_images[row], cax=ax_cb)
            cbar.ax.tick_params(labelsize=4)
            if exact_layout and row in fixed_cbar_positions:
                ax_cb.set_position(list(fixed_cbar_positions[row]))
        else:
            fig.add_subplot(cbar_gs_top[row]).axis("off")

    if apply_tight_layout and (not exact_layout):
        try:
            tight_fn = getattr(fig, "tight_layout", None)
            if callable(tight_fn):
                tight_fn()
        except Exception:
            pass
    return resolved_avg_ylim


def plot_pf_centered_single_cell_heatmap(
    entry_data: dict[str, Any],
    time_rel: np.ndarray,
    *,
    smooth_window: int = 0,
    out_path: str | Path | None = None,
    show_plot: bool = True,
    fr_vmax_scale: float = 0.5,
    theta_vlim: tuple[float, float] = (0, 0.4),
    slow_vlim: tuple[float, float] = (-0.2, 0.2),
    fig_width: float = 4.5,
    trial_height: float = 0.06,
    xlim: tuple[float, float] = (-4, 4),
    merge_ss_cs: bool = False,
    merge_plateau: bool = True,
    smooth_plateau: bool = False,
    plateau_vlim: float = 0.1,
    avg_height: float = 0.3,
    avg_smooth_window: int = 0,
    x_label: str = "Time (s)",
    center_line_x: float = 0.0,
    show_session_gap_line: bool = False,
    auto_colorbar_vmax_from_pf1_all: bool = True,
    colorbar_std_multiplier: float = 3.0,
    colorbar_vmax_override: dict[str, float] | None = None,
    show_titles: bool = True,
    show_column_titles: bool | None = None,
    column_title_include_trials: bool = False,
    x_label_col_idx: int | None = None,
    show_heatmap_yticks: bool = True,
    show_heatmap_yticks_all_columns: bool = False,
    ss_cs_cbar_tick_labelsize: int = 3,
    heatmap_wspace: float = 0.15,
    avg_theta_ylim: tuple[float, float] | None = None,
    avg_slow_ylim: tuple[float, float] | None = None,
    disable_pf2_avg_ylim_sync: bool = False,
    fixed_heatmap_height: float | None = None,
    fixed_subplot_width: float | None = None,
    direction_keys: tuple[str, str, str] | list[str] = ("all", "cw", "ccw"),
    direction_titles: tuple[str, str, str] | list[str] | None = None,
) -> plt.Figure:
    dir_keys, dir_titles = _normalize_direction_triplet(
        direction_keys=direction_keys,
        direction_titles=direction_titles,
    )
    show_column_titles_use = bool(show_titles) if show_column_titles is None else bool(show_column_titles)
    exact_layout = (
        fixed_subplot_width is not None
        and np.isfinite(float(fixed_subplot_width))
        and float(fixed_subplot_width) > 0
        and fixed_heatmap_height is not None
        and np.isfinite(float(fixed_heatmap_height))
        and float(fixed_heatmap_height) > 0
    )
    if exact_layout:
        n_rows = 4 if bool(merge_ss_cs) else 5
        panel_layout = _compute_pf_centered_panel_layout_inches(
            n_rows=n_rows,
            heatmap_height=float(fixed_heatmap_height),
            avg_height=float(avg_height),
            subplot_width=float(fixed_subplot_width),
            show_row_ylabel=True,
            show_column_titles=show_column_titles_use,
            show_colorbar=True,
            heatmap_wspace=float(heatmap_wspace),
        )
        fig_height = float(panel_layout["panel_height"])
        fig = plt.figure(figsize=(float(panel_layout["panel_width"]), fig_height))
    else:
        fig_height = _estimate_single_heatmap_figure_height(
            entry_data,
            np.asarray(time_rel, dtype=float),
            trial_height=trial_height,
            avg_height=avg_height,
            merge_ss_cs=merge_ss_cs,
            fixed_heatmap_height=fixed_heatmap_height,
            direction_keys=dir_keys,
        )
        fig = plt.figure(figsize=(fig_width, fig_height))
    colorbar_vmax_use = dict(colorbar_vmax_override) if isinstance(colorbar_vmax_override, dict) else None
    if colorbar_vmax_use is None and bool(auto_colorbar_vmax_from_pf1_all):
        colorbar_vmax_use = _compute_cell_colorbar_vmax_from_all_direction(
            entry_data,
            np.asarray(time_rel, dtype=float),
            smooth_window=int(smooth_window),
            std_multiplier=float(colorbar_std_multiplier),
        )
    avg_ylim_override: dict[int, tuple[float, float]] = {}
    theta_row = 2 if bool(merge_ss_cs) else 3
    slow_row = 3 if bool(merge_ss_cs) else 4
    if avg_theta_ylim is not None:
        avg_ylim_override[int(theta_row)] = (float(avg_theta_ylim[0]), float(avg_theta_ylim[1]))
    if avg_slow_ylim is not None:
        avg_ylim_override[int(slow_row)] = (float(avg_slow_ylim[0]), float(avg_slow_ylim[1]))
    _plot_single_cell_heatmap_on_figure(
        fig,
        entry_data,
        np.asarray(time_rel, dtype=float),
        smooth_window=smooth_window,
        fr_vmax_scale=fr_vmax_scale,
        theta_vlim=theta_vlim,
        slow_vlim=slow_vlim,
        trial_height=trial_height,
        xlim=xlim,
        merge_ss_cs=merge_ss_cs,
        merge_plateau=merge_plateau,
        smooth_plateau=smooth_plateau,
        plateau_vlim=plateau_vlim,
        avg_height=avg_height,
        avg_smooth_window=avg_smooth_window,
        x_label=x_label,
        center_line_x=center_line_x,
        show_session_gap_line=show_session_gap_line,
        colorbar_vmax_override=colorbar_vmax_use,
        avg_ylim_override=(avg_ylim_override if len(avg_ylim_override) > 0 else None),
        fixed_heatmap_height=fixed_heatmap_height,
        fixed_subplot_width=fixed_subplot_width,
        panel_bbox=((0.0, 0.0, 1.0, 1.0) if exact_layout else None),
        show_column_titles=show_column_titles_use,
        column_title_include_trials=bool(column_title_include_trials),
        x_label_col_idx=x_label_col_idx,
        show_heatmap_yticks=bool(show_heatmap_yticks),
        show_heatmap_yticks_all_columns=bool(show_heatmap_yticks_all_columns),
        ss_cs_cbar_tick_labelsize=int(ss_cs_cbar_tick_labelsize),
        heatmap_wspace=float(heatmap_wspace),
        apply_tight_layout=(not exact_layout),
        direction_keys=dir_keys,
        direction_titles=dir_titles,
    )
    if out_path is not None:
        fig.savefig(out_path, dpi=300)
    if show_plot:
        plt.show()
    else:
        plt.close(fig)
    return fig


def plot_pf_centered_dual_component_heatmap(
    entry_primary: dict[str, Any],
    entry_secondary: dict[str, Any] | None,
    time_rel: np.ndarray,
    *,
    smooth_window: int = 0,
    out_path: str | Path | None = None,
    show_plot: bool = True,
    fr_vmax_scale: float = 0.5,
    theta_vlim: tuple[float, float] = (0, 0.4),
    slow_vlim: tuple[float, float] = (-0.2, 0.2),
    fig_width: float = 4.5,
    trial_height: float = 0.06,
    xlim: tuple[float, float] = (-4, 4),
    merge_ss_cs: bool = False,
    merge_plateau: bool = True,
    smooth_plateau: bool = False,
    plateau_vlim: float = 0.1,
    avg_height: float = 0.3,
    avg_smooth_window: int = 0,
    x_label: str = "Time (s)",
    center_line_x: float = 0.0,
    show_session_gap_line: bool = False,
    auto_colorbar_vmax_from_pf1_all: bool = True,
    colorbar_std_multiplier: float = 3.0,
    fr_vmax_override: tuple[float, float, float] | None = None,
    colorbar_vmax_override: dict[str, float] | None = None,
    show_titles: bool = True,
    show_column_titles: bool | None = None,
    column_title_include_trials: bool = False,
    x_label_col_idx: int | None = None,
    show_heatmap_yticks: bool = True,
    show_heatmap_yticks_all_columns: bool = False,
    ss_cs_cbar_tick_labelsize: int = 3,
    heatmap_wspace: float = 0.15,
    avg_theta_ylim: tuple[float, float] | None = None,
    avg_slow_ylim: tuple[float, float] | None = None,
    disable_pf2_avg_ylim_sync: bool = False,
    fixed_heatmap_height: float | None = None,
    fixed_subplot_width: float | None = None,
    direction_keys: tuple[str, str, str] | list[str] = ("all", "cw", "ccw"),
    direction_titles: tuple[str, str, str] | list[str] | None = None,
) -> plt.Figure:
    dir_keys, dir_titles = _normalize_direction_triplet(
        direction_keys=direction_keys,
        direction_titles=direction_titles,
    )
    if entry_secondary is None:
        return plot_pf_centered_single_cell_heatmap(
            entry_primary,
            time_rel,
            smooth_window=smooth_window,
            out_path=out_path,
            show_plot=show_plot,
            fr_vmax_scale=fr_vmax_scale,
            theta_vlim=theta_vlim,
            slow_vlim=slow_vlim,
            fig_width=fig_width,
            trial_height=trial_height,
            xlim=xlim,
            merge_ss_cs=merge_ss_cs,
            merge_plateau=merge_plateau,
            smooth_plateau=smooth_plateau,
            plateau_vlim=plateau_vlim,
            avg_height=avg_height,
            avg_smooth_window=avg_smooth_window,
            x_label=x_label,
            center_line_x=center_line_x,
            show_session_gap_line=show_session_gap_line,
            auto_colorbar_vmax_from_pf1_all=auto_colorbar_vmax_from_pf1_all,
            colorbar_std_multiplier=colorbar_std_multiplier,
            colorbar_vmax_override=colorbar_vmax_override,
            show_titles=show_titles,
            show_column_titles=show_column_titles,
            column_title_include_trials=column_title_include_trials,
            x_label_col_idx=x_label_col_idx,
            show_heatmap_yticks=show_heatmap_yticks,
            show_heatmap_yticks_all_columns=show_heatmap_yticks_all_columns,
            ss_cs_cbar_tick_labelsize=ss_cs_cbar_tick_labelsize,
            heatmap_wspace=heatmap_wspace,
            avg_theta_ylim=avg_theta_ylim,
            avg_slow_ylim=avg_slow_ylim,
            fixed_heatmap_height=fixed_heatmap_height,
            fixed_subplot_width=fixed_subplot_width,
            direction_keys=dir_keys,
            direction_titles=dir_titles,
        )

    time_rel = np.asarray(time_rel, dtype=float)
    fr_vmax_use = fr_vmax_override
    if fr_vmax_use is None:
        fr_vmax_use = _compute_single_cell_fr_vmaxs(
            entry_primary,
            time_rel,
            smooth_window=int(smooth_window),
            direction_keys=dir_keys,
        )
    colorbar_vmax_use = dict(colorbar_vmax_override) if isinstance(colorbar_vmax_override, dict) else None
    if colorbar_vmax_use is None and bool(auto_colorbar_vmax_from_pf1_all):
        colorbar_vmax_use = _compute_cell_colorbar_vmax_from_all_direction(
            entry_primary,
            time_rel,
            smooth_window=int(smooth_window),
            std_multiplier=float(colorbar_std_multiplier),
        )
    fixed_avg_ylim_override: dict[int, tuple[float, float]] = {}
    theta_row = 2 if bool(merge_ss_cs) else 3
    slow_row = 3 if bool(merge_ss_cs) else 4
    if avg_theta_ylim is not None:
        fixed_avg_ylim_override[int(theta_row)] = (float(avg_theta_ylim[0]), float(avg_theta_ylim[1]))
    if avg_slow_ylim is not None:
        fixed_avg_ylim_override[int(slow_row)] = (float(avg_slow_ylim[0]), float(avg_slow_ylim[1]))
    fixed_heatmap_height_use = fixed_heatmap_height
    if fixed_heatmap_height_use is None:
        max_trials_primary = _compute_single_heatmap_max_trials(
            entry_primary,
            time_rel,
            direction_keys=dir_keys,
        )
        max_trials_secondary = _compute_single_heatmap_max_trials(
            entry_secondary,
            time_rel,
            direction_keys=dir_keys,
        )
        fixed_heatmap_height_use = max(max_trials_primary, max_trials_secondary) * float(trial_height)
    show_column_titles_use = bool(show_titles) if show_column_titles is None else bool(show_column_titles)
    exact_layout = (
        fixed_subplot_width is not None
        and np.isfinite(float(fixed_subplot_width))
        and float(fixed_subplot_width) > 0
        and fixed_heatmap_height_use is not None
        and np.isfinite(float(fixed_heatmap_height_use))
        and float(fixed_heatmap_height_use) > 0
    )

    if exact_layout:
        n_rows = 4 if bool(merge_ss_cs) else 5
        left_layout = _compute_pf_centered_panel_layout_inches(
            n_rows=n_rows,
            heatmap_height=float(fixed_heatmap_height_use),
            avg_height=float(avg_height),
            subplot_width=float(fixed_subplot_width),
            show_row_ylabel=True,
            show_column_titles=show_column_titles_use,
            show_colorbar=False,
            heatmap_wspace=float(heatmap_wspace),
        )
        right_layout = _compute_pf_centered_panel_layout_inches(
            n_rows=n_rows,
            heatmap_height=float(fixed_heatmap_height_use),
            avg_height=float(avg_height),
            subplot_width=float(fixed_subplot_width),
            show_row_ylabel=False,
            show_column_titles=show_column_titles_use,
            show_colorbar=True,
            heatmap_wspace=float(heatmap_wspace),
        )
        panel_gap = 0.18
        fig_w = float(left_layout["panel_width"]) + float(panel_gap) + float(right_layout["panel_width"])
        fig_h = max(float(left_layout["panel_height"]), float(right_layout["panel_height"]))
        fig = plt.figure(figsize=(fig_w, fig_h))
        left_bbox = (0.0, 0.0, float(left_layout["panel_width"]) / fig_w, 1.0)
        right_bbox = (
            (float(left_layout["panel_width"]) + float(panel_gap)) / fig_w,
            0.0,
            float(right_layout["panel_width"]) / fig_w,
            1.0,
        )
    else:
        h1 = _estimate_single_heatmap_figure_height(
            entry_primary,
            time_rel,
            trial_height=trial_height,
            avg_height=avg_height,
            merge_ss_cs=merge_ss_cs,
            fixed_heatmap_height=fixed_heatmap_height_use,
            direction_keys=dir_keys,
        )
        h2 = _estimate_single_heatmap_figure_height(
            entry_secondary,
            time_rel,
            trial_height=trial_height,
            avg_height=avg_height,
            merge_ss_cs=merge_ss_cs,
            fixed_heatmap_height=fixed_heatmap_height_use,
            direction_keys=dir_keys,
        )
        fig = plt.figure(figsize=(fig_width * 2 + 0.45, max(h1, h2)))
        subfigs = fig.subfigures(1, 2, wspace=0.04)
        subfigs = list(np.ravel(subfigs))

    pf1_avg_ylim = _plot_single_cell_heatmap_on_figure(
        (fig if exact_layout else subfigs[0]),
        entry_primary,
        time_rel,
        smooth_window=smooth_window,
        fr_vmax_scale=fr_vmax_scale,
        theta_vlim=theta_vlim,
        slow_vlim=slow_vlim,
        trial_height=trial_height,
        xlim=xlim,
        merge_ss_cs=merge_ss_cs,
        merge_plateau=merge_plateau,
        smooth_plateau=smooth_plateau,
        plateau_vlim=plateau_vlim,
        avg_height=avg_height,
        avg_smooth_window=avg_smooth_window,
        x_label=x_label,
        center_line_x=center_line_x,
        show_session_gap_line=show_session_gap_line,
        fr_vmax_override=fr_vmax_use,
        colorbar_vmax_override=colorbar_vmax_use,
        avg_ylim_override=(fixed_avg_ylim_override if len(fixed_avg_ylim_override) > 0 else None),
        fixed_heatmap_height=fixed_heatmap_height_use,
        fixed_subplot_width=fixed_subplot_width,
        panel_bbox=(left_bbox if exact_layout else None),
        show_row_ylabel=True,
        show_colorbar=False,
        show_avg_yticks_left_only=True,
        show_column_titles=show_column_titles_use,
        column_title_include_trials=bool(column_title_include_trials),
        x_label_col_idx=x_label_col_idx,
        show_heatmap_yticks=bool(show_heatmap_yticks),
        show_heatmap_yticks_all_columns=bool(show_heatmap_yticks_all_columns),
        ss_cs_cbar_tick_labelsize=int(ss_cs_cbar_tick_labelsize),
        heatmap_wspace=float(heatmap_wspace),
        apply_tight_layout=(not exact_layout),
        direction_keys=dir_keys,
        direction_titles=dir_titles,
    )
    _plot_single_cell_heatmap_on_figure(
        (fig if exact_layout else subfigs[1]),
        entry_secondary,
        time_rel,
        smooth_window=smooth_window,
        fr_vmax_scale=fr_vmax_scale,
        theta_vlim=theta_vlim,
        slow_vlim=slow_vlim,
        trial_height=trial_height,
        xlim=xlim,
        merge_ss_cs=merge_ss_cs,
        merge_plateau=merge_plateau,
        smooth_plateau=smooth_plateau,
        plateau_vlim=plateau_vlim,
        avg_height=avg_height,
        avg_smooth_window=avg_smooth_window,
        x_label=x_label,
        center_line_x=center_line_x,
        show_session_gap_line=show_session_gap_line,
        fr_vmax_override=fr_vmax_use,
        colorbar_vmax_override=colorbar_vmax_use,
        avg_ylim_override=(None if bool(disable_pf2_avg_ylim_sync) else pf1_avg_ylim),
        fixed_heatmap_height=fixed_heatmap_height_use,
        fixed_subplot_width=fixed_subplot_width,
        panel_bbox=(right_bbox if exact_layout else None),
        show_row_ylabel=False,
        show_colorbar=True,
        show_avg_yticks_left_only=(not bool(disable_pf2_avg_ylim_sync)),
        show_column_titles=show_column_titles_use,
        column_title_include_trials=bool(column_title_include_trials),
        x_label_col_idx=x_label_col_idx,
        show_heatmap_yticks=bool(show_heatmap_yticks),
        show_heatmap_yticks_all_columns=bool(show_heatmap_yticks_all_columns),
        ss_cs_cbar_tick_labelsize=int(ss_cs_cbar_tick_labelsize),
        heatmap_wspace=float(heatmap_wspace),
        apply_tight_layout=(not exact_layout),
        direction_keys=dir_keys,
        direction_titles=dir_titles,
    )

    session = entry_primary["session"]
    cell_idx = int(entry_primary["cell_idx"])
    if bool(show_titles):
        subfigs[0].suptitle("Primary PF", fontsize=6, y=0.998)
        subfigs[1].suptitle("Secondary PF", fontsize=6, y=0.998)
        fig.suptitle(f"{session} - Cell {cell_idx + 1}", fontsize=8, y=0.999)

    if out_path is not None:
        fig.savefig(out_path, dpi=300)
    if show_plot:
        plt.show()
    else:
        plt.close(fig)
    return fig


def generate_pf_centered_component_heatmaps(
    dataset: dict[str, Any],
    *,
    figure_save_folder: str | Path,
    clear_output: bool = True,
    smooth_window: int = 300,
    fr_vmax_scale: float = 0.6,
    theta_vlim: tuple[float, float] = (0, 0.5),
    slow_vlim: tuple[float, float] = (-0.5, 0.5),
    fig_width: float = 3.8,
    trial_height: float = 0.02,
    xlim: tuple[float, float] = (-4, 4),
    merge_ss_cs: bool = True,
    merge_plateau: bool = True,
    smooth_plateau: bool = False,
    plateau_vlim: float = 0.01,
    avg_smooth_window: int = 0,
    x_label: str = "Time (s)",
    center_line_x: float = 0.0,
    show_session_gap_line: bool = False,
    auto_colorbar_vmax_from_pf1_all: bool = True,
    colorbar_std_multiplier: float = 3.0,
    output_prefix: str = "pf_centered",
    show_plot: bool = False,
) -> dict[str, Any]:
    figure_root = Path(figure_save_folder)
    figure_root.mkdir(parents=True, exist_ok=True)
    print(f"PF-centered heatmaps root folder: {figure_root}")
    categories = _ordered_dataset_categories(dataset)
    cat_to_dir = {
        cat: figure_root / _category_output_dir_name(prefix=str(output_prefix), category=cat, suffix="_heatmaps")
        for cat in categories
    }
    summary: dict[str, Any] = {}

    for category in categories:
        cat_data = dataset.get(category, {})
        primary_entries = list(cat_data.get(1, {}).get("entries", []))
        secondary_entries = list(cat_data.get(2, {}).get("entries", []))
        primary_time_rel = np.asarray(cat_data.get(1, {}).get("time_rel", []), dtype=float)
        secondary_time_rel = np.asarray(cat_data.get(2, {}).get("time_rel", []), dtype=float)
        pri_by_key = {(e["session"], int(e["cell_idx"])): e for e in primary_entries}
        sec_by_key = {(e["session"], int(e["cell_idx"])): e for e in secondary_entries}
        all_keys = sorted(set(pri_by_key.keys()) | set(sec_by_key.keys()))
        out_dir = cat_to_dir[category]
        if clear_output and out_dir.exists():
            shutil.rmtree(out_dir)
        out_dir.mkdir(parents=True, exist_ok=True)
        print(f"[{category}] output folder: {out_dir}")

        n_saved = 0
        n_dual = 0
        n_pf2_only = 0
        for i, key in enumerate(all_keys, start=1):
            entry1 = pri_by_key.get(key)
            entry2 = sec_by_key.get(key)
            if entry1 is not None:
                entry_main = entry1
                entry_secondary = entry2
                time_rel = primary_time_rel
            else:
                entry_main = entry2
                entry_secondary = None
                time_rel = secondary_time_rel
                n_pf2_only += 1
            if entry_main is None:
                continue
            out_path = out_dir / f"{entry_main['session']}_Cell{int(entry_main['cell_idx']) + 1}_heatmap.svg"
            plot_pf_centered_dual_component_heatmap(
                entry_primary=entry_main,
                entry_secondary=entry_secondary,
                time_rel=time_rel,
                smooth_window=smooth_window,
                out_path=out_path,
                show_plot=show_plot,
                fr_vmax_scale=fr_vmax_scale,
                theta_vlim=theta_vlim,
                slow_vlim=slow_vlim,
                fig_width=fig_width,
                trial_height=trial_height,
                xlim=xlim,
                merge_ss_cs=merge_ss_cs,
                merge_plateau=merge_plateau,
                smooth_plateau=smooth_plateau,
                plateau_vlim=plateau_vlim,
                avg_smooth_window=avg_smooth_window,
                x_label=x_label,
                center_line_x=center_line_x,
                show_session_gap_line=show_session_gap_line,
                auto_colorbar_vmax_from_pf1_all=auto_colorbar_vmax_from_pf1_all,
                colorbar_std_multiplier=colorbar_std_multiplier,
            )
            n_saved += 1
            if entry1 is not None and entry2 is not None:
                n_dual += 1
            print(f"[{category}] {i}/{len(all_keys)} saved: {out_path.name}")

        summary[category] = {
            "output_dir": str(out_dir),
            "n_primary_entries": len(primary_entries),
            "n_secondary_entries": len(secondary_entries),
            "n_union_entries": len(all_keys),
            "n_pf2_only_entries": int(n_pf2_only),
            "n_saved_files": n_saved,
            "n_dual_pf_files": n_dual,
        }
    return summary


def _extract_cell_metric_trace(
    cell_data: dict[str, Any],
    direction: str,
    metric_key: str,
    n_time: int,
    *,
    smooth_window: int | None = None,
    avg_smooth_window: int | None = None,
) -> np.ndarray | None:
    """Extract a per-cell mean trace using the same stack->mean path as heatmaps."""
    if cell_data is None:
        return None
    dir_data = cell_data.get(direction, {})
    arr = dir_data.get(metric_key)
    if arr is None:
        return None
    arr = np.asarray(arr, dtype=float)
    smooth_win = None if smooth_window is None else int(smooth_window)
    avg_smooth_win = None if avg_smooth_window is None else int(avg_smooth_window)

    if arr.ndim == 2:
        if arr.shape[1] != n_time:
            return None
        stack = arr
        if smooth_win is not None and smooth_win > 1:
            smoothed = np.full_like(stack, np.nan)
            for i in range(stack.shape[0]):
                smoothed[i] = _smooth_boxcar(stack[i], smooth_win)
            stack = smoothed
        trace = np.nanmean(stack, axis=0)
    elif arr.ndim == 1:
        if arr.size != n_time:
            return None
        trace = arr.copy()
        if smooth_win is not None and smooth_win > 1:
            trace = _smooth_boxcar(trace, smooth_win)
    else:
        return None

    if avg_smooth_win is not None and avg_smooth_win > 1:
        trace = _smooth_boxcar(trace, avg_smooth_win)
    return trace


def _normalize_fr_norm_denominator_mode(mode: str | None) -> str:
    mode_norm = str(mode or "zero").strip().lower()
    aliases = {
        "zero": "zero",
        "at_zero": "zero",
        "zero_point": "zero",
        "zero_then_peak": "zero_then_peak",
        "zero_or_peak": "zero_then_peak",
        "peak_fallback": "zero_then_peak",
    }
    if mode_norm not in aliases:
        raise ValueError("fr_norm_denominator_mode must be 'zero' or 'zero_then_peak'.")
    return aliases[mode_norm]


def _fr_norm_denominator_from_trace(
    trace: Any,
    zero_idx: int,
    *,
    mode: str = "zero",
) -> tuple[float, str]:
    arr = np.asarray(trace, dtype=float).reshape(-1) if trace is not None else np.array([], dtype=float)
    if arr.size == 0:
        return np.nan, "invalid"
    idx = int(zero_idx)
    zero_val = float(arr[idx]) if 0 <= idx < arr.size and np.isfinite(arr[idx]) else np.nan
    if np.isfinite(zero_val) and not np.isclose(zero_val, 0.0):
        return zero_val, "zero"
    if _normalize_fr_norm_denominator_mode(mode) == "zero_then_peak":
        finite = arr[np.isfinite(arr)]
        if finite.size > 0:
            peak_val = float(np.nanmax(finite))
            if np.isfinite(peak_val) and not np.isclose(peak_val, 0.0):
                return peak_val, "peak_fallback"
    return np.nan, "invalid"


def _plot_pooled_category_3col_on_axes(
    time_rel: np.ndarray,
    entries: list[dict[str, Any]],
    axes: np.ndarray,
    *,
    smooth_window: int | None = None,
    plot_trials: bool = True,
    trial_alpha: float = 0.2,
    trial_linewidth: float = 0.5,
    theta_ylim: tuple[float, float] | None = None,
    slow_ylim: tuple[float, float] | None = None,
    fr_ylim_scale: float = 1.2,
    ss_cs_ylim_scale: float = 1.2,
    xlim: tuple[float, float] = (-2, 2),
    title_prefix: str = "",
    set_row_labels: bool = True,
    rate_norm_denom_by_cell: dict[tuple[str, int] | tuple[str, int, str], float] | None = None,
    fr_row_ylim_max: float | None = None,
    ss_cs_row_ylim_max: float | None = None,
    show_ss_cs_legend: bool = True,
    min_traversals_per_type: int = 5,
    min_trials_per_column: int | None = None,
    x_label: str = "Time from max FR (s)",
    center_line_x: float = 0.0,
    align_all_peak_to_zero: bool = False,
    peak_align_window: tuple[float, float] = (-5.0, 5.0),
    avg_smooth_window: int | None = None,
    all_direction_key: str = "all",
    cw_direction_key: str = "cw",
    ccw_direction_key: str = "ccw",
    explicit_preferred_nonpreferred_keys: tuple[str, str] | list[str] | None = None,
    direction_titles: tuple[str, str, str] | list[str] = ("All", "Pref", "Non-pref"),
    fr_norm_reference_col: str = "all",
    fr_norm_denominator_mode: str = "zero",
    show_sem_shading: bool = True,
    show_column_counts_in_titles: bool = False,
    x_ticks: tuple[float, ...] | list[float] | np.ndarray | None = None,
) -> None:
    min_trav = int(min_traversals_per_type)
    if min_trav < 0:
        raise ValueError("min_traversals_per_type must be >= 0.")
    if min_trials_per_column is not None:
        min_col_req = int(min_trials_per_column)
        if min_col_req < 0:
            raise ValueError("min_trials_per_column must be >= 0.")
    else:
        min_col_req = min_trav
    n_time = len(time_rel)

    def _mean_sem(arr: np.ndarray | None) -> tuple[np.ndarray | None, np.ndarray | None]:
        if arr is None or arr.size == 0:
            return None, None
        mean = np.nanmean(arr, axis=0)
        sem = np.nanstd(arr, axis=0) / np.sqrt(arr.shape[0])
        return mean, sem

    avg_smooth_win = smooth_window if avg_smooth_window is None else avg_smooth_window
    zero_idx = int(np.argmin(np.abs(time_rel)))
    align_mask = (time_rel >= float(peak_align_window[0])) & (time_rel <= float(peak_align_window[1]))
    if not np.any(align_mask):
        align_mask = np.ones_like(time_rel, dtype=bool)
    all_key = str(all_direction_key).strip()
    cw_key = str(cw_direction_key).strip()
    ccw_key = str(ccw_direction_key).strip()
    if len(all_key) == 0 or len(cw_key) == 0 or len(ccw_key) == 0:
        raise ValueError("Direction keys cannot be empty.")
    if explicit_preferred_nonpreferred_keys is None:
        pref_fixed = None
        nonpref_fixed = None
    else:
        pref_nonpref = tuple(explicit_preferred_nonpreferred_keys)
        if len(pref_nonpref) != 2:
            raise ValueError("explicit_preferred_nonpreferred_keys must contain exactly two keys.")
        pref_fixed = str(pref_nonpref[0]).strip()
        nonpref_fixed = str(pref_nonpref[1]).strip()
        if len(pref_fixed) == 0 or len(nonpref_fixed) == 0:
            raise ValueError("Preferred/non-preferred direction keys cannot be empty.")
        if pref_fixed == nonpref_fixed:
            raise ValueError("Preferred and non-preferred direction keys must differ.")
    titles_in = tuple(direction_titles)
    if len(titles_in) != 3:
        raise ValueError("direction_titles must contain exactly three labels.")
    dir_titles = [str(titles_in[0]), str(titles_in[1]), str(titles_in[2])]
    ref_norm = str(fr_norm_reference_col).strip().lower()
    ref_aliases = {
        "all": "all",
        "combined": "all",
        "pref": "preferred",
        "preferred": "preferred",
        "nonpref": "nonpreferred",
        "non-pref": "nonpreferred",
        "nonpreferred": "nonpreferred",
        "non-preferred": "nonpreferred",
    }
    if ref_norm not in ref_aliases:
        raise ValueError("fr_norm_reference_col must be one of: 'all', 'preferred', or 'nonpreferred'.")
    ref_norm = ref_aliases[ref_norm]
    denom_mode = _normalize_fr_norm_denominator_mode(fr_norm_denominator_mode)
    trace_direction_keys = [all_key, cw_key, ccw_key]
    if pref_fixed is not None:
        trace_direction_keys.extend([pref_fixed, nonpref_fixed])
    trace_direction_keys = list(dict.fromkeys(trace_direction_keys))
    metric_keys = ["rate_stack", "ss_rate_stack", "cs_rate_stack", "theta_stack", "slow_stack"]
    denom_source_counts: dict[str, int] = {"zero": 0, "peak_fallback": 0, "external": 0, "invalid": 0}

    def _valid_plotted_trace(trace: Any) -> bool:
        if trace is None:
            return False
        arr = np.asarray(trace, dtype=float)
        return bool(arr.ndim == 1 and arr.size == n_time and np.any(np.isfinite(arr)))

    records = []
    for e in entries:
        cell_data = e.get("data")
        if cell_data is None:
            continue
        session = str(e.get("session", ""))
        cell_idx = int(e.get("cell_idx", -1))
        traces = {k: {} for k in trace_direction_keys}
        for base_dir in trace_direction_keys:
            for key in metric_keys:
                traces[base_dir][key] = _extract_cell_metric_trace(
                    cell_data,
                    base_dir,
                    key,
                    n_time,
                    smooth_window=smooth_window,
                    avg_smooth_window=avg_smooth_win,
                )

        if bool(align_all_peak_to_zero):
            # Match heatmap alignment behavior: alignment is based on the final
            # all-spike mean trace after both smoothing stages.
            all_rate_ref = _extract_cell_metric_trace(
                cell_data,
                all_key,
                "rate_stack",
                n_time,
                smooth_window=smooth_window,
                avg_smooth_window=avg_smooth_win,
            )
            if all_rate_ref is not None:
                all_rate_ref = np.asarray(all_rate_ref, dtype=float)
                if all_rate_ref.ndim == 1 and all_rate_ref.size == n_time and np.any(np.isfinite(all_rate_ref[align_mask])):
                    masked = np.where(align_mask, all_rate_ref, np.nan)
                    peak_idx = int(np.nanargmax(masked))
                    shift_bins = int(zero_idx - peak_idx)
                    if shift_bins != 0:
                        for base_dir in trace_direction_keys:
                            for key in metric_keys:
                                tr = traces[base_dir].get(key)
                                if tr is None:
                                    continue
                                tr = np.asarray(tr, dtype=float)
                                if tr.ndim == 1 and tr.size == n_time:
                                    traces[base_dir][key] = _shift_trace_with_nan(tr, shift_bins)

        all_rate = traces[all_key]["rate_stack"]
        cw_rate = traces[cw_key]["rate_stack"]
        ccw_rate = traces[ccw_key]["rate_stack"]
        all_zero = all_rate[zero_idx] if all_rate is not None else np.nan

        if pref_fixed is None:
            preferred_dir = _infer_preferred_direction_from_rate_traces(cw_rate, ccw_rate)
            if preferred_dir == "cw":
                preferred_dir_key = cw_key
                nonpreferred_dir_key = ccw_key
            elif preferred_dir == "ccw":
                preferred_dir_key = ccw_key
                nonpreferred_dir_key = cw_key
            else:
                preferred_dir_key = None
                nonpreferred_dir_key = None
        else:
            preferred_dir_key = str(pref_fixed)
            nonpreferred_dir_key = str(nonpref_fixed)

        if preferred_dir_key is None or nonpreferred_dir_key is None:
            continue
        plotted_direction_keys = [all_key, str(preferred_dir_key), str(nonpreferred_dir_key)]
        has_all_plotted_traces = all(
            _valid_plotted_trace(traces[direction_key].get(metric_key))
            for direction_key in plotted_direction_keys
            for metric_key in metric_keys
        )
        if not has_all_plotted_traces:
            continue

        # Gate inclusion so each kept cell has enough traversals in all 3 plotted types:
        # All, Preferred, Non-preferred.
        n_all_trials = int(cell_data.get(all_key, {}).get("n_trials", 0))
        n_pref_trials = int(cell_data.get(str(preferred_dir_key), {}).get("n_trials", 0))
        n_nonpref_trials = int(cell_data.get(str(nonpreferred_dir_key), {}).get("n_trials", 0))
        if (
            n_all_trials < min_col_req
            or n_pref_trials < min_col_req
            or n_nonpref_trials < min_col_req
        ):
            continue
        pref_rate = traces[str(preferred_dir_key)].get("rate_stack")
        nonpref_rate = traces[str(nonpreferred_dir_key)].get("rate_stack")
        ref_trace_by_col = {
            "all": all_rate,
            "preferred": pref_rate,
            "nonpreferred": nonpref_rate,
        }
        rate_zero_by_col = {
            "all": float(all_zero),
            "preferred": float(pref_rate[zero_idx]) if pref_rate is not None and np.size(pref_rate) > zero_idx else np.nan,
            "nonpreferred": float(nonpref_rate[zero_idx]) if nonpref_rate is not None and np.size(nonpref_rate) > zero_idx else np.nan,
        }
        rate_denom_by_col: dict[str, float] = {}
        rate_denom_source_by_col: dict[str, str] = {}
        for col_key, col_trace in ref_trace_by_col.items():
            denom_val, denom_source = _fr_norm_denominator_from_trace(
                col_trace,
                zero_idx,
                mode=denom_mode,
            )
            rate_denom_by_col[col_key] = float(denom_val) if np.isfinite(denom_val) else np.nan
            rate_denom_source_by_col[col_key] = str(denom_source)
        if rate_norm_denom_by_cell is not None:
            override = rate_norm_denom_by_cell.get((session, cell_idx, "all"))
            if override is None:
                override = rate_norm_denom_by_cell.get((session, cell_idx))
            if override is not None and np.isfinite(override) and not np.isclose(float(override), 0.0):
                rate_denom_by_col[ref_norm] = float(override)
                rate_denom_source_by_col[ref_norm] = "external"
        ref_denom_source = str(rate_denom_source_by_col.get(ref_norm, "invalid"))
        denom_source_counts[ref_denom_source] = int(denom_source_counts.get(ref_denom_source, 0)) + 1
        if ref_denom_source == "invalid":
            continue

        records.append(
            {
                "traces": traces,
                "all_rate_zero": all_zero,
                "rate_zero_by_col": rate_zero_by_col,
                "rate_denom_by_col": rate_denom_by_col,
                "rate_denom_source_by_col": rate_denom_source_by_col,
                "preferred_direction_key": preferred_dir_key,
                "nonpreferred_direction_key": nonpreferred_dir_key,
                "session": session,
                "cell_idx": cell_idx,
            }
        )

    def _collect_stack(column_key: str, metric_key: str, normalize_with_all: bool = False) -> np.ndarray | None:
        arrs = []
        for rec in records:
            if column_key == "all":
                trace = rec["traces"][all_key][metric_key]
            elif column_key == "preferred":
                pref = rec.get("preferred_direction_key")
                if pref is None:
                    continue
                trace = rec["traces"][pref][metric_key]
            else:
                nonpref = rec.get("nonpreferred_direction_key")
                if nonpref is None:
                    continue
                trace = rec["traces"][nonpref][metric_key]
            if trace is None:
                continue
            trace = np.asarray(trace, dtype=float)
            if trace.size != n_time:
                continue
            if normalize_with_all:
                # Row-1 normalization anchor.  Direction comparison can use
                # the first comparison column (preferred) to mirror the
                # two-session plot's session1 normalization.
                denom = float(rec.get("rate_denom_by_col", {}).get(ref_norm, rec["all_rate_zero"]))
                # Optional override for row-1 normalization (e.g., PF2 normalized by PF1 All FR).
                # Apply the same denominator override logic to all row-1/row-2 rate traces so
                # row 2 remains normalized by the exact row-1 denominator.
                if rate_norm_denom_by_cell is not None:
                    override = rate_norm_denom_by_cell.get((rec["session"], int(rec["cell_idx"]), "all"))
                    if override is None:
                        override = rate_norm_denom_by_cell.get((rec["session"], int(rec["cell_idx"])))
                    if override is not None and np.isfinite(override) and override != 0:
                        denom = float(override)
                if (not np.isfinite(denom)) or denom == 0:
                    continue
                trace = trace / denom
            arrs.append(trace)
        if len(arrs) == 0:
            return None
        return np.vstack(arrs)

    directions = ["all", "preferred", "nonpreferred"]
    all_rate_means, all_ss_means, all_cs_means = [], [], []
    n_cells_by_direction: dict[str, int] = {}

    for direction in directions:
        rate_norm = _collect_stack(direction, "rate_stack", normalize_with_all=True)
        ss_rate_norm = _collect_stack(direction, "ss_rate_stack", normalize_with_all=True)
        cs_rate_norm = _collect_stack(direction, "cs_rate_stack", normalize_with_all=True)
        rate_mean, _ = _mean_sem(rate_norm)
        ss_mean, _ = _mean_sem(ss_rate_norm)
        cs_mean, _ = _mean_sem(cs_rate_norm)
        if rate_mean is not None:
            all_rate_means.append(rate_mean)
        if ss_mean is not None:
            all_ss_means.append(ss_mean)
        if cs_mean is not None:
            all_cs_means.append(cs_mean)

    fr_max = max([np.nanmax(rm) for rm in all_rate_means]) if all_rate_means else 0
    fr_ylim_auto = (0, fr_max * fr_ylim_scale) if fr_max > 0 else None
    ss_cs_max = max([np.nanmax(m) for m in all_ss_means + all_cs_means]) if (all_ss_means or all_cs_means) else 0
    ss_cs_ylim_auto = (0, ss_cs_max * ss_cs_ylim_scale) if ss_cs_max > 0 else None

    for col, (direction, dir_title) in enumerate(zip(directions, dir_titles)):
        rate_norm = _collect_stack(direction, "rate_stack", normalize_with_all=True)
        ss_rate_norm = _collect_stack(direction, "ss_rate_stack", normalize_with_all=True)
        cs_rate_norm = _collect_stack(direction, "cs_rate_stack", normalize_with_all=True)
        theta = _collect_stack(direction, "theta_stack", normalize_with_all=False)
        slow = _collect_stack(direction, "slow_stack", normalize_with_all=False)

        rate_mean, rate_sem = _mean_sem(rate_norm)
        ss_mean, ss_sem = _mean_sem(ss_rate_norm)
        cs_mean, cs_sem = _mean_sem(cs_rate_norm)
        theta_mean, theta_sem = _mean_sem(theta)
        slow_mean, slow_sem = _mean_sem(slow)
        n_cells = rate_norm.shape[0] if rate_norm is not None else 0
        n_cells_by_direction[direction] = int(n_cells)
        if plot_trials and rate_norm is not None:
            for i in range(rate_norm.shape[0]):
                axes[0, col].plot(time_rel, rate_norm[i], color="#555555", linewidth=trial_linewidth, alpha=trial_alpha)
        if plot_trials and cs_rate_norm is not None:
            for i in range(cs_rate_norm.shape[0]):
                axes[1, col].plot(time_rel, cs_rate_norm[i], color="#EE9B00", linewidth=trial_linewidth, alpha=trial_alpha)
        if plot_trials and ss_rate_norm is not None:
            for i in range(ss_rate_norm.shape[0]):
                axes[1, col].plot(time_rel, ss_rate_norm[i], color="#026C80", linewidth=trial_linewidth, alpha=trial_alpha)
        if plot_trials and theta is not None:
            for i in range(theta.shape[0]):
                axes[2, col].plot(time_rel, theta[i], color="blue", linewidth=trial_linewidth, alpha=trial_alpha)
        if plot_trials and slow is not None:
            for i in range(slow.shape[0]):
                axes[3, col].plot(time_rel, slow[i], color="red", linewidth=trial_linewidth, alpha=trial_alpha)

        if rate_mean is not None:
            axes[0, col].plot(time_rel, rate_mean, color="#555555", linewidth=1.0)
            if bool(show_sem_shading):
                axes[0, col].fill_between(time_rel, rate_mean - rate_sem, rate_mean + rate_sem, color="#555555", alpha=0.2)
        axes[0, col].axvline(center_line_x, color="black", linewidth=0.4, linestyle="--", alpha=0.6)
        column_title = f"{dir_title} (n={int(n_cells)})" if bool(show_column_counts_in_titles) else f"{dir_title}"
        axes[0, col].set_title(column_title, fontsize=6)

        if cs_mean is not None:
            axes[1, col].plot(time_rel, cs_mean, color="#EE9B00", linewidth=1.0, label="CS")
            if bool(show_sem_shading):
                axes[1, col].fill_between(time_rel, cs_mean - cs_sem, cs_mean + cs_sem, color="#EE9B00", alpha=0.2)
        if ss_mean is not None:
            axes[1, col].plot(time_rel, ss_mean, color="#026C80", linewidth=1.0, label="SS")
            if bool(show_sem_shading):
                axes[1, col].fill_between(time_rel, ss_mean - ss_sem, ss_mean + ss_sem, color="#026C80", alpha=0.2)
        axes[1, col].axvline(center_line_x, color="black", linewidth=0.4, linestyle="--", alpha=0.6)
        if col == 0 and show_ss_cs_legend:
            axes[1, col].legend(fontsize=5, frameon=False, loc="upper right")

        if theta_mean is not None:
            axes[2, col].plot(time_rel, theta_mean, color="blue", linewidth=1.0)
            if bool(show_sem_shading):
                axes[2, col].fill_between(time_rel, theta_mean - theta_sem, theta_mean + theta_sem, color="blue", alpha=0.2)
        axes[2, col].axvline(center_line_x, color="black", linewidth=0.4, linestyle="--", alpha=0.6)

        if slow_mean is not None:
            axes[3, col].plot(time_rel, slow_mean, color="red", linewidth=1.0)
            if bool(show_sem_shading):
                axes[3, col].fill_between(time_rel, slow_mean - slow_sem, slow_mean + slow_sem, color="red", alpha=0.2)
        axes[3, col].axvline(center_line_x, color="black", linewidth=0.4, linestyle="--", alpha=0.6)
        axes[3, col].axhline(0, color="black", linewidth=0.4, linestyle="--", alpha=0.6)

    label = str(title_prefix).strip()
    if label:
        print(
            f"{label} counts: "
            f"All (n={n_cells_by_direction.get('all', 0)}), "
            f"Pref (n={n_cells_by_direction.get('preferred', 0)}), "
            f"Non-pref (n={n_cells_by_direction.get('nonpreferred', 0)})"
        )
        print(
            f"{label} FR norm denominator mode={denom_mode}: "
            f"zero={int(denom_source_counts.get('zero', 0))}, "
            f"peak fallback={int(denom_source_counts.get('peak_fallback', 0))}, "
            f"external={int(denom_source_counts.get('external', 0))}, "
            f"invalid/skipped={int(denom_source_counts.get('invalid', 0))}"
        )
    else:
        print(
            f"Counts: "
            f"All (n={n_cells_by_direction.get('all', 0)}), "
            f"Pref (n={n_cells_by_direction.get('preferred', 0)}), "
            f"Non-pref (n={n_cells_by_direction.get('nonpreferred', 0)})"
        )
        print(
            f"FR norm denominator mode={denom_mode}: "
            f"zero={int(denom_source_counts.get('zero', 0))}, "
            f"peak fallback={int(denom_source_counts.get('peak_fallback', 0))}, "
            f"external={int(denom_source_counts.get('external', 0))}, "
            f"invalid/skipped={int(denom_source_counts.get('invalid', 0))}"
        )

    if set_row_labels:
        axes[0, 0].set_ylabel("Norm. FR")
        axes[1, 0].set_ylabel("Norm. FR")
        axes[2, 0].set_ylabel("Theta amp.")
        axes[3, 0].set_ylabel("Slow Vm")
    for col in range(3):
        axes[3, col].set_xlabel(x_label)

    if fr_ylim_auto is not None:
        for col in range(3):
            axes[0, col].set_ylim(fr_ylim_auto)
    if fr_row_ylim_max is not None:
        for col in range(3):
            axes[0, col].set_ylim(0, float(fr_row_ylim_max))
    if ss_cs_row_ylim_max is not None:
        for col in range(3):
            axes[1, col].set_ylim(0.0, float(ss_cs_row_ylim_max))
    else:
        for col in range(3):
            axes[1, col].set_ylim(axes[0, col].get_ylim())
    if theta_ylim is not None:
        for col in range(3):
            axes[2, col].set_ylim(theta_ylim)
    if slow_ylim is not None:
        for col in range(3):
            axes[3, col].set_ylim(slow_ylim)
    for ax in axes.flat:
        ax.spines["top"].set_visible(False)
        ax.spines["right"].set_visible(False)
        ax.set_xlim(xlim)
        if x_ticks is not None:
            ax.set_xticks(np.asarray(x_ticks, dtype=float))


def plot_pooled_category_3col(
    time_rel: np.ndarray,
    entries: list[dict[str, Any]],
    title: str,
    *,
    out_path: str | Path | None = None,
    smooth_window: int | None = None,
    plot_trials: bool = True,
    trial_alpha: float = 0.2,
    trial_linewidth: float = 0.5,
    theta_ylim: tuple[float, float] | None = None,
    slow_ylim: tuple[float, float] | None = None,
    fr_ylim_scale: float = 1.2,
    ss_cs_ylim_scale: float = 1.2,
    figsize: tuple[float, float] = (4, 2.5),
    xlim: tuple[float, float] = (-2, 2),
    fr_row_ylim_max: float | None = None,
    ss_cs_row_ylim_max: float | None = None,
    min_traversals_per_type: int = 5,
    min_trials_per_column: int | None = None,
    x_label: str = "Time from max FR (s)",
    center_line_x: float = 0.0,
    align_all_peak_to_zero: bool = False,
    peak_align_window: tuple[float, float] = (-5.0, 5.0),
    avg_smooth_window: int | None = None,
    all_direction_key: str = "all",
    cw_direction_key: str = "cw",
    ccw_direction_key: str = "ccw",
    explicit_preferred_nonpreferred_keys: tuple[str, str] | list[str] | None = None,
    direction_titles: tuple[str, str, str] | list[str] = ("All", "Pref", "Non-pref"),
    fr_norm_reference_col: str = "all",
    fr_norm_denominator_mode: str = "zero",
    rate_norm_denom_by_cell: dict[tuple[str, int] | tuple[str, int, str], float] | None = None,
    show_sem_shading: bool = True,
    show_column_counts_in_titles: bool = False,
    x_ticks: tuple[float, ...] | list[float] | np.ndarray | None = None,
    show_plot: bool = True,
    close_on_return: bool = True,
) -> plt.Figure | None:
    if time_rel is None or len(entries) == 0:
        print(f"No data to plot for {title}")
        return None
    fig, axes = plt.subplots(4, 3, figsize=figsize, sharex="all", sharey="row")
    _plot_pooled_category_3col_on_axes(
        np.asarray(time_rel, dtype=float),
        entries,
        axes,
        smooth_window=smooth_window,
        plot_trials=plot_trials,
        trial_alpha=trial_alpha,
        trial_linewidth=trial_linewidth,
        theta_ylim=theta_ylim,
        slow_ylim=slow_ylim,
        fr_ylim_scale=fr_ylim_scale,
        ss_cs_ylim_scale=ss_cs_ylim_scale,
        xlim=xlim,
        title_prefix="",
        set_row_labels=True,
        fr_row_ylim_max=fr_row_ylim_max,
        ss_cs_row_ylim_max=ss_cs_row_ylim_max,
        min_traversals_per_type=min_traversals_per_type,
        min_trials_per_column=min_trials_per_column,
        x_label=x_label,
        center_line_x=center_line_x,
        align_all_peak_to_zero=align_all_peak_to_zero,
        peak_align_window=peak_align_window,
        avg_smooth_window=avg_smooth_window,
        all_direction_key=all_direction_key,
        cw_direction_key=cw_direction_key,
        ccw_direction_key=ccw_direction_key,
        explicit_preferred_nonpreferred_keys=explicit_preferred_nonpreferred_keys,
        direction_titles=direction_titles,
        fr_norm_reference_col=fr_norm_reference_col,
        fr_norm_denominator_mode=fr_norm_denominator_mode,
        rate_norm_denom_by_cell=rate_norm_denom_by_cell,
        show_sem_shading=show_sem_shading,
        show_column_counts_in_titles=show_column_counts_in_titles,
        x_ticks=x_ticks,
    )
    fig.suptitle(f"{title}", y=0.98)
    try:
        tight_fn = getattr(fig, "tight_layout", None)
        if callable(tight_fn):
            tight_fn(rect=[0, 0, 1, 0.96])
    except Exception:
        pass
    if out_path is not None:
        fig.savefig(out_path, dpi=300)
    if show_plot:
        plt.show()
    elif close_on_return:
        plt.close(fig)
    return fig


def plot_pooled_category_primary_secondary(
    time_rel_primary: np.ndarray,
    entries_primary: list[dict[str, Any]],
    time_rel_secondary: np.ndarray | None,
    entries_secondary: list[dict[str, Any]] | None,
    title: str,
    *,
    out_path: str | Path | None = None,
    smooth_window: int | None = None,
    plot_trials: bool = True,
    trial_alpha: float = 0.2,
    trial_linewidth: float = 0.5,
    theta_ylim: tuple[float, float] | None = None,
    slow_ylim: tuple[float, float] | None = None,
    fr_ylim_scale: float = 1.2,
    ss_cs_ylim_scale: float = 1.2,
    figsize_per_block: tuple[float, float] = (3.4, 3.0),
    xlim: tuple[float, float] = (-2, 2),
    fr_row_ylim_max: float | None = 1.2,
    ss_cs_row_ylim_max: float | None = None,
    min_traversals_per_type: int = 5,
    min_trials_per_column: int | None = None,
    x_label: str = "Time from max FR (s)",
    center_line_x: float = 0.0,
    align_all_peak_to_zero: bool = False,
    peak_align_window: tuple[float, float] = (-5.0, 5.0),
    avg_smooth_window: int | None = None,
    all_direction_key: str = "all",
    cw_direction_key: str = "cw",
    ccw_direction_key: str = "ccw",
    explicit_preferred_nonpreferred_keys: tuple[str, str] | list[str] | None = None,
    direction_titles: tuple[str, str, str] | list[str] = ("All", "Pref", "Non-pref"),
    fr_norm_reference_col: str = "all",
    fr_norm_denominator_mode: str = "zero",
    rate_norm_denom_by_cell: dict[tuple[str, int] | tuple[str, int, str], float] | None = None,
    show_sem_shading: bool = True,
    show_column_counts_in_titles: bool = False,
    x_ticks: tuple[float, ...] | list[float] | np.ndarray | None = None,
    show_plot: bool = True,
    close_on_return: bool = True,
) -> plt.Figure | None:
    if time_rel_primary is None or len(entries_primary) == 0:
        print(f"No primary PF data to plot for {title}")
        return None
    has_secondary = time_rel_secondary is not None and entries_secondary is not None and len(entries_secondary) > 0
    if not has_secondary:
        return plot_pooled_category_3col(
            time_rel=np.asarray(time_rel_primary, dtype=float),
            entries=entries_primary,
            title=title,
            out_path=out_path,
            smooth_window=smooth_window,
            plot_trials=plot_trials,
            trial_alpha=trial_alpha,
            trial_linewidth=trial_linewidth,
            theta_ylim=theta_ylim,
            slow_ylim=slow_ylim,
            fr_ylim_scale=fr_ylim_scale,
            ss_cs_ylim_scale=ss_cs_ylim_scale,
            figsize=figsize_per_block,
            xlim=xlim,
            fr_row_ylim_max=fr_row_ylim_max,
            ss_cs_row_ylim_max=ss_cs_row_ylim_max,
            min_traversals_per_type=min_traversals_per_type,
            min_trials_per_column=min_trials_per_column,
            x_label=x_label,
            center_line_x=center_line_x,
            align_all_peak_to_zero=align_all_peak_to_zero,
            peak_align_window=peak_align_window,
            avg_smooth_window=avg_smooth_window,
            all_direction_key=all_direction_key,
            cw_direction_key=cw_direction_key,
            ccw_direction_key=ccw_direction_key,
            explicit_preferred_nonpreferred_keys=explicit_preferred_nonpreferred_keys,
            direction_titles=direction_titles,
            fr_norm_reference_col=fr_norm_reference_col,
            fr_norm_denominator_mode=fr_norm_denominator_mode,
            rate_norm_denom_by_cell=rate_norm_denom_by_cell,
            show_sem_shading=show_sem_shading,
            show_column_counts_in_titles=show_column_counts_in_titles,
            x_ticks=x_ticks,
            show_plot=show_plot,
            close_on_return=close_on_return,
        )

    # Build PF1 denominator map for PF2 row-1 normalization, using the same
    # reference column as PF1.  This mirrors the two-session plot where PF2 is
    # normalized by the PF1 value from the selected reference column.
    denom_map: dict[tuple[str, int] | tuple[str, int, str], float] = {}
    time_rel_primary = np.asarray(time_rel_primary, dtype=float)
    zero_idx = int(np.argmin(np.abs(time_rel_primary)))
    ref_norm = str(fr_norm_reference_col).strip().lower()
    ref_aliases = {
        "all": "all",
        "combined": "all",
        "pref": "preferred",
        "preferred": "preferred",
        "nonpref": "nonpreferred",
        "non-pref": "nonpreferred",
        "nonpreferred": "nonpreferred",
        "non-preferred": "nonpreferred",
    }
    if ref_norm not in ref_aliases:
        raise ValueError("fr_norm_reference_col must be one of: 'all', 'preferred', or 'nonpreferred'.")
    ref_norm = ref_aliases[ref_norm]

    for entry in entries_primary:
        session = str(entry.get("session", ""))
        cell_idx = int(entry.get("cell_idx", -1))
        if not session or cell_idx < 0:
            continue
        cell_data = entry.get("data", {})
        cw_tr = _extract_cell_metric_trace(
            cell_data,
            str(cw_direction_key),
            "rate_stack",
            len(time_rel_primary),
            smooth_window=smooth_window,
            avg_smooth_window=(smooth_window if avg_smooth_window is None else avg_smooth_window),
        )
        ccw_tr = _extract_cell_metric_trace(
            cell_data,
            str(ccw_direction_key),
            "rate_stack",
            len(time_rel_primary),
            smooth_window=smooth_window,
            avg_smooth_window=(smooth_window if avg_smooth_window is None else avg_smooth_window),
        )
        if explicit_preferred_nonpreferred_keys is not None:
            pref_nonpref = tuple(explicit_preferred_nonpreferred_keys)
            pref_key = str(pref_nonpref[0]).strip() if len(pref_nonpref) >= 1 else None
            nonpref_key = str(pref_nonpref[1]).strip() if len(pref_nonpref) >= 2 else None
        else:
            preferred_dir = _infer_preferred_direction_from_rate_traces(cw_tr, ccw_tr)
            if preferred_dir == "cw":
                pref_key = str(cw_direction_key)
                nonpref_key = str(ccw_direction_key)
            elif preferred_dir == "ccw":
                pref_key = str(ccw_direction_key)
                nonpref_key = str(cw_direction_key)
            else:
                pref_key = None
                nonpref_key = None
        if ref_norm == "preferred":
            ref_key = pref_key
        elif ref_norm == "nonpreferred":
            ref_key = nonpref_key
        else:
            ref_key = str(all_direction_key)
        if ref_key is None:
            continue
        ref_tr = _extract_cell_metric_trace(
            cell_data,
            ref_key,
            "rate_stack",
            len(time_rel_primary),
            smooth_window=smooth_window,
            avg_smooth_window=(smooth_window if avg_smooth_window is None else avg_smooth_window),
        )
        denom_val, _ = _fr_norm_denominator_from_trace(
            ref_tr,
            zero_idx,
            mode=fr_norm_denominator_mode,
        )
        if np.isfinite(denom_val) and not np.isclose(float(denom_val), 0.0):
            denom_map[(session, cell_idx, "all")] = float(denom_val)
            denom_map[(session, cell_idx)] = float(denom_val)
    if rate_norm_denom_by_cell is not None:
        # External denominators are used when another analysis defines the
        # normalization anchor.  For example, time-centered direction grand
        # averages can use the exact distance-centered PF1 denominator.
        for key, value in dict(rate_norm_denom_by_cell).items():
            try:
                val = float(value)
            except Exception:
                continue
            if np.isfinite(val) and not np.isclose(val, 0.0):
                denom_map[key] = val

    fig, axes = plt.subplots(
        4,
        6,
        figsize=(figsize_per_block[0] * 2, figsize_per_block[1]),
        sharex="all",
        sharey="row",
    )
    _plot_pooled_category_3col_on_axes(
        np.asarray(time_rel_primary, dtype=float),
        entries_primary,
        axes[:, :3],
        smooth_window=smooth_window,
        plot_trials=plot_trials,
        trial_alpha=trial_alpha,
        trial_linewidth=trial_linewidth,
        theta_ylim=theta_ylim,
        slow_ylim=slow_ylim,
        fr_ylim_scale=fr_ylim_scale,
        ss_cs_ylim_scale=ss_cs_ylim_scale,
        xlim=xlim,
        title_prefix="PF1 ",
        set_row_labels=True,
        fr_row_ylim_max=fr_row_ylim_max,
        ss_cs_row_ylim_max=ss_cs_row_ylim_max,
        show_ss_cs_legend=True,
        min_traversals_per_type=min_traversals_per_type,
        min_trials_per_column=min_trials_per_column,
        x_label=x_label,
        center_line_x=center_line_x,
        align_all_peak_to_zero=align_all_peak_to_zero,
        peak_align_window=peak_align_window,
        avg_smooth_window=avg_smooth_window,
        all_direction_key=all_direction_key,
        cw_direction_key=cw_direction_key,
        ccw_direction_key=ccw_direction_key,
        explicit_preferred_nonpreferred_keys=explicit_preferred_nonpreferred_keys,
        direction_titles=direction_titles,
        fr_norm_reference_col=fr_norm_reference_col,
        fr_norm_denominator_mode=fr_norm_denominator_mode,
        rate_norm_denom_by_cell=rate_norm_denom_by_cell,
        show_sem_shading=show_sem_shading,
        show_column_counts_in_titles=show_column_counts_in_titles,
        x_ticks=x_ticks,
    )
    _plot_pooled_category_3col_on_axes(
        np.asarray(time_rel_secondary, dtype=float),
        entries_secondary,
        axes[:, 3:],
        smooth_window=smooth_window,
        plot_trials=plot_trials,
        trial_alpha=trial_alpha,
        trial_linewidth=trial_linewidth,
        theta_ylim=theta_ylim,
        slow_ylim=slow_ylim,
        fr_ylim_scale=fr_ylim_scale,
        ss_cs_ylim_scale=ss_cs_ylim_scale,
        xlim=xlim,
        title_prefix="PF2 ",
        set_row_labels=False,
        rate_norm_denom_by_cell=denom_map,
        fr_row_ylim_max=fr_row_ylim_max,
        ss_cs_row_ylim_max=ss_cs_row_ylim_max,
        show_ss_cs_legend=False,
        min_traversals_per_type=min_traversals_per_type,
        min_trials_per_column=min_trials_per_column,
        x_label=x_label,
        center_line_x=center_line_x,
        align_all_peak_to_zero=align_all_peak_to_zero,
        peak_align_window=peak_align_window,
        avg_smooth_window=avg_smooth_window,
        all_direction_key=all_direction_key,
        cw_direction_key=cw_direction_key,
        ccw_direction_key=ccw_direction_key,
        explicit_preferred_nonpreferred_keys=explicit_preferred_nonpreferred_keys,
        direction_titles=direction_titles,
        fr_norm_reference_col=fr_norm_reference_col,
        fr_norm_denominator_mode=fr_norm_denominator_mode,
        show_sem_shading=show_sem_shading,
        show_column_counts_in_titles=show_column_counts_in_titles,
        x_ticks=x_ticks,
    )
    fig.suptitle(f"{title}", y=0.999)
    try:
        tight_fn = getattr(fig, "tight_layout", None)
        if callable(tight_fn):
            tight_fn(rect=[0, 0, 1, 0.98])
    except Exception:
        pass

    if out_path is not None:
        fig.savefig(out_path, dpi=300)
    if show_plot:
        plt.show()
    elif close_on_return:
        plt.close(fig)
    return fig


def plot_pf_centered_category_primary_secondary_from_dataset(
    dataset: dict[str, Any],
    category: str,
    *,
    title: str,
    out_path: str | Path,
    smooth_window: int | None = 400,
    avg_smooth_window: int | None = None,
    plot_trials: bool = True,
    trial_alpha: float = 0.2,
    trial_linewidth: float = 0.5,
    theta_ylim: tuple[float, float] | None = (-0.02, 0.1),
    slow_ylim: tuple[float, float] | None = (-0.05, 0.2),
    fr_ylim_scale: float = 1.2,
    ss_cs_ylim_scale: float = 1.2,
    figsize_per_block: tuple[float, float] = (3.4, 3.0),
    xlim: tuple[float, float] = (-4, 4),
    fr_row_ylim_max: float | None = 1.2,
    ss_cs_row_ylim_max: float | None = None,
    min_traversals_per_type: int = 5,
    x_label: str = "Time from max FR (s)",
    center_line_x: float = 0.0,
    show_plot: bool = True,
) -> plt.Figure | None:
    cat = _normalize_pf_category_name(category)
    cat_data = dataset.get(cat, {})
    primary = cat_data.get(1, {})
    secondary = cat_data.get(2, {})
    # Keep height unchanged, but make output width half of the previous block width.
    figsize_per_block_scaled = (float(figsize_per_block[0]) * 0.5, float(figsize_per_block[1]))
    return plot_pooled_category_primary_secondary(
        time_rel_primary=np.asarray(primary.get("time_rel", []), dtype=float),
        entries_primary=list(primary.get("entries", [])),
        time_rel_secondary=np.asarray(secondary.get("time_rel", []), dtype=float)
        if secondary.get("time_rel") is not None
        else None,
        entries_secondary=list(secondary.get("entries", [])),
        title=title,
        out_path=out_path,
        smooth_window=smooth_window,
        plot_trials=plot_trials,
        trial_alpha=trial_alpha,
        trial_linewidth=trial_linewidth,
        theta_ylim=theta_ylim,
        slow_ylim=slow_ylim,
        fr_ylim_scale=fr_ylim_scale,
        ss_cs_ylim_scale=ss_cs_ylim_scale,
        figsize_per_block=figsize_per_block_scaled,
        xlim=xlim,
        fr_row_ylim_max=fr_row_ylim_max,
        ss_cs_row_ylim_max=ss_cs_row_ylim_max,
        min_traversals_per_type=min_traversals_per_type,
        x_label=x_label,
        center_line_x=center_line_x,
        avg_smooth_window=avg_smooth_window,
        show_plot=show_plot,
    )


def _shift_distance_centered_entry_for_peak_alignment(
    entry: dict[str, Any],
    distance_rel: np.ndarray,
    *,
    smooth_window: int | None,
    avg_smooth_window: int | None,
    peak_align_window: tuple[float, float],
    reference_session: str | int | None = None,
) -> dict[str, Any]:
    out = dict(entry)
    data_in = dict(entry.get("data", {}))
    distance_rel = np.asarray(distance_rel, dtype=float)
    n_time = int(distance_rel.size)
    zero_idx = int(np.argmin(np.abs(distance_rel)))
    align_mask = (distance_rel >= float(peak_align_window[0])) & (distance_rel <= float(peak_align_window[1]))
    if not np.any(align_mask):
        align_mask = np.ones_like(distance_rel, dtype=bool)

    all_dir = dict(data_in.get("all", {}))
    ref_stack = all_dir.get("rate_stack")
    if ref_stack is None:
        out["_peak_align_shift_cm"] = 0.0
        out["data"] = data_in
        return out
    ref_arr = np.asarray(ref_stack, dtype=float)
    if ref_arr.ndim == 2:
        if ref_arr.shape[1] != n_time:
            out["_peak_align_shift_cm"] = 0.0
            out["data"] = data_in
            return out
        ref_arr_use = ref_arr
        if reference_session is not None:
            td = all_dir.get("trial_data", {}) if isinstance(all_dir, dict) else {}
            sess = np.asarray(td.get("session_idx", []), dtype=int) if isinstance(td, dict) else np.array([], dtype=int)
            if sess.ndim == 1 and sess.size == int(ref_arr.shape[0]) and sess.size > 0:
                mask = None
                if isinstance(reference_session, str):
                    rs = str(reference_session).strip().lower()
                    s1_named, s2_named = _resolve_two_session_label_values(sess)
                    if rs in {"session1", "s1", "first"}:
                        if s1_named is not None:
                            mask = sess == int(s1_named)
                    elif rs in {"session2", "s2", "second"}:
                        if s2_named is not None:
                            mask = sess == int(s2_named)
                    else:
                        try:
                            s_val = int(float(rs))
                            mask = sess == int(s_val)
                        except (TypeError, ValueError):
                            mask = None
                else:
                    try:
                        s_val = int(reference_session)
                        mask = sess == int(s_val)
                    except (TypeError, ValueError):
                        mask = None
                if mask is not None and np.any(mask):
                    ref_arr_use = ref_arr[mask]
        # Keep peak alignment logic consistent with plotted averages:
        # 1) smooth each trial trace, 2) average across trials, 3) optional avg smoothing.
        if smooth_window is not None and int(smooth_window) > 1:
            ref_arr_sm = np.full_like(ref_arr_use, np.nan)
            for i in range(ref_arr_use.shape[0]):
                ref_arr_sm[i] = _smooth_boxcar(ref_arr_use[i], int(smooth_window))
            ref_arr_use = ref_arr_sm
        ref_trace = np.nanmean(ref_arr_use, axis=0)
        if avg_smooth_window is not None and int(avg_smooth_window) > 1:
            ref_trace = _smooth_boxcar(ref_trace, int(avg_smooth_window))
    elif ref_arr.ndim == 1:
        if ref_arr.size != n_time:
            out["_peak_align_shift_cm"] = 0.0
            out["data"] = data_in
            return out
        ref_trace = ref_arr.copy()
        # Fallback path for pre-collapsed traces (no trial axis available).
        if smooth_window is not None and int(smooth_window) > 1:
            ref_trace = _smooth_boxcar(ref_trace, int(smooth_window))
        if avg_smooth_window is not None and int(avg_smooth_window) > 1:
            ref_trace = _smooth_boxcar(ref_trace, int(avg_smooth_window))
    else:
        out["_peak_align_shift_cm"] = 0.0
        out["data"] = data_in
        return out
    if not np.any(np.isfinite(ref_trace[align_mask])):
        out["_peak_align_shift_cm"] = 0.0
        out["data"] = data_in
        return out
    peak_idx = int(np.nanargmax(np.where(align_mask, ref_trace, np.nan)))
    shift_bins = int(zero_idx - peak_idx)
    shift_cm = float(shift_bins) * float(distance_rel[1] - distance_rel[0]) if n_time > 1 else 0.0
    out["_peak_align_shift_cm"] = shift_cm
    if shift_bins == 0:
        out["data"] = data_in
        return out

    shift_keys = [
        "rate_stack",
        "ss_rate_stack",
        "cs_rate_stack",
        "theta_stack",
        "slow_stack",
        "plateau_stack",
        "rate_mean",
        "ss_rate_mean",
        "cs_rate_mean",
        "theta_mean",
        "slow_mean",
        "ss_pct_mean",
        "cs_pct_mean",
    ]
    data_out: dict[str, Any] = {}
    for dir_key, dir_data_in in data_in.items():
        if not isinstance(dir_data_in, dict):
            data_out[dir_key] = dir_data_in
            continue
        dir_data_out = dict(dir_data_in)
        for key in shift_keys:
            arr = dir_data_in.get(key)
            if arr is None:
                continue
            arr = np.asarray(arr, dtype=float)
            if arr.ndim == 1 and arr.size == n_time:
                dir_data_out[key] = _shift_trace_with_nan(arr, shift_bins)
            elif arr.ndim == 2 and arr.shape[1] == n_time:
                shifted = np.full_like(arr, np.nan)
                for i in range(arr.shape[0]):
                    shifted[i] = _shift_trace_with_nan(arr[i], shift_bins)
                dir_data_out[key] = shifted
        data_out[dir_key] = dir_data_out
    out["data"] = data_out
    return out


def _normalize_two_session_split_mode(split_mode: str | None) -> str:
    token = str("recorded_sessions" if split_mode is None else split_mode).strip().lower()
    aliases = {
        "recorded_sessions": "recorded_sessions",
        "recorded": "recorded_sessions",
        "sessions": "recorded_sessions",
        "native_sessions": "recorded_sessions",
        "time_windows": "time_windows",
        "time_window": "time_windows",
        "windows": "time_windows",
        "fixed_windows": "time_windows",
        "prepost_plateau": "prepost_plateau",
        "pre_post_plateau": "prepost_plateau",
        "plateau": "prepost_plateau",
        "plateau_split": "prepost_plateau",
    }
    if token not in aliases:
        raise ValueError("split_mode must be 'recorded_sessions', 'time_windows', or 'prepost_plateau'.")
    return aliases[token]


def _normalize_two_phase_labels(
    phase_labels: tuple[str, str] | list[str] | None = None,
    *,
    split_mode: str = "recorded_sessions",
) -> tuple[str, str]:
    if phase_labels is None:
        mode = _normalize_two_session_split_mode(split_mode)
        if mode == "prepost_plateau":
            return "Pre plateau", "Post plateau"
        return "Session 1", "Session 2"
    labels = tuple(str(v).strip() for v in phase_labels)
    if len(labels) != 2 or any(len(v) == 0 for v in labels):
        raise ValueError("phase_labels must contain exactly two non-empty labels.")
    return labels[0], labels[1]


def _two_phase_count_labels(phase_labels: tuple[str, str] | list[str] | None = None, *, split_mode: str = "recorded_sessions") -> tuple[str, str]:
    labels = _normalize_two_phase_labels(phase_labels, split_mode=split_mode)
    mode = _normalize_two_session_split_mode(split_mode)
    if mode == "prepost_plateau" or labels == ("Pre plateau", "Post plateau"):
        return "pre", "post"
    return "S1", "S2"


def _validate_plateau_split_min_traversals_per_phase(value: int | float | None) -> int:
    min_val = 5 if value is None else int(value)
    if min_val < 0:
        raise ValueError("plateau_split_min_traversals_per_phase must be >= 0.")
    return int(min_val)


def _validate_plateau_split_excluded_traversals(value: int | float | None) -> int:
    excl = 0 if value is None else int(value)
    if excl < 0:
        raise ValueError("plateau_split_excluded_traversals must be >= 0.")
    return int(excl)


def _validate_two_session_split_window_minutes(
    split_mode: str,
    split_window_minutes: float | None,
) -> float | None:
    mode = _normalize_two_session_split_mode(split_mode)
    if mode != "time_windows":
        return None
    if split_window_minutes is None:
        raise ValueError("split_window_minutes is required when split_mode='time_windows'.")
    window_min = float(split_window_minutes)
    if (not np.isfinite(window_min)) or window_min <= 0:
        raise ValueError("split_window_minutes must be a finite number > 0.")
    return window_min


def _resolve_two_session_label_values(session_idx: np.ndarray) -> tuple[int | None, int | None]:
    sess = np.asarray(session_idx, dtype=int).reshape(-1)
    uniq = np.sort(np.unique(sess.astype(int)))
    if uniq.size == 0:
        return None, None
    if np.all(np.isin(uniq, np.array([0, 1], dtype=int))):
        return 0, 1
    return int(uniq[0]), (int(uniq[1]) if uniq.size > 1 else None)


def _two_session_split_metadata(
    *,
    split_mode: str,
    split_window_minutes: float | None,
    plateau_split_min_traversals_per_phase: int | None = None,
    plateau_split_excluded_traversals: int | None = None,
) -> dict[str, Any]:
    mode = _normalize_two_session_split_mode(split_mode)
    window_min = _validate_two_session_split_window_minutes(mode, split_window_minutes)
    if mode == "time_windows":
        window_sec = float(window_min) * 60.0
        return {
            "split_mode": mode,
            "split_window_minutes": float(window_min),
            "window1_start_sec": 0.0,
            "window1_end_sec": float(window_sec),
            "window2_start_sec": float(window_sec),
            "window2_end_sec": float(window_sec * 2.0),
            "plateau_split_min_traversals_per_phase": np.nan,
            "plateau_split_excluded_traversals": np.nan,
        }
    if mode == "prepost_plateau":
        return {
            "split_mode": mode,
            "split_window_minutes": np.nan,
            "window1_start_sec": np.nan,
            "window1_end_sec": np.nan,
            "window2_start_sec": np.nan,
            "window2_end_sec": np.nan,
            "plateau_split_min_traversals_per_phase": int(_validate_plateau_split_min_traversals_per_phase(plateau_split_min_traversals_per_phase)),
            "plateau_split_excluded_traversals": int(_validate_plateau_split_excluded_traversals(plateau_split_excluded_traversals)),
        }
    return {
        "split_mode": mode,
        "split_window_minutes": np.nan,
        "window1_start_sec": np.nan,
        "window1_end_sec": np.nan,
        "window2_start_sec": np.nan,
        "window2_end_sec": np.nan,
        "plateau_split_min_traversals_per_phase": np.nan,
        "plateau_split_excluded_traversals": np.nan,
    }


def _export_matches_two_session_split(
    row: dict[str, Any] | None,
    npz_obj: Any,
    *,
    split_mode: str,
    split_window_minutes: float | None,
    plateau_split_min_traversals_per_phase: int | None = None,
    plateau_split_excluded_traversals: int | None = None,
) -> bool:
    expected = _two_session_split_metadata(
        split_mode=split_mode,
        split_window_minutes=split_window_minutes,
        plateau_split_min_traversals_per_phase=plateau_split_min_traversals_per_phase,
        plateau_split_excluded_traversals=plateau_split_excluded_traversals,
    )

    def _scalar_from_sources(key: str) -> Any:
        if row is not None and key in row and row.get(key, "") not in ("", None):
            return row.get(key)
        if key in npz_obj:
            arr = np.asarray(npz_obj[key]).reshape(-1)
            if arr.size > 0:
                return arr[0]
        return None

    mode_val = _scalar_from_sources("split_mode")
    if mode_val is None:
        return False
    if _normalize_two_session_split_mode(str(mode_val)) != str(expected["split_mode"]):
        return False

    for key in (
        "split_window_minutes",
        "window1_start_sec",
        "window1_end_sec",
        "window2_start_sec",
        "window2_end_sec",
    ):
        exp_val = expected[key]
        got_raw = _scalar_from_sources(key)
        try:
            got_val = float(got_raw)
        except (TypeError, ValueError):
            return False
        if np.isnan(float(exp_val)):
            if not np.isnan(got_val):
                return False
        elif (not np.isfinite(got_val)) or (not np.isclose(got_val, float(exp_val), atol=1e-9, rtol=0.0)):
            return False
    if str(expected["split_mode"]) == "prepost_plateau":
        for key in ("plateau_split_min_traversals_per_phase", "plateau_split_excluded_traversals"):
            got_raw = _scalar_from_sources(key)
            if got_raw is None:
                return False
            try:
                got_val = int(float(got_raw))
            except (TypeError, ValueError):
                return False
            if got_val != int(expected[key]):
                return False
    return True


def _infer_distance_direction_trial_count(dir_data: dict[str, Any]) -> int:
    for key in (
        "rate_stack",
        "ss_rate_stack",
        "cs_rate_stack",
        "theta_stack",
        "slow_stack",
        "plateau_stack",
        "ss_pct_stack",
        "cs_pct_stack",
    ):
        arr = dir_data.get(key)
        if arr is None:
            continue
        arr = np.asarray(arr)
        if arr.ndim == 2:
            return int(arr.shape[0])
    trial_data = dir_data.get("trial_data", {}) if isinstance(dir_data, dict) else {}
    if isinstance(trial_data, dict):
        for key in ("epoch_start_sec", "session_idx", "traversal_types"):
            arr = np.asarray(trial_data.get(key, []))
            if arr.ndim == 1:
                return int(arr.size)
    return int(max(0, int(dir_data.get("n_trials", 0))))


def _recompute_distance_direction_trial_summary(
    dir_data: dict[str, Any],
    *,
    n_trials: int,
) -> dict[str, Any]:
    out = dict(dir_data)
    n_trials_i = int(max(0, int(n_trials)))
    out["n_trials"] = n_trials_i
    out["n_total_trials"] = n_trials_i

    trial_data = out.get("trial_data", {}) if isinstance(out.get("trial_data", {}), dict) else {}
    n_spikes_all = np.asarray(trial_data.get("n_spikes_all", []), dtype=float)
    if n_spikes_all.ndim == 1 and n_spikes_all.size == n_trials_i:
        n_reliable = int(np.sum(np.isfinite(n_spikes_all) & (n_spikes_all > 0)))
    else:
        rate_stack = np.asarray(out.get("rate_stack", np.empty((0, 0))), dtype=float)
        if rate_stack.ndim == 2 and rate_stack.shape[0] == n_trials_i and n_trials_i > 0:
            n_reliable = int(np.sum(np.any(np.isfinite(rate_stack) & (rate_stack > 0), axis=1)))
        else:
            n_reliable = 0
    out["n_reliable_trials"] = int(n_reliable)
    out["reliability"] = (float(n_reliable) / float(n_trials_i)) if n_trials_i > 0 else np.nan

    stack_to_mean = {
        "theta_stack": "theta_mean",
        "slow_stack": "slow_mean",
        "rate_stack": "rate_mean",
        "ss_rate_stack": "ss_rate_mean",
        "cs_rate_stack": "cs_rate_mean",
    }
    n_time = None
    for stack_key, mean_key in stack_to_mean.items():
        stack = np.asarray(out.get(stack_key, np.empty((0, 0))), dtype=float)
        if stack.ndim == 2:
            n_time = int(stack.shape[1])
            if stack.shape[0] > 0:
                out[mean_key] = np.asarray(np.nanmean(stack, axis=0), dtype=float)
            else:
                out[mean_key] = np.full(int(stack.shape[1]), np.nan, dtype=float)
    if n_time is None:
        rate_mean = np.asarray(out.get("rate_mean", []), dtype=float).reshape(-1)
        n_time = int(rate_mean.size) if rate_mean.ndim == 1 else 0

    ss_pct_stack = np.asarray(out.get("ss_pct_stack", np.empty((0, n_time))), dtype=float)
    cs_pct_stack = np.asarray(out.get("cs_pct_stack", np.empty((0, n_time))), dtype=float)
    if ss_pct_stack.ndim == 2:
        out["ss_pct_mean"] = (
            np.asarray(np.nanmean(ss_pct_stack, axis=0), dtype=float)
            if ss_pct_stack.shape[0] > 0
            else np.full(int(ss_pct_stack.shape[1]), np.nan, dtype=float)
        )
    if cs_pct_stack.ndim == 2:
        out["cs_pct_mean"] = (
            np.asarray(np.nanmean(cs_pct_stack, axis=0), dtype=float)
            if cs_pct_stack.shape[0] > 0
            else np.full(int(cs_pct_stack.shape[1]), np.nan, dtype=float)
        )
    traversal_types = np.asarray(trial_data.get("traversal_types", []), dtype=object)
    if traversal_types.ndim == 1 and traversal_types.size == n_trials_i:
        out["traversal_types"] = traversal_types.copy()
    return out


def _filter_distance_direction_rows_with_labels(
    dir_data: dict[str, Any],
    *,
    keep: np.ndarray,
    labels: np.ndarray,
) -> dict[str, Any] | None:
    n_rows_ref = _infer_distance_direction_trial_count(dir_data)
    if n_rows_ref <= 0:
        return _recompute_distance_direction_trial_summary(dict(dir_data), n_trials=0)

    keep = np.asarray(keep, dtype=bool).reshape(-1)
    labels = np.asarray(labels, dtype=int).reshape(-1)
    if keep.size != int(n_rows_ref) or labels.size != int(n_rows_ref):
        return None

    trial_data_in = dir_data.get("trial_data", {})
    trial_data_in = trial_data_in if isinstance(trial_data_in, dict) else {}
    out = dict(dir_data)
    rowwise_1d_keys = {"pf_entry_rel", "pf_exit_rel", "n_plateaus_per_trial", "traversal_types"}

    for key, value in dir_data.items():
        if key == "trial_data":
            continue
        if key == "plateau_trace_events_by_trial" and isinstance(value, (list, tuple)) and len(value) == int(n_rows_ref):
            out[key] = [value[int(i)] for i in np.flatnonzero(keep)]
            continue
        try:
            arr = np.asarray(value)
        except Exception:
            out[key] = value
            continue
        if arr.ndim == 2 and arr.shape[0] == int(n_rows_ref):
            out[key] = arr[keep]
        elif key in rowwise_1d_keys and arr.ndim == 1 and arr.size == int(n_rows_ref):
            out[key] = arr[keep]
        else:
            out[key] = value

    trial_data_out: dict[str, Any] = {}
    for key, value in trial_data_in.items():
        if key == "session_idx":
            continue
        try:
            arr = np.asarray(value)
        except Exception:
            trial_data_out[key] = value
            continue
        if arr.ndim == 1 and arr.size == int(n_rows_ref):
            trial_data_out[key] = arr[keep]
        else:
            trial_data_out[key] = value
    trial_data_out["session_idx"] = np.asarray(labels[keep], dtype=int)
    out["trial_data"] = trial_data_out
    return _recompute_distance_direction_trial_summary(out, n_trials=int(np.sum(keep)))


def _split_distance_direction_for_two_sessions(
    dir_data: dict[str, Any],
    *,
    split_mode: str,
    split_window_minutes: float | None,
) -> dict[str, Any] | None:
    mode = _normalize_two_session_split_mode(split_mode)
    if mode != "time_windows":
        return dir_data

    window_min = _validate_two_session_split_window_minutes(mode, split_window_minutes)
    n_rows_ref = _infer_distance_direction_trial_count(dir_data)
    if n_rows_ref <= 0:
        return _recompute_distance_direction_trial_summary(dict(dir_data), n_trials=0)

    trial_data_in = dir_data.get("trial_data", {})
    if not isinstance(trial_data_in, dict):
        return None
    epoch_start_sec = np.asarray(trial_data_in.get("epoch_start_sec", []), dtype=float)
    if epoch_start_sec.ndim != 1 or epoch_start_sec.size != int(n_rows_ref):
        return None

    window_sec = float(window_min) * 60.0
    session_labels = np.full(int(n_rows_ref), -1, dtype=int)
    finite_mask = np.isfinite(epoch_start_sec) & (epoch_start_sec >= 0.0)
    session_labels[finite_mask & (epoch_start_sec < window_sec)] = 0
    session_labels[finite_mask & (epoch_start_sec >= window_sec) & (epoch_start_sec < (2.0 * window_sec))] = 1
    keep = session_labels >= 0

    return _filter_distance_direction_rows_with_labels(dir_data, keep=keep, labels=session_labels)


def _prepost_plateau_split_spec_from_all_direction(
    all_data: dict[str, Any],
    *,
    plateau_split_min_traversals_per_phase: int,
    plateau_split_excluded_traversals: int,
) -> dict[str, Any] | None:
    n_rows_ref = _infer_distance_direction_trial_count(all_data)
    if n_rows_ref <= 0:
        return None
    n_plateaus = np.asarray(all_data.get("n_plateaus_per_trial", []), dtype=float).reshape(-1)
    if n_plateaus.ndim != 1 or n_plateaus.size != int(n_rows_ref):
        return None
    plateau_rows = np.flatnonzero(np.isfinite(n_plateaus) & (n_plateaus > 0))
    if plateau_rows.size == 0:
        return None
    first_plateau_idx = int(plateau_rows[0])
    post_start_idx = int(first_plateau_idx + int(plateau_split_excluded_traversals))
    if post_start_idx >= int(n_rows_ref):
        return None

    pre_count = int(first_plateau_idx)
    post_count = int(n_rows_ref - post_start_idx)
    min_trav = int(plateau_split_min_traversals_per_phase)
    if pre_count < min_trav or post_count < min_trav:
        return None

    trial_data = all_data.get("trial_data", {}) if isinstance(all_data, dict) else {}
    trial_data = trial_data if isinstance(trial_data, dict) else {}
    epoch_start_frames = np.asarray(trial_data.get("epoch_start_frames", []), dtype=float).reshape(-1)
    if epoch_start_frames.ndim != 1 or epoch_start_frames.size != int(n_rows_ref):
        return None
    if (not np.isfinite(epoch_start_frames[first_plateau_idx])) or (not np.isfinite(epoch_start_frames[post_start_idx])):
        return None

    return {
        "first_plateau_idx": int(first_plateau_idx),
        "post_start_idx": int(post_start_idx),
        "first_plateau_epoch_start_frame": float(epoch_start_frames[first_plateau_idx]),
        "post_epoch_start_frame": float(epoch_start_frames[post_start_idx]),
        "pre_count_all": int(pre_count),
        "post_count_all": int(post_count),
        "plateau_split_min_traversals_per_phase": int(min_trav),
        "plateau_split_excluded_traversals": int(plateau_split_excluded_traversals),
    }


def _split_distance_direction_for_prepost_plateau(
    dir_data: dict[str, Any],
    *,
    split_spec: dict[str, Any],
) -> dict[str, Any] | None:
    n_rows_ref = _infer_distance_direction_trial_count(dir_data)
    if n_rows_ref <= 0:
        return _recompute_distance_direction_trial_summary(dict(dir_data), n_trials=0)
    trial_data = dir_data.get("trial_data", {}) if isinstance(dir_data, dict) else {}
    trial_data = trial_data if isinstance(trial_data, dict) else {}
    epoch_start_frames = np.asarray(trial_data.get("epoch_start_frames", []), dtype=float).reshape(-1)
    if epoch_start_frames.ndim != 1 or epoch_start_frames.size != int(n_rows_ref):
        return None

    first_frame = float(split_spec["first_plateau_epoch_start_frame"])
    post_frame = float(split_spec["post_epoch_start_frame"])
    labels = np.full(int(n_rows_ref), -1, dtype=int)
    finite = np.isfinite(epoch_start_frames)
    labels[finite & (epoch_start_frames < first_frame)] = 0
    labels[finite & (epoch_start_frames >= post_frame)] = 1
    keep = labels >= 0
    return _filter_distance_direction_rows_with_labels(dir_data, keep=keep, labels=labels)


def _split_distance_centered_entry_for_prepost_plateau(
    entry: dict[str, Any] | None,
    *,
    plateau_split_min_traversals_per_phase: int,
    plateau_split_excluded_traversals: int,
) -> dict[str, Any] | None:
    if entry is None:
        return None
    data_in = entry.get("data", {})
    if not isinstance(data_in, dict):
        return None
    all_data = data_in.get("all", {})
    if not isinstance(all_data, dict):
        return None

    split_spec = _prepost_plateau_split_spec_from_all_direction(
        all_data,
        plateau_split_min_traversals_per_phase=plateau_split_min_traversals_per_phase,
        plateau_split_excluded_traversals=plateau_split_excluded_traversals,
    )
    if split_spec is None:
        return None

    out = dict(entry)
    data_out: dict[str, Any] = {}
    for dir_key, dir_data in data_in.items():
        if dir_key in {"all", "cw", "ccw"} and isinstance(dir_data, dict):
            split_dir = _split_distance_direction_for_prepost_plateau(dir_data, split_spec=split_spec)
            if split_dir is None:
                return None
            data_out[dir_key] = split_dir
        else:
            data_out[dir_key] = dir_data
    out["data"] = data_out
    out["_prepost_plateau_split"] = dict(split_spec)
    return out


def _split_distance_centered_entry_for_two_sessions(
    entry: dict[str, Any] | None,
    *,
    split_mode: str,
    split_window_minutes: float | None,
    plateau_split_min_traversals_per_phase: int = 5,
    plateau_split_excluded_traversals: int = 0,
) -> dict[str, Any] | None:
    if entry is None:
        return None
    mode = _normalize_two_session_split_mode(split_mode)
    if mode == "prepost_plateau":
        return _split_distance_centered_entry_for_prepost_plateau(
            entry,
            plateau_split_min_traversals_per_phase=int(plateau_split_min_traversals_per_phase),
            plateau_split_excluded_traversals=int(plateau_split_excluded_traversals),
        )
    if mode != "time_windows":
        return entry

    out = dict(entry)
    data_in = entry.get("data", {})
    if not isinstance(data_in, dict):
        return None
    data_out: dict[str, Any] = {}
    for dir_key, dir_data in data_in.items():
        if dir_key in {"all", "cw", "ccw"} and isinstance(dir_data, dict):
            split_dir = _split_distance_direction_for_two_sessions(
                dir_data,
                split_mode=mode,
                split_window_minutes=split_window_minutes,
            )
            if split_dir is None:
                return None
            data_out[dir_key] = split_dir
        else:
            data_out[dir_key] = dir_data
    out["data"] = data_out
    return out


def _split_distance_centered_entries_for_two_sessions(
    entries: list[dict[str, Any]],
    *,
    split_mode: str,
    split_window_minutes: float | None,
    plateau_split_min_traversals_per_phase: int = 5,
    plateau_split_excluded_traversals: int = 0,
) -> list[dict[str, Any]]:
    out: list[dict[str, Any]] = []
    for entry in entries:
        split_entry = _split_distance_centered_entry_for_two_sessions(
            entry,
            split_mode=split_mode,
            split_window_minutes=split_window_minutes,
            plateau_split_min_traversals_per_phase=plateau_split_min_traversals_per_phase,
            plateau_split_excluded_traversals=plateau_split_excluded_traversals,
        )
        if split_entry is not None:
            out.append(split_entry)
    return out


def _plateau_trace_events_by_trial_from_entry(entry: dict[str, Any] | None) -> list[list[dict[str, Any]]]:
    if not isinstance(entry, dict):
        return []
    data = entry.get("data", {})
    if not isinstance(data, dict):
        return []
    all_data = data.get("all", {})
    if not isinstance(all_data, dict):
        return []
    raw = all_data.get("plateau_trace_events_by_trial", [])
    if isinstance(raw, np.ndarray) and raw.dtype == object:
        raw = raw.tolist()
    if not isinstance(raw, (list, tuple)):
        return []
    out: list[list[dict[str, Any]]] = []
    for trial_events in raw:
        if isinstance(trial_events, np.ndarray) and trial_events.dtype == object:
            trial_events = trial_events.tolist()
        if not isinstance(trial_events, (list, tuple)):
            out.append([])
            continue
        cleaned: list[dict[str, Any]] = []
        for event in trial_events:
            if not isinstance(event, dict):
                continue
            x = np.asarray(event.get("x_ms", []), dtype=float).reshape(-1)
            y = np.asarray(event.get("trace_spkh", []), dtype=float).reshape(-1)
            if x.size == 0 or y.size == 0 or x.size != y.size:
                continue
            if not np.any(np.isfinite(x) & np.isfinite(y)):
                continue
            cleaned.append(
                {
                    **event,
                    "x_ms": x,
                    "trace_spkh": y,
                }
            )
        out.append(cleaned)
    return out


def _plateau_trace_entry_has_events(entry: dict[str, Any] | None) -> bool:
    return any(len(events) > 0 for events in _plateau_trace_events_by_trial_from_entry(entry))


def _plateau_trace_entry_has_payload(entry: dict[str, Any] | None) -> bool:
    if not isinstance(entry, dict):
        return False
    data = entry.get("data", {})
    if not isinstance(data, dict):
        return False
    all_data = data.get("all", {})
    return isinstance(all_data, dict) and "plateau_trace_events_by_trial" in all_data


def _compute_plateau_trace_xlim_for_entries(
    entries: list[dict[str, Any] | None],
    *,
    fallback: tuple[float, float] = (-100.0, 250.0),
) -> tuple[float, float]:
    xs: list[np.ndarray] = []
    for entry in entries:
        for trial_events in _plateau_trace_events_by_trial_from_entry(entry):
            for event in trial_events:
                x = np.asarray(event.get("x_ms", []), dtype=float)
                if x.size > 0 and np.any(np.isfinite(x)):
                    xs.append(x[np.isfinite(x)])
    if len(xs) == 0:
        return float(fallback[0]), float(fallback[1])
    cat = np.concatenate(xs)
    x0 = float(np.nanmin(cat))
    x1 = float(np.nanmax(cat))
    x0 = min(x0, 0.0)
    x1 = max(x1, 100.0)
    if (not np.isfinite(x0)) or (not np.isfinite(x1)) or x1 <= x0:
        return float(fallback[0]), float(fallback[1])
    pad = max(5.0, 0.03 * (x1 - x0))
    return float(x0 - pad), float(x1 + pad)


def _flatten_plateau_trace_events_for_entry(entry: dict[str, Any] | None) -> list[dict[str, Any]]:
    events: list[dict[str, Any]] = []
    for trial_idx, trial_events in enumerate(_plateau_trace_events_by_trial_from_entry(entry)):
        for event_idx, event in enumerate(trial_events):
            x = np.asarray(event.get("x_ms", []), dtype=float).reshape(-1)
            y = np.asarray(event.get("trace_spkh", []), dtype=float).reshape(-1)
            if x.size == 0 or y.size == 0 or x.size != y.size:
                continue
            finite = np.isfinite(x) & np.isfinite(y)
            if not np.any(finite):
                continue
            plateau_start_ms = float(event.get("plateau_start_ms", 0.0))
            plateau_end_ms = event.get("plateau_end_ms", np.nan)
            try:
                plateau_end_ms = float(plateau_end_ms)
            except Exception:
                plateau_end_ms = np.nan
            events.append(
                {
                    "trial_idx": int(trial_idx),
                    "event_idx": int(event_idx),
                    "x_ms": x[finite],
                    "trace_spkh": y[finite],
                    "plateau_start_ms": plateau_start_ms,
                    "plateau_end_ms": plateau_end_ms,
                }
            )
    return events


def _pack_plateau_trace_events_for_entry(
    entry: dict[str, Any] | None,
    *,
    plateau_height_per_spkh: float = 0.15,
    vertical_gap: float = 0.025,
) -> tuple[list[dict[str, Any]], float]:
    amp_scale = float(plateau_height_per_spkh)
    if (not np.isfinite(amp_scale)) or amp_scale <= 0:
        amp_scale = 0.15
    gap = float(vertical_gap)
    if (not np.isfinite(gap)) or gap < 0:
        gap = 0.025
    packed: list[dict[str, Any]] = []
    next_top = 0.0
    last_bottom = 0.0
    for event in _flatten_plateau_trace_events_for_entry(entry):
        x = np.asarray(event["x_ms"], dtype=float)
        y = np.asarray(event["trace_spkh"], dtype=float)
        y_min = float(np.nanmin(y))
        y_max = float(np.nanmax(y))
        if (not np.isfinite(y_min)) or (not np.isfinite(y_max)):
            continue
        baseline = next_top + y_max * amp_scale
        y_plot = baseline - y * amp_scale
        y_top = float(np.nanmin(y_plot))
        y_bottom = float(np.nanmax(y_plot))
        packed.append(
            {
                **event,
                "y_plot": y_plot,
                "y_top": y_top,
                "y_bottom": y_bottom,
            }
        )
        last_bottom = y_bottom
        next_top = y_bottom + gap
    return packed, float(last_bottom)


def _compute_plateau_trace_ylim_for_entries(
    entries: list[dict[str, Any] | None],
    *,
    include_scale_bars: bool = True,
    plateau_height_per_spkh: float = 0.15,
    vertical_gap: float = 0.025,
) -> tuple[float, float]:
    amp_scale = float(plateau_height_per_spkh)
    if (not np.isfinite(amp_scale)) or amp_scale <= 0:
        amp_scale = 0.15
    top_lim = -0.025
    bottom_values: list[float] = []
    for entry in entries:
        packed, last_bottom = _pack_plateau_trace_events_for_entry(
            entry,
            plateau_height_per_spkh=amp_scale,
            vertical_gap=vertical_gap,
        )
        if len(packed) == 0:
            bottom_values.append(1.0)
            continue
        bottom = max(1.0, float(last_bottom) + 0.06)
        if bool(include_scale_bars):
            bottom = max(bottom, float(last_bottom) + 0.08 + amp_scale + 0.12)
        bottom_values.append(bottom)
    bottom_lim = max(bottom_values) if bottom_values else 1.0
    if (not np.isfinite(bottom_lim)) or bottom_lim <= top_lim:
        bottom_lim = 1.0
    return float(top_lim), float(bottom_lim)


def _infer_entry_trial_count(entry: dict[str, Any] | None) -> int:
    if not isinstance(entry, dict):
        return 0
    data = entry.get("data", {})
    if not isinstance(data, dict):
        return 0
    all_data = data.get("all", {})
    if not isinstance(all_data, dict):
        return 0
    for key in ("rate_stack", "theta_stack", "slow_stack", "plateau_stack"):
        arr = all_data.get(key)
        if arr is None:
            continue
        arr = np.asarray(arr)
        if arr.ndim == 2:
            return int(arr.shape[0])
    try:
        return int(all_data.get("n_trials", 0))
    except Exception:
        return 0


def _plot_plateau_trace_events_column(
    fig: Any,
    entry: dict[str, Any],
    bbox: tuple[float, float, float, float],
    *,
    xlim: tuple[float, float],
    title: str | None = None,
    show_scale_bars: bool = False,
    shared_ylim: tuple[float, float] | None = None,
    plateau_height_per_spkh: float = 0.15,
    vertical_gap: float = 0.025,
) -> Any:
    ax = fig.add_axes(list(bbox))
    ax.set_facecolor("white")
    x0, x1 = float(xlim[0]), float(xlim[1])
    if (not np.isfinite(x0)) or (not np.isfinite(x1)) or x1 <= x0:
        x0, x1 = -100.0, 250.0
    ax.set_xlim(x0, x1)
    if shared_ylim is not None and len(shared_ylim) == 2:
        top_lim, bottom_lim = float(shared_ylim[0]), float(shared_ylim[1])
    else:
        top_lim, bottom_lim = _compute_plateau_trace_ylim_for_entries(
            [entry],
            include_scale_bars=bool(show_scale_bars),
            plateau_height_per_spkh=plateau_height_per_spkh,
            vertical_gap=vertical_gap,
        )
    if (
        (not np.isfinite(top_lim))
        or (not np.isfinite(bottom_lim))
        or bottom_lim <= top_lim
    ):
        top_lim, bottom_lim = -0.08, 1.0
    ax.set_ylim(bottom_lim, top_lim)
    ax.set_xticks([])
    ax.set_yticks([])
    for spine in ax.spines.values():
        spine.set_visible(False)

    packed_events, last_plateau_bottom = _pack_plateau_trace_events_for_entry(
        entry,
        plateau_height_per_spkh=plateau_height_per_spkh,
        vertical_gap=vertical_gap,
    )
    amp_scale = float(plateau_height_per_spkh)
    if (not np.isfinite(amp_scale)) or amp_scale <= 0:
        amp_scale = 0.15
    for event in packed_events:
        plateau_start_ms = float(event.get("plateau_start_ms", np.nan))
        plateau_end_ms = float(event.get("plateau_end_ms", np.nan))
        if (
            (not np.isfinite(plateau_start_ms))
            or (not np.isfinite(plateau_end_ms))
            or plateau_end_ms <= plateau_start_ms
        ):
            continue
        shade_x0 = max(float(x0), plateau_start_ms)
        shade_x1 = min(float(x1), plateau_end_ms)
        if shade_x1 <= shade_x0:
            continue
        y_top = float(event.get("y_top", np.nan))
        y_bottom = float(event.get("y_bottom", np.nan))
        if (not np.isfinite(y_top)) or (not np.isfinite(y_bottom)):
            continue
        y_mid = 0.5 * (y_top + y_bottom)
        shade_height = max((y_bottom - y_top) + 0.05 * amp_scale, 0.75 * amp_scale)
        shade_y0 = y_mid - 0.5 * shade_height
        ax.add_patch(
            Rectangle(
                (shade_x0, shade_y0),
                shade_x1 - shade_x0,
                shade_height,
                facecolor="#D62728",
                edgecolor="none",
                alpha=0.18,
                linewidth=0.0,
                zorder=0.5,
            )
        )
    for event in packed_events:
        ax.plot(
            np.asarray(event["x_ms"], dtype=float),
            np.asarray(event["y_plot"], dtype=float),
            color="black",
            alpha=0.95,
            linewidth=0.35,
            zorder=2.0,
        )

    if title:
        ax.set_title(str(title), fontsize=5, fontname="Arial", pad=1.0)
    if len(packed_events) == 0:
        ax.text(0.5, 0.5, "No plateaus", transform=ax.transAxes, ha="center", va="center", fontsize=4, fontname="Arial")

    if show_scale_bars and len(packed_events) > 0:
        x_span = float(x1 - x0)
        x_bar1 = x1 - 0.08 * x_span
        x_bar0 = x_bar1 - 100.0
        min_x_bar0 = x0 + 0.05 * x_span
        if x_bar0 < min_x_bar0:
            x_bar0 = min_x_bar0
            x_bar1 = x_bar0 + 100.0
        y_bar = float(last_plateau_bottom) + 0.08
        if x_bar1 > x_bar0 and x_bar0 >= x0 and x_bar1 <= x1:
            ax.plot([x_bar0, x_bar1], [y_bar, y_bar], color="black", linewidth=0.8, solid_capstyle="butt")
            ax.text((x_bar0 + x_bar1) / 2, y_bar + 0.035, "100 ms", ha="center", va="top", fontsize=4, fontname="Arial")
            x_v = x_bar0
            ax.plot([x_v, x_v], [y_bar, y_bar + amp_scale], color="black", linewidth=0.8, solid_capstyle="butt")
            ax.text(x_v - 0.03 * x_span, y_bar + 0.5 * amp_scale, "1 spkh", ha="right", va="center", fontsize=4, fontname="Arial")
    return ax


def generate_pf_distance_centered_component_heatmaps(
    dataset: dict[str, Any],
    *,
    figure_save_folder: str | Path,
    clear_output: bool = True,
    smooth_window: float = 1.0,
    fr_vmax_scale: float = 0.6,
    theta_vlim: tuple[float, float] = (0, 0.5),
    slow_vlim: tuple[float, float] = (-0.4, 0.4),
    fig_width: float = 3.8,
    trial_height: float = 0.02,
    xlim: tuple[float, float] | None = None,
    merge_ss_cs: bool = True,
    merge_plateau: bool = True,
    smooth_plateau: bool = False,
    plateau_vlim: float = 0.01,
    avg_smooth_window: float | None = None,
    align_all_peak_to_zero: bool = True,
    peak_align_window: tuple[float, float] = (-5.0, 5.0),
    max_peak_adjust_cm: float | None = None,
    max_peak_adjust_cm_pf1: float | None = None,
    max_peak_adjust_cm_pf2: float | None = None,
    show_session_gap_line: bool = True,
    auto_colorbar_vmax_from_pf1_all: bool = True,
    colorbar_std_multiplier: float = 3.0,
    x_label: str = "Distance from PF peak (cm)",
    output_prefix: str = "pf_centered",
    show_plot: bool = False,
) -> dict[str, Any]:
    figure_root = Path(figure_save_folder)
    distance_window_cm = float(dataset.get("metadata", {}).get("distance_window_cm", 20.0))
    distance_bin_cm = float(dataset.get("metadata", {}).get("distance_bin_cm", 1.0))
    xlim_use = (-distance_window_cm, distance_window_cm) if xlim is None else xlim
    smooth_window_bins = _distance_smooth_cm_to_bins(distance_bin_cm, smooth_window)
    if avg_smooth_window is None:
        avg_smooth_window = smooth_window
    avg_smooth_window_bins = _distance_smooth_cm_to_bins(distance_bin_cm, avg_smooth_window)
    def _window_from_cap(cap_cm: float | None) -> tuple[float, float]:
        if cap_cm is None:
            return peak_align_window
        cap_cm = float(cap_cm)
        if (not np.isfinite(cap_cm)) or cap_cm < 0:
            raise ValueError("max_peak_adjust_cm values must be finite numbers >= 0.")
        return (-cap_cm, cap_cm)

    # Backward-compatible behavior: PF-specific cap overrides global cap.
    pf1_window = _window_from_cap(max_peak_adjust_cm_pf1 if max_peak_adjust_cm_pf1 is not None else max_peak_adjust_cm)
    pf2_window = _window_from_cap(max_peak_adjust_cm_pf2 if max_peak_adjust_cm_pf2 is not None else max_peak_adjust_cm)
    categories = _ordered_dataset_categories(dataset)

    def _prep_entries(cat_name: str, pf_rank: int) -> tuple[np.ndarray, list[dict[str, Any]]]:
        rel = np.asarray(dataset.get(cat_name, {}).get(pf_rank, {}).get("distance_rel", []), dtype=float)
        entries = list(dataset.get(cat_name, {}).get(pf_rank, {}).get("entries", []))
        if not bool(align_all_peak_to_zero) or rel.size == 0:
            for entry in entries:
                entry["_peak_align_shift_cm"] = 0.0
            return rel, entries
        peak_align_window_use = pf1_window if int(pf_rank) == 1 else pf2_window
        shifted_entries = [
            _shift_distance_centered_entry_for_peak_alignment(
                entry,
                rel,
                smooth_window=smooth_window_bins,
                avg_smooth_window=avg_smooth_window_bins,
                peak_align_window=peak_align_window_use,
            )
            for entry in entries
        ]
        for entry in shifted_entries:
            session = str(entry.get("session", ""))
            cell_idx = int(entry.get("cell_idx", -1))
            shift_cm = float(entry.get("_peak_align_shift_cm", 0.0))
            print(f"[{cat_name}] {session} Cell {cell_idx + 1} PF{pf_rank}: peak shift = {shift_cm:.2f} cm")
        return rel, shifted_entries

    pf_centered_dataset: dict[str, Any] = {}
    for cat_name in categories:
        rel1, entries1 = _prep_entries(cat_name, 1)
        rel2, entries2 = _prep_entries(cat_name, 2)
        pf_centered_dataset[cat_name] = {
            1: {"time_rel": rel1, "entries": entries1},
            2: {"time_rel": rel2, "entries": entries2},
        }

    return generate_pf_centered_component_heatmaps(
        dataset=pf_centered_dataset,
        figure_save_folder=figure_root,
        clear_output=clear_output,
        smooth_window=smooth_window_bins,
        fr_vmax_scale=fr_vmax_scale,
        theta_vlim=theta_vlim,
        slow_vlim=slow_vlim,
        fig_width=fig_width,
        trial_height=trial_height,
        xlim=xlim_use,
        merge_ss_cs=merge_ss_cs,
        merge_plateau=merge_plateau,
        smooth_plateau=smooth_plateau,
        plateau_vlim=plateau_vlim,
        avg_smooth_window=avg_smooth_window_bins,
        x_label=str(x_label),
        center_line_x=0.0,
        show_session_gap_line=show_session_gap_line,
        auto_colorbar_vmax_from_pf1_all=auto_colorbar_vmax_from_pf1_all,
        colorbar_std_multiplier=colorbar_std_multiplier,
        output_prefix=str(output_prefix),
        show_plot=show_plot,
    )


def _plot_single_cell_heatmap_on_figure_2sessions(
    fig: Any,
    entry_data: dict[str, Any],
    time_rel: np.ndarray,
    *,
    smooth_window: int = 0,
    interpolate_nan: bool = True,
    fr_vmax_scale: float = 0.5,
    theta_vlim: tuple[float, float] = (0, 0.4),
    slow_vlim: tuple[float, float] = (-0.4, 0.4),
    trial_height: float = 0.06,
    xlim: tuple[float, float] = (-4, 4),
    merge_ss_cs: bool = True,
    merge_plateau: bool = True,
    smooth_plateau: bool = False,
    plateau_vlim: float = 0.1,
    avg_height: float = 0.3,
    avg_smooth_window: int = 0,
    x_label: str = "Distance (cm)",
    center_line_x: float = 0.0,
    show_session_gap_line: bool = False,
    session_gap_line_color: str = "black",
    session_gap_line_width: float = 0.35,
    fr_vmax_override: tuple[float, float, float] | None = None,
    colorbar_vmax_override: dict[str, float] | None = None,
    avg_ylim_override: dict[str, tuple[float, float]] | None = None,
    fixed_heatmap_height: float | None = None,
    fixed_subplot_width: float | None = None,
    panel_bbox: tuple[float, float, float, float] | None = None,
    show_row_ylabel: bool = True,
    show_heatmap_yticks: bool = True,
    show_colorbar: bool = True,
    show_avg_yticks_left_only: bool = True,
    show_rate_session_legend: bool = True,
    panel_title: str | None = None,
    panel_title_pad: float = 1.0,
    avg_ylim_focus_window: tuple[float, float] | None = None,
    apply_tight_layout: bool = True,
    Plot_plateaus: bool = True,
    plateau_column_bbox: tuple[float, float, float, float] | None = None,
    plateau_trace_xlim: tuple[float, float] | None = None,
    plateau_trace_ylim: tuple[float, float] | None = None,
    plateau_height_per_spkh: float = 0.15,
    show_plateau_scale_bars: bool = False,
    plateau_column_title: str | None = None,
    phase_labels: tuple[str, str] | list[str] | None = None,
) -> dict[str, tuple[float, float]]:
    from matplotlib.cm import ScalarMappable
    from matplotlib.colors import LinearSegmentedColormap, Normalize
    from matplotlib.gridspec import GridSpec, GridSpecFromSubplotSpec
    from matplotlib.lines import Line2D

    cell_data = entry_data.get("data", {})
    all_data = cell_data.get("all", {})
    phase_labels_use = _normalize_two_phase_labels(phase_labels)
    n_time = int(len(time_rel))
    avg_display_mask = (time_rel >= xlim[0]) & (time_rel <= xlim[1])
    if not np.any(avg_display_mask):
        avg_display_mask = np.ones(n_time, dtype=bool)
    if avg_ylim_focus_window is None:
        avg_ylim_mask = avg_display_mask.copy()
    else:
        w0, w1 = float(avg_ylim_focus_window[0]), float(avg_ylim_focus_window[1])
        if w1 < w0:
            w0, w1 = w1, w0
        avg_ylim_mask = (time_rel >= w0) & (time_rel <= w1)
        if not np.any(avg_ylim_mask):
            avg_ylim_mask = avg_display_mask.copy()

    def _get_stack(key: str) -> np.ndarray | None:
        arr = all_data.get(key)
        if arr is None:
            return None
        arr = np.asarray(arr, dtype=float)
        if arr.ndim != 2 or arr.shape[1] != n_time:
            return None
        if bool(interpolate_nan) and key != "plateau_stack":
            arr = _interpolate_nan_stack_rows(arr)
        if int(smooth_window) > 1:
            smoothed = np.full_like(arr, np.nan)
            for i in range(arr.shape[0]):
                smoothed[i] = _smooth_boxcar(arr[i], int(smooth_window))
            arr = smoothed
        return arr

    def _smooth_avg(trace: np.ndarray) -> np.ndarray:
        if int(avg_smooth_window) > 1:
            return _smooth_boxcar(trace, int(avg_smooth_window))
        return trace

    def _session_idx_for_n(n_trials_local: int) -> np.ndarray:
        td = all_data.get("trial_data", {}) if isinstance(all_data, dict) else {}
        sess = np.asarray(td.get("session_idx", []), dtype=int) if isinstance(td, dict) else np.array([], dtype=int)
        if sess.ndim == 1 and sess.size == int(n_trials_local):
            return sess
        return np.zeros(int(n_trials_local), dtype=int)

    def _session_gap_y(actual_trials: int) -> float | None:
        if not bool(show_session_gap_line):
            return None
        sess = _session_idx_for_n(actual_trials)
        if sess.size < 2:
            return None
        changes = np.where(np.diff(sess.astype(int)) != 0)[0]
        if changes.size == 0:
            return None
        return float(int(changes[0]) + 1) + 0.5

    rate_stack = _get_stack("rate_stack")
    ss_stack = _get_stack("ss_rate_stack")
    cs_stack = _get_stack("cs_rate_stack")
    theta_stack = _get_stack("theta_stack")
    slow_stack = _get_stack("slow_stack")
    plateau_stack = _get_stack("plateau_stack") if bool(merge_plateau) else None

    if plateau_stack is not None and bool(smooth_plateau) and int(smooth_window) > 1:
        p_sm = np.full_like(plateau_stack, np.nan)
        for i in range(plateau_stack.shape[0]):
            p_sm[i] = _smooth_boxcar(plateau_stack[i], int(smooth_window))
        plateau_stack = p_sm

    row_vmax = [0.0, 0.0, 0.0]  # rate, ss, cs
    for i, st in enumerate([rate_stack, ss_stack, cs_stack]):
        if st is not None and st.size > 0:
            row_vmax[i] = float(np.nanmax(st))
    if fr_vmax_override is not None and len(fr_vmax_override) == 3:
        for i in range(3):
            v = float(fr_vmax_override[i])
            if np.isfinite(v) and v > 0:
                row_vmax[i] = v

    vmax_override: dict[str, float] = {}
    if isinstance(colorbar_vmax_override, dict):
        for key in ("rate", "ss", "cs", "theta"):
            val = colorbar_vmax_override.get(key)
            if val is None:
                continue
            val_f = float(val)
            if np.isfinite(val_f) and val_f > 0:
                vmax_override[key] = val_f

    rate_vmax = float(vmax_override.get("rate", row_vmax[0] * fr_vmax_scale if row_vmax[0] > 0 else 1.0))
    ss_vmax = float(vmax_override.get("ss", row_vmax[1] * fr_vmax_scale if row_vmax[1] > 0 else 1.0))
    cs_vmax = float(vmax_override.get("cs", row_vmax[2] * fr_vmax_scale if row_vmax[2] > 0 else 1.0))
    theta_vmax = float(vmax_override.get("theta", theta_vlim[1]))
    if not np.isfinite(theta_vmax):
        theta_vmax = float(theta_vlim[1])
    if theta_vmax <= float(theta_vlim[0]):
        theta_vmax = float(theta_vlim[0]) + 1e-6

    if bool(merge_ss_cs):
        row_defs = [
            {"key": "rate", "label": "FR, all spikes (Hz)", "avg_keys": ["rate"], "vmin": 0.0, "vmax": rate_vmax},
            {"key": "sscs", "label": "FR, SS/CS (Hz)", "avg_keys": ["ss", "cs"], "vmin": 0.0, "vmax": None},
            {"key": "theta", "label": "\u03b8 amplitude (spkh.)", "avg_keys": ["theta"], "vmin": float(theta_vlim[0]), "vmax": theta_vmax},
            {"key": "slow", "label": "Slow Vm (spkh.)", "avg_keys": ["slow"], "vmin": float(slow_vlim[0]), "vmax": float(slow_vlim[1])},
        ]
    else:
        row_defs = [
            {"key": "rate", "label": "FR, all spikes (Hz)", "avg_keys": ["rate"], "vmin": 0.0, "vmax": rate_vmax},
            {"key": "ss", "label": "FR, SS (Hz)", "avg_keys": ["ss"], "vmin": 0.0, "vmax": ss_vmax},
            {"key": "cs", "label": "FR, CS (Hz)", "avg_keys": ["cs"], "vmin": 0.0, "vmax": cs_vmax},
            {"key": "theta", "label": "\u03b8 amplitude (spkh.)", "avg_keys": ["theta"], "vmin": float(theta_vlim[0]), "vmax": theta_vmax},
            {"key": "slow", "label": "Slow Vm (spkh.)", "avg_keys": ["slow"], "vmin": float(slow_vlim[0]), "vmax": float(slow_vlim[1])},
        ]

    stacks_by_key = {
        "rate": rate_stack,
        "ss": ss_stack,
        "cs": cs_stack,
        "theta": theta_stack,
        "slow": slow_stack,
    }

    n_trials = 1
    for st in [rate_stack, ss_stack, cs_stack, theta_stack, slow_stack]:
        if st is not None and st.ndim == 2:
            n_trials = max(n_trials, int(st.shape[0]))

    if fixed_heatmap_height is not None and np.isfinite(float(fixed_heatmap_height)) and float(fixed_heatmap_height) > 0:
        heatmap_h = float(fixed_heatmap_height)
    else:
        heatmap_h = int(n_trials) * float(trial_height)

    n_rows = len(row_defs)
    exact_layout = (
        panel_bbox is not None
        and fixed_subplot_width is not None
        and np.isfinite(float(fixed_subplot_width))
        and float(fixed_subplot_width) > 0
        and np.isfinite(float(heatmap_h))
        and float(heatmap_h) > 0
    )
    outer_gs = GridSpec(
        n_rows,
        2,
        figure=fig,
        width_ratios=[1, 0.05],
        wspace=0.15,
        hspace=0.15,
    )

    heat_axes: dict[int, Any] = {}
    avg_axes: dict[int, dict[str, Any]] = {}
    cbar_specs: dict[int, Any] = {}
    row_images: dict[int, Any] = {}
    sscs_colorbar_slot: dict[int, Any] = {}
    fixed_cbar_positions: dict[int, tuple[float, float, float, float]] = {}

    for row_i, row_def in enumerate(row_defs):
        avg_keys = list(row_def["avg_keys"])
        hr = [heatmap_h] + [float(avg_height)] * len(avg_keys)
        # More vertical breathing room: heatmap->avg for all rows,
        # and slightly larger spacing when SS and CS avg rows are both present.
        inner_hspace = 0.18 if len(avg_keys) <= 1 else 0.24
        inner = GridSpecFromSubplotSpec(
            1 + len(avg_keys),
            1,
            subplot_spec=outer_gs[row_i, 0],
            height_ratios=hr,
            hspace=inner_hspace,
        )
        ax_h = fig.add_subplot(inner[0])
        heat_axes[row_i] = ax_h
        avg_axes[row_i] = {}
        for k_i, avg_key in enumerate(avg_keys):
            if row_i == 0 and k_i == 0:
                ax_avg = fig.add_subplot(inner[1])
            else:
                share_target = list(avg_axes.values())[0]
                share_ax = share_target[list(share_target.keys())[0]] if len(share_target) > 0 else None
                ax_avg = fig.add_subplot(inner[1 + k_i], sharex=share_ax) if share_ax is not None else fig.add_subplot(inner[1 + k_i])
            avg_axes[row_i][avg_key] = ax_avg

        inner_cb = GridSpecFromSubplotSpec(
            1 + len(avg_keys),
            1,
            subplot_spec=outer_gs[row_i, 1],
            height_ratios=hr,
            hspace=inner_hspace,
        )
        cbar_specs[row_i] = inner_cb[0]
        for k_i in range(len(avg_keys)):
            fig.add_subplot(inner_cb[1 + k_i]).axis("off")
        if row_def["key"] == "sscs":
            sscs_colorbar_slot[row_i] = inner_cb[0]

    if exact_layout:
        fig_w, fig_h = fig.get_size_inches()
        panel_x, panel_y, panel_w, panel_h = [float(v) for v in panel_bbox]
        layout_in = _compute_pf_centered_2session_panel_layout_inches(
            avg_key_counts=[len(list(row_def["avg_keys"])) for row_def in row_defs],
            heatmap_height=float(heatmap_h),
            avg_height=float(avg_height),
            subplot_width=float(fixed_subplot_width),
            show_row_ylabel=bool(show_row_ylabel),
            show_colorbar=bool(show_colorbar),
            show_panel_title=bool(isinstance(panel_title, str) and panel_title.strip()),
        )
        left_in = panel_x * float(fig_w) + float(layout_in["left_margin"])
        top_in = panel_y * float(fig_h) + panel_h * float(fig_h) - float(layout_in["top_margin"])
        subplot_width_in = float(fixed_subplot_width)
        inner_gap_in = float(layout_in["inner_gap"])
        row_gap_in = float(layout_in["row_gap"])
        cbar_x_in = left_in + subplot_width_in + float(layout_in["cbar_gap"])
        cbar_w_in = float(layout_in["cbar_width"])
        row_top_in = top_in
        for row_i, row_def in enumerate(row_defs):
            avg_keys = list(row_def["avg_keys"])
            heat_y0_in = row_top_in - float(heatmap_h)
            heat_axes[row_i].set_position([
                left_in / float(fig_w),
                heat_y0_in / float(fig_h),
                subplot_width_in / float(fig_w),
                float(heatmap_h) / float(fig_h),
            ])
            cursor_top_in = heat_y0_in - inner_gap_in
            for avg_key in avg_keys:
                avg_y0_in = cursor_top_in - float(avg_height)
                avg_axes[row_i][avg_key].set_position([
                    left_in / float(fig_w),
                    avg_y0_in / float(fig_h),
                    subplot_width_in / float(fig_w),
                    float(avg_height) / float(fig_h),
                ])
                cursor_top_in = avg_y0_in - inner_gap_in
            if bool(show_colorbar):
                fixed_cbar_positions[row_i] = (
                    cbar_x_in / float(fig_w),
                    heat_y0_in / float(fig_h),
                    cbar_w_in / float(fig_w),
                    float(heatmap_h) / float(fig_h),
                )
            row_height_in = float(heatmap_h) + len(avg_keys) * (float(avg_height) + inner_gap_in)
            row_top_in -= row_height_in + row_gap_in

    ss_rgb = np.array([2, 108, 128]) / 255.0
    cs_rgb = np.array([238, 155, 0]) / 255.0
    line_colors = {"rate": "#555555", "ss": "#026C80", "cs": "#EE9B00", "theta": "blue", "slow": "red"}
    avg_ranges: dict[str, tuple[float, float]] = {}
    avg_min: dict[str, float] = {"rate": np.inf, "ss": np.inf, "cs": np.inf, "theta": np.inf, "slow": np.inf}
    avg_max: dict[str, float] = {"rate": -np.inf, "ss": -np.inf, "cs": -np.inf, "theta": -np.inf, "slow": -np.inf}
    avg_mean_min: dict[str, float] = {"rate": np.inf, "ss": np.inf, "cs": np.inf, "theta": np.inf, "slow": np.inf}
    avg_mean_max: dict[str, float] = {"rate": -np.inf, "ss": -np.inf, "cs": -np.inf, "theta": -np.inf, "slow": -np.inf}
    rate_legend_added = False

    def _plot_session_mean_sem(ax: Any, metric_key: str) -> None:
        metric_to_stack_key = {
            "rate": "rate_stack",
            "ss": "ss_rate_stack",
            "cs": "cs_rate_stack",
            "theta": "theta_stack",
            "slow": "slow_stack",
        }
        stack_key = metric_to_stack_key.get(metric_key)
        if stack_key is None:
            ax.text(0.5, 0.5, "No data", transform=ax.transAxes, ha="center", va="center", fontsize=5)
            return
        color = line_colors.get(metric_key, "#555555")
        plotted_any = False
        for sess_name, ls in (("session1", "-"), ("session2", "--")):
            mean_tr, sem_tr, _ = _extract_cell_metric_stats_from_all_by_session(
                cell_data,
                stack_key,
                n_time,
                session_idx_filter=sess_name,
                smooth_window=smooth_window,
                avg_smooth_window=avg_smooth_window,
            )
            if mean_tr is None:
                continue
            mean_tr = np.asarray(mean_tr, dtype=float)
            sem_tr = np.asarray(sem_tr, dtype=float) if sem_tr is not None else np.full_like(mean_tr, np.nan)
            ax.plot(time_rel, mean_tr, color=color, linewidth=0.8, linestyle=ls)
            ax.fill_between(time_rel, mean_tr - sem_tr, mean_tr + sem_tr, color=color, alpha=0.15)
            mean_vis = mean_tr[avg_display_mask]
            if np.any(np.isfinite(mean_vis)):
                avg_mean_min[metric_key] = min(avg_mean_min[metric_key], float(np.nanmin(mean_vis)))
                avg_mean_max[metric_key] = max(avg_mean_max[metric_key], float(np.nanmax(mean_vis)))
            vis_lo = (mean_tr - sem_tr)[avg_ylim_mask]
            vis_hi = (mean_tr + sem_tr)[avg_ylim_mask]
            if np.any(np.isfinite(vis_lo)):
                avg_min[metric_key] = min(avg_min[metric_key], float(np.nanmin(vis_lo)))
            if np.any(np.isfinite(vis_hi)):
                avg_max[metric_key] = max(avg_max[metric_key], float(np.nanmax(vis_hi)))
            plotted_any = True
        if not plotted_any:
            ax.text(0.5, 0.5, "No data", transform=ax.transAxes, ha="center", va="center", fontsize=5)
        ax.axvline(center_line_x, color="k", linewidth=0.25, linestyle="--", alpha=0.5)
        if metric_key == "slow":
            ax.axhline(0, color="k", linewidth=0.25, linestyle="--", alpha=0.5)

    def _compute_integer_hz_ticks(y0: float, y1: float) -> np.ndarray:
        if (not np.isfinite(y0)) or (not np.isfinite(y1)) or y1 <= y0:
            return np.array([], dtype=float)
        for step in (5, 2, 1):
            lo = int(np.ceil(y0 / float(step))) * step
            hi = int(np.floor(y1 / float(step))) * step
            if hi < lo:
                continue
            ticks = np.arange(lo, hi + step, step, dtype=float)
            if ticks.size >= 2:
                return ticks
        lo_i = int(np.floor(y0))
        hi_i = int(np.ceil(y1))
        if hi_i <= lo_i:
            return np.array([float(lo_i)], dtype=float)
        return np.array([float(lo_i), float(hi_i)], dtype=float)

    def _compute_fr_two_ticks(y1: float) -> np.ndarray:
        if (not np.isfinite(y1)) or y1 <= 0:
            return np.array([0.0, 1.0], dtype=float)
        if y1 >= 5:
            top = float(int(np.ceil(y1 / 5.0)) * 5)
        else:
            top = float(int(np.ceil(y1)))
        if top <= 0:
            top = 1.0
        return np.array([0.0, top], dtype=float)

    for row_i, row_def in enumerate(row_defs):
        key = str(row_def["key"])
        ax_h = heat_axes[row_i]
        if row_i == 0 and isinstance(panel_title, str) and panel_title.strip():
            ax_h.set_title(panel_title.strip(), fontsize=6, pad=float(panel_title_pad))

        if key == "sscs":
            st_ss = ss_stack
            st_cs = cs_stack
            if (st_ss is None or st_ss.size == 0) and (st_cs is None or st_cs.size == 0):
                ax_h.text(0.5, 0.5, "No data", transform=ax_h.transAxes, ha="center", va="center", fontsize=6)
            else:
                ref_stack = st_ss if st_ss is not None else st_cs
                actual_trials = int(ref_stack.shape[0])
                ss_nan = np.isnan(st_ss) if st_ss is not None else np.ones((actual_trials, n_time), dtype=bool)
                cs_nan = np.isnan(st_cs) if st_cs is not None else np.ones((actual_trials, n_time), dtype=bool)
                both_nan = ss_nan & cs_nan
                ss_norm = (
                    np.clip(np.nan_to_num(st_ss, nan=0.0) / max(ss_vmax, 1e-12), 0, 1)
                    if st_ss is not None
                    else np.zeros((actual_trials, n_time))
                )
                cs_norm = (
                    np.clip(np.nan_to_num(st_cs, nan=0.0) / max(cs_vmax, 1e-12), 0, 1)
                    if st_cs is not None
                    else np.zeros((actual_trials, n_time))
                )
                rgba = np.ones((actual_trials, n_time, 4))
                for ch in range(3):
                    rgba[..., ch] = 1.0 - ss_norm * (1.0 - ss_rgb[ch]) - cs_norm * (1.0 - cs_rgb[ch])
                rgba[..., :3] = np.clip(rgba[..., :3], 0, 1)
                rgba[both_nan] = [0.9, 0.9, 0.9, 1.0]
                ax_h.imshow(
                    rgba,
                    aspect="auto",
                    origin="upper",
                    extent=[time_rel[0], time_rel[-1], actual_trials + 0.5, 0.5],
                    interpolation="nearest",
                    resample=False,
                )
                gap_y = _session_gap_y(actual_trials)
                if gap_y is not None:
                    ax_h.axhline(gap_y, color=session_gap_line_color, linewidth=session_gap_line_width, alpha=0.9)
        else:
            stack = stacks_by_key.get(key)
            if stack is None or stack.size == 0:
                ax_h.text(0.5, 0.5, "No data", transform=ax_h.transAxes, ha="center", va="center", fontsize=6)
            else:
                cmap_use = "Greys"
                if key == "ss":
                    cmap_use = "BuGn"
                elif key == "cs":
                    cmap_use = "YlOrBr"
                elif key == "theta":
                    cmap_use = "Blues"
                elif key == "slow":
                    cmap_use = "RdBu_r"
                cmap_obj = plt.get_cmap(cmap_use).copy()
                cmap_obj.set_bad(color=[0.9, 0.9, 0.9, 1.0])
                actual_trials = int(stack.shape[0])
                im = ax_h.imshow(
                    stack,
                    aspect="auto",
                    origin="upper",
                    extent=[time_rel[0], time_rel[-1], actual_trials + 0.5, 0.5],
                    cmap=cmap_obj,
                    vmin=float(row_def["vmin"]),
                    vmax=float(row_def["vmax"]),
                    interpolation="nearest",
                    resample=False,
                )
                if bool(merge_plateau) and key == "rate" and plateau_stack is not None and plateau_stack.size > 0 and np.any(plateau_stack != 0):
                    p_abs = np.abs(plateau_stack)
                    p_vmax = float(plateau_vlim) if float(plateau_vlim) > 0 else 0.1
                    p_norm = np.clip(p_abs / p_vmax, 0, 1)
                    rgba_p = np.zeros((*plateau_stack.shape, 4))
                    rgba_p[..., 0] = 1.0
                    rgba_p[..., 3] = np.where(plateau_stack != 0, p_norm * 0.8, 0.0)
                    ax_h.imshow(
                        rgba_p,
                        aspect="auto",
                        origin="upper",
                        extent=[time_rel[0], time_rel[-1], actual_trials + 0.5, 0.5],
                        interpolation="nearest",
                        resample=False,
                    )
                gap_y = _session_gap_y(actual_trials)
                if gap_y is not None:
                    ax_h.axhline(gap_y, color=session_gap_line_color, linewidth=session_gap_line_width, alpha=0.9)
                row_images[row_i] = im

        ax_h.axvline(center_line_x, color="k", linewidth=0.25, linestyle="--", alpha=0.5)
        ax_h.set_xlim(xlim)
        ax_h.set_ylim(n_trials + 0.5, 0.5)
        if bool(show_row_ylabel):
            ax_h.set_ylabel(str(row_def["label"]), fontsize=6, labelpad=9)
            ax_h.set_yticks([1, n_trials] if n_trials > 1 else [1])
            ax_h.tick_params(labelsize=5, labelleft=True)
        else:
            ax_h.set_ylabel("")
            if bool(show_heatmap_yticks):
                ax_h.set_yticks([1, n_trials] if n_trials > 1 else [1])
                ax_h.tick_params(labelsize=5, labelleft=True)
            else:
                ax_h.set_yticks([])
                ax_h.tick_params(labelleft=False)
        ax_h.tick_params(labelbottom=False)

        for avg_key, ax_avg in avg_axes[row_i].items():
            _plot_session_mean_sem(ax_avg, avg_key)
            if bool(show_rate_session_legend) and (not rate_legend_added) and row_i == 0 and avg_key == "rate":
                rate_stack_local = stacks_by_key.get("rate")
                sess_vals = np.array([], dtype=int)
                if rate_stack_local is not None and rate_stack_local.ndim == 2 and rate_stack_local.shape[0] > 0:
                    sess_vals = np.sort(np.unique(_session_idx_for_n(rate_stack_local.shape[0]).astype(int)))
                handles: list[Line2D] = []
                s1_named, s2_named = _resolve_two_session_label_values(sess_vals)
                if s1_named is not None and np.any(sess_vals == int(s1_named)):
                    handles.append(Line2D([0], [0], color="#555555", linewidth=0.8, linestyle="-", label=str(phase_labels_use[0])))
                if s2_named is not None and np.any(sess_vals == int(s2_named)):
                    handles.append(Line2D([0], [0], color="#555555", linewidth=0.8, linestyle="--", label=str(phase_labels_use[1])))
                ax_avg.legend(
                    handles=handles,
                    fontsize=4,
                    frameon=False,
                    loc="upper left",
                    bbox_to_anchor=(0.80, 1.0),
                    borderaxespad=0.0,
                    handlelength=2.0,
                )
                rate_legend_added = True
            ax_avg.set_xlim(xlim)
            if avg_key == list(avg_axes[row_i].keys())[-1] and row_i == n_rows - 1:
                ax_avg.set_xlabel(x_label, fontsize=6)
            else:
                ax_avg.tick_params(labelbottom=False)
            if bool(show_avg_yticks_left_only):
                ax_avg.tick_params(labelsize=5, labelleft=bool(show_row_ylabel))
            else:
                ax_avg.tick_params(labelsize=5)
            ax_avg.yaxis.set_major_formatter(FuncFormatter(_format_avg_axis_ticklabel))
            ax_avg.spines["top"].set_visible(False)
            ax_avg.spines["right"].set_visible(False)

    for metric in ("rate", "ss", "cs", "theta", "slow"):
        y0 = y1 = None
        if isinstance(avg_ylim_override, dict) and metric in avg_ylim_override:
            yp = avg_ylim_override.get(metric)
            if isinstance(yp, (tuple, list)) and len(yp) == 2:
                y0 = float(yp[0])
                y1 = float(yp[1])
        if y0 is None or y1 is None:
            candidates_lo: list[float] = []
            candidates_hi: list[float] = []
            if np.isfinite(avg_min.get(metric, np.inf)) and np.isfinite(avg_max.get(metric, -np.inf)):
                candidates_lo.append(float(avg_min[metric]))
                candidates_hi.append(float(avg_max[metric]))
            if np.isfinite(avg_mean_min.get(metric, np.inf)) and np.isfinite(avg_mean_max.get(metric, -np.inf)):
                candidates_lo.append(float(avg_mean_min[metric]))
                candidates_hi.append(float(avg_mean_max[metric]))
            if len(candidates_lo) > 0 and len(candidates_hi) > 0:
                y0 = float(min(candidates_lo))
                y1 = float(max(candidates_hi))
                if np.isclose(y0, y1):
                    eps = 1e-6 if np.isfinite(y0) else 1.0
                    y0 = float(y0 - eps)
                    y1 = float(y1 + eps)
        if y0 is None or y1 is None or (not np.isfinite(y0)) or (not np.isfinite(y1)):
            continue
        mean_y0 = avg_mean_min.get(metric, np.inf)
        mean_y1 = avg_mean_max.get(metric, -np.inf)
        if np.isfinite(mean_y0):
            y0 = min(float(y0), float(mean_y0))
        if np.isfinite(mean_y1):
            y1 = max(float(y1), float(mean_y1))
        if metric in ("rate", "ss", "cs"):
            y0 = min(float(y0), 0.0)
        elif metric == "theta":
            # Keep the preferred zero baseline for theta, but do not clip the mean if it dips slightly below zero.
            y0 = min(float(y0), 0.0)
            if (not np.isfinite(y1)) or y1 <= y0:
                y1 = y0 + 1e-6
        if y1 <= y0:
            y1 = y0 + 1e-6
        pad_ref = max(float(y1 - y0), abs(float(y0)), abs(float(y1)), 1.0)
        pad = max(1e-6, 0.02 * pad_ref)
        if metric in ("rate", "ss", "cs", "theta") and y0 >= 0:
            y1 = float(y1) + pad
        else:
            y0 = float(y0) - pad
            y1 = float(y1) + pad
        avg_ranges[metric] = (y0, y1)
        for row_i, row_def in enumerate(row_defs):
            for avg_key, ax_avg in avg_axes[row_i].items():
                if avg_key == metric:
                    ax_avg.set_ylim(y0, y1)
                    if metric in ("rate", "ss", "cs"):
                        ax_avg.set_yticks(_compute_fr_two_ticks(y1))

    for row_i, row_def in enumerate(row_defs):
        if not bool(show_colorbar):
            fig.add_subplot(cbar_specs[row_i]).axis("off")
            continue
        key = str(row_def["key"])
        if key == "sscs":
            gs_inner = GridSpecFromSubplotSpec(2, 1, subplot_spec=sscs_colorbar_slot[row_i], hspace=0.4)
            ss_cmap = LinearSegmentedColormap.from_list("ss_teal", ["white", "#026C80"])
            cs_cmap = LinearSegmentedColormap.from_list("cs_orange", ["white", "#EE9B00"])

            ax_ss_cb = fig.add_subplot(gs_inner[0])
            sm_ss = ScalarMappable(cmap=ss_cmap, norm=Normalize(vmin=0, vmax=max(ss_vmax, 1e-12)))
            sm_ss.set_array([])
            cb_ss = fig.colorbar(sm_ss, cax=ax_ss_cb)
            cb_ss.ax.tick_params(labelsize=4)
            cb_ss.set_label("SS", fontsize=4, rotation=0, labelpad=8)

            ax_cs_cb = fig.add_subplot(gs_inner[1])
            sm_cs = ScalarMappable(cmap=cs_cmap, norm=Normalize(vmin=0, vmax=max(cs_vmax, 1e-12)))
            sm_cs.set_array([])
            cb_cs = fig.colorbar(sm_cs, cax=ax_cs_cb)
            cb_cs.ax.tick_params(labelsize=4)
            cb_cs.set_label("CS", fontsize=4, rotation=0, labelpad=8)
            if exact_layout and row_i in fixed_cbar_positions:
                x0, y0, w0, h0 = fixed_cbar_positions[row_i]
                cb_gap_in = 0.06
                cb_gap = cb_gap_in / float(fig.get_size_inches()[1])
                cb_half_h = max(0.0, (h0 - cb_gap) / 2.0)
                ax_ss_cb.set_position([x0, y0 + cb_half_h + cb_gap, w0, cb_half_h])
                ax_cs_cb.set_position([x0, y0, w0, cb_half_h])
        elif row_i in row_images:
            ax_cb = fig.add_subplot(cbar_specs[row_i])
            cbar = fig.colorbar(row_images[row_i], cax=ax_cb)
            cbar.ax.tick_params(labelsize=4)
            if exact_layout and row_i in fixed_cbar_positions:
                ax_cb.set_position(list(fixed_cbar_positions[row_i]))
        else:
            fig.add_subplot(cbar_specs[row_i]).axis("off")

    if bool(Plot_plateaus):
        has_plateau_events = _plateau_trace_entry_has_events(entry_data)
        if plateau_column_bbox is not None or has_plateau_events:
            bbox_use = plateau_column_bbox
            if bbox_use is None:
                axes_for_bbox = list(heat_axes.values())
                for avg_map in avg_axes.values():
                    axes_for_bbox.extend(list(avg_map.values()))
                if axes_for_bbox:
                    x_right = max(ax.get_position().x1 for ax in axes_for_bbox)
                    y0 = min(ax.get_position().y0 for ax in axes_for_bbox)
                    y1 = max(ax.get_position().y1 for ax in axes_for_bbox)
                    width = max(0.04, min(0.12, (1.0 - x_right) * 0.75))
                    bbox_use = (x_right + 0.01, y0, width, y1 - y0)
            if bbox_use is not None:
                xlim_use = (
                    tuple(float(v) for v in plateau_trace_xlim)
                    if plateau_trace_xlim is not None and len(plateau_trace_xlim) == 2
                    else _compute_plateau_trace_xlim_for_entries([entry_data])
                )
                _plot_plateau_trace_events_column(
                    fig,
                    entry_data,
                    bbox_use,
                    xlim=xlim_use,
                    title=plateau_column_title,
                    show_scale_bars=bool(show_plateau_scale_bars),
                    shared_ylim=plateau_trace_ylim,
                    plateau_height_per_spkh=plateau_height_per_spkh,
                )

    if apply_tight_layout and (not exact_layout):
        try:
            tight_fn = getattr(fig, "tight_layout", None)
            if callable(tight_fn):
                tight_fn()
        except Exception:
            pass
    return avg_ranges


def _compute_dual_pf_fr_colorbar_vmax_from_session_means(
    entry_primary: dict[str, Any],
    entry_secondary: dict[str, Any] | None,
    time_rel: np.ndarray,
    *,
    smooth_window: int = 0,
    avg_smooth_window: int = 0,
    interpolate_nan: bool = True,
) -> dict[str, float]:
    """Colorbar vmax for FR stacks from session-split mean traces across PF1/PF2."""
    n_time = int(len(time_rel))
    metric_to_stack = {
        "rate": "rate_stack",
        "ss": "ss_rate_stack",
        "cs": "cs_rate_stack",
    }

    def _smooth_stack(stack: np.ndarray) -> np.ndarray:
        if bool(interpolate_nan):
            stack = _interpolate_nan_stack_rows(stack)
        if int(smooth_window) <= 1:
            return stack
        out = np.full_like(stack, np.nan)
        for i in range(stack.shape[0]):
            out[i] = _smooth_boxcar(stack[i], int(smooth_window))
        return out

    def _smooth_trace(trace: np.ndarray) -> np.ndarray:
        if int(avg_smooth_window) <= 1:
            return trace
        return _smooth_boxcar(trace, int(avg_smooth_window))

    def _session_idx(dir_data: dict[str, Any], n_trials: int) -> np.ndarray:
        td = dir_data.get("trial_data", {}) if isinstance(dir_data, dict) else {}
        sess = np.asarray(td.get("session_idx", []), dtype=int) if isinstance(td, dict) else np.array([], dtype=int)
        if sess.ndim == 1 and sess.size == int(n_trials):
            return sess
        return np.zeros(int(n_trials), dtype=int)

    maxima: dict[str, list[float]] = {"rate": [], "ss": [], "cs": []}
    for entry in [entry_primary, entry_secondary]:
        if entry is None:
            continue
        cell_data = entry.get("data", {})
        all_data = cell_data.get("all", {}) if isinstance(cell_data, dict) else {}
        for metric_key, stack_key in metric_to_stack.items():
            stack = all_data.get(stack_key)
            if stack is None:
                continue
            stack = np.asarray(stack, dtype=float)
            if stack.ndim != 2 or stack.shape[1] != n_time or stack.shape[0] == 0:
                continue
            stack = _smooth_stack(stack)
            sess = _session_idx(all_data, stack.shape[0])
            for s_val in np.sort(np.unique(sess.astype(int))):
                mask = sess == int(s_val)
                if not np.any(mask):
                    continue
                mean_trace = np.nanmean(stack[mask], axis=0)
                mean_trace = _smooth_trace(np.asarray(mean_trace, dtype=float))
                finite = mean_trace[np.isfinite(mean_trace)]
                if finite.size == 0:
                    continue
                maxima[metric_key].append(float(np.max(finite)))

    out: dict[str, float] = {}
    for key, vals in maxima.items():
        if len(vals) == 0:
            continue
        vmax = float(np.nanmax(np.asarray(vals, dtype=float)))
        if np.isfinite(vmax) and vmax > 0:
            out[key] = vmax
    return out


def _compute_shared_avg_ylim_for_metrics_2sessions(
    entry_primary: dict[str, Any],
    entry_secondary: dict[str, Any] | None,
    time_rel: np.ndarray,
    *,
    smooth_window: int = 0,
    avg_smooth_window: int = 0,
    interpolate_nan: bool = True,
    avg_ylim_focus_window: tuple[float, float] | None = None,
    xlim: tuple[float, float] | None = None,
) -> dict[str, tuple[float, float]]:
    """Compute shared avg y-limits (mean±SEM) for theta/slow across PF1/PF2 and sessions."""
    time_rel = np.asarray(time_rel, dtype=float)
    n_time = int(len(time_rel))
    if avg_ylim_focus_window is None:
        focus_mask_theta = (np.ones(n_time, dtype=bool) if xlim is None else (time_rel >= float(xlim[0])) & (time_rel <= float(xlim[1])))
    else:
        w0, w1 = float(avg_ylim_focus_window[0]), float(avg_ylim_focus_window[1])
        if w1 < w0:
            w0, w1 = w1, w0
        focus_mask_theta = (time_rel >= w0) & (time_rel <= w1)
    if not np.any(focus_mask_theta):
        focus_mask_theta = np.ones(n_time, dtype=bool)
    # Slow Vm should not depend on the focus window; use displayed x-range (or full trace).
    focus_mask_slow = (np.ones(n_time, dtype=bool) if xlim is None else (time_rel >= float(xlim[0])) & (time_rel <= float(xlim[1])))
    if not np.any(focus_mask_slow):
        focus_mask_slow = np.ones(n_time, dtype=bool)

    def _smooth_stack(stack: np.ndarray) -> np.ndarray:
        if bool(interpolate_nan):
            stack = _interpolate_nan_stack_rows(stack)
        if int(smooth_window) <= 1:
            return stack
        out = np.full_like(stack, np.nan)
        for i in range(stack.shape[0]):
            out[i] = _smooth_boxcar(stack[i], int(smooth_window))
        return out

    def _smooth_trace(trace: np.ndarray) -> np.ndarray:
        if int(avg_smooth_window) <= 1:
            return trace
        return _smooth_boxcar(trace, int(avg_smooth_window))

    def _session_idx(dir_data: dict[str, Any], n_trials: int) -> np.ndarray:
        td = dir_data.get("trial_data", {}) if isinstance(dir_data, dict) else {}
        sess = np.asarray(td.get("session_idx", []), dtype=int) if isinstance(td, dict) else np.array([], dtype=int)
        if sess.ndim == 1 and sess.size == int(n_trials):
            return sess
        return np.zeros(int(n_trials), dtype=int)

    metric_to_stack = {"theta": "theta_stack", "slow": "slow_stack"}
    lo: dict[str, float] = {k: np.inf for k in metric_to_stack}
    hi: dict[str, float] = {k: -np.inf for k in metric_to_stack}

    for entry in [entry_primary, entry_secondary]:
        if entry is None:
            continue
        cell_data = entry.get("data", {})
        all_data = cell_data.get("all", {}) if isinstance(cell_data, dict) else {}
        for metric, stack_key in metric_to_stack.items():
            stack = all_data.get(stack_key)
            if stack is None:
                continue
            stack = np.asarray(stack, dtype=float)
            if stack.ndim != 2 or stack.shape[1] != n_time or stack.shape[0] == 0:
                continue
            stack = _smooth_stack(stack)
            sess = _session_idx(all_data, stack.shape[0])
            for s_val in np.sort(np.unique(sess.astype(int))):
                mask = sess == int(s_val)
                if not np.any(mask):
                    continue
                sub = stack[mask]
                mean_tr = _smooth_trace(np.asarray(np.nanmean(sub, axis=0), dtype=float))
                n_valid = np.sum(np.isfinite(sub), axis=0)
                sem_tr = _smooth_trace(np.asarray(np.nanstd(sub, axis=0) / np.sqrt(np.maximum(n_valid, 1)), dtype=float))
                mask_use = focus_mask_theta if metric == "theta" else focus_mask_slow
                vis_lo = (mean_tr - sem_tr)[mask_use]
                vis_hi = (mean_tr + sem_tr)[mask_use]
                if np.any(np.isfinite(vis_lo)):
                    lo[metric] = min(lo[metric], float(np.nanmin(vis_lo)))
                if np.any(np.isfinite(vis_hi)):
                    hi[metric] = max(hi[metric], float(np.nanmax(vis_hi)))

    out: dict[str, tuple[float, float]] = {}
    for metric in ("theta", "slow"):
        y0 = float(lo[metric])
        y1 = float(hi[metric])
        if (not np.isfinite(y0)) or (not np.isfinite(y1)):
            continue
        if metric == "theta":
            y0 = 0.0
            if y1 <= y0:
                y1 = y0 + 1e-6
        elif np.isclose(y0, y1):
            y0 -= 1e-6
            y1 += 1e-6
        out[metric] = (y0, y1)
    return out


def plot_pf_centered_dual_component_heatmap_2sessions(
    entry_primary: dict[str, Any],
    entry_secondary: dict[str, Any] | None,
    time_rel: np.ndarray,
    *,
    smooth_window: int = 0,
    out_path: str | Path | None = None,
    show_plot: bool = True,
    interpolate_nan: bool = True,
    fr_vmax_scale: float = 0.6,
    rate_colorbar_vmax: float | None = None,
    subplot_width: float | None = None,
    theta_vlim: tuple[float, float] = (0, 0.5),
    slow_vlim: tuple[float, float] = (-0.4, 0.4),
    fig_width: float = 3.8,
    trial_height: float = 0.02,
    heatmap_height: float | None = None,
    xlim: tuple[float, float] = (-4, 4),
    merge_ss_cs: bool = True,
    merge_plateau: bool = True,
    smooth_plateau: bool = False,
    plateau_vlim: float = 0.01,
    avg_height: float = 0.3,
    avg_smooth_window: int = 0,
    x_label: str = "Distance (cm)",
    center_line_x: float = 0.0,
    show_session_gap_line: bool = True,
    disable_pf2_avg_ylim_sync: bool = False,
    avg_ylim_focus_window: tuple[float, float] | None = None,
    Plot_plateaus: bool = True,
    plateau_height_per_spkh: float = 0.15,
    phase_labels: tuple[str, str] | list[str] | None = None,
) -> plt.Figure:
    plateau_height_per_spkh = float(plateau_height_per_spkh)
    if (not np.isfinite(plateau_height_per_spkh)) or plateau_height_per_spkh <= 0:
        raise ValueError("plateau_height_per_spkh must be a finite number > 0.")
    phase_labels_use = _normalize_two_phase_labels(phase_labels)
    if rate_colorbar_vmax is not None:
        rate_colorbar_vmax = float(rate_colorbar_vmax)
        if (not np.isfinite(rate_colorbar_vmax)) or rate_colorbar_vmax <= 0:
            raise ValueError("rate_colorbar_vmax must be a finite number > 0.")
    if subplot_width is not None:
        subplot_width = float(subplot_width)
        if (not np.isfinite(subplot_width)) or subplot_width <= 0:
            raise ValueError("subplot_width must be a finite number > 0.")
    if heatmap_height is not None:
        heatmap_height = float(heatmap_height)
        if (not np.isfinite(heatmap_height)) or heatmap_height <= 0:
            raise ValueError("heatmap_height must be a finite number > 0.")

    def _pf_specific_xlabel(base_label: str, pf_rank: int) -> str:
        base = str(base_label)
        if "PF1 peak" in base or "PF2 peak" in base:
            return base.replace("PF1 peak", f"PF{pf_rank} peak").replace("PF2 peak", f"PF{pf_rank} peak")
        if "PF peak" in base:
            return base.replace("PF peak", f"PF{pf_rank} peak")
        if "Distance" in base and "(cm)" in base:
            return f"Distance from PF{pf_rank} peak (cm)"
        return f"{base} (PF{pf_rank})"

    def _apply_rate_colorbar_override(colorbar_vmax_override: dict[str, float]) -> dict[str, float]:
        colorbar_vmax_use = dict(colorbar_vmax_override)
        if rate_colorbar_vmax is not None:
            colorbar_vmax_use["rate"] = float(rate_colorbar_vmax)
        return colorbar_vmax_use

    time_rel = np.asarray(time_rel, dtype=float)
    exact_layout = subplot_width is not None
    plot_plateau_columns = bool(Plot_plateaus) and (
        _plateau_trace_entry_has_events(entry_primary)
        or _plateau_trace_entry_has_events(entry_secondary)
    )
    plateau_gap_in = 0.08
    plateau_col_width_in = (
        max(0.28, min(0.55, 0.70 * float(subplot_width)))
        if exact_layout and subplot_width is not None
        else 0.35
    )
    plateau_trace_xlim = _compute_plateau_trace_xlim_for_entries([entry_primary, entry_secondary])
    plateau_trace_ylim = _compute_plateau_trace_ylim_for_entries(
        [entry_primary, entry_secondary],
        include_scale_bars=True,
        plateau_height_per_spkh=plateau_height_per_spkh,
    )
    primary_has_plateaus = _plateau_trace_entry_has_events(entry_primary)
    secondary_has_plateaus = _plateau_trace_entry_has_events(entry_secondary)
    primary_show_plateau_scale = bool(primary_has_plateaus or not secondary_has_plateaus)
    secondary_show_plateau_scale = bool((not primary_has_plateaus) and secondary_has_plateaus)
    if entry_secondary is None:
        fixed_heatmap_height_use = (
            float(heatmap_height)
            if heatmap_height is not None
            else None
        )
        if exact_layout and fixed_heatmap_height_use is None:
            fixed_heatmap_height_use = (
                _compute_single_heatmap_max_trials(entry_primary, time_rel, direction_keys=("all", "cw", "ccw"))
                * float(trial_height)
            )
        fig_h = _estimate_single_heatmap_figure_height(
            entry_primary,
            time_rel,
            trial_height=trial_height,
            avg_height=avg_height,
            merge_ss_cs=merge_ss_cs,
            fixed_heatmap_height=fixed_heatmap_height_use,
        )
        if exact_layout:
            n_rows = 4 if bool(merge_ss_cs) else 5
            avg_key_counts = [1] * n_rows
            if bool(merge_ss_cs):
                avg_key_counts[1] = 2
            panel_layout = _compute_pf_centered_2session_panel_layout_inches(
                avg_key_counts=avg_key_counts,
                heatmap_height=float(fixed_heatmap_height_use),
                avg_height=float(avg_height),
                subplot_width=float(subplot_width),
                show_row_ylabel=True,
                show_colorbar=True,
                show_panel_title=False,
            )
            panel_width = float(panel_layout["panel_width"])
            panel_height = float(panel_layout["panel_height"])
            fig_w = panel_width + ((plateau_gap_in + plateau_col_width_in) if plot_plateau_columns else 0.0)
            fig = plt.figure(figsize=(fig_w, panel_height))
            panel_bbox_single = (0.0, 0.0, panel_width / fig_w, 1.0)
            plateau_bbox_single = (
                ((panel_width + plateau_gap_in) / fig_w, 0.0, plateau_col_width_in / fig_w, 1.0)
                if plot_plateau_columns
                else None
            )
        else:
            fig = plt.figure(figsize=(fig_width, fig_h))
            panel_bbox_single = None
            plateau_bbox_single = None
        colorbar_vmax_override = _compute_dual_pf_fr_colorbar_vmax_from_session_means(
            entry_primary,
            None,
            time_rel,
            smooth_window=int(smooth_window),
            avg_smooth_window=int(avg_smooth_window),
            interpolate_nan=bool(interpolate_nan),
        )
        colorbar_vmax_override = _apply_rate_colorbar_override(colorbar_vmax_override)
        _plot_single_cell_heatmap_on_figure_2sessions(
            fig,
            entry_primary,
            time_rel,
            interpolate_nan=interpolate_nan,
            smooth_window=smooth_window,
            fr_vmax_scale=fr_vmax_scale,
            theta_vlim=theta_vlim,
            slow_vlim=slow_vlim,
            trial_height=trial_height,
            xlim=xlim,
            merge_ss_cs=merge_ss_cs,
            merge_plateau=merge_plateau,
            smooth_plateau=smooth_plateau,
            plateau_vlim=plateau_vlim,
            avg_height=avg_height,
            avg_smooth_window=avg_smooth_window,
            x_label=x_label,
            center_line_x=center_line_x,
            show_session_gap_line=show_session_gap_line,
            colorbar_vmax_override=colorbar_vmax_override,
            show_row_ylabel=True,
            show_heatmap_yticks=True,
            show_colorbar=True,
            show_avg_yticks_left_only=True,
            show_rate_session_legend=True,
            panel_title=None,
            avg_ylim_focus_window=avg_ylim_focus_window,
            fixed_heatmap_height=fixed_heatmap_height_use,
            fixed_subplot_width=subplot_width,
            panel_bbox=(panel_bbox_single if exact_layout else None),
            apply_tight_layout=(not exact_layout),
            Plot_plateaus=bool(Plot_plateaus),
            plateau_column_bbox=plateau_bbox_single,
            plateau_trace_xlim=plateau_trace_xlim,
            plateau_trace_ylim=plateau_trace_ylim,
            plateau_height_per_spkh=plateau_height_per_spkh,
            show_plateau_scale_bars=True,
            plateau_column_title="Plateaus",
            phase_labels=phase_labels_use,
        )
        if out_path is not None:
            fig.savefig(out_path, dpi=300)
        if show_plot:
            plt.show()
        else:
            plt.close(fig)
        return fig

    fr_vmax_override = _compute_single_cell_fr_vmaxs(
        entry_primary,
        time_rel,
        smooth_window=int(smooth_window),
        interpolate_nan=bool(interpolate_nan),
    )
    colorbar_vmax_override = _compute_dual_pf_fr_colorbar_vmax_from_session_means(
        entry_primary,
        entry_secondary,
        time_rel,
        smooth_window=int(smooth_window),
        avg_smooth_window=int(avg_smooth_window),
        interpolate_nan=bool(interpolate_nan),
    )
    colorbar_vmax_override = _apply_rate_colorbar_override(colorbar_vmax_override)
    theta_slow_shared = _compute_shared_avg_ylim_for_metrics_2sessions(
        entry_primary,
        entry_secondary,
        time_rel,
        smooth_window=int(smooth_window),
        avg_smooth_window=int(avg_smooth_window),
        interpolate_nan=bool(interpolate_nan),
        avg_ylim_focus_window=avg_ylim_focus_window,
        xlim=xlim,
    )

    if heatmap_height is not None:
        fixed_heatmap_height = float(heatmap_height)
    else:
        max_trials_primary = _compute_single_heatmap_max_trials(entry_primary, time_rel)
        max_trials_secondary = _compute_single_heatmap_max_trials(entry_secondary, time_rel)
        fixed_heatmap_height = max(max_trials_primary, max_trials_secondary) * float(trial_height)
    if exact_layout:
        n_rows = 4 if bool(merge_ss_cs) else 5
        avg_key_counts = [1] * n_rows
        if bool(merge_ss_cs):
            avg_key_counts[1] = 2
        left_layout = _compute_pf_centered_2session_panel_layout_inches(
            avg_key_counts=avg_key_counts,
            heatmap_height=float(fixed_heatmap_height),
            avg_height=float(avg_height),
            subplot_width=float(subplot_width),
            show_row_ylabel=True,
            show_colorbar=False,
            show_panel_title=True,
        )
        right_layout = _compute_pf_centered_2session_panel_layout_inches(
            avg_key_counts=avg_key_counts,
            heatmap_height=float(fixed_heatmap_height),
            avg_height=float(avg_height),
            subplot_width=float(subplot_width),
            show_row_ylabel=False,
            show_colorbar=True,
            show_panel_title=True,
        )
        panel_gap = 0.18
        left_panel_width = float(left_layout["panel_width"])
        right_panel_width = float(right_layout["panel_width"])
        left_total_width = left_panel_width + ((plateau_gap_in + plateau_col_width_in) if plot_plateau_columns else 0.0)
        right_total_width = right_panel_width + ((plateau_gap_in + plateau_col_width_in) if plot_plateau_columns else 0.0)
        fig_w = float(left_total_width) + float(panel_gap) + float(right_total_width)
        fig_h = max(float(left_layout["panel_height"]), float(right_layout["panel_height"]))
        fig = plt.figure(figsize=(fig_w, fig_h))
        left_bbox = (0.0, 0.0, left_panel_width / fig_w, 1.0)
        left_plateau_bbox = (
            ((left_panel_width + plateau_gap_in) / fig_w, 0.0, plateau_col_width_in / fig_w, 1.0)
            if plot_plateau_columns
            else None
        )
        right_x0 = (float(left_total_width) + float(panel_gap)) / fig_w
        right_bbox = (
            right_x0,
            0.0,
            right_panel_width / fig_w,
            1.0,
        )
        right_plateau_bbox = (
            (
                (float(left_total_width) + float(panel_gap) + right_panel_width + plateau_gap_in) / fig_w,
                0.0,
                plateau_col_width_in / fig_w,
                1.0,
            )
            if plot_plateau_columns
            else None
        )
        subfigs = None
    else:
        h1 = _estimate_single_heatmap_figure_height(
            entry_primary, time_rel, trial_height=trial_height, avg_height=avg_height, merge_ss_cs=merge_ss_cs
        )
        h2 = _estimate_single_heatmap_figure_height(
            entry_secondary, time_rel, trial_height=trial_height, avg_height=avg_height, merge_ss_cs=merge_ss_cs
        )
        fig = plt.figure(figsize=(fig_width * 2 + 0.45 + (0.9 if plot_plateau_columns else 0.0), max(h1, h2)))
        subfigs = fig.subfigures(1, 2, wspace=0.04)
        subfigs = list(np.ravel(subfigs))
        left_bbox = None
        right_bbox = None
        left_plateau_bbox = None
        right_plateau_bbox = None
    x_label_pf1 = _pf_specific_xlabel(x_label, 1)
    x_label_pf2 = _pf_specific_xlabel(x_label, 2)

    pf1_avg_ylim = _plot_single_cell_heatmap_on_figure_2sessions(
        (fig if exact_layout else subfigs[0]),
        entry_primary,
        time_rel,
        interpolate_nan=interpolate_nan,
        smooth_window=smooth_window,
        fr_vmax_scale=fr_vmax_scale,
        theta_vlim=theta_vlim,
        slow_vlim=slow_vlim,
        trial_height=trial_height,
        xlim=xlim,
        merge_ss_cs=merge_ss_cs,
        merge_plateau=merge_plateau,
        smooth_plateau=smooth_plateau,
        plateau_vlim=plateau_vlim,
        avg_height=avg_height,
        avg_smooth_window=avg_smooth_window,
        x_label=x_label_pf1,
        center_line_x=center_line_x,
        show_session_gap_line=show_session_gap_line,
        fr_vmax_override=fr_vmax_override,
        colorbar_vmax_override=colorbar_vmax_override,
        avg_ylim_override=(theta_slow_shared if len(theta_slow_shared) > 0 else None),
        fixed_heatmap_height=fixed_heatmap_height,
        fixed_subplot_width=subplot_width,
        panel_bbox=left_bbox,
        show_row_ylabel=True,
        show_heatmap_yticks=True,
        show_colorbar=False,
        show_avg_yticks_left_only=True,
        show_rate_session_legend=True,
        panel_title="PF1",
        panel_title_pad=1.0,
        avg_ylim_focus_window=avg_ylim_focus_window,
        apply_tight_layout=(not exact_layout),
        Plot_plateaus=bool(Plot_plateaus),
        plateau_column_bbox=left_plateau_bbox,
        plateau_trace_xlim=plateau_trace_xlim,
        plateau_trace_ylim=plateau_trace_ylim,
        plateau_height_per_spkh=plateau_height_per_spkh,
        show_plateau_scale_bars=primary_show_plateau_scale,
        plateau_column_title="PF1 plateaus",
        phase_labels=phase_labels_use,
    )
    _plot_single_cell_heatmap_on_figure_2sessions(
        (fig if exact_layout else subfigs[1]),
        entry_secondary,
        time_rel,
        interpolate_nan=interpolate_nan,
        smooth_window=smooth_window,
        fr_vmax_scale=fr_vmax_scale,
        theta_vlim=theta_vlim,
        slow_vlim=slow_vlim,
        trial_height=trial_height,
        xlim=xlim,
        merge_ss_cs=merge_ss_cs,
        merge_plateau=merge_plateau,
        smooth_plateau=smooth_plateau,
        plateau_vlim=plateau_vlim,
        avg_height=avg_height,
        avg_smooth_window=avg_smooth_window,
        x_label=x_label_pf2,
        center_line_x=center_line_x,
        show_session_gap_line=show_session_gap_line,
        fr_vmax_override=fr_vmax_override,
        colorbar_vmax_override=colorbar_vmax_override,
        avg_ylim_override=(
            (
                {
                    **({} if bool(disable_pf2_avg_ylim_sync) else dict(pf1_avg_ylim)),
                    **theta_slow_shared,
                }
            )
            if (len(theta_slow_shared) > 0 or (not bool(disable_pf2_avg_ylim_sync)))
            else None
        ),
        fixed_heatmap_height=fixed_heatmap_height,
        fixed_subplot_width=subplot_width,
        panel_bbox=right_bbox,
        show_row_ylabel=False,
        show_heatmap_yticks=True,
        show_colorbar=True,
        show_avg_yticks_left_only=(not bool(disable_pf2_avg_ylim_sync)),
        show_rate_session_legend=False,
        panel_title="PF2",
        panel_title_pad=1.0,
        avg_ylim_focus_window=avg_ylim_focus_window,
        apply_tight_layout=(not exact_layout),
        Plot_plateaus=bool(Plot_plateaus),
        plateau_column_bbox=right_plateau_bbox,
        plateau_trace_xlim=plateau_trace_xlim,
        plateau_trace_ylim=plateau_trace_ylim,
        plateau_height_per_spkh=plateau_height_per_spkh,
        show_plateau_scale_bars=secondary_show_plateau_scale,
        plateau_column_title="PF2 plateaus",
        phase_labels=phase_labels_use,
    )

    if out_path is not None:
        fig.savefig(out_path, dpi=300)
    if show_plot:
        plt.show()
    else:
        plt.close(fig)
    return fig


def generate_pf_centered_component_heatmaps_2sessions(
    dataset: dict[str, Any],
    *,
    figure_save_folder: str | Path,
    clear_output: bool = True,
    interpolate_nan: bool = True,
    smooth_window: int = 300,
    fr_vmax_scale: float = 0.6,
    rate_colorbar_vmax: float | None = None,
    avg_height: float = 0.3,
    subplot_width: float | None = None,
    theta_vlim: tuple[float, float] = (0, 0.5),
    slow_vlim: tuple[float, float] = (-0.4, 0.4),
    fig_width: float = 3.8,
    trial_height: float = 0.02,
    heatmap_height: float | None = None,
    xlim: tuple[float, float] = (-4, 4),
    merge_ss_cs: bool = True,
    merge_plateau: bool = True,
    smooth_plateau: bool = False,
    plateau_vlim: float = 0.01,
    avg_smooth_window: int = 0,
    x_label: str = "Distance (cm)",
    center_line_x: float = 0.0,
    show_session_gap_line: bool = True,
    disable_pf2_avg_ylim_sync: bool = False,
    avg_ylim_focus_window: tuple[float, float] | None = None,
    output_prefix: str = "pf_centered_2sessions",
    show_plot: bool = False,
    Plot_plateaus: bool = True,
    plateau_height_per_spkh: float = 0.15,
    phase_labels: tuple[str, str] | list[str] | None = None,
) -> dict[str, Any]:
    plateau_height_per_spkh = float(plateau_height_per_spkh)
    if (not np.isfinite(plateau_height_per_spkh)) or plateau_height_per_spkh <= 0:
        raise ValueError("plateau_height_per_spkh must be a finite number > 0.")
    phase_labels_use = _normalize_two_phase_labels(phase_labels)
    figure_root = Path(figure_save_folder)
    figure_root.mkdir(parents=True, exist_ok=True)
    print(f"PF-centered (2 sessions) heatmaps root folder: {figure_root}")
    categories = _ordered_dataset_categories(dataset)
    cat_to_dir = {
        cat: figure_root / _category_output_dir_name(prefix=str(output_prefix), category=cat, suffix="_heatmaps")
        for cat in categories
    }
    summary: dict[str, Any] = {}

    for category in categories:
        cat_data = dataset.get(category, {})
        primary_entries = list(cat_data.get(1, {}).get("entries", []))
        secondary_entries = list(cat_data.get(2, {}).get("entries", []))
        primary_time_rel = np.asarray(cat_data.get(1, {}).get("time_rel", []), dtype=float)
        secondary_time_rel = np.asarray(cat_data.get(2, {}).get("time_rel", []), dtype=float)
        pri_by_key = {(e["session"], int(e["cell_idx"])): e for e in primary_entries}
        sec_by_key = {(e["session"], int(e["cell_idx"])): e for e in secondary_entries}
        all_keys = sorted(set(pri_by_key.keys()) | set(sec_by_key.keys()))
        out_dir = cat_to_dir[category]
        if clear_output and out_dir.exists():
            shutil.rmtree(out_dir)
        out_dir.mkdir(parents=True, exist_ok=True)
        print(f"[{category}] output folder: {out_dir}")

        n_saved = 0
        n_dual = 0
        n_pf2_only = 0
        n_plateau_trace_payload_files = 0
        n_plateau_trace_event_files = 0
        n_plateau_trace_missing_payload_files = 0
        for i, key in enumerate(all_keys, start=1):
            entry1 = pri_by_key.get(key)
            entry2 = sec_by_key.get(key)
            if entry1 is not None:
                entry_main = entry1
                entry_secondary = entry2
                time_rel = primary_time_rel
            else:
                entry_main = entry2
                entry_secondary = None
                time_rel = secondary_time_rel
                n_pf2_only += 1
            if entry_main is None:
                continue
            out_path = out_dir / f"{entry_main['session']}_Cell{int(entry_main['cell_idx']) + 1}_heatmap_2sessions.svg"
            entries_for_plateau_check = [e for e in (entry1, entry2) if e is not None]
            if bool(Plot_plateaus):
                if any(_plateau_trace_entry_has_payload(e) for e in entries_for_plateau_check):
                    n_plateau_trace_payload_files += 1
                else:
                    n_plateau_trace_missing_payload_files += 1
                if any(_plateau_trace_entry_has_events(e) for e in entries_for_plateau_check):
                    n_plateau_trace_event_files += 1
            plot_pf_centered_dual_component_heatmap_2sessions(
                entry_primary=entry_main,
                entry_secondary=entry_secondary,
                time_rel=time_rel,
                smooth_window=smooth_window,
                out_path=out_path,
                show_plot=show_plot,
                interpolate_nan=interpolate_nan,
                fr_vmax_scale=fr_vmax_scale,
                rate_colorbar_vmax=rate_colorbar_vmax,
                avg_height=avg_height,
                subplot_width=subplot_width,
                theta_vlim=theta_vlim,
                slow_vlim=slow_vlim,
                fig_width=fig_width,
                trial_height=trial_height,
                heatmap_height=heatmap_height,
                xlim=xlim,
                merge_ss_cs=merge_ss_cs,
                merge_plateau=merge_plateau,
                smooth_plateau=smooth_plateau,
                plateau_vlim=plateau_vlim,
                avg_smooth_window=avg_smooth_window,
                x_label=x_label,
                center_line_x=center_line_x,
                show_session_gap_line=show_session_gap_line,
                disable_pf2_avg_ylim_sync=disable_pf2_avg_ylim_sync,
                avg_ylim_focus_window=avg_ylim_focus_window,
                Plot_plateaus=bool(Plot_plateaus),
                plateau_height_per_spkh=plateau_height_per_spkh,
                phase_labels=phase_labels_use,
            )
            n_saved += 1
            if entry1 is not None and entry2 is not None:
                n_dual += 1
            print(f"[{category}] {i}/{len(all_keys)} saved: {out_path.name}")

        summary[category] = {
            "output_dir": str(out_dir),
            "n_primary_entries": len(primary_entries),
            "n_secondary_entries": len(secondary_entries),
            "n_union_entries": len(all_keys),
            "n_pf2_only_entries": int(n_pf2_only),
            "n_saved_files": n_saved,
            "n_dual_pf_files": n_dual,
            "Plot_plateaus": bool(Plot_plateaus),
            "plateau_height_per_spkh": float(plateau_height_per_spkh),
            "phase_labels": tuple(phase_labels_use),
            "n_plateau_trace_payload_files": int(n_plateau_trace_payload_files),
            "n_plateau_trace_event_files": int(n_plateau_trace_event_files),
            "n_plateau_trace_missing_payload_files": int(n_plateau_trace_missing_payload_files),
            "mode": "all_direction_heatmap_with_session_split_averages",
        }
        if bool(Plot_plateaus) and n_plateau_trace_missing_payload_files > 0 and n_plateau_trace_payload_files == 0:
            print(
                f"[{category}] Plateau trace columns requested, but no entries contain "
                "'plateau_trace_events_by_trial'. Regenerate distance_centered_dataset to populate them."
            )
    return summary


def generate_pf_distance_centered_component_heatmaps_2sessions(
    dataset: dict[str, Any],
    *,
    figure_save_folder: str | Path,
    clear_output: bool = True,
    interpolate_nan: bool = True,
    smooth_window: float = 1.0,
    fr_vmax_scale: float = 0.6,
    rate_colorbar_vmax: float | None = None,
    avg_height: float = 0.3,
    subplot_width: float | None = None,
    theta_vlim: tuple[float, float] = (0, 0.5),
    slow_vlim: tuple[float, float] = (-0.4, 0.4),
    fig_width: float = 3.8,
    trial_height: float = 0.02,
    heatmap_height: float | None = None,
    xlim: tuple[float, float] | None = None,
    merge_ss_cs: bool = True,
    merge_plateau: bool = True,
    smooth_plateau: bool = False,
    plateau_vlim: float = 0.01,
    avg_smooth_window: float | None = None,
    align_all_peak_to_zero: bool = True,
    peak_align_window: tuple[float, float] = (-5.0, 5.0),
    max_peak_adjust_cm: float | None = None,
    max_peak_adjust_cm_pf1: float | None = None,
    max_peak_adjust_cm_pf2: float | None = None,
    peak_align_reference_session: str | int | None = "session1",
    show_session_gap_line: bool = True,
    disable_pf2_avg_ylim_sync: bool = False,
    avg_ylim_focus_window: tuple[float, float] | None = (-5.0, 5.0),
    save_average_exports: bool = True,
    average_export_subdir: str = "pf_distance_centered_2sessions_average_exports",
    split_mode: str = "recorded_sessions",
    split_window_minutes: float | None = None,
    plateau_split_min_traversals_per_phase: int = 5,
    plateau_split_excluded_traversals: int = 0,
    phase_labels: tuple[str, str] | list[str] | None = None,
    print_peak_shift_bins: bool = False,
    x_label: str = "Distance from PF peak (cm)",
    output_prefix: str = "pf_centered_2sessions",
    show_plot: bool = False,
    Plot_plateaus: bool = True,
    plateau_height_per_spkh: float = 0.15,
) -> dict[str, Any]:
    import csv

    plateau_height_per_spkh = float(plateau_height_per_spkh)
    if (not np.isfinite(plateau_height_per_spkh)) or plateau_height_per_spkh <= 0:
        raise ValueError("plateau_height_per_spkh must be a finite number > 0.")

    split_mode_norm = _normalize_two_session_split_mode(split_mode)
    split_window_minutes_use = _validate_two_session_split_window_minutes(split_mode_norm, split_window_minutes)
    plateau_split_min_traversals_per_phase_use = _validate_plateau_split_min_traversals_per_phase(
        plateau_split_min_traversals_per_phase
    )
    plateau_split_excluded_traversals_use = _validate_plateau_split_excluded_traversals(
        plateau_split_excluded_traversals
    )
    phase_labels_use = _normalize_two_phase_labels(phase_labels, split_mode=split_mode_norm)
    split_meta = _two_session_split_metadata(
        split_mode=split_mode_norm,
        split_window_minutes=split_window_minutes_use,
        plateau_split_min_traversals_per_phase=plateau_split_min_traversals_per_phase_use,
        plateau_split_excluded_traversals=plateau_split_excluded_traversals_use,
    )

    figure_root = Path(figure_save_folder)
    distance_window_cm = float(dataset.get("metadata", {}).get("distance_window_cm", 20.0))
    distance_bin_cm = float(dataset.get("metadata", {}).get("distance_bin_cm", 1.0))
    xlim_use = (-distance_window_cm, distance_window_cm) if xlim is None else xlim
    smooth_window_bins = _distance_smooth_cm_to_bins(distance_bin_cm, smooth_window)
    if avg_smooth_window is None:
        avg_smooth_window = smooth_window
    avg_smooth_window_bins = _distance_smooth_cm_to_bins(distance_bin_cm, avg_smooth_window)

    def _window_from_cap(cap_cm: float | None) -> tuple[float, float]:
        if cap_cm is None:
            return peak_align_window
        cap_cm = float(cap_cm)
        if (not np.isfinite(cap_cm)) or cap_cm < 0:
            raise ValueError("max_peak_adjust_cm values must be finite numbers >= 0.")
        return (-cap_cm, cap_cm)

    pf1_window = _window_from_cap(max_peak_adjust_cm_pf1 if max_peak_adjust_cm_pf1 is not None else max_peak_adjust_cm)
    pf2_window = _window_from_cap(max_peak_adjust_cm_pf2 if max_peak_adjust_cm_pf2 is not None else max_peak_adjust_cm)

    def _prep_entries(cat_name: str, pf_rank: int) -> tuple[np.ndarray, list[dict[str, Any]], list[dict[str, Any]]]:
        rel = np.asarray(dataset.get(cat_name, {}).get(pf_rank, {}).get("distance_rel", []), dtype=float)
        entries = _split_distance_centered_entries_for_two_sessions(
            list(dataset.get(cat_name, {}).get(pf_rank, {}).get("entries", [])),
            split_mode=split_mode_norm,
            split_window_minutes=split_window_minutes_use,
            plateau_split_min_traversals_per_phase=plateau_split_min_traversals_per_phase_use,
            plateau_split_excluded_traversals=plateau_split_excluded_traversals_use,
        )
        original_entries = list(entries)
        if not bool(align_all_peak_to_zero) or rel.size == 0:
            for entry in entries:
                entry["_peak_align_shift_cm"] = 0.0
            return rel, entries, original_entries
        peak_align_window_use = pf1_window if int(pf_rank) == 1 else pf2_window
        shifted_entries = [
            _shift_distance_centered_entry_for_peak_alignment(
                entry,
                rel,
                smooth_window=smooth_window_bins,
                avg_smooth_window=avg_smooth_window_bins,
                peak_align_window=peak_align_window_use,
                reference_session=peak_align_reference_session,
            )
            for entry in entries
        ]
        return rel, shifted_entries, original_entries

    categories = _ordered_dataset_categories(dataset)
    prep_by_cat: dict[str, dict[str, Any]] = {}
    for cat_name in categories:
        rel1, entries1, entries1_pre = _prep_entries(cat_name, 1)
        rel2, entries2, entries2_pre = _prep_entries(cat_name, 2)
        prep_by_cat[cat_name] = {
            "rel1": np.asarray(rel1, dtype=float),
            "rel2": np.asarray(rel2, dtype=float),
            "entries1": list(entries1),
            "entries2": list(entries2),
            "entries1_pre": list(entries1_pre),
            "entries2_pre": list(entries2_pre),
        }

    if bool(print_peak_shift_bins):
        def _entry_key(entry: dict[str, Any]) -> tuple[str, int]:
            return str(entry.get("session", "")), int(entry.get("cell_idx", -1))

        def _entry_map(entries: list[dict[str, Any]]) -> dict[tuple[str, int], dict[str, Any]]:
            out: dict[tuple[str, int], dict[str, Any]] = {}
            for e in entries:
                out[_entry_key(e)] = e
            return out

        def _cm_to_bins(shift_cm: float) -> float:
            if (not np.isfinite(float(shift_cm))) or (not np.isfinite(float(distance_bin_cm))) or float(distance_bin_cm) <= 0:
                return np.nan
            return float(int(np.rint(float(shift_cm) / float(distance_bin_cm))))

        for cat_name in categories:
            pf1_entries = list(prep_by_cat.get(cat_name, {}).get("entries1", []))
            pf2_entries = list(prep_by_cat.get(cat_name, {}).get("entries2", []))
            pf1_map = _entry_map(list(pf1_entries))
            pf2_map = _entry_map(list(pf2_entries))
            all_keys = sorted(set(pf1_map.keys()) | set(pf2_map.keys()), key=lambda x: (x[0], x[1]))
            print(f"[{cat_name}] per-cell peak shifts (distance bin = {float(distance_bin_cm):.4g} cm):")
            for animal_id, cell_idx in all_keys:
                e1 = pf1_map.get((animal_id, cell_idx))
                e2 = pf2_map.get((animal_id, cell_idx))
                shift_pf1_cm = float(e1.get("_peak_align_shift_cm", np.nan)) if e1 is not None else np.nan
                shift_pf2_cm = float(e2.get("_peak_align_shift_cm", np.nan)) if e2 is not None else np.nan
                shift_pf1_bins = _cm_to_bins(shift_pf1_cm)
                shift_pf2_bins = _cm_to_bins(shift_pf2_cm)
                pf1_txt = (
                    f"{int(shift_pf1_bins):+d} bins ({shift_pf1_cm:+.2f} cm)"
                    if np.isfinite(shift_pf1_bins)
                    else "NA"
                )
                pf2_txt = (
                    f"{int(shift_pf2_bins):+d} bins ({shift_pf2_cm:+.2f} cm)"
                    if np.isfinite(shift_pf2_bins)
                    else "NA"
                )
                print(f"  {animal_id} Cell {int(cell_idx) + 1}: PF1={pf1_txt}, PF2={pf2_txt}")

    shifted_dataset: dict[str, Any] = {}
    for cat_name in categories:
        prep = prep_by_cat.get(cat_name, {})
        shifted_dataset[cat_name] = {
            1: {"time_rel": np.asarray(prep.get("rel1", []), dtype=float), "entries": list(prep.get("entries1", []))},
            2: {"time_rel": np.asarray(prep.get("rel2", []), dtype=float), "entries": list(prep.get("entries2", []))},
        }

    summary = generate_pf_centered_component_heatmaps_2sessions(
        dataset=shifted_dataset,
        figure_save_folder=figure_root,
        clear_output=clear_output,
        interpolate_nan=interpolate_nan,
        smooth_window=smooth_window_bins,
        fr_vmax_scale=fr_vmax_scale,
        rate_colorbar_vmax=rate_colorbar_vmax,
        avg_height=avg_height,
        subplot_width=subplot_width,
        theta_vlim=theta_vlim,
        slow_vlim=slow_vlim,
        fig_width=fig_width,
        trial_height=trial_height,
        heatmap_height=heatmap_height,
        xlim=xlim_use,
        merge_ss_cs=merge_ss_cs,
        merge_plateau=merge_plateau,
        smooth_plateau=smooth_plateau,
        plateau_vlim=plateau_vlim,
        avg_smooth_window=avg_smooth_window_bins,
        x_label=str(x_label),
        center_line_x=0.0,
        show_session_gap_line=show_session_gap_line,
        disable_pf2_avg_ylim_sync=disable_pf2_avg_ylim_sync,
        avg_ylim_focus_window=avg_ylim_focus_window,
        output_prefix=str(output_prefix),
        show_plot=show_plot,
        Plot_plateaus=bool(Plot_plateaus),
        plateau_height_per_spkh=plateau_height_per_spkh,
        phase_labels=phase_labels_use,
    )
    for cat_name in categories:
        if cat_name in summary and isinstance(summary[cat_name], dict):
            summary[cat_name]["split_mode"] = str(split_meta["split_mode"])
            summary[cat_name]["split_window_minutes"] = (
                None if not np.isfinite(float(split_meta["split_window_minutes"])) else float(split_meta["split_window_minutes"])
            )
            summary[cat_name]["phase_labels"] = tuple(phase_labels_use)
            if split_mode_norm == "prepost_plateau":
                summary[cat_name]["plateau_split_min_traversals_per_phase"] = int(plateau_split_min_traversals_per_phase_use)
                summary[cat_name]["plateau_split_excluded_traversals"] = int(plateau_split_excluded_traversals_use)

    if bool(save_average_exports):
        export_root = figure_root / str(average_export_subdir)
        export_root.mkdir(parents=True, exist_ok=True)

        metric_to_stack = {
            "all_spike": "rate_stack",
            "ss": "ss_rate_stack",
            "cs": "cs_rate_stack",
            "theta": "theta_stack",
            "slow": "slow_stack",
        }

        def _entry_key(entry: dict[str, Any]) -> tuple[str, int]:
            return str(entry.get("session", "")), int(entry.get("cell_idx", -1))

        def _entry_map(entries: list[dict[str, Any]]) -> dict[tuple[str, int], dict[str, Any]]:
            out: dict[tuple[str, int], dict[str, Any]] = {}
            for e in entries:
                out[_entry_key(e)] = e
            return out

        def _smooth_stack_for_export(stack: np.ndarray) -> np.ndarray:
            if int(smooth_window_bins) <= 1:
                return stack
            out = np.full_like(stack, np.nan)
            for i in range(stack.shape[0]):
                out[i] = _smooth_boxcar(stack[i], int(smooth_window_bins))
            return out

        def _smooth_trace_for_export(trace: np.ndarray) -> np.ndarray:
            if int(avg_smooth_window_bins) <= 1:
                return trace
            return _smooth_boxcar(trace, int(avg_smooth_window_bins))

        def _session_means_for_stack(
            entry: dict[str, Any] | None,
            stack_key: str,
            n_time: int,
        ) -> tuple[np.ndarray, np.ndarray, np.ndarray, np.ndarray, int, int, float, float]:
            nan_trace = np.full(int(n_time), np.nan, dtype=float)
            if entry is None:
                return nan_trace, nan_trace, nan_trace, nan_trace, 0, 0, np.nan, np.nan
            all_data = entry.get("data", {}).get("all", {})
            arr = all_data.get(stack_key)
            if arr is None:
                return nan_trace, nan_trace, nan_trace, nan_trace, 0, 0, np.nan, np.nan
            arr = np.asarray(arr, dtype=float)
            if arr.ndim != 2 or arr.shape[1] != int(n_time):
                return nan_trace, nan_trace, nan_trace, nan_trace, 0, 0, np.nan, np.nan

            td = all_data.get("trial_data", {}) if isinstance(all_data, dict) else {}
            sess = np.asarray(td.get("session_idx", []), dtype=int) if isinstance(td, dict) else np.array([], dtype=int)
            if sess.ndim != 1 or sess.size != int(arr.shape[0]):
                sess = np.zeros(int(arr.shape[0]), dtype=int)
            s1_named, s2_named = _resolve_two_session_label_values(sess)
            if s1_named is None:
                return nan_trace, nan_trace, nan_trace, nan_trace, 0, 0, np.nan, np.nan

            cell_data_local = {"all": all_data}
            tr1, sem1, n1 = _extract_cell_metric_stats_from_all_by_session(
                cell_data_local,
                stack_key,
                int(n_time),
                session_idx_filter="session1",
                smooth_window=smooth_window_bins,
                avg_smooth_window=avg_smooth_window_bins,
            )
            tr1 = nan_trace if tr1 is None else np.asarray(tr1, dtype=float)
            sem1 = nan_trace if sem1 is None else np.asarray(sem1, dtype=float)
            s1_val = int(s1_named)

            if s2_named is not None:
                tr2, sem2, n2 = _extract_cell_metric_stats_from_all_by_session(
                    cell_data_local,
                    stack_key,
                    int(n_time),
                    session_idx_filter="session2",
                    smooth_window=smooth_window_bins,
                    avg_smooth_window=avg_smooth_window_bins,
                )
                tr2 = nan_trace if tr2 is None else np.asarray(tr2, dtype=float)
                sem2 = nan_trace if sem2 is None else np.asarray(sem2, dtype=float)
                s2_val = int(s2_named)
            else:
                s2_val = np.nan
                n2 = 0
                tr2 = nan_trace
                sem2 = nan_trace
            return (
                np.asarray(tr1, dtype=float),
                np.asarray(tr2, dtype=float),
                np.asarray(sem1, dtype=float),
                np.asarray(sem2, dtype=float),
                n1,
                n2,
                float(s1_val),
                float(s2_val),
            )

        cat_payload = {
            cat: {
                "pf1_pre": list(prep_by_cat.get(cat, {}).get("entries1_pre", [])),
                "pf2_pre": list(prep_by_cat.get(cat, {}).get("entries2_pre", [])),
                "pf1_post": list(prep_by_cat.get(cat, {}).get("entries1", [])),
                "pf2_post": list(prep_by_cat.get(cat, {}).get("entries2", [])),
                "rel1": np.asarray(prep_by_cat.get(cat, {}).get("rel1", []), dtype=float),
                "rel2": np.asarray(prep_by_cat.get(cat, {}).get("rel2", []), dtype=float),
            }
            for cat in categories
        }

        for cat in categories:
            cp = cat_payload[cat]
            cat_dir = export_root / cat
            cat_dir.mkdir(parents=True, exist_ok=True)
            csv_path = cat_dir / "session_averages_pre_post_index.csv"
            pf1_pre_map = _entry_map(list(cp["pf1_pre"]))
            pf2_pre_map = _entry_map(list(cp["pf2_pre"]))
            pf1_post_map = _entry_map(list(cp["pf1_post"]))
            pf2_post_map = _entry_map(list(cp["pf2_post"]))
            all_keys = sorted(set(pf1_post_map.keys()) | set(pf2_post_map.keys()), key=lambda x: (x[0], x[1]))

            with open(csv_path, "w", newline="") as fcsv:
                writer = csv.writer(fcsv)
                writer.writerow(
                    [
                        "category",
                        "animal_id",
                        "cell_idx",
                        "cell_num",
                        "split_mode",
                        "split_window_minutes",
                        "window1_start_sec",
                        "window1_end_sec",
                        "window2_start_sec",
                        "window2_end_sec",
                        "phase1_label",
                        "phase2_label",
                        "plateau_split_min_traversals_per_phase",
                        "plateau_split_excluded_traversals",
                        "shift_pf1_cm",
                        "shift_pf2_cm",
                        "n_trials_pf1_s1",
                        "n_trials_pf1_s2",
                        "n_trials_pf2_s1",
                        "n_trials_pf2_s2",
                        "session_idx_pf1_s1",
                        "session_idx_pf1_s2",
                        "session_idx_pf2_s1",
                        "session_idx_pf2_s2",
                        "npz_path",
                    ]
                )

                for animal_id, cell_idx in all_keys:
                    e1_pre = pf1_pre_map.get((animal_id, cell_idx))
                    e2_pre = pf2_pre_map.get((animal_id, cell_idx))
                    e1_post = pf1_post_map.get((animal_id, cell_idx))
                    e2_post = pf2_post_map.get((animal_id, cell_idx))

                    shift_pf1 = float(e1_post.get("_peak_align_shift_cm", np.nan)) if e1_post is not None else np.nan
                    shift_pf2 = float(e2_post.get("_peak_align_shift_cm", np.nan)) if e2_post is not None else np.nan

                    n1_time = int(cp["rel1"].size)
                    n2_time = int(cp["rel2"].size)

                    npz_payload: dict[str, Any] = {
                        "category": str(cat),
                        "animal_id": str(animal_id),
                        "cell_idx": int(cell_idx),
                        "cell_num": int(cell_idx + 1),
                        "split_mode": str(split_meta["split_mode"]),
                        "split_window_minutes": float(split_meta["split_window_minutes"]),
                        "window1_start_sec": float(split_meta["window1_start_sec"]),
                        "window1_end_sec": float(split_meta["window1_end_sec"]),
                        "window2_start_sec": float(split_meta["window2_start_sec"]),
                        "window2_end_sec": float(split_meta["window2_end_sec"]),
                        "phase1_label": str(phase_labels_use[0]),
                        "phase2_label": str(phase_labels_use[1]),
                        "plateau_split_min_traversals_per_phase": float(split_meta["plateau_split_min_traversals_per_phase"]),
                        "plateau_split_excluded_traversals": float(split_meta["plateau_split_excluded_traversals"]),
                        "distance_rel_pf1": np.asarray(cp["rel1"], dtype=float),
                        "distance_rel_pf2": np.asarray(cp["rel2"], dtype=float),
                        "shift_pf1_cm": float(shift_pf1),
                        "shift_pf2_cm": float(shift_pf2),
                    }

                    # Session-specific traversal counts come from post-shift entries
                    # (same trials as plotted/exported downstream).
                    _, _, _, _, n_pf1_s1, n_pf1_s2, idx_pf1_s1, idx_pf1_s2 = _session_means_for_stack(
                        e1_post, "rate_stack", n1_time
                    )
                    _, _, _, _, n_pf2_s1, n_pf2_s2, idx_pf2_s1, idx_pf2_s2 = _session_means_for_stack(
                        e2_post, "rate_stack", n2_time
                    )
                    npz_payload["n_trials_pf1_s1"] = int(n_pf1_s1)
                    npz_payload["n_trials_pf1_s2"] = int(n_pf1_s2)
                    npz_payload["n_trials_pf2_s1"] = int(n_pf2_s1)
                    npz_payload["n_trials_pf2_s2"] = int(n_pf2_s2)
                    npz_payload["session_idx_pf1_s1"] = float(idx_pf1_s1)
                    npz_payload["session_idx_pf1_s2"] = float(idx_pf1_s2)
                    npz_payload["session_idx_pf2_s1"] = float(idx_pf2_s1)
                    npz_payload["session_idx_pf2_s2"] = float(idx_pf2_s2)

                    for metric_name, stack_key in metric_to_stack.items():
                        tr, tr2, sem1, sem2, *_ = _session_means_for_stack(e1_pre, stack_key, n1_time)
                        npz_payload[f"pre_pf1_s1_{metric_name}"] = tr
                        npz_payload[f"pre_pf1_s2_{metric_name}"] = tr2
                        npz_payload[f"pre_pf1_s1_sem_{metric_name}"] = sem1
                        npz_payload[f"pre_pf1_s2_sem_{metric_name}"] = sem2
                        tr, tr2, sem1, sem2, *_ = _session_means_for_stack(e1_post, stack_key, n1_time)
                        npz_payload[f"post_pf1_s1_{metric_name}"] = tr
                        npz_payload[f"post_pf1_s2_{metric_name}"] = tr2
                        npz_payload[f"post_pf1_s1_sem_{metric_name}"] = sem1
                        npz_payload[f"post_pf1_s2_sem_{metric_name}"] = sem2

                        tr, tr2, sem1, sem2, *_ = _session_means_for_stack(e2_pre, stack_key, n2_time)
                        npz_payload[f"pre_pf2_s1_{metric_name}"] = tr
                        npz_payload[f"pre_pf2_s2_{metric_name}"] = tr2
                        npz_payload[f"pre_pf2_s1_sem_{metric_name}"] = sem1
                        npz_payload[f"pre_pf2_s2_sem_{metric_name}"] = sem2
                        tr, tr2, sem1, sem2, *_ = _session_means_for_stack(e2_post, stack_key, n2_time)
                        npz_payload[f"post_pf2_s1_{metric_name}"] = tr
                        npz_payload[f"post_pf2_s2_{metric_name}"] = tr2
                        npz_payload[f"post_pf2_s1_sem_{metric_name}"] = sem1
                        npz_payload[f"post_pf2_s2_sem_{metric_name}"] = sem2

                    npz_name = f"{animal_id}_Cell{int(cell_idx) + 1}_session_averages_pre_post.npz"
                    npz_path = cat_dir / npz_name
                    np.savez(npz_path, **npz_payload)

                    writer.writerow(
                        [
                            str(cat),
                            str(animal_id),
                            int(cell_idx),
                            int(cell_idx + 1),
                            str(split_meta["split_mode"]),
                            float(split_meta["split_window_minutes"]) if np.isfinite(float(split_meta["split_window_minutes"])) else np.nan,
                            float(split_meta["window1_start_sec"]) if np.isfinite(float(split_meta["window1_start_sec"])) else np.nan,
                            float(split_meta["window1_end_sec"]) if np.isfinite(float(split_meta["window1_end_sec"])) else np.nan,
                            float(split_meta["window2_start_sec"]) if np.isfinite(float(split_meta["window2_start_sec"])) else np.nan,
                            float(split_meta["window2_end_sec"]) if np.isfinite(float(split_meta["window2_end_sec"])) else np.nan,
                            str(phase_labels_use[0]),
                            str(phase_labels_use[1]),
                            float(split_meta["plateau_split_min_traversals_per_phase"]) if np.isfinite(float(split_meta["plateau_split_min_traversals_per_phase"])) else np.nan,
                            float(split_meta["plateau_split_excluded_traversals"]) if np.isfinite(float(split_meta["plateau_split_excluded_traversals"])) else np.nan,
                            float(shift_pf1) if np.isfinite(shift_pf1) else np.nan,
                            float(shift_pf2) if np.isfinite(shift_pf2) else np.nan,
                            int(n_pf1_s1),
                            int(n_pf1_s2),
                            int(n_pf2_s1),
                            int(n_pf2_s2),
                            float(idx_pf1_s1) if np.isfinite(idx_pf1_s1) else np.nan,
                            float(idx_pf1_s2) if np.isfinite(idx_pf1_s2) else np.nan,
                            float(idx_pf2_s1) if np.isfinite(idx_pf2_s1) else np.nan,
                            float(idx_pf2_s2) if np.isfinite(idx_pf2_s2) else np.nan,
                            str(npz_path),
                        ]
                    )

            if cat in summary and isinstance(summary[cat], dict):
                summary[cat]["average_export_dir"] = str(cat_dir)
                summary[cat]["average_export_index_csv"] = str(csv_path)
                summary[cat]["n_average_export_files"] = int(len(all_keys))
                summary[cat]["split_mode"] = str(split_meta["split_mode"])
                summary[cat]["split_window_minutes"] = (
                    None if not np.isfinite(float(split_meta["split_window_minutes"])) else float(split_meta["split_window_minutes"])
                )
                summary[cat]["phase_labels"] = tuple(phase_labels_use)
                if split_mode_norm == "prepost_plateau":
                    summary[cat]["plateau_split_min_traversals_per_phase"] = int(plateau_split_min_traversals_per_phase_use)
                    summary[cat]["plateau_split_excluded_traversals"] = int(plateau_split_excluded_traversals_use)

    return summary


def _normalize_direction_avg_mode(avg_mode: str | None) -> str:
    """Normalize avg mode token for direction/session filtered plotting."""
    token = str("combined" if avg_mode is None else avg_mode).strip().lower()
    aliases = {
        "combined": "combined",
        "all": "combined",
        "both": "combined",
        "s1": "s1",
        "session1": "s1",
        "session_1": "s1",
        "first": "s1",
        "1": "s1",
        "s2": "s2",
        "session2": "s2",
        "session_2": "s2",
        "second": "s2",
        "2": "s2",
    }
    if token not in aliases:
        raise ValueError("avg_mode must be one of: combined, S1, S2.")
    return aliases[token]


def _normalize_direction_triplet(
    direction_keys: tuple[str, str, str] | list[str] | None = None,
    direction_titles: tuple[str, str, str] | list[str] | None = None,
) -> tuple[tuple[str, str, str], tuple[str, str, str]]:
    keys_in = ("all", "cw", "ccw") if direction_keys is None else tuple(direction_keys)
    if len(keys_in) != 3:
        raise ValueError("direction_keys must contain exactly three keys.")
    keys = tuple(str(k).strip() for k in keys_in)
    if any(len(k) == 0 for k in keys):
        raise ValueError("direction_keys cannot contain empty keys.")
    if len(set(keys)) != 3:
        raise ValueError("direction_keys must be unique.")

    if direction_titles is None:
        default_labels = {
            "all": "All",
            "cw": "CW",
            "ccw": "CCW",
            "p": "Preferred",
            "np": "Non-preferred",
        }
        titles = tuple(default_labels.get(k, k) for k in keys)
    else:
        titles_in = tuple(direction_titles)
        if len(titles_in) != 3:
            raise ValueError("direction_titles must contain exactly three labels.")
        titles = tuple(str(t).strip() for t in titles_in)
    return keys, titles


def _filter_direction_data_by_avg_mode(
    dir_data: dict[str, Any],
    *,
    avg_mode: str,
) -> dict[str, Any]:
    """Filter one direction payload to combined/S1/S2 trial subset."""
    mode = _normalize_direction_avg_mode(avg_mode)
    if mode == "combined":
        return dir_data

    if not isinstance(dir_data, dict):
        return dir_data

    trial_data_in = dir_data.get("trial_data", {})
    trial_data_in = trial_data_in if isinstance(trial_data_in, dict) else {}
    session_idx = np.asarray(trial_data_in.get("session_idx", []), dtype=int)

    n_rows_ref: int | None = None
    for v in dir_data.values():
        arr = np.asarray(v) if isinstance(v, np.ndarray) else None
        if arr is None:
            continue
        if arr.ndim == 2:
            n_rows_ref = int(arr.shape[0])
            break
    if n_rows_ref is None:
        n_rows_ref = int(dir_data.get("n_trials", 0))

    if session_idx.ndim != 1 or session_idx.size != int(n_rows_ref):
        if mode == "s1":
            mask = np.ones(int(n_rows_ref), dtype=bool)
            uniq = np.array([0], dtype=int) if int(n_rows_ref) > 0 else np.array([], dtype=int)
        else:
            mask = np.zeros(int(n_rows_ref), dtype=bool)
            uniq = np.array([0], dtype=int) if int(n_rows_ref) > 0 else np.array([], dtype=int)
    else:
        uniq = np.sort(np.unique(session_idx.astype(int)))
        if uniq.size == 0:
            mask = np.zeros(int(n_rows_ref), dtype=bool)
        elif mode == "s1":
            mask = session_idx == int(uniq[0])
        else:
            if uniq.size >= 2:
                mask = session_idx == int(uniq[1])
            else:
                mask = np.zeros_like(session_idx, dtype=bool)

    out = dict(dir_data)
    for key, value in list(dir_data.items()):
        if key == "trial_data":
            td_out: dict[str, Any] = {}
            for td_key, td_val in trial_data_in.items():
                td_arr = np.asarray(td_val)
                if td_arr.ndim == 1 and td_arr.size == int(mask.size):
                    td_out[td_key] = td_arr[mask]
                else:
                    td_out[td_key] = td_val
            out["trial_data"] = td_out
            continue

        if key == "plateau_trace_events_by_trial" and isinstance(value, (list, tuple)) and len(value) == int(mask.size):
            out[key] = [value[int(i)] for i in np.flatnonzero(mask)]
            continue

        try:
            arr = np.asarray(value)
        except Exception:
            out[key] = value
            continue

        if arr.ndim == 2 and arr.shape[0] == int(mask.size):
            out[key] = arr[mask]
        elif arr.ndim == 1 and arr.size == int(mask.size):
            out[key] = arr[mask]
        else:
            out[key] = value

    out["n_trials"] = int(np.sum(mask))
    return out


def _filter_entry_by_avg_mode_for_directions(
    entry: dict[str, Any] | None,
    *,
    avg_mode: str,
    direction_keys: tuple[str, str, str] | list[str] = ("all", "cw", "ccw"),
) -> dict[str, Any] | None:
    """Filter PF entry by avg_mode across the selected direction stacks."""
    if entry is None:
        return None
    mode = _normalize_direction_avg_mode(avg_mode)
    if mode == "combined":
        return entry
    direction_keys_use, _ = _normalize_direction_triplet(direction_keys=direction_keys, direction_titles=None)

    out = dict(entry)
    data_in = entry.get("data", {})
    if not isinstance(data_in, dict):
        return out
    data_out: dict[str, Any] = {}
    for dir_key, dir_data in data_in.items():
        if dir_key in set(direction_keys_use) and isinstance(dir_data, dict):
            data_out[dir_key] = _filter_direction_data_by_avg_mode(dir_data, avg_mode=mode)
        else:
            data_out[dir_key] = dir_data
    out["data"] = data_out
    return out


def _compute_dual_pf_fr_colorbar_vmax_from_direction_means(
    entry_primary: dict[str, Any],
    entry_secondary: dict[str, Any] | None,
    time_rel: np.ndarray,
    *,
    smooth_window: int = 0,
    avg_smooth_window: int = 0,
    avg_mode: str = "combined",
    direction_keys: tuple[str, str, str] | list[str] = ("all", "cw", "ccw"),
) -> dict[str, float]:
    """Dynamic FR colorbar vmax from displayed mean traces across PF1/PF2 and all directions."""
    mode = _normalize_direction_avg_mode(avg_mode)
    direction_keys_use, _ = _normalize_direction_triplet(direction_keys=direction_keys, direction_titles=None)
    n_time = int(len(time_rel))
    metric_to_stack = {
        "rate": "rate_stack",
        "ss": "ss_rate_stack",
        "cs": "cs_rate_stack",
    }
    directions = tuple(direction_keys_use)

    def _smooth_stack(stack: np.ndarray) -> np.ndarray:
        if int(smooth_window) <= 1:
            return stack
        out = np.full_like(stack, np.nan)
        for i in range(stack.shape[0]):
            out[i] = _smooth_boxcar(stack[i], int(smooth_window))
        return out

    def _smooth_trace(trace: np.ndarray) -> np.ndarray:
        if int(avg_smooth_window) <= 1:
            return trace
        return _smooth_boxcar(trace, int(avg_smooth_window))

    def _select_mask(dir_data: dict[str, Any], n_trials: int) -> np.ndarray:
        if mode == "combined":
            return np.ones(int(n_trials), dtype=bool)
        td = dir_data.get("trial_data", {}) if isinstance(dir_data, dict) else {}
        sess = np.asarray(td.get("session_idx", []), dtype=int) if isinstance(td, dict) else np.array([], dtype=int)
        if sess.ndim != 1 or sess.size != int(n_trials):
            return np.ones(int(n_trials), dtype=bool) if mode == "s1" else np.zeros(int(n_trials), dtype=bool)
        uniq = np.sort(np.unique(sess.astype(int)))
        if uniq.size == 0:
            return np.zeros(int(n_trials), dtype=bool)
        if mode == "s1":
            return sess == int(uniq[0])
        if uniq.size >= 2:
            return sess == int(uniq[1])
        return np.zeros(int(n_trials), dtype=bool)

    maxima: dict[str, list[float]] = {"rate": [], "ss": [], "cs": []}
    for entry in (entry_primary, entry_secondary):
        if entry is None:
            continue
        cell_data = entry.get("data", {})
        if not isinstance(cell_data, dict):
            continue
        for direction in directions:
            dir_data = cell_data.get(direction, {})
            if not isinstance(dir_data, dict):
                continue
            for metric_key, stack_key in metric_to_stack.items():
                stack = dir_data.get(stack_key)
                if stack is None:
                    continue
                stack = np.asarray(stack, dtype=float)
                if stack.ndim != 2 or stack.shape[1] != n_time or stack.shape[0] == 0:
                    continue
                stack = _smooth_stack(stack)
                mask = _select_mask(dir_data, int(stack.shape[0]))
                if mask.size != int(stack.shape[0]) or (not np.any(mask)):
                    continue
                mean_trace = np.asarray(np.nanmean(stack[mask], axis=0), dtype=float)
                mean_trace = _smooth_trace(mean_trace)
                finite = mean_trace[np.isfinite(mean_trace)]
                if finite.size == 0:
                    continue
                maxima[metric_key].append(float(np.max(finite)))

    out: dict[str, float] = {}
    for key, vals in maxima.items():
        if len(vals) == 0:
            continue
        vmax = float(np.nanmax(np.asarray(vals, dtype=float)))
        if np.isfinite(vmax) and vmax > 0:
            out[key] = vmax
    return out


def generate_pf_distance_centered_component_heatmaps_2directions(
    dataset: dict[str, Any],
    *,
    figure_save_folder: str | Path,
    clear_output: bool = True,
    smooth_window: float = 1.0,
    fr_vmax_scale: float = 0.6,
    rate_colorbar_vmax: float | None = None,
    theta_vlim: tuple[float, float] = (0, 0.5),
    slow_vlim: tuple[float, float] = (-0.4, 0.4),
    fig_width: float = 3.0,
    trial_height: float = 0.02,
    heatmap_height: float | None = None,
    xlim: tuple[float, float] | None = None,
    merge_ss_cs: bool = True,
    merge_plateau: bool = True,
    smooth_plateau: bool = False,
    plateau_vlim: float = 0.01,
    avg_height: float = 0.25,
    subplot_width: float = 0.55,
    avg_smooth_window: float | None = None,
    avg_theta_ylim: tuple[float, float] | None = (0.0, 0.2),
    avg_slow_ylim: tuple[float, float] | None = (-0.1, 0.1),
    align_all_peak_to_zero: bool = True,
    peak_align_window: tuple[float, float] = (-5.0, 5.0),
    max_peak_adjust_cm: float | None = None,
    max_peak_adjust_cm_pf1: float | None = None,
    max_peak_adjust_cm_pf2: float | None = None,
    peak_align_reference_session: str | int | None = "session1",
    show_session_gap_line: bool = True,
    disable_pf2_avg_ylim_sync: bool = False,
    avg_mode: str = "combined",
    save_average_exports: bool = True,
    average_export_subdir: str = "pf_distance_centered_2directions_average_exports",
    print_peak_shift_bins: bool = False,
    x_label: str = "Distance from PF peak (cm)",
    output_prefix: str = "pf_centered_2directions",
    show_plot: bool = False,
) -> dict[str, Any]:
    import csv

    mode_norm = _normalize_direction_avg_mode(avg_mode)
    figure_root = Path(figure_save_folder).resolve()
    distance_window_cm = float(dataset.get("metadata", {}).get("distance_window_cm", 20.0))
    distance_bin_cm = float(dataset.get("metadata", {}).get("distance_bin_cm", 1.0))
    xlim_use = (-distance_window_cm, distance_window_cm) if xlim is None else xlim
    smooth_window_bins = _distance_smooth_cm_to_bins(distance_bin_cm, smooth_window)
    if avg_smooth_window is None:
        avg_smooth_window = smooth_window
    avg_smooth_window_bins = _distance_smooth_cm_to_bins(distance_bin_cm, avg_smooth_window)
    if rate_colorbar_vmax is not None:
        rate_colorbar_vmax = float(rate_colorbar_vmax)
        if (not np.isfinite(rate_colorbar_vmax)) or rate_colorbar_vmax <= 0:
            raise ValueError("rate_colorbar_vmax must be a finite number > 0.")
    fixed_heatmap_height = None
    if heatmap_height is not None:
        fixed_heatmap_height = float(heatmap_height)
        if (not np.isfinite(fixed_heatmap_height)) or fixed_heatmap_height <= 0:
            raise ValueError("heatmap_height must be a finite number > 0.")

    def _window_from_cap(cap_cm: float | None) -> tuple[float, float]:
        if cap_cm is None:
            return peak_align_window
        cap_cm_f = float(cap_cm)
        if (not np.isfinite(cap_cm_f)) or cap_cm_f < 0:
            raise ValueError("max_peak_adjust_cm values must be finite numbers >= 0.")
        return (-cap_cm_f, cap_cm_f)

    pf1_window = _window_from_cap(max_peak_adjust_cm_pf1 if max_peak_adjust_cm_pf1 is not None else max_peak_adjust_cm)
    pf2_window = _window_from_cap(max_peak_adjust_cm_pf2 if max_peak_adjust_cm_pf2 is not None else max_peak_adjust_cm)

    def _prep_entries(cat_name: str, pf_rank: int) -> tuple[np.ndarray, list[dict[str, Any]], list[dict[str, Any]]]:
        rel = np.asarray(dataset.get(cat_name, {}).get(pf_rank, {}).get("distance_rel", []), dtype=float)
        entries = list(dataset.get(cat_name, {}).get(pf_rank, {}).get("entries", []))
        original_entries = list(entries)
        if not bool(align_all_peak_to_zero) or rel.size == 0:
            for entry in entries:
                entry["_peak_align_shift_cm"] = 0.0
            return rel, entries, original_entries
        peak_align_window_use = pf1_window if int(pf_rank) == 1 else pf2_window
        shifted_entries = [
            _shift_distance_centered_entry_for_peak_alignment(
                entry,
                rel,
                smooth_window=smooth_window_bins,
                avg_smooth_window=avg_smooth_window_bins,
                peak_align_window=peak_align_window_use,
                reference_session=peak_align_reference_session,
            )
            for entry in entries
        ]
        return rel, shifted_entries, original_entries

    categories = _ordered_dataset_categories(dataset)
    prep_by_cat: dict[str, dict[str, Any]] = {}
    for cat_name in categories:
        rel1, entries1, entries1_pre = _prep_entries(cat_name, 1)
        rel2, entries2, entries2_pre = _prep_entries(cat_name, 2)
        prep_by_cat[cat_name] = {
            "rel1": np.asarray(rel1, dtype=float),
            "rel2": np.asarray(rel2, dtype=float),
            "entries1": list(entries1),
            "entries2": list(entries2),
            "entries1_pre": list(entries1_pre),
            "entries2_pre": list(entries2_pre),
        }

    if bool(print_peak_shift_bins):
        def _entry_key(entry: dict[str, Any]) -> tuple[str, int]:
            return str(entry.get("session", "")), int(entry.get("cell_idx", -1))

        def _entry_map(entries: list[dict[str, Any]]) -> dict[tuple[str, int], dict[str, Any]]:
            out: dict[tuple[str, int], dict[str, Any]] = {}
            for e in entries:
                out[_entry_key(e)] = e
            return out

        def _cm_to_bins(shift_cm: float) -> float:
            if (not np.isfinite(float(shift_cm))) or (not np.isfinite(float(distance_bin_cm))) or float(distance_bin_cm) <= 0:
                return np.nan
            return float(int(np.rint(float(shift_cm) / float(distance_bin_cm))))

        for cat_name in categories:
            pf1_entries = list(prep_by_cat.get(cat_name, {}).get("entries1", []))
            pf2_entries = list(prep_by_cat.get(cat_name, {}).get("entries2", []))
            pf1_map = _entry_map(list(pf1_entries))
            pf2_map = _entry_map(list(pf2_entries))
            all_keys = sorted(set(pf1_map.keys()) | set(pf2_map.keys()), key=lambda x: (x[0], x[1]))
            print(f"[{cat_name}] per-cell peak shifts (distance bin = {float(distance_bin_cm):.4g} cm):")
            for animal_id, cell_idx in all_keys:
                e1 = pf1_map.get((animal_id, cell_idx))
                e2 = pf2_map.get((animal_id, cell_idx))
                shift_pf1_cm = float(e1.get("_peak_align_shift_cm", np.nan)) if e1 is not None else np.nan
                shift_pf2_cm = float(e2.get("_peak_align_shift_cm", np.nan)) if e2 is not None else np.nan
                shift_pf1_bins = _cm_to_bins(shift_pf1_cm)
                shift_pf2_bins = _cm_to_bins(shift_pf2_cm)
                pf1_txt = (
                    f"{int(shift_pf1_bins):+d} bins ({shift_pf1_cm:+.2f} cm)"
                    if np.isfinite(shift_pf1_bins)
                    else "NA"
                )
                pf2_txt = (
                    f"{int(shift_pf2_bins):+d} bins ({shift_pf2_cm:+.2f} cm)"
                    if np.isfinite(shift_pf2_bins)
                    else "NA"
                )
                print(f"  {animal_id} Cell {int(cell_idx) + 1}: PF1={pf1_txt}, PF2={pf2_txt}")

    cat_to_payload = {
        cat: {
            "pf1_pre": list(prep_by_cat.get(cat, {}).get("entries1_pre", [])),
            "pf2_pre": list(prep_by_cat.get(cat, {}).get("entries2_pre", [])),
            "pf1_post": list(prep_by_cat.get(cat, {}).get("entries1", [])),
            "pf2_post": list(prep_by_cat.get(cat, {}).get("entries2", [])),
            "rel1": np.asarray(prep_by_cat.get(cat, {}).get("rel1", []), dtype=float),
            "rel2": np.asarray(prep_by_cat.get(cat, {}).get("rel2", []), dtype=float),
        }
        for cat in categories
    }

    figure_root.mkdir(parents=True, exist_ok=True)
    cat_to_dir = {
        cat: figure_root / _category_output_dir_name(prefix=str(output_prefix), category=cat, suffix="_heatmaps")
        for cat in categories
    }
    summary: dict[str, Any] = {}

    for category in categories:
        payload = cat_to_payload[category]
        primary_entries = list(payload["pf1_post"])
        secondary_entries = list(payload["pf2_post"])
        pri_by_key = {(e["session"], int(e["cell_idx"])): e for e in primary_entries}
        sec_by_key = {(e["session"], int(e["cell_idx"])): e for e in secondary_entries}
        all_keys = sorted(set(pri_by_key.keys()) | set(sec_by_key.keys()))
        out_dir = cat_to_dir[category]
        if clear_output and out_dir.exists():
            shutil.rmtree(out_dir)
        out_dir.mkdir(parents=True, exist_ok=True)
        print(f"[{category}] output folder: {out_dir}")

        n_saved = 0
        n_dual = 0
        n_pf2_only = 0
        for i, key in enumerate(all_keys, start=1):
            entry1 = pri_by_key.get(key)
            entry2 = sec_by_key.get(key)
            if entry1 is not None:
                entry_main = _filter_entry_by_avg_mode_for_directions(entry1, avg_mode=mode_norm)
                entry_secondary = _filter_entry_by_avg_mode_for_directions(entry2, avg_mode=mode_norm)
                time_rel = np.asarray(payload["rel1"], dtype=float)
            else:
                entry_main = _filter_entry_by_avg_mode_for_directions(entry2, avg_mode=mode_norm)
                entry_secondary = None
                time_rel = np.asarray(payload["rel2"], dtype=float)
                n_pf2_only += 1
            if entry_main is None:
                continue
            out_path = out_dir / f"{entry_main['session']}_Cell{int(entry_main['cell_idx']) + 1}_heatmap_2directions.svg"
            colorbar_vmax_override = _compute_dual_pf_fr_colorbar_vmax_from_direction_means(
                entry_main,
                entry_secondary,
                np.asarray(time_rel, dtype=float),
                smooth_window=int(smooth_window_bins),
                avg_smooth_window=int(avg_smooth_window_bins),
                avg_mode=mode_norm,
            )
            if rate_colorbar_vmax is not None:
                colorbar_vmax_override = dict(colorbar_vmax_override)
                colorbar_vmax_override["rate"] = float(rate_colorbar_vmax)
            plot_pf_centered_dual_component_heatmap(
                entry_primary=entry_main,
                entry_secondary=entry_secondary,
                time_rel=time_rel,
                smooth_window=smooth_window_bins,
                out_path=out_path,
                show_plot=show_plot,
                fr_vmax_scale=fr_vmax_scale,
                theta_vlim=theta_vlim,
                slow_vlim=slow_vlim,
                fig_width=fig_width,
                trial_height=trial_height,
                xlim=xlim_use,
                merge_ss_cs=merge_ss_cs,
                merge_plateau=merge_plateau,
                smooth_plateau=smooth_plateau,
                plateau_vlim=plateau_vlim,
                avg_height=avg_height,
                avg_smooth_window=avg_smooth_window_bins,
                x_label=str(x_label),
                center_line_x=0.0,
                show_session_gap_line=show_session_gap_line,
                auto_colorbar_vmax_from_pf1_all=False,
                colorbar_vmax_override=colorbar_vmax_override,
                show_titles=False,
                show_column_titles=True,
                column_title_include_trials=True,
                x_label_col_idx=1,
                show_heatmap_yticks=False,
                show_heatmap_yticks_all_columns=False,
                ss_cs_cbar_tick_labelsize=4,
                heatmap_wspace=0.20,
                avg_theta_ylim=avg_theta_ylim,
                avg_slow_ylim=avg_slow_ylim,
                disable_pf2_avg_ylim_sync=disable_pf2_avg_ylim_sync,
                fixed_heatmap_height=(float(fixed_heatmap_height) if fixed_heatmap_height is not None else 0.5),
                fixed_subplot_width=float(subplot_width),
            )
            n_saved += 1
            if entry1 is not None and entry2 is not None:
                n_dual += 1
            print(f"[{category}] {i}/{len(all_keys)} saved: {out_path.name}")

        summary[category] = {
            "output_dir": str(out_dir),
            "n_primary_entries": len(primary_entries),
            "n_secondary_entries": len(secondary_entries),
            "n_union_entries": len(all_keys),
            "n_pf2_only_entries": int(n_pf2_only),
            "n_saved_files": n_saved,
            "n_dual_pf_files": n_dual,
            "mode": "direction_heatmap_with_avg_mode",
            "avg_mode": str(mode_norm),
        }

    if bool(save_average_exports):
        export_root = figure_root / str(average_export_subdir)
        export_root.mkdir(parents=True, exist_ok=True)
        metric_to_stack = {
            "all_spike": "rate_stack",
            "ss": "ss_rate_stack",
            "cs": "cs_rate_stack",
            "theta": "theta_stack",
            "slow": "slow_stack",
        }
        directions = ("all", "cw", "ccw")
        modes = ("combined", "s1", "s2")

        def _entry_key(entry: dict[str, Any]) -> tuple[str, int]:
            return str(entry.get("session", "")), int(entry.get("cell_idx", -1))

        def _entry_map(entries: list[dict[str, Any]]) -> dict[tuple[str, int], dict[str, Any]]:
            out: dict[tuple[str, int], dict[str, Any]] = {}
            for e in entries:
                out[_entry_key(e)] = e
            return out

        def _smooth_stack_for_export(stack: np.ndarray) -> np.ndarray:
            if int(smooth_window_bins) <= 1:
                return stack
            out = np.full_like(stack, np.nan)
            for i in range(stack.shape[0]):
                out[i] = _smooth_boxcar(stack[i], int(smooth_window_bins))
            return out

        def _smooth_trace_for_export(trace: np.ndarray) -> np.ndarray:
            if int(avg_smooth_window_bins) <= 1:
                return trace
            return _smooth_boxcar(trace, int(avg_smooth_window_bins))

        def _direction_mode_stats(
            entry: dict[str, Any] | None,
            direction: str,
            stack_key: str,
            n_time: int,
        ) -> tuple[dict[str, np.ndarray], dict[str, np.ndarray], dict[str, int], float, float]:
            nan_trace = np.full(int(n_time), np.nan, dtype=float)
            empty_trace_dict = {m: nan_trace.copy() for m in modes}
            empty_count_dict = {m: 0 for m in modes}
            if entry is None:
                return empty_trace_dict, empty_trace_dict.copy(), empty_count_dict, np.nan, np.nan

            dir_data = entry.get("data", {}).get(direction, {})
            arr = dir_data.get(stack_key)
            if arr is None:
                return empty_trace_dict, empty_trace_dict.copy(), empty_count_dict, np.nan, np.nan
            arr = np.asarray(arr, dtype=float)

            if arr.ndim == 1:
                if arr.size != int(n_time):
                    return empty_trace_dict, empty_trace_dict.copy(), empty_count_dict, np.nan, np.nan
                tr = arr.copy()
                if int(smooth_window_bins) > 1:
                    tr = _smooth_boxcar(tr, int(smooth_window_bins))
                tr = _smooth_trace_for_export(tr)
                out_tr = dict(empty_trace_dict)
                out_sem = dict(empty_trace_dict)
                out_n = dict(empty_count_dict)
                out_tr["combined"] = tr
                out_n["combined"] = int(max(1, int(dir_data.get("n_trials", 1))))
                return out_tr, out_sem, out_n, np.nan, np.nan

            if arr.ndim != 2 or arr.shape[1] != int(n_time):
                return empty_trace_dict, empty_trace_dict.copy(), empty_count_dict, np.nan, np.nan

            arr = _smooth_stack_for_export(arr)
            td = dir_data.get("trial_data", {}) if isinstance(dir_data, dict) else {}
            sess = np.asarray(td.get("session_idx", []), dtype=int) if isinstance(td, dict) else np.array([], dtype=int)
            if sess.ndim != 1 or sess.size != int(arr.shape[0]):
                sess = np.zeros(int(arr.shape[0]), dtype=int)
            uniq = np.sort(np.unique(sess.astype(int)))
            s1_val = float(uniq[0]) if uniq.size >= 1 else np.nan
            s2_val = float(uniq[1]) if uniq.size >= 2 else np.nan

            out_tr = {m: nan_trace.copy() for m in modes}
            out_sem = {m: nan_trace.copy() for m in modes}
            out_n = {m: 0 for m in modes}
            mode_masks: dict[str, np.ndarray] = {
                "combined": np.ones(int(arr.shape[0]), dtype=bool),
                "s1": (sess == int(uniq[0])) if uniq.size >= 1 else np.zeros(int(arr.shape[0]), dtype=bool),
                "s2": (sess == int(uniq[1])) if uniq.size >= 2 else np.zeros(int(arr.shape[0]), dtype=bool),
            }
            for m in modes:
                msk = np.asarray(mode_masks[m], dtype=bool)
                n_m = int(np.sum(msk))
                out_n[m] = n_m
                if n_m <= 0:
                    continue
                sub = arr[msk]
                tr = np.asarray(np.nanmean(sub, axis=0), dtype=float)
                n_valid = np.sum(np.isfinite(sub), axis=0)
                sem = np.asarray(np.nanstd(sub, axis=0) / np.sqrt(np.maximum(n_valid, 1)), dtype=float)
                tr = _smooth_trace_for_export(tr)
                sem = _smooth_trace_for_export(sem)
                out_tr[m] = tr
                out_sem[m] = sem
            return out_tr, out_sem, out_n, s1_val, s2_val

        for cat in categories:
            payload = cat_to_payload[cat]
            cat_dir = export_root / cat
            cat_dir.mkdir(parents=True, exist_ok=True)
            csv_path = cat_dir / "session_averages_pre_post_index.csv"

            pf1_pre_map = _entry_map(list(payload["pf1_pre"]))
            pf2_pre_map = _entry_map(list(payload["pf2_pre"]))
            pf1_post_map = _entry_map(list(payload["pf1_post"]))
            pf2_post_map = _entry_map(list(payload["pf2_post"]))
            all_keys = sorted(set(pf1_post_map.keys()) | set(pf2_post_map.keys()), key=lambda x: (x[0], x[1]))

            count_cols = []
            idx_cols = []
            for pf in (1, 2):
                for d in directions:
                    count_cols.extend([
                        f"n_trials_pf{pf}_{d}_combined",
                        f"n_trials_pf{pf}_{d}_s1",
                        f"n_trials_pf{pf}_{d}_s2",
                    ])
                    idx_cols.extend([
                        f"session_idx_pf{pf}_{d}_s1",
                        f"session_idx_pf{pf}_{d}_s2",
                    ])

            with open(csv_path, "w", newline="") as fcsv:
                writer = csv.writer(fcsv)
                writer.writerow(
                    [
                        "category",
                        "animal_id",
                        "cell_idx",
                        "cell_num",
                        "shift_pf1_cm",
                        "shift_pf2_cm",
                        *count_cols,
                        *idx_cols,
                        "npz_path",
                    ]
                )

                for animal_id, cell_idx in all_keys:
                    e1_pre = pf1_pre_map.get((animal_id, cell_idx))
                    e2_pre = pf2_pre_map.get((animal_id, cell_idx))
                    e1_post = pf1_post_map.get((animal_id, cell_idx))
                    e2_post = pf2_post_map.get((animal_id, cell_idx))

                    shift_pf1 = float(e1_post.get("_peak_align_shift_cm", np.nan)) if e1_post is not None else np.nan
                    shift_pf2 = float(e2_post.get("_peak_align_shift_cm", np.nan)) if e2_post is not None else np.nan

                    n1_time = int(payload["rel1"].size)
                    n2_time = int(payload["rel2"].size)
                    npz_payload: dict[str, Any] = {
                        "category": str(cat),
                        "animal_id": str(animal_id),
                        "cell_idx": int(cell_idx),
                        "cell_num": int(cell_idx + 1),
                        "distance_rel_pf1": np.asarray(payload["rel1"], dtype=float),
                        "distance_rel_pf2": np.asarray(payload["rel2"], dtype=float),
                        "shift_pf1_cm": float(shift_pf1),
                        "shift_pf2_cm": float(shift_pf2),
                    }

                    row_counts: dict[str, int] = {}
                    row_idx: dict[str, float] = {}
                    for pf_rank, entry_post, n_time in ((1, e1_post, n1_time), (2, e2_post, n2_time)):
                        for direction in directions:
                            _, _, n_counts, s1_val, s2_val = _direction_mode_stats(entry_post, direction, "rate_stack", n_time)
                            row_counts[f"n_trials_pf{pf_rank}_{direction}_combined"] = int(n_counts["combined"])
                            row_counts[f"n_trials_pf{pf_rank}_{direction}_s1"] = int(n_counts["s1"])
                            row_counts[f"n_trials_pf{pf_rank}_{direction}_s2"] = int(n_counts["s2"])
                            row_idx[f"session_idx_pf{pf_rank}_{direction}_s1"] = float(s1_val) if np.isfinite(s1_val) else np.nan
                            row_idx[f"session_idx_pf{pf_rank}_{direction}_s2"] = float(s2_val) if np.isfinite(s2_val) else np.nan

                    for pf_rank, entry_pre, entry_post, n_time in (
                        (1, e1_pre, e1_post, n1_time),
                        (2, e2_pre, e2_post, n2_time),
                    ):
                        for direction in directions:
                            for metric_name, stack_key in metric_to_stack.items():
                                tr_pre, sem_pre, n_pre, _, _ = _direction_mode_stats(entry_pre, direction, stack_key, n_time)
                                tr_post, sem_post, n_post, _, _ = _direction_mode_stats(entry_post, direction, stack_key, n_time)
                                for mode in modes:
                                    npz_payload[f"pre_pf{pf_rank}_{direction}_{mode}_{metric_name}"] = tr_pre[mode]
                                    npz_payload[f"pre_pf{pf_rank}_{direction}_{mode}_sem_{metric_name}"] = sem_pre[mode]
                                    npz_payload[f"post_pf{pf_rank}_{direction}_{mode}_{metric_name}"] = tr_post[mode]
                                    npz_payload[f"post_pf{pf_rank}_{direction}_{mode}_sem_{metric_name}"] = sem_post[mode]
                                    npz_payload[f"n_trials_pre_pf{pf_rank}_{direction}_{mode}_{metric_name}"] = int(n_pre[mode])
                                    npz_payload[f"n_trials_post_pf{pf_rank}_{direction}_{mode}_{metric_name}"] = int(n_post[mode])

                    npz_name = f"{animal_id}_Cell{int(cell_idx) + 1}_direction_averages_pre_post.npz"
                    npz_path = cat_dir / npz_name
                    np.savez(npz_path, **npz_payload)

                    writer.writerow(
                        [
                            str(cat),
                            str(animal_id),
                            int(cell_idx),
                            int(cell_idx + 1),
                            float(shift_pf1) if np.isfinite(shift_pf1) else np.nan,
                            float(shift_pf2) if np.isfinite(shift_pf2) else np.nan,
                            *[int(row_counts.get(c, 0)) for c in count_cols],
                            *[
                                float(row_idx.get(c, np.nan)) if np.isfinite(float(row_idx.get(c, np.nan))) else np.nan
                                for c in idx_cols
                            ],
                            str(npz_path),
                        ]
                    )

            if cat in summary and isinstance(summary[cat], dict):
                summary[cat]["average_export_dir"] = str(cat_dir)
                summary[cat]["average_export_index_csv"] = str(csv_path)
                summary[cat]["n_average_export_files"] = int(len(all_keys))

    return summary


def plot_pf_distance_centered_category_primary_secondary_from_dataset(
    dataset: dict[str, Any],
    category: str,
    *,
    title: str,
    out_path: str | Path,
    smooth_window: float | None = 1.0,
    avg_smooth_window: float | None = None,
    plot_trials: bool = True,
    trial_alpha: float = 0.2,
    trial_linewidth: float = 0.5,
    theta_ylim: tuple[float, float] | None = (-0.02, 0.1),
    slow_ylim: tuple[float, float] | None = (-0.05, 0.2),
    fr_ylim_scale: float = 1.2,
    ss_cs_ylim_scale: float = 1.2,
    figsize_per_block: tuple[float, float] = (3.4, 3.0),
    xlim: tuple[float, float] | None = None,
    fr_row_ylim_max: float | None = 1.2,
    min_traversals_per_type: int = 5,
    align_all_peak_to_zero: bool = True,
    peak_align_window: tuple[float, float] = (-5.0, 5.0),
    max_peak_adjust_cm: float | None = None,
    max_peak_adjust_cm_pf1: float | None = None,
    max_peak_adjust_cm_pf2: float | None = None,
    x_label: str = "Distance (cm)",
    show_plot: bool = True,
) -> plt.Figure | None:
    cat = _normalize_pf_category_name(category)
    cat_data = dataset.get(cat, {})
    primary = cat_data.get(1, {})
    secondary = cat_data.get(2, {})
    distance_window_cm = float(dataset.get("metadata", {}).get("distance_window_cm", 20.0))
    distance_bin_cm = float(dataset.get("metadata", {}).get("distance_bin_cm", 1.0))
    xlim_use = (-distance_window_cm, distance_window_cm) if xlim is None else xlim
    figsize_per_block_scaled = (float(figsize_per_block[0]) * 0.5, float(figsize_per_block[1]))
    smooth_window_bins = _distance_smooth_cm_to_bins(distance_bin_cm, smooth_window)
    if avg_smooth_window is None:
        avg_smooth_window = smooth_window
    avg_smooth_window_bins = _distance_smooth_cm_to_bins(distance_bin_cm, avg_smooth_window)
    def _window_from_cap(cap_cm: float | None) -> tuple[float, float]:
        if cap_cm is None:
            return peak_align_window
        cap_cm = float(cap_cm)
        if (not np.isfinite(cap_cm)) or cap_cm < 0:
            raise ValueError("max_peak_adjust_cm values must be finite numbers >= 0.")
        return (-cap_cm, cap_cm)

    # Backward-compatible behavior: PF-specific cap overrides global cap.
    pf1_window = _window_from_cap(max_peak_adjust_cm_pf1 if max_peak_adjust_cm_pf1 is not None else max_peak_adjust_cm)
    pf2_window = _window_from_cap(max_peak_adjust_cm_pf2 if max_peak_adjust_cm_pf2 is not None else max_peak_adjust_cm)

    primary_rel = np.asarray(primary.get("distance_rel", []), dtype=float)
    secondary_rel = np.asarray(secondary.get("distance_rel", []), dtype=float)
    primary_entries = list(primary.get("entries", []))
    secondary_entries = list(secondary.get("entries", []))

    if bool(align_all_peak_to_zero) and primary_rel.size > 0:
        primary_entries = [
            _shift_distance_centered_entry_for_peak_alignment(
                entry,
                primary_rel,
                smooth_window=smooth_window_bins,
                avg_smooth_window=avg_smooth_window_bins,
                peak_align_window=pf1_window,
            )
            for entry in primary_entries
        ]
    if bool(align_all_peak_to_zero) and secondary_rel.size > 0:
        secondary_entries = [
            _shift_distance_centered_entry_for_peak_alignment(
                entry,
                secondary_rel,
                smooth_window=smooth_window_bins,
                avg_smooth_window=avg_smooth_window_bins,
                peak_align_window=pf2_window,
            )
            for entry in secondary_entries
        ]

    fig = plot_pooled_category_primary_secondary(
        time_rel_primary=primary_rel,
        entries_primary=primary_entries,
        time_rel_secondary=secondary_rel if secondary.get("distance_rel") is not None else None,
        entries_secondary=secondary_entries,
        title=title,
        out_path=None,
        smooth_window=smooth_window_bins,
        plot_trials=plot_trials,
        trial_alpha=trial_alpha,
        trial_linewidth=trial_linewidth,
        theta_ylim=theta_ylim,
        slow_ylim=slow_ylim,
        fr_ylim_scale=fr_ylim_scale,
        ss_cs_ylim_scale=ss_cs_ylim_scale,
        figsize_per_block=figsize_per_block_scaled,
        xlim=xlim_use,
        fr_row_ylim_max=fr_row_ylim_max,
        min_traversals_per_type=min_traversals_per_type,
        x_label="",
        center_line_x=0.0,
        align_all_peak_to_zero=False,
        peak_align_window=pf1_window,
        avg_smooth_window=avg_smooth_window_bins,
        show_plot=False,
        close_on_return=False,
    )
    if fig is None:
        return None
    fig.subplots_adjust(wspace=0.12, bottom=0.12)
    bottom_axes = [ax for ax in fig.axes if ax.get_subplotspec().is_last_row()]
    for ax in bottom_axes:
        ax.set_xlabel("")
    pref_bottom_axes = [ax for ax in bottom_axes if int(ax.get_subplotspec().colspan.start) in {1, 4}]
    for ax in pref_bottom_axes:
        ax.set_xlabel(str(x_label), labelpad=2.0)
    if out_path is not None:
        fig.savefig(out_path, dpi=300)
    if show_plot:
        plt.show()
    else:
        plt.close(fig)
    return fig


def _extract_cell_metric_trace_from_all_by_session(
    cell_data: dict[str, Any],
    metric_key: str,
    n_time: int,
    *,
    session_idx_filter: int | str | None = None,
    smooth_window: int | None = None,
    avg_smooth_window: int | None = None,
) -> tuple[np.ndarray | None, int]:
    """Extract mean trace from all-direction stack, optionally filtering trials by session index."""
    trace, _, n_trials = _extract_cell_metric_stats_from_all_by_session(
        cell_data,
        metric_key,
        n_time,
        session_idx_filter=session_idx_filter,
        smooth_window=smooth_window,
        avg_smooth_window=avg_smooth_window,
    )
    return trace, n_trials


def _extract_cell_metric_stats_from_all_by_session(
    cell_data: dict[str, Any],
    metric_key: str,
    n_time: int,
    *,
    session_idx_filter: int | str | None = None,
    smooth_window: int | None = None,
    avg_smooth_window: int | None = None,
) -> tuple[np.ndarray | None, np.ndarray | None, int]:
    """Extract mean/SEM trace from all-direction stack, optionally filtering trials by named session."""
    if cell_data is None:
        return None, None, 0
    dir_data = cell_data.get("all", {})
    arr = dir_data.get(metric_key)
    if arr is None:
        return None, None, 0
    arr = np.asarray(arr, dtype=float)
    smooth_win = None if smooth_window is None else int(smooth_window)
    avg_smooth_win = None if avg_smooth_window is None else int(avg_smooth_window)

    if arr.ndim == 2:
        if arr.shape[1] != int(n_time):
            return None, None, 0
        stack = arr
        if smooth_win is not None and smooth_win > 1:
            smoothed = np.full_like(stack, np.nan)
            for i in range(stack.shape[0]):
                smoothed[i] = _smooth_boxcar(stack[i], smooth_win)
            stack = smoothed
        if session_idx_filter is not None:
            td = dir_data.get("trial_data", {}) if isinstance(dir_data, dict) else {}
            sess = np.asarray(td.get("session_idx", []), dtype=int) if isinstance(td, dict) else np.array([], dtype=int)
            if sess.ndim != 1 or sess.size != int(stack.shape[0]):
                return None, None, 0
            if isinstance(session_idx_filter, str):
                filt = str(session_idx_filter).strip().lower()
                s1_named, s2_named = _resolve_two_session_label_values(sess)
                if filt == "session1":
                    target_session = s1_named
                elif filt == "session2":
                    target_session = s2_named
                else:
                    try:
                        target_session = int(filt)
                    except ValueError:
                        return None, None, 0
                if target_session is None:
                    return None, None, 0
            else:
                target_session = int(session_idx_filter)
            mask = sess == int(target_session)
            if not np.any(mask):
                return None, None, 0
            stack = stack[mask]
        if stack.shape[0] == 0:
            return None, None, 0
        trace = np.asarray(np.nanmean(stack, axis=0), dtype=float)
        n_valid = np.sum(np.isfinite(stack), axis=0)
        sem = np.asarray(np.nanstd(stack, axis=0) / np.sqrt(np.maximum(n_valid, 1)), dtype=float)
        n_trials = int(stack.shape[0])
    elif arr.ndim == 1:
        if arr.size != int(n_time):
            return None, None, 0
        if session_idx_filter is not None:
            # Cannot split session-specific traces from already-collapsed 1D means.
            return None, None, 0
        trace = arr.copy()
        if smooth_win is not None and smooth_win > 1:
            trace = _smooth_boxcar(trace, smooth_win)
        sem = np.full(int(n_time), np.nan, dtype=float)
        n_trials = int(max(1, int(dir_data.get("n_trials", 1)) if isinstance(dir_data, dict) else 1))
    else:
        return None, None, 0

    if avg_smooth_win is not None and avg_smooth_win > 1:
        trace = _smooth_boxcar(trace, avg_smooth_win)
        sem = _smooth_boxcar(sem, avg_smooth_win)
    return trace, sem, n_trials


def _plot_pooled_category_3col_sessions_on_axes(
    time_rel: np.ndarray,
    entries: list[dict[str, Any]],
    axes: np.ndarray,
    *,
    smooth_window: int | None = None,
    plot_trials: bool = True,
    trial_alpha: float = 0.2,
    trial_linewidth: float = 0.5,
    theta_ylim: tuple[float, float] | None = None,
    slow_ylim: tuple[float, float] | None = None,
    fr_ylim_scale: float = 1.2,
    ss_cs_ylim_scale: float = 1.2,
    xlim: tuple[float, float] = (-15, 15),
    title_prefix: str = "",
    set_row_labels: bool = True,
    rate_norm_denom_by_cell: dict[tuple[str, int] | tuple[str, int, str], float] | None = None,
    fr_row_ylim_max: float | None = None,
    min_traversals_per_type: int = 5,
    min_trials_per_column: int | None = None,
    x_label: str = "Distance from PF peak (cm)",
    center_line_x: float = 0.0,
    align_all_peak_to_zero: bool = False,
    peak_align_window: tuple[float, float] = (-5.0, 5.0),
    avg_smooth_window: int | None = None,
    merge_ss_cs_subplots: bool = False,
    require_both_sessions_for_pf: bool = False,
    fr_norm_reference_col: str = "all",
    fr_norm_denominator_mode: str = "zero",
    show_sem_shading: bool = True,
    session_column_titles: tuple[str, str] | list[str] | None = None,
) -> dict[str, int]:
    min_trav = int(min_traversals_per_type)
    if min_trav < 0:
        raise ValueError("min_traversals_per_type must be >= 0.")
    n_time = int(len(time_rel))
    zero_idx = int(np.argmin(np.abs(time_rel)))
    align_mask = (time_rel >= float(peak_align_window[0])) & (time_rel <= float(peak_align_window[1]))
    if not np.any(align_mask):
        align_mask = np.ones_like(time_rel, dtype=bool)

    metric_keys = ["rate_stack", "ss_rate_stack", "cs_rate_stack", "theta_stack", "slow_stack"]
    session_column_titles_use = _normalize_two_phase_labels(session_column_titles)
    col_specs: list[tuple[str, int | str | None, str]] = [
        ("all", None, "combined"),
        ("session1", "session1", str(session_column_titles_use[0])),
        ("session2", "session2", str(session_column_titles_use[1])),
    ]
    valid_norm_cols = {k for k, _, _ in col_specs}
    if str(fr_norm_reference_col) not in valid_norm_cols:
        raise ValueError(f"fr_norm_reference_col must be one of {sorted(valid_norm_cols)}.")
    denom_mode = _normalize_fr_norm_denominator_mode(fr_norm_denominator_mode)
    denom_source_counts: dict[str, int] = {"zero": 0, "peak_fallback": 0, "invalid": 0}

    def _mean_sem(arr: np.ndarray | None) -> tuple[np.ndarray | None, np.ndarray | None]:
        if arr is None or arr.size == 0:
            return None, None
        mean = np.nanmean(arr, axis=0)
        n_valid = np.sum(np.isfinite(arr), axis=0)
        sem = np.nanstd(arr, axis=0) / np.sqrt(np.maximum(n_valid, 1))
        return mean, sem

    avg_smooth_win = smooth_window if avg_smooth_window is None else avg_smooth_window
    records: list[dict[str, Any]] = []
    for entry in entries:
        cell_data = entry.get("data")
        if cell_data is None:
            continue
        session = str(entry.get("session", ""))
        cell_idx = int(entry.get("cell_idx", -1))

        traces: dict[str, dict[str, np.ndarray | None]] = {k: {} for k, _, _ in col_specs}
        n_trials_by_col: dict[str, int] = {k: 0 for k, _, _ in col_specs}
        for col_key, sess_filter, _ in col_specs:
            for mk in metric_keys:
                tr, n_tr = _extract_cell_metric_trace_from_all_by_session(
                    cell_data,
                    mk,
                    n_time,
                    session_idx_filter=sess_filter,
                    smooth_window=smooth_window,
                    avg_smooth_window=avg_smooth_win,
                )
                traces[col_key][mk] = tr
                if mk == "rate_stack":
                    n_trials_by_col[col_key] = int(n_tr)

        if bool(align_all_peak_to_zero):
            all_rate_ref = traces["all"].get("rate_stack")
            if all_rate_ref is not None:
                all_rate_ref = np.asarray(all_rate_ref, dtype=float)
                if all_rate_ref.ndim == 1 and all_rate_ref.size == n_time and np.any(np.isfinite(all_rate_ref[align_mask])):
                    masked = np.where(align_mask, all_rate_ref, np.nan)
                    peak_idx = int(np.nanargmax(masked))
                    shift_bins = int(zero_idx - peak_idx)
                    if shift_bins != 0:
                        for col_key, _, _ in col_specs:
                            for mk in metric_keys:
                                tr = traces[col_key].get(mk)
                                if tr is None:
                                    continue
                                tr_arr = np.asarray(tr, dtype=float)
                                if tr_arr.ndim == 1 and tr_arr.size == n_time:
                                    traces[col_key][mk] = _shift_trace_with_nan(tr_arr, shift_bins)

        if min_trials_per_column is None:
            if min(
                int(n_trials_by_col.get("all", 0)),
                int(n_trials_by_col.get("session1", 0)),
                int(n_trials_by_col.get("session2", 0)),
            ) < min_trav:
                continue

        rate_zero_by_col: dict[str, float] = {}
        rate_denom_by_col: dict[str, float] = {}
        rate_denom_source_by_col: dict[str, str] = {}
        for k, _, _ in col_specs:
            trk = traces[k].get("rate_stack")
            rate_zero_by_col[k] = float(trk[zero_idx]) if trk is not None and np.size(trk) > zero_idx else np.nan
            denom_val, denom_source = _fr_norm_denominator_from_trace(
                trk,
                zero_idx,
                mode=denom_mode,
            )
            rate_denom_by_col[k] = float(denom_val) if np.isfinite(denom_val) else np.nan
            rate_denom_source_by_col[k] = str(denom_source)
        all_zero = float(rate_zero_by_col.get("all", np.nan))
        ref_denom_source = str(rate_denom_source_by_col.get(str(fr_norm_reference_col), "invalid"))
        denom_source_counts[ref_denom_source] = int(denom_source_counts.get(ref_denom_source, 0)) + 1
        records.append(
            {
                "traces": traces,
                "n_trials_by_col": dict(n_trials_by_col),
                "all_rate_zero": all_zero,
                "rate_zero_by_col": dict(rate_zero_by_col),
                "rate_denom_by_col": dict(rate_denom_by_col),
                "rate_denom_source_by_col": dict(rate_denom_source_by_col),
                "session": session,
                "cell_idx": cell_idx,
            }
        )

    # Optional PF-level gate: keep only cells with both session columns present.
    # This forces the 3 columns (combined/S1/S2) to use the same cell set per PF.
    if bool(require_both_sessions_for_pf):
        if min_trials_per_column is not None:
            both_req = max(1, int(min_trials_per_column))
        else:
            both_req = max(1, int(min_trav))
        records = [
            rec
            for rec in records
            if int(rec.get("n_trials_by_col", {}).get("session1", 0)) >= both_req
            and int(rec.get("n_trials_by_col", {}).get("session2", 0)) >= both_req
        ]

    denom_source_counts = {"zero": 0, "peak_fallback": 0, "invalid": 0}
    for rec in records:
        denom_source = str(rec.get("rate_denom_source_by_col", {}).get(str(fr_norm_reference_col), "invalid"))
        denom_source_counts[denom_source] = int(denom_source_counts.get(denom_source, 0)) + 1

    def _collect_stack(col_key: str, metric_key: str, *, normalize_with_all: bool = False) -> np.ndarray | None:
        arrs: list[np.ndarray] = []
        for rec in records:
            if min_trials_per_column is not None:
                n_col = int(rec.get("n_trials_by_col", {}).get(col_key, 0))
                if n_col < int(min_trials_per_column):
                    continue
            tr = rec["traces"][col_key].get(metric_key)
            if tr is None:
                continue
            tr = np.asarray(tr, dtype=float)
            if tr.ndim != 1 or tr.size != n_time:
                continue
            if normalize_with_all:
                denom = float(rec.get("rate_denom_by_col", {}).get(str(fr_norm_reference_col), rec.get("all_rate_zero", np.nan)))
                if rate_norm_denom_by_cell is not None:
                    override = rate_norm_denom_by_cell.get((rec["session"], int(rec["cell_idx"])))
                    if override is not None and np.isfinite(override) and override != 0:
                        denom = float(override)
                if (not np.isfinite(denom)) or np.isclose(float(denom), 0.0):
                    continue
                tr = tr / float(denom)
            arrs.append(tr)
        if len(arrs) == 0:
            return None
        return np.vstack(arrs)

    if bool(merge_ss_cs_subplots):
        row_specs = [
            {"label": "Norm. FR all", "metrics": [("rate_stack", "#555555")]},
            {"label": "Norm. FR SS/CS", "metrics": [("ss_rate_stack", "#026C80"), ("cs_rate_stack", "#EE9B00")]},
            {"label": "Theta amp.", "metrics": [("theta_stack", "blue")]},
            {"label": "Slow Vm", "metrics": [("slow_stack", "red")]},
        ]
    else:
        row_specs = [
            {"label": "Norm. FR all", "metrics": [("rate_stack", "#555555")]},
            {"label": "Norm. FR SS", "metrics": [("ss_rate_stack", "#026C80")]},
            {"label": "Norm. FR CS", "metrics": [("cs_rate_stack", "#EE9B00")]},
            {"label": "Theta amp.", "metrics": [("theta_stack", "blue")]},
            {"label": "Slow Vm", "metrics": [("slow_stack", "red")]},
        ]
    n_rows = int(len(row_specs))
    if axes.ndim != 2 or int(axes.shape[0]) != n_rows or int(axes.shape[1]) != 3:
        raise ValueError(f"axes must have shape ({n_rows}, 3), got {axes.shape}.")

    fr_metric_keys = {"rate_stack", "ss_rate_stack", "cs_rate_stack"}
    means_by_metric: dict[str, list[np.ndarray]] = {
        "rate_stack": [],
        "ss_rate_stack": [],
        "cs_rate_stack": [],
        "theta_stack": [],
        "slow_stack": [],
    }
    n_cells_by_col: dict[str, int] = {k: 0 for k, _, _ in col_specs}

    for col, (col_key, _, col_title) in enumerate(col_specs):
        stacks_by_metric: dict[str, np.ndarray | None] = {
            "rate_stack": _collect_stack(col_key, "rate_stack", normalize_with_all=True),
            "ss_rate_stack": _collect_stack(col_key, "ss_rate_stack", normalize_with_all=True),
            "cs_rate_stack": _collect_stack(col_key, "cs_rate_stack", normalize_with_all=True),
            "theta_stack": _collect_stack(col_key, "theta_stack", normalize_with_all=False),
            "slow_stack": _collect_stack(col_key, "slow_stack", normalize_with_all=False),
        }
        n_cells_by_col[col_key] = int(stacks_by_metric["rate_stack"].shape[0]) if stacks_by_metric["rate_stack"] is not None else 0

        for row_i, row_spec in enumerate(row_specs):
            ax = axes[row_i, col]
            for metric_key, color in row_spec["metrics"]:
                stack = stacks_by_metric.get(metric_key)
                if plot_trials and stack is not None:
                    for i in range(stack.shape[0]):
                        ax.plot(time_rel, stack[i], color=color, linewidth=trial_linewidth, alpha=trial_alpha)
                mean, sem = _mean_sem(stack)
                if mean is not None:
                    ax.plot(time_rel, mean, color=color, linewidth=1.0)
                    if bool(show_sem_shading) and sem is not None:
                        ax.fill_between(time_rel, mean - sem, mean + sem, color=color, alpha=0.2)
                    means_by_metric[metric_key].append(np.asarray(mean, dtype=float))
            ax.axvline(center_line_x, color="black", linewidth=0.4, linestyle="--", alpha=0.6)
            if any(mk == "slow_stack" for mk, _ in row_spec["metrics"]):
                ax.axhline(0, color="black", linewidth=0.4, linestyle="--", alpha=0.6)
            if row_i == 0:
                ax.set_title("", fontsize=6)

    if set_row_labels:
        for row_i, row_spec in enumerate(row_specs):
            axes[row_i, 0].set_ylabel(str(row_spec["label"]))
    for col, (col_key, _, col_title) in enumerate(col_specs):
        axes[0, col].set_title(
            f"{title_prefix}{col_title}\n" f"n={int(n_cells_by_col.get(col_key, 0))}",
            fontsize=6,
        )
    label = str(title_prefix).strip() or "PF"
    print(
        f"{label} FR norm denominator mode={denom_mode}: "
        f"zero={int(denom_source_counts.get('zero', 0))}, "
        f"peak fallback={int(denom_source_counts.get('peak_fallback', 0))}, "
        f"invalid={int(denom_source_counts.get('invalid', 0))}"
    )
    for col in range(3):
        axes[n_rows - 1, col].set_xlabel(x_label)

    fr_peaks: list[float] = []
    for metric_key in ("rate_stack", "ss_rate_stack", "cs_rate_stack"):
        for m in means_by_metric[metric_key]:
            m_vis = np.asarray(m, dtype=float)
            if m_vis.ndim == 1 and np.any(np.isfinite(m_vis)):
                fr_peaks.append(float(np.nanmax(m_vis)))
    fr_max = float(np.nanmax(fr_peaks)) if len(fr_peaks) > 0 else 0.0
    if fr_row_ylim_max is not None:
        fr_ylim = (0.0, float(fr_row_ylim_max))
    elif fr_max > 0:
        fr_ylim = (0.0, float(fr_max * float(max(fr_ylim_scale, ss_cs_ylim_scale))))
    else:
        fr_ylim = None
    fr_rows = [
        idx
        for idx, row_spec in enumerate(row_specs)
        if any((mk in fr_metric_keys) for mk, _ in row_spec["metrics"])
    ]
    theta_rows = [
        idx
        for idx, row_spec in enumerate(row_specs)
        if any(mk == "theta_stack" for mk, _ in row_spec["metrics"])
    ]
    slow_rows = [
        idx
        for idx, row_spec in enumerate(row_specs)
        if any(mk == "slow_stack" for mk, _ in row_spec["metrics"])
    ]

    if fr_ylim is not None:
        for row_i in fr_rows:
            for col in range(3):
                axes[row_i, col].set_ylim(fr_ylim)
    # For merged SS/CS row, keep a fixed comparable scale across PF/session panels.
    if bool(merge_ss_cs_subplots) and n_rows >= 2:
        for col in range(3):
            axes[1, col].set_ylim(0.0, 1.0)

    if theta_ylim is not None:
        for row_i in theta_rows:
            for col in range(3):
                axes[row_i, col].set_ylim(theta_ylim)
    if slow_ylim is not None:
        for row_i in slow_rows:
            for col in range(3):
                axes[row_i, col].set_ylim(slow_ylim)

    for ax in axes.flat:
        ax.spines["top"].set_visible(False)
        ax.spines["right"].set_visible(False)
        ax.set_xlim(xlim)
    return n_cells_by_col


def plot_pooled_category_primary_secondary_2sessions(
    time_rel_primary: np.ndarray,
    entries_primary: list[dict[str, Any]],
    time_rel_secondary: np.ndarray | None,
    entries_secondary: list[dict[str, Any]] | None,
    title: str,
    *,
    out_path: str | Path | None = None,
    smooth_window: int | None = None,
    plot_trials: bool = True,
    trial_alpha: float = 0.2,
    trial_linewidth: float = 0.5,
    theta_ylim: tuple[float, float] | None = None,
    slow_ylim: tuple[float, float] | None = None,
    fr_ylim_scale: float = 1.2,
    ss_cs_ylim_scale: float = 1.2,
    figsize_per_block: tuple[float, float] = (3.4, 3.0),
    xlim: tuple[float, float] = (-15, 15),
    fr_row_ylim_max: float | None = 1.2,
    min_traversals_per_type: int = 5,
    min_trials_per_column: int | None = None,
    x_label_pf1: str = "Distance from PF1 peak (cm)",
    x_label_pf2: str = "Distance from PF2 peak (cm)",
    center_line_x: float = 0.0,
    align_all_peak_to_zero: bool = False,
    peak_align_window: tuple[float, float] = (-5.0, 5.0),
    avg_smooth_window: int | None = None,
    merge_ss_cs_subplots: bool = False,
    require_both_sessions_for_pf: bool = False,
    fr_norm_reference_col: str = "all",
    fr_norm_denominator_mode: str = "zero",
    show_sem_shading: bool = True,
    phase_labels: tuple[str, str] | list[str] | None = None,
    show_plot: bool = True,
    close_on_return: bool = True,
) -> plt.Figure | None:
    if time_rel_primary is None or len(entries_primary) == 0:
        print(f"No primary PF data to plot for {title}")
        return None

    phase_labels_use = _normalize_two_phase_labels(phase_labels)
    count_labels = _two_phase_count_labels(phase_labels_use)
    has_secondary = time_rel_secondary is not None and entries_secondary is not None and len(entries_secondary) > 0
    n_rows = 4 if bool(merge_ss_cs_subplots) else 5
    if not has_secondary:
        fig, axes = plt.subplots(n_rows, 3, figsize=figsize_per_block, sharex="all", sharey="row")
        n_cells_single = _plot_pooled_category_3col_sessions_on_axes(
            np.asarray(time_rel_primary, dtype=float),
            entries_primary,
            axes,
            smooth_window=smooth_window,
            plot_trials=plot_trials,
            trial_alpha=trial_alpha,
            trial_linewidth=trial_linewidth,
            theta_ylim=theta_ylim,
            slow_ylim=slow_ylim,
            fr_ylim_scale=fr_ylim_scale,
            ss_cs_ylim_scale=ss_cs_ylim_scale,
            xlim=xlim,
            title_prefix="",
            set_row_labels=True,
            fr_row_ylim_max=fr_row_ylim_max,
            min_traversals_per_type=min_traversals_per_type,
            min_trials_per_column=min_trials_per_column,
            x_label=x_label_pf1,
            center_line_x=center_line_x,
            align_all_peak_to_zero=align_all_peak_to_zero,
            peak_align_window=peak_align_window,
            avg_smooth_window=avg_smooth_window,
            merge_ss_cs_subplots=merge_ss_cs_subplots,
            require_both_sessions_for_pf=require_both_sessions_for_pf,
            fr_norm_reference_col=fr_norm_reference_col,
            fr_norm_denominator_mode=fr_norm_denominator_mode,
            show_sem_shading=show_sem_shading,
            session_column_titles=phase_labels_use,
        )
        print(
            f"[{title}] n (PF1): combined={int(n_cells_single.get('all', 0))}, "
            f"{count_labels[0]}={int(n_cells_single.get('session1', 0))}, "
            f"{count_labels[1]}={int(n_cells_single.get('session2', 0))}"
        )
        fig.suptitle(f"{title}", y=0.995)
        try:
            tight_fn = getattr(fig, "tight_layout", None)
            if callable(tight_fn):
                tight_fn(rect=[0, 0, 1, 0.98])
        except Exception:
            pass
        if out_path is not None:
            fig.savefig(out_path, dpi=300)
        if show_plot:
            plt.show()
        elif close_on_return:
            plt.close(fig)
        return fig

    # PF2 normalization uses PF1 all-traversal FR at x=0 for each cell.
    denom_map: dict[tuple[str, int] | tuple[str, int, str], float] = {}
    time_rel_primary = np.asarray(time_rel_primary, dtype=float)
    zero_idx = int(np.argmin(np.abs(time_rel_primary)))
    ref_col = str(fr_norm_reference_col).strip().lower()
    if ref_col not in {"all", "session1", "session2"}:
        raise ValueError("fr_norm_reference_col must be 'all', 'session1', or 'session2'.")
    sess_filter = None if ref_col == "all" else (0 if ref_col == "session1" else 1)
    for entry in entries_primary:
        session = str(entry.get("session", ""))
        cell_idx = int(entry.get("cell_idx", -1))
        if not session or cell_idx < 0:
            continue
        all_tr, _ = _extract_cell_metric_trace_from_all_by_session(
            entry.get("data", {}),
            "rate_stack",
            len(time_rel_primary),
            session_idx_filter=sess_filter,
            smooth_window=smooth_window,
            avg_smooth_window=(smooth_window if avg_smooth_window is None else avg_smooth_window),
        )
        denom_val, _ = _fr_norm_denominator_from_trace(
            all_tr,
            zero_idx,
            mode=fr_norm_denominator_mode,
        )
        if np.isfinite(denom_val) and not np.isclose(float(denom_val), 0.0):
            denom_map[(session, cell_idx, "all")] = float(denom_val)
            denom_map[(session, cell_idx)] = float(denom_val)

    fig_h = float(figsize_per_block[1]) * 1.25
    fig, axes = plt.subplots(
        n_rows,
        6,
        figsize=(float(figsize_per_block[0]) * 2.0, fig_h),
        sharex="all",
        sharey="row",
    )
    n_cells_primary = _plot_pooled_category_3col_sessions_on_axes(
        np.asarray(time_rel_primary, dtype=float),
        entries_primary,
        axes[:, :3],
        smooth_window=smooth_window,
        plot_trials=plot_trials,
        trial_alpha=trial_alpha,
        trial_linewidth=trial_linewidth,
        theta_ylim=theta_ylim,
        slow_ylim=slow_ylim,
        fr_ylim_scale=fr_ylim_scale,
        ss_cs_ylim_scale=ss_cs_ylim_scale,
        xlim=xlim,
        title_prefix="",
        set_row_labels=True,
        fr_row_ylim_max=fr_row_ylim_max,
        min_traversals_per_type=min_traversals_per_type,
        min_trials_per_column=min_trials_per_column,
        x_label=x_label_pf1,
        center_line_x=center_line_x,
        align_all_peak_to_zero=align_all_peak_to_zero,
        peak_align_window=peak_align_window,
        avg_smooth_window=avg_smooth_window,
        merge_ss_cs_subplots=merge_ss_cs_subplots,
        require_both_sessions_for_pf=require_both_sessions_for_pf,
        fr_norm_reference_col=fr_norm_reference_col,
        fr_norm_denominator_mode=fr_norm_denominator_mode,
        show_sem_shading=show_sem_shading,
        session_column_titles=phase_labels_use,
    )
    n_cells_secondary = _plot_pooled_category_3col_sessions_on_axes(
        np.asarray(time_rel_secondary, dtype=float),
        entries_secondary,
        axes[:, 3:],
        smooth_window=smooth_window,
        plot_trials=plot_trials,
        trial_alpha=trial_alpha,
        trial_linewidth=trial_linewidth,
        theta_ylim=theta_ylim,
        slow_ylim=slow_ylim,
        fr_ylim_scale=fr_ylim_scale,
        ss_cs_ylim_scale=ss_cs_ylim_scale,
        xlim=xlim,
        title_prefix="",
        set_row_labels=False,
        rate_norm_denom_by_cell=denom_map,
        fr_row_ylim_max=fr_row_ylim_max,
        min_traversals_per_type=min_traversals_per_type,
        min_trials_per_column=min_trials_per_column,
        x_label=x_label_pf2,
        center_line_x=center_line_x,
        align_all_peak_to_zero=align_all_peak_to_zero,
        peak_align_window=peak_align_window,
        avg_smooth_window=avg_smooth_window,
        merge_ss_cs_subplots=merge_ss_cs_subplots,
        require_both_sessions_for_pf=require_both_sessions_for_pf,
        fr_norm_reference_col=fr_norm_reference_col,
        fr_norm_denominator_mode=fr_norm_denominator_mode,
        show_sem_shading=show_sem_shading,
        session_column_titles=phase_labels_use,
    )
    print(
        f"[{title}] n (PF1): combined={int(n_cells_primary.get('all', 0))}, "
        f"{count_labels[0]}={int(n_cells_primary.get('session1', 0))}, "
        f"{count_labels[1]}={int(n_cells_primary.get('session2', 0))}"
    )
    print(
        f"[{title}] n (PF2): combined={int(n_cells_secondary.get('all', 0))}, "
        f"{count_labels[0]}={int(n_cells_secondary.get('session1', 0))}, "
        f"{count_labels[1]}={int(n_cells_secondary.get('session2', 0))}"
    )
    fig.suptitle(f"{title}", y=0.995)
    try:
        tight_fn = getattr(fig, "tight_layout", None)
        if callable(tight_fn):
            tight_fn(rect=[0, 0, 1, 0.98])
    except Exception:
        pass
    if out_path is not None:
        fig.savefig(out_path, dpi=300)
    if show_plot:
        plt.show()
    elif close_on_return:
        plt.close(fig)
    return fig


def plot_pf_distance_centered_category_primary_secondary_from_dataset_2sessions(
    dataset: dict[str, Any],
    category: str,
    *,
    title: str,
    out_path: str | Path,
    smooth_window: float | None = 1.0,
    avg_smooth_window: float | None = None,
    plot_trials: bool = True,
    trial_alpha: float = 0.2,
    trial_linewidth: float = 0.5,
    theta_ylim: tuple[float, float] | None = (-0.02, 0.1),
    slow_ylim: tuple[float, float] | None = (-0.05, 0.2),
    fr_ylim_scale: float = 1.2,
    ss_cs_ylim_scale: float = 1.2,
    figsize_per_block: tuple[float, float] = (3.4, 3.0),
    xlim: tuple[float, float] | None = None,
    distance_centered_display_xlim: tuple[float, float] | None = None,
    fr_row_ylim_max: float | None = 1.2,
    min_traversals_per_type: int = 5,
    min_trials_per_column: int | None = None,
    align_all_peak_to_zero: bool = True,
    peak_align_window: tuple[float, float] = (-5.0, 5.0),
    max_peak_adjust_cm: float | None = None,
    max_peak_adjust_cm_pf1: float | None = None,
    max_peak_adjust_cm_pf2: float | None = None,
    use_saved_average_exports: bool = True,
    average_export_dir: str | Path | None = None,
    average_export_stage: str = "post",
    enforce_min_traversals_on_saved_exports: bool = False,
    merge_ss_cs_subplots: bool = True,
    require_both_sessions_for_pf: bool = True,
    fr_norm_reference_col: str = "all",
    fr_norm_denominator_mode: str = "zero",
    show_sem_shading: bool = True,
    split_mode: str = "recorded_sessions",
    split_window_minutes: float | None = None,
    plateau_split_min_traversals_per_phase: int = 5,
    plateau_split_excluded_traversals: int = 0,
    phase_labels: tuple[str, str] | list[str] | None = None,
    x_label_pf1: str = "Distance from PF1 peak (cm)",
    x_label_pf2: str = "Distance from PF2 peak (cm)",
    show_plot: bool = True,
) -> plt.Figure | None:
    import csv

    split_mode_norm = _normalize_two_session_split_mode(split_mode)
    split_window_minutes_use = _validate_two_session_split_window_minutes(split_mode_norm, split_window_minutes)
    plateau_split_min_traversals_per_phase_use = _validate_plateau_split_min_traversals_per_phase(
        plateau_split_min_traversals_per_phase
    )
    plateau_split_excluded_traversals_use = _validate_plateau_split_excluded_traversals(
        plateau_split_excluded_traversals
    )
    phase_labels_use = _normalize_two_phase_labels(phase_labels, split_mode=split_mode_norm)
    cat = _normalize_pf_category_name(category)
    cat_data = dataset.get(cat, {})
    primary = cat_data.get(1, {})
    secondary = cat_data.get(2, {})
    distance_window_cm = float(dataset.get("metadata", {}).get("distance_window_cm", 20.0))
    distance_bin_cm = float(dataset.get("metadata", {}).get("distance_bin_cm", 1.0))
    xlim_input = distance_centered_display_xlim if distance_centered_display_xlim is not None else xlim
    xlim_use = (-distance_window_cm, distance_window_cm) if xlim_input is None else xlim_input
    figsize_per_block_scaled = (float(figsize_per_block[0]) * 0.5, float(figsize_per_block[1]))
    smooth_window_bins = _distance_smooth_cm_to_bins(distance_bin_cm, smooth_window)
    if avg_smooth_window is None:
        avg_smooth_window = smooth_window
    avg_smooth_window_bins = _distance_smooth_cm_to_bins(distance_bin_cm, avg_smooth_window)

    def _window_from_cap(cap_cm: float | None) -> tuple[float, float]:
        if cap_cm is None:
            return peak_align_window
        cap_cm = float(cap_cm)
        if (not np.isfinite(cap_cm)) or cap_cm < 0:
            raise ValueError("max_peak_adjust_cm values must be finite numbers >= 0.")
        return (-cap_cm, cap_cm)

    pf1_window = _window_from_cap(max_peak_adjust_cm_pf1 if max_peak_adjust_cm_pf1 is not None else max_peak_adjust_cm)
    pf2_window = _window_from_cap(max_peak_adjust_cm_pf2 if max_peak_adjust_cm_pf2 is not None else max_peak_adjust_cm)

    primary_rel = np.asarray(primary.get("distance_rel", []), dtype=float)
    secondary_rel = np.asarray(secondary.get("distance_rel", []), dtype=float)
    primary_entries = list(primary.get("entries", []))
    secondary_entries = list(secondary.get("entries", []))

    def _trace_1d(npz_obj: Any, key: str, n_time: int) -> np.ndarray:
        if key not in npz_obj:
            return np.full(int(n_time), np.nan, dtype=float)
        arr = np.asarray(npz_obj[key], dtype=float).reshape(-1)
        if arr.size != int(n_time):
            return np.full(int(n_time), np.nan, dtype=float)
        return arr

    def _stack_from_session_means(
        tr_s1: np.ndarray,
        tr_s2: np.ndarray,
        n_s1: int,
        n_s2: int,
    ) -> np.ndarray:
        rows: list[np.ndarray] = []
        if int(n_s1) > 0:
            rows.append(np.tile(np.asarray(tr_s1, dtype=float), (int(n_s1), 1)))
        if int(n_s2) > 0:
            rows.append(np.tile(np.asarray(tr_s2, dtype=float), (int(n_s2), 1)))
        if len(rows) == 0:
            return np.empty((0, tr_s1.size), dtype=float)
        return np.vstack(rows)

    def _build_entry_from_export(
        npz_obj: Any,
        *,
        animal_id: str,
        cell_idx: int,
        pf_rank: int,
        stage: str,
    ) -> dict[str, Any] | None:
        rel_key = f"distance_rel_pf{int(pf_rank)}"
        if rel_key not in npz_obj:
            return None
        rel = np.asarray(npz_obj[rel_key], dtype=float).reshape(-1)
        if rel.ndim != 1 or rel.size == 0:
            return None
        n_time = int(rel.size)

        n_s1_key = f"n_trials_pf{int(pf_rank)}_s1"
        n_s2_key = f"n_trials_pf{int(pf_rank)}_s2"
        n_s1 = int(npz_obj[n_s1_key]) if n_s1_key in npz_obj else 0
        n_s2 = int(npz_obj[n_s2_key]) if n_s2_key in npz_obj else 0

        idx_s1_key = f"session_idx_pf{int(pf_rank)}_s1"
        idx_s2_key = f"session_idx_pf{int(pf_rank)}_s2"
        s1_idx = int(npz_obj[idx_s1_key]) if idx_s1_key in npz_obj and np.isfinite(float(npz_obj[idx_s1_key])) else 0
        s2_idx = int(npz_obj[idx_s2_key]) if idx_s2_key in npz_obj and np.isfinite(float(npz_obj[idx_s2_key])) else 1

        metric_names = ["all_spike", "ss", "cs", "theta", "slow"]
        metric_to_stack_key = {
            "all_spike": "rate_stack",
            "ss": "ss_rate_stack",
            "cs": "cs_rate_stack",
            "theta": "theta_stack",
            "slow": "slow_stack",
        }
        stacks: dict[str, np.ndarray] = {}
        for metric in metric_names:
            k1 = f"{stage}_pf{int(pf_rank)}_s1_{metric}"
            k2 = f"{stage}_pf{int(pf_rank)}_s2_{metric}"
            tr1 = _trace_1d(npz_obj, k1, n_time)
            tr2 = _trace_1d(npz_obj, k2, n_time)
            stacks[metric_to_stack_key[metric]] = _stack_from_session_means(tr1, tr2, n_s1, n_s2)

        n_total = int(n_s1 + n_s2)
        session_idx = np.array(([s1_idx] * int(n_s1)) + ([s2_idx] * int(n_s2)), dtype=int)
        if n_total <= 0:
            session_idx = np.array([], dtype=int)
        traversal_types = np.array((["cw"] * int(n_s1)) + (["ccw"] * int(n_s2)), dtype=object)

        rate_stack = stacks["rate_stack"]
        ss_stack = stacks["ss_rate_stack"]
        cs_stack = stacks["cs_rate_stack"]
        with np.errstate(divide="ignore", invalid="ignore"):
            denom = ss_stack + cs_stack
            ss_pct_stack = np.where(np.isfinite(denom) & (denom > 0), 100.0 * ss_stack / denom, np.nan) if ss_stack.size > 0 else np.empty((0, n_time), dtype=float)
            cs_pct_stack = np.where(np.isfinite(denom) & (denom > 0), 100.0 * cs_stack / denom, np.nan) if cs_stack.size > 0 else np.empty((0, n_time), dtype=float)

        def _mean_or_nan(stack: np.ndarray) -> np.ndarray:
            if stack.ndim == 2 and stack.shape[0] > 0:
                return np.nanmean(stack, axis=0)
            return np.full(n_time, np.nan, dtype=float)

        data_all = {
            "distance_rel": rel,
            "n_trials": int(n_total),
            "n_total_trials": int(n_total),
            "rate_stack": rate_stack,
            "ss_rate_stack": ss_stack,
            "cs_rate_stack": cs_stack,
            "theta_stack": stacks["theta_stack"],
            "slow_stack": stacks["slow_stack"],
            "plateau_stack": np.zeros((int(n_total), n_time), dtype=float) if n_total > 0 else np.empty((0, n_time), dtype=float),
            "rate_mean": _mean_or_nan(rate_stack),
            "ss_rate_mean": _mean_or_nan(ss_stack),
            "cs_rate_mean": _mean_or_nan(cs_stack),
            "theta_mean": _mean_or_nan(stacks["theta_stack"]),
            "slow_mean": _mean_or_nan(stacks["slow_stack"]),
            "ss_pct_mean": _mean_or_nan(ss_pct_stack),
            "cs_pct_mean": _mean_or_nan(cs_pct_stack),
            "trial_data": {
                "session_idx": session_idx,
                "traversal_types": traversal_types,
            },
        }
        return {
            "session": str(animal_id),
            "cell_idx": int(cell_idx),
            "pf_rank": int(pf_rank),
            "data": {
                "all": data_all,
                "cw": {"n_trials": int(n_s1)},
                "ccw": {"n_trials": int(n_s2)},
            },
        }

    if bool(use_saved_average_exports):
        stage = str(average_export_stage).strip().lower()
        if stage not in {"pre", "post"}:
            raise ValueError("average_export_stage must be 'pre' or 'post'.")
        if average_export_dir is None:
            export_root = Path(out_path).resolve().parent / "pf_distance_centered_2sessions_average_exports"
        else:
            export_root = Path(average_export_dir)
        cat_export_dir = export_root / cat
        index_csv = cat_export_dir / "session_averages_pre_post_index.csv"
        used_saved_average_exports_local = False
        if index_csv.exists():
            loaded_primary_entries: list[dict[str, Any]] = []
            loaded_secondary_entries: list[dict[str, Any]] = []
            rel_pf1: np.ndarray | None = None
            rel_pf2: np.ndarray | None = None
            with open(index_csv, newline="") as f:
                reader = csv.DictReader(f)
                for row in reader:
                    animal_id = str(row.get("animal_id", ""))
                    cell_idx = int(row.get("cell_idx", -1))
                    npz_path = Path(str(row.get("npz_path", "")))
                    if not npz_path.exists():
                        continue
                    try:
                        npz = np.load(npz_path, allow_pickle=True)
                    except Exception:
                        continue
                    if not _export_matches_two_session_split(
                        row,
                        npz,
                        split_mode=split_mode_norm,
                        split_window_minutes=split_window_minutes_use,
                        plateau_split_min_traversals_per_phase=plateau_split_min_traversals_per_phase_use,
                        plateau_split_excluded_traversals=plateau_split_excluded_traversals_use,
                    ):
                        try:
                            npz.close()
                        except Exception:
                            pass
                        continue
                    entry_pf1 = _build_entry_from_export(npz, animal_id=animal_id, cell_idx=cell_idx, pf_rank=1, stage=stage)
                    entry_pf2 = _build_entry_from_export(npz, animal_id=animal_id, cell_idx=cell_idx, pf_rank=2, stage=stage)
                    if entry_pf1 is not None:
                        loaded_primary_entries.append(entry_pf1)
                        if rel_pf1 is None and "distance_rel_pf1" in npz:
                            rel_pf1 = np.asarray(npz["distance_rel_pf1"], dtype=float).reshape(-1)
                    if entry_pf2 is not None:
                        loaded_secondary_entries.append(entry_pf2)
                        if rel_pf2 is None and "distance_rel_pf2" in npz:
                            rel_pf2 = np.asarray(npz["distance_rel_pf2"], dtype=float).reshape(-1)
                    try:
                        npz.close()
                    except Exception:
                        pass
            if len(loaded_primary_entries) > 0:
                primary_entries = loaded_primary_entries
                if rel_pf1 is not None and rel_pf1.size > 0:
                    primary_rel = rel_pf1
            if len(loaded_secondary_entries) > 0:
                secondary_entries = loaded_secondary_entries
                if rel_pf2 is not None and rel_pf2.size > 0:
                    secondary_rel = rel_pf2
            used_saved_average_exports_local = bool(len(loaded_primary_entries) > 0 or len(loaded_secondary_entries) > 0)
            if bool(used_saved_average_exports_local):
                # Exported traces are already pre/post aligned; do not shift again.
                align_all_peak_to_zero = False
                # Exported traces are session means already smoothed in the heatmap pipeline;
                # avoid re-smoothing in this plotting function.
                smooth_window_bins = 0
                avg_smooth_window_bins = 0
        if not bool(used_saved_average_exports_local):
            primary_entries = _split_distance_centered_entries_for_two_sessions(
                primary_entries,
                split_mode=split_mode_norm,
                split_window_minutes=split_window_minutes_use,
                plateau_split_min_traversals_per_phase=plateau_split_min_traversals_per_phase_use,
                plateau_split_excluded_traversals=plateau_split_excluded_traversals_use,
            )
            secondary_entries = _split_distance_centered_entries_for_two_sessions(
                secondary_entries,
                split_mode=split_mode_norm,
                split_window_minutes=split_window_minutes_use,
                plateau_split_min_traversals_per_phase=plateau_split_min_traversals_per_phase_use,
                plateau_split_excluded_traversals=plateau_split_excluded_traversals_use,
            )
    else:
        primary_entries = _split_distance_centered_entries_for_two_sessions(
            primary_entries,
            split_mode=split_mode_norm,
            split_window_minutes=split_window_minutes_use,
            plateau_split_min_traversals_per_phase=plateau_split_min_traversals_per_phase_use,
            plateau_split_excluded_traversals=plateau_split_excluded_traversals_use,
        )
        secondary_entries = _split_distance_centered_entries_for_two_sessions(
            secondary_entries,
            split_mode=split_mode_norm,
            split_window_minutes=split_window_minutes_use,
            plateau_split_min_traversals_per_phase=plateau_split_min_traversals_per_phase_use,
            plateau_split_excluded_traversals=plateau_split_excluded_traversals_use,
        )
    if bool(align_all_peak_to_zero) and primary_rel.size > 0:
        primary_entries = [
            _shift_distance_centered_entry_for_peak_alignment(
                entry,
                primary_rel,
                smooth_window=smooth_window_bins,
                avg_smooth_window=avg_smooth_window_bins,
                peak_align_window=pf1_window,
            )
            for entry in primary_entries
        ]
    if bool(align_all_peak_to_zero) and secondary_rel.size > 0:
        secondary_entries = [
            _shift_distance_centered_entry_for_peak_alignment(
                entry,
                secondary_rel,
                smooth_window=smooth_window_bins,
                avg_smooth_window=avg_smooth_window_bins,
                peak_align_window=pf2_window,
            )
            for entry in secondary_entries
        ]

    fig = plot_pooled_category_primary_secondary_2sessions(
        time_rel_primary=primary_rel,
        entries_primary=primary_entries,
        time_rel_secondary=secondary_rel if secondary.get("distance_rel") is not None else None,
        entries_secondary=secondary_entries,
        title=title,
        out_path=None,
        smooth_window=smooth_window_bins,
        plot_trials=plot_trials,
        trial_alpha=trial_alpha,
        trial_linewidth=trial_linewidth,
        theta_ylim=theta_ylim,
        slow_ylim=slow_ylim,
        fr_ylim_scale=fr_ylim_scale,
        ss_cs_ylim_scale=ss_cs_ylim_scale,
        figsize_per_block=figsize_per_block_scaled,
        xlim=xlim_use,
        fr_row_ylim_max=fr_row_ylim_max,
        min_traversals_per_type=(
            int(min_traversals_per_type)
            if (not bool(use_saved_average_exports) or bool(enforce_min_traversals_on_saved_exports))
            else 0
        ),
        min_trials_per_column=min_trials_per_column,
        x_label_pf1=str(x_label_pf1),
        x_label_pf2=str(x_label_pf2),
        center_line_x=0.0,
        align_all_peak_to_zero=False,
        peak_align_window=pf1_window,
        avg_smooth_window=avg_smooth_window_bins,
        merge_ss_cs_subplots=merge_ss_cs_subplots,
        require_both_sessions_for_pf=require_both_sessions_for_pf,
        fr_norm_reference_col=fr_norm_reference_col,
        fr_norm_denominator_mode=fr_norm_denominator_mode,
        show_sem_shading=show_sem_shading,
        phase_labels=phase_labels_use,
        show_plot=False,
        close_on_return=False,
    )
    if fig is None:
        return None
    fig.subplots_adjust(wspace=0.12, hspace=0.20, bottom=0.12)
    if out_path is not None:
        fig.savefig(out_path, dpi=300)
    if show_plot:
        plt.show()
    else:
        plt.close(fig)
    return fig


def build_direction_average_fr_norm_denominator_map(
    average_export_dir: str | Path,
    category: str,
    *,
    pf_rank_for_denominator: int = 1,
    stage: str = "post",
    avg_mode: str = "combined",
    fr_norm_reference_col: str = "all",
    fr_norm_denominator_mode: str = "zero",
    direction_keys: tuple[str, str, str] | list[str] = ("all", "cw", "ccw"),
    explicit_preferred_nonpreferred_keys: tuple[str, str] | list[str] | None = None,
) -> dict[str, Any]:
    """Build per-cell FR normalization denominators from direction average exports.

    The returned map is keyed by ``(animal_id, cell_idx)`` and
    ``(animal_id, cell_idx, "all")`` so it can be passed directly as
    ``rate_norm_denom_by_cell`` to the pooled direction plotting helpers.
    """
    import csv

    export_root = Path(average_export_dir)
    cat = _normalize_pf_category_name(category)
    mode_norm = _normalize_direction_avg_mode(avg_mode)
    stage_norm = str(stage).strip().lower()
    if stage_norm not in {"pre", "post"}:
        raise ValueError("stage must be 'pre' or 'post'.")
    dir_keys, _ = _normalize_direction_triplet(direction_keys=direction_keys, direction_titles=None)
    all_key, cw_key, ccw_key = str(dir_keys[0]), str(dir_keys[1]), str(dir_keys[2])
    pf_rank = int(pf_rank_for_denominator)
    if pf_rank < 1:
        raise ValueError("pf_rank_for_denominator must be >= 1.")

    ref_norm = str(fr_norm_reference_col).strip().lower()
    ref_aliases = {
        "all": "all",
        "combined": "all",
        "pref": "preferred",
        "preferred": "preferred",
        "nonpref": "nonpreferred",
        "non-pref": "nonpreferred",
        "nonpreferred": "nonpreferred",
        "non-preferred": "nonpreferred",
    }
    if ref_norm not in ref_aliases:
        raise ValueError("fr_norm_reference_col must be one of: 'all', 'preferred', or 'nonpreferred'.")
    ref_norm = ref_aliases[ref_norm]
    denom_mode = _normalize_fr_norm_denominator_mode(fr_norm_denominator_mode)

    index_csv = export_root / cat / "session_averages_pre_post_index.csv"
    denom_by_cell: dict[tuple[str, int] | tuple[str, int, str], float] = {}
    skipped_rows: list[dict[str, Any]] = []
    summary = {
        "category": cat,
        "index_csv": str(index_csv),
        "rows": 0,
        "denominator_cells": 0,
        "skipped": 0,
        "stage": stage_norm,
        "avg_mode": mode_norm,
        "pf_rank_for_denominator": pf_rank,
        "fr_norm_reference_col": ref_norm,
        "fr_norm_denominator_mode": denom_mode,
    }
    if not index_csv.exists():
        summary["missing_index"] = True
        return {"denom_by_cell": denom_by_cell, "summary": summary, "skipped_rows": skipped_rows}

    def _row_int(row: dict[str, Any], key: str, default: int = -1) -> int:
        try:
            value = row.get(key, default)
            if value is None or value == "":
                return int(default)
            return int(float(value))
        except Exception:
            return int(default)

    def _trace_from_npz(npz_obj: Any, key: str) -> np.ndarray | None:
        if key not in npz_obj:
            return None
        arr = np.asarray(npz_obj[key], dtype=float).reshape(-1)
        if arr.ndim != 1 or arr.size == 0:
            return None
        return arr

    with index_csv.open(newline="") as f:
        rows = list(csv.DictReader(f))
    summary["rows"] = int(len(rows))

    for row in rows:
        animal_id = str(row.get("animal_id", ""))
        cell_idx = _row_int(row, "cell_idx", -1)
        if not animal_id or cell_idx < 0:
            skipped_rows.append({"animal_id": animal_id, "cell_idx": cell_idx, "reason": "invalid cell key"})
            continue
        npz_path = Path(str(row.get("npz_path", "")))
        if not npz_path.is_absolute():
            npz_path = index_csv.parent / npz_path
        if not npz_path.exists():
            skipped_rows.append({"animal_id": animal_id, "cell_idx": cell_idx, "reason": "missing npz", "npz_path": str(npz_path)})
            continue
        try:
            with np.load(npz_path, allow_pickle=True) as npz:
                rel = _trace_from_npz(npz, f"distance_rel_pf{pf_rank}")
                if rel is None:
                    skipped_rows.append({"animal_id": animal_id, "cell_idx": cell_idx, "reason": "missing distance axis"})
                    continue
                zero_idx = int(np.argmin(np.abs(rel)))
                all_trace = _trace_from_npz(npz, f"{stage_norm}_pf{pf_rank}_{all_key}_{mode_norm}_all_spike")
                cw_trace = _trace_from_npz(npz, f"{stage_norm}_pf{pf_rank}_{cw_key}_{mode_norm}_all_spike")
                ccw_trace = _trace_from_npz(npz, f"{stage_norm}_pf{pf_rank}_{ccw_key}_{mode_norm}_all_spike")
                if explicit_preferred_nonpreferred_keys is not None:
                    pref_nonpref = tuple(explicit_preferred_nonpreferred_keys)
                    if len(pref_nonpref) != 2:
                        raise ValueError("explicit_preferred_nonpreferred_keys must contain exactly two keys.")
                    pref_key = str(pref_nonpref[0]).strip()
                    nonpref_key = str(pref_nonpref[1]).strip()
                else:
                    preferred = _infer_preferred_direction_from_rate_traces(cw_trace, ccw_trace)
                    if preferred == "cw":
                        pref_key, nonpref_key = cw_key, ccw_key
                    elif preferred == "ccw":
                        pref_key, nonpref_key = ccw_key, cw_key
                    else:
                        pref_key, nonpref_key = None, None
                if ref_norm == "all":
                    ref_key = all_key
                    ref_trace = all_trace
                elif ref_norm == "preferred":
                    ref_key = pref_key
                    ref_trace = _trace_from_npz(npz, f"{stage_norm}_pf{pf_rank}_{ref_key}_{mode_norm}_all_spike") if ref_key else None
                else:
                    ref_key = nonpref_key
                    ref_trace = _trace_from_npz(npz, f"{stage_norm}_pf{pf_rank}_{ref_key}_{mode_norm}_all_spike") if ref_key else None
                denom_val, denom_source = _fr_norm_denominator_from_trace(ref_trace, zero_idx, mode=denom_mode)
        except Exception as exc:
            skipped_rows.append({"animal_id": animal_id, "cell_idx": cell_idx, "reason": f"load/calculation failed: {exc}", "npz_path": str(npz_path)})
            continue
        if not np.isfinite(denom_val) or np.isclose(float(denom_val), 0.0):
            skipped_rows.append(
                {
                    "animal_id": animal_id,
                    "cell_idx": cell_idx,
                    "reason": "invalid denominator",
                    "denominator_source": str(denom_source),
                    "reference_direction": ref_key,
                }
            )
            continue
        denom = float(denom_val)
        denom_by_cell[(animal_id, int(cell_idx))] = denom
        denom_by_cell[(animal_id, int(cell_idx), "all")] = denom

    summary["denominator_cells"] = int(len({(k[0], k[1]) for k in denom_by_cell if len(k) >= 2}))
    summary["skipped"] = int(len(skipped_rows))
    return {"denom_by_cell": denom_by_cell, "summary": summary, "skipped_rows": skipped_rows}


def plot_pf_distance_centered_category_primary_secondary_from_dataset_2directions(
    dataset: dict[str, Any],
    category: str,
    *,
    title: str,
    out_path: str | Path,
    smooth_window: float | None = 1.0,
    avg_smooth_window: float | None = None,
    plot_trials: bool = True,
    trial_alpha: float = 0.2,
    trial_linewidth: float = 0.5,
    theta_ylim: tuple[float, float] | None = (-0.02, 0.1),
    slow_ylim: tuple[float, float] | None = (-0.05, 0.2),
    fr_ylim_scale: float = 1.2,
    ss_cs_ylim_scale: float = 1.2,
    figsize_per_block: tuple[float, float] = (3.4, 3.0),
    xlim: tuple[float, float] | None = None,
    distance_centered_display_xlim: tuple[float, float] | None = None,
    fr_row_ylim_max: float | None = 1.2,
    ss_cs_row_ylim_max: float | None = None,
    min_traversals_per_type: int = 5,
    min_trials_per_column: int | None = None,
    align_all_peak_to_zero: bool = True,
    peak_align_window: tuple[float, float] = (-5.0, 5.0),
    max_peak_adjust_cm: float | None = None,
    max_peak_adjust_cm_pf1: float | None = None,
    max_peak_adjust_cm_pf2: float | None = None,
    use_saved_average_exports: bool = True,
    average_export_dir: str | Path | None = None,
    average_export_stage: str = "post",
    avg_mode: str = "combined",
    enforce_min_traversals_on_saved_exports: bool = False,
    show_sem_shading: bool = True,
    show_column_counts_in_titles: bool = False,
    direction_keys: tuple[str, str, str] | list[str] = ("all", "cw", "ccw"),
    direction_titles: tuple[str, str, str] | list[str] = ("All", "Pref", "Non-pref"),
    explicit_preferred_nonpreferred_keys: tuple[str, str] | list[str] | None = None,
    fr_norm_reference_col: str = "all",
    fr_norm_denominator_mode: str = "zero",
    rate_norm_denom_by_cell: dict[tuple[str, int] | tuple[str, int, str], float] | None = None,
    x_label: str = "Distance (cm)",
    x_ticks: tuple[float, ...] | list[float] | np.ndarray | None = None,
    show_plot: bool = True,
) -> plt.Figure | None:
    import csv

    mode_norm = _normalize_direction_avg_mode(avg_mode)
    dir_keys, dir_titles = _normalize_direction_triplet(
        direction_keys=direction_keys,
        direction_titles=direction_titles,
    )
    cat = _normalize_pf_category_name(category)
    cat_data = dataset.get(cat, {})
    primary = cat_data.get(1, {})
    secondary = cat_data.get(2, {})
    distance_window_cm = float(dataset.get("metadata", {}).get("distance_window_cm", 20.0))
    distance_bin_cm = float(dataset.get("metadata", {}).get("distance_bin_cm", 1.0))
    xlim_input = distance_centered_display_xlim if distance_centered_display_xlim is not None else xlim
    xlim_use = (-distance_window_cm, distance_window_cm) if xlim_input is None else xlim_input
    figsize_per_block_scaled = (float(figsize_per_block[0]) * 0.5, float(figsize_per_block[1]))
    smooth_window_bins = _distance_smooth_cm_to_bins(distance_bin_cm, smooth_window)
    if avg_smooth_window is None:
        avg_smooth_window = smooth_window
    avg_smooth_window_bins = _distance_smooth_cm_to_bins(distance_bin_cm, avg_smooth_window)

    def _window_from_cap(cap_cm: float | None) -> tuple[float, float]:
        if cap_cm is None:
            return peak_align_window
        cap_cm_f = float(cap_cm)
        if (not np.isfinite(cap_cm_f)) or cap_cm_f < 0:
            raise ValueError("max_peak_adjust_cm values must be finite numbers >= 0.")
        return (-cap_cm_f, cap_cm_f)

    pf1_window = _window_from_cap(max_peak_adjust_cm_pf1 if max_peak_adjust_cm_pf1 is not None else max_peak_adjust_cm)
    pf2_window = _window_from_cap(max_peak_adjust_cm_pf2 if max_peak_adjust_cm_pf2 is not None else max_peak_adjust_cm)

    primary_rel = np.asarray(primary.get("distance_rel", []), dtype=float)
    secondary_rel = np.asarray(secondary.get("distance_rel", []), dtype=float)
    primary_entries = list(primary.get("entries", []))
    secondary_entries = list(secondary.get("entries", []))

    def _trace_1d(npz_obj: Any, key: str, n_time: int) -> np.ndarray:
        if key not in npz_obj:
            return np.full(int(n_time), np.nan, dtype=float)
        arr = np.asarray(npz_obj[key], dtype=float).reshape(-1)
        if arr.size != int(n_time):
            return np.full(int(n_time), np.nan, dtype=float)
        return arr

    def _stack_from_trace(trace: np.ndarray, n_rows: int) -> np.ndarray:
        n_rows_i = int(max(0, int(n_rows)))
        if n_rows_i <= 0:
            return np.empty((0, trace.size), dtype=float)
        return np.tile(np.asarray(trace, dtype=float), (n_rows_i, 1))

    def _build_entry_from_export(
        npz_obj: Any,
        *,
        animal_id: str,
        cell_idx: int,
        pf_rank: int,
        stage: str,
        mode: str,
    ) -> dict[str, Any] | None:
        rel_key = f"distance_rel_pf{int(pf_rank)}"
        if rel_key not in npz_obj:
            return None
        rel = np.asarray(npz_obj[rel_key], dtype=float).reshape(-1)
        if rel.ndim != 1 or rel.size == 0:
            return None
        n_time = int(rel.size)
        metric_to_stack_key = {
            "all_spike": "rate_stack",
            "ss": "ss_rate_stack",
            "cs": "cs_rate_stack",
            "theta": "theta_stack",
            "slow": "slow_stack",
        }
        directions = tuple(dir_keys)
        data_out: dict[str, Any] = {}

        for direction in directions:
            n_key = f"n_trials_{stage}_pf{int(pf_rank)}_{direction}_{mode}_all_spike"
            n_trials = int(npz_obj[n_key]) if n_key in npz_obj else 0
            dir_data: dict[str, Any] = {
                "distance_rel": rel,
                "n_trials": int(n_trials),
                "n_total_trials": int(n_trials),
                "trial_data": {
                    "traversal_types": np.array([str(direction)] * int(max(0, n_trials)), dtype=object),
                },
            }
            for metric, stack_key in metric_to_stack_key.items():
                key = f"{stage}_pf{int(pf_rank)}_{direction}_{mode}_{metric}"
                tr = _trace_1d(npz_obj, key, n_time)
                st = _stack_from_trace(tr, int(n_trials))
                dir_data[stack_key] = st
                mean_key = stack_key.replace("_stack", "_mean")
                dir_data[mean_key] = tr.copy()
            ss_stack = np.asarray(dir_data["ss_rate_stack"], dtype=float)
            cs_stack = np.asarray(dir_data["cs_rate_stack"], dtype=float)
            with np.errstate(divide="ignore", invalid="ignore"):
                denom = ss_stack + cs_stack
                ss_pct = np.where(np.isfinite(denom) & (denom > 0), 100.0 * ss_stack / denom, np.nan) if ss_stack.size > 0 else np.empty((0, n_time), dtype=float)
                cs_pct = np.where(np.isfinite(denom) & (denom > 0), 100.0 * cs_stack / denom, np.nan) if cs_stack.size > 0 else np.empty((0, n_time), dtype=float)
            dir_data["ss_pct_mean"] = np.nanmean(ss_pct, axis=0) if ss_pct.size > 0 else np.full(n_time, np.nan, dtype=float)
            dir_data["cs_pct_mean"] = np.nanmean(cs_pct, axis=0) if cs_pct.size > 0 else np.full(n_time, np.nan, dtype=float)
            data_out[direction] = dir_data

        return {
            "session": str(animal_id),
            "cell_idx": int(cell_idx),
            "pf_rank": int(pf_rank),
            "data": data_out,
        }

    if bool(use_saved_average_exports):
        stage = str(average_export_stage).strip().lower()
        if stage not in {"pre", "post"}:
            raise ValueError("average_export_stage must be 'pre' or 'post'.")
        if average_export_dir is None:
            export_root = Path(out_path).resolve().parent / "pf_distance_centered_2directions_average_exports"
        else:
            export_root = Path(average_export_dir)
        cat_export_dir = export_root / cat
        index_csv = cat_export_dir / "session_averages_pre_post_index.csv"
        if index_csv.exists():
            loaded_primary_entries: list[dict[str, Any]] = []
            loaded_secondary_entries: list[dict[str, Any]] = []
            rel_pf1: np.ndarray | None = None
            rel_pf2: np.ndarray | None = None
            with open(index_csv, newline="") as f:
                reader = csv.DictReader(f)
                for row in reader:
                    animal_id = str(row.get("animal_id", ""))
                    cell_idx = int(row.get("cell_idx", -1))
                    npz_path = Path(str(row.get("npz_path", "")))
                    if not npz_path.exists():
                        continue
                    try:
                        npz = np.load(npz_path, allow_pickle=True)
                    except Exception:
                        continue
                    entry_pf1 = _build_entry_from_export(
                        npz,
                        animal_id=animal_id,
                        cell_idx=cell_idx,
                        pf_rank=1,
                        stage=stage,
                        mode=mode_norm,
                    )
                    entry_pf2 = _build_entry_from_export(
                        npz,
                        animal_id=animal_id,
                        cell_idx=cell_idx,
                        pf_rank=2,
                        stage=stage,
                        mode=mode_norm,
                    )
                    if entry_pf1 is not None:
                        loaded_primary_entries.append(entry_pf1)
                        if rel_pf1 is None and "distance_rel_pf1" in npz:
                            rel_pf1 = np.asarray(npz["distance_rel_pf1"], dtype=float).reshape(-1)
                    if entry_pf2 is not None:
                        loaded_secondary_entries.append(entry_pf2)
                        if rel_pf2 is None and "distance_rel_pf2" in npz:
                            rel_pf2 = np.asarray(npz["distance_rel_pf2"], dtype=float).reshape(-1)
            if len(loaded_primary_entries) > 0:
                primary_entries = loaded_primary_entries
                if rel_pf1 is not None and rel_pf1.size > 0:
                    primary_rel = rel_pf1
            if len(loaded_secondary_entries) > 0:
                secondary_entries = loaded_secondary_entries
                if rel_pf2 is not None and rel_pf2.size > 0:
                    secondary_rel = rel_pf2
            # Exported traces are already aligned/smoothed in heatmap pipeline.
            align_all_peak_to_zero = False
            smooth_window_bins = 0
            avg_smooth_window_bins = 0
    else:
        if mode_norm != "combined":
            primary_entries = [
                _filter_entry_by_avg_mode_for_directions(e, avg_mode=mode_norm, direction_keys=dir_keys)
                for e in primary_entries
            ]
            secondary_entries = [
                _filter_entry_by_avg_mode_for_directions(e, avg_mode=mode_norm, direction_keys=dir_keys)
                for e in secondary_entries
            ]

    if bool(align_all_peak_to_zero) and primary_rel.size > 0:
        primary_entries = [
            _shift_distance_centered_entry_for_peak_alignment(
                entry,
                primary_rel,
                smooth_window=smooth_window_bins,
                avg_smooth_window=avg_smooth_window_bins,
                peak_align_window=pf1_window,
            )
            for entry in primary_entries
        ]
    if bool(align_all_peak_to_zero) and secondary_rel.size > 0:
        secondary_entries = [
            _shift_distance_centered_entry_for_peak_alignment(
                entry,
                secondary_rel,
                smooth_window=smooth_window_bins,
                avg_smooth_window=avg_smooth_window_bins,
                peak_align_window=pf2_window,
            )
            for entry in secondary_entries
        ]

    fig = plot_pooled_category_primary_secondary(
        time_rel_primary=primary_rel,
        entries_primary=primary_entries,
        time_rel_secondary=secondary_rel if secondary.get("distance_rel") is not None else None,
        entries_secondary=secondary_entries,
        title=title,
        out_path=None,
        smooth_window=smooth_window_bins,
        plot_trials=plot_trials,
        trial_alpha=trial_alpha,
        trial_linewidth=trial_linewidth,
        theta_ylim=theta_ylim,
        slow_ylim=slow_ylim,
        fr_ylim_scale=fr_ylim_scale,
        ss_cs_ylim_scale=ss_cs_ylim_scale,
        figsize_per_block=figsize_per_block_scaled,
        xlim=xlim_use,
        fr_row_ylim_max=fr_row_ylim_max,
        ss_cs_row_ylim_max=ss_cs_row_ylim_max,
        min_traversals_per_type=(
            int(min_traversals_per_type)
            if (not bool(use_saved_average_exports) or bool(enforce_min_traversals_on_saved_exports))
            else 0
        ),
        min_trials_per_column=min_trials_per_column,
        x_label="",
        center_line_x=0.0,
        align_all_peak_to_zero=False,
        peak_align_window=pf1_window,
        avg_smooth_window=avg_smooth_window_bins,
        show_sem_shading=show_sem_shading,
        show_plot=False,
        close_on_return=False,
        all_direction_key=str(dir_keys[0]),
        cw_direction_key=str(dir_keys[1]),
        ccw_direction_key=str(dir_keys[2]),
        explicit_preferred_nonpreferred_keys=explicit_preferred_nonpreferred_keys,
        direction_titles=dir_titles,
        fr_norm_reference_col=fr_norm_reference_col,
        fr_norm_denominator_mode=fr_norm_denominator_mode,
        rate_norm_denom_by_cell=rate_norm_denom_by_cell,
        x_ticks=x_ticks,
        show_column_counts_in_titles=show_column_counts_in_titles,
    )
    if fig is None:
        return None
    fig.subplots_adjust(wspace=0.12, bottom=0.12)
    bottom_axes = [ax for ax in fig.axes if ax.get_subplotspec().is_last_row()]
    for ax in bottom_axes:
        ax.set_xlabel("")
    pref_bottom_axes = [ax for ax in bottom_axes if int(ax.get_subplotspec().colspan.start) in {1, 4}]
    for ax in pref_bottom_axes:
        ax.set_xlabel(str(x_label), labelpad=2.0)
    if out_path is not None:
        fig.savefig(out_path, dpi=300)
    if show_plot:
        plt.show()
    else:
        plt.close(fig)
    return fig


def compute_pf_distance_centered_pref_nonpref_stats(
    distance_centered_dataset: dict[str, Any],
    *,
    timepoint_cm: float = 0.0,
    min_traversals_per_type: int = 5,
    smooth_window_cm: float | None = 0.0,
    auc_window_cm: tuple[float, float] | None = None,
    slow_auc_window_cm: tuple[float, float] = (-10.0, 10.0),
    peak_window_cm: tuple[float, float] = (-10.0, 10.0),
    use_saved_average_exports: bool = True,
    average_export_dir: str | Path | None = None,
    average_export_stage: str = "post",
    avg_mode: str = "combined",
    all_direction_key: str = "all",
    cw_direction_key: str = "cw",
    ccw_direction_key: str = "ccw",
    explicit_preferred_nonpreferred_keys: tuple[str, str] | list[str] | None = None,
    print_nan_diagnostics: bool = True,
    set_nan_r_to_zero: bool = True,
) -> dict[str, Any]:
    """
    Compute Pref-vs-Non-pref stability metrics using the same framework as compare-sessions.

    For each cell/group/metric, compute between preferred and non-preferred traces:
      - r (Pearson correlation)
      - delta_peak_x_cm (Non-pref minus Pref peak location)
      - auc_ratio (AUC_nonpref / AUC_pref)
      - peak_ratio_s2_s1 (peak_nonpref / peak_pref)
      - peak_abs_sym_diff (abs((peak_nonpref-peak_pref)/(peak_nonpref+peak_pref)))

    Preferred direction is defined by higher all-spike peak between CW and CCW unless
    explicit_preferred_nonpreferred_keys is provided.
    `timepoint_cm` is kept for API compatibility and is not used.
    """
    import csv
    import pandas as pd

    mode_norm = _normalize_direction_avg_mode(avg_mode)
    all_key = str(all_direction_key).strip()
    cw_key = str(cw_direction_key).strip()
    ccw_key = str(ccw_direction_key).strip()
    if len(all_key) == 0 or len(cw_key) == 0 or len(ccw_key) == 0:
        raise ValueError("Direction keys cannot be empty.")
    if explicit_preferred_nonpreferred_keys is None:
        pref_key_fixed = None
        nonpref_key_fixed = None
    else:
        pref_nonpref = tuple(explicit_preferred_nonpreferred_keys)
        if len(pref_nonpref) != 2:
            raise ValueError("explicit_preferred_nonpreferred_keys must contain exactly two keys.")
        pref_key_fixed = str(pref_nonpref[0]).strip()
        nonpref_key_fixed = str(pref_nonpref[1]).strip()
        if len(pref_key_fixed) == 0 or len(nonpref_key_fixed) == 0:
            raise ValueError("Preferred/non-preferred keys cannot be empty.")
        if pref_key_fixed == nonpref_key_fixed:
            raise ValueError("Preferred and non-preferred keys must differ.")
    _ = float(timepoint_cm)  # retained for compatibility with older call sites
    min_req = int(min_traversals_per_type)
    if min_req < 0:
        raise ValueError("min_traversals_per_type must be >= 0.")

    distance_bin_cm = float(distance_centered_dataset.get("metadata", {}).get("distance_bin_cm", 1.0))
    smooth_bins = int(_distance_smooth_cm_to_bins(distance_bin_cm, smooth_window_cm))
    if smooth_bins < 0:
        raise ValueError("smooth_window_cm must be >= 0 or None.")

    if auc_window_cm is not None:
        auc_x0, auc_x1 = float(auc_window_cm[0]), float(auc_window_cm[1])
        if not (np.isfinite(auc_x0) and np.isfinite(auc_x1)) or auc_x1 <= auc_x0:
            raise ValueError("auc_window_cm must be a finite (start, end) tuple with end > start.")
    slow_x0, slow_x1 = float(slow_auc_window_cm[0]), float(slow_auc_window_cm[1])
    if not (np.isfinite(slow_x0) and np.isfinite(slow_x1)) or np.isclose(slow_x0, slow_x1):
        raise ValueError("slow_auc_window_cm must be finite with non-zero width.")
    peak_x0, peak_x1 = float(peak_window_cm[0]), float(peak_window_cm[1])
    if not (np.isfinite(peak_x0) and np.isfinite(peak_x1)) or np.isclose(peak_x0, peak_x1):
        raise ValueError("peak_window_cm must be finite with non-zero width.")

    metric_names = ("all_spike", "ss", "cs", "theta", "slow")
    group_specs = [
        ("CSplus", 1, "CSplus_PF1"),
        ("CSplus", 2, "CSplus_PF2"),
        ("CSminus", 1, "CSminus_PF1"),
    ]

    def _smooth_1d(arr: np.ndarray) -> np.ndarray:
        arr = np.asarray(arr, dtype=float).reshape(-1)
        if int(smooth_bins) > 1:
            return _smooth_boxcar(arr, int(smooth_bins))
        return arr

    def _pearson_r_with_reason(a: np.ndarray, b: np.ndarray) -> tuple[float, str | None, int]:
        valid = np.isfinite(a) & np.isfinite(b)
        n_valid = int(np.sum(valid))
        if n_valid < 2:
            return np.nan, "insufficient_overlap_bins", n_valid
        av = np.asarray(a[valid], dtype=float)
        bv = np.asarray(b[valid], dtype=float)
        std_a = float(np.nanstd(av))
        std_b = float(np.nanstd(bv))
        if np.isclose(std_a, 0.0) and np.isclose(std_b, 0.0):
            return np.nan, "flat_trace_both_directions", n_valid
        if np.isclose(std_a, 0.0):
            return np.nan, "flat_trace_preferred", n_valid
        if np.isclose(std_b, 0.0):
            return np.nan, "flat_trace_nonpreferred", n_valid
        return float(np.corrcoef(av, bv)[0, 1]), None, n_valid

    def _peak_x_with_reason(trace: np.ndarray, x: np.ndarray) -> tuple[float, str | None]:
        if trace.ndim != 1 or x.ndim != 1 or trace.size != x.size:
            return np.nan, "shape_mismatch"
        if not np.any(np.isfinite(trace)):
            return np.nan, "all_nan_trace"
        idx = int(np.nanargmax(trace))
        if idx < 0 or idx >= x.size or (not np.isfinite(x[idx])):
            return np.nan, "invalid_peak_index"
        return float(x[idx]), None

    def _auc_ratio_with_reason(metric: str, tr_pref: np.ndarray, tr_nonpref: np.ndarray, x: np.ndarray) -> tuple[float, str | None, int]:
        if tr_pref.ndim != 1 or tr_nonpref.ndim != 1 or x.ndim != 1 or tr_pref.size != x.size or tr_nonpref.size != x.size:
            return np.nan, "shape_mismatch", 0
        if metric == "slow":
            w0, w1 = float(slow_x0), float(slow_x1)
            if w1 < w0:
                w0, w1 = w1, w0
            mask = (x >= w0) & (x <= w1) & np.isfinite(x) & np.isfinite(tr_pref) & np.isfinite(tr_nonpref)
            n_bins = int(np.sum(mask))
            if n_bins < 2:
                return np.nan, "insufficient_auc_bins", n_bins
            y_pref = np.maximum(tr_pref[mask], 0.0)
            y_nonpref = np.maximum(tr_nonpref[mask], 0.0)
        else:
            if auc_window_cm is None:
                mask = np.isfinite(x) & np.isfinite(tr_pref) & np.isfinite(tr_nonpref)
            else:
                w0, w1 = float(auc_x0), float(auc_x1)
                if w1 < w0:
                    w0, w1 = w1, w0
                mask = (x >= w0) & (x <= w1) & np.isfinite(x) & np.isfinite(tr_pref) & np.isfinite(tr_nonpref)
            n_bins = int(np.sum(mask))
            if n_bins < 2:
                return np.nan, "insufficient_auc_bins", n_bins
            y_pref = tr_pref[mask]
            y_nonpref = tr_nonpref[mask]
        xx = x[mask]
        auc_pref = float(np.trapz(y_pref, x=xx))
        auc_nonpref = float(np.trapz(y_nonpref, x=xx))
        if (not np.isfinite(auc_pref)) or np.isclose(auc_pref, 0.0):
            return np.nan, "zero_or_invalid_auc_preferred", int(np.sum(mask))
        return float(auc_nonpref / auc_pref), None, int(np.sum(mask))

    def _peak_ratio_with_reason(tr_pref: np.ndarray, tr_nonpref: np.ndarray, x: np.ndarray) -> tuple[float, float, float, str | None, int]:
        if tr_pref.ndim != 1 or tr_nonpref.ndim != 1 or x.ndim != 1 or tr_pref.size != x.size or tr_nonpref.size != x.size:
            return np.nan, np.nan, np.nan, "shape_mismatch", 0
        w0, w1 = float(peak_x0), float(peak_x1)
        if w1 < w0:
            w0, w1 = w1, w0
        mask_x = (x >= w0) & (x <= w1) & np.isfinite(x)
        if int(np.sum(mask_x)) < 1:
            return np.nan, np.nan, np.nan, "insufficient_peak_window_bins", int(np.sum(mask_x))
        m_pref = mask_x & np.isfinite(tr_pref)
        m_nonpref = mask_x & np.isfinite(tr_nonpref)
        if int(np.sum(m_pref)) < 1:
            return np.nan, np.nan, np.nan, "no_finite_peak_preferred", int(np.sum(mask_x))
        if int(np.sum(m_nonpref)) < 1:
            return np.nan, np.nan, np.nan, "no_finite_peak_nonpreferred", int(np.sum(mask_x))
        peak_pref = float(np.nanmax(tr_pref[m_pref]))
        peak_nonpref = float(np.nanmax(tr_nonpref[m_nonpref]))
        if (not np.isfinite(peak_pref)) or np.isclose(peak_pref, 0.0):
            return peak_pref, peak_nonpref, np.nan, "zero_or_invalid_peak_preferred", int(np.sum(mask_x))
        return peak_pref, peak_nonpref, float(peak_nonpref / peak_pref), None, int(np.sum(mask_x))

    def _peak_abs_sym_diff_with_reason(peak_pref: float, peak_nonpref: float) -> tuple[float, str | None]:
        if (not np.isfinite(peak_pref)) or (not np.isfinite(peak_nonpref)):
            return np.nan, "invalid_peak_values"
        denom = float(peak_nonpref) + float(peak_pref)
        if np.isclose(denom, 0.0):
            return np.nan, "zero_or_invalid_peak_sum"
        return float(abs((float(peak_nonpref) - float(peak_pref)) / denom)), None

    def _apply_r_nan_policy(r_val: float) -> tuple[float, bool]:
        if np.isfinite(r_val):
            return float(r_val), False
        if bool(set_nan_r_to_zero):
            return 0.0, True
        return np.nan, False

    def _safe_float(v: Any, default: float = np.nan) -> float:
        try:
            val = float(v)
        except (TypeError, ValueError):
            return float(default)
        return val if np.isfinite(val) else float(default)

    def _safe_int(v: Any, default: int = 0) -> int:
        vv = _safe_float(v, default=np.nan)
        if not np.isfinite(vv):
            return int(default)
        return int(vv)

    def _trace_1d(npz_obj: Any, key: str, n_time: int) -> np.ndarray:
        if key not in npz_obj:
            return np.full(int(n_time), np.nan, dtype=float)
        arr = np.asarray(npz_obj[key], dtype=float).reshape(-1)
        if arr.size != int(n_time):
            return np.full(int(n_time), np.nan, dtype=float)
        return _smooth_1d(arr)

    def _trace_from_dir(dir_data: dict[str, Any], mean_key: str, stack_key: str, n_time: int) -> np.ndarray:
        arr = np.asarray(dir_data.get(mean_key, []), dtype=float)
        if arr.ndim == 1 and arr.size == int(n_time):
            return _smooth_1d(arr)
        stk = np.asarray(dir_data.get(stack_key, []), dtype=float)
        if stk.ndim == 2 and stk.shape[1] == int(n_time):
            if stk.shape[0] <= 0:
                return np.full(int(n_time), np.nan, dtype=float)
            if int(smooth_bins) > 1:
                sm = np.full_like(stk, np.nan)
                for i in range(stk.shape[0]):
                    sm[i] = _smooth_boxcar(stk[i], int(smooth_bins))
                stk = sm
            return np.asarray(np.nanmean(stk, axis=0), dtype=float)
        return np.full(int(n_time), np.nan, dtype=float)

    def _build_entry_from_export(
        npz_obj: Any,
        *,
        animal_id: str,
        cell_idx: int,
        pf_rank: int,
        stage: str,
        mode: str,
    ) -> dict[str, Any] | None:
        rel_key = f"distance_rel_pf{int(pf_rank)}"
        if rel_key not in npz_obj:
            return None
        rel = np.asarray(npz_obj[rel_key], dtype=float).reshape(-1)
        if rel.ndim != 1 or rel.size == 0:
            return None

        metric_to_mean = {
            "all_spike": "rate_mean",
            "ss": "ss_rate_mean",
            "cs": "cs_rate_mean",
            "theta": "theta_mean",
            "slow": "slow_mean",
        }
        directions = [all_key, cw_key, ccw_key]
        if pref_key_fixed is not None:
            directions.extend([pref_key_fixed, nonpref_key_fixed])
        directions = list(dict.fromkeys(directions))
        data_out: dict[str, Any] = {"time_rel": rel}
        for direction in directions:
            d: dict[str, Any] = {"distance_rel": rel}
            n_key = f"n_trials_{stage}_pf{int(pf_rank)}_{direction}_{mode}_all_spike"
            d["n_trials"] = int(npz_obj[n_key]) if n_key in npz_obj else 0
            for metric, mean_key in metric_to_mean.items():
                k = f"{stage}_pf{int(pf_rank)}_{direction}_{mode}_{metric}"
                if k in npz_obj:
                    tr = np.asarray(npz_obj[k], dtype=float).reshape(-1)
                else:
                    tr = np.full(rel.size, np.nan, dtype=float)
                if tr.size != rel.size:
                    tr = np.full(rel.size, np.nan, dtype=float)
                d[mean_key] = tr
            data_out[direction] = d
        return {
            "session": str(animal_id),
            "cell_idx": int(cell_idx),
            "pf_rank": int(pf_rank),
            "data": data_out,
        }

    rows: list[dict[str, Any]] = []
    nan_rows: list[dict[str, Any]] = []
    skipped_counts: dict[str, int] = {"missing": 0, "low_traversals": 0, "no_preferred": 0}
    used_saved_average_exports = False

    stage = str(average_export_stage).strip().lower()
    if stage not in {"pre", "post"}:
        raise ValueError("average_export_stage must be 'pre' or 'post'.")

    if bool(use_saved_average_exports):
        if average_export_dir is None:
            export_root = Path("figures") / "CKII_pooled" / "pf_distance_centered_2directions_average_exports"
        else:
            export_root = Path(average_export_dir)
        if export_root.exists():
            for cat_name, pf_rank, group_name in group_specs:
                index_csv = export_root / str(cat_name) / "session_averages_pre_post_index.csv"
                if not index_csv.exists():
                    continue
                try:
                    with open(index_csv, newline="") as f:
                        reader = csv.DictReader(f)
                        for row in reader:
                            npz_path = Path(str(row.get("npz_path", "")))
                            if not npz_path.exists():
                                skipped_counts["missing"] += 1
                                continue
                            try:
                                with np.load(npz_path, allow_pickle=True) as npz:
                                    rel_key = f"distance_rel_pf{int(pf_rank)}"
                                    if rel_key not in npz:
                                        skipped_counts["missing"] += 1
                                        continue
                                    x_rel = np.asarray(npz[rel_key], dtype=float).reshape(-1)
                                    if x_rel.ndim != 1 or x_rel.size == 0:
                                        skipped_counts["missing"] += 1
                                        continue
                                    n_time = int(x_rel.size)

                                    if pref_key_fixed is None:
                                        cw_rate = _trace_1d(
                                            npz,
                                            f"{stage}_pf{int(pf_rank)}_{cw_key}_{mode_norm}_all_spike",
                                            n_time,
                                        )
                                        ccw_rate = _trace_1d(
                                            npz,
                                            f"{stage}_pf{int(pf_rank)}_{ccw_key}_{mode_norm}_all_spike",
                                            n_time,
                                        )
                                        pref_side = _infer_preferred_direction_from_rate_traces(cw_rate, ccw_rate)
                                        if pref_side not in {"cw", "ccw"}:
                                            skipped_counts["no_preferred"] += 1
                                            continue
                                        pref_key = str(cw_key) if pref_side == "cw" else str(ccw_key)
                                        nonpref_key = str(ccw_key) if pref_side == "cw" else str(cw_key)
                                    else:
                                        pref_key = str(pref_key_fixed)
                                        nonpref_key = str(nonpref_key_fixed)

                                    n_all = _safe_int(row.get(f"n_trials_pf{int(pf_rank)}_{all_key}_{mode_norm}", np.nan), default=0)
                                    if n_all <= 0:
                                        n_all = _safe_int(npz.get(f"n_trials_pf{int(pf_rank)}_{all_key}_{mode_norm}", np.nan), default=0)
                                    n_pref = _safe_int(row.get(f"n_trials_pf{int(pf_rank)}_{pref_key}_{mode_norm}", np.nan), default=0)
                                    if n_pref <= 0:
                                        n_pref = _safe_int(npz.get(f"n_trials_pf{int(pf_rank)}_{pref_key}_{mode_norm}", np.nan), default=0)
                                    n_nonpref = _safe_int(row.get(f"n_trials_pf{int(pf_rank)}_{nonpref_key}_{mode_norm}", np.nan), default=0)
                                    if n_nonpref <= 0:
                                        n_nonpref = _safe_int(npz.get(f"n_trials_pf{int(pf_rank)}_{nonpref_key}_{mode_norm}", np.nan), default=0)
                                    if min(n_all, n_pref, n_nonpref) < int(min_req):
                                        skipped_counts["low_traversals"] += 1
                                        continue

                                    animal_id = str(row.get("animal_id", ""))
                                    cell_idx = _safe_int(row.get("cell_idx", -1), default=-1)
                                    cell_num = _safe_int(row.get("cell_num", cell_idx + 1), default=(cell_idx + 1))

                                    for metric_name in metric_names:
                                        tr_pref = _trace_1d(
                                            npz,
                                            f"{stage}_pf{int(pf_rank)}_{pref_key}_{mode_norm}_{metric_name}",
                                            n_time,
                                        )
                                        tr_nonpref = _trace_1d(
                                            npz,
                                            f"{stage}_pf{int(pf_rank)}_{nonpref_key}_{mode_norm}_{metric_name}",
                                            n_time,
                                        )
                                        r_raw, r_reason, n_overlap_bins = _pearson_r_with_reason(tr_pref, tr_nonpref)
                                        r_val, r_set_to_zero = _apply_r_nan_policy(r_raw)
                                        p_pref_x, p_pref_reason = _peak_x_with_reason(tr_pref, x_rel)
                                        p_nonpref_x, p_nonpref_reason = _peak_x_with_reason(tr_nonpref, x_rel)
                                        dpeak = float(p_nonpref_x - p_pref_x) if (np.isfinite(p_pref_x) and np.isfinite(p_nonpref_x)) else np.nan
                                        auc_ratio, auc_reason, n_auc_bins = _auc_ratio_with_reason(metric_name, tr_pref, tr_nonpref, x_rel)
                                        peak_pref, peak_nonpref, peak_ratio, peak_reason, n_peak_bins = _peak_ratio_with_reason(tr_pref, tr_nonpref, x_rel)
                                        peak_abs_sym_diff, peak_abs_sym_diff_reason = _peak_abs_sym_diff_with_reason(peak_pref, peak_nonpref)

                                        rows.append(
                                            {
                                                "group": str(group_name),
                                                "category": str(cat_name),
                                                "pf_rank": int(pf_rank),
                                                "animal_id": str(animal_id),
                                                "cell_idx": int(cell_idx),
                                                "cell_num": int(cell_num) if int(cell_idx) >= 0 else np.nan,
                                                "metric": str(metric_name),
                                                "direction_pref": str(pref_key),
                                                "direction_nonpref": str(nonpref_key),
                                                "avg_mode": str(mode_norm),
                                                "n_trials_all": int(n_all),
                                                "n_trials_pref": int(n_pref),
                                                "n_trials_nonpref": int(n_nonpref),
                                                "r": float(r_val) if np.isfinite(r_val) else np.nan,
                                                "delta_peak_x_cm": float(dpeak) if np.isfinite(dpeak) else np.nan,
                                                "auc_ratio": float(auc_ratio) if np.isfinite(auc_ratio) else np.nan,
                                                "peak_pref": float(peak_pref) if np.isfinite(peak_pref) else np.nan,
                                                "peak_nonpref": float(peak_nonpref) if np.isfinite(peak_nonpref) else np.nan,
                                                "peak_ratio_s2_s1": float(peak_ratio) if np.isfinite(peak_ratio) else np.nan,
                                                "peak_ratio_nonpref_pref": float(peak_ratio) if np.isfinite(peak_ratio) else np.nan,
                                                "peak_abs_sym_diff": float(peak_abs_sym_diff) if np.isfinite(peak_abs_sym_diff) else np.nan,
                                            }
                                        )
                                        if bool(r_set_to_zero) or (not np.isfinite(dpeak)) or (not np.isfinite(auc_ratio)) or (not np.isfinite(peak_ratio)) or (not np.isfinite(peak_abs_sym_diff)):
                                            nan_rows.append(
                                                {
                                                    "group": str(group_name),
                                                    "category": str(cat_name),
                                                    "pf_rank": int(pf_rank),
                                                    "animal_id": str(animal_id),
                                                    "cell_idx": int(cell_idx),
                                                    "cell_num": int(cell_num) if int(cell_idx) >= 0 else np.nan,
                                                    "metric": str(metric_name),
                                                    "direction_pref": str(pref_key),
                                                    "direction_nonpref": str(nonpref_key),
                                                    "n_trials_pref": int(n_pref),
                                                    "n_trials_nonpref": int(n_nonpref),
                                                    "n_overlap_bins_for_r": int(n_overlap_bins),
                                                    "n_auc_bins": int(n_auc_bins),
                                                    "n_peak_bins": int(n_peak_bins),
                                                    "r_is_nan": bool(not np.isfinite(r_raw)),
                                                    "r_set_to_zero": bool(r_set_to_zero),
                                                    "r_nan_reason": (str(r_reason) if ((not np.isfinite(r_raw)) and r_reason is not None) else ""),
                                                    "peak_shift_is_nan": bool(not np.isfinite(dpeak)),
                                                    "peak_shift_nan_reason": (
                                                        "pref:" + str(p_pref_reason) if ((not np.isfinite(p_pref_x)) and p_pref_reason is not None) else ""
                                                    )
                                                    + (
                                                        (";nonpref:" + str(p_nonpref_reason))
                                                        if ((not np.isfinite(p_nonpref_x)) and p_nonpref_reason is not None)
                                                        else ""
                                                    ),
                                                    "auc_ratio_is_nan": bool(not np.isfinite(auc_ratio)),
                                                    "auc_ratio_nan_reason": (str(auc_reason) if (not np.isfinite(auc_ratio) and auc_reason is not None) else ""),
                                                    "peak_ratio_is_nan": bool(not np.isfinite(peak_ratio)),
                                                    "peak_ratio_nan_reason": (str(peak_reason) if (not np.isfinite(peak_ratio) and peak_reason is not None) else ""),
                                                    "peak_abs_sym_diff_is_nan": bool(not np.isfinite(peak_abs_sym_diff)),
                                                    "peak_abs_sym_diff_nan_reason": (
                                                        str(peak_abs_sym_diff_reason)
                                                        if ((not np.isfinite(peak_abs_sym_diff)) and peak_abs_sym_diff_reason is not None)
                                                        else ""
                                                    ),
                                                }
                                            )
                                        used_saved_average_exports = True
                            except Exception:
                                skipped_counts["missing"] += 1
                                continue
                except OSError:
                    continue

    if not bool(used_saved_average_exports):
        metric_cfg = {
            "all_spike": ("rate_mean", "rate_stack"),
            "ss": ("ss_rate_mean", "ss_rate_stack"),
            "cs": ("cs_rate_mean", "cs_rate_stack"),
            "theta": ("theta_mean", "theta_stack"),
            "slow": ("slow_mean", "slow_stack"),
        }
        for cat_name, pf_rank, group_name in group_specs:
            entries = list(distance_centered_dataset.get(cat_name, {}).get(int(pf_rank), {}).get("entries", []))
            if mode_norm != "combined":
                entries = [_filter_entry_by_avg_mode_for_directions(e, avg_mode=mode_norm) for e in entries]

            for entry in entries:
                data = entry.get("data", {})
                x_rel = np.asarray(
                    data.get("time_rel", data.get("distance_rel", data.get(all_key, {}).get("distance_rel", []))),
                    dtype=float,
                )
                if x_rel.ndim != 1 or x_rel.size == 0:
                    skipped_counts["missing"] += 1
                    continue
                n_time = int(x_rel.size)
                all_dir = data.get(all_key, {})
                cw_dir = data.get(cw_key, {})
                ccw_dir = data.get(ccw_key, {})

                if pref_key_fixed is None:
                    cw_rate = _trace_from_dir(cw_dir, "rate_mean", "rate_stack", n_time)
                    ccw_rate = _trace_from_dir(ccw_dir, "rate_mean", "rate_stack", n_time)
                    pref_side = _infer_preferred_direction_from_rate_traces(cw_rate, ccw_rate)
                    if pref_side not in {"cw", "ccw"}:
                        skipped_counts["no_preferred"] += 1
                        continue
                    pref_key = str(cw_key) if pref_side == "cw" else str(ccw_key)
                    nonpref_key = str(ccw_key) if pref_side == "cw" else str(cw_key)
                else:
                    pref_key = str(pref_key_fixed)
                    nonpref_key = str(nonpref_key_fixed)
                pref_dir = data.get(pref_key, {})
                nonpref_dir = data.get(nonpref_key, {})

                n_all = int(all_dir.get("n_trials", 0))
                n_pref = int(pref_dir.get("n_trials", 0))
                n_nonpref = int(nonpref_dir.get("n_trials", 0))
                if min(n_all, n_pref, n_nonpref) < int(min_req):
                    skipped_counts["low_traversals"] += 1
                    continue

                animal_id = str(entry.get("session", ""))
                cell_idx = int(entry.get("cell_idx", -1))
                cell_num = int(cell_idx + 1) if cell_idx >= 0 else np.nan

                for metric_name, (mean_key, stack_key) in metric_cfg.items():
                    tr_pref = _trace_from_dir(pref_dir, mean_key, stack_key, n_time)
                    tr_nonpref = _trace_from_dir(nonpref_dir, mean_key, stack_key, n_time)
                    r_raw, r_reason, n_overlap_bins = _pearson_r_with_reason(tr_pref, tr_nonpref)
                    r_val, r_set_to_zero = _apply_r_nan_policy(r_raw)
                    p_pref_x, p_pref_reason = _peak_x_with_reason(tr_pref, x_rel)
                    p_nonpref_x, p_nonpref_reason = _peak_x_with_reason(tr_nonpref, x_rel)
                    dpeak = float(p_nonpref_x - p_pref_x) if (np.isfinite(p_pref_x) and np.isfinite(p_nonpref_x)) else np.nan
                    auc_ratio, auc_reason, n_auc_bins = _auc_ratio_with_reason(metric_name, tr_pref, tr_nonpref, x_rel)
                    peak_pref, peak_nonpref, peak_ratio, peak_reason, n_peak_bins = _peak_ratio_with_reason(tr_pref, tr_nonpref, x_rel)
                    peak_abs_sym_diff, peak_abs_sym_diff_reason = _peak_abs_sym_diff_with_reason(peak_pref, peak_nonpref)

                    rows.append(
                        {
                            "group": str(group_name),
                            "category": str(cat_name),
                            "pf_rank": int(pf_rank),
                            "animal_id": str(animal_id),
                            "cell_idx": int(cell_idx),
                            "cell_num": int(cell_num) if np.isfinite(cell_num) else np.nan,
                            "metric": str(metric_name),
                            "direction_pref": str(pref_key),
                            "direction_nonpref": str(nonpref_key),
                            "avg_mode": str(mode_norm),
                            "n_trials_all": int(n_all),
                            "n_trials_pref": int(n_pref),
                            "n_trials_nonpref": int(n_nonpref),
                            "r": float(r_val) if np.isfinite(r_val) else np.nan,
                            "delta_peak_x_cm": float(dpeak) if np.isfinite(dpeak) else np.nan,
                            "auc_ratio": float(auc_ratio) if np.isfinite(auc_ratio) else np.nan,
                            "peak_pref": float(peak_pref) if np.isfinite(peak_pref) else np.nan,
                            "peak_nonpref": float(peak_nonpref) if np.isfinite(peak_nonpref) else np.nan,
                            "peak_ratio_s2_s1": float(peak_ratio) if np.isfinite(peak_ratio) else np.nan,
                            "peak_ratio_nonpref_pref": float(peak_ratio) if np.isfinite(peak_ratio) else np.nan,
                            "peak_abs_sym_diff": float(peak_abs_sym_diff) if np.isfinite(peak_abs_sym_diff) else np.nan,
                        }
                    )
                    if bool(r_set_to_zero) or (not np.isfinite(dpeak)) or (not np.isfinite(auc_ratio)) or (not np.isfinite(peak_ratio)) or (not np.isfinite(peak_abs_sym_diff)):
                        nan_rows.append(
                            {
                                "group": str(group_name),
                                "category": str(cat_name),
                                "pf_rank": int(pf_rank),
                                "animal_id": str(animal_id),
                                "cell_idx": int(cell_idx),
                                "cell_num": int(cell_num) if np.isfinite(cell_num) else np.nan,
                                "metric": str(metric_name),
                                "direction_pref": str(pref_key),
                                "direction_nonpref": str(nonpref_key),
                                "n_trials_pref": int(n_pref),
                                "n_trials_nonpref": int(n_nonpref),
                                "n_overlap_bins_for_r": int(n_overlap_bins),
                                "n_auc_bins": int(n_auc_bins),
                                "n_peak_bins": int(n_peak_bins),
                                "r_is_nan": bool(not np.isfinite(r_raw)),
                                "r_set_to_zero": bool(r_set_to_zero),
                                "r_nan_reason": (str(r_reason) if ((not np.isfinite(r_raw)) and r_reason is not None) else ""),
                                "peak_shift_is_nan": bool(not np.isfinite(dpeak)),
                                "peak_shift_nan_reason": (
                                    "pref:" + str(p_pref_reason) if ((not np.isfinite(p_pref_x)) and p_pref_reason is not None) else ""
                                )
                                + (
                                    (";nonpref:" + str(p_nonpref_reason))
                                    if ((not np.isfinite(p_nonpref_x)) and p_nonpref_reason is not None)
                                    else ""
                                ),
                                "auc_ratio_is_nan": bool(not np.isfinite(auc_ratio)),
                                "auc_ratio_nan_reason": (str(auc_reason) if (not np.isfinite(auc_ratio) and auc_reason is not None) else ""),
                                "peak_ratio_is_nan": bool(not np.isfinite(peak_ratio)),
                                "peak_ratio_nan_reason": (str(peak_reason) if (not np.isfinite(peak_ratio) and peak_reason is not None) else ""),
                                "peak_abs_sym_diff_is_nan": bool(not np.isfinite(peak_abs_sym_diff)),
                                "peak_abs_sym_diff_nan_reason": (
                                    str(peak_abs_sym_diff_reason)
                                    if ((not np.isfinite(peak_abs_sym_diff)) and peak_abs_sym_diff_reason is not None)
                                    else ""
                                ),
                            }
                        )

    per_cell = pd.DataFrame(rows)
    nan_diag_df = pd.DataFrame(nan_rows)
    if bool(print_nan_diagnostics):
        if nan_diag_df is None or len(nan_diag_df) == 0:
            print("[pref_nonpref_stability] No NaN metrics from flat/invalid traces after inclusion gating.")
        else:
            print("[pref_nonpref_stability] Cells/metrics with NaN values (flat/invalid traces):")
            for _, rr in nan_diag_df.iterrows():
                parts: list[str] = []
                if bool(rr.get("r_is_nan", False)):
                    parts.append(f"r:{str(rr.get('r_nan_reason', ''))}")
                if bool(rr.get("r_set_to_zero", False)):
                    parts.append("r_set_to_zero")
                if bool(rr.get("peak_shift_is_nan", False)):
                    parts.append(f"peak_shift:{str(rr.get('peak_shift_nan_reason', ''))}")
                if bool(rr.get("auc_ratio_is_nan", False)):
                    parts.append(f"auc_ratio:{str(rr.get('auc_ratio_nan_reason', ''))}")
                if bool(rr.get("peak_ratio_is_nan", False)):
                    parts.append(f"peak_ratio:{str(rr.get('peak_ratio_nan_reason', ''))}")
                if bool(rr.get("peak_abs_sym_diff_is_nan", False)):
                    parts.append(f"peak_abs_sym_diff:{str(rr.get('peak_abs_sym_diff_nan_reason', ''))}")
                cell_num_val = rr.get("cell_num", np.nan)
                if np.isfinite(cell_num_val):
                    cell_lbl = f"{rr.get('animal_id', '')}_Cell{int(cell_num_val)}"
                else:
                    cell_lbl = f"{rr.get('animal_id', '')}_CellIdx{rr.get('cell_idx', '')}"
                print(
                    f"  group={rr.get('group', '')}, metric={rr.get('metric', '')}, "
                    f"cell={cell_lbl}, n_pref={int(rr.get('n_trials_pref', 0))}, n_nonpref={int(rr.get('n_trials_nonpref', 0))}, "
                    f"overlap_bins={int(rr.get('n_overlap_bins_for_r', 0))}, auc_bins={int(rr.get('n_auc_bins', 0))}, peak_bins={int(rr.get('n_peak_bins', 0))}, "
                    f"reasons={'; '.join(parts)}"
                )

    group_metric_counts: dict[str, int] = {}
    if len(per_cell) > 0:
        counts_df = (
            per_cell.dropna(subset=["r"])
            .groupby(["group", "metric"])["cell_idx"]
            .nunique()
            .reset_index(name="n_cells")
        )
        for _, r in counts_df.iterrows():
            group_metric_counts[f"{r['group']}::{r['metric']}"] = int(r["n_cells"])

    return {
        "per_cell_stability": per_cell,
        # Keep legacy key for backward compatibility with old notebook cells.
        "per_cell_selectivity": per_cell,
        "nan_diagnostics": nan_diag_df,
        "group_metric_counts": group_metric_counts,
        "skipped_counts": skipped_counts,
        "avg_mode": str(mode_norm),
        "data_source": "saved_average_exports" if bool(used_saved_average_exports) else "distance_centered_dataset",
        "average_export_dir": str(export_root) if bool(used_saved_average_exports) else None,
        "average_export_stage": str(stage) if bool(used_saved_average_exports) else None,
        "min_traversals_per_type": int(min_req),
        "smooth_window_cm": None if smooth_window_cm is None else float(smooth_window_cm),
        "auc_window_cm": None if auc_window_cm is None else (float(auc_x0), float(auc_x1)),
        "slow_auc_window_cm": (float(slow_x0), float(slow_x1)),
        "peak_window_cm": (float(peak_x0), float(peak_x1)),
        "set_nan_r_to_zero": bool(set_nan_r_to_zero),
        "all_direction_key": str(all_key),
        "cw_direction_key": str(cw_key),
        "ccw_direction_key": str(ccw_key),
        "explicit_preferred_nonpreferred_keys": (
            None
            if pref_key_fixed is None
            else (str(pref_key_fixed), str(nonpref_key_fixed))
        ),
    }


def plot_pf_distance_centered_pref_nonpref_stats(
    stats_results: dict[str, Any],
    *,
    figure_save_folder: str | Path | None = None,
    five_panel_figsize: tuple[float, float] | None = None,
    two_subplot_figsize: tuple[float, float] | None = None,
    stat_label_overrides: dict[str, str] | None = None,
    output_prefix: str = "pf_distance_centered_pref_nonpref",
    show_plot: bool = True,
    save_csv: bool = True,
) -> dict[str, str]:
    """Plot Pref-vs-Non-pref stability with the same outputs as compare-sessions."""
    import pandas as pd

    figure_root = Path(figure_save_folder) if figure_save_folder is not None else Path("figures") / "CKII_pooled"
    figure_root.mkdir(parents=True, exist_ok=True)

    per_cell = stats_results.get("per_cell_stability", None)
    if per_cell is None:
        per_cell = stats_results.get("per_cell_selectivity", None)
    if per_cell is None or len(per_cell) == 0:
        return {}
    per_cell_df = pd.DataFrame(per_cell).copy()

    payload = dict(stats_results)
    payload["per_cell_stability"] = per_cell_df
    label_overrides = {
        "peak_ratio_s2_s1": "Peak ratio (Non-pref/Pref)",
        "peak_abs_sym_diff": "|(Non-pref-Pref)/(Non-pref+Pref)|",
    }
    if isinstance(stat_label_overrides, dict):
        label_overrides.update({str(k): str(v) for k, v in stat_label_overrides.items()})
    prefix = str(output_prefix)

    base = plot_pf_distance_centered_session_stability(
        payload,
        figure_save_folder=figure_root,
        figsize=(None if five_panel_figsize is None else tuple(five_panel_figsize)),
        stat_label_overrides=label_overrides,
        show_plot=False,
        save_csv=save_csv,
    )
    if not base:
        return {}

    out: dict[str, str] = {}
    dst_map = {
        "figure": figure_root / f"{prefix}_summary_5panels.svg",
        "per_cell_csv": figure_root / f"{prefix}_per_cell.csv",
        "stats_csv": figure_root / f"{prefix}_stats.csv",
    }
    src_fig = base.get("figure_paths", {}).get("combined")
    src_per_cell = base.get("per_cell_csv")
    src_stats = base.get("stats_csv")
    src_map = {
        "figure": src_fig,
        "per_cell_csv": src_per_cell,
        "stats_csv": src_stats,
    }
    for key, dst in dst_map.items():
        src = src_map.get(key)
        if src is None:
            continue
        src_p = Path(str(src))
        if src_p.exists():
            shutil.copy2(src_p, dst)
            out[key] = str(dst)

    # Secondary 2-subplot figure based on columns 5 and 4.
    panel_out_name = f"{prefix}_summary_ss_cs_2subplots.svg"
    panel_summary = plot_pf_distance_centered_abs_norm_fr_change_ss_cs(
        payload,
        figure_save_folder=figure_root,
        out_name=panel_out_name,
        figsize=(3.0, 4.0) if two_subplot_figsize is None else tuple(two_subplot_figsize),
        abs_delta_ylabel="|(Non-pref-Pref)/(Non-pref+Pref)|",
        ratio_ylabel="Non-pref/Pref",
        show_plot=False,
        save_csv=save_csv,
    )
    if panel_summary:
        out["figure_2subplots"] = str(panel_summary.get("figure", ""))
        out["stats_csv_2subplots"] = str(panel_summary.get("stats_csv", ""))

    if show_plot:
        _ = plot_pf_distance_centered_session_stability(
            payload,
            figure_save_folder=figure_root,
            figsize=(None if five_panel_figsize is None else tuple(five_panel_figsize)),
            stat_label_overrides=label_overrides,
            show_plot=True,
            save_csv=False,
        )
        _ = plot_pf_distance_centered_abs_norm_fr_change_ss_cs(
            payload,
            figure_save_folder=figure_root,
            out_name=panel_out_name,
            figsize=(3.0, 4.0) if two_subplot_figsize is None else tuple(two_subplot_figsize),
            abs_delta_ylabel="|(Non-pref-Pref)/(Non-pref+Pref)|",
            ratio_ylabel="Non-pref/Pref",
            show_plot=True,
            save_csv=False,
        )
    return out


def compute_pf_centered_selectivity_summary(
    pf_centered_dataset: dict[str, Any],
    *,
    timepoint_sec: float = 0.0,
    min_traversals_per_type: int = 5,
    smooth_window: int | None = 400,
    auc_window_sec: tuple[float, float] = (-2.0, 2.0),
) -> dict[str, Any]:
    """
    Compute per-cell PF-centered selectivity summary at a single timepoint.

    Signed selectivity per measurement:
        (Pref - Non-pref) / (Pref + Non-pref)

    Directionality is defined as abs(selectivity).

    Notes
    -----
    - all_spike / ss / cs use value at `timepoint_sec`.
    - theta_amp / slow_vm use positive-only AUC within `auc_window_sec`.
    """
    import pandas as pd

    min_trav = int(min_traversals_per_type)
    if min_trav < 0:
        raise ValueError("min_traversals_per_type must be >= 0.")
    t0 = float(timepoint_sec)
    auc_t0, auc_t1 = float(auc_window_sec[0]), float(auc_window_sec[1])
    if not (np.isfinite(auc_t0) and np.isfinite(auc_t1)) or auc_t1 <= auc_t0:
        raise ValueError("auc_window_sec must be a finite (start, end) tuple with end > start.")

    metric_map = {
        "all_spike": "rate_mean",
        "ss": "ss_rate_mean",
        "cs": "cs_rate_mean",
        "theta_amp": "theta_mean",
        "slow_vm": "slow_mean",
    }
    auc_metrics = {"theta_mean", "slow_mean"}
    group_specs = [
        ("CSplus", 1, "CSplus_PF1"),
        ("CSplus", 2, "CSplus_PF2"),
        ("CSminus", 1, "CSminus_PF1"),
    ]

    smooth_win = None if smooth_window is None else int(smooth_window)
    if smooth_win is not None and smooth_win < 0:
        raise ValueError("smooth_window must be >= 0 or None.")

    def _center_value(dir_data: dict[str, Any], key: str, idx0: int, time_rel: np.ndarray) -> float:
        arr = np.asarray(dir_data.get(key, []), dtype=float)
        if arr.ndim != 1 or idx0 < 0 or idx0 >= arr.size:
            return np.nan
        # Match plotted PF-centered averages by applying the same smoothing pass.
        if smooth_win is not None and smooth_win > 1:
            arr = _smooth_boxcar(arr, smooth_win)
        if key in auc_metrics:
            t = np.asarray(time_rel, dtype=float)
            if t.ndim != 1 or t.size != arr.size:
                return np.nan
            mask = (t >= auc_t0) & (t <= auc_t1) & np.isfinite(arr) & np.isfinite(t)
            if int(np.sum(mask)) < 2:
                return np.nan
            y = np.maximum(arr[mask], 0.0)
            return float(np.trapz(y, x=t[mask]))
        v = float(arr[idx0])
        return v if np.isfinite(v) else np.nan

    rows: list[dict[str, Any]] = []
    skipped_counts: dict[str, int] = {"missing": 0, "low_traversals": 0, "no_preferred": 0}

    for cat_name, pf_rank, group_name in group_specs:
        entries = list(pf_centered_dataset.get(cat_name, {}).get(int(pf_rank), {}).get("entries", []))
        for entry in entries:
            data = entry.get("data", {})
            time_rel = np.asarray(data.get("time_rel", []), dtype=float)
            if time_rel.ndim != 1 or time_rel.size == 0:
                skipped_counts["missing"] += 1
                continue
            idx0 = int(np.nanargmin(np.abs(time_rel - t0)))

            all_dir = data.get("all", {})
            cw_dir = data.get("cw", {})
            ccw_dir = data.get("ccw", {})

            cw0 = _center_value(cw_dir, "rate_mean", idx0, time_rel)
            ccw0 = _center_value(ccw_dir, "rate_mean", idx0, time_rel)
            preferred_dir: dict[str, Any] | None = None
            nonpreferred_dir: dict[str, Any] | None = None
            if np.isfinite(cw0) and np.isfinite(ccw0):
                if cw0 > ccw0:
                    preferred_dir = cw_dir
                    nonpreferred_dir = ccw_dir
                elif ccw0 > cw0:
                    preferred_dir = ccw_dir
                    nonpreferred_dir = cw_dir
            if preferred_dir is None or nonpreferred_dir is None:
                skipped_counts["no_preferred"] += 1
                continue

            n_all = int(all_dir.get("n_trials", 0))
            n_pref = int(preferred_dir.get("n_trials", 0))
            n_nonpref = int(nonpreferred_dir.get("n_trials", 0))
            if min(n_all, n_pref, n_nonpref) < min_trav:
                skipped_counts["low_traversals"] += 1
                continue

            animal_id = str(entry.get("session", ""))
            cell_idx = int(entry.get("cell_idx", -1))
            for metric_name, key in metric_map.items():
                pref_val = _center_value(preferred_dir, key, idx0, time_rel)
                nonpref_val = _center_value(nonpreferred_dir, key, idx0, time_rel)
                denom = pref_val + nonpref_val
                if key in auc_metrics:
                    # For theta/slow, report non-normalized absolute difference as directionality.
                    if np.isfinite(pref_val) and np.isfinite(nonpref_val):
                        sel = pref_val - nonpref_val
                        directionality = abs(sel)
                    else:
                        sel = np.nan
                        directionality = np.nan
                else:
                    if np.isfinite(pref_val) and np.isfinite(nonpref_val) and np.isfinite(denom) and (not np.isclose(denom, 0.0)):
                        sel = (pref_val - nonpref_val) / denom
                        directionality = abs(float(sel))
                    else:
                        sel = np.nan
                        directionality = np.nan
                rows.append(
                    {
                        "group": str(group_name),
                        "category": str(cat_name),
                        "pf_rank": int(pf_rank),
                        "animal_id": animal_id,
                        "cell_idx": int(cell_idx),
                        "cell_num": int(cell_idx) + 1 if cell_idx >= 0 else np.nan,
                        "metric": str(metric_name),
                        "selectivity": float(sel) if np.isfinite(sel) else np.nan,
                        "directionality": float(directionality) if np.isfinite(directionality) else np.nan,
                        "pref_value": float(pref_val) if np.isfinite(pref_val) else np.nan,
                        "nonpref_value": float(nonpref_val) if np.isfinite(nonpref_val) else np.nan,
                        "n_trials_all": int(n_all),
                        "n_trials_pref": int(n_pref),
                        "n_trials_nonpref": int(n_nonpref),
                        "timepoint_sec": float(t0),
                    }
                )

    per_cell_selectivity = pd.DataFrame(rows)
    group_metric_counts: dict[str, int] = {}
    if len(per_cell_selectivity) > 0:
        counts_df = (
            per_cell_selectivity.dropna(subset=["directionality"])
            .groupby(["group", "metric"])["cell_idx"]
            .nunique()
            .reset_index(name="n_cells")
        )
        for _, r in counts_df.iterrows():
            group_metric_counts[f"{r['group']}::{r['metric']}"] = int(r["n_cells"])

    return {
        "per_cell_selectivity": per_cell_selectivity,
        "group_metric_counts": group_metric_counts,
        "skipped_counts": skipped_counts,
        "timepoint_sec": float(t0),
        "min_traversals_per_type": int(min_trav),
        "smooth_window": smooth_win,
        "auc_window_sec": (float(auc_t0), float(auc_t1)),
    }


def plot_pf_centered_selectivity_summary(
    selectivity_results: dict[str, Any],
    *,
    figure_save_folder: str | Path | None = None,
    show_plot: bool = True,
    save_csv: bool = True,
) -> dict[str, str]:
    """
    Plot 5-panel directionality summary:
      metrics = [All spike, SS, CS, Theta amp, Slow Vm]
      groups  = [CS+ PF1, CS+ PF2, CS- PF1]
    """
    import pandas as pd

    df = selectivity_results.get("per_cell_selectivity")
    if df is None or len(df) == 0:
        return {}

    if figure_save_folder is None:
        figure_root = Path("figures") / "CKII_pooled"
    else:
        figure_root = Path(figure_save_folder)
    figure_root.mkdir(parents=True, exist_ok=True)

    fig_path = figure_root / "pf_centered_selectivity_summary_5panels.svg"
    per_cell_csv = figure_root / "pf_centered_selectivity_per_cell.csv"
    stats_csv = figure_root / "pf_centered_selectivity_stats.csv"

    metric_order = ["all_spike", "ss", "cs", "theta_amp", "slow_vm"]
    metric_labels = {
        "all_spike": "All spike",
        "ss": "SS",
        "cs": "CS",
        "theta_amp": "Theta amp",
        "slow_vm": "Slow Vm",
    }
    group_order = ["CSplus_PF1", "CSplus_PF2", "CSminus_PF1"]
    group_labels = ["CS+ PF1", "CS+ PF2", "CS- PF1"]
    group_colors = ["#D81B60", "#00ACC1", "#1F77B4"]

    def _paired_test_auto_small_n(vals_a: np.ndarray, vals_b: np.ndarray) -> tuple[float, float, str, int, float]:
        vals_a = np.asarray(vals_a, dtype=float)
        vals_b = np.asarray(vals_b, dtype=float)
        n_pairs = min(len(vals_a), len(vals_b))
        if n_pairs == 0:
            return np.nan, np.nan, "n/a", 0, np.nan
        a = vals_a[:n_pairs]
        b = vals_b[:n_pairs]
        valid = np.isfinite(a) & np.isfinite(b)
        n_valid = int(np.sum(valid))
        if n_valid < 3:
            return np.nan, np.nan, "n/a", n_valid, np.nan
        if n_valid <= 6:
            try:
                res = scipy_stats.wilcoxon(a[valid], b[valid])
                return float(res.pvalue), float(res.statistic), "wilcoxon (n<=6)", n_valid, np.nan
            except ValueError:
                return np.nan, np.nan, "wilcoxon (n<=6)", n_valid, np.nan
        return paired_test_auto(a[valid], b[valid])

    def _unpaired_test_auto_small_n(vals_a: np.ndarray, vals_b: np.ndarray) -> tuple[float, float, str, int, int]:
        a = np.asarray(vals_a, dtype=float)
        b = np.asarray(vals_b, dtype=float)
        a = a[np.isfinite(a)]
        b = b[np.isfinite(b)]
        na, nb = len(a), len(b)
        if min(na, nb) < 3:
            return np.nan, np.nan, "n/a", na, nb
        if min(na, nb) <= 6:
            try:
                res = scipy_stats.mannwhitneyu(a, b, alternative="two-sided")
                return float(res.pvalue), float(res.statistic), "mann-whitney (n<=6)", na, nb
            except ValueError:
                return np.nan, np.nan, "mann-whitney (n<=6)", na, nb
        return unpaired_test_auto(a, b)

    def _swarm_x(y_vals: np.ndarray, center: float, width: float = 0.08) -> np.ndarray:
        y_vals = np.asarray(y_vals, dtype=float)
        n = y_vals.size
        if n == 0:
            return np.array([], dtype=float)
        if n == 1:
            return np.array([center], dtype=float)
        order = np.argsort(y_vals)
        x = np.full(n, center, dtype=float)
        y_span = float(np.nanmax(y_vals) - np.nanmin(y_vals)) if np.any(np.isfinite(y_vals)) else 1.0
        if (not np.isfinite(y_span)) or y_span <= 0:
            y_span = 1.0
        min_dy = 0.03 * y_span
        step = width / 5.0
        offsets = [0.0]
        for k in range(1, 6):
            offsets.extend([k * step, -k * step])
        placed: list[tuple[float, float]] = []
        for idx in order:
            yi = float(y_vals[idx])
            chosen = 0.0
            for off in offsets:
                xi = center + off
                clash = False
                for xj, yj in placed:
                    if abs(yj - yi) <= min_dy and abs(xj - xi) < (0.95 * step):
                        clash = True
                        break
                if not clash:
                    chosen = off
                    break
            x[idx] = center + chosen
            placed.append((x[idx], yi))
        return x

    def _add_sig_bracket(ax: Any, x1: float, x2: float, y: float, h: float, txt: str) -> None:
        ax.plot([x1, x1, x2, x2], [y, y + h, y + h, y], color="black", linewidth=0.6, clip_on=False)
        ax.text((x1 + x2) / 2, y + h, txt, ha="center", va="bottom", fontsize=5)

    fig, axes = plt.subplots(1, len(metric_order), figsize=(1.25 * len(metric_order), 1.4), sharey=False)
    axes = np.atleast_1d(axes)
    stats_rows: list[dict[str, Any]] = []

    for ax, metric in zip(axes, metric_order):
        sub = df[df["metric"] == metric].copy()
        show_csminus_group = metric != "cs"
        group_order_use = ["CSplus_PF1", "CSplus_PF2", "CSminus_PF1"] if show_csminus_group else ["CSplus_PF1", "CSplus_PF2"]
        group_labels_use = ["PF1", "PF2", "PF1"] if show_csminus_group else ["PF1", "PF2"]
        group_colors_use = ["#D81B60", "#00ACC1", "#1F77B4"] if show_csminus_group else ["#D81B60", "#00ACC1"]

        groups = []
        for g in group_order_use:
            vals = np.asarray(sub.loc[sub["group"] == g, "directionality"], dtype=float)
            vals = vals[np.isfinite(vals)]
            groups.append(vals)

        positions = np.arange(len(group_order_use), dtype=float)
        # Group background: CS+ (first two), CS- (third when present).
        ax.axvspan(-0.5, 1.5, color="#FFF3E0", alpha=0.3, zorder=0)
        if show_csminus_group:
            ax.axvspan(1.5, 2.5, color="#E3F2FD", alpha=0.3, zorder=0)
        bp = ax.boxplot(
            groups,
            positions=positions,
            widths=0.5,
            patch_artist=True,
            showfliers=False,
            medianprops={"color": "black", "linewidth": 0.7},
            boxprops={"linewidth": 0.5},
            whiskerprops={"linewidth": 0.5},
            capprops={"linewidth": 0.5},
        )
        for box, c in zip(bp["boxes"], group_colors_use):
            box.set_facecolor(c)
            box.set_alpha(0.25)

        for i, vals in enumerate(groups):
            if len(vals) == 0:
                continue
            xs = _swarm_x(vals, positions[i], width=0.10)
            ax.scatter(xs, vals, s=8, color=group_colors_use[i], alpha=0.9, linewidths=0, zorder=2)

        # Connect paired CS+ PF1 <-> PF2 values (same animal/cell).
        cs_pair = sub[sub["group"].isin(["CSplus_PF1", "CSplus_PF2"])][["animal_id", "cell_idx", "group", "directionality"]].copy()
        if len(cs_pair) > 0:
            piv = cs_pair.pivot_table(index=["animal_id", "cell_idx"], columns="group", values="directionality", aggfunc="first")
            if {"CSplus_PF1", "CSplus_PF2"}.issubset(set(piv.columns)):
                for _, row in piv.iterrows():
                    v1 = row["CSplus_PF1"]
                    v2 = row["CSplus_PF2"]
                    if np.isfinite(v1) and np.isfinite(v2):
                        ax.plot([0, 1], [v1, v2], color="#C8C8C8", linewidth=0.45, alpha=0.7, zorder=1)

        # Stats: 1) CS+ PF1 vs PF2 (paired)  2) CS+ PF1 vs CS- PF1 (unpaired)
        if len(cs_pair) > 0:
            piv = cs_pair.pivot_table(index=["animal_id", "cell_idx"], columns="group", values="directionality", aggfunc="first")
            if {"CSplus_PF1", "CSplus_PF2"}.issubset(set(piv.columns)):
                p1 = np.asarray(piv["CSplus_PF1"], dtype=float)
                p2 = np.asarray(piv["CSplus_PF2"], dtype=float)
                p, stat, test_name, n_valid, shapiro_p = _paired_test_auto_small_n(p1, p2)
            else:
                p, stat, test_name, n_valid, shapiro_p = np.nan, np.nan, "n/a", 0, np.nan
        else:
            p, stat, test_name, n_valid, shapiro_p = np.nan, np.nan, "n/a", 0, np.nan
        stats_rows.append(
            {
                "metric": metric,
                "comparison": "CSplus_PF1_vs_CSplus_PF2",
                "n": int(n_valid),
                "p_value": float(p) if np.isfinite(p) else np.nan,
                "statistic": float(stat) if np.isfinite(stat) else np.nan,
                "test": str(test_name),
                "shapiro_p": float(shapiro_p) if np.isfinite(shapiro_p) else np.nan,
            }
        )

        p_u, stat_u, test_u, na, nb = np.nan, np.nan, "n/a", 0, 0
        if show_csminus_group:
            g_csplus_pf1 = np.asarray(sub.loc[sub["group"] == "CSplus_PF1", "directionality"], dtype=float)
            g_csminus_pf1 = np.asarray(sub.loc[sub["group"] == "CSminus_PF1", "directionality"], dtype=float)
            p_u, stat_u, test_u, na, nb = _unpaired_test_auto_small_n(g_csplus_pf1, g_csminus_pf1)
            stats_rows.append(
                {
                    "metric": metric,
                    "comparison": "CSplus_PF1_vs_CSminus_PF1",
                    "n_a": int(na),
                    "n_b": int(nb),
                    "p_value": float(p_u) if np.isfinite(p_u) else np.nan,
                    "statistic": float(stat_u) if np.isfinite(stat_u) else np.nan,
                    "test": str(test_u),
                    "shapiro_p": np.nan,
                }
            )

        print(f"\n{metric_labels.get(metric, metric)}:")
        print(
            f"  CS+ PF1 vs PF2: n={n_valid}, test={test_name}, "
            f"shapiro_p={shapiro_p:.3g}, stat={stat:.3g}, p={p:.3g}, sig={_sig_label(p)}"
        )
        if show_csminus_group:
            print(
                f"  CS+ PF1 vs CS- PF1: n=({na},{nb}), test={test_u}, "
                f"stat={stat_u:.3g}, p={p_u:.3g}, sig={_sig_label(p_u)}"
            )

        all_vals = np.concatenate([v for v in groups if len(v) > 0]) if any(len(v) > 0 for v in groups) else np.array([0.0])
        y_min = float(np.nanmin(all_vals)) if np.any(np.isfinite(all_vals)) else -1.0
        y_max = float(np.nanmax(all_vals)) if np.any(np.isfinite(all_vals)) else 1.0
        span = y_max - y_min
        if not np.isfinite(span) or span <= 0:
            span = max(abs(y_max), 1.0) * 0.3
        base = y_max + 0.08 * span
        step = 0.20 * span
        h = 0.03 * span
        _add_sig_bracket(ax, 0.0, 1.0, base, h, _sig_label(p))
        if show_csminus_group:
            _add_sig_bracket(ax, 0.0, 2.0, base + step, h, _sig_label(p_u))
            y_top = base + step + 2 * h + 0.10 * span
        else:
            y_top = base + h + 0.10 * span
        ax.set_ylim(y_min - 0.08 * span, y_top)

        ax.axhline(0, color="black", linestyle="--", linewidth=0.5, alpha=0.6)
        ax.set_title(metric_labels.get(metric, metric), fontsize=6)
        ax.set_xticks(positions)
        ax.set_xticklabels(group_labels_use, rotation=0, ha="center")
        ax.set_xlim(-0.5, float(len(group_order_use)) - 0.5)
        if metric == metric_order[0]:
            ax.set_ylabel("Directionality", fontsize=6)
        ax.tick_params(labelsize=5)
        ax.spines["top"].set_visible(False)
        ax.spines["right"].set_visible(False)

    fig.tight_layout()
    fig.savefig(fig_path, dpi=300)
    if show_plot:
        plt.show()
    else:
        plt.close(fig)

    stats_df = pd.DataFrame(stats_rows)
    if bool(save_csv):
        df.to_csv(per_cell_csv, index=False)
        stats_df.to_csv(stats_csv, index=False)

    return {
        "figure": str(fig_path),
        "per_cell_csv": str(per_cell_csv),
        "stats_csv": str(stats_csv),
    }


def compute_pf_distance_centered_session_stability(
    distance_centered_dataset: dict[str, Any],
    *,
    min_traversals_per_session: int = 5,
    min_trials_per_column_2sessions: int | None = None,
    strict_follow_plot_inclusion: bool = True,
    smooth_window_cm: float | None = None,
    auc_window_cm: tuple[float, float] | None = None,
    slow_auc_window_cm: tuple[float, float] = (-10.0, 10.0),
    peak_window_cm: tuple[float, float] = (-10.0, 10.0),
    use_saved_average_exports: bool = True,
    average_export_dir: str | Path | None = None,
    average_export_stage: str = "post",
    split_mode: str = "recorded_sessions",
    split_window_minutes: float | None = None,
    print_nan_diagnostics: bool = True,
    set_nan_r_to_zero: bool = True,
) -> dict[str, Any]:
    """
    Compute session1-vs-session2 stability metrics on all-direction traversals only.

    Groups:
      - CSplus PF1
      - CSplus PF2
      - CSminus PF1

    Metrics per cell:
      - r (Pearson correlation between S1 and S2 tuning curves)
      - spearman_r (Spearman rank correlation between S1 and S2 tuning curves)
      - cosine_similarity between S1 and S2 tuning curves
        * For theta, subtract each session trace mean before cosine.
      - delta_peak_x_cm (peak location shift: S2 - S1)
      - auc_ratio (AUC_S2 / AUC_S1)
        * For slow Vm: use positive-only AUC over slow_auc_window_cm.
      - peak_ratio_s2_s1 (peak value in peak_window_cm: S2 / S1)
      - peak_abs_sym_diff (abs((S2-S1)/(S2+S1)) using peak values in peak_window_cm)
    """
    import csv
    import pandas as pd

    min_trav = int(min_traversals_per_session)
    if min_trav < 0:
        raise ValueError("min_traversals_per_session must be >= 0.")
    split_mode_norm = _normalize_two_session_split_mode(split_mode)
    split_window_minutes_use = _validate_two_session_split_window_minutes(split_mode_norm, split_window_minutes)
    min_trials_col = None if min_trials_per_column_2sessions is None else int(min_trials_per_column_2sessions)
    if min_trials_col is not None and min_trials_col < 0:
        raise ValueError("min_trials_per_column_2sessions must be >= 0 when provided.")
    effective_min_trials = int(min_trav)
    if min_trials_col is not None:
        # Plot path uses gate per column: n_trials >= min_trials_per_column.
        # For stability (S1 vs S2), apply that exact rule to BOTH sessions.
        if bool(strict_follow_plot_inclusion):
            effective_min_trials = int(min_trials_col)
        else:
            effective_min_trials = max(effective_min_trials, int(min_trials_col))

    stage = str(average_export_stage).strip().lower()
    if stage not in {"pre", "post"}:
        raise ValueError("average_export_stage must be 'pre' or 'post'.")

    distance_bin_cm = float(distance_centered_dataset.get("metadata", {}).get("distance_bin_cm", 1.0))
    smooth_bins = 0
    if smooth_window_cm is not None:
        smooth_bins = int(_distance_smooth_cm_to_bins(distance_bin_cm, float(smooth_window_cm)))
    if smooth_bins < 0:
        smooth_bins = 0

    metric_to_stack = {
        "all_spike": "rate_stack",
        "ss": "ss_rate_stack",
        "cs": "cs_rate_stack",
        "theta": "theta_stack",
        "slow": "slow_stack",
    }
    group_specs = [
        ("CSplus", 1, "CSplus_PF1"),
        ("CSplus", 2, "CSplus_PF2"),
        ("CSminus", 1, "CSminus_PF1"),
    ]

    def _smooth_stack(stack: np.ndarray) -> np.ndarray:
        if smooth_bins <= 1:
            return stack
        out = np.full_like(stack, np.nan)
        for i in range(stack.shape[0]):
            out[i] = _smooth_boxcar(stack[i], int(smooth_bins))
        return out

    def _pearson_r_with_reason(a: np.ndarray, b: np.ndarray) -> tuple[float, str | None, int]:
        valid = np.isfinite(a) & np.isfinite(b)
        n_valid = int(np.sum(valid))
        if n_valid < 2:
            return np.nan, "insufficient_overlap_bins", n_valid
        av = np.asarray(a[valid], dtype=float)
        bv = np.asarray(b[valid], dtype=float)
        std_a = float(np.nanstd(av))
        std_b = float(np.nanstd(bv))
        if np.isclose(std_a, 0.0) and np.isclose(std_b, 0.0):
            return np.nan, "flat_trace_both_sessions", n_valid
        if np.isclose(std_a, 0.0):
            return np.nan, "flat_trace_session1", n_valid
        if np.isclose(std_b, 0.0):
            return np.nan, "flat_trace_session2", n_valid
        return float(np.corrcoef(av, bv)[0, 1]), None, n_valid

    def _spearman_r_with_reason(a: np.ndarray, b: np.ndarray) -> tuple[float, str | None, int]:
        valid = np.isfinite(a) & np.isfinite(b)
        n_valid = int(np.sum(valid))
        if n_valid < 2:
            return np.nan, "insufficient_overlap_bins", n_valid
        av = np.asarray(a[valid], dtype=float)
        bv = np.asarray(b[valid], dtype=float)
        std_a = float(np.nanstd(av))
        std_b = float(np.nanstd(bv))
        if np.isclose(std_a, 0.0) and np.isclose(std_b, 0.0):
            return np.nan, "flat_trace_both_sessions", n_valid
        if np.isclose(std_a, 0.0):
            return np.nan, "flat_trace_session1", n_valid
        if np.isclose(std_b, 0.0):
            return np.nan, "flat_trace_session2", n_valid
        res = scipy_stats.spearmanr(av, bv, nan_policy="omit")
        rho = float(res.statistic)
        if not np.isfinite(rho):
            return np.nan, "spearman_nan", n_valid
        return rho, None, n_valid

    def _cosine_similarity_with_reason(
        a: np.ndarray,
        b: np.ndarray,
        *,
        center: bool = False,
    ) -> tuple[float, str | None, int]:
        valid = np.isfinite(a) & np.isfinite(b)
        n_valid = int(np.sum(valid))
        if n_valid < 2:
            return np.nan, "insufficient_overlap_bins", n_valid
        av = np.asarray(a[valid], dtype=float)
        bv = np.asarray(b[valid], dtype=float)
        if bool(center):
            mean_a = float(np.nanmean(av))
            mean_b = float(np.nanmean(bv))
            if (not np.isfinite(mean_a)) or (not np.isfinite(mean_b)):
                return np.nan, "invalid_centering_mean", n_valid
            av = av - mean_a
            bv = bv - mean_b
        norm_a = float(np.linalg.norm(av))
        norm_b = float(np.linalg.norm(bv))
        if np.isclose(norm_a, 0.0) and np.isclose(norm_b, 0.0):
            return np.nan, "zero_norm_both_sessions", n_valid
        if np.isclose(norm_a, 0.0):
            return 0.0, "zero_norm_session1_set_to_zero", n_valid
        if np.isclose(norm_b, 0.0):
            return 0.0, "zero_norm_session2_set_to_zero", n_valid
        return float(np.dot(av, bv) / (norm_a * norm_b)), None, n_valid

    def _peak_x_with_reason(trace: np.ndarray, x: np.ndarray) -> tuple[float, str | None]:
        if trace.ndim != 1 or x.ndim != 1 or trace.size != x.size:
            return np.nan, "shape_mismatch"
        if not np.any(np.isfinite(trace)):
            return np.nan, "all_nan_trace"
        idx = int(np.nanargmax(trace))
        if idx < 0 or idx >= x.size or (not np.isfinite(x[idx])):
            return np.nan, "invalid_peak_index"
        return float(x[idx]), None

    def _auc_ratio_with_reason(metric: str, tr1: np.ndarray, tr2: np.ndarray, x: np.ndarray) -> tuple[float, str | None, int]:
        if tr1.ndim != 1 or tr2.ndim != 1 or x.ndim != 1 or tr1.size != x.size or tr2.size != x.size:
            return np.nan, "shape_mismatch", 0
        if metric == "slow":
            w0, w1 = float(slow_auc_window_cm[0]), float(slow_auc_window_cm[1])
            if w1 < w0:
                w0, w1 = w1, w0
            mask = (x >= w0) & (x <= w1) & np.isfinite(x) & np.isfinite(tr1) & np.isfinite(tr2)
            n_bins = int(np.sum(mask))
            if n_bins < 2:
                return np.nan, "insufficient_auc_bins", n_bins
            y1 = np.maximum(tr1[mask], 0.0)
            y2 = np.maximum(tr2[mask], 0.0)
        else:
            if auc_window_cm is None:
                mask = np.isfinite(x) & np.isfinite(tr1) & np.isfinite(tr2)
            else:
                a0, a1 = float(auc_window_cm[0]), float(auc_window_cm[1])
                if a1 < a0:
                    a0, a1 = a1, a0
                mask = (x >= a0) & (x <= a1) & np.isfinite(x) & np.isfinite(tr1) & np.isfinite(tr2)
            n_bins = int(np.sum(mask))
            if n_bins < 2:
                return np.nan, "insufficient_auc_bins", n_bins
            y1 = tr1[mask]
            y2 = tr2[mask]
        xx = x[mask]
        auc1 = float(np.trapz(y1, x=xx))
        auc2 = float(np.trapz(y2, x=xx))
        if (not np.isfinite(auc1)) or np.isclose(auc1, 0.0):
            return np.nan, "zero_or_invalid_auc_session1", int(np.sum(mask))
        return float(auc2 / auc1), None, int(np.sum(mask))

    def _peak_ratio_with_reason(tr1: np.ndarray, tr2: np.ndarray, x: np.ndarray) -> tuple[float, float, float, str | None, int]:
        if tr1.ndim != 1 or tr2.ndim != 1 or x.ndim != 1 or tr1.size != x.size or tr2.size != x.size:
            return np.nan, np.nan, np.nan, "shape_mismatch", 0
        p0, p1 = float(peak_window_cm[0]), float(peak_window_cm[1])
        if p1 < p0:
            p0, p1 = p1, p0
        mask_x = (x >= p0) & (x <= p1) & np.isfinite(x)
        if int(np.sum(mask_x)) < 1:
            return np.nan, np.nan, np.nan, "insufficient_peak_window_bins", int(np.sum(mask_x))
        m1 = mask_x & np.isfinite(tr1)
        m2 = mask_x & np.isfinite(tr2)
        if int(np.sum(m1)) < 1:
            return np.nan, np.nan, np.nan, "no_finite_peak_session1", int(np.sum(mask_x))
        if int(np.sum(m2)) < 1:
            return np.nan, np.nan, np.nan, "no_finite_peak_session2", int(np.sum(mask_x))
        peak1 = float(np.nanmax(tr1[m1]))
        peak2 = float(np.nanmax(tr2[m2]))
        if (not np.isfinite(peak1)) or np.isclose(peak1, 0.0):
            return peak1, peak2, np.nan, "zero_or_invalid_peak_session1", int(np.sum(mask_x))
        return peak1, peak2, float(peak2 / peak1), None, int(np.sum(mask_x))

    def _peak_abs_sym_diff_with_reason(peak1: float, peak2: float) -> tuple[float, str | None]:
        if (not np.isfinite(peak1)) or (not np.isfinite(peak2)):
            return np.nan, "invalid_peak_values"
        denom = float(peak2) + float(peak1)
        if np.isclose(denom, 0.0):
            return np.nan, "zero_or_invalid_peak_sum"
        return float(abs((float(peak2) - float(peak1)) / denom)), None

    def _apply_r_nan_policy(r_val: float) -> tuple[float, bool]:
        if np.isfinite(r_val):
            return float(r_val), False
        if bool(set_nan_r_to_zero):
            return 0.0, True
        return np.nan, False

    rows: list[dict[str, Any]] = []
    nan_rows: list[dict[str, Any]] = []
    skipped: dict[str, int] = {"missing": 0, "insufficient_sessions": 0, "low_traversals": 0}

    used_saved_average_exports = False

    def _safe_float(v: Any, default: float = np.nan) -> float:
        try:
            val = float(v)
        except (TypeError, ValueError):
            return float(default)
        return val if np.isfinite(val) else float(default)

    def _safe_int(v: Any, default: int = 0) -> int:
        val = _safe_float(v, default=np.nan)
        if not np.isfinite(val):
            return int(default)
        return int(val)

    def _row_to_scalar(row: dict[str, Any], npz: Any, key: str, default: float = np.nan) -> float:
        if key in row and row.get(key, "") not in ("", None):
            return _safe_float(row.get(key), default=default)
        if key in npz:
            arr = np.asarray(npz[key], dtype=float).reshape(-1)
            if arr.size > 0:
                return _safe_float(arr[0], default=default)
        return float(default)

    if bool(use_saved_average_exports):
        if average_export_dir is None:
            export_root = Path("figures") / "CKII_pooled" / "pf_distance_centered_2sessions_average_exports"
        else:
            export_root = Path(average_export_dir)

        if export_root.exists():
            for cat, pf_rank, group in group_specs:
                index_csv = export_root / str(cat) / "session_averages_pre_post_index.csv"
                if not index_csv.exists():
                    continue
                try:
                    with open(index_csv, newline="") as f:
                        reader = csv.DictReader(f)
                        for row in reader:
                            npz_path = Path(str(row.get("npz_path", "")))
                            if not npz_path.exists():
                                skipped["missing"] += 1
                                continue
                            try:
                                with np.load(npz_path, allow_pickle=True) as npz:
                                    if not _export_matches_two_session_split(
                                        row,
                                        npz,
                                        split_mode=split_mode_norm,
                                        split_window_minutes=split_window_minutes_use,
                                    ):
                                        continue
                                    rel_key = f"distance_rel_pf{int(pf_rank)}"
                                    if rel_key not in npz:
                                        skipped["missing"] += 1
                                        continue
                                    x = np.asarray(npz[rel_key], dtype=float).reshape(-1)
                                    if x.ndim != 1 or x.size == 0:
                                        skipped["missing"] += 1
                                        continue

                                    n1_key = f"n_trials_pf{int(pf_rank)}_s1"
                                    n2_key = f"n_trials_pf{int(pf_rank)}_s2"
                                    n1 = _safe_int(_row_to_scalar(row, npz, n1_key, default=np.nan), default=0)
                                    n2 = _safe_int(_row_to_scalar(row, npz, n2_key, default=np.nan), default=0)
                                    if min(n1, n2) < effective_min_trials:
                                        skipped["low_traversals"] += 1
                                        continue

                                    s1_key = f"session_idx_pf{int(pf_rank)}_s1"
                                    s2_key = f"session_idx_pf{int(pf_rank)}_s2"
                                    s1_val = _safe_int(_row_to_scalar(row, npz, s1_key, default=0.0), default=0)
                                    s2_val = _safe_int(_row_to_scalar(row, npz, s2_key, default=1.0), default=1)

                                    animal_id = str(row.get("animal_id", ""))
                                    cell_idx = _safe_int(row.get("cell_idx", -1), default=-1)
                                    cell_num = _safe_int(row.get("cell_num", cell_idx + 1), default=(cell_idx + 1))

                                    for metric_name in metric_to_stack:
                                        tr1_key = f"{stage}_pf{int(pf_rank)}_s1_{metric_name}"
                                        tr2_key = f"{stage}_pf{int(pf_rank)}_s2_{metric_name}"
                                        if tr1_key not in npz or tr2_key not in npz:
                                            continue
                                        tr1 = np.asarray(npz[tr1_key], dtype=float).reshape(-1)
                                        tr2 = np.asarray(npz[tr2_key], dtype=float).reshape(-1)
                                        if tr1.ndim != 1 or tr2.ndim != 1 or tr1.size != x.size or tr2.size != x.size:
                                            skipped["missing"] += 1
                                            continue
                                        r_val_raw, r_reason, n_overlap_bins = _pearson_r_with_reason(tr1, tr2)
                                        r_val, r_set_to_zero = _apply_r_nan_policy(r_val_raw)
                                        spearman_val_raw, spearman_reason, n_spearman_bins = _spearman_r_with_reason(tr1, tr2)
                                        spearman_val, spearman_set_to_zero = _apply_r_nan_policy(spearman_val_raw)
                                        cosine_similarity, cosine_reason, n_cosine_bins = _cosine_similarity_with_reason(
                                            tr1,
                                            tr2,
                                            center=(str(metric_name) == "theta"),
                                        )
                                        p1, p1_reason = _peak_x_with_reason(tr1, x)
                                        p2, p2_reason = _peak_x_with_reason(tr2, x)
                                        dpeak = float(p2 - p1) if (np.isfinite(p1) and np.isfinite(p2)) else np.nan
                                        auc_ratio, auc_reason, n_auc_bins = _auc_ratio_with_reason(metric_name, tr1, tr2, x)
                                        peak_s1, peak_s2, peak_ratio, peak_reason, n_peak_bins = _peak_ratio_with_reason(tr1, tr2, x)
                                        peak_abs_sym_diff, peak_abs_sym_diff_reason = _peak_abs_sym_diff_with_reason(peak_s1, peak_s2)

                                        rows.append(
                                            {
                                                "group": str(group),
                                                "category": str(cat),
                                                "pf_rank": int(pf_rank),
                                                "animal_id": str(animal_id),
                                                "cell_idx": int(cell_idx),
                                                "cell_num": int(cell_num) if int(cell_idx) >= 0 else np.nan,
                                                "metric": str(metric_name),
                                                "session1_idx": int(s1_val),
                                                "session2_idx": int(s2_val),
                                                "n_trials_s1": int(n1),
                                                "n_trials_s2": int(n2),
                                                "r": float(r_val) if np.isfinite(r_val) else np.nan,
                                                "spearman_r": float(spearman_val) if np.isfinite(spearman_val) else np.nan,
                                                "cosine_similarity": float(cosine_similarity) if np.isfinite(cosine_similarity) else np.nan,
                                                "cosine_mean_centered": bool(str(metric_name) == "theta"),
                                                "delta_peak_x_cm": float(dpeak) if np.isfinite(dpeak) else np.nan,
                                                "auc_ratio": float(auc_ratio) if np.isfinite(auc_ratio) else np.nan,
                                                "peak_s1": float(peak_s1) if np.isfinite(peak_s1) else np.nan,
                                                "peak_s2": float(peak_s2) if np.isfinite(peak_s2) else np.nan,
                                                "peak_ratio_s2_s1": float(peak_ratio) if np.isfinite(peak_ratio) else np.nan,
                                                "peak_abs_sym_diff": float(peak_abs_sym_diff) if np.isfinite(peak_abs_sym_diff) else np.nan,
                                            }
                                        )
                                        if bool(r_set_to_zero) or bool(spearman_set_to_zero) or (not np.isfinite(cosine_similarity)) or (not np.isfinite(dpeak)) or (not np.isfinite(auc_ratio)) or (not np.isfinite(peak_ratio)) or (not np.isfinite(peak_abs_sym_diff)):
                                            nan_rows.append(
                                                {
                                                    "group": str(group),
                                                    "category": str(cat),
                                                    "pf_rank": int(pf_rank),
                                                    "animal_id": str(animal_id),
                                                    "cell_idx": int(cell_idx),
                                                    "cell_num": int(cell_num) if int(cell_idx) >= 0 else np.nan,
                                                    "metric": str(metric_name),
                                                    "n_trials_s1": int(n1),
                                                    "n_trials_s2": int(n2),
                                                    "n_overlap_bins_for_r": int(n_overlap_bins),
                                                    "n_overlap_bins_for_spearman": int(n_spearman_bins),
                                                    "n_overlap_bins_for_cosine": int(n_cosine_bins),
                                                    "n_auc_bins": int(n_auc_bins),
                                                    "n_peak_bins": int(n_peak_bins),
                                                    "r_is_nan": bool(not np.isfinite(r_val_raw)),
                                                    "r_set_to_zero": bool(r_set_to_zero),
                                                    "r_nan_reason": (str(r_reason) if ((not np.isfinite(r_val_raw)) and r_reason is not None) else ""),
                                                    "spearman_r_is_nan": bool(not np.isfinite(spearman_val_raw)),
                                                    "spearman_r_set_to_zero": bool(spearman_set_to_zero),
                                                    "spearman_r_nan_reason": (
                                                        str(spearman_reason)
                                                        if ((not np.isfinite(spearman_val_raw)) and spearman_reason is not None)
                                                        else ""
                                                    ),
                                                    "cosine_similarity_is_nan": bool(not np.isfinite(cosine_similarity)),
                                                    "cosine_mean_centered": bool(str(metric_name) == "theta"),
                                                    "cosine_similarity_nan_reason": (
                                                        str(cosine_reason)
                                                        if ((not np.isfinite(cosine_similarity)) and cosine_reason is not None)
                                                        else ""
                                                    ),
                                                    "peak_shift_is_nan": bool(not np.isfinite(dpeak)),
                                                    "peak_shift_nan_reason": (
                                                        "session1:" + str(p1_reason) if ((not np.isfinite(p1)) and p1_reason is not None) else ""
                                                    )
                                                    + (
                                                        (";session2:" + str(p2_reason))
                                                        if ((not np.isfinite(p2)) and p2_reason is not None)
                                                        else ""
                                                    ),
                                                    "auc_ratio_is_nan": bool(not np.isfinite(auc_ratio)),
                                                    "auc_ratio_nan_reason": (str(auc_reason) if (not np.isfinite(auc_ratio) and auc_reason is not None) else ""),
                                                    "peak_ratio_is_nan": bool(not np.isfinite(peak_ratio)),
                                                    "peak_ratio_nan_reason": (str(peak_reason) if (not np.isfinite(peak_ratio) and peak_reason is not None) else ""),
                                                    "peak_abs_sym_diff_is_nan": bool(not np.isfinite(peak_abs_sym_diff)),
                                                    "peak_abs_sym_diff_nan_reason": (
                                                        str(peak_abs_sym_diff_reason)
                                                        if ((not np.isfinite(peak_abs_sym_diff)) and peak_abs_sym_diff_reason is not None)
                                                        else ""
                                                    ),
                                                }
                                            )
                                    used_saved_average_exports = True
                            except Exception:
                                skipped["missing"] += 1
                                continue
                except OSError:
                    continue

    if not bool(used_saved_average_exports):
        for cat, pf_rank, group in group_specs:
            block = distance_centered_dataset.get(cat, {}).get(int(pf_rank), {})
            x = np.asarray(block.get("distance_rel", []), dtype=float)
            entries = list(block.get("entries", []))
            if x.ndim != 1 or x.size == 0:
                skipped["missing"] += int(len(entries))
                continue

            for entry in entries:
                entry_use = _split_distance_centered_entry_for_two_sessions(
                    entry,
                    split_mode=split_mode_norm,
                    split_window_minutes=split_window_minutes_use,
                )
                if entry_use is None:
                    skipped["missing"] += 1
                    continue
                data_all = entry_use.get("data", {}).get("all", {})
                trial_data = data_all.get("trial_data", {}) if isinstance(data_all, dict) else {}
                sess = np.asarray(trial_data.get("session_idx", []), dtype=int) if isinstance(trial_data, dict) else np.array([], dtype=int)

                rate_stack = data_all.get("rate_stack")
                if rate_stack is None:
                    skipped["missing"] += 1
                    continue
                rate_stack = np.asarray(rate_stack, dtype=float)
                if rate_stack.ndim != 2 or rate_stack.shape[1] != x.size:
                    skipped["missing"] += 1
                    continue
                if sess.ndim != 1 or sess.size != int(rate_stack.shape[0]):
                    skipped["missing"] += 1
                    continue

                sess_vals = np.sort(np.unique(sess.astype(int)))
                if sess_vals.size < 2:
                    skipped["insufficient_sessions"] += 1
                    continue
                s1_val, s2_val = int(sess_vals[0]), int(sess_vals[1])
                m1 = sess == s1_val
                m2 = sess == s2_val
                n1 = int(np.sum(m1))
                n2 = int(np.sum(m2))
                if min(n1, n2) < effective_min_trials:
                    skipped["low_traversals"] += 1
                    continue

                for metric_name, stack_key in metric_to_stack.items():
                    stack = data_all.get(stack_key)
                    if stack is None:
                        continue
                    stack = np.asarray(stack, dtype=float)
                    if stack.ndim != 2 or stack.shape[1] != x.size or stack.shape[0] != sess.size:
                        continue
                    stack = _smooth_stack(stack)
                    tr1 = np.nanmean(stack[m1], axis=0)
                    tr2 = np.nanmean(stack[m2], axis=0)
                    tr1 = np.asarray(tr1, dtype=float)
                    tr2 = np.asarray(tr2, dtype=float)
                    r_val_raw, r_reason, n_overlap_bins = _pearson_r_with_reason(tr1, tr2)
                    r_val, r_set_to_zero = _apply_r_nan_policy(r_val_raw)
                    spearman_val_raw, spearman_reason, n_spearman_bins = _spearman_r_with_reason(tr1, tr2)
                    spearman_val, spearman_set_to_zero = _apply_r_nan_policy(spearman_val_raw)
                    cosine_similarity, cosine_reason, n_cosine_bins = _cosine_similarity_with_reason(
                        tr1,
                        tr2,
                        center=(str(metric_name) == "theta"),
                    )
                    p1, p1_reason = _peak_x_with_reason(tr1, x)
                    p2, p2_reason = _peak_x_with_reason(tr2, x)
                    dpeak = float(p2 - p1) if (np.isfinite(p1) and np.isfinite(p2)) else np.nan
                    auc_ratio, auc_reason, n_auc_bins = _auc_ratio_with_reason(metric_name, tr1, tr2, x)
                    peak_s1, peak_s2, peak_ratio, peak_reason, n_peak_bins = _peak_ratio_with_reason(tr1, tr2, x)
                    peak_abs_sym_diff, peak_abs_sym_diff_reason = _peak_abs_sym_diff_with_reason(peak_s1, peak_s2)

                    rows.append(
                        {
                            "group": str(group),
                            "category": str(cat),
                            "pf_rank": int(pf_rank),
                            "animal_id": str(entry_use.get("session", "")),
                            "cell_idx": int(entry_use.get("cell_idx", -1)),
                            "cell_num": (int(entry_use.get("cell_idx", -1)) + 1) if int(entry_use.get("cell_idx", -1)) >= 0 else np.nan,
                            "metric": str(metric_name),
                            "session1_idx": int(s1_val),
                            "session2_idx": int(s2_val),
                            "n_trials_s1": int(n1),
                            "n_trials_s2": int(n2),
                            "r": float(r_val) if np.isfinite(r_val) else np.nan,
                            "spearman_r": float(spearman_val) if np.isfinite(spearman_val) else np.nan,
                            "cosine_similarity": float(cosine_similarity) if np.isfinite(cosine_similarity) else np.nan,
                            "cosine_mean_centered": bool(str(metric_name) == "theta"),
                            "delta_peak_x_cm": float(dpeak) if np.isfinite(dpeak) else np.nan,
                            "auc_ratio": float(auc_ratio) if np.isfinite(auc_ratio) else np.nan,
                            "peak_s1": float(peak_s1) if np.isfinite(peak_s1) else np.nan,
                            "peak_s2": float(peak_s2) if np.isfinite(peak_s2) else np.nan,
                            "peak_ratio_s2_s1": float(peak_ratio) if np.isfinite(peak_ratio) else np.nan,
                            "peak_abs_sym_diff": float(peak_abs_sym_diff) if np.isfinite(peak_abs_sym_diff) else np.nan,
                        }
                    )
                    if bool(r_set_to_zero) or bool(spearman_set_to_zero) or (not np.isfinite(cosine_similarity)) or (not np.isfinite(dpeak)) or (not np.isfinite(auc_ratio)) or (not np.isfinite(peak_ratio)) or (not np.isfinite(peak_abs_sym_diff)):
                        nan_rows.append(
                            {
                                "group": str(group),
                                "category": str(cat),
                                "pf_rank": int(pf_rank),
                                "animal_id": str(entry_use.get("session", "")),
                                "cell_idx": int(entry_use.get("cell_idx", -1)),
                                "cell_num": (int(entry_use.get("cell_idx", -1)) + 1) if int(entry_use.get("cell_idx", -1)) >= 0 else np.nan,
                                "metric": str(metric_name),
                                "n_trials_s1": int(n1),
                                "n_trials_s2": int(n2),
                                "n_overlap_bins_for_r": int(n_overlap_bins),
                                "n_overlap_bins_for_spearman": int(n_spearman_bins),
                                "n_overlap_bins_for_cosine": int(n_cosine_bins),
                                "n_auc_bins": int(n_auc_bins),
                                "n_peak_bins": int(n_peak_bins),
                                "r_is_nan": bool(not np.isfinite(r_val_raw)),
                                "r_set_to_zero": bool(r_set_to_zero),
                                "r_nan_reason": (str(r_reason) if ((not np.isfinite(r_val_raw)) and r_reason is not None) else ""),
                                "spearman_r_is_nan": bool(not np.isfinite(spearman_val_raw)),
                                "spearman_r_set_to_zero": bool(spearman_set_to_zero),
                                "spearman_r_nan_reason": (
                                    str(spearman_reason)
                                    if ((not np.isfinite(spearman_val_raw)) and spearman_reason is not None)
                                    else ""
                                ),
                                "cosine_similarity_is_nan": bool(not np.isfinite(cosine_similarity)),
                                "cosine_mean_centered": bool(str(metric_name) == "theta"),
                                "cosine_similarity_nan_reason": (
                                    str(cosine_reason)
                                    if ((not np.isfinite(cosine_similarity)) and cosine_reason is not None)
                                    else ""
                                ),
                                "peak_shift_is_nan": bool(not np.isfinite(dpeak)),
                                "peak_shift_nan_reason": (
                                    "session1:" + str(p1_reason) if ((not np.isfinite(p1)) and p1_reason is not None) else ""
                                )
                                + (
                                    (";session2:" + str(p2_reason))
                                    if ((not np.isfinite(p2)) and p2_reason is not None)
                                    else ""
                                ),
                                "auc_ratio_is_nan": bool(not np.isfinite(auc_ratio)),
                                "auc_ratio_nan_reason": (str(auc_reason) if (not np.isfinite(auc_ratio) and auc_reason is not None) else ""),
                                "peak_ratio_is_nan": bool(not np.isfinite(peak_ratio)),
                                "peak_ratio_nan_reason": (str(peak_reason) if (not np.isfinite(peak_ratio) and peak_reason is not None) else ""),
                                "peak_abs_sym_diff_is_nan": bool(not np.isfinite(peak_abs_sym_diff)),
                                "peak_abs_sym_diff_nan_reason": (
                                    str(peak_abs_sym_diff_reason)
                                    if ((not np.isfinite(peak_abs_sym_diff)) and peak_abs_sym_diff_reason is not None)
                                    else ""
                                ),
                            }
                        )

    per_cell = pd.DataFrame(rows)
    nan_diag_df = pd.DataFrame(nan_rows)
    if bool(print_nan_diagnostics):
        if nan_diag_df is None or len(nan_diag_df) == 0:
            print("[session_stability] No NaN metrics from flat/invalid traces after inclusion gating.")
        else:
            print("[session_stability] Cells/metrics with NaN values (flat/invalid traces):")
            for _, rr in nan_diag_df.iterrows():
                parts: list[str] = []
                if bool(rr.get("r_is_nan", False)):
                    parts.append(f"r:{str(rr.get('r_nan_reason', ''))}")
                if bool(rr.get("r_set_to_zero", False)):
                    parts.append("r_set_to_zero")
                if bool(rr.get("spearman_r_is_nan", False)):
                    parts.append(f"spearman:{str(rr.get('spearman_r_nan_reason', ''))}")
                if bool(rr.get("spearman_r_set_to_zero", False)):
                    parts.append("spearman_set_to_zero")
                if bool(rr.get("cosine_similarity_is_nan", False)):
                    parts.append(f"cosine:{str(rr.get('cosine_similarity_nan_reason', ''))}")
                if bool(rr.get("peak_shift_is_nan", False)):
                    parts.append(f"peak_shift:{str(rr.get('peak_shift_nan_reason', ''))}")
                if bool(rr.get("auc_ratio_is_nan", False)):
                    parts.append(f"auc_ratio:{str(rr.get('auc_ratio_nan_reason', ''))}")
                if bool(rr.get("peak_ratio_is_nan", False)):
                    parts.append(f"peak_ratio:{str(rr.get('peak_ratio_nan_reason', ''))}")
                if bool(rr.get("peak_abs_sym_diff_is_nan", False)):
                    parts.append(f"peak_abs_sym_diff:{str(rr.get('peak_abs_sym_diff_nan_reason', ''))}")
                cell_num_val = rr.get("cell_num", np.nan)
                if np.isfinite(cell_num_val):
                    cell_lbl = f"{rr.get('animal_id', '')}_Cell{int(cell_num_val)}"
                else:
                    cell_lbl = f"{rr.get('animal_id', '')}_CellIdx{rr.get('cell_idx', '')}"
                print(
                    f"  group={rr.get('group', '')}, metric={rr.get('metric', '')}, "
                    f"cell={cell_lbl}, n_s1={int(rr.get('n_trials_s1', 0))}, n_s2={int(rr.get('n_trials_s2', 0))}, "
                    f"overlap_bins={int(rr.get('n_overlap_bins_for_r', 0))}, "
                    f"spearman_bins={int(rr.get('n_overlap_bins_for_spearman', 0))}, "
                    f"cosine_bins={int(rr.get('n_overlap_bins_for_cosine', 0))}, "
                    f"auc_bins={int(rr.get('n_auc_bins', 0))}, "
                    f"peak_bins={int(rr.get('n_peak_bins', 0))}, "
                    f"reasons={'; '.join(parts)}"
                )
    return {
        "per_cell_stability": per_cell,
        "nan_diagnostics": nan_diag_df,
        "skipped_counts": skipped,
        "data_source": "saved_average_exports" if bool(used_saved_average_exports) else "distance_centered_dataset",
        "average_export_dir": str(export_root) if bool(used_saved_average_exports) else None,
        "average_export_stage": str(stage) if bool(used_saved_average_exports) else None,
        "split_mode": str(split_mode_norm),
        "split_window_minutes": (None if split_window_minutes_use is None else float(split_window_minutes_use)),
        "min_traversals_per_session": int(min_trav),
        "min_trials_per_column_2sessions": (None if min_trials_col is None else int(min_trials_col)),
        "effective_min_trials_per_session": int(effective_min_trials),
        "strict_follow_plot_inclusion": bool(strict_follow_plot_inclusion),
        "set_nan_r_to_zero": bool(set_nan_r_to_zero),
        "smooth_window_cm": None if bool(used_saved_average_exports) else (None if smooth_window_cm is None else float(smooth_window_cm)),
        "auc_window_cm": None if auc_window_cm is None else (float(auc_window_cm[0]), float(auc_window_cm[1])),
        "slow_auc_window_cm": (float(slow_auc_window_cm[0]), float(slow_auc_window_cm[1])),
        "peak_window_cm": (float(peak_window_cm[0]), float(peak_window_cm[1])),
        "theta_cosine_mean_centered": True,
    }


def plot_pf_distance_centered_session_stability(
    stability_results: dict[str, Any],
    *,
    figure_save_folder: str | Path | None = None,
    figsize: tuple[float, float] | None = None,
    row_height: float = 1.2,
    stat_label_overrides: dict[str, str] | None = None,
    show_plot: bool = True,
    save_csv: bool = True,
) -> dict[str, Any]:
    """
    Plot session-stability summary as one combined figure.
    Rows: metrics [all_spike, ss, cs, theta, slow]
    Cols: [r, spearman_r, cosine_similarity, peak_shift_cm, auc_ratio, peak_ratio_s2_s1, peak_abs_sym_diff]
    Groups per subplot: [CS+ PF1, CS+ PF2, CS- PF1] except CS row (no CS- PF1).
    """
    import pandas as pd
    from matplotlib.lines import Line2D

    df = stability_results.get("per_cell_stability")
    if df is None or len(df) == 0:
        return {}

    if figure_save_folder is None:
        figure_root = Path("figures") / "CKII_pooled"
    else:
        figure_root = Path(figure_save_folder)
    figure_root.mkdir(parents=True, exist_ok=True)

    metric_order = ["all_spike", "ss", "cs", "theta", "slow"]
    metric_labels = {
        "all_spike": "All-spike",
        "ss": "SS",
        "cs": "CS",
        "theta": "Theta",
        "slow": "Slow Vm",
    }
    # Match grand-average trace colors.
    metric_colors = {
        "all_spike": "#555555",
        "ss": "#026C80",
        "cs": "#EE9B00",
        "theta": "blue",
        "slow": "red",
    }
    stat_specs = [("r", "r")]
    if "spearman_r" in set(pd.DataFrame(df).columns):
        stat_specs.append(("spearman_r", "Spearman"))
    if "cosine_similarity" in set(pd.DataFrame(df).columns):
        stat_specs.append(("cosine_similarity", "Cosine"))
    stat_specs.extend(
        [
            ("delta_peak_x_cm", "Peak shift (cm)"),
            ("auc_ratio", "AUC ratio"),
            ("peak_ratio_s2_s1", "Peak ratio (S2/S1)"),
            ("peak_abs_sym_diff", "|(S2-S1)/(S2+S1)|"),
        ]
    )
    if isinstance(stat_label_overrides, dict) and len(stat_label_overrides) > 0:
        stat_specs = [(k, str(stat_label_overrides.get(k, lbl))) for (k, lbl) in stat_specs]
    group_order = ["CSplus_PF1", "CSplus_PF2", "CSminus_PF1"]
    group_labels = ["CS+ PF1", "CS+ PF2", "CS- PF1"]

    def _paired_test_auto_small_n(vals_a: np.ndarray, vals_b: np.ndarray) -> tuple[float, float, str, int, float]:
        vals_a = np.asarray(vals_a, dtype=float)
        vals_b = np.asarray(vals_b, dtype=float)
        n_pairs = min(len(vals_a), len(vals_b))
        if n_pairs == 0:
            return np.nan, np.nan, "n/a", 0, np.nan
        a = vals_a[:n_pairs]
        b = vals_b[:n_pairs]
        valid = np.isfinite(a) & np.isfinite(b)
        n_valid = int(np.sum(valid))
        if n_valid < 3:
            return np.nan, np.nan, "n/a", n_valid, np.nan
        if n_valid <= 6:
            try:
                res = scipy_stats.wilcoxon(a[valid], b[valid])
                return float(res.pvalue), float(res.statistic), "wilcoxon (n<=6)", n_valid, np.nan
            except ValueError:
                return np.nan, np.nan, "wilcoxon (n<=6)", n_valid, np.nan
        return paired_test_auto(a[valid], b[valid])

    def _unpaired_test_auto_small_n(vals_a: np.ndarray, vals_b: np.ndarray) -> tuple[float, float, str, int, int]:
        a = np.asarray(vals_a, dtype=float)
        b = np.asarray(vals_b, dtype=float)
        a = a[np.isfinite(a)]
        b = b[np.isfinite(b)]
        na, nb = len(a), len(b)
        if min(na, nb) < 3:
            return np.nan, np.nan, "n/a", na, nb
        if min(na, nb) <= 6:
            try:
                res = scipy_stats.mannwhitneyu(a, b, alternative="two-sided")
                return float(res.pvalue), float(res.statistic), "mann-whitney (n<=6)", na, nb
            except ValueError:
                return np.nan, np.nan, "mann-whitney (n<=6)", na, nb
        return unpaired_test_auto(a, b)

    def _swarm_x(y_vals: np.ndarray, center: float, width: float = 0.08) -> np.ndarray:
        y_vals = np.asarray(y_vals, dtype=float)
        n = y_vals.size
        if n == 0:
            return np.array([], dtype=float)
        if n == 1:
            return np.array([center], dtype=float)
        order = np.argsort(y_vals)
        x = np.full(n, center, dtype=float)
        y_span = float(np.nanmax(y_vals) - np.nanmin(y_vals)) if np.any(np.isfinite(y_vals)) else 1.0
        if (not np.isfinite(y_span)) or y_span <= 0:
            y_span = 1.0
        min_dy = 0.03 * y_span
        step = width / 5.0
        offsets = [0.0]
        for k in range(1, 6):
            offsets.extend([k * step, -k * step])
        placed: list[tuple[float, float]] = []
        for idx in order:
            yi = float(y_vals[idx])
            chosen = 0.0
            for off in offsets:
                xi = center + off
                clash = False
                for xj, yj in placed:
                    if abs(yj - yi) <= min_dy and abs(xj - xi) < (0.95 * step):
                        clash = True
                        break
                if not clash:
                    chosen = off
                    break
            x[idx] = center + chosen
            placed.append((x[idx], yi))
        return x

    def _add_sig_bracket(ax: Any, x1: float, x2: float, y: float, h: float, txt: str) -> None:
        ax.plot([x1, x1, x2, x2], [y, y + h, y + h, y], color="black", linewidth=0.6, clip_on=False)
        ax.text((x1 + x2) / 2, y + h, txt, ha="center", va="bottom", fontsize=5)

    figure_paths: dict[str, str] = {}
    stats_rows: list[dict[str, Any]] = []
    valid_metrics = [m for m in metric_order if len(df[df["metric"] == m]) > 0]
    if len(valid_metrics) == 0:
        return {}

    if figsize is None:
        fig_h = max(float(row_height) * len(valid_metrics), 1.8)
        fig_w = 5.4
    else:
        fig_w = float(figsize[0])
        fig_h = float(figsize[1])
    n_cols = int(len(stat_specs))
    fig, axes = plt.subplots(len(valid_metrics), n_cols, figsize=(fig_w, fig_h), sharex=True, sharey=False)
    if len(valid_metrics) == 1:
        axes = np.array([axes])

    for row_i, metric in enumerate(valid_metrics):
        sub = df[df["metric"] == metric].copy()
        metric_color = metric_colors.get(metric, "#555555")
        show_csminus_group = metric != "cs"
        group_order_use = list(group_order if show_csminus_group else group_order[:2])
        for col_i, (stat_key, stat_label) in enumerate(stat_specs):
            ax = axes[row_i, col_i]
            # Category backgrounds: CS+ PLC (first two groups), CS- PLC (third group).
            ax.axvspan(-0.5, 1.5, color="#FFF3E0", alpha=0.3, zorder=0)
            ax.axvspan(1.5, 2.5, color="#E3F2FD", alpha=0.3, zorder=0)
            if stat_key in set(sub.columns):
                sub_stat = sub[["animal_id", "cell_idx", "group", stat_key]].copy()
            else:
                sub_stat = pd.DataFrame(columns=["animal_id", "cell_idx", "group", stat_key])
            sub_stat["_plot_val"] = np.asarray(sub_stat[stat_key], dtype=float)
            if stat_key == "delta_peak_x_cm":
                sub_stat["_plot_val"] = np.abs(sub_stat["_plot_val"])
            groups = []
            for g in group_order_use:
                vals = np.asarray(sub_stat.loc[sub_stat["group"] == g, "_plot_val"], dtype=float)
                vals = vals[np.isfinite(vals)]
                groups.append(vals)

            pos = np.arange(len(group_order_use), dtype=float)
            bp = ax.boxplot(
                groups,
                positions=pos,
                widths=0.5,
                patch_artist=True,
                showfliers=False,
                medianprops={"color": "black", "linewidth": 0.7},
                boxprops={"linewidth": 0.5},
                whiskerprops={"linewidth": 0.5},
                capprops={"linewidth": 0.5},
            )
            for box in bp["boxes"]:
                box.set_facecolor(metric_color)
                box.set_alpha(0.25)

            for i, vals in enumerate(groups):
                if len(vals) == 0:
                    continue
                xs = _swarm_x(vals, pos[i], width=0.10)
                ax.scatter(xs, vals, s=4, color=metric_color, alpha=0.9, linewidths=0, zorder=2)

            # Connect paired CS+ PF1 <-> PF2 values (same animal/cell).
            pair = sub_stat[sub_stat["group"].isin(["CSplus_PF1", "CSplus_PF2"])][["animal_id", "cell_idx", "group", "_plot_val"]].copy()
            if len(pair) > 0:
                piv = pair.pivot_table(index=["animal_id", "cell_idx"], columns="group", values="_plot_val", aggfunc="first")
                if {"CSplus_PF1", "CSplus_PF2"}.issubset(set(piv.columns)):
                    for _, row in piv.iterrows():
                        v1 = row["CSplus_PF1"]
                        v2 = row["CSplus_PF2"]
                        if np.isfinite(v1) and np.isfinite(v2):
                            ax.plot([0, 1], [v1, v2], color="#C8C8C8", linewidth=0.45, alpha=0.7, zorder=1)

            # Stats: paired (g1 vs g2), unpaired (g1 vs g3)
            if len(pair) > 0:
                piv = pair.pivot_table(index=["animal_id", "cell_idx"], columns="group", values="_plot_val", aggfunc="first")
                if {"CSplus_PF1", "CSplus_PF2"}.issubset(set(piv.columns)):
                    p1 = np.asarray(piv["CSplus_PF1"], dtype=float)
                    p2 = np.asarray(piv["CSplus_PF2"], dtype=float)
                    p_pair, stat_pair, test_pair, n_pair, shapiro_pair = _paired_test_auto_small_n(p1, p2)
                else:
                    p_pair, stat_pair, test_pair, n_pair, shapiro_pair = np.nan, np.nan, "n/a", 0, np.nan
            else:
                p_pair, stat_pair, test_pair, n_pair, shapiro_pair = np.nan, np.nan, "n/a", 0, np.nan

            if show_csminus_group:
                g1 = np.asarray(sub_stat.loc[sub_stat["group"] == "CSplus_PF1", "_plot_val"], dtype=float)
                g3 = np.asarray(sub_stat.loc[sub_stat["group"] == "CSminus_PF1", "_plot_val"], dtype=float)
                p_u, stat_u, test_u, na, nb = _unpaired_test_auto_small_n(g1, g3)
            else:
                p_u, stat_u, test_u, na, nb = np.nan, np.nan, "n/a", 0, 0

            stats_rows.append(
                {
                    "metric": metric,
                    "subplot": "peak_shift_cm" if stat_key == "delta_peak_x_cm" else stat_key,
                    "comparison": "CSplus_PF1_vs_CSplus_PF2",
                    "n": int(n_pair),
                    "p_value": float(p_pair) if np.isfinite(p_pair) else np.nan,
                    "statistic": float(stat_pair) if np.isfinite(stat_pair) else np.nan,
                    "test": str(test_pair),
                    "shapiro_p": float(shapiro_pair) if np.isfinite(shapiro_pair) else np.nan,
                }
            )
            if show_csminus_group:
                stats_rows.append(
                    {
                        "metric": metric,
                        "subplot": "peak_shift_cm" if stat_key == "delta_peak_x_cm" else stat_key,
                        "comparison": "CSplus_PF1_vs_CSminus_PF1",
                        "n_a": int(na),
                        "n_b": int(nb),
                        "p_value": float(p_u) if np.isfinite(p_u) else np.nan,
                        "statistic": float(stat_u) if np.isfinite(stat_u) else np.nan,
                        "test": str(test_u),
                        "shapiro_p": np.nan,
                    }
                )

            all_vals = np.concatenate([v for v in groups if len(v) > 0]) if any(len(v) > 0 for v in groups) else np.array([0.0])
            y_min = float(np.nanmin(all_vals)) if np.any(np.isfinite(all_vals)) else -1.0
            y_max = float(np.nanmax(all_vals)) if np.any(np.isfinite(all_vals)) else 1.0
            span = y_max - y_min
            if not np.isfinite(span) or span <= 0:
                span = max(abs(y_max), 1.0) * 0.3
            base = y_max + 0.08 * span
            step = 0.32 * span
            h = 0.03 * span
            _add_sig_bracket(ax, 0.0, 1.0, base, h, _sig_label(p_pair))
            if show_csminus_group:
                _add_sig_bracket(ax, 0.0, 2.0, base + step, h, _sig_label(p_u))
                y_top = base + step + 2 * h + 0.10 * span
            else:
                y_top = base + h + 0.10 * span
            ax.set_ylim(y_min - 0.08 * span, y_top)

            if stat_key in {"r", "spearman_r", "cosine_similarity"}:
                ax.axhline(0, color="black", linestyle="--", linewidth=0.5, alpha=0.6)
            elif stat_key == "delta_peak_x_cm":
                ax.axhline(0, color="black", linestyle="--", linewidth=0.5, alpha=0.6)
            elif stat_key in {"auc_ratio", "peak_ratio_s2_s1"}:
                ax.axhline(1, color="black", linestyle="--", linewidth=0.5, alpha=0.6)
            elif stat_key == "peak_abs_sym_diff":
                ax.axhline(0, color="black", linestyle="--", linewidth=0.5, alpha=0.6)

            if row_i == 0:
                ax.set_title(stat_label, fontsize=6)
            if row_i == len(valid_metrics) - 1:
                ax.set_xticks(np.arange(3, dtype=float))
                ax.set_xticklabels(["PF1", "PF2", "PF"], rotation=0, ha="center")
            else:
                ax.set_xticks(np.arange(3, dtype=float))
                ax.tick_params(labelbottom=False)
            ax.set_xlim(-0.5, 2.5)
            ax.set_ylabel("")
            ax.tick_params(labelsize=5)
            ax.spines["top"].set_visible(False)
            ax.spines["right"].set_visible(False)

    fig.tight_layout(pad=0.1, w_pad=0.1, h_pad=0.1)
    fig.subplots_adjust(wspace=0.32, hspace=0.12)
    out_path = figure_root / "pf_distance_centered_stability_combined.svg"
    fig.savefig(out_path, dpi=300)
    figure_paths["combined"] = str(out_path)
    if show_plot:
        plt.show()
    else:
        plt.close(fig)

    stats_df = pd.DataFrame(stats_rows)
    per_cell_csv = figure_root / "pf_distance_centered_stability_per_cell.csv"
    stats_csv = figure_root / "pf_distance_centered_stability_stats.csv"
    if bool(save_csv):
        df_out = df.copy()
        if "delta_peak_x_cm" in set(df_out.columns):
            df_out["peak_shift_cm"] = np.abs(np.asarray(df_out["delta_peak_x_cm"], dtype=float))
        df_out.to_csv(per_cell_csv, index=False)
        stats_df.to_csv(stats_csv, index=False)

    return {
        "figure_paths": figure_paths,
        "per_cell_csv": str(per_cell_csv),
        "stats_csv": str(stats_csv),
    }


def _time_centered_dataset_as_distance_alias(time_centered_dataset: dict[str, Any]) -> dict[str, Any]:
    """Return a copy that exposes `time_rel` blocks through distance-centered keys."""
    dataset = copy.deepcopy(time_centered_dataset)
    metadata = dataset.setdefault("metadata", {})
    time_window = metadata.get("time_window_sec", metadata.get("distance_window_cm", 4.0))
    time_bin = metadata.get("time_bin_sec", metadata.get("distance_bin_cm", np.nan))

    if not np.isfinite(float(time_bin)) or float(time_bin) <= 0:
        for cat_name in _ordered_dataset_categories(dataset):
            for pf_rank in (1, 2):
                rel = np.asarray(dataset.get(cat_name, {}).get(pf_rank, {}).get("time_rel", []), dtype=float)
                if rel.size > 1:
                    diffs = np.diff(rel)
                    diffs = diffs[np.isfinite(diffs) & (diffs > 0)]
                    if diffs.size > 0:
                        time_bin = float(np.nanmedian(diffs))
                        break
            if np.isfinite(float(time_bin)) and float(time_bin) > 0:
                break
    if not np.isfinite(float(time_bin)) or float(time_bin) <= 0:
        time_bin = 1.0

    metadata["axis_kind"] = "time"
    metadata["distance_window_cm"] = float(time_window)
    metadata["distance_bin_cm"] = float(time_bin)
    metadata["time_window_sec"] = float(time_window)
    metadata["time_bin_sec"] = float(time_bin)

    def _alias_axis(obj: Any) -> None:
        if isinstance(obj, dict):
            if "time_rel" in obj:
                rel = np.asarray(obj["time_rel"], dtype=float)
                obj["distance_rel"] = rel
            elif "distance_rel" in obj and "time_rel" not in obj:
                obj["time_rel"] = np.asarray(obj["distance_rel"], dtype=float)
            for value in list(obj.values()):
                _alias_axis(value)
        elif isinstance(obj, list):
            for value in obj:
                _alias_axis(value)

    _alias_axis(dataset)
    return dataset


def _time_centered_xlim(dataset: dict[str, Any], xlim: tuple[float, float] | None) -> tuple[float, float] | None:
    if xlim is not None:
        return xlim
    meta = dataset.get("metadata", {}) if isinstance(dataset, dict) else {}
    window = float(meta.get("time_window_sec", 4.0))
    if np.isfinite(window) and window > 0:
        return (-window, window)
    return (-4.0, 4.0)


def _add_time_axis_stat_aliases(results: dict[str, Any]) -> dict[str, Any]:
    if not isinstance(results, dict):
        return results
    results = dict(results)
    df = results.get("per_cell_stability", None)
    if df is not None and hasattr(df, "copy"):
        df_out = df.copy()
        if "delta_peak_x_cm" in set(df_out.columns) and "delta_peak_x_sec" not in set(df_out.columns):
            df_out["delta_peak_x_sec"] = df_out["delta_peak_x_cm"]
        results["per_cell_stability"] = df_out
        if "per_cell_selectivity" in results:
            results["per_cell_selectivity"] = df_out
    results["axis_kind"] = "time"
    return results


def generate_pf_time_centered_component_heatmaps(
    dataset: dict[str, Any],
    *,
    figure_save_folder: str | Path,
    xlim: tuple[float, float] | None = None,
    align_all_peak_to_zero: bool = False,
    peak_align_window: tuple[float, float] = (-1.0, 1.0),
    max_peak_adjust_sec: float | None = None,
    max_peak_adjust_sec_pf1: float | None = None,
    max_peak_adjust_sec_pf2: float | None = None,
    x_label: str = "Time from closest PF frame (s)",
    output_prefix: str = "pf_time_centered",
    **kwargs: Any,
) -> dict[str, Any]:
    alias_dataset = _time_centered_dataset_as_distance_alias(dataset)
    return generate_pf_distance_centered_component_heatmaps(
        alias_dataset,
        figure_save_folder=figure_save_folder,
        xlim=_time_centered_xlim(dataset, xlim),
        align_all_peak_to_zero=align_all_peak_to_zero,
        peak_align_window=peak_align_window,
        max_peak_adjust_cm=max_peak_adjust_sec,
        max_peak_adjust_cm_pf1=max_peak_adjust_sec_pf1,
        max_peak_adjust_cm_pf2=max_peak_adjust_sec_pf2,
        x_label=x_label,
        output_prefix=output_prefix,
        **kwargs,
    )


